}

function runTests(): void {
  // --- Basic operations (both implementations) ---
  for (const make of [() => new ChainingHashMap<string, number>(), () => new OpenAddressingHashMap<string, number>()]) {
    const m = make();
    assert(m.size === 0, "initial size 0");
    m.set("a", 1).set("b", 2).set("c", 3);
    assert(m.size === 3, "size after 3 sets");
    assert(m.get("a") === 1 && m.get("b") === 2 && m.get("c") === 3, "get");
    assert(m.has("b"), "has");
    assert(!m.has("zzz"), "!has");
    m.set("a", 10);
    assert(m.get("a") === 10 && m.size === 3, "update keeps size");
    assert(m.delete("b") === true, "delete true");
    assert(m.delete("b") === false, "delete false");
    assert(m.size === 2, "size after delete");
    assert(m.get("b") === undefined, "deleted gone");
    // iteration
    const items = [...m.entries()].sort();
    assert(JSON.stringify(items) === JSON.stringify([["a", 10], ["c", 3]]), "iteration");
  }

  // --- Collision stress: many keys mapping into few buckets ---
  {
    const m = new ChainingHashMap<number, number>({ initialCapacity: 4, maxLoadFactor: 0.99 });
    for (let i = 0; i < 1000; i++) m.set(i, i * 2);
    assert(m.size === 1000, "chaining size");
    for (let i = 0; i < 1000; i++) assert(m.get(i) === i * 2, "chaining get " + i);
  }
  {
    const m = new OpenAddressingHashMap<number, number>({ initialCapacity: 4, maxLoadFactor: 0.7 });
    for (let i = 0; i < 1000; i++) m.set(i, i * 2);
    assert(m.size === 1000, "open size");
    for (let i = 0; i < 1000; i++) assert(m.get(i) === i * 2, "open get " + i);
  }

  // --- Object keys by identity ---
  {
    const m = new ChainingHashMap<object, string>();
    const o1 = { x: 1 };
    const o2 = { x: 1 };
    m.set(o1, "first");
    assert(m.get(o1) === "first", "object key found");
    assert(m.get(o2) === undefined, "distinct object not found");
  }

  // --- Custom hasher/equals (case-insensitive strings) ---
  {
    const m = new OpenAddressingHashMap<string, number>({
      hasher: (s) => defaultHash(s.toLowerCase()),
      equals: (a, b) => a.toLowerCase() === b.toLowerCase(),
    });
    m.set("Hello", 42);
    assert(m.get("HELLO") === 42, "custom equals");
    assert(m.size === 1, "custom size");
  }

  // --- Deletion then re-insert (open addressing tombstone path) ---
  {
    const m = new OpenAddressingHashMap<number, number>();
    for (let i = 0; i < 50; i++) m.set(i, i);
    for (let i = 0; i < 25; i++) assert(m.delete(i), "del " + i);
    for (let i = 0; i < 25; i++) m.set(i, i + 1000);
    for (let i = 0; i < 50; i++) {
      const expected = i < 25 ? i + 1000 : i;
      assert(m.get(i) === expected, "reinsert " + i);
    }
    assert(m.size === 50, "reinsert size");
  }

  // --- Iterable protocol ---
  {
    const m = new ChainingHashMap<string, number>();
    m.set("x", 7).set("y", 8);
    const sum = [...m.values()].reduce((a, b) => a + b, 0);
    assert(sum === 15, "values iterable");
  }

  console.log("All tests passed.");
