    Object.freeze(value);

    for (const key of Object.keys(value)) {
      deepFreeze((value as Record<string, unknown>)[key]);
    }
  }
  return value as DeepReadonly<T>;
}

function createDocument(input: {
  id: string;
  title: string;
  tags?: readonly string[];
  sections?: readonly Section[];
}): Document {
  const now = Date.now();

  return deepFreeze({
    id: input.id,
    title: input.title,
    tags: [...(input.tags ?? [])],
    sections: [...(input.sections ?? [])],
    metadata: {
      createdAt: now,
      updatedAt: now,
    },
  });
}

function addTag(document: Document, tag: string): Document {
  const normalized = tag.trim();
  if (!normalized) throw new Error("Tag cannot be empty");
  if (document.tags.includes(normalized)) return document;

  return deepFreeze({
    ...document,
    tags: [...document.tags, normalized],
    metadata: {
      ...document.metadata,
      updatedAt: Date.now(),
    },
  });
}

function removeSection(document: Document, sectionId: string): Document {
  const sections = document.sections.filter(
    (section) => section.id !== sectionId
  );

  if (sections.length === document.sections.length) {
    return document;
  }

  return deepFreeze({
    ...document,
    sections,
    metadata: {
      ...document.metadata,
      updatedAt: Date.now(),
    },
  });
}

function updateSectionBody(
  document: Document,
  sectionId: string,
  body: string
): Document {
  let changed = false;

  const sections = document.sections.map((section) => {
    if (section.id !== sectionId) return section;
    changed = true;
    return { ...section, body };
  });

