const next = addTag(doc, "typescript");
console.log(doc.tags);   // []
console.log(next.tags); // ["typescript"]
```

### Key takeaways

- Use `readonly` and `ReadonlyArray` for compile-time protection.
- Use spread copies for updates.
- Return the original when nothing changes to preserve referential equality.
- Use `Object.freeze` recursively only if runtime protection is needed; for large apps, prefer structural-sharing libraries such as Immer or Immutable.js.

### Immutable Data Structures in TypeScript — Interview Answer

**What they are.** An *immutable* data structure can never be changed after creation. Instead of mutating in place, every update returns a **new** version. A *persistent* structure does this efficiently by **structural sharing**: the new version reuses unchanged parts of the old one via references, so updates cost `O(log n)` or `O(key length)` time/space instead of `O(n)`.

**Why use them.** Predictable state, trivial rollback (“undo”), cheap snapshotting, safe sharing across async/concurrent code, pure functions, and easy memoization/diffing.

**TypeScript’s role — two layers.**
1. **Compile-time:** `readonly`, `ReadonlyArray`, `ReadonlyMap`, and mapped types like `Immutable<T>` make accidental mutation a type error.
2. **Runtime:** TS types vanish at runtime, so true immutability requires either disciplined copying or a persistent structure that *never mutates* (what we implement below). `Object.freeze` is shallow; deep freeze is a band-aid.

**Naive vs. persistent.** The naive approach (`{ ...obj, a: 1 }`) copies the top level but still shares nested refs—and for collections it’s `O(n)`. A persistent structure uses a **trie** (or tree): updates copy only the path from root to the changed node (`O(log₃₂ n)` for a HAMT, `O(L)` for a string-keyed trie), sharing all siblings.

**Real-world libs:** Immer (draft/proxy → structural sharing), Immutable.js (HAMT), fp-ts/Effect. For most apps, Immer + TS `readonly` is the pragmatic core; the trie below shows *how* that sharing works.

---

### Core Implementation: Persistent Map (path-copying trie)

Keys are strings; updates never mutate—every node on the path is cloned, siblings are shared by reference.

```ts
// persistent-map.ts

/**
 * A trie node. Never mutated after creation: updates clone along the path.
 */
interface Node<V> {
  hasValue: boolean;
  value: V | undefined;
  children: { [key: string]: Node<V> } | null;
}

function cloneNode<V>(node: Node<V>): Node<V> {
  return {
    hasValue: node.hasValue,
    value: node.value,
    children: node.children ? { ...node.children } : null,
  };
}

function getNode<V>(node: Node<V> | null, key: string, i: number): V | undefined {
  if (!node) return undefined;
  if (i === key.length) return node.hasValue ? node.value : undefined;
  const child = node.children?.[key[i]];
  return getNode(child ?? null, key, i + 1);
}

function setNode<V>(node: Node<V> | null, key: string, value: V, i: number): Node<V> {
  // Clone (or create) the current node; original stays untouched.
  const cur: Node<V> = node
    ? { hasValue: node.hasValue, value: node.value, children: node.children ? { ...node.children } : null }
    : { hasValue: false, value: undefined, children: null };

  if (i === key.length) {
    cur.hasValue = true;
    cur.value = value;
    return cur;
  }

  const c = key[i];
  cur.children ??= {};
  // Recurse and store the (possibly new) child; siblings are shared by ref.
  cur.children[c] = setNode(cur.children[c] ?? null, key, value, i + 1);
  return cur;
}

function deleteNode<V>(node: Node<V> | null, key: string, i: number): Node<V> | null {
  if (!node) return null;

  if (i === key.length) {
    if (!node.hasValue) return node; // nothing to remove
    const cur = cloneNode(node);
    cur.hasValue = false;
    cur.value = undefined;
    if (!cur.children || Object.keys(cur.children).length === 0) return null;
    return cur;
  }

  const c = key[i];
  const child = node.children?.[c];
  if (!child) return node; // path absent → no change, share original

  const newChild = deleteNode(child, key, i + 1);
  if (newChild === child) return node; // no change → share original

  if (newChild === null) {
    const cur = cloneNode(node);
    if (cur.children) {
      delete cur.children[c];
      if (Object.keys(cur.children).length === 0) cur.children = null;
    }
    if (!cur.hasValue && (!cur.children || Object.keys(cur.children).length === 0)) return null;
    return cur;
  }

  const cur = cloneNode(node);
  cur.children ??= {};
  cur.children[c] = newChild;
  return cur;
}

/** Public, immutable-ish API wrapper. */
export class PersistentMap<V> {
  constructor(private readonly root: Node<V> | null = null) {}

  get(key: string): V | undefined {
    return getNode(this.root, key, 0);
  }

  set(key: string, value: V): PersistentMap<V> {
    return new PersistentMap(setNode(this.root, key, value, 0));
  }

  delete(key: string): PersistentMap<V> {
    return new PersistentMap(deleteNode(this.root, key, 0));
  }

  has(key: string): boolean {
    return getNode(this.root, key, 0) !== undefined || this._hasKey(key);
  }

  // Note: trie can't distinguish "missing" from "stored undefined" without hasValue;
  // _hasKey checks terminal presence explicitly.
  private _hasKey(key: string): boolean {
    const walk = (n: Node<V> | null, i: number): boolean => {
      if (!n) return false;
      if (i === key.length) return n.hasValue;
      return walk(n.children?.[key[i]] ?? null, i + 1);
    };
    return walk(this.root, 0);
  }
}

// Compile-time deep immutability helper (type only).
export type Immutable<T> =
  T extends Function ? T :
  T extends Array<infer U> ? ReadonlyArray<Immutable<U>> :
  T extends object ? { readonly [K in keyof T]: Immutable<T[K]> } :
  T;

// Example:
// const m1 = new PersistentMap<number>();
// const m2 = m1.set("a", 1).set("ab", 2);
// m1.get("a") === undefined; m2.get("a") === 1;  // old version intact
```

**Complexity.** `get`/`set`/`delete` are `O(L)` time and `O(L)` new nodes per update (`L = key length`), with all untouched siblings shared by reference. This is the structural-sharing “path copy” at the heart of persistent maps.

**Interview talking points to close.**
- *Why not just freeze?* `Object.freeze` is shallow and mutates nothing at runtime semantics; persistence gives *versions* for free.
- *When persistence hurts:* high write churn on large keys, GC pressure, and ergonomics (access requires `.get`). Hence Immer for app state, persistent tries for caches/versioned editors.

# Edge cases when using immutable data structures in TypeScript

Below are the most common (and subtle) edge cases, with explanations and code. I group them by theme.

---

## 1. `readonly` / `Readonly<T>` are **shallow**

The type system only protects the top level. Nested objects remain mutable.

```ts
type User = { name: string; tags: string[] };

const u: Readonly<User> = { name: "ada", tags: ["ts"] };

// u.name = "bob";   // ❌ compile error
u.tags.push("js");     // ✅ allowed — nested array is still mutable
```

**Fix:** use a recursive `DeepReadonly`.

```ts
type DeepReadonly<T> =
  T extends (...args: any[]) => any ? T :          // leave functions alone
  T extends (infer U)[] ? readonly DeepReadonly<U>[] :
  T extends readonly (infer U)[] ? readonly DeepReadonly<U>[] :
  T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } :
  T;

type DeepUser = DeepReadonly<User>;
const du: DeepUser = { name: "ada", tags: ["ts"] };
// du.tags.push("js"); // ❌ compile error
```

> Note: a naive recursive mapped type will turn `Date`, `Map`, `Set`, `RegExp` into weird readonly objects. Treat them as leaves (as above, or add explicit branches).

---

## 2. `as const` is **type-only** — no runtime protection

```ts
const cfg = { retries: 3 } as const;
// cfg.retries = 5; // ❌ compile error

// But at runtime nothing is frozen:
(cfg as any).retries = 5; // ✅ succeeds silently
```

**Fix:** combine with `Object.freeze` (and freeze recursively).

```ts
const cfg = Object.freeze({ retries: 3 } as const);
// (cfg as any).retries = 5; // ❌ runtime TypeError in strict mode
```

---

## 3. `Object.freeze` is also **shallow** (runtime + types)

```ts
const o = Object.freeze({ nested: { x: 1 } });

// TS type is Readonly<{ nested: { x: number } }>  (shallow)
o.nested.x = 2; // ✅ TS allows it, and runtime allows it too
```

**Fix:** recursive freeze.

```ts
function deepFreeze<T>(obj: T): Readonly<T> {
  if (obj && typeof obj === "object") {
    Object.freeze(obj);
    for (const key of Object.keys(obj as object)) {
      deepFreeze((obj as any)[key]);
    }
  }
  return obj as Readonly<T>;
}

const o2 = deepFreeze({ nested: { x: 1 } });
// o2.nested.x = 2; // ❌ compile error (with DeepReadonly) and runtime throws
```

Handle circular references with a `WeakSet` in production.

---

## 4. Runtime mutation can bypass `readonly` via casts

```ts
const arr: readonly number[] = [1, 2, 3];
(arr as number[]).push(4); // compiles, mutates the original array
console.log(arr); // [1, 2, 3, 4]
```

`readonly` is a compile-time contract. If you need runtime guarantees, you must actually freeze or use a library (Immer, Immutable.js) that returns genuinely new data.

---

## 5. Passing `readonly` arrays to APIs expecting mutable arrays

```ts
function sortInPlace(a: number[]) { a.sort(); }

const r: readonly number[] = [3, 1, 2];
sortInPlace(r); // ❌ readonly number[] not assignable to number[]
```

This is usually *good* — it prevents accidental mutation. But third-party libs often demand mutable arrays.

**Fixes:**

```ts
// Copy (gives up readonly, but safe)
sortInPlace([...r]);

// Or change API to accept readonly and copy internally
function sortCopy(a: readonly number[]): number[] {
  return [...a].sort((x, y) => x - y);
}

// ES2023 non-mutating alternatives
const sorted = r.toSorted((a, b) => a - b); // readonly number[] -> number[]
const reversed = r.toReversed();
const removed = r.toSpliced(1, 1);
```

---

## 6. Spreading **loses** `readonly`

```ts
const r: readonly number[] = [1, 2, 3];

const c1 = [...r];            // type: number[]  (mutable!)
const c2 = r.slice();         // type: number[]  (mutable!)
```

If the copy must stay immutable, annotate it.

```ts
const c3: readonly number[] = [...r];
const c4 = [...r] as const;   // readonly [1,2,3] (literal tuple)
```

Same applies to objects:

```ts
const o: Readonly<{ a: number }> = { a: 1 };
const copy = { ...o }; // { a: number } — mutable again
```

---

## 7. `const` declarations are not immutable values

```ts
const arr = [1, 2, 3]; // type number[], elements mutable
arr.push(4);           // ✅ allowed

const arr2 = [1, 2, 3] as const; // readonly [1, 2, 3]
// arr2.push(4); // ❌
```

`const` only prevents reassigning the binding, not mutating the value.

---

## 8. `readonly` class fields protect the **reference**, not contents

```ts
class Box {
  readonly value = { count: 0 };
}

const b = new Box();
// b.value = { count: 1 }; // ❌
b.value.count = 1;         // ✅ allowed — field is readonly, object is not
```

---

## 9. React / state: mutation breaks change detection

Even with immutable *types*, mutating nested state silently breaks re-renders.

```ts
const [state, setState] = useState({ nested: { count: 0 } });

// ❌ mutates in place; React may skip re-render
state.nested.count++;
setState(state);

// ✅ new references at every changed level
setState(prev => ({
  ...prev,
  nested: { ...prev.nested, count: prev.nested.count + 1 },
}));
```

With Immer, drafts look mutable but produce immutable updates:

```ts
import produce from "immer";

const next = produce(state, draft => {
  draft.nested.count += 1; // mutate the draft
});
// `next` is a new immutable value; `state` untouched
```

Immer edge case: if you **return** a value from the recipe, it *replaces* the draft — don't mix.

```ts
const next = produce(state, draft => {
  draft.count += 1;
  return { replaced: true }; // ⚠️ discards all draft changes
});
```

---

## 10. `Map` / `Set` cannot be truly frozen by `Object.freeze`

```ts
const m: ReadonlyMap<string, number> = new Map([["a", 1]]);
// m.set("b", 2); // ❌ type error

// But the underlying Map is mutable at runtime:
(m as Map<string, number>).set("b", 2); // ✅ mutates
```

`Object.freeze` on a `Map` does not block `.set` (internal slots). For real immutability, use `Immutable.js`/`immer` or wrap in a proxy that throws.

---

## 11. Deep equality vs. reference equality

Immutable updates always produce new references, even when nothing changed.

```ts
const a = { x: 1 };
const b = { ...a }; // new ref even though equal
a === b; // false

// Memoization based on === will miss "equal but new" values.
// Use deep equality (or Immer's structural sharing) where needed.
```

Conversely, accidental mutation of a "immutable" value corrupts every reference sharing it — a common source of bugs.

---

## 12. Covariance differs: `readonly` arrays are covariant

```ts
class Animal {}
class Dog extends Animal {}

const dogs: readonly Dog[] = [new Dog()];
const animals: readonly Animal[] = dogs; // ✅ covariant

const mutDogs: Dog[] = [new Dog()];
// const mutAnimals: Animal[] = mutDogs; // ❌ invariant (would allow pushing Cat)
```

This is great for reading, but means a `readonly Dog[]` can be treated as `readonly Animal[]` — fine for reads, never for writes (there are none).

---

## 13. Generic constraints and `readonly`

```ts
// Accept both mutable and readonly arrays
function first<T extends readonly unknown[]>(arr: T): T[0] {
  return arr[0];
}

first([1, 2, 3]);           // T = number[]
first([1, 2, 3] as const);  // T = readonly [1,2,3], returns 1
```

If you write `T extends unknown[]`, readonly tuples/arrays are rejected. Use `readonly unknown[]`.

---

## 14. `noUncheckedIndexedAccess` + readonly arrays

```ts
// tsconfig: "noUncheckedIndexedAccess": true
const r: readonly number[] = [1, 2];
const x = r[0]; // number | undefined
```

Indexing a readonly array has the same `undefined` possibility as a mutable one. Guard accordingly.

---

## 15. Tuple rest and readonly

```ts
type Row = readonly [id: number, ...values: string[]];

const r: Row = [1, "a", "b"];
// r[0] = 2;            // ❌
// r.push("c");         // ❌ (readonly array)
```

Spreading a readonly tuple into a function expecting a mutable rest param fails; copy first.

---

## 16. Stripping / adding `readonly` via mapped types

```ts
type Mutable<T> = { -readonly [K in keyof T]: T[K] };
type Frozen<T> = { readonly [K in keyof T]: T[K] };

type A = { readonly x: number };
type B = Mutable<A>; // { x: number }
```

Useful when interfacing with mutable third-party APIs or when you need a writable draft type.

---

## 17. `Object.freeze` return type and arrays

```ts
const arr = Object.freeze([1, 2, 3]);
// type: readonly [1, 2, 3]? Actually Object.freeze on number[] -> readonly number[]
arr.push(4); // ❌
```

But `Object.freeze` on a tuple literal may widen unless you `as const` first:

```ts
const t = Object.freeze([1, "a"] as const);
// type: readonly [1, "a"]
```

---

## 18. JSON / `structuredClone` produce **mutable** data

```ts
const r: readonly { x: number }[] = [{ x: 1 }];
const clone = structuredClone(r); // mutable { x: number }[]
clone[0].x = 9; // ✅ allowed
```

If you need immutability after deserialization, re-apply `DeepReadonly` or freeze.

---

## 19. `Date`, `RegExp`, and other mutable built-ins

`DeepReadonly` that blindly maps over object keys will make `Date`'s methods read-only-ish but the object is still mutable at runtime (`setTime`, etc.). Treat built-ins as leaves:

```ts
type DeepReadonly<T> =
  T extends Date | RegExp | Function ? T :
  T extends (infer U)[] ? readonly DeepReadonly<U>[] :
  T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } :
  T;
```

For true immutability of dates, store epoch millis (`number`) or use a library value type.

---

## 20. Immer and TypeScript: draft types

```ts
import { produce } from "immer";

type State = { count: number; nested: { x: number } };

const next = produce<State, State>((draft) => {
  draft.count += 1;
  draft.nested.x = 2;
});
```

Edge cases:

- Forgetting the generic can widen `draft` to `any` in some configs.
- Mutating *and* returning replaces the whole value.
- Immer freezes output in dev by default (configurable) — relying on that for runtime safety is dev-only unless you enable `freeze` in prod.

---

## 21. `Readonly<T>` with optional / nullable fields

```ts
type T = { a?: number; b: number | null };
type R = Readonly<T>;
// { readonly a?: number; readonly b: number | null }
```

`readonly` does not make fields required or non-null. Combine deliberately:

```ts
type Strict = Readonly<Required<NonNullableFields<T>>>; // define as needed
```

---

## 22. Index signatures

```ts
type Dict = { readonly [k: string]: number };
const d: Dict = { a: 1 };
// d.b = 2; // ❌
// But deletion/mutation via cast still possible at runtime.
```

Readonly index signatures prevent assignment via index, but `delete` and casts bypass.

---

## Summary checklist

| Concern | Compile-time fix | Runtime fix |
|---|---|---|
| Nested mutation | `DeepReadonly<T>` | `deepFreeze` |
| `as const` not frozen | — | `Object.freeze` |
| `Object.freeze` shallow | `DeepReadonly` | recursive freeze |
| Cast bypass | strict lint (`no-explicit-any`) | proxies / libs |
| Mutable APIs | accept `readonly ...[]` | copy with `[...x]` |
| Spread loses readonly | annotate result | — |
| React state | immutable types | immutable updates / Immer |
| Map/Set | `ReadonlyMap` | wrapper / immutable lib |
| Built-ins (Date) | treat as leaves | store primitives |
| Generic readonly arrays | `T extends readonly unknown[]` | — |

The core principle: **TypeScript's `readonly` is a static contract.** For true immutability you need both the types (to catch mistakes at compile time) *and* runtime enforcement (freeze, Immer, or persistent data structures) where untrusted code or casts are possible.

Here is a complete, runnable TypeScript example that demonstrates the main inheritance features: `extends`, `super`, method overriding, polymorphism, `abstract` classes, access modifiers, and `instanceof`.

Save it as `inheritance.ts`.

```ts
// inheritance.ts

// Abstract base class: cannot be instantiated directly.
abstract class Employee {
  protected id: number;
  protected name: string;
  private monthlySalary: number;

  constructor(id: number, name: string, monthlySalary: number) {
    this.id = id;
    this.name = name;
    this.monthlySalary = monthlySalary;
  }

  // Common behavior shared by all employees.
  public getId(): number {
    return this.id;
  }

  public getName(): string {
    return this.name;
  }

  public getAnnualSalary(): number {
    return this.monthlySalary * 12;
  }

  // Template method: subclasses customize part of the description.
  public describe(): string {
    return `${this.name} (id=${this.id})`;
  }

  // Abstract method: every subclass must implement this.
  public abstract getRole(): string;

  // Protected helper: subclasses can use it, outside code cannot.
  protected adjustSalary(amount: number): void {
    this.monthlySalary += amount;
  }

  // Subclasses can call this to change their own salary.
  public promote(amount: number): void {
    this.adjustSalary(amount);
  }
}

// First derived class.
class Developer extends Employee {
  private languages: string[];

  constructor(
    id: number,
    name: string,
    monthlySalary: number,
    languages: string[]
  ) {
    super(id, name, monthlySalary); // must call super() before using this
    this.languages = languages;
  }

  public getRole(): string {
    return "Developer";
  }

  public describe(): string {
    return `${super.describe()} - knows ${this.languages.join(", ")}`;
  }

  public addLanguage(language: string): void {
    this.languages.push(language);
  }
}

// Second derived class.
class Manager extends Employee {
  private reports: Employee[] = [];

  constructor(
    id: number,
    name: string,
    monthlySalary: number,
    reports: Employee[] = []
  ) {
    super(id, name, monthlySalary);
    this.reports = reports;
  }

  public getRole(): string {
    return "Manager";
  }

  public describe(): string {
    return `${super.describe()} - manages ${this.reports.length} report(s)`;
  }

  public addReport(employee: Employee): void {
    this.reports.push(employee);
  }

  public getTeamSize(): number {
    return this.reports.length;
  }
}

// Deeper inheritance: TechLead extends Developer.
class TechLead extends Developer {
  constructor(
    id: number,
    name: string,
    monthlySalary: number,
    languages: string[],
    public teamName: string
  ) {
    super(id, name, monthlySalary, languages);
  }

  public getRole(): string {
    return "Tech Lead";
  }

  public describe(): string {
    return `${super.describe()} - leads team ${this.teamName}`;
  }
}

// Usage / demonstration
const dev1 = new Developer(1, "Alice", 8000, ["TypeScript", "Rust"]);
const dev2 = new Developer(2, "Bob", 7500, ["Go"]);
const techLead = new TechLead(3, "Carol", 10000, ["TypeScript", "Kotlin"], "Platform");
const manager = new Manager(4, "David", 12000, [dev1, dev2]);

// Polymorphism: all are Employee instances.
const staff: Employee[] = [dev1, dev2, techLead, manager];

for (const person of staff) {
  console.log(
    person.describe(),
    "| role:",
    person.getRole(),
    "| annual salary:",
    person.getAnnualSalary()
  );

  // Type narrowing with instanceof.
  if (person instanceof Manager) {
    console.log("   team size:", person.getTeamSize());
  }

  if (person instanceof Developer) {
    console.log("   is a developer or tech lead");
  }
}

// Promote one employee.
dev1.promote(500);
console.log("\nAfter promotion:");
console.log(dev1.getName(), "annual salary:", dev1.getAnnualSalary());

// Cannot instantiate an abstract class:
// const invalid = new Employee(5, "X", 1000); // Error: Cannot create an instance of an abstract class.
```

## How to run it

Using `ts-node`:

```bash
npm install -D typescript ts-node
npx ts-node inheritance.ts
```

Or compile first:

```bash
npx tsc inheritance.ts --target es2020 --module commonjs
node inheritance.js
```

## Key concepts shown

- `abstract class Employee` defines shared state and behavior, but cannot be created directly.
- `class Developer extends Employee` and `class Manager extends Employee` inherit from `Employee`.
- `super(...)` calls the parent constructor and must be used before accessing `this`.
- `super.describe()` calls the parent implementation while overriding a method.
- `getRole()` is abstract in the base class, so every subclass must provide its own role.
- `protected` members such as `adjustSalary` are available to subclasses but not to outside code.
- `private` members such as `monthlySalary` are only accessible inside the class where they are declared.
- `Employee[]` arrays and loops demonstrate polymorphism: different subclasses are treated uniformly as `Employee`.
- `instanceof` narrows the type so subclass-specific methods become available.

## Inheritance in TypeScript

### The idea

Inheritance lets a **derived class** acquire and specialize the fields and methods of a **base class**. TypeScript uses JavaScript’s prototype-based inheritance but exposes it through class syntax with static type checking.

Key points:

- **Single inheritance**: a class extends at most one base class.
- **`super`**: calls the base constructor or base methods.
- **Polymorphism**: a derived instance is assignable to its base type.
- **Compile-time vs runtime**: TS types/visibility are erased; `private`/`protected` are enforced only at compile time (use `#field` for true runtime privacy).
- **Prefer composition** for code reuse in many cases; inheritance is best for true “is-a” hierarchies.

---

### Basic syntax

```ts
class Animal {
  constructor(public name: string) {}

  speak(): string {
    return `${this.name} makes a sound`;
  }
}

class Dog extends Animal {
  constructor(name: string, public breed: string) {
    super(name); // must call base constructor first
  }

  // override
  speak(): string {
    return `${this.name} barks`;
  }

  fetch(item: string): string {
    return `${this.name} fetches ${item}`;
  }
}

const d = new Dog("Rex", "Labrador");
console.log(d.speak());   // Rex barks
console.log(d instanceof Animal); // true
```

---

### Access modifiers

```ts
class Base {
  public id = 1;          // anywhere
  protected secret = "x";  // this class + subclasses
  private internal = 0;    // this class only (compile-time)
  #trulyPrivate = 42;     // runtime private (ES2022)
}

class Child extends Base {
  show() {
    console.log(this.id, this.secret); // ok
    // console.log(this.internal);     // error
    // console.log(this.#trulyPrivate); // error (and not inherited)
  }
}
```

---

### Abstract classes (partial implementation)

```ts
abstract class Shape {
  abstract area(): number; // must implement in subclass

  describe(): string {
    return `Area = ${this.area()}`;
  }
}

class Circle extends Shape {
  constructor(private r: number) { super(); }
  area(): number { return Math.PI * this.r ** 2; }
}
```

---

### Method overriding & `super`

```ts
class Logger {
  log(msg: string) { console.log("[LOG]", msg); }
}

class TimestampLogger extends Logger {
  log(msg: string) {
    super.log(`${new Date().toISOString()} ${msg}`);
  }
}
```

---

### Static members & inheritance

```ts
class Config {
  static defaults = { theme: "light" };
}

class UserConfig extends Config {
  static defaults = { ...Config.defaults, theme: "dark" };
}
```

---

### Getters/setters

```ts
class Person {
  private _age = 0;
  get age() { return this._age; }
  set age(v: number) {
    if (v < 0) throw new Error("negative age");
    this._age = v;
  }
}

class Employee extends Person {
  // can override accessor if needed
}
```

---

### Interfaces + inheritance

A class can implement interfaces while extending a base:

```ts
interface Serializable { toJSON(): string; }

class Entity { id = 0; }

class User extends Entity implements Serializable {
  toJSON() { return JSON.stringify({ id: this.id }); }
}
```

---

### Typical use cases

1. **Domain hierarchies**: `Account → SavingsAccount, CheckingAccount`.
2. **Framework subclasses**: extending `React.Component`, `Error`, `HTMLElement`.
3. **Custom errors**:
   ```ts
   class HttpError extends Error {
     constructor(public status: number, message: string) {
       super(message);
       this.name = "HttpError";
     }
   }
   ```
4. **Template method pattern**: base defines algorithm skeleton, subclasses fill steps.
5. **Polymorphic collections**: `Shape[]` holding `Circle`, `Rect`.

---

### Gotchas & best practices

- **Call `super()` before using `this`** in a derived constructor.
- **TS structural typing**: inheritance is nominal-ish at runtime via prototype chain, but assignability is structural; prefer explicit `extends` for clarity.
- **Don’t overuse deep hierarchies**; flatten with composition/mixins when sharing behavior across unrelated types.
- **Mixins** (for multiple inheritance needs):
  ```ts
  type Constructor<T = {}> = new (...args: any[]) => T;
  function Timestamped<TBase extends Constructor>(Base: TBase) {
    return class extends Base {
      createdAt = new Date();
    };
  }
  class User extends Timestamped(Object) {}
  ```
- **`instanceof` works** across inheritance; but cross-realm/iframe issues can occur.

---

### Composition alternative (often better)

```ts
class Engine { start() {} }
class Car {
  constructor(private engine = new Engine()) {}
  drive() { this.engine.start(); }
}
```

Use inheritance for “is-a”; composition for “has-a”.

## Typical inheritance mistake (TypeScript)

### ❌ Buggy version

```ts
class Person {
  constructor(public name: string) {}

  greet(): string {
    return `Hi, I'm ${this.name}`;
  }
}

class Employee extends Person {
  // Mistake 1: using `this` before calling `super()`
  constructor(name: string, public role: string) {
    this.role = role;   // ❌ 'super' must be called before accessing 'this'
    super(name);
  }

  // Mistake 2: overriding without preserving base behavior
  // Mistake 3: typo-prone override (no `override` keyword)
  greet(): string {
    return `Employee role: ${this.role}`; // loses Person's greeting entirely
  }
}
```

### ✅ Corrected version

```ts
class Person {
  constructor(public name: string) {}

  greet(): string {
    return `Hi, I'm ${this.name}`;
  }
}

class Employee extends Person {
  constructor(name: string, public role: string) {
    super(name); // call base constructor first
  }

  override greet(): string {
    // extend, don't silently replace, base behavior
    return `${super.greet()} (role: ${this.role})`;
  }
}

// Usage
const e = new Employee("Ada", "Engineer");
console.log(e.greet()); // Hi, I'm Ada (role: Engineer)
```

## What was wrong and why

1. **`this` before `super()`**  
   In a derived class, the instance (`this`) does not exist until the base constructor runs. TypeScript (and JavaScript at runtime) requires `super(...)` to be the first statement that touches `this`. Accessing `this.role` first throws a compile-time error (`'super' must be called before accessing 'this' in derived class constructor`) and would be a runtime `ReferenceError` if bypassed.

2. **Overriding that discards base behavior**  
   `Employee.greet()` completely replaced `Person.greet()`. That violates the Liskov Substitution Principle in spirit: code expecting a `Person` may rely on the `"Hi, I'm ..."` prefix. The fix uses `super.greet()` to compose the new behavior on top of the inherited one.

3. **Missing `override` keyword**  
   Without `override`, a typo like `greeter()` instead of `greet()` silently creates a new method instead of overriding, leading to confusing bugs. Adding `override` makes TypeScript verify that a matching base member exists.

### Extra best practices

- Prefer **composition over inheritance** when behavior varies a lot; inheritance is for true "is-a" relationships.
- Keep overrides **covariant/compatible**: don't narrow parameter types or change return types in ways that break callers.
- Mark intentionally overridable base methods and avoid mutating shared prototype state (e.g., arrays/objects defined on the prototype). Define mutable fields as instance properties instead.
- If a base class should not be instantiated directly, make it `abstract` and its methods `abstract`.

Below are common TypeScript/JavaScript inheritance pitfalls, with short examples and safer patterns.

## 1. Losing `this` when extracting a method

Methods are not bound to instances by default.

```ts
class User {
  name = "Ada";

  greet() {
    return `Hello, ${this.name}`;
  }
}

const u = new User();
const fn = u.greet;
fn(); // Runtime: Cannot read properties of undefined (strict mode)
```

**Safer options**

```ts
class User {
  name = "Ada";

  // Arrow field: bound, but costs memory per instance
  greet = () => `Hello, ${this.name}`;
}

// Or bind explicitly
const fn = u.greet.bind(u);
```

---

## 2. Calling `super()` too late in a constructor

In a derived constructor, `this` cannot be used before `super()`.

```ts
class Base {
  constructor(public x: number) {}
}

class Derived extends Base {
  y: number;

  constructor(x: number, y: number) {
    this.y = y;     // Error: 'super' must be called before accessing 'this'
    super(x);
  }
}
```

**Fix**

```ts
class Derived extends Base {
  y: number;

  constructor(x: number, y: number) {
    super(x);
    this.y = y;
  }
}
```

---

## 3. TypeScript is structural, not nominal

A subclass may not give the type-level safety you expect, and unrelated objects can satisfy a class type.

```ts
class Point {
  x = 0;
  y = 0;
}

class LabeledPoint extends Point {
  label = "origin";
}

function move(p: Point) {
  p.x += 1;
}

move({ x: 10, y: 20 }); // OK structurally, even though not a Point instance

const lp = new LabeledPoint();
const p: Point = lp;     // OK: subtype
// const bad: LabeledPoint = new Point(); // Error: missing label
```

**Pitfall:** relying on `instanceof` or class identity when only structural compatibility is checked.

---

## 4. Method override mistakes without `override`

TypeScript allows accidental overloads/typos unless you use `override`.

```ts
class Base {
  save(data: string): void {}
}

class Derived extends Base {
  // Typo: silently becomes a new method, not an override
  savve(data: string): void {}

  // Also dangerous: parameter widened without intent
  save(data: any): void {}
}
```

**Safer**

```ts
class Derived extends Base {
  override save(data: string): void {
    super.save(data);
  }
}
```

Enable `noImplicitOverride` so overrides must be marked.

---

## 5. Parameter type changes and `strictFunctionTypes`

Methods are checked bivariantly by default in many configurations, which can hide unsound overrides.

```ts
class Handler {
  handle(x: string): void {}
}

class LooseHandler extends Handler {
  // Often allowed, but unsafe: base callers may pass only strings
  handle(x: any): void {}
}
```

**Safer pattern:** keep override signatures compatible, or use function-typed properties when you want stricter contravariance.

```ts
class StrictHandler {
  handle: (x: string) => void = (x) => {};
}
```

---

## 6. Private and protected members are compile-time only

`private`/`protected` disappear at runtime. `#private` fields are truly private.

```ts
class Base {
  private token = "secret";
  #realSecret = "hidden";
}

class Derived extends Base {
  token = "not actually private at runtime"; // shadows, does not access base private
  // #realSecret = "x"; // Error: cannot redeclare private field? Actually separate class-private field allowed,
  // but it is a different field, not the base one.
}

const d = new Derived() as any;
console.log(d.token); // "not actually private at runtime"
```

**Pitfall:** assuming `private` protects runtime data or that subclasses cannot shadow/reach it.

---

## 7. Forgetting `abstract` implementations

Abstract members must be implemented by concrete subclasses.

```ts
abstract class Shape {
  abstract area(): number;

  describe() {
    return `area=${this.area()}`;
  }
}

class Circle extends Shape {
  constructor(public radius: number) {
    super();
  }
  // Error: Non-abstract class 'Circle' does not implement inherited abstract member 'area'
}
```

**Fix**

```ts
class Circle extends Shape {
  constructor(public radius: number) {
    super();
  }
  area() {
    return Math.PI * this.radius ** 2;
  }
}
```

---

## 8. Single inheritance and the mixin workaround

TypeScript classes extend only one class. Multiple inheritance requires mixins, which introduce generic/typing complexity.

```ts
type Constructor<T = object> = new (...args: any[]) => T;

function Timestamped<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    timestamp = Date.now();
  };
}

function Tagged<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    tag = "item";
  };
}

class Item {}
class TimestampedTaggedItem extends Timestamped(Tagged(Item)) {}
```

**Pitfalls**
- Deep mixin chains hurt readability.
- Static members and constructor argument types can be lost.
- `instanceof` checks become less intuitive.

---

## 9. Static members and polymorphic `this`

Static inheritance exists, but `this` typing in static methods can surprise you.

```ts
class Base {
  static create() {
    return new this(); // `this` is the constructor
  }
}

class Derived extends Base {
  value = 42;
}

const d = Derived.create();
// Type is Derived, but if Base.create were not generic/polymorphic enough,
// callers could get Base instead.
```

**Safer typed factory**

```ts
class Base {
  static create<T extends Base>(this: new () => T): T {
    return new this();
  }
}
```

---

## 10. `super` is not available in arrow class fields

Class fields are initialized during construction; `super` cannot be used in an arrow field initializer the way it can in a method.

```ts
class Base {
  log() {
    console.log("base");
  }
}

class Derived extends Base {
  // Error: 'super' is only allowed in members of object literals or classes,
  // or in nested functions inside such members.
  log = () => super.log();
}
```

**Fix:** use a normal method, or call `super.log()` from a method.

---

## 11. Overriding instance properties can be unsafe

You can narrow a property type in a subclass, which is convenient but can break base-class assumptions.

```ts
class Zoo {
  animals: Animal[] = [];
}

class DogZoo extends Zoo {
  animals: Dog[] = []; // Covariant override; often allowed, but unsafe in general
}

function addAnimal(zoo: Zoo, a: Animal) {
  zoo.animals.push(a); // Could push a Cat into a DogZoo at runtime
}
```

**Safer:** prefer composition or readonly collections when mutability matters.

---

## 12. `readonly` is not runtime protection

`readonly` only blocks assignment in TypeScript. It does not freeze the object.

```ts
class Config {
  readonly apiKey = "secret";
}

const c = new Config();
(c as any).apiKey = "leaked"; // Runtime mutation possible
```

**Safer:** use `Object.freeze`, private state, or `#private` fields.

---

## 13. Runtime identity and transpilation issues

Inheritance usually works across targets, but runtime identity can break in bundled/multi-copy environments.

```ts
// Two copies of the same module/class in a bundle
class A {}
const x = new A();
x instanceof A; // may be false if `A` comes from a different module instance
```

**Pitfall:** relying on `instanceof` across package boundaries. Prefer brand checks, symbols, or explicit type tags when needed.

---

## 14. Using inheritance for code reuse

Deep hierarchies become fragile (fragile base class problem). Composition is often clearer.

```ts
// Inheritance-heavy
class Animal {}
class Mammal extends Animal {}
class Dog extends Mammal {}
class GuardDog extends Dog {}

// Composition
class GuardDog {
  constructor(
    private dog: Dog,
    private alarm: AlarmSystem,
  ) {}

  bark() {
    this.dog.bark();
    this.alarm.trigger();
  }
}
```

---

## 15. Constructor parameter properties and ordering

Parameter properties are convenient but can make subclass constructors confusing.

```ts
class Base {
  constructor(public x: number, protected y: number) {}
}

class Derived extends Base {
  constructor(
    x: number,
    y: number,
    public z: number, // z assigned after super()
  ) {
    super(x, y);
    // this.z already initialized by parameter property
  }
}
```

**Pitfall:** forgetting that parameter properties still require `super()` first and that visibility modifiers affect subclass access.

---

## Recommended compiler settings

```json
{
  "compilerOptions": {
    "strict": true,
    "noImplicitOverride": true,
    "strictPropertyInitialization": true,
    "useDefineForClassFields": true
  }
}
```

These settings catch many override, initialization, and `this`-related mistakes early.

## Exercise

Build a tiny geometry library using TypeScript inheritance:

1. Create an abstract base class `Shape` with:
   - a `color: string` property
   - an abstract `area(): number`
   - an abstract `perimeter(): number`
   - a concrete inherited method `describe(): string`

2. Create two subclasses:
   - `Circle extends Shape`
   - `Rectangle extends Shape`

3. Store several mixed shapes in one `Shape[]` array and compute the total area.

---

## Step-by-step solution

### Step 1: Define the abstract base class

The base class holds shared state and behavior. It is `abstract`, so it cannot be instantiated directly. It defines the contract that every shape must implement.

```ts
abstract class Shape {
  constructor(public color: string) {}

  abstract area(): number;
  abstract perimeter(): number;

  describe(): string {
    return `${this.constructor.name} (${this.color}) -> area=${this.area().toFixed(2)}, perimeter=${this.perimeter().toFixed(2)}`;
  }
}
```

Why this works:

- `public color` is a TypeScript parameter property. It declares and assigns the property in one line.
- `abstract area()` and `abstract perimeter()` force subclasses to provide implementations.
- `describe()` is inherited. It calls `this.area()` and `this.perimeter()`, which dispatch polymorphically to the subclass implementation.

### Step 2: Implement `Circle`

`Circle` calls `super(color)` to initialize the base class, then adds `radius`.

```ts
class Circle extends Shape {
  constructor(color: string, private radius: number) {
    super(color);

    if (radius <= 0) {
      throw new Error("Radius must be positive");
    }
  }

  area(): number {
    return Math.PI * this.radius ** 2;
  }

  perimeter(): number {
    return 2 * Math.PI * this.radius;
  }
}
```

### Step 3: Implement `Rectangle`

`Rectangle` does the same, but with width and height.

```ts
class Rectangle extends Shape {
  constructor(color: string, private width: number, private height: number) {
    super(color);

    if (width <= 0 || height <= 0) {
      throw new Error("Width and height must be positive");
    }
  }

  area(): number {
    return this.width * this.height;
  }

  perimeter(): number {
    return 2 * (this.width + this.height);
  }
}
```

### Step 4: Use polymorphism with mixed shapes

Because both subclasses inherit from `Shape`, they can be stored in the same array and treated uniformly.

```ts
const shapes: Shape[] = [
  new Circle("red", 5),
  new Rectangle("blue", 4, 6),
  new Circle("green", 2.5),
];

for (const shape of shapes) {
  console.log(shape.describe());
}

const totalArea = shapes.reduce((sum, shape) => sum + shape.area(), 0);
console.log(`Total area: ${totalArea.toFixed(2)}`);
```

---

## Final solution

```ts
abstract class Shape {
  constructor(public color: string) {}

  abstract area(): number;
  abstract perimeter(): number;

  describe(): string {
    return `${this.constructor.name} (${this.color}) -> area=${this.area().toFixed(2)}, perimeter=${this.perimeter().toFixed(2)}`;
  }
}

class Circle extends Shape {
  constructor(color: string, private radius: number) {
    super(color);

    if (radius <= 0) {
      throw new Error("Radius must be positive");
    }
  }

  area(): number {
    return Math.PI * this.radius ** 2;
  }

  perimeter(): number {
    return 2 * Math.PI * this.radius;
  }
}

class Rectangle extends Shape {
  constructor(color: string, private width: number, private height: number) {
    super(color);

    if (width <= 0 || height <= 0) {
      throw new Error("Width and height must be positive");
    }
  }

  area(): number {
    return this.width * this.height;
  }

  perimeter(): number {
    return 2 * (this.width + this.height);
  }
}

const shapes: Shape[] = [
  new Circle("red", 5),
  new Rectangle("blue", 4, 6),
  new Circle("green", 2.5),
];

for (const shape of shapes) {
  console.log(shape.describe());
}

const totalArea = shapes.reduce((sum, shape) => sum + shape.area(), 0);
console.log(`Total area: ${totalArea.toFixed(2)}`);
```

### Key inheritance concepts demonstrated

- `extends` establishes an "is-a" relationship.
- `super()` initializes inherited state.
- Abstract methods enforce a shared contract.
- A concrete inherited method can call abstract methods polymorphically.
- Mixed subclass instances can be handled through their common base type.

## Inheritance in TypeScript — Interview Answer

### Concept

Inheritance in TypeScript is **single implementation inheritance** via `extends`, built on JavaScript’s prototype chain.

Core ideas:

- **`extends`** links a derived class’s prototype to the base class’s prototype.
- **`super(...)`** calls the base constructor; **`super.method()`** calls an overridden base method.
- **Method overriding** + **polymorphism**: a base-typed reference can hold a derived instance and dispatch to the derived method.
- **Access modifiers**: `public` (default), `private` (compile-time only, erased at runtime), `protected` (accessible in subclasses).
- **`abstract`** classes/methods cannot be instantiated and force subclasses to implement behavior.
- **`implements`** is *not* inheritance of implementation — it’s a compile-time contract (interface).
- **Multiple inheritance of implementation is not supported**; use **mixins** or composition instead.

---

### Clean Implementation: Core Features

```ts
// base.ts
export abstract class Animal {
  // protected: shared state for subclasses, hidden from external callers
  protected name: string;
  protected energy: number = 100;

  constructor(name: string) {
    this.name = name;
  }

  // abstract: every concrete animal MUST implement this
  abstract speak(): string;

  // concrete: inherited as-is, can be overridden
  move(distanceMeters = 0): string {
    this.energy = Math.max(0, this.energy - distanceMeters);
    return `${this.name} moved ${distanceMeters}m (energy=${this.energy})`;
  }

  // getter: part of the public contract
  get label(): string {
    return `Animal(${this.name})`;
  }
}

// dog.ts
export class Dog extends Animal {
  // private: Dog-only state (compile-time enforced)
  private readonly breed: string;

  constructor(name: string, breed: string) {
    super(name); // MUST call base constructor first
    this.breed = breed;
  }

  // override: TS 4.3+ keyword documents intent; enable noImplicitOverride for safety
  override speak(): string {
    return `${this.name} barks!`;
  }

  // overriding + reusing base behavior via super
  override move(distanceMeters = 5): string {
    const base = super.move(distanceMeters);
    return `${base} and wagged its tail`;
  }

  override get label(): string {
    return `Dog(${this.name}, ${this.breed})`;
  }

  // subclass-specific API
  fetch(item: string): string {
    return `${this.name} fetched the ${item}`;
  }
}

// cat.ts
export class Cat extends Animal {
  constructor(name: string) {
    super(name);
  }

  override speak(): string {
    return `${this.name} meows.`;
  }
  // inherits move() unchanged
}

// polymorphism.ts
export function makeNoise(animal: Animal): string {
  // runtime dispatch to the actual subclass method
  return animal.speak();
}

export function describe(animal: Animal): string {
  return `${animal.label}: ${animal.move(2)}`;
}
```

### Usage / Demo

```ts
import { Dog, Cat, makeNoise, describe } from "./animals";

const rex = new Dog("Rex", "Shepherd");
const whiskers = new Cat("Whiskers");

console.log(makeNoise(rex));       // "Rex barks!"
console.log(makeNoise(whiskers)); // "Whiskers meows."

console.log(describe(rex));
// "Dog(Rex, Shepherd): Rex moved 2m (energy=98) and wagged its tail"

console.log(rex instanceof Animal); // true  (prototype chain)
console.log(rex instanceof Dog);    // true

// rex.fetch("ball") works; whiskers.fetch(...) is a compile error
```

### Under the Hood (Core Mechanism)

TypeScript classes compile to constructor functions + prototype linking. The *essence* of inheritance is just two operations:

```ts
// 1) Link child prototype to parent prototype (inherit methods)
Object.setPrototypeOf(Child.prototype, Parent.prototype);

// 2) Chain constructors when instantiating
function Child(...args) {
  Parent.call(this, ...args); // super(...)
  // child-specific init...
}
```

A minimal manual version (for understanding) looks like:

```ts
function Animal(this: any, name: string) {
  this.name = name;
}
Animal.prototype.speak = function () { return `${this.name} makes a sound`; };

function Dog(this: any, name: string, breed: string) {
  Animal.call(this, name); // super(name)
  this.breed = breed;
}
// core inheritance link
Object.setPrototypeOf(Dog.prototype, Animal.prototype);

Dog.prototype.speak = function () {
  return `${this.name} barks`; // override
};

const d = new (Dog as any)("Rex", "Shepherd");
console.log(d.speak());          // "Rex barks"
console.log(d instanceof Animal); // true
```

### Interview Talking Points (Quick)

- **Why single inheritance?** Avoids diamond problem; use mixins/composition for reuse.
- **`private` vs `#private`**: TS `private` is compile-time only; JS `#field` is truly runtime-private.
- **`override` keyword**: opt-in safety; pair with `noImplicitOverride: true`.
- **Abstract vs interface**: abstract = partial implementation + contract; interface = pure contract (can be implemented by many unrelated types).
- **Prefer composition over inheritance** when behavior varies independently (Strategy pattern).

When using inheritance in TypeScript, the tricky parts usually come from three sources: JavaScript runtime semantics, TypeScript’s structural type system, and compiler options such as `strict`, `noImplicitOverride`, `useDefineForClassFields`, and `strictPropertyInitialization`.

Below are the most important edge cases, with idiomatic TypeScript examples.

---

## 1. `super()` must be called before `this`

In a derived constructor, you cannot access `this` before calling `super()`.

```ts
class Base {
  x = 1;
}

class Derived extends Base {
  y = 2;

  constructor() {
    // this.x = 5; // Error: 'super' must be called first
    super();
    this.y = 10; // OK after super()
  }
}
```

Also, instance field initializers run in class order: base fields first, then derived fields.

---

## 2. Calling overridden methods from a base constructor

If the base constructor calls a method that is overridden in the derived class, the derived override runs before derived fields are initialized.

```ts
class Base {
  x = 1;

  constructor() {
    this.init(); // virtual call
  }

  init() {
    console.log("base init", this.x);
  }
}

class Derived extends Base {
  y = 2;

  constructor() {
    super();
  }

  override init() {
    // y is still undefined here because Derived field init hasn't run yet
    console.log("derived init", this.x, this.y);
  }
}

new Derived();
```

**Rule:** avoid calling overridable methods from constructors, or make them `final`-like by not overriding them.

---

## 3. Field initialization order and `useDefineForClassFields`

With modern TypeScript/ES class fields, derived class fields are defined after `super()` returns. This can overwrite inherited accessor behavior.

```ts
class Base {
  get value() {
    return 42;
  }
}

class Derived extends Base {
  // With useDefineForClassFields, this becomes an own data property
  value = 100;
}

const d = new Derived();
console.log(d.value); // 100
console.log(Object.prototype.hasOwnProperty.call(d, "value")); // true
```

If you intend to keep inherited getter/setter semantics, do not redeclare the field in the subclass.

---

## 4. Overriding getters/setters separately

If you override only a getter, you may lose the inherited setter at runtime.

```ts
class Base {
  protected _x = 0;

  get x() {
    return this._x;
  }

  set x(v: number) {
    this._x = v;
  }
}

class Derived extends Base {
  override get x() {
    return super.x + 1;
  }

  // No setter here: Derived.prototype.x has only a getter.
}

const d = new Derived();
d.x = 5; // Runtime error in strict mode: no setter
```

**Fix:** override both getter and setter, or avoid partial accessor overrides.

---

## 5. `private`, `protected`, and ECMAScript `#private`

TypeScript `private` is compile-time only. `#private` is truly runtime-private and inherited subclasses cannot access either.

```ts
class Base {
  private tsPrivate = "ts";
  #esPrivate = "es";
  protected shared = 1;

  getTsPrivate() {
    return this.tsPrivate;
  }
}

class Derived extends Base {
  constructor() {
    super();
    console.log(this.shared); // OK

    // console.log(this.tsPrivate);   // TS error
    // console.log(this.#esPrivate);  // TS + runtime error
  }
}
```

Also, `private` members are not inherited in the structural sense; a subclass instance does not expose them publicly, but they still exist on the instance.

---

## 6. Method override safety and `noImplicitOverride`

Enable `noImplicitOverride` so overrides are explicit.

```ts
class Animal {
  speak() {
    return "sound";
  }
}

class Dog extends Animal {
  // Error with noImplicitOverride: this method overrides 'speak'
  speak() {
    return "woof";
  }

  // Correct
  override speak() {
    return "woof";
  }
}
```

Parameter narrowing in overrides is unsafe and rejected:

```ts
class Parent {
  feed(animal: Animal): void {}
}

class Child extends Parent {
  // Error: parameter type not assignable / unsafe narrowing
  override feed(dog: Dog): void {}
}
```

Return-type covariance is allowed:

```ts
class Factory {
  create(): Animal {
    return new Animal();
  }
}

class DogFactory extends Factory {
  override create(): Dog {
    return new Dog();
  }
}
```

---

## 7. `this` binding when passing methods as callbacks

Class methods are not bound to the instance by default.

```ts
class Counter {
  count = 0;

  increment() {
    this.count++; // 'this' may be undefined
  }
}

const c = new Counter();
setTimeout(c.increment, 100); // runtime error in strict mode

// Fixes:
setTimeout(c.increment.bind(c), 100);
// or use arrow field:
class SafeCounter {
  count = 0;
  increment = () => {
    this.count++;
  };
}
```

Trade-off: arrow fields are not on the prototype and are slightly less memory-efficient.

---

## 8. Polymorphic `this` for fluent APIs

Use `this` as the return type so subclass chaining is preserved.

```ts
class Builder {
  value = "";

  setValue(v: string): this {
    this.value = v;
    return this;
  }
}

class ExtendedBuilder extends Builder {
  extra = 0;

  setExtra(n: number): this {
    this.extra = n;
    return this;
  }
}

const b = new ExtendedBuilder().setValue("x").setExtra(3);
```

If `setValue` returned `Builder`, `setExtra` would not be available.

---

## 9. Static members are inherited, but mutations can split

Static methods are inherited, but `this` refers to the class on which the method is called.

```ts
class Base {
  static count = 0;

  static increment() {
    this.count++;
  }
}

class Derived extends Base {}

Derived.increment();
console.log(Derived.count); // 1
console.log(Base.count);    // 0
```

`Derived.increment()` creates an own `count` property on `Derived` instead of mutating `Base.count`.

---

## 10. Abstract classes and abstract members

Abstract classes cannot be instantiated directly, and subclasses must implement all abstract members.

```ts
abstract class Shape {
  abstract area(): number;

  describe() {
    return `area = ${this.area()}`;
  }
}

class Circle extends Shape {
  constructor(private radius: number) {
    super();
  }

  override area() {
    return Math.PI * this.radius * this.radius;
  }
}

const c = new Circle(2);
// const s = new Shape(); // Error: cannot instantiate abstract class
```

Abstract properties are also supported:

```ts
abstract class Entity {
  abstract id: string;
}
```

---

## 11. Protected constructors for controlled instantiation

Use a protected constructor to force factory usage while still allowing subclassing.

```ts
class Base {
  protected constructor(public id: string) {}

  static create(id: string) {
    return new Base(id);
  }
}

class Derived extends Base {
  constructor(id: string) {
    super(id);
  }
}

// const b = new Base("1"); // Error
const d = new Derived("2"); // OK
```

---

## 12. Constructor parameter properties and `readonly`

Parameter properties generate fields automatically. Be careful when overriding and redeclaring.

```ts
class Base {
  constructor(public readonly id: number) {}
}

class Derived extends Base {
  constructor(id: number, public name: string) {
    super(id);
    // this.id = 2; // Error: readonly
  }
}
```

Edge case: redeclaring `id` in `Derived` with a different type can break assignability.

---

## 13. Generics and inheritance

Subclasses can specialize generic base classes.

```ts
class Box<T> {
  constructor(public value: T) {}
}

class NumberBox extends Box<number> {
  double() {
    return this.value * 2;
  }
}
```

Be careful with variance. Method parameters are checked for safety; narrowing parameters in overrides is unsafe.

```ts
class Handler<T> {
  handle(x: T): void {}
}

class StringHandler extends Handler<string> {
  override handle(x: string): void {
    console.log(x.toUpperCase());
  }
}
```

---

## 14. Mixins for multiple inheritance

TypeScript supports only single class inheritance. Use mixin factories for multiple behavior composition.

```ts
type Constructor<T = {}> = new (...args: any[]) => T;

function Timestamped<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    timestamp = Date.now();
  };
}

function Tagged<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    tags: string[] = [];
  };
}

class User {
  name = "";
}

class TimestampedTaggedUser extends Timestamped(Tagged(User)) {}

const u = new TimestampedTaggedUser();
u.name = "Ada";
u.tags.push("admin");
console.log(u.timestamp);
```

Edge cases:

- Constructor signatures must be preserved or explicitly typed.
- Mixin order matters, especially if multiple mixins define the same member.
- `instanceof` checks against the final class, not individual mixin factories unless you add branded checks.

---

## 15. `instanceof`, prototype chain, and transpilation

`instanceof` follows the prototype chain. It works across inheritance, but not for interfaces or types.

```ts
interface Animal {} // erased at runtime

class Dog {}

const x: Animal = new Dog();
// x instanceof Animal; // Error: 'Animal' only refers to a type
console.log(x instanceof Dog); // true
```

When targeting older ES versions, TypeScript emits `__extends` helper code. Prototype chain semantics remain, but some advanced features (like true private `#fields`) may require newer targets.

---

## 16. Method overloading in subclasses

Overload signatures are not automatically inherited in a useful way unless the base method is compatible. Child classes should maintain compatible signatures.

```ts
class Parent {
  process(x: string): string;
  process(x: number): number;
  process(x: string | number): string | number {
    return typeof x === "string" ? x.toUpperCase() : x * 2;
  }
}

class Child extends Parent {
  // Must remain compatible with Parent's call signatures
  override process(x: string | number): string | number {
    return super.process(x);
  }
}
```

Avoid changing parameter arity or types in ways that break callers expecting the parent interface.

---

## 17. Structural typing can make unrelated classes assignable

TypeScript uses structural typing, so a subclass instance is assignable to the base type, but so can any structurally compatible object.

```ts
class Base {
  x = 1;
}

class Derived extends Base {
  y = 2;
}

function takeBase(b: Base) {}

takeBase(new Derived()); // OK

const fake = { x: 1, y: 2 };
takeBase(fake); // Also OK structurally
```

If you need nominal identity, use branding:

```ts
class Base {
  private readonly __brand = "Base";
  x = 1;
}
```

---

## 18. `new.target` and constructor delegation

`new.target` identifies the actually constructed class. This matters in factory-style base classes.

```ts
class Base {
  constructor() {
    console.log("constructed:", new.target?.name);
  }
}

class Derived extends Base {}

new Derived(); // "constructed: Derived"
```

Useful for abstract factories or logging which subclass was instantiated.

---

## 19. Static blocks and initialization order

Static initialization blocks run in declaration order within a class. Inheritance does not run base static blocks when constructing a derived instance.

```ts
class Base {
  static value = 1;
  static {
    Base.value += 10;
  }
}

class Derived extends Base {
  static {
    // Base.value is already 11
    Derived.value = Base.value + 1;
  }
}
```

Do not assume instance construction triggers parent static initialization again.

---

## 20. Decorators and metadata are not automatically inherited

Decorators attach metadata to the decorated class member. Subclasses do not automatically inherit decorator metadata from base members.

```ts
function Log(_target: any, key: string) {
  console.log("decorated:", key);
}

class Base {
  @Log
  method() {}
}

class Derived extends Base {
  // @Log is not inherited; metadata is attached to Base.prototype.method
}
```

If you rely on reflection-based frameworks, explicitly reapply decorators or implement metadata inheritance logic.

---

## Practical recommended compiler settings

For predictable inheritance behavior, enable:

```json
{
  "compilerOptions": {
    "strict": true,
    "noImplicitOverride": true,
    "useDefineForClassFields": true,
    "target": "ES2022"
  }
}
```

These settings make override mistakes, field initialization, and private field semantics much safer.

Below is a complete, dependency-free TypeScript example that validates **unknown** runtime input and returns either a typed value or a list of errors. It also shows the equivalent modern approach with **Zod**.

## 1. Zero-dependency example (runnable with `tsc` + Node)

### `validation.ts`

```ts
// validation.ts
export interface User {
  name: string;
  age: number;
  email?: string;
}

export type Result<T> =
  | { ok: true; value: T }
  | { ok: false; errors: string[] };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function pathError(path: string, message: string): string {
  return `${path}: ${message}`;
}

export function validateUser(input: unknown): Result<User> {
  const errors: string[] = [];

  if (!isRecord(input)) {
    return { ok: false, errors: ["input: expected a plain object"] };
  }

  const output: Partial<User> = {};

  // ---- name ----
  const name = input.name;
  if (typeof name !== "string" || name.trim() === "") {
    errors.push(pathError("name", "must be a non-empty string"));
  } else {
    output.name = name.trim();
  }

  // ---- age ----
  const age = input.age;
  if (
    typeof age !== "number" ||
    !Number.isFinite(age) ||
    !Number.isInteger(age) ||
    age < 0 ||
    age > 150
  ) {
    errors.push(pathError("age", "must be an integer between 0 and 150"));
  } else {
    output.age = age;
  }

  // ---- email (optional) ----
  if (input.email !== undefined) {
    const email = input.email;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (typeof email !== "string" || !emailRegex.test(email)) {
      errors.push(pathError("email", "must be a valid email address"));
    } else {
      output.email = email;
    }
  }

  // ---- optional: reject unknown keys ----
  const allowedKeys = new Set(["name", "age", "email"]);
  for (const key of Object.keys(input)) {
    if (!allowedKeys.has(key)) {
      errors.push(pathError(key, "unknown property"));
    }
  }

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  return { ok: true, value: output as User };
}
```

### `main.ts`

```ts
// main.ts
import { validateUser } from "./validation";

const samples: unknown[] = [
  { name: "  Ada  ", age: 36, email: "ada@example.com" },
  { name: "", age: -5 },
  "not an object",
  { name: "Grace", age: 42, admin: true },
];

for (const sample of samples) {
  const result = validateUser(sample);
  if (result.ok) {
    console.log("VALID:", result.value);
  } else {
    console.log("INVALID:", result.errors);
  }
}
```

### Run it

```bash
npm init -y
npm i -D typescript ts-node @types/node
npx tsc --init --strict --esModuleInterop
npx ts-node main.ts
```

Expected output:

```text
VALID: { name: 'Ada', age: 36, email: 'ada@example.com' }
INVALID: [ 'name: must be a non-empty string', 'age: must be an integer between 0 and 150' ]
INVALID: [ 'input: expected a plain object' ]
INVALID: [ 'admin: unknown property' ]
```

---

## 2. Industry-standard approach with Zod

For larger projects, use a schema library. Zod gives you runtime validation **and** TypeScript types from one source of truth.

### Install

```bash
npm i zod
```

### `userSchema.ts`

```ts
import { z } from "zod";

export const UserSchema = z.object({
  name: z.string().trim().min(1, "name must not be empty"),
  age: z.number().int().min(0).max(150),
  email: z.string().email().optional(),
});

// Type is inferred automatically from the schema
export type User = z.infer<typeof UserSchema>;

export function validateUser(input: unknown) {
  const result = UserSchema.safeParse(input);
  if (result.success) {
    return { ok: true as const, value: result.data };
  }
  return {
    ok: false as const,
    errors: result.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`),
  };
}
```

Usage is identical to the manual version:

```ts
const r = validateUser({ name: "Ada", age: 36 });
if (r.ok) console.log(r.value.name); // typed as string
```

---

## Key ideas to remember

1. **Never trust input at runtime.** TypeScript types disappear after compilation; always validate `unknown` boundaries (HTTP bodies, CLI args, `JSON.parse`, DB rows).
2. **Use `unknown`, not `any`.** `unknown` forces you to narrow before use.
3. **Prefer schema inference.** With Zod/io-ts/Valibot, the runtime schema is the single source of truth, and the TS type is derived from it.
4. **Return structured errors.** A `Result`-style union (`{ok:true,value}` | `{ok:false,errors}`) keeps validation explicit and avoids throwing for expected bad input.
5. **Validate shape, not just types.** Check ranges, formats, allowed keys, and invariants (e.g., `start < end`).

If you want, I can extend this with **nested objects, arrays, async validation, or Express/Fastify middleware integration**.

# Input Validation in TypeScript

TypeScript’s type system exists **only at compile time**. At runtime, values are just JavaScript, so `string`, `number`, etc. are erased. Input validation is the practice of **checking unknown data at runtime** and narrowing it to a trusted TypeScript type before you use it.

## 1. The core idea

- **Boundary validation**: Validate data where it enters your program (HTTP body, CLI args, `localStorage`, env vars, file contents, third-party SDK responses).
- **Parse, don’t validate** (often): Instead of only checking “is this a string?”, transform raw input into a domain type and reject anything that doesn’t fit.
- **Single source of truth**: Ideally, the runtime validator and the TypeScript type come from the same definition (schema-first), so they can’t drift.

## 2. Manual validation with type guards

A **type guard** is a function returning `value is T`. It narrows the type after a truthy check.

```ts
type User = { id: number; email: string };

function isUser(x: unknown): x is User {
  return (
    typeof x === "object" &&
    x !== null &&
    "id" in x &&
    typeof (x as any).id === "number" &&
    "email" in x &&
    typeof (x as any).email === "string"
  );
}

function handle(input: unknown) {
  if (!isUser(input)) throw new Error("Invalid user");
  // input is User here
  console.log(input.email.toUpperCase());
}
```

**Pros**: zero dependencies. **Cons**: verbose, easy to get wrong, types and runtime checks duplicate.

## 3. Assertion functions

Instead of returning a boolean, throw on failure. TS narrows after the call.

```ts
function assertUser(x: unknown): asserts x is User {
  if (!isUser(x)) throw new Error("Invalid user");
}

function handle(input: unknown) {
  assertUser(input);
  // input is User
  console.log(input.id);
}
```

Useful for centralizing “fail fast” logic.

## 4. Schema-first validation (recommended)

Libraries like **Zod**, **io-ts**, **Yup**, or **Valibot** define a schema that produces both a runtime validator and a TypeScript type.

### Zod example

```ts
import { z } from "zod";

const UserSchema = z.object({
  id: z.number().int().positive(),
  email: z.string().email(),
  role: z.enum(["admin", "user"]).default("user"),
});

type User = z.infer<typeof UserSchema>; // { id: number; email: string; role: "admin" | "user" }

function parseUser(raw: unknown): User {
  return UserSchema.parse(raw); // throws ZodError on failure
}

// Safe variant (no throw)
const result = UserSchema.safeParse(raw);
if (!result.success) {
  console.error(result.error.flatten());
} else {
  console.log(result.data.email);
}
```

### Why schema-first wins

- One definition → type + runtime check.
- Composable: `z.string().min(1)`, `z.coerce.number()`, transforms, refinements.
- Great error messages for forms/APIs.

## 5. Typical use cases

| Scenario | What to validate | Suggested approach |
|---|---|---|
| Express/Fastify route body | `req.body` | Zod schema + middleware |
| Environment variables | `process.env` | `z.object({ PORT: z.coerce.number() })` |
| JSON from `fetch` | response body | `schema.parse(await res.json())` |
| Query params | `req.query` | coerce strings to numbers/dates |
| Config files | parsed JSON/YAML | schema + `.safeParse` |
| Form submissions | `FormData`/JSON | schema + field-level errors |
| Webhook payloads | unknown JSON | strict schema, reject unknown keys |

## 6. Parsing vs. validating

- **Validation**: “is this already a `User`?” (boolean).
- **Parsing**: “turn this raw thing into a `User`, or fail.” Parsing is usually more useful because it can coerce (`"42"` → `42`), apply defaults, and strip unknown keys.

```ts
const EnvSchema = z.object({
  PORT: z.coerce.number().default(3000),
  NODE_ENV: z.enum(["dev", "prod"]).default("dev"),
});

const env = EnvSchema.parse(process.env);
// env.PORT is number, env.NODE_ENV is "dev" | "prod"
```

## 7. Common pitfalls

- **Trusting `as`**: `const u = data as User` does **no runtime check**. Avoid at boundaries.
- **`any`/`unknown` confusion**: Accept `unknown` at boundaries, then narrow.
- **Partial validation**: Validating only top-level fields leaves nested holes. Use recursive schemas.
- **Over-validation**: Don’t re-validate internal, already-typed data; validate at edges only.
- **Error leakage**: Don’t send raw validation errors to clients in production; map to safe messages.

## 8. Minimal “boundary” pattern

```ts
// api.ts
import { z } from "zod";

const CreateUserSchema = z.object({
  name: z.string().min(1),
  age: z.number().int().min(0),
});

export type CreateUserInput = z.infer<typeof CreateUserSchema>;

export function createUser(raw: unknown): CreateUserInput {
  return CreateUserSchema.parse(raw); // throws on bad input
}
```

```ts
// route handler
app.post("/users", (req, res) => {
  try {
    const input = createUser(req.body);
    // input is fully typed and trusted
    res.json({ ok: true, id: save(input) });
  } catch (e) {
    res.status(400).json({ error: "Invalid input" });
  }
});
```

## Summary

- TypeScript types vanish at runtime → validate at boundaries.
- Use **type guards/assertions** for small, dependency-free checks.
- Prefer **schema libraries (Zod, etc.)** for real apps: one source of truth, coercion, composition, and good errors.
- Accept `unknown`, parse into a trusted type, and never use `as` to skip validation.

```ts
// ❌ Mistaken version
interface User {
  age: number;
}

const user: User = { age: 0 };

function setAge(input: string): void {
  const age = parseInt(input, 10);

  if (age >= 0 && age <= 120) {
    user.age = age;
  }
}
```

```ts
// ✅ Corrected version
interface User {
  age: number;
}

const user: User = { age: 0 };

function setAge(input: unknown): void {
  if (typeof input !== "string") {
    throw new TypeError("age must be a string");
  }

  const trimmed = input.trim();

  // Reject anything that is not a plain non-negative integer string
  if (!/^\d+$/.test(trimmed)) {
    throw new RangeError("age must be a non-negative integer");
  }

  const age = Number(trimmed);

  if (!Number.isSafeInteger(age) || age < 0 || age > 120) {
    throw new RangeError("age must be between 0 and 120");
  }

  user.age = age;
}
```

### What was wrong?

1. **TypeScript types do not validate runtime input.**  
   `input: string` is erased at runtime. If this function is called from JavaScript, an API, `JSON.parse`, a form, or an untrusted source, `input` may not actually be a string. Using `unknown` forces explicit runtime checking.

2. **`parseInt` is too lenient for validation.**  
   `parseInt("12abc", 10)` returns `12`, and `parseInt("  12  ", 10)` ignores surrounding whitespace. That can accept invalid or misleading input. A strict regular expression rejects mixed or malformed values.

3. **`NaN` and partial parsing were not handled.**  
   `parseInt("")` returns `NaN`, and comparisons like `NaN >= 0` are `false`, so invalid input may silently do nothing. Silent failure is dangerous because callers may assume validation succeeded.

4. **No trimming or strict format check.**  
   User input often contains accidental whitespace. Trimming is reasonable, but after trimming the value should still match a strict expected format.

5. **Range validation should be explicit and strict.**  
   Using `Number.isSafeInteger` prevents accepting values such as `"9007199254740993"` that cannot be represented safely as JavaScript numbers. The bounds `0` and `120` are then checked clearly.

### Why the corrected version is better

- It validates the **runtime type** first.
- It rejects **malformed numeric strings** instead of partially parsing them.
- It handles **whitespace** deliberately.
- It checks **safe integer representation** and **business range**.
- It **throws on invalid input** rather than silently ignoring it, making failures visible to callers and tests.

# Common Pitfalls in TypeScript Input Validation

TypeScript types disappear at runtime, so “valid TypeScript” guarantees nothing about runtime data. The pitfalls below are the ones that bite most often.

---

## 1. Treating `as` as validation

```ts
// BAD: compiles, but crashes at runtime if shape is wrong
const user = JSON.parse(req.body) as User;
console.log(user.profile.age.toFixed(2)); // TypeError if age missing
```

**Fix:** parse at the boundary with a runtime schema, then infer the type.

```ts
import { z } from "zod";

const UserSchema = z.object({
  profile: z.object({ age: z.number().int().nonnegative() }),
});
type User = z.infer<typeof UserSchema>;

const user = UserSchema.parse(JSON.parse(req.body)); // throws on bad data
```

---

## 2. `typeof` checks that lie about `null` and arrays

```ts
function isObject(x: unknown): x is Record<string, unknown> {
  // BAD: null is "object", arrays are "object"
  return typeof x === "object";
}
```

**Fix:**

```ts
function isPlainObject(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}
```

Also note `typeof NaN === "number"`.

---

## 3. `NaN`, `Infinity`, and partial parsing

```ts
const n = Number("12abc");   // NaN
const p = parseInt("12abc"); // 12 (silent truncation)
const plus = +"  ";          // 0
```

**Fix:** use strict parsers and `Number.isFinite`.

```ts
const n = Number(input);
if (!Number.isFinite(n)) throw new Error("not a finite number");
// or in Zod:
z.coerce.number().refine(Number.isFinite);
```

---

## 4. `new Date("garbage")` is still a `Date`

```ts
const d = new Date("not-a-date");
console.log(d instanceof Date); // true
d.toISOString();                 // throws RangeError
```

**Fix:**

```ts
function isValidDate(d: unknown): d is Date {
  return d instanceof Date && !Number.isNaN(d.getTime());
}
// Zod:
z.date().refine((d) => !Number.isNaN(d.getTime()));
// or parse strings:
z.string().datetime().transform((s) => new Date(s));
```

---

## 5. Query params / form data are always strings

```ts
// req.query.limit is "10" (string), not 10
if (req.query.limit > 5) { ... }          // "10" > 5 → true (coerced), but fragile
if (req.query.active === true) { ... }     // never true; it's "true"/"false"/undefined
```

**Fix:** coerce explicitly and validate.

```ts
const Query = z.object({
  limit: z.coerce.number().int().min(1).max(100).default(20),
  active: z
    .enum(["true", "false"])
    .transform((v) => v === "true")
    .optional(),
});
const q = Query.parse(req.query);
```

Watch out: `z.coerce.boolean()` treats `"false"` as truthy (non-empty string). Don’t use it for query booleans.

---

## 6. Duplicate source of truth (interface + schema drift)

```ts
interface User { id: string; age: number }
const UserSchema = z.object({ id: z.string(), age: z.string() }); // drift: age string vs number
```

**Fix:** one schema, derive the type.

```ts
const UserSchema = z.object({ id: z.string().uuid(), age: z.number().int() });
type User = z.infer<typeof UserSchema>;
```

---

## 7. Optional vs `null` vs `undefined`

```ts
interface Profile { bio?: string } // undefined only
// API sends { bio: null } → type says string | undefined, runtime says null
```

**Fix:** model what the wire actually sends.

```ts
const ProfileSchema = z.object({
  bio: z.string().nullable().optional(), // string | null | undefined
});
```

---

## 8. Enums validated the wrong way

```ts
enum Role { Admin = "admin", User = "user" }
// BAD: accepts any string at runtime after cast
const r = input as Role;
```

**Fix:** use a runtime-checked union or `z.enum`.

```ts
const RoleSchema = z.enum(["admin", "user"]);
type Role = z.infer<typeof RoleSchema>; // "admin" | "user"

// If you must keep TS enum:
const RoleValues = Object.values(Role) as string[];
z.string().refine((v): v is Role => RoleValues.includes(v));
```

---

## 9. Mass assignment / unknown keys

```ts
// BAD: spreads untrusted input into DB update
await db.user.update({ data: { ...req.body } });
```

**Fix:** pick explicit fields; reject or strip unknowns deliberately.

```ts
const UpdateSchema = z.object({
  name: z.string().optional(),
  email: z.string().email().optional(),
}).strict(); // .strict() rejects unknown keys; .strip() (default) silently drops them
```

Choose `.strict()` for security-sensitive updates; `.passthrough()` only when you truly need extras.

---

## 10. Prototype pollution when merging

```ts
function merge(target: any, src: any) {
  for (const k in src) target[k] = src[k]; // __proto__ pollution
}
merge({}, JSON.parse('{"__proto__":{"isAdmin":true}}'));
```

**Fix:** never merge untrusted objects generically; validate first, or use `Object.create(null)` / `Map`, and block dangerous keys.

```ts
const DANGEROUS = new Set(["__proto__", "constructor", "prototype"]);
function safeAssign(target: Record<string, unknown>, src: unknown) {
  const obj = isPlainObject(src) ? src : {};
  for (const [k, v] of Object.entries(obj)) {
    if (DANGEROUS.has(k)) continue;
    target[k] = v;
  }
}
```

---

## 11. Regex ReDoS and overly strict email/URL rules

```ts
// Catastrophic backtracking on "aaaaaaaaaaaaaaaaab"
const re = /^(a+)+$/;
re.test("a".repeat(30) + "b");
```

**Fix:** avoid nested quantifiers; prefer battle-tested validators.

```ts
import { isEmail } from "validator"; // or Zod's built-ins
z.string().email();   // uses a safe, reasonable regex
z.string().url();     // validates URL syntax (still check scheme/allowlist separately)
```

For URLs, also enforce protocol allowlist (`https:`) to prevent `javascript:` injection.

---

## 12. Async validation not awaited

```ts
const schema = z.object({
  email: z.string().email().refine(async (e) => !(await db.users.exists(e)), "taken"),
});
const result = schema.parse(data); // refine is async → returns promise; parse is sync
```

**Fix:** use async methods.

```ts
const data = await schema.parseAsync(data);
// or safeParseAsync
```

---

## 13. Coercion surprises

```ts
z.coerce.number().parse("");   // 0
z.coerce.boolean().parse("false"); // true
z.coerce.date().parse(0);      // epoch date, not error
```

**Fix:** be explicit; prefer non-coercing schemas at API boundaries and coerce in a controlled transform.

```ts
z.string()
  .min(1)
  .transform((s) => Number(s))
  .refine(Number.isFinite);
```

---

## 14. Not validating nested arrays / indices

```ts
const Body = z.object({ items: z.array(z.string()) });
// items: ["", "x", ...] passes; empty strings, huge arrays pass
```

**Fix:** constrain size and element rules.

```ts
z.object({
  items: z.array(z.string().min(1).max(100)).min(1).max(50),
});
```

Also cap total payload size before parsing (express `limit`, or check `Content-Length`).

---

## 15. Discarded validation errors / poor reporting

```ts
try { Schema.parse(x); } catch { res.status(400).send("bad"); } // no field info
```

**Fix:** use `safeParse` and map errors without leaking internals.

```ts
const r = Schema.safeParse(x);
if (!r.success) {
  const issues = r.error.issues.map((i) => ({
    path: i.path.join("."),
    message: i.message, // sanitize in production if needed
  }));
  return res.status(422).json({ errors: issues });
}
```

Don’t echo raw input or stack traces to clients.

---

## 16. Trusting file metadata from the client

```ts
if (file.mimetype === "image/png") { ... } // client-controlled
```

**Fix:** inspect magic bytes server-side.

```ts
import { fileTypeFromBuffer } from "file-type";
const type = await fileTypeFromBuffer(buffer);
if (type?.mime !== "image/png") throw new Error("not png");
```

Also enforce size limits and store outside webroot / with random names.

---

## 17. Integer vs float

```ts
z.number().parse(1.5) // passes even if you wanted an int
```

**Fix:**

```ts
z.number().int().safe(); // or Number.isSafeInteger
```

---

## 18. Whitespace-only “required” strings

```ts
z.string().min(1).parse("   "); // passes
```

**Fix:**

```ts
z.string().trim().min(1);
```

Be careful: trimming changes the value; decide whether to store trimmed.

---

## 19. Validating only at one layer

```ts
// Controller validates, service assumes valid; later a new caller skips controller
```

**Fix:** validate at system boundaries (HTTP handler, queue consumer, CLI entry, DB read of untrusted JSON column). Internal functions can trust typed inputs but document the contract. For defense in depth, re-validate when crossing trust boundaries (e.g., deserializing from cache/DB).

---

## 20. Forgetting that `JSON.parse` accepts more than you think

```ts
JSON.parse("123");        // number, not object
JSON.parse("null");       // null
JSON.parse('"x"');        // string
```

**Fix:** validate the parsed value’s shape, not just that parsing succeeded.

```ts
const parsed = JSON.parse(raw);
const data = Schema.parse(parsed); // schema enforces object shape
```

---

### Quick checklist

- Types are compile-time only; always validate at runtime at boundaries.
- Derive TS types from schemas, not the other way around.
- Handle `null`, `undefined`, `NaN`, arrays, and strings explicitly.
- Constrain size, length, and depth to avoid DoS.
- Avoid ReDoS; prefer library validators.
- Reject/strip unknown keys deliberately.
- Never trust client MIME types, booleans-as-strings, or `as` casts.
- Use `safeParse`/`parseAsync` correctly and return sanitized errors.

If you’re starting fresh, Zod (or Valibot/ArkType) + `z.infer` covers most of these; the pitfalls mostly come from mixing manual checks with schema-based validation.

## Exercise

Write a TypeScript function `validateRegistration(input: unknown)` that accepts arbitrary input and returns either:

- `{ ok: true; data: Registration }` with a strongly typed, validated object, or
- `{ ok: false; errors: string[] }` with all validation errors found.

Rules:
- `email` must be a string matching a basic email pattern.
- `age` must be an integer between 13 and 120.
- `password` must be a string with at least 8 characters, one uppercase letter, one lowercase letter, and one digit.

Do not assume the input has the right shape; validate at runtime.

---

## Step-by-step solution

### 1. Define the domain types

First, separate the *trusted* shape from the *validation result*.

```ts
type Registration = {
  email: string;
  age: number;
  password: string;
};

type ValidationResult =
  | { ok: true; data: Registration }
  | { ok: false; errors: string[] };
```

The result is a discriminated union, so callers can narrow with `if (result.ok)`.

### 2. Create small reusable guards

Instead of one giant function, define focused helpers. This keeps each rule testable and readable.

```ts
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}
```

These are type predicates (`value is T`), so TypeScript narrows types after a successful check.

### 3. Validate each field independently

Collect errors instead of failing on the first one. This gives users actionable feedback.

```ts
function validateEmail(value: unknown): string[] {
  const errors: string[] = [];

  if (!isString(value)) {
    errors.push("email must be a string");
    return errors;
  }

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(value)) {
    errors.push("email must be a valid email address");
  }

  return errors;
}

function validateAge(value: unknown): string[] {
  const errors: string[] = [];

  if (!isNumber(value)) {
    errors.push("age must be a number");
    return errors;
  }

  if (!Number.isInteger(value)) {
    errors.push("age must be an integer");
  }

  if (value < 13 || value > 120) {
    errors.push("age must be between 13 and 120");
  }

  return errors;
}

function validatePassword(value: unknown): string[] {
  const errors: string[] = [];

  if (!isString(value)) {
    errors.push("password must be a string");
    return errors;
  }

  if (value.length < 8) {
    errors.push("password must be at least 8 characters long");
  }
  if (!/[A-Z]/.test(value)) {
    errors.push("password must contain an uppercase letter");
  }
  if (!/[a-z]/.test(value)) {
    errors.push("password must contain a lowercase letter");
  }
  if (!/[0-9]/.test(value)) {
    errors.push("password must contain a digit");
  }

  return errors;
}
```

### 4. Compose the validators

Now combine them. If the top-level value is not an object, return immediately. Otherwise, validate each field and merge errors.

```ts
function validateRegistration(input: unknown): ValidationResult {
  if (!isObject(input)) {
    return { ok: false, errors: ["input must be an object"] };
  }

  const errors: string[] = [
    ...validateEmail(input.email),
    ...validateAge(input.age),
    ...validatePassword(input.password),
  ];

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  // At this point, all checks passed, so narrowing is safe.
  return {
    ok: true,
    data: {
      email: input.email as string,
      age: input.age as number,
      password: input.password as string,
    },
  };
}
```

Because the validators already confirmed the runtime types, the casts in the success branch are safe. In production, you could avoid casts by returning parsed values from each validator, but this keeps the example concise.

### 5. Add stricter typing with a schema-like helper (optional improvement)

A common next step is to make validators return parsed values rather than just errors. This removes casts entirely:

```ts
type FieldResult<T> =
  | { ok: true; value: T }
  | { ok: false; errors: string[] };

function parseEmail(value: unknown): FieldResult<string> {
  const errors = validateEmail(value);
  return errors.length
    ? { ok: false, errors }
    : { ok: true, value: value as string };
}
```

For most small projects, the array-of-errors approach above is enough. For larger ones, libraries such as `zod` or `valibot` provide the same idea with less boilerplate and better error messages.

---

## Final solution

```ts
type Registration = {
  email: string;
  age: number;
  password: string;
};

type ValidationResult =
  | { ok: true; data: Registration }
  | { ok: false; errors: string[] };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function validateEmail(value: unknown): string[] {
  const errors: string[] = [];

  if (!isString(value)) {
    errors.push("email must be a string");
    return errors;
  }

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(value)) {
    errors.push("email must be a valid email address");
  }

  return errors;
}

function validateAge(value: unknown): string[] {
  const errors: string[] = [];

  if (!isNumber(value)) {
    errors.push("age must be a number");
    return errors;
  }

  if (!Number.isInteger(value)) {
    errors.push("age must be an integer");
  }

  if (value < 13 || value > 120) {
    errors.push("age must be between 13 and 120");
  }

  return errors;
}

function validatePassword(value: unknown): string[] {
  const errors: string[] = [];

  if (!isString(value)) {
    errors.push("password must be a string");
    return errors;
  }

  if (value.length < 8) {
    errors.push("password must be at least 8 characters long");
  }
  if (!/[A-Z]/.test(value)) {
    errors.push("password must contain an uppercase letter");
  }
  if (!/[a-z]/.test(value)) {
    errors.push("password must contain a lowercase letter");
  }
  if (!/[0-9]/.test(value)) {
    errors.push("password must contain a digit");
  }

  return errors;
}

function validateRegistration(input: unknown): ValidationResult {
  if (!isObject(input)) {
    return { ok: false, errors: ["input must be an object"] };
  }

  const errors: string[] = [
    ...validateEmail(input.email),
    ...validateAge(input.age),
    ...validatePassword(input.password),
  ];

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  return {
    ok: true,
    data: {
      email: input.email as string,
      age: input.age as number,
      password: input.password as string,
    },
  };
}

// Example usage
const result = validateRegistration({
  email: "alice@example.com",
  age: 25,
  password: "Secret123",
});

if (result.ok) {
  console.log("Valid registration:", result.data.email);
} else {
  console.log("Validation errors:", result.errors);
}
```

### Why this is a good pattern

- It treats external input as `unknown`, forcing runtime checks.
- Type predicates (`value is T`) let TypeScript narrow values safely.
- Errors are collected, not short-circuited, improving UX.
- The discriminated union result makes success/failure handling explicit and type-safe.

## Input validation in TypeScript — interview answer

### 1. Why it matters
TypeScript types are erased at runtime. Data coming from HTTP bodies, query params, env vars, `localStorage`, files, or third-party APIs is effectively `unknown`. Validation is the boundary where we turn untrusted input into a trusted, typed value.

Key ideas I’d emphasize:
- **Validate at the boundary, not deep in business logic.** Parse once, then pass typed values down.
- **Fail fast with precise errors.** Report *which* field failed and *why*.
- **Allowlist, don’t blocklist.** Prefer schemas that declare expected fields; ignore or reject extras intentionally.
- **Separate validation from sanitization.** Validate first (is it a valid email?), then sanitize (trim/lowercase) if needed.
- **Type narrowing.** A good validator should make TypeScript understand the result type (`unknown → User`).
- **Composability.** Small reusable schemas (`Email`, `PositiveInt`) beat one-off `if` chains.
- **Security.** Watch for mass assignment, prototype pollution (`__proto__`), oversized payloads, and injection. Use safe parsers, size limits, and explicit field selection.

Common approaches:
1. **Manual type guards** — fine for tiny cases.
2. **Assertion functions** (`asserts x is T`) — good for internal invariants.
3. **Schema libraries** (Zod, Valibot, io-ts, Yup) — best for boundaries; they give runtime validation + inferred static types.

Below is a compact but complete “core” of a schema validator: primitives, objects, arrays, optional/nullable, literals, unions, and refinements, with inferred TypeScript types.

---

### 2. Core implementation

```ts
// ---------------------------------------------------------------------------
// Tiny schema validation core (TypeScript)
// Supports: string, number, boolean, literal, object, array, optional,
// nullable, union, and refine. Designed to mirror the ergonomics of Zod
// while staying small enough to read in an interview.
// ---------------------------------------------------------------------------

type Path = (string | number)[];

export interface ValidationError {
  path: Path;
  message: string;
}

export type ValidationResult<T> =
  | { success: true; data: T }
  | { success: false; errors: ValidationError[] };

// Phantom type carrier: Schema<T> also carries T for inference via Infer<T>.
export class Schema<T> {
  constructor(
    // Internal parser receives the current path for accurate error locations.
    public readonly _parse: (input: unknown, path: Path) => ValidationResult<T>
  ) {}

  // Public entry points -----------------------------------------------------
  safeParse(input: unknown): ValidationResult<T> {
    return this._parse(input, []);
  }

  parse(input: unknown): T {
    const result = this.safeParse(input);
    if (!result.success) {
      const message = result.errors
        .map((e) => `${e.path.join(".") || "<root>"}: ${e.message}`)
        .join("; ");
      throw new ValidationErrorList(result.errors, message);
    }
    return result.data;
  }

  // Combinators -------------------------------------------------------------
  optional(): Schema<T | undefined> {
    return new Schema((input, path) =>
      input === undefined
        ? { success: true, data: undefined }
        : this._parse(input, path)
    );
  }

  nullable(): Schema<T | null> {
    return new Schema((input, path) =>
      input === null
        ? { success: true, data: null }
        : this._parse(input, path)
    );
  }

  refine(predicate: (value: T) => boolean, message: string): Schema<T> {
    return new Schema((input, path) => {
      const result = this._parse(input, path);
      if (!result.success) return result;
      if (!predicate(result.data)) {
        return { success: false, errors: [{ path, message }] };
      }
      return result;
    });
  }

  or<U>(other: Schema<U>): Schema<T | U> {
    return new Schema((input, path) => {
      const first = this._parse(input, path);
      if (first.success) return first;
      const second = other._parse(input, path);
      if (second.success) return second;
      // Prefer the second error set; in production you might merge both.
      return second;
    });
  }
}

export class ValidationErrorList extends Error {
  constructor(
    public readonly errors: ValidationError[],
    message: string
  ) {
    super(message);
    this.name = "ValidationErrorList";
  }
}

// ---------------------------------------------------------------------------
// Type inference helper
// ---------------------------------------------------------------------------
export type Infer<S> = S extends Schema<infer T> ? T : never;

// ---------------------------------------------------------------------------
// Primitive schemas
// ---------------------------------------------------------------------------
function ok<T>(data: T): ValidationResult<T> {
  return { success: true, data };
}

function fail(path: Path, message: string): ValidationResult<never> {
  return { success: false, errors: [{ path, message }] };
}

export function string(): Schema<string> {
  return new Schema((input, path) =>
    typeof input === "string" ? ok(input) : fail(path, "Expected string")
  );
}

export function number(): Schema<number> {
  return new Schema((input, path) =>
    typeof input === "number" && !Number.isNaN(input)
      ? ok(input)
      : fail(path, "Expected number")
  );
}

export function boolean(): Schema<boolean> {
  return new Schema((input, path) =>
    typeof input === "boolean" ? ok(input) : fail(path, "Expected boolean")
  );
}

export function literal<V extends string | number | boolean>(
  value: V
): Schema<V> {
  return new Schema((input, path) =>
    input === value ? ok(value) : fail(path, `Expected literal ${String(value)}`)
  );
}

// ---------------------------------------------------------------------------
// Composite schemas
// ---------------------------------------------------------------------------

export function array<T>(item: Schema<T>): Schema<T[]> {
  return new Schema((input, path) => {
    if (!Array.isArray(input)) {
      return fail(path, "Expected array");
    }

    const result: T[] = [];
    const errors: ValidationError[] = [];

    input.forEach((value, index) => {
      const parsed = item._parse(value, [...path, index]);
      if (parsed.success) {
        result.push(parsed.data);
      } else {
        errors.push(...parsed.errors);
      }
    });

    return errors.length === 0
      ? ok(result)
      : { success: false, errors };
  });
}

export function object<TShape extends Record<string, Schema<any>>>(
  shape: TShape
): Schema<{ [K in keyof TShape]: Infer<TShape[K]> }> {
  return new Schema((input, path) => {
    if (typeof input !== "object" || input === null || Array.isArray(input)) {
      return fail(path, "Expected object");
    }

    // Guard against prototype pollution / inherited keys.
    const obj = Object.create(null) as Record<string, unknown>;
    for (const key of Object.keys(input as object)) {
      obj[key] = (input as Record<string, unknown>)[key];
    }

    const result: Record<string, unknown> = {};
    const errors: ValidationError[] = [];

    for (const key of Object.keys(shape) as (keyof TShape)[]) {
      // Only declared keys are accepted -> allowlist behavior.
      const fieldResult = shape[key]._parse(obj[key as string], [...path, key as string]);
      if (fieldResult.success) {
        result[key as string] = fieldResult.data;
      } else {
        errors.push(...fieldResult.errors);
      }
    }

    if (errors.length > 0) {
      return { success: false, errors };
    }

    return ok(result as { [K in keyof TShape]: Infer<TShape[K]> });
  });
}

// ---------------------------------------------------------------------------
// Example usage
// ---------------------------------------------------------------------------

const Email = string().refine(
  (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
  "Invalid email"
);

const PositiveInt = number().refine(
  (n) => Number.isInteger(n) && n > 0,
  "Expected positive integer"
);

const Role = literal("admin").or(literal("user"));

const UserSchema = object({
  id: PositiveInt,
  email: Email,
  age: number().optional(),
  roles: array(Role),
});

// Inferred type: { id: number; email: string; age?: number; roles: ("admin"|"user")[] }
type User = Infer<typeof UserSchema>;

function handleRequest(raw: unknown) {
  try {
    const user: User = UserSchema.parse(raw); // throws on invalid input
    // From here, `user` is fully typed and trusted.
    console.log("OK", user);
  } catch (err) {
    if (err instanceof ValidationErrorList) {
      console.error("Validation failed:", err.errors);
    } else {
      throw err;
    }
  }
}

// Demo
handleRequest({
  id: 42,
  email: "ada@example.com",
  roles: ["admin", "user"],
});
```

### 3. Interview follow-ups you can mention
- **Coercion:** Add `coerceNumber()` that runs `Number(input)` first, but keep it explicit and separate from strict `number()`.
- **Async validation:** Database uniqueness checks can be `parseAsync` variants.
- **Unknown keys:** Switch `object()` to strict mode by rejecting keys not in `shape`.
- **Error formatting:** Map `ValidationError[]` to framework-specific responses (e.g., RFC 7807 problem details).
- **Performance:** Compile schemas to validators for hot paths; cache parsed results carefully.
- **Security hardening:** Limit payload size before parsing, cap array lengths, and avoid `eval`/dynamic code.

This implementation gives you the essential core: runtime checks, precise paths, type inference, and composable schemas.

## Input validation edge cases in TypeScript

TypeScript types are erased at runtime, so validation must happen at runtime. The hard part is usually not the “happy path,” but distinguishing values that look valid in JS (`null`, `0`, `""`, `NaN`, `Infinity`, arrays, dates, etc.).

Below are common edge cases with idiomatic examples. Many examples use **Zod**, but the same ideas apply to Yup, io-ts, Valibot, or hand-written guards.

---

### 1. `typeof null === "object"`

A classic TypeScript guard bug.

```ts
function isUser(x: unknown): x is { name: string } {
  // BAD: null passes typeof check
  // return typeof x === "object" && "name" in x;

  // GOOD
  return (
    typeof x === "object" &&
    x !== null &&
    "name" in x &&
    typeof (x as { name: unknown }).name === "string"
  );
}
```

---

### 2. Falsy but valid values: `0`, `""`, `false`

Do not use truthiness for required fields.

```ts
// BAD
if (!age) throw new Error("age required");

// GOOD
if (age === undefined || age === null) throw new Error("age required");
```

With Zod:

```ts
import { z } from "zod";

const schema = z.object({
  age: z.number().min(0),        // 0 is valid
  name: z.string().min(1),       // "" is invalid, but "a" is valid
  active: z.boolean(),           // false is valid
});

schema.parse({ age: 0, name: "a", active: false }); // OK
```

---

### 3. `NaN` and `Infinity`

`typeof NaN === "number"` but it is not a useful number.

```ts
import { z } from "zod";

const n = z.number().finite(); // rejects NaN and ±Infinity

n.safeParse(NaN).success;        // false
n.safeParse(Infinity).success;   // false
n.safeParse(42).success;         // true
```

Hand-written:

```ts
function isFiniteNumber(x: unknown): x is number {
  return typeof x === "number" && Number.isFinite(x);
}
```

---

### 4. String coercion surprises

Coercion can silently convert unwanted values.

```ts
import { z } from "zod";

// z.coerce.number(): "" -> 0, true -> 1, null -> 0
const bad = z.coerce.number();
bad.parse(""); // 0 (probably not desired)

// Better: require string first, then parse with explicit rules
const good = z
  .string()
  .trim()
  .regex(/^\d+$/)
  .transform((s) => Number(s))
  .refine(Number.isSafeInteger, "must be safe integer");
```

Also handle Unicode, invisible characters, and normalization:

```ts
const username = z
  .string()
  .trim()
  .min(3)
  .max(32)
  .regex(/^[\p{L}\p{N}_-]+$/u, "invalid characters");
```

---

### 5. Empty vs missing: optional, nullable, undefined, null

These are not the same.

```ts
import { z } from "zod";

const schema = z.object({
  nickname: z.string().optional(),   // undefined allowed
  bio: z.string().nullable(),       // null allowed
  score: z.number().nullish(),       // null or undefined allowed
});

schema.parse({});                       // OK: nickname/bio/score undefined
schema.parse({ bio: null });            // OK
```

Defaults apply only to `undefined`, not `null`:

```ts
const withDefault = z.object({
  role: z.string().default("user"),
});

withDefault.parse({ role: undefined }); // { role: "user" }
withDefault.parse({ role: null });     // throws
```

---

### 6. Objects: extra keys, missing keys, and prototype pollution

```ts
import { z } from "zod";

const schema = z
  .object({
    name: z.string(),
  })
  .strict(); // reject unknown keys

schema.parse({ name: "Ada", admin: true }); // throws

// Zod default strips unknown keys:
z.object({ name: z.string() }).parse({ name: "Ada", admin: true });
// { name: "Ada" }
```

Avoid trusting `__proto__`, `constructor`, `prototype`:

```ts
function safeParseObject(input: unknown) {
  if (typeof input !== "object" || input === null) return null;
  const obj = Object.create(null); // no prototype
  for (const key of Object.keys(input)) {
    if (key === "__proto__" || key === "constructor" || key === "prototype") continue;
    obj[key] = (input as Record<string, unknown>)[key];
  }
  return obj;
}
```

---

### 7. Arrays: empty, sparse, and nested validation

```ts
import { z } from "zod";

const tags = z
  .array(z.string().min(1))
  .min(1)          // at least one tag
  .max(20)         // prevent unbounded input
  .refine((arr) => new Set(arr).size === arr.length, "duplicate tags");

tags.parse(["a", "b"]); // OK
tags.parse([]);         // throws
tags.parse(["", "x"]);  // throws
```

Sparse arrays are a JS edge case:

```ts
const arr = [1, , 3];
arr.length; // 3
arr[1];     // undefined

// If accepting arrays from JSON, sparse arrays usually aren't representable,
// but defensive code can reject holes:
function isDense(arr: unknown[]): boolean {
  return arr.every((_, i) => Object.prototype.hasOwnProperty.call(arr, i));
}
```

---

### 8. Dates and time zones

```ts
import { z } from "zod";

const dateSchema = z.coerce.date().refine((d) => !isNaN(d.getTime()), "invalid date");

dateSchema.parse("2024-01-01"); // Date
dateSchema.parse("not-a-date"); // throws

// Better for APIs: accept ISO strings, not arbitrary Date parsing
const isoDate = z.string().datetime(); // RFC3339/ISO
```

Be careful: `new Date("2024-02-30")` rolls over in JS. If strict calendar validation matters, parse components manually.

---

### 9. Enums and literal unions

```ts
import { z } from "zod";

const role = z.enum(["admin", "user", "guest"]);

role.parse("admin"); // OK
role.parse("ADMIN"); // throws
```

For case-insensitive input, normalize first:

```ts
const role = z
  .string()
  .transform((s) => s.toLowerCase())
  .pipe(z.enum(["admin", "user", "guest"]));
```

---

### 10. Discriminated unions

Make sure the discriminator is validated before branching.

```ts
import { z } from "zod";

const event = z.discriminatedUnion("type", [
  z.object({ type: z.literal("click"), x: z.number(), y: z.number() }),
  z.object({ type: z.literal("keypress"), key: z.string() }),
]);

event.parse({ type: "click", x: 1, y: 2 }); // OK
event.parse({ type: "unknown" });             // throws
```

Hand-written version must validate discriminator first:

```ts
function parseEvent(x: unknown) {
  if (typeof x !== "object" || x === null) throw new Error("object required");
  const type = (x as { type?: unknown }).type;
  if (type === "click") {
    // validate x, y...
  } else if (type === "keypress") {
    // validate key...
  } else {
    throw new Error("unknown event type");
  }
}
```

---

### 11. Branded types for domain invariants

Use brands to prevent mixing validated and unvalidated strings.

```ts
import { z } from "zod";

const Email = z
  .string()
  .email()
  .brand<"Email">();

type Email = z.infer<typeof Email>;

function send(to: Email) {}

const raw = "a@example.com";
const email = Email.parse(raw);
send(email); // OK
// send(raw); // Type error: string is not Email
```

---

### 12. Async validation (database uniqueness, remote checks)

Sync schemas are not enough for uniqueness.

```ts
import { z } from "zod";

const usernameSchema = z
  .string()
  .min(3)
  .refine(async (value) => {
    const exists = await db.userExists(value);
    return !exists;
  }, "username already taken");

// Must use parseAsync
const result = await usernameSchema.safeParseAsync("ada");
```

Edge cases:
- Race conditions: two requests can pass uniqueness check simultaneously. Add a DB unique constraint.
- Timeouts and partial failures.
- Do not run expensive async checks for syntactically invalid input; structure with `.pipe` or manual gating.

---

### 13. Input from URLs, forms, and environment variables

Query params and env vars are usually strings, often optional, sometimes arrays.

```ts
import { z } from "zod";

const Query = z.object({
  page: z.coerce.number().int().min(1).default(1),
  q: z.string().trim().optional(),
  ids: z
    .union([z.string(), z.array(z.string())])
    .transform((v) => (Array.isArray(v) ? v : [v]))
    .default([]),
});

// Express/Fastify-style:
const parsed = Query.parse(req.query);
```

Env vars:

```ts
const Env = z.object({
  PORT: z.coerce.number().int().min(1).max(65535).default(3000),
  DATABASE_URL: z.string().url(),
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
});

const env = Env.parse(process.env);
```

Edge: empty env var `""` is present but invalid; Zod treats it as a string and validation can reject it.

---

### 14. JSON parsing boundaries

`JSON.parse` can throw and can produce `any`.

```ts
function parseJson<T>(input: string, schema: z.ZodType<T>): T {
  let data: unknown;
  try {
    data = JSON.parse(input);
  } catch {
    throw new Error("invalid JSON");
  }
  return schema.parse(data);
}

// Also limit size before parsing
const MAX_BYTES = 1_000_000;
if (Buffer.byteLength(body) > MAX_BYTES) throw new Error("payload too large");
```

Edge cases:
- Duplicate keys (last wins in JS).
- `__proto__` in JSON can be dangerous if assigned blindly.
- Very deep nesting can cause stack overflows.

---

### 15. Regex validation and ReDoS

Catastrophic backtracking is a real DoS vector.

```ts
// BAD: nested quantifiers
const bad = /^([a-zA-Z0-9]+)+$/;

// GOOD: avoid nested quantifiers; set max length first
const good = z
  .string()
  .max(100)
  .regex(/^[a-zA-Z0-9]+$/);
```

Prefer linear-time patterns or dedicated validators (e.g. `validator` library) for emails/URLs instead of giant regexes.

---

### 16. Error reporting: collect all errors, not just first

```ts
import { z } from "zod";

const schema = z.object({
  email: z.string().email(),
  age: z.number().int().min(0),
});

const result = schema.safeParse({ email: "bad", age: -1 });

if (!result.success) {
  // result.error.flatten() gives per-field errors
  console.log(result.error.flatten().fieldErrors);
  // { email: ['Invalid email'], age: ['Number must be greater than or equal to 0'] }
}
```

For user-facing forms, return structured errors keyed by field rather than a single thrown string.

---

### 17. Security limits

Validation is also a DoS defense.

```ts
const schema = z.object({
  title: z.string().max(200),
  body: z.string().max(10_000),
  tags: z.array(z.string().max(50)).max(20),
  metadata: z.record(z.string().max(500)).refine(
    (obj) => Object.keys(obj).length <= 50,
    "too many metadata keys"
  ),
});
```

Also validate file uploads separately: MIME type, magic bytes, size, and filename sanitization. Never trust client-provided filenames or content types alone.

---

### 18. Custom type guards with exhaustive checks

```ts
type Status = "pending" | "approved" | "rejected";

function isStatus(x: unknown): x is Status {
  return x === "pending" || x === "approved" || x === "rejected";
}

// Exhaustive handling prevents missing cases
function label(s: Status): string {
  switch (s) {
    case "pending": return "Pending";
    case "approved": return "Approved";
    case "rejected": return "Rejected";
    default: {
      const _exhaustive: never = s;
      throw new Error(`unhandled status: ${_exhaustive}`);
    }
  }
}
```

---

### Practical checklist

- Validate at every trust boundary: HTTP, DB reads, message queues, files, env.
- Use `unknown` for untrusted input, never `any`.
- Reject `null` explicitly unless nullable is intended.
- Use finite number checks and safe integers.
- Trim and normalize strings, but be explicit about Unicode.
- Set `min`, `max`, and size limits everywhere.
- Use strict object schemas unless extra keys are intentionally allowed.
- Prefer ISO strings over locale-dependent date parsing.
- Keep async validation behind syntactic validation.
- Return structured errors for UX.
- Add DB constraints as the final source of truth for uniqueness.

If you want, I can also show a full request-validation middleware example for Express/Fastify/Nest using Zod.

Here is a complete, runnable TypeScript implementation of arbitrary-precision integers and binary floating-point numbers, with arithmetic, parsing, formatting, and a demo.

```typescript
// numbers.ts
// Run with: npx ts-node numbers.ts   (or tsc numbers.ts && node numbers.js)

// ============================================================
// Integer: arbitrary-precision, base 2^24 limbs, manual arithmetic
// ============================================================

class Integer {
  static readonly BASE = 1 << 24; // 16777216
  static readonly ZERO = new Integer();
  static readonly ONE = Integer.fromBigInt(1n);
  static readonly TWO = Integer.fromBigInt(2n);

  private limbs: number[]; // little-endian, base BASE
  private neg: boolean;

  constructor() {
    this.limbs = [0];
    this.neg = false;
  }

  // ---------- construction ----------
  static fromBigInt(b: bigint): Integer {
    const r = new Integer();
    if (b === 0n) return r;
    const negative = b < 0n;
    let x = negative ? -b : b;
    const limbs: number[] = [];
    while (x > 0n) {
      limbs.push(Number(x % BigInt(Integer.BASE)));
      x /= BigInt(Integer.BASE);
    }
    r.limbs = limbs;
    r.neg = negative;
    return r;
  }

  static fromNumber(n: number): Integer {
    return Integer.fromBigInt(BigInt(Math.trunc(n)));
  }

  static fromString(s: string): Integer {
    s = s.trim();
    if (s === '') throw new Error('empty integer string');
    return Integer.fromBigInt(BigInt(s)); // BigInt handles parsing/validation
  }

  // ---------- basic predicates ----------
  isZero(): boolean {
    return this.limbs.length === 1 && this.limbs[0] === 0;
  }

  clone(): Integer {
    const r = new Integer();
    r.limbs = [...this.limbs];
    r.neg = this.neg;
    return r;
  }

  abs(): Integer {
    const r = this.clone();
    r.neg = false;
    return r;
  }

  neg(): Integer {
    const r = this.clone();
    if (!r.isZero()) r.neg = !r.neg;
    return r;
  }

  // ---------- comparison ----------
  static cmpAbs(a: Integer, b: Integer): number {
    if (a.limbs.length !== b.limbs.length) {
      return a.limbs.length < b.limbs.length ? -1 : 1;
    }
    for (let i = a.limbs.length - 1; i >= 0; i--) {
      if (a.limbs[i] !== b.limbs[i]) {
        return a.limbs[i] < b.limbs[i] ? -1 : 1;
      }
    }
    return 0;
  }

  cmp(other: Integer): number {
    if (this.neg !== other.neg) {
      if (this.isZero() && other.isZero()) return 0;
      return this.neg ? -1 : 1;
    }
    const c = Integer.cmpAbs(this, other);
    return this.neg ? -c : c;
  }

  equals(other: Integer): boolean {
    return this.cmp(other) === 0;
  }

  // ---------- bit helpers ----------
  bitLength(): number {
    if (this.isZero()) return 0;
    const top = this.limbs[this.limbs.length - 1];
    let bl = 0;
    let t = top;
    while (t > 0) {
      bl++;
      t >>= 1;
    }
    return bl + 24 * (this.limbs.length - 1);
  }

  bitAt(pos: number): number {
    if (pos < 0) return 0;
    const li = Math.floor(pos / 24);
    const bi = pos % 24;
    if (li >= this.limbs.length) return 0;
    return (this.limbs[li] >> bi) & 1;
  }

  static oneShl(k: number): Integer {
    if (k < 0) throw new Error('negative shift');
    const limbIndex = Math.floor(k / 24);
    const bitIndex = k % 24;
    const r = new Integer();
    const limbs = new Array(limbIndex + 1).fill(0);
    limbs[limbIndex] = 1 << bitIndex;
    r.limbs = limbs;
    r.neg = false;
    return r;
  }

  static shl1(a: Integer): Integer {
    const r = new Integer();
    const limbs = [...a.limbs];
    let carry = 0;
    for (let i = 0; i < limbs.length; i++) {
      const v = (limbs[i] << 1) | carry;
      if (v >= Integer.BASE) {
        limbs[i] = v - Integer.BASE;
        carry = 1;
      } else {
        limbs[i] = v;
        carry = 0;
      }
    }
    if (carry) limbs.push(1);
    r.limbs = limbs;
    r.neg = a.neg;
    if (r.isZero()) r.neg = false;
    return r;
  }

  static shr1(a: Integer): Integer {
    const r = new Integer();
    const limbs = new Array(a.limbs.length).fill(0);
    let carry = 0;
    for (let i = a.limbs.length - 1; i >= 0; i--) {
      const val = a.limbs[i] + carry * Integer.BASE;
      limbs[i] = Math.floor(val / 2);
      carry = val % 2;
    }
    while (limbs.length > 1 && limbs[limbs.length - 1] === 0) limbs.pop();
    r.limbs = limbs;
    r.neg = a.neg;
    if (r.isZero()) r.neg = false;
    return r;
  }

  // ---------- arithmetic ----------
  static addAbs(a: Integer, b: Integer): Integer {
    const r = new Integer();
    const n = Math.max(a.limbs.length, b.limbs.length);
    const limbs: number[] = [];
    let carry = 0;
    for (let i = 0; i < n; i++) {
      const x =
        (i < a.limbs.length ? a.limbs[i] : 0) +
        (i < b.limbs.length ? b.limbs[i] : 0) +
        carry;
      carry = Math.floor(x / Integer.BASE);
      limbs.push(x % Integer.BASE);
    }
    if (carry) limbs.push(carry);
    r.limbs = limbs;
    r.neg = false;
    return r;
  }

  static subAbs(a: Integer, b: Integer): Integer {
    // assumes |a| >= |b|
    const r = new Integer();
    const limbs: number[] = [];
    let borrow = 0;
    for (let i = 0; i < a.limbs.length; i++) {
      const x =
        a.limbs[i] - (i < b.limbs.length ? b.limbs[i] : 0) - borrow;
      if (x < 0) {
        borrow = 1;
        limbs.push(x + Integer.BASE);
      } else {
        borrow = 0;
        limbs.push(x);
      }
    }
    while (limbs.length > 1 && limbs[limbs.length - 1] === 0) limbs.pop();
    r.limbs = limbs;
    r.neg = false;
    return r;
  }

  static add(a: Integer, b: Integer): Integer {
    if (a.neg === b.neg) {
      const r = Integer.addAbs(a, b);
      r.neg = a.neg;
      if (r.isZero()) r.neg = false;
      return r;
    }
    const c = Integer.cmpAbs(a, b);
    if (c === 0) return new Integer();
    if (c > 0) {
      const r = Integer.subAbs(a, b);
      r.neg = a.neg;
      return r;
    } else {
      const r = Integer.subAbs(b, a);
      r.neg = b.neg;
      return r;
    }
  }

  static sub(a: Integer, b: Integer): Integer {
    return Integer.add(a, b.neg());
  }

  static mul(a: Integer, b: Integer): Integer {
    if (a.isZero() || b.isZero()) return new Integer();
    const res = new Array(a.limbs.length + b.limbs.length).fill(0);
    for (let i = 0; i < a.limbs.length; i++) {
      let carry = 0;
      for (let j = 0; j < b.limbs.length; j++) {
        const prod = res[i + j] + a.limbs[i] * b.limbs[j] + carry;
        res[i + j] = prod % Integer.BASE;
        carry = Math.floor(prod / Integer.BASE);
      }
      let k = i + b.limbs.length;
      let c = carry;
      while (c > 0) {
        const sum = res[k] + c;
        res[k] = sum % Integer.BASE;
        c = Math.floor(sum / Integer.BASE);
        k++;
      }
    }
    while (res.length > 1 && res[res.length - 1] === 0) res.pop();
    const r = new Integer();
    r.limbs = res;
    r.neg = a.neg !== b.neg;
    return r;
  }

  static divMod(a: Integer, b: Integer): { q: Integer; r: Integer } {
    if (b.isZero()) throw new Error('division by zero');
    const negQ = a.neg !== b.neg;
    const A = a.abs();
    const B = b.abs();
    if (Integer.cmpAbs(A, B) < 0) {
      return { q: new Integer(), r: a.clone() };
    }
    let q = new Integer();
    let rem = new Integer();
    const n = A.bitLength();
    for (let i = n - 1; i >= 0; i--) {
      rem = Integer.shl1(rem);
      if (A.bitAt(i) === 1) rem = Integer.add(rem, Integer.ONE);
      if (Integer.cmpAbs(rem, B) >= 0) {
        rem = Integer.subAbs(rem, B);
        q = Integer.add(q, Integer.oneShl(i));
      }
    }
    if (negQ && !q.isZero()) q.neg = true;
    if (a.neg && !rem.isZero()) rem.neg = true;
    return { q, r: rem };
  }

  static div(a: Integer, b: Integer): Integer {
    return Integer.divMod(a, b).q;
  }

  static mod(a: Integer, b: Integer): Integer {
    return Integer.divMod(a, b).r;
  }

  static pow(base: Integer, exp: Integer): Integer {
    if (exp.neg) throw new Error('negative exponent');
    let result = Integer.ONE.clone();
    let b = base.clone();
    let e = exp.clone();
    while (!e.isZero()) {
      if (e.bitAt(0) === 1) result = Integer.mul(result, b);
      e = Integer.shr1(e);
      if (!e.isZero()) b = Integer.mul(b, b);
    }
    return result;
  }

  // ---------- conversion ----------
  toBigInt(): bigint {
    let x = 0n;
    for (let i = this.limbs.length - 1; i >= 0; i--) {
      x = x * BigInt(Integer.BASE) + BigInt(this.limbs[i]);
    }
    return this.neg ? -x : x;
  }

  toString(): string {
    return this.toBigInt().toString();
  }
}

// ============================================================
// Float: binary floating point (configurable mantissa precision)
// ============================================================

class Float {
  static readonly DEFAULT_PRECISION = 53;

  private sign: boolean; // true = negative
  private mantissa: Integer; // non-negative integer
  private exponent: number; // base-2 exponent
  private precision: number;
  private isNaN: boolean;
  private isInfinity: boolean;

  constructor(precision: number = Float.DEFAULT_PRECISION) {
    this.precision = precision;
    this.sign = false;
    this.mantissa = new Integer();
    this.exponent = 0;
    this.isNaN = false;
    this.isInfinity = false;
  }

  // ---------- factories ----------
  static fromInteger(x: Integer, precision: number = Float.DEFAULT_PRECISION): Float {
    const f = new Float(precision);
    if (x.isZero()) {
      f.mantissa = new Integer();
      f.exponent = 0;
      f.sign = false;
      return f;
    }
    f.sign = x.neg;
    f.mantissa = x.abs();
    f.exponent = 0;
    f.normalize();
    return f;
  }

  static fromNumber(n: number, precision: number = Float.DEFAULT_PRECISION): Float {
    const f = new Float(precision);
    if (Number.isNaN(n)) {
      f.isNaN = true;
      return f;
    }
    if (n === Infinity) {
      f.isInfinity = true;
      f.sign = false;
      return f;
    }
    if (n === -Infinity) {
      f.isInfinity = true;
      f.sign = true;
      return f;
    }
    if (n === 0) {
      f.mantissa = new Integer();
      f.exponent = 0;
      f.sign = Math.sign(n) < 0;
      return f;
    }
    f.sign = n < 0;
    const a = Math.abs(n);
    const exp = Math.floor(Math.log2(a));
    const mant = a / Math.pow(2, exp);
    const scale = Math.pow(2, precision - 1);
    let m = Math.round(mant * scale);
    let e = exp - (precision - 1);
    if (m === Math.pow(2, precision)) {
      m = Math.pow(2, precision - 1);
      e += 1;
    }
    f.mantissa = Integer.fromNumber(m);
    f.exponent = e;
    f.normalize();
    return f;
  }

  static fromString(s: string, precision: number = Float.DEFAULT_PRECISION): Float {
    s = s.trim();
    const lower = s.toLowerCase();
    if (lower === 'nan') {
      const f = new Float(precision);
      f.isNaN = true;
      return f;
    }
    if (lower === 'infinity' || lower === 'inf') {
      const f = new Float(precision);
      f.isInfinity = true;
      return f;
    }
    if (lower === '-infinity' || lower === '-inf') {
      const f = new Float(precision);
      f.isInfinity = true;
      f.sign = true;
      return f;
    }

    let sign = false;
    let t = s;
    if (t[0] === '-' || t[0] === '+') {
      if (t[0] === '-') sign = true;
      t = t.slice(1);
    }

    let exp10 = 0;
    const eIdx = t.toLowerCase().indexOf('e');
    if (eIdx >= 0) {
      exp10 = parseInt(t.slice(eIdx + 1), 10);
      t = t.slice(0, eIdx);
    }

    let intPart = t;
    let fracPart = '';
    const dot = t.indexOf('.');
    if (dot >= 0) {
      intPart = t.slice(0, dot);
      fracPart = t.slice(dot + 1);
    }
    if (intPart === '') intPart = '0';

    const digits = (intPart + fracPart).replace(/^0+/, '') || '0';
    const decExp = exp10 - fracPart.length;

    const M = Integer.fromString(digits);
    const fM = Float.fromInteger(M, precision);

    if (decExp === 0) {
      fM.sign = sign && !fM.mantissa.isZero();
      return fM;
    }

    const pow10 = Integer.pow(
      Integer.fromNumber(10),
      Integer.fromNumber(Math.abs(decExp))
    );
    const fPow = Float.fromInteger(pow10, precision);

    let result: Float;
    if (decExp > 0) result = Float.mul(fM, fPow);
    else result = Float.div(fM, fPow);

    if (result.mantissa.isZero()) result.sign = false;
    else result.sign = sign;
    return result;
  }

  // ---------- normalization ----------
  private normalize(): void {
    if (this.isNaN || this.isInfinity) return;
    if (this.mantissa.isZero()) {
      this.sign = false;
      this.exponent = 0;
      return;
    }
    const prec = this.precision;
    const bl = this.mantissa.bitLength();
    if (bl === prec) {
      // ok
    } else if (bl > prec) {
      const shift = bl - prec;
      const { q, r } = Integer.divMod(this.mantissa, Integer.oneShl(shift));
      let mant = q;
      const half = Integer.oneShl(shift - 1);
      const cmp = Integer.cmpAbs(r, half);
      if (cmp > 0) {
        mant = Integer.add(mant, Integer.ONE);
      } else if (cmp === 0) {
        if (mant.bitAt(0) === 1) mant = Integer.add(mant, Integer.ONE);
      }
      if (mant.bitLength() > prec) {
        mant = Integer.shr1(mant);
        this.exponent += 1;
      }
      this.mantissa = mant;
      this.exponent += shift;
    } else {
      const shift = prec - bl;
      this.mantissa = Integer.mul(this.mantissa, Integer.oneShl(shift));
      this.exponent -= shift;
    }
  }

  // ---------- predicates ----------
  isZero(): boolean {
    return !this.isNaN && !this.isInfinity && this.mantissa.isZero();
  }

  // ---------- arithmetic ----------
  static add(a: Float, b: Float): Float {
    const prec = a.precision;
    const r = new Float(prec);

    if (a.isNaN || b.isNaN) {
      r.isNaN = true;
      return r;
    }
    // infinity handling
    if (a.isInfinity || b.isInfinity) {
      if (a.isInfinity && b.isInfinity) {
        if (a.sign === b.sign) {
          r.isInfinity = true;
          r.sign = a.sign;
          return r;
        }
        r.isNaN = true;
        return r;
      }
      const inf = a.isInfinity ? a : b;
      r.isInfinity = true;
      r.sign = inf.sign;
      return r;
    }

    if (a.mantissa.isZero()) {
      // return copy of b
      r.sign = b.sign;
      r.mantissa = b.mantissa.clone();
      r.exponent = b.exponent;
      r.normalize();
      return r;
    }
    if (b.mantissa.isZero()) {
      r.sign = a.sign;
      r.mantissa = a.mantissa.clone();
      r.exponent = a.exponent;
      r.normalize();
      return r;
    }

    const e = Math.min(a.exponent, b.exponent);
    const shiftA = a.exponent - e;
    const shiftB = b.exponent - e;
    const ma = Integer.mul(a.mantissa, Integer.oneShl(shiftA));
    const mb = Integer.mul(b.mantissa, Integer.oneShl(shiftB));

    let m: Integer;
    let resultSign = a.sign;

    if (a.sign === b.sign) {
      m = Integer.add(ma, mb);
      resultSign = a.sign;
    } else {
      const c = Integer.cmpAbs(ma, mb);
      if (c === 0) {
        r.mantissa = new Integer();
        r.exponent = 0;
        r.sign = false;
        return r;
      }
      if (c > 0) {
        m = Integer.subAbs(ma, mb);
        resultSign = a.sign;
      } else {
        m = Integer.subAbs(mb, ma);
        resultSign = b.sign;
      }
    }

    if (m.isZero()) resultSign = false;
    r.sign = resultSign;
    r.mantissa = m;
    r.exponent = e;
    r.normalize();
    return r;
  }

  static sub(a: Float, b: Float): Float {
    const nb = b.cloneNegate();
    return Float.add(a, nb);
  }

  cloneNegate(): Float {
    const r = this.clone();
    if (!r.mantissa.isZero() && !r.isNaN && !r.isInfinity) r.sign = !r.sign;
    if (r.isInfinity) r.sign = !r.sign;
    return r;
  }

  clone(): Float {
    const r = new Float(this.precision);
    r.sign = this.sign;
    r.mantissa = this.mantissa.clone();
    r.exponent = this.exponent;
    r.isNaN = this.isNaN;
    r.isInfinity = this.isInfinity;
    return r;
  }

  static mul(a: Float, b: Float): Float {
    const prec = a.precision;
    const r = new Float(prec);

    if (a.isNaN || b.isNaN) {
      r.isNaN = true;
      return r;
    }
    if (a.isInfinity || b.isInfinity) {
      if (a.mantissa.isZero() || b.mantissa.isZero()) {
        // inf * 0 -> nan
        if ((a.isInfinity && b.isZero()) || (b.isInfinity && a.isZero())) {
          r.isNaN = true;
          return r;
        }
      }
      r.isInfinity = true;
      r.sign = a.sign !== b.sign;
      return r;
    }
    if (a.mantissa.isZero() || b.mantissa.isZero()) {
      r.mantissa = new Integer();
      r.exponent = 0;
      r.sign = false;
      return r;
    }

    r.sign = a.sign !== b.sign;
    r.mantissa = Integer.mul(a.mantissa, b.mantissa);
    r.exponent = a.exponent + b.exponent;
    r.normalize();
    return r;
  }

  static div(a: Float, b: Float): Float {
    const prec = a.precision;
    const r = new Float(prec);

    if (a.isNaN || b.isNaN) {
      r.isNaN = true;
      return r;
    }
    if (b.mantissa.isZero() && !b.isInfinity) {
      // divide by zero
      if (a.mantissa.isZero()) r.isNaN = true;
      else {
        r.isInfinity = true;
        r.sign = a.sign !== b.sign;
      }
      return r;
    }
    if (a.isInfinity && b.isInfinity) {
      r.isNaN = true;
      return r;
    }
    if (a.isInfinity) {
      r.isInfinity = true;
      r.sign = a.sign !== b.sign;
      return r;
    }
    if (b.isInfinity) {
      r.mantissa = new Integer();
      r.exponent = 0;
      r.sign = false;
      return r;
    }
    if (a.mantissa.isZero()) {
      r.mantissa = new Integer();
      r.exponent = 0;
      r.sign = false;
      return r;
    }

    r.sign = a.sign !== b.sign;
    const shift = prec + b.mantissa.bitLength();
    const num = Integer.mul(a.mantissa, Integer.oneShl(shift));
    const { q } = Integer.divMod(num, b.mantissa);
    r.mantissa = q;
    r.exponent = a.exponent - b.exponent - shift;
    r.normalize();
    return r;
  }

  // ---------- comparison ----------
  cmp(other: Float): number {
    if (this.isNaN || other.isNaN) return NaN;
    if (this.isInfinity || other.isInfinity) {
      if (this.isInfinity && other.isInfinity) {
        if (this.sign === other.sign) return 0;
        return this.sign ? -1 : 1;
      }
      if (this.isInfinity) return this.sign ? -1 : 1;
      return other.sign ? 1 : -1;
    }
    if (this.mantissa.isZero() && other.mantissa.isZero()) return 0;
    if (this.sign !== other.sign) {
      return this.sign ? -1 : 1;
    }
    // same sign: compare magnitudes
    // align exponents
    const e = Math.min(this.exponent, other.exponent);
    const ma = Integer.mul(this.mantissa, Integer.oneShl(this.exponent - e));
    const mb = Integer.mul(other.mantissa, Integer.oneShl(other.exponent - e));
    const c = Integer.cmpAbs(ma, mb);
    return this.sign ? -c : c;
  }

  equals(other: Float): boolean {
    if (this.isNaN || other.isNaN) return false;
    if (this.isInfinity || other.isInfinity) {
      return this.isInfinity && other.isInfinity && this.sign === other.sign;
    }
    if (this.mantissa.isZero() && other.mantissa.isZero()) return true;
    return (
      this.sign === other.sign &&
      this.exponent === other.exponent &&
      this.mantissa.equals(other.mantissa)
    );
  }

  // ---------- conversion / formatting ----------
  toNumber(): number {
    if (this.isNaN) return NaN;
    if (this.isInfinity) return this.sign ? -Infinity : Infinity;
    return Number(this.toString());
  }

  toString(): string {
    if (this.isNaN) return 'NaN';
    if (this.isInfinity) return (this.sign ? '-' : '') + 'Infinity';
    if (this.mantissa.isZero()) return (this.sign ? '-' : '') + '0';

    const M = this.mantissa;
    const E = this.exponent;

    if (E >= 0) {
      const intVal = Integer.mul(M, Integer.oneShl(E));
      return (this.sign ? '-' : '') + intVal.toString();
    }

    const k = -E;
    const denom = Integer.oneShl(k);
    const { q: intPart, r: rem } = Integer.divMod(M, denom);

    const scale = Integer.pow(Integer.fromNumber(10), Integer.fromNumber(17));
    const fracScaled = Integer.divMod(Integer.mul(rem, scale), denom).q;
    let fracStr = fracScaled.toString().padStart(17, '0');
    fracStr = fracStr.replace(/0+$/, '');
    if (fracStr === '') fracStr = '0';

    return (this.sign ? '-' : '') + intPart.toString() + '.' + fracStr;
  }
}

