# Implementing Iterators in TypeScript

Below is a single, self-contained, runnable file (`iterators.ts`) that demonstrates four complementary techniques:

1. **Manual iterator + iterable** (full control over `next()`/`return()`/`throw()`).
2. **Iterable data structure** (a binary-search tree with in-order traversal).
3. **Generator functions** (the idiomatic, concise way).
4. **Async iterators / async generators** (streaming with `for await…of`).

It also exercises consumption patterns (`for…of`, spread, destructuring), early termination (`break` → `return()`), and exception propagation (`throw()`).

---

## `iterators.ts`

```typescript
// iterators.ts
// Run with:  npx ts-node iterators.ts   (or: tsc iterators.ts && node iterators.js)
// Requires target >= ES2015 (default in modern tsconfig).

/* =========================================================================
 * 1. Manual iterator: a numeric Range
 * ========================================================================= */

/** A plain Iterator<number> with full control over the protocol. */
class RangeIterator implements Iterator<number> {
  private current: number;
  private readonly end: number;
  private readonly step: number;
  private exhausted = false;

  constructor(start: number, end: number, step = 1) {
    if (step === 0) throw new Error("step cannot be 0");
    this.current = start;
    this.end = end;
    this.step = step;
  }

  next(): IteratorResult<number> {
    if (this.exhausted) return { value: undefined, done: true };

    const inBounds =
      this.step > 0 ? this.current < this.end : this.current > this.end;

    if (!inBounds) {
      this.exhausted = true;
      return { value: undefined, done: true };
    }

    const value = this.current;
    this.current += this.step;
    return { value, done: false };
  }

  // Called when a consumer stops early (break/return/destructuring).
  return(value?: any): IteratorResult<number> {
    this.exhausted = true;
    console.log("  [RangeIterator.return] closed early");
    return { value, done: true };
  }

  // Called if a consumer invokes iterator.throw(err).
  throw(err: any): IteratorResult<number> {
    this.exhausted = true;
    console.log("  [RangeIterator.throw] received:", err?.message ?? err);
    throw err; // re-throw so the caller sees it
  }
}

/** Make Range itself Iterable so it works with for…of / spread / destructuring. */
class Range implements Iterable<number> {
  constructor(
    private readonly start: number,
    private readonly end: number,
    private readonly step = 1,
  ) {}

  [Symbol.iterator](): Iterator<number> {
    return new RangeIterator(this.start, this.end, this.step);
  }
}

/* =========================================================================
 * 2. Iterable data structure: BST with in-order traversal
 * ========================================================================= */

class BSTNode<T> {
  constructor(
    public value: T,
    public left: BSTNode<T> | null = null,
    public right: BSTNode<T> | null = null,
  ) {}
}

class BinarySearchTree<T> implements Iterable<T> {
  root: BSTNode<T> | null = null;

  insert(value: T): void {
    const node = new BSTNode(value);
    if (!this.root) {
      this.root = node;
      return;
    }
    let cur = this.root;
    while (true) {
      if (value < cur.value) {
        if (!cur.left) {
          cur.left = node;
          return;
        }
        cur = cur.left;
      } else {
        if (!cur.right) {
          cur.right = node;
          return;
        }
        cur = cur.right;
      }
    }
  }

  *[Symbol.iterator](): Iterator<T> {
    // Recursive in-order via a stack to avoid call-stack limits.
    const stack: BSTNode<T>[] = [];
    let cur = this.root;
    while (cur || stack.length) {
      while (cur) {
        stack.push(cur);
        cur = cur.left;
      }
      cur = stack.pop()!;
      yield cur.value;
      cur = cur.right;
    }
  }
}

/* =========================================================================
 * 3. Generator helpers (IterableIterator, the idiomatic style)
 * ========================================================================= */

/** Infinite Fibonacci sequence (lazy, bounded only by consumer). */
function* fibonacci(): IterableIterator<number> {
  let a = 0;
  let b = 1;
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

/** Finite generator producing values optionally transformed. */
function* mapIterable<T, U>(
  source: Iterable<T>,
  fn: (x: T, i: number) => U,
): IterableIterator<U> {
  let i = 0;
  for (const x of source) yield fn(x, i++);
}

/* =========================================================================
 * 4. Async iterator / async generator: simulated paged fetch
 * ========================================================================= */

interface Page<T> {
  items: T[];
  nextCursor: number | null;
}

async function fetchPage(cursor: number): Promise<Page<number>> {
  await new Promise((r) => setTimeout(r, 20));
  const items = [cursor, cursor + 1, cursor + 2].filter((n) => n < 10);
  return { items, nextCursor: items.length ? cursor + 3 : null };
}

class PagedStream implements AsyncIterable<number> {
  async *[Symbol.asyncIterator](): AsyncIterator<number> {
    let cursor: number | null = 0;
    while (cursor !== null) {
      const page = await fetchPage(cursor);
      for (const item of page.items) yield item;
      cursor = page.nextCursor;
    }
  }
}

/* =========================================================================
 * 5. Type-safe inspection helper
 * ========================================================================= */

function describeResult<T>(r: IteratorResult<T>): string {
  return r.done ? `done (value=${String(r.value)})` : `value=${r.value}`;
}

/* =========================================================================
 * Demo / main
 * ========================================================================= */

async function main(): Promise<void> {
  console.log("=== 1. Manual Range ===");
  const range = new Range(0, 10, 3);
  console.log("spread:", [...range]);
  console.log("destructuring:", (() => {
    const [a, b, ...rest] = range; // new iterator each time because Iterable
    return { a, b, rest };
  })());

  const it = range[Symbol.iterator]();
  console.log("next x3:", it.next(), it.next(), it.next());
  console.log("return early:", it.return("bye"));
  try {
    // After exhaustion, throw() still runs our hook then re-throws.
    it.throw(new Error("boom"));
  } catch (e) {
    console.log("caught:", (e as Error).message);
  }

  console.log("\n=== 2. BST in-order ===");
  const bst = new BinarySearchTree<number>();
  for (const v of [5, 3, 7, 1, 4, 6, 9]) bst.insert(v);
  console.log("sorted:", [...bst]);

  // Early termination triggers generator's implicit return().
  let count = 0;
  for (const v of bst) {
    console.log("  visited", v);
    if (++count === 3) break;
  }

  console.log("\n=== 3. Generators ===");
  const fib = fibonacci();
  console.log("first 8 fib:", Array.from({ length: 8 }, () => fib.next().value));

  const doubled = mapIterable(new Range(1, 6), (x, i) => `${i}:${x * 2}`);
  console.log("mapped:", [...doubled]);

  console.log("\n=== 4. Async iterator ===");
  const stream = new PagedStream();
  const collected: number[] = [];
  for await (const n of stream) {
    collected.push(n);
    if (n === 5) break; // exercises async return()
  }
  console.log("collected (stopped at 5):", collected);

  console.log("\n=== 5. Manual next() loop ===");
  const manual = new Range(1, 4)[Symbol.iterator]();
  while (true) {
    const r = manual.next();
    console.log("  ", describeResult(r));
    if (r.done) break;
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

