### Core implementation: a `Range` with manual + generator iterators

```ts
// range.ts
export class Range implements Iterable<number> {
  constructor(
    private readonly start: number,
    private readonly end: number,   // exclusive
    private readonly step: number = 1
  ) {
    if (step === 0) throw new Error("step must be non-zero");
  }

  // --- Manual iterator implementation (explicit protocol) ---
  [Symbol.iterator](): Iterator<number> {
    let current = this.start;
    const { end, step } = this;
    const ascending = step > 0;

    return {
      next(): IteratorResult<number> {
        const finished = ascending
          ? current >= end
          : current <= end;

        if (finished) {
          // `value: undefined` is conventional when done; cast for typing.
          return { value: undefined as unknown as number, done: true };
        }

        const value = current;
        current += step;
        return { value, done: false };
      },

      // Optional: support early termination (break in for...of calls this).
      return(value?: any): IteratorResult<number> {
        current = ascending ? end : end; // mark exhausted
        return { value, done: true };
      },
    };
  }

  // --- Generator version (idiomatic, preferred) ---
  *values(): IterableIterator<number> {
    const ascending = this.step > 0;
    if (ascending) {
      for (let v = this.start; v < this.end; v += this.step) yield v;
    } else {
      for (let v = this.start; v > this.end; v += this.step) yield v;
    }
  }
}

// Re-export as default iterable via generator for ergonomics:
// (Range already implements Iterable via manual; here's a subclass showing generator-only)
export class RangeG implements Iterable<number> {
  constructor(private start: number, private end: number, private step = 1) {}
  *[Symbol.iterator](): IterableIterator<number> {
    const asc = this.step > 0;
    if (asc) for (let v = this.start; v < this.end; v += this.step) yield v;
    else for (let v = this.start; v > this.end; v += this.step) yield v;
  }
}
```

### Consumption examples

```ts
const r = new Range(0, 10, 2);

// 1. for...of
for (const n of r) console.log(n); // 0 2 4 6 8

// 2. spread
const arr = [...r]; // [0,2,4,6,8]

// 3. destructuring
const [a, b, ...rest] = r; // a=0 b=2 rest=[4,6,8]

// 4. Array.from with map
const doubled = Array.from(r, (x) => x * 2);

// 5. manual next()
const it = r[Symbol.iterator]();
console.log(it.next()); // { value: 0, done: false }
console.log(it.next()); // { value: 2, done: false }
```

### Advanced: a stateful iterator over an external resource

```ts
// paginated-fetch.ts — shows why manual iterators matter
export function paginatedIds(baseUrl: string): IterableIterator<number> {
  let page = 0;
  let buffer: number[] = [];
  let idx = 0;
  let done = false;

  return {
    next(): IteratorResult<number> {
      // refill buffer lazily
      if (idx >= buffer.length && !done) {
        // synchronous demo: pretend fetch is sync; real code would use async iterator
        buffer = Array.from({ length: 3 }, (_, i) => page * 3 + i);
        page++;
        idx = 0;
        if (page > 3) done = true;
      }
      if (idx >= buffer.length) return { value: undefined as any, done: true };
      return { value: buffer[idx++], done: false };
    },
  };
}
```

### Async iterators (brief)

For I/O-bound sequences, use `AsyncIterable` / `for await...of`:

```ts
async function* fetchPages(url: string): AsyncIterable<string> {
  let page = 1;
  while (true) {
    const res = await fetch(`${url}?page=${page++}`);
    if (!res.ok) break;
    const data = await res.json();
    if (!data.length) break;
    for (const item of data) yield item.name;
  }
}
// usage: for await (const name of fetchPages(url)) { ... }
```

