### `src/application/usecases/CreateUserUseCase.ts`

```ts
import { User } from "../../domain/entities/User";
import { IUserRepository } from "../../domain/repositories/IUserRepository";
import { CreateUserDto } from "../dto/CreateUserDto";

export class CreateUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly idGenerator: () => string
  ) {}

  async execute(dto: CreateUserDto): Promise<User> {
    const existing = await this.userRepository.findByEmail(dto.email);
    if (existing) {
      throw new Error("A user with this email already exists");
    }

    const user = User.create(this.idGenerator(), dto.email, dto.name);
    return this.userRepository.save(user);
  }
}
```

### `src/application/usecases/GetUserUseCase.ts`

```ts
import { User } from "../../domain/entities/User";
import { IUserRepository } from "../../domain/repositories/IUserRepository";

export class GetUserUseCase {
  constructor(private readonly userRepository: IUserRepository) {}

  async byId(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) throw new Error("User not found");
    return user;
  }

  async all(): Promise<User[]> {
    return this.userRepository.findAll();
  }
}
```

### `src/application/usecases/DeleteUserUseCase.ts`

```ts
import { IUserRepository } from "../../domain/repositories/IUserRepository";

export class DeleteUserUseCase {
  constructor(private readonly userRepository: IUserRepository) {}

  async execute(id: string): Promise<void> {
    const user = await this.userRepository.findById(id);
    if (!user) throw new Error("User not found");
    await this.userRepository.delete(id);
  }
}
```

## Infrastructure layer (implements domain interfaces)

### `src/infrastructure/repositories/InMemoryUserRepository.ts`

```ts
import { User } from "../../domain/entities/User";
import { IUserRepository } from "../../domain/repositories/IUserRepository";

export class InMemoryUserRepository implements IUserRepository {
  private readonly store = new Map<string, User>();

  async save(user: User): Promise<User> {
    this.store.set(user.id, user);
    return user;
  }

  async findById(id: string): Promise<User | null> {
    return this.store.get(id) ?? null;
  }

  async findByEmail(email: string): Promise<User | null> {
    const normalized = email.trim().toLowerCase();
    for (const user of this.store.values()) {
      if (user.email === normalized) return user;
    }
    return null;
  }

  async findAll(): Promise<User[]> {
    return [...this.store.values()];
  }

  async delete(id: string): Promise<void> {
    this.store.delete(id);
  }
}
```

> To swap to PostgreSQL/Mongo, implement `IUserRepository` in a new infrastructure class—no application/domain code changes.

## Presentation layer (HTTP)

### `src/presentation/controllers/UserController.ts`

```ts
import { Request, Response } from "express";
import { CreateUserUseCase } from "../../application/usecases/CreateUserUseCase";
import { GetUserUseCase } from "../../application/usecases/GetUserUseCase";
import { DeleteUserUseCase } from "../../application/usecases/DeleteUserUseCase";
import { CreateUserDto } from "../../application/dto/CreateUserDto";

export class UserController {
  constructor(
    private readonly createUser: CreateUserUseCase,
    private readonly getUser: GetUserUseCase,
    private readonly deleteUser: DeleteUserUseCase
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    try {
      const dto: CreateUserDto = {
        email: String(req.body?.email ?? ""),
        name: String(req.body?.name ?? ""),
      };
      const user = await this.createUser.execute(dto);
      res.status(201).json(user);
    } catch (err) {
      res.status(400).json({ error: (err as Error).message });
    }
  };

  getById = async (req: Request, res: Response): Promise<void> => {
    try {
      const user = await this.getUser.byId(req.params.id);
      res.json(user);
    } catch (err) {
      res.status(404).json({ error: (err as Error).message });
    }
  };

  list = async (_req: Request, res: Response): Promise<void> => {
    const users = await this.getUser.all();
    res.json(users);
  };

  remove = async (req: Request, res: Response): Promise<void> => {
    try {
      await this.deleteUser.execute(req.params.id);
      res.status(204).send();
    } catch (err) {
      res.status(404).json({ error: (err as Error).message });
    }
  };
}
```

### `src/presentation/routes/userRoutes.ts`

```ts
import { Router } from "express";
import { UserController } from "../controllers/UserController";

export function userRoutes(controller: UserController): Router {
  const router = Router();
  router.post("/users", controller.create);
  router.get("/users", controller.list);
  router.get("/users/:id", controller.getById);
  router.delete("/users/:id", controller.remove);
  return router;
}
```

