## Core implementation (clean, commented)

### 1. Domain layer — pure, framework-free

```ts
// domain/user.ts

export class User {
  constructor(
    public readonly id: string,
    public readonly email: string,
    public readonly name: string,
  ) {
    if (!email.includes("@")) throw new Error("Invalid email");
  }
}

// Port (interface) defined by the domain, implemented by infrastructure.
export interface UserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<void>;
}

export class DuplicateEmailError extends Error {
  constructor(email: string) {
    super(`Email already registered: ${email}`);
    this.name = "DuplicateEmailError";
  }
}
```

### 2. Application layer — orchestration + DTOs

```ts
// application/register-user.ts

import { User, UserRepository, DuplicateEmailError } from "../domain/user";

export interface RegisterUserInput {
  email: string;
  name: string;
}

export class RegisterUserUseCase {
  constructor(private readonly users: UserRepository) {}

  async execute(input: RegisterUserInput): Promise<User> {
    // Application rule: normalize before lookup.
    const email = input.email.trim().toLowerCase();

    const existing = await this.users.findByEmail(email);
    if (existing) throw new DuplicateEmailError(email);

    // Entity enforces its own invariants (domain rule).
    const user = new User(crypto.randomUUID(), email, input.name.trim());

    await this.users.save(user);
    return user;
  }
}
```

### 3. Infrastructure layer — concrete adapter

```ts
// infrastructure/in-memory-user-repository.ts

import { User, UserRepository } from "../domain/user";

export class InMemoryUserRepository implements UserRepository {
  private readonly store = new Map<string, User>();

  async findByEmail(email: string): Promise<User | null> {
    for (const u of this.store.values()) {
      if (u.email === email) return u;
    }
    return null;
  }

  async save(user: User): Promise<void> {
    this.store.set(user.id, user);
  }
}
```

### 4. Presentation layer — HTTP-ish controller (framework-agnostic)

```ts
// presentation/user-controller.ts

import { RegisterUserUseCase, RegisterUserInput } from "../application/register-user";
import { DuplicateEmailError } from "../domain/user";

export interface HttpRequest {
  body: unknown;
}

export interface HttpResponse {
  status: number;
  body: unknown;
}

export class UserController {
  constructor(private readonly registerUser: RegisterUserUseCase) {}

  async register(req: HttpRequest): Promise<HttpResponse> {
    const input = req.body as Partial<RegisterUserInput>;

    if (typeof input?.email !== "string" || typeof input?.name !== "string") {
      return { status: 400, body: { error: "email and name are required strings" } };
    }

    try {
      const user = await this.registerUser.execute({ email: input.email, name: input.name });
      return { status: 201, body: { id: user.id, email: user.email, name: user.name } };
    } catch (err) {
      if (err instanceof DuplicateEmailError) {
        return { status: 409, body: { error: err.message } };
      }
      // Unknown errors are not leaked; infra/logging would handle details.
      return { status: 500, body: { error: "Internal server error" } };
    }
  }
}
```

### 5. Composition root — wiring (the only place that knows concrete classes)

```ts
// main.ts

import { InMemoryUserRepository } from "./infrastructure/in-memory-user-repository";
import { RegisterUserUseCase } from "./application/register-user";
import { UserController } from "./presentation/user-controller";

// Build graph: infrastructure -> application -> presentation
const repo = new InMemoryUserRepository();
const useCase = new RegisterUserUseCase(repo);
const controller = new UserController(useCase);

// Example usage (could be Express/Fastify handler instead)
controller.register({ body: { email: "Ada@Example.com", name: "Ada" } })
  .then((res) => console.log(res));
```

