## 12. Testing seams and over-mocking

**Risk:** Tests mock repositories but not transaction behavior; false positives.

**Fix:** provide in-memory implementations of ports; test service with real domain logic.

```ts
// tests/InMemoryOrderRepository.ts
export class InMemoryOrderRepository implements OrderRepository {
  private store = new Map<string, Order>();
  async save(o: Order, _tx?: TxContext) { this.store.set(o.id, o); }
  async findById(id: string) { return this.store.get(id) ?? null; }
}

// test
const repo = new InMemoryOrderRepository();
const svc = new OrderService(new FakeInventoryPort(), repo);
await svc.placeOrder({ sku: 'A', qty: 2 });
expect(await repo.findById(/*...*/)).not.toBeNull();
```

