## Quick checklist

- Dependencies point inward; outer layers depend on inner abstractions.
- No ORM/DB types in domain or application.
- Every multi-write use case runs in a transaction.
- Domain invariants throw domain errors; infra translates; presentation maps to HTTP.
- Aggregates carry version for concurrency.
- DTOs are the only types crossing the API boundary.
- Repositories return fully loaded aggregates.
- Authorization and validation exist in service/domain, not just UI.
- Async side effects go through outbox or explicit error handling.

If you want, I can tailor this to a specific stack (NestJS, Express, tRPC, Prisma, TypeORM) or to a concrete domain (orders, users, payments).

Below is a complete, runnable TypeScript file that implements three common forms of lazy evaluation:

1. **`Lazy<T>`** – a thunk that is evaluated at most once (call-by-need), with error caching and `map`/`flatMap`.
2. **`MemoSeq<T>`** – a memoized lazy sequence (stream) with `map`, `filter`, `take`, `skip`, and infinite generators.
3. **`memoize`** – function-level memoization.

You can save it as `lazy.ts` and run it with:

```bash
npx ts-node lazy.ts
# or
tsc lazy.ts && node lazy.js
```

```ts
// lazy.ts
// Run: npx ts-node lazy.ts   (or: tsc lazy.ts && node lazy.js)

/* ============================================================
 * 1. Lazy single value (call-by-need, evaluated at most once)
 * ============================================================ */

type LazyState<T> =
  | { kind: "unevaluated" }
  | { kind: "value"; value: T }
  | { kind: "error"; error: unknown };

class Lazy<T> {
  private state: LazyState<T> = { kind: "unevaluated" };

  constructor(private readonly factory: () => T) {}

  /** Force evaluation (cached). */
  get value(): T {
    if (this.state.kind === "unevaluated") {
      try {
        const v = this.factory();
        this.state = { kind: "value", value: v };
        return v;
      } catch (e) {
        // Cache the error too, so a failing thunk isn't retried forever.
        this.state = { kind: "error", error: e };
        throw e;
      }
    }
    if (this.state.kind === "error") throw this.state.error;
    return this.state.value;
  }

  get evaluated(): boolean {
    return this.state.kind !== "unevaluated";
  }

  map<U>(fn: (x: T) => U): Lazy<U> {
    return new Lazy(() => fn(this.value));
  }

  flatMap<U>(fn: (x: T) => Lazy<U>): Lazy<U> {
    return new Lazy(() => fn(this.value).value);
  }
}

/* ============================================================
 * 2. Lazy, memoized sequences (streams)
 * ============================================================ */

function* mapGen<T, U>(src: Iterable<T>, fn: (x: T) => U): Generator<U> {
  for (const x of src) yield fn(x);
}

function* filterGen<T>(src: Iterable<T>, pred: (x: T) => boolean): Generator<T> {
  for (const x of src) if (pred(x)) yield x;
}

function* takeGen<T>(src: Iterable<T>, n: number): Generator<T> {
  let i = 0;
  for (const x of src) {
    if (i++ >= n) return;
    yield x;
  }
}

function* skipGen<T>(src: Iterable<T>, n: number): Generator<T> {
  let i = 0;
  for (const x of src) {
    if (i++ < n) continue;
    yield x;
  }
}

function* rangeGen(start: number, end?: number, step = 1): Generator<number> {
  if (end === undefined) {
    for (let x = start; ; x += step) yield x;
  } else {
    const cond = step > 0 ? (x: number) => x < end : (x: number) => x > end;
    for (let x = start; cond(x); x += step) yield x;
  }
}

class MemoSeq<T> implements Iterable<T> {
  private cache: T[] = [];
  private done = false;
  private iterator: Iterator<T> | null = null;

  constructor(private readonly factory: () => Iterator<T>) {}

  static from<T>(iterable: Iterable<T>): MemoSeq<T> {
    return new MemoSeq<T>(() => iterable[Symbol.iterator]());
  }

  static range(start = 0, end?: number, step = 1): MemoSeq<number> {
    return new MemoSeq<number>(() => rangeGen(start, end, step));
  }

  static infinite(start = 0, step = 1): MemoSeq<number> {
    return new MemoSeq<number>(() => rangeGen(start, undefined, step));
  }

  /** Memoized iteration: each element is computed at most once. */
  *[Symbol.iterator](): Generator<T> {
    let i = 0;
    while (true) {
      if (i < this.cache.length) {
        yield this.cache[i++];
        continue;
      }
      if (this.done) return;
      if (!this.iterator) this.iterator = this.factory();
      const step = this.iterator.next();
      if (step.done) {
        this.done = true;
        return;
      }
      this.cache.push(step.value);
      yield step.value;
      i++;
    }
  }

  toArray(): T[] {
    return [...this];
  }

  map<U>(fn: (x: T) => U): MemoSeq<U> {
    const src = this;
    return new MemoSeq<U>(() => mapGen(src[Symbol.iterator](), fn));
  }

  filter(pred: (x: T) => boolean): MemoSeq<T> {
    const src = this;
    return new MemoSeq<T>(() => filterGen(src[Symbol.iterator](), pred));
  }

  take(n: number): MemoSeq<T> {
    const src = this;
    return new MemoSeq<T>(() => takeGen(src[Symbol.iterator](), n));
  }

  skip(n: number): MemoSeq<T> {
    const src = this;
    return new MemoSeq<T>(() => skipGen(src[Symbol.iterator](), n));
  }

  reduce<U>(fn: (acc: U, x: T) => U, init: U): U {
    let acc = init;
    for (const x of this) acc = fn(acc, x);
    return acc;
  }
}

/* ============================================================
 * 3. Function memoization
 * ============================================================ */

function memoize<Args extends unknown[], R>(
  fn: (...args: Args) => R,
): (...args: Args) => R {
  const cache = new Map<string, R>();
  return (...args: Args): R => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key)!;
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

/* ============================================================
 * 4. Infinite generators used in demos
 * ============================================================ */

function* fibonacciGen(): Generator<number> {
  let a = 0;
  let b = 1;
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

function* primesGen(): Generator<number> {
  yield 2;
  let n = 3;
  while (true) {
    let isPrime = true;
    for (let d = 3; d * d <= n; d += 2) {
      if (n % d === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) yield n;
    n += 2;
  }
}

/* ============================================================
 * 5. Demo
 * ============================================================ */

function main(): void {
  console.log("=== Lazy single value ===");
  let calls = 0;
  const expensive = new Lazy(() => {
    calls++;
    // Simulate an expensive computation.
    return 6 * 7;
  });

  console.log("evaluated before access?", expensive.evaluated); // false
  console.log("value:", expensive.value);                      // 42, calls=1
  console.log("value again:", expensive.value);                // 42, calls=1 (cached)
  console.log("calls:", calls);

  const doubled = expensive.map((x) => x * 2);
  console.log("doubled:", doubled.value); // 84

  // Lazy values compose without forcing intermediate results early.
  const pipeline = new Lazy(() => 10)
    .map((x) => x + 5)
    .flatMap((x) => new Lazy(() => x * 3));
  console.log("pipeline:", pipeline.value); // 45

  console.log("\n=== Lazy sequences ===");
  const first10Fibs = MemoSeq.from(fibonacciGen()).take(10).toArray();
  console.log("first 10 fibs:", first10Fibs);

  // Infinite stream: filter primes, square them, take 5.
  const squaredPrimes = MemoSeq.from(primesGen())
    .filter((p) => p % 3 === 1)
    .map((p) => p * p)
    .take(5)
    .toArray();
  console.log("squared primes (p%3===1), first 5:", squaredPrimes);

  // Memoization proof: element factory runs once even on re-iteration.
  let produced = 0;
  const seq = new MemoSeq<number>(() => {
    function* g() {
      while (true) {
        produced++;
        yield produced;
      }
    }
    return g();
  });

  console.log("produced before consumption:", produced); // 0
  console.log("first 3:", seq.take(3).toArray());       // [1,2,3]
  console.log("produced after first take(3):", produced); // 3
  // Re-iterating the (memoized) source reuses cached elements.
  console.log("re-read first 2:", [...seq].slice(0, 2)); // [1,2], no new production
  console.log("produced after re-read:", produced);       // still 3

  const sumFirst100 = MemoSeq.infinite(1).take(100).reduce((a, b) => a + b, 0);
  console.log("sum 1..100:", sumFirst100); // 5050

  console.log("\n=== Function memoization ===");
  const fib = memoize((n: number): number => {
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
  });
  console.log("fib(35):", fib(35)); // 9227465 (fast thanks to memoization)

  console.log("\nDone.");
}

main();
```

### Key ideas illustrated

- **`Lazy<T>`** wraps a thunk `() => T`. The factory runs only on first `.value` access; the result (or thrown error) is cached, so repeated access is O(1) and side effects happen once.
- **`MemoSeq<T>`** is a memoized pull-based stream. Operations like `map`/`filter`/`take` build new lazy sequences without consuming the source; consumption happens only when you iterate (`toArray`, `reduce`, spread, etc.). Once an element is produced it is cached, so re-iterating or re-slicing does not recompute.
- **Infinite streams** (`fibonacciGen`, `primesGen`, `MemoSeq.infinite`) work because evaluation is demand-driven: `take(n)` stops the generator after `n` items.
- **`memoize`** caches by a JSON key of arguments, turning exponential recursion (naïve Fibonacci) into linear time.

If you want, I can extend this with async lazy values (`Lazy<Promise<T>>` / async generators), parallel evaluation, or a `force`/`thunk` interop layer.

## Idea

**Lazy evaluation** means an expression is not computed until its value is actually needed. JavaScript/TypeScript evaluate arguments eagerly by default, so “laziness” is a *pattern* you build with functions, generators, or proxies—not a language keyword.

Benefits:
- Avoid expensive work when the result isn’t used.
- Work with (conceptually) infinite data.
- Defer side effects (I/O, heavy parsing) until the moment they’re needed.
- Enable short-circuit composition (`a && b`, optional chaining already lazily skips).

---

## 1. Thunks (the simplest form)

Wrap a computation in a zero-arg function; call it only when needed.

```ts
type Thunk<T> = () => T;

const heavy = (): number => {
  console.log("computing...");
  return 42 * 42;
};

const lazy: Thunk<number> = () => heavy();

// Nothing computed yet
if (Math.random() > 0.5) {
  console.log(lazy()); // computed here
}
```

**Typing tip:** Prefer `() => T` over `Function` for safety.

---

## 2. Lazy properties via getters

Expose a value that is computed on first access and cached.

```ts
class Config {
  private _parsed?: Record<string, string>;

  get parsed(): Record<string, string> {
    if (!this._parsed) {
      console.log("parsing once");
      this._parsed = Object.fromEntries(
        "a=1\nb=2".split("\n").map((l) => l.split("=") as [string, string])
      );
    }
    return this._parsed;
  }
}

const c = new Config();
// parsed not computed yet
console.log(c.parsed.a); // computes now
console.log(c.parsed.b); // cached
```

---

## 3. Lazy sequences with generators

Generators (`function*`) produce values on demand—ideal for infinite or large streams.

```ts
function* naturals(): Generator<number> {
  let n = 0;
  while (true) yield n++;
}

function* take<T>(g: Generator<T>, n: number): Generator<T> {
  for (let i = 0; i < n; i++) {
    const { value, done } = g.next();
    if (done) break;
    yield value;
  }
}

// Only 5 values are ever produced
for (const x of take(naturals(), 5)) {
  console.log(x);
}
```

---

## 4. Lazy “and” / composition (short-circuiting)

TS/JS already short-circuit `&&`, `||`, `??`, and `?.`. Build pipelines that stop early.

```ts
const isReady = () => false;
const loadHeavy = () => {
  console.log("LOADING");
  return { data: 1 };
};

// loadHeavy never runs
const result = isReady() && loadHeavy();
console.log(result); // false
```

For arrays, prefer lazy iteration over eager `.map().filter()` chains when data is large:

```ts
function* map<T, U>(src: Iterable<T>, f: (x: T) => U): Generator<U> {
  for (const x of src) yield f(x);
}
function* filter<T>(src: Iterable<T>, p: (x: T) => boolean): Generator<T> {
  for (const x of src) if (p(x)) yield x;
}

const pipeline = filter(map([1, 2, 3, 4], (x) => x * 2), (x) => x > 4);
console.log([...pipeline]); // [6, 8] — stops conceptually early per element
```

---

## 5. Memoized lazy initialization (once)

Combine a thunk with a cache so the expensive work happens at most once, on first use.

```ts
function lazyOnce<T>(factory: () => T): () => T {
  let cached: T | undefined;
  let done = false;
  return () => {
    if (!done) {
      cached = factory();
      done = true;
    }
    return cached as T;
  };
}

const getDb = lazyOnce(() => {
  console.log("connecting...");
  return { query: (s: string) => s };
});

// connect happens only on first call
getDb().query("SELECT 1");
getDb().query("SELECT 2");
```

---

## 6. Lazy object access with `Proxy`

Useful for deferring property computation until accessed (e.g., feature flags, config).

```ts
function lazyObject<T extends object>(factory: (key: string) => unknown): T {
  const cache = new Map<string, unknown>();
  return new Proxy({} as T, {
    get(_target, prop: string) {
      if (!cache.has(prop)) cache.set(prop, factory(prop));
      return cache.get(prop);
    },
  });
}

const flags = lazyObject((k) => {
  console.log("evaluating", k);
  return k === "newUI";
});

console.log(flags.newUI); // evaluates
console.log(flags.newUI); // cached
```

---

## Typical use cases

| Use case | Pattern |
|---|---|
| Expensive derived value | getter + cache |
| Infinite/huge collections | generators |
| Conditional heavy I/O | thunk + `if` |
| One-time singleton init | `lazyOnce` |
| Feature flags / dynamic config | `Proxy` |
| React/Vue rendering pipelines | memoized selectors, lazy components (`React.lazy`) |

---

## Caveats

- **Arguments are eager:** `foo(expensive())` always evaluates `expensive()` before `foo` runs. Pass a thunk instead: `foo(() => expensive())`.
- **Side effects & ordering:** Laziness can change *when* (or *if*) side effects occur—keep factories pure when possible.
- **Error timing:** Errors throw on first *use*, not on definition—handle at consumption site.
- **Memory:** Cached lazy values (getters/memo) retain references; clear them if needed.
- **Type narrowing:** TS narrows eagerly; a lazy thunk’s type won’t refine until called.

### Quick decision guide
- Need “compute on first read + cache” → **getter** or **lazyOnce**.
- Need “stream of values, possibly infinite” → **generator**.
- Need “defer until branch taken” → **thunk (`() => T`)**.
- Need “defer per-key access” → **Proxy**.

A common lazy-evaluation mistake is creating deferred functions inside a loop and expecting them to “remember” the value of the loop variable at the time they were created. They do not; they remember the variable binding and read its current value only when called.

### Mistaken version

```ts
type LazyNumber = () => number;

function makeLazyValues(): LazyNumber[] {
  const result: LazyNumber[] = [];

  // `var` is function-scoped, so all closures share one `i`.
  for (var i = 0; i < 3; i++) {
    result.push(() => i * 10);
  }

  return result;
}

const lazyValues = makeLazyValues();

// The functions are only evaluated now.
console.log(lazyValues.map(fn => fn())); // [30, 30, 30], not [0, 10, 20]
```

### Corrected version

```ts
type LazyNumber = () => number;

function makeLazyValues(): LazyNumber[] {
  const result: LazyNumber[] = [];

  // `let` creates a fresh binding for each loop iteration,
  // so each closure captures its own `i`.
  for (let i = 0; i < 3; i++) {
    result.push(() => i * 10);
  }

  return result;
}

const lazyValues = makeLazyValues();

console.log(lazyValues.map(fn => fn())); // [0, 10, 20]
```

### What was wrong

The expression `() => i * 10` is **not** evaluated when `push` runs. That is the point of lazy evaluation: the arrow function stores the computation and defers it. But the closure does not capture the *value* of `i` at creation time; it captures the *variable binding*. With `var`, there is only one function-scoped `i`, and by the time the functions are finally called, that single variable has reached its final value, `3`.

### Why `let` fixes it

`let` in a `for` loop gives each iteration its own lexical binding. Therefore, each arrow function closes over a distinct `i`, whose value remains `0`, `1`, and `2` respectively.

### Alternative fix: capture the value eagerly

If you specifically want each lazy function to freeze the value at creation time, pass it as a parameter or use an immediately invoked function:

```ts
for (var i = 0; i < 3; i++) {
  const captured = i;
  result.push(() => captured * 10);
}
```

or:

```ts
for (var i = 0; i < 3; i++) {
  result.push(((value: number) => () => value * 10)(i));
}
```

Both versions evaluate `i` while the loop is running and store that value in a new binding, so the deferred function later returns the expected number.

# Common Pitfalls with Lazy Evaluation in TypeScript

Lazy evaluation in TypeScript usually appears as **lazy properties/getters**, **thunks**, **memoized functions**, **generators**, or **dynamic imports**. The pitfalls below are the ones that show up most often in real code.

---

## 1. Recomputing on every access (no memoization)

A getter looks like a field, but unless you cache the result, it runs every time.

```ts
class Report {
  get expensiveSummary(): string {
    console.log("computing...");
    return heavyCalculation();
  }
}

const r = new Report();
r.expensiveSummary; // logs "computing..."
r.expensiveSummary; // logs again
```

**Fix:** cache the value in a private field.

```ts
class Report {
  private _summary?: string;

  get expensiveSummary(): string {
    if (this._summary === undefined) {
      console.log("computing...");
      this._summary = heavyCalculation();
    }
    return this._summary;
  }
}
```

---

## 2. Side effects in lazy initializers

Lazy code often hides side effects, making execution order surprising.

```ts
let auditLog: string[] = [];

class User {
  get permissions(): string[] {
    auditLog.push("permissions read"); // side effect
    return ["read", "write"];
  }
}

const u = new User();
console.log(auditLog); // []
u.permissions;
console.log(auditLog); // ["permissions read"]
```

**Pitfall:** Callers do not expect reading a property to mutate global state or trigger I/O.

**Fix:** Keep lazy computations pure; move side effects to explicit methods.

---

## 3. Async lazy evaluation races and unhandled rejections

Caching a `Promise` is the right idea, but naive implementations can start multiple requests or lose errors.

```ts
class ApiClient {
  private _data?: Promise<Data>;

  get data(): Promise<Data> {
    if (!this._data) {
      this._data = fetchData(); // may throw synchronously or reject
    }
    return this._data;
  }
}
```

**Pitfalls:**
- If `fetchData()` throws synchronously, `_data` stays `undefined`, so the next access retries. That may be desired, but often is not.
- If the promise rejects, it stays cached forever unless you reset it.

**Better pattern:**

```ts
class ApiClient {
  private _data?: Promise<Data>;

  async getData(): Promise<Data> {
    if (!this._data) {
      this._data = fetchData().catch((err) => {
        this._data = undefined; // allow retry
        throw err;
      });
    }
    return this._data;
  }
}
```

---

## 4. Memoization key bugs

Memoizing functions with arguments is easy to get wrong.

```ts
function memoize<A extends any[], R>(fn: (...args: A) => R) {
  const cache = new Map<string, R>();
  return (...args: A): R => {
    const key = JSON.stringify(args); // fragile
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key)!;
  };
}
```

**Pitfalls:**
- `JSON.stringify` drops `undefined`, functions, symbols, and `BigInt`.
- Object arguments are compared by serialized shape, not identity.
- `this` is lost unless you bind it.

**Safer for single-argument object identity:**

```ts
function memoizeByReference<TArg, TResult>(fn: (arg: TArg) => TResult) {
  const cache = new WeakMap<object, TResult>();
  return (arg: TArg): TResult => {
    if (typeof arg !== "object" || arg === null) {
      return fn(arg); // no caching for primitives unless you add a Map
    }
    if (!cache.has(arg as object)) {
      cache.set(arg as object, fn(arg));
    }
    return cache.get(arg as object)!;
  };
}
```

---

## 5. Mutating cached results

If a lazy value returns a mutable object, callers can corrupt the cache.

```ts
const getItems = (() => {
  let cached: number[] | undefined;
  return () => {
    if (!cached) cached = [1, 2, 3];
    return cached;
  };
})();

const items = getItems();
items.push(999);

console.log(getItems()); // [1, 2, 3, 999] — cache corrupted
```

**Fix:** return a copy or freeze the result.

```ts
return Object.freeze([...cached]);
// or
return cached.slice();
```

---

## 6. Memory leaks through closures

Lazy closures often capture large objects longer than necessary.

```ts
function makeLazyLength() {
  const huge = new Array(1_000_000).fill("x");
  return () => huge.length; // `huge` stays alive forever
}

const fn = makeLazyLength();
console.log(fn());
```

Even after the result is no longer needed, the closure keeps `huge` reachable.

**Fix:** compute eagerly if the large input is temporary, or release references.

```ts
function makeLazyLength() {
  const huge = new Array(1_000_000).fill("x");
  const length = huge.length;
  // `huge` can now be garbage collected
  return () => length;
}
```

---

## 7. Generators are single-use and stateful

Lazy generators look like arrays but are not reusable.

```ts
function* numbers() {
  console.log("start");
  yield 1;
  yield 2;
}

const g = numbers();
console.log([...g]); // [1, 2], logs "start"
console.log([...g]); // [] — already exhausted
```

**Pitfalls:**
- Iterating twice yields nothing the second time.
- Side effects inside the generator run only as far as iteration goes.
- Partial iteration leaves the generator suspended and may retain closures.

**Fix:** If you need reuse, materialize with `Array.from` or create a factory.

```ts
const makeNumbers = () => function* () {
  yield 1;
  yield 2;
};

const a = [...makeNumbers()()];
const b = [...makeNumbers()()];
```

---

## 8. `this` binding in lazy class members

Lazy getters depend on `this`. Passing them as callbacks breaks that binding.

```ts
class Counter {
  count = 0;
  get next(): number {
    return ++this.count;
  }
}

const c = new Counter();
const getter = c.next; // Error: getter is not a function? Actually property access already evaluated
// More common:
const read = c.next; // number, not a function
```

A more realistic pitfall is extracting a lazy method:

```ts
class Service {
  private cache?: string;
  load = () => {
    if (!this.cache) this.cache = expensive();
    return this.cache;
  };
}

const s = new Service();
const load = s.load;
load(); // works because arrow captures this
// But if it were a normal method:
// const load = s.load; load(); // this is undefined
```

**Fix:** Use arrow functions for lazy callbacks, or bind explicitly.

---

## 9. Circular dependencies with lazy imports

Dynamic imports can hide circular dependency problems until runtime.

```ts
// a.ts
export async function getB() {
  const { B } = await import("./b");
  return new B();
}

// b.ts
import { getA } from "./a";
export class B {
  a = getA(); // may be undefined or circular
}
```

**Pitfalls:**
- Lazy imports delay errors, making them harder to trace.
- If modules are evaluated partially, exported bindings may be `undefined`.

**Fix:** Keep dependency graphs acyclic; use explicit initialization functions rather than top-level side effects.

---

## 10. Serialization and enumerability surprises

Lazy getters are often non-enumerable by default in classes, so they do not serialize.

```ts
class Person {
  constructor(public first: string, public last: string) {}
  get fullName(): string {
    return `${this.first} ${this.last}`;
  }
}

console.log(JSON.stringify(new Person("Ada", "Lovelace")));
// {"first":"Ada","last":"Lovelace"} — fullName is missing
```

If you define an own enumerable getter, it may serialize as a value, but the getter itself is not a plain data property.

**Fix:** Add a `toJSON()` method or explicitly include computed fields.

```ts
toJSON() {
  return { first: this.first, last: this.last, fullName: this.fullName };
}
```

---

## 11. Error timing and stack traces

Lazy evaluation moves failures from construction time to access time.

```ts
class Config {
  get databaseUrl(): string {
    if (!process.env.DB_URL) throw new Error("DB_URL missing");
    return process.env.DB_URL;
  }
}

const cfg = new Config(); // no error here
// ... much later ...
connect(cfg.databaseUrl); // error thrown here
```

**Pitfall:** Stack traces point to the access site, not where the object was created, making debugging harder.

**Fix:** Validate eagerly for required configuration, or wrap lazy access in a clear error boundary.

---

## 12. Strict null checks with “lazy optional” values

TypeScript cannot know that a lazy field has been initialized after first access.

```ts
class Cache {
  private _value?: string;

  get value(): string {
    if (!this._value) this._value = compute();
    return this._value; // TS may complain if not narrowed well
  }
}
```

Usually this compiles, but with more complex control flow you may need a non-null assertion or a definite assignment pattern.

```ts
get value(): string {
  if (this._value === undefined) {
    this._value = compute();
  }
  return this._value!; // or refactor to a helper
}
```

---

## Summary checklist

- Memoize if the computation is expensive or has side effects.
- Treat lazy results as immutable, or clone/freeze them.
- Cache promises for async lazy values and reset on failure.
- Avoid capturing large objects in long-lived closures.
- Remember generators are single-use.
- Watch `this` binding when passing lazy accessors as callbacks.
- Do not assume lazy getters serialize automatically.
- Validate required values eagerly when failure should happen early.
- Keep lazy computations pure whenever possible.

## Exercise

Implement a **lazy numeric pipeline** in TypeScript:

1. Start with an **infinite** sequence of integers beginning at `1`.
2. Keep only even numbers.
3. Square each kept number.
4. Take only the first `5` values.
5. Sum them.

The constraint is that the infinite sequence must never be materialized as an array, and no value should be computed until it is actually needed by the final reduction.

---

## Step-by-step solution

### Step 1: Understand lazy evaluation in TypeScript

TypeScript has two common lazy-evaluation patterns:

1. **Deferred single values** using thunks:

```ts
const lazyValue = () => expensiveComputation();
```

The computation runs only when `lazyValue()` is called.

2. **Lazy collections** using generators:

```ts
function* infiniteNumbers() {
  let n = 1;
  while (true) yield n++;
}
```

A generator does not run its body until iteration starts, and it produces one value at a time.

For this exercise, generators are the natural fit because we need lazy sequences.

---

### Step 2: Create an infinite lazy range

```ts
function* range(start = 0, step = 1): Generator<number> {
  for (let n = start; ; n += step) {
    yield n;
  }
}
```

This never terminates by itself. It is safe only when combined with a limiting operation such as `take`.

---

### Step 3: Add lazy combinators

Each combinator is also a generator, so it pulls values from its source only as needed.

```ts
function* filter<T>(
  source: Iterable<T>,
  predicate: (value: T, index: number) => boolean
): Generator<T> {
  let index = 0;

  for (const value of source) {
    if (predicate(value, index)) {
      yield value;
    }
    index++;
  }
}

function* map<T, U>(
  source: Iterable<T>,
  mapper: (value: T, index: number) => U
): Generator<U> {
  let index = 0;

  for (const value of source) {
    yield mapper(value, index++);
  }
}

function* take<T>(
  source: Iterable<T>,
  count: number
): Generator<T> {
  if (count <= 0) return;

  let taken = 0;

  for (const value of source) {
    yield value;
    taken++;

    if (taken >= count) {
      return;
    }
  }
}
```

Key point: `take` stops iteration early. Because generators are lazy, stopping `take` also stops upstream generators from producing more values.

---

### Step 4: Add a consuming reduction

```ts
function reduce<T, U>(
  source: Iterable<T>,
  reducer: (accumulator: U, value: T, index: number) => U,
  initial: U
): U {
  let accumulator = initial;
  let index = 0;

  for (const value of source) {
    accumulator = reducer(accumulator, value, index++);
  }

  return accumulator;
}
```

This is the only operation that eagerly consumes the pipeline, and because of `take(5)`, it consumes exactly five squared even numbers.

---

### Step 5: Solve the exercise

```ts
const result = reduce(
  take(
    map(
      filter(range(1), n => n % 2 === 0),
      n => n * n
    ),
    5
  ),
  (sum, value) => sum + value,
  0
);

console.log(result); // 220
```

Calculation:

```text
Even numbers: 2, 4, 6, 8, 10
Squares:      4, 16, 36, 64, 100
Sum:          220
```

Only the first ten integers are inspected, and only five squared values are produced. The infinite tail of `range(1)` is never evaluated.

---

## Complete TypeScript solution

```ts
// lazy.ts

export function* range(start = 0, step = 1): Generator<number> {
  for (let n = start; ; n += step) {
    yield n;
  }
}

export function* filter<T>(
  source: Iterable<T>,
  predicate: (value: T, index: number) => boolean
): Generator<T> {
  let index = 0;

  for (const value of source) {
    if (predicate(value, index)) {
      yield value;
    }
    index++;
  }
}

export function* map<T, U>(
  source: Iterable<T>,
  mapper: (value: T, index: number) => U
): Generator<U> {
  let index = 0;

  for (const value of source) {
    yield mapper(value, index++);
  }
}

export function* take<T>(
  source: Iterable<T>,
  count: number
): Generator<T> {
  if (count <= 0) return;

  let taken = 0;

  for (const value of source) {
    yield value;
    taken++;

    if (taken >= count) {
      return;
    }
  }
}

export function reduce<T, U>(
  source: Iterable<T>,
  reducer: (accumulator: U, value: T, index: number) => U,
  initial: U
): U {
  let accumulator = initial;
  let index = 0;

  for (const value of source) {
    accumulator = reducer(accumulator, value, index++);
  }

  return accumulator;
}

// Example usage
const result = reduce(
  take(
    map(
      filter(range(1), n => n % 2 === 0),
      n => n * n
    ),
    5
  ),
  (sum, value) => sum + value,
  0
);

console.log(result); // 220
```

