## Bonus: lazy single value with memoization

Lazy evaluation is not only for collections. A single expensive value can also be deferred:

```ts
class Lazy<T> {
  private state:
    | { kind: "pending" }
    | { kind: "computed"; value: T } = { kind: "pending" };

  constructor(private readonly factory: () => T) {}

  get value(): T {
    if (this.state.kind === "pending") {
      const value = this.factory();
      this.state = { kind: "computed", value };
    }

    return this.state.value;
  }

  map<U>(transform: (value: T) => U): Lazy<U> {
    return new Lazy(() => transform(this.value));
  }
}

const lazyNumber = new Lazy(() => {
  console.log("Computing...");
  return 42;
});

console.log("Not computed yet");
console.log(lazyNumber.value); // Computing... then 42
console.log(lazyNumber.value); // 42, no recomputation
```

This pattern is useful for configuration, expensive parsing, cached derived values, and dependency injection.

---

## Practical notes

- Generators are ideal for **infinite or very large sequences**.
- Operations such as `map`, `filter`, and `take` should be generators if you want laziness.
- `Array.from(infiniteGenerator)` will hang; always bound infinite sequences with `take`.
- For single values, use a memoized thunk or a `Lazy<T>` wrapper.
- In performance-sensitive code, avoid excessive generator chaining if profiling shows overhead; sometimes a manual loop is clearer and faster.

## Lazy evaluation in TypeScript: concept + core implementation

### 1) What lazy evaluation means

- **Eager evaluation** computes a value as soon as it is bound.
- **Lazy evaluation** delays computation until the value is actually needed.
- In practice, you wrap a computation in a *thunk* `() => T` and force it later.
- Benefits: avoid unnecessary work, model infinite structures, short-circuit, delay side effects.
- TypeScript/JS are strict languages, so laziness is *simulated* with closures, getters, generators, or proxies.

Core idea:

```ts
const thunk = () => expensiveComputation();
// nothing runs yet
const value = thunk(); // forced
```

### 2) A clean, typed `Lazy<T>` core (memoized thunk)

This is the usual “core” of laziness: force once, cache forever, preserve errors.

```ts
// lazy.ts

/** A suspended computation. */
export type Producer<T> = () => T;

/** Three-state machine for safe memoization. */
type State<T> =
  | { kind: 'pending' }
  | { kind: 'value'; value: T }
  | { kind: 'error'; error: unknown };

/**
 * Lazy<T> wraps a producer and evaluates it at most once.
 *
 * Interview notes:
 * - JS is single-threaded, so we don't need locks, but we DO need
 *   error caching and re-entrancy awareness.
 * - `.value` is the forcing point.
 */
export class Lazy<T> {
  private state: State<T> = { kind: 'pending' };

  constructor(private readonly producer: Producer<T>) {}

  /** Force evaluation (or return cached result). */
  get value(): T {
    switch (this.state.kind) {
      case 'value':
        return this.state.value;

      case 'error':
        throw this.state.error;

      case 'pending': {
        // Evaluate exactly once. Cache either success or failure.
        try {
          const produced = this.producer();
          this.state = { kind: 'value', value: produced };
          return produced;
        } catch (err) {
          this.state = { kind: 'error', error: err };
          throw err;
        }
      }
    }
  }

  /** Transform lazily: f runs only when `.value` is forced. */
  map<U>(f: (value: T) => U): Lazy<U> {
    return new Lazy(() => f(this.value));
  }

  /** Monadic bind, still lazy. */
  flatMap<U>(f: (value: T) => Lazy<U>): Lazy<U> {
    return new Lazy(() => f(this.value).value);
  }

  /** Lift a pure value into Lazy. */
  static of<T>(value: T): Lazy<T> {
    return new Lazy(() => value);
  }

  /** Explicitly defer an already-thunked computation. */
  static defer<T>(producer: Producer<T>): Lazy<T> {
    return new Lazy(producer);
  }
}
```

Usage:

```ts
import { Lazy } from './lazy';

const computation = new Lazy(() => {
  console.log('running...');
  return 40 + 2;
});

// nothing printed yet
const doubled = computation.map(x => x * 2);

// forcing happens here
console.log(doubled.value); // logs "running..." then 84
console.log(doubled.value); // no log, cached -> 84
```

### 3) Lazy streams (infinite structures)

True laziness shines with lists where the tail is suspended.

```ts
// stream.ts

export abstract class Stream<T> {
  static empty<T>(): Stream<T> {
    return new EmptyStream<T>();
  }

  static cons<T>(head: T, tailThunk: () => Stream<T>): Stream<T> {
    return new ConsStream(head, tailThunk);
  }

  abstract isEmpty(): boolean;
  abstract head(): T;
  abstract tail(): Stream<T>;

  map<U>(f: (x: T) => U): Stream<U> {
    if (this.isEmpty()) return Stream.empty<U>();
    const h = f(this.head());
    const t = this.tail();
    // tail transformation is deferred
    return Stream.cons(h, () => t.map(f));
  }

  take(n: number): T[] {
    const out: T[] = [];
    let cur: Stream<T> = this;
    for (let i = 0; i < n && !cur.isEmpty(); i++) {
      out.push(cur.head());
      cur = cur.tail();
    }
    return out;
  }

  static fromGenerator<T>(g: Generator<T>): Stream<T> {
    const next = g.next();
    if (next.done) return Stream.empty<T>();
    return Stream.cons(next.value, () => Stream.fromGenerator(g));
  }
}

class EmptyStream<T> extends Stream<T> {
  isEmpty() { return true; }
  head(): T { throw new Error('head of empty stream'); }
  tail(): Stream<T> { throw new Error('tail of empty stream'); }
}

class ConsStream<T> extends Stream<T> {
  private tailCache?: Stream<T>;
  private tailComputed = false;

  constructor(
    private readonly h: T,
    private readonly tailThunk: () => Stream<T>,
  ) {
    super();
  }

  isEmpty() { return false; }
  head() { return this.h; }

  tail(): Stream<T> {
    if (!this.tailComputed) {
      this.tailCache = this.tailThunk();
      this.tailComputed = true;
    }
    return this.tailCache as Stream<T>;
  }
}
```

Usage with infinite data:

```ts
// naturals: 0,1,2,...
const naturals: Stream<number> = Stream.cons(0, () =>
  naturals.tail().map(x => x + 1) // naive, see note below
);
```

> Note: the naive self-reference above is for illustration; in a real interview you’d generate via a helper that takes current value.

Better helper:

```ts
function naturalsFrom(n: number): Stream<number> {
  return Stream.cons(n, () => naturalsFrom(n + 1));
}

const evens = naturalsFrom(0).map(x => x * 2);
console.log(evens.take(5)); // [0,2,4,6,8]
```

### 4) Edge cases and interview discussion points

- **Error caching:** If producer throws, we cache the error so repeated forces don’t re-run side effects.
- **Re-entrancy:** If the producer calls `.value` on the same `Lazy` instance, you get infinite recursion. Detect with a “computing” flag if needed.
- **Memory:** Lazy values and stream tails are retained after forcing. Use weak memoization or drop references for huge streams.
- **Purity:** Laziness + side effects is dangerous. Prefer pure producers.
- **Generators vs Lazy:** Generators are lazy iterators but don’t memoize; `Lazy` memoizes. Combine them when needed.
- **Complexity:** Forcing is `O(cost of producer)` once; afterward `O(1)`.

### 5) Minimal test ideas

```ts
import { Lazy } from './lazy';

test('forces once', () => {
  let calls = 0;
  const L = new Lazy(() => { calls++; return 7; });
  expect(L.value).toBe(7);
  expect(L.value).toBe(7);
  expect(calls).toBe(1);
});

test('caches errors', () => {
  let calls = 0;
  const L = new Lazy(() => { calls++; throw new Error('boom'); });
  expect(() => L.value).toThrow('boom');
  expect(() => L.value).toThrow('boom');
  expect(calls).toBe(1);
});
```

If you want, I can extend this into a full lazy Option/Result monad or an async lazy (`Lazy<Promise<T>>`) with concurrency control.

# Edge Cases in Lazy Evaluation (TypeScript)

Below are the most important edge cases, grouped by theme, with runnable TS examples.

---

## 1. Caching `undefined` / `null` (the sentinel problem)

A naive “cache if not computed” check breaks when the factory legitimately returns `undefined`.

```ts
// ❌ Broken: undefined is treated as "not computed"
function lazyBad<T>(factory: () => T) {
  let cache: T | undefined;
  return () => cache ?? (cache = factory());
}

// ✅ Use an explicit flag
function lazy<T>(factory: () => T): () => T {
  let cache: T;
  let computed = false;
  return () => {
    if (!computed) {
      cache = factory();
      computed = true;
    }
    return cache;
  };
}

const getNothing = lazy(() => undefined);
console.log(getNothing() === undefined); // true, and factory ran once
```

**Edge:** If `factory` throws, decide whether to retry. The version above leaves `computed=false`, so the next call retries — sometimes desirable, sometimes not.

---

## 2. Async deduplication (thundering herd)

Multiple callers must share one in-flight promise; otherwise the factory runs N times.

```ts
function lazyAsync<T>(factory: () => Promise<T>) {
  let promise: Promise<T> | undefined;
  return () => {
    if (!promise) {
      promise = factory().catch((err) => {
        promise = undefined; // allow retry on failure
        throw err;
      });
    }
    return promise;
  };
}

const load = lazyAsync(async () => {
  await new Promise((r) => setTimeout(r, 50));
  return 42;
});

// Both calls share one execution
const p1 = load();
const p2 = load();
console.log(p1 === p2); // true
```

**Edge:** Caching the *promise* (not the resolved value) is what gives dedup. Resetting on error vs. keeping the rejected promise is a policy choice.

---

## 3. `this` binding in lazy getters

Getters are functions; their `this` depends on how they are invoked.

```ts
class Box {
  factor = 2;
  get doubled() {
    return this.factor * 2;
  }
}

const b = new Box();
const read = b.doubled;          // 4 — getter invoked with b as `this`
const desc = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(b), 'doubled')!;
console.log(desc.get?.());       // NaN — `this` is undefined

// ✅ Safer: bind or use an arrow stored as an own property
class Box2 {
  factor = 2;
  doubled = () => this.factor * 2; // own property, lexically bound
}
```

**Edge:** Destructuring `{ doubled } = obj` evaluates the getter immediately with `obj` as `this` (fine), but extracting the getter function itself loses context.

---

## 4. Stale closures over mutable state (snapshot vs. live)

```ts
let discount = 0.1;
const price = () => 100 * (1 - discount); // live read

discount = 0.5;
console.log(price()); // 50 — surprising if you expected 90

// ✅ Snapshot at creation time
function makePrice(discount: number) {
  return () => 100 * (1 - discount);
}
const p2 = makePrice(0.1);
discount = 0.5;
console.log(p2()); // 90
```

**Edge:** Lazy values that close over variables are “live”; document which semantics you intend.

---

## 5. Side effects and evaluation order

Array literals and most expressions are **eager**. Laziness must be explicit.

```ts
function f() { console.log('f'); return 1; }
function g() { console.log('g'); return 2; }

const arr = [f(), g()]; // prints f, g — both run

// Lazy via generator
function* lazyItems() {
  yield f();
  yield g();
}
const it = lazyItems();
it.next(); // prints f only
it.next(); // prints g

// Short-circuiting IS lazy
const x = f() && g(); // if f() is falsy, g() never runs
```

**Edge:** `map`/`filter` are eager and allocate. For huge pipelines use generators or a lazy library (e.g., `itertools`).

---

## 6. Circular lazy dependencies

```ts
const a = () => b() + 1;
const b = () => a() + 1;
// a(); // RangeError: Maximum call stack size exceeded

// ✅ Detect cycles with a visiting set
function makeLazyGraph() {
  const computing = new Set<string>();
  const cache = new Map<string, number>();
  const fns: Record<string, () => number> = {
    a: () => { if (computing.has('a')) throw new Error('cycle: a'); computing.add('a'); const v = fns.b() + 1; computing.delete('a'); cache.set('a', v); return v; },
    b: () => { if (computing.has('b')) throw new Error('cycle: b'); computing.add('b'); const v = fns.a() + 1; computing.delete('b'); cache.set('b', v); return v; },
  };
  return fns;
}
```

**Edge:** Even with caching, a cycle during the *first* computation must be detected before caching completes.

---

## 7. Serialization: non-enumerable getters

Class getters live on the prototype and are **non-enumerable**, so `JSON.stringify` skips them.

```ts
class User {
  constructor(public id: number) {}
  get displayName() { return `user-${this.id}`; } // prototype getter, non-enumerable
}
console.log(JSON.stringify(new User(1))); // {"id":1}  — displayName missing!

// ✅ Define an enumerable own accessor
function withLazy<T extends object>(obj: T, key: string, factory: () => unknown) {
  Object.defineProperty(obj, key, {
    get() { const v = factory(); Object.defineProperty(this, key, { value: v, writable: false, enumerable: true }); return v; },
    enumerable: true,
    configurable: true,
  });
}
const u: any = { id: 1 };
withLazy(u, 'displayName', () => `user-${u.id}`);
console.log(JSON.stringify(u)); // {"id":1,"displayName":"user-1"}
```

**Edge:** Replacing the getter with a data property after first read (“memoizing getter”) is a common perf trick but changes enumerability/iteration semantics.

---

## 8. Memory leaks and `WeakRef`

A cached lazy value can pin large graphs forever.

```ts
function makeHuge() {
  const big = new Array(1_000_000).fill(0);
  return () => big.length; // closure retains `big` for the lifetime of the function
}

// ✅ Allow GC when no one holds the value
function lazyWeak<T extends object>(factory: () => T) {
  let ref: WeakRef<T> | undefined;
  return () => {
    const v = ref?.deref();
    if (v) return v;
    const fresh = factory();
    ref = new WeakRef(fresh);
    return fresh;
  };
}
```

**Edge:** `WeakRef` may return `undefined` after GC; design callers to handle re-computation. `FinalizationRegistry` can log/evict.

---

## 9. `this` / initialization order in classes

Field initializers run top-to-bottom; a lazy getter touching later fields gets `undefined`.

```ts
class A {
  x = this.compute(); // runs during construction, before `y` is set
  compute() { return this.y; } // undefined!
  y = 5;
}
console.log(new A().x); // undefined

// ✅ Defer: don't compute in field initializer; compute on first access after construction
class B {
  y = 5;
  get x() { return this.y * 2; }
}
```

---

## 10. Proxy traps and infinite recursion

Lazy objects via `Proxy` are convenient but foot-guns abound.

```ts
const cache = new Map<string, number>();
const lazy = new Proxy({} as Record<string, number>, {
  get(target, prop: string) {
    if (typeof prop === 'symbol') return (target as any)[prop];
    if (!cache.has(prop)) cache.set(prop, Math.random()); // compute
    const v = cache.get(prop)!;
    // ❌ assigning back to target and then reading target[prop] re-triggers get → recursion
    return v;
  },
});

console.log(lazy.a, lazy.a); // same value? depends on cache keying; here yes

// ✅ Keep storage in a separate Map, never route through the proxy
```

**Edge:** `console.log(proxy)` triggers many traps (`ownKeys`, `getOwnPropertyDescriptor`, etc.). Implement them or use a non-proxy approach.

---

## 11. Generators: exhaustion, `return`, and cleanup

```ts
function* gen() {
  try {
    yield 1;
    yield 2;
  } finally {
    console.log('cleanup runs on return/throw/exhaustion');
  }
}

const it = gen();
console.log(it.next()); // {value:1, done:false}
it.return(99);          // triggers finally, then {value:99, done:true}
console.log(it.next()); // {value:undefined, done:true} — exhausted, no re-run
```

**Edges:**
- After exhaustion, `.next()` keeps returning `{done:true}` (idempotent but not restarting).
- `for...of` calls `.return()` on early break — finally runs.
- Generators are **not** thread-safe across async interleaving (single-threaded JS is fine, but reentrancy via callbacks can surprise).

---

## 12. React / UI: stale closures in lazy callbacks

```tsx
function Counter() {
  const [count, setCount] = useState(0);
  // ❌ useMemo with [] captures initial count forever
  const log = useMemo(() => () => console.log(count), []);
  // ✅ include count, or use a ref
  const countRef = useRef(count);
  countRef.current = count;
  const log2 = useCallback(() => console.log(countRef.current), []);
  return <button onClick={() => setCount(c => c + 1)}>+ {count}</button>;
}
```

**Edge:** `lazy(() => import('./Heavy'))` in React is module-level; combined with Suspense, errors become render errors — wrap in ErrorBoundary.

---

## 13. Dynamic `import()` caching (module-level laziness)

```ts
let modPromise: Promise<typeof import('./heavy')> | undefined;
function loadHeavy() {
  if (!modPromise) modPromise = import('./heavy'); // browser caches by URL
  return modPromise;
}
// ESM already caches modules; re-import returns same module. But your wrapper's
// promise must be cached to avoid duplicate dynamic import() calls in flight.
```

**Edge:** Top-level `await` makes the whole module graph lazy/blocking; tree-shakers may drop “unused” dynamic imports incorrectly if side-effect-free assumptions are wrong.

---

## 14. Type-level: forcing evaluation and narrowing

```ts
type Lazy<T> = () => T;

function force<T>(l: Lazy<T>): T { return l(); }

// ❌ Conditional types distribute; wrap to avoid
type UnwrapLazy<T> = T extends Lazy<infer U> ? U : T;

// Edge: a lazy value's type may be wider than its runtime value
const x: Lazy<number | string> = () => 42;
const v = force(x); // number | string, even though runtime is number
```

**Edge:** If you need “computed once and narrowed,” store the result in a `const` and let TS narrow the variable, not the factory.

---

## 15. Async cancellation / abandonment

A lazy async computation that nobody awaits still runs to completion (JS has no cancellation). Use `AbortSignal`.

```ts
function lazyFetch(url: string) {
  let ctrl: AbortController | undefined;
  let promise: Promise<Response> | undefined;
  return (signal?: AbortSignal) => {
    if (!promise) {
      ctrl = new AbortController();
      promise = fetch(url, { signal: ctrl.signal });
    }
    signal?.addEventListener('abort', () => ctrl?.abort(), { once: true });
    return promise;
  };
}
```

**Edge:** Aborting shared promise rejects it for all callers — decide per-caller vs. shared controllers.

---

## Summary checklist

| Concern | Guard |
|---|---|
| `undefined` results | boolean `computed` flag, not nullish check |
| Concurrency | cache the promise, not just the value |
| Errors | explicit retry policy |
| `this` | bind/arrow or avoid methods |
| Mutability | document snapshot vs. live |
| Serialization | enumerable accessor or data property |
| Memory | `WeakRef` + `FinalizationRegistry` |
| Cycles | visiting set during first compute |
| Proxies | separate backing store; implement all traps |
| Generators | handle `return`/exhaustion; finally for cleanup |
| React | deps arrays, ErrorBoundary around `lazy` |
| Types | force with a function; don't rely on factory narrowing |

Lazy evaluation is mostly about *when* and *how many times* code runs — the edge cases are all consequences of deferring side effects, identity, and errors.

Below is a complete, runnable TypeScript example that implements two fundamental sequence types from scratch:

- **`ArrayList<T>`** – a dynamic array with amortized O(1) append and O(n) insert/remove.
- **`SinglyLinkedList<T>`** – a node-based list with O(1) prepend/append and O(n) indexed access.

Both are generic, null-safe, and include common operations (`push`, `pop`, `insert`, `removeAt`, `get`, `set`, `reverse`, `toArray`, etc.). The file ends with a small demo you can run directly.

### `lists-and-arrays.ts`

```ts
// lists-and-arrays.ts
// Run with: npx ts-node lists-and-arrays.ts
// or: tsc lists-and-arrays.ts && node lists-and-arrays.js

/* ------------------------------------------------------------------ */
/* 1. Dynamic Array (ArrayList)                                       */
/* ------------------------------------------------------------------ */

class ArrayList<T> {
  private data: (T | undefined)[];
  private _size = 0;

  constructor(initialCapacity = 8) {
    if (initialCapacity < 1) initialCapacity = 1;
    this.data = new Array(initialCapacity);
  }

  private ensureCapacity(minCapacity: number): void {
    if (this.data.length >= minCapacity) return;
    let newCapacity = this.data.length * 2;
    while (newCapacity < minCapacity) newCapacity *= 2;

    const next = new Array<T | undefined>(newCapacity);
    for (let i = 0; i < this._size; i++) next[i] = this.data[i];
    this.data = next;
  }

  size(): number {
    return this._size;
  }

  isEmpty(): boolean {
    return this._size === 0;
  }

  capacity(): number {
    return this.data.length;
  }

  clear(): void {
    this.data = new Array(8);
    this._size = 0;
  }

  push(value: T): void {
    this.ensureCapacity(this._size + 1);
    this.data[this._size++] = value;
  }

  pop(): T | undefined {
    if (this._size === 0) return undefined;
    const value = this.data[--this._size];
    this.data[this._size] = undefined;
    return value;
  }

  get(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;
    return this.data[index];
  }

  set(index: number, value: T): boolean {
    if (index < 0 || index >= this._size) return false;
    this.data[index] = value;
    return true;
  }

  insert(index: number, value: T): boolean {
    if (index < 0 || index > this._size) return false;
    this.ensureCapacity(this._size + 1);
    for (let i = this._size; i > index; i--) {
      this.data[i] = this.data[i - 1];
    }
    this.data[index] = value;
    this._size++;
    return true;
  }

  removeAt(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;
    const removed = this.data[index];
    for (let i = index; i < this._size - 1; i++) {
      this.data[i] = this.data[i + 1];
    }
    this._size--;
    this.data[this._size] = undefined;
    return removed;
  }

  indexOf(value: T, equals: (a: T, b: T) => boolean = (a, b) => a === b): number {
    for (let i = 0; i < this._size; i++) {
      if (equals(this.data[i] as T, value)) return i;
    }
    return -1;
  }

  contains(value: T): boolean {
    return this.indexOf(value) >= 0;
  }

  reverse(): void {
    let left = 0;
    let right = this._size - 1;
    while (left < right) {
      const tmp = this.data[left];
      this.data[left] = this.data[right];
      this.data[right] = tmp;
      left++;
      right--;
    }
  }

  toArray(): T[] {
    const result: T[] = [];
    for (let i = 0; i < this._size; i++) result.push(this.data[i] as T);
    return result;
  }
}

/* ------------------------------------------------------------------ */
/* 2. Singly Linked List                                              */
/* ------------------------------------------------------------------ */

class SLLNode<T> {
  constructor(public value: T, public next: SLLNode<T> | null = null) {}
}

class SinglyLinkedList<T> {
  private head: SLLNode<T> | null = null;
  private tail: SLLNode<T> | null = null;
  private _size = 0;

  size(): number {
    return this._size;
  }

  isEmpty(): boolean {
    return this._size === 0;
  }

  append(value: T): this {
    const node = new SLLNode(value);
    if (!this.tail) {
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this._size++;
    return this;
  }

  prepend(value: T): this {
    const node = new SLLNode(value, this.head);
    this.head = node;
    if (!this.tail) this.tail = node;
    this._size++;
    return this;
  }

  insertAt(index: number, value: T): boolean {
    if (index < 0 || index > this._size) return false;
    if (index === 0) {
      this.prepend(value);
      return true;
    }
    if (index === this._size) {
      this.append(value);
      return true;
    }

    let current = this.head;
    for (let i = 0; i < index - 1; i++) current = current!.next;
    const node = new SLLNode(value, current!.next);
    current!.next = node;
    this._size++;
    return true;
  }

  removeAt(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;

    let removed: T;
    if (index === 0) {
      removed = this.head!.value;
      this.head = this.head!.next;
      if (this._size === 1) this.tail = null;
    } else {
      let current = this.head;
      for (let i = 0; i < index - 1; i++) current = current!.next;
      removed = current!.next!.value;
      current!.next = current!.next!.next;
      if (index === this._size - 1) this.tail = current;
    }

    this._size--;
    return removed;
  }

  get(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;
    let current = this.head;
    for (let i = 0; i < index; i++) current = current!.next;
    return current!.value;
  }

  set(index: number, value: T): boolean {
    if (index < 0 || index >= this._size) return false;
    let current = this.head;
    for (let i = 0; i < index; i++) current = current!.next;
    current!.value = value;
    return true;
  }

  indexOf(value: T, equals: (a: T, b: T) => boolean = (a, b) => a === b): number {
    let current = this.head;
    let index = 0;
    while (current) {
      if (equals(current.value, value)) return index;
      current = current.next;
      index++;
    }
    return -1;
  }

  contains(value: T): boolean {
    return this.indexOf(value) >= 0;
  }

  reverse(): void {
    let previous: SLLNode<T> | null = null;
    let current = this.head;
    this.tail = this.head; // old head becomes new tail
    while (current) {
      const next = current.next;
      current.next = previous;
      previous = current;
      current = next;
    }
    this.head = previous;
  }

  toArray(): T[] {
    const result: T[] = [];
    let current = this.head;
    while (current) {
      result.push(current.value);
      current = current.next;
    }
    return result;
  }
}

/* ------------------------------------------------------------------ */
/* 3. Demo / sanity checks                                            */
/* ------------------------------------------------------------------ */

function demoArrayList(): void {
  console.log("=== ArrayList demo ===");
  const list = new ArrayList<number>(4);

  for (let i = 1; i <= 6; i++) list.push(i);
  console.log("after push 1..6:", list.toArray(), "size=", list.size(), "cap=", list.capacity());

  list.insert(2, 99);
  console.log("insert 99 at index 2:", list.toArray());

  console.log("get(2) =", list.get(2));
  list.set(2, 100);
  console.log("set(2,100):", list.toArray());

  console.log("removeAt(0) =", list.removeAt(0));
  console.log("after remove:", list.toArray());

  list.reverse();
  console.log("reversed:", list.toArray());

  console.log("indexOf(5) =", list.indexOf(5));
  console.log("contains(42) =", list.contains(42));
  console.log("pop() =", list.pop(), "->", list.toArray());
}

function demoLinkedList(): void {
  console.log("\n=== SinglyLinkedList demo ===");
  const list = new SinglyLinkedList<string>();

  list.append("b").append("c").prepend("a");
  console.log("after append/prepend:", list.toArray());

  list.insertAt(2, "x");
  console.log("insertAt(2,'x'):", list.toArray());

  console.log("get(1) =", list.get(1));
  list.set(1, "A");
  console.log("set(1,'A'):", list.toArray());

  console.log("removeAt(3) =", list.removeAt(3));
  console.log("after remove:", list.toArray());

  list.reverse();
  console.log("reversed:", list.toArray());

  console.log("size =", list.size(), "isEmpty =", list.isEmpty());
  console.log("indexOf('A') =", list.indexOf("A"));
}

demoArrayList();
demoLinkedList();
```

