Below are the most important edge cases when logging in TypeScript, grouped by concern, with runnable patterns.

---

## 1. Serialization edge cases

### 1.1 Circular references

`JSON.stringify` throws on cycles. Always guard.

```ts
type Replacer = (key: string, value: unknown) => unknown;

function safeStringify(obj: unknown, space?: number): string {
  const seen = new WeakSet<object>();
  const replacer: Replacer = (_key, value) => {
    if (typeof value === 'object' && value !== null) {
      if (seen.has(value)) return '[Circular]';
      seen.add(value);
    }
    return value;
  };
  try {
    return JSON.stringify(obj, replacer, space);
  } catch (e) {
    return `[Unserializable: ${(e as Error).message}]`;
  }
}

// Usage
const a: any = { name: 'a' };
a.self = a;
console.log(safeStringify(a)); // {"name":"a","self":"[Circular]"}
```

### 1.2 BigInt

```ts
function bigintReplacer(_k: string, v: unknown) {
  if (typeof v === 'bigint') return v.toString() + 'n';
  return v;
}
JSON.stringify({ count: 9007199254740993n }, bigintReplacer);
```

### 1.3 Errors (non-enumerable props)

`Error` objects serialize to `{}` because `message`/`stack` are non-enumerable. Normalize explicitly.

```ts
function normalizeError(err: unknown) {
  if (!(err instanceof Error)) return { value: err };
  return {
    name: err.name,
    message: err.message,
    stack: err.stack,
    cause: err.cause ? normalizeError(err.cause) : undefined,
    // custom props
    ...Object.getOwnPropertyNames(err).reduce<Record<string, unknown>>((acc, k) => {
      if (!['name', 'message', 'stack', 'cause'].includes(k)) acc[k] = (err as any)[k];
      return acc;
    }, {}),
  };
}
```

### 1.4 Dates, Maps, Sets, RegExp, Functions

```ts
function deepNormalize(v: unknown, seen = new WeakSet()): unknown {
  if (v === null || typeof v !== 'object') return v;
  if (seen.has(v as object)) return '[Circular]';
  seen.add(v as object);

  if (v instanceof Date) return v.toISOString();
  if (v instanceof Map) return Object.fromEntries([...v].map(([k, val]) => [String(k), deepNormalize(val, seen)]));
  if (v instanceof Set) return [...v].map((x) => deepNormalize(x, seen));
  if (v instanceof RegExp) return v.toString();
  if (v instanceof Error) return normalizeError(v);
  if (Array.isArray(v)) return v.map((x) => deepNormalize(x, seen));

  const out: Record<string, unknown> = {};
  for (const [k, val] of Object.entries(v as Record<string, unknown>)) {
    // skip functions & symbols-ish
    if (typeof val === 'function') continue;
    out[k] = deepNormalize(val, seen);
  }
  return out;
}
```

### 1.5 Proxy objects

Proxies can throw on property access. Wrap in try/catch.

```ts
function safeEntries(obj: unknown): [string, unknown][] {
  try {
    return Object.entries(obj as any);
  } catch {
    return [];
  }
}
```

---

## 2. Security / privacy edge cases

### 2.1 Redaction of secrets (deep)

```ts
const SENSITIVE = /password|token|secret|api[_-]?key|authorization|cookie/i;

function redact(obj: unknown, seen = new WeakSet()): unknown {
  if (obj === null || typeof obj !== 'object') return obj;
  if (seen.has(obj as object)) return '[Circular]';
  seen.add(obj as object);

  if (Array.isArray(obj)) return obj.map((x) => redact(x, seen));

  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
    if (SENSITIVE.test(k)) {
      out[k] = '[REDACTED]';
    } else {
      out[k] = redact(v, seen);
    }
  }
  return out;
}
```

### 2.2 Request URLs with query tokens

```ts
function sanitizeUrl(url: string): string {
  try {
    const u = new URL(url);
    for (const key of [...u.searchParams.keys()]) {
      if (SENSITIVE.test(key)) u.searchParams.set(key, '[REDACTED]');
    }
    return u.toString();
  } catch {
    return url;
  }
}
```

### 2.3 Never log raw request bodies blindly in prod

```ts
const isProd = process.env.NODE_ENV === 'production';

function logRequest(body: unknown) {
  if (isProd) {
    logger.info({ bodySize: byteLength(body) }, 'request received');
  } else {
    logger.debug({ body: redact(body) }, 'request received');
  }
}
```

---

## 3. Reliability edge cases

### 3.1 Logger must never throw to caller

Wrap all sink operations.

```ts
class SafeLogger {
  constructor(private sink: (msg: string) => void) {}

  info(obj: unknown, msg?: string) {
    try {
      const line = `${new Date().toISOString()} INFO ${msg ?? ''} ${safeStringify(redact(normalizeForLog(obj)))}`;
      this.sink(line);
    } catch (e) {
      // last-resort: write to stderr without throwing
      process.stderr.write(`[logger failure] ${(e as Error).message}\n`);
    }
  }
}
```

### 3.2 Flush on process exit / signals

```ts
function flushAndExit(code: number) {
  logger.flush(() => process.exit(code));
}

process.on('SIGTERM', () => flushAndExit(0));
process.on('SIGINT', () => flushAndExit(0));
process.on('uncaughtException', (e) => {
  logger.fatal({ err: normalizeError(e) }, 'uncaughtException');
  flushAndExit(1);
});
process.on('unhandledRejection', (reason) => {
  logger.error({ err: normalizeError(reason) }, 'unhandledRejection');
});
```

### 3.3 Async context loss

Use `AsyncLocalStorage` to keep request id.

```ts
import { AsyncLocalStorage } from 'node:async_hooks';

const als = new AsyncLocalStorage<{ requestId: string }>();

function withRequest<T>(id: string, fn: () => T): T {
  return als.run({ requestId: id }, fn);
}

function log(level: string, obj: unknown, msg?: string) {
  const ctx = als.getStore();
  const payload = { ...normalizeForLog(obj), requestId: ctx?.requestId };
  // sink...
}
```

---

## 4. Performance edge cases

### 4.1 Avoid work when level disabled

Check level before expensive serialization.

```ts
if (logger.isLevelEnabled('debug')) {
  logger.debug({ expensive: computeHeavySnapshot() }, 'snapshot');
}
```

### 4.2 Sampling high-volume logs

```ts
function sampledLog(key: string, sampleRate = 0.01) {
  if (Math.random() < sampleRate) {
    logger.debug({ key, sampled: true }, 'high-volume event');
  }
}
```

### 4.3 Backpressure / bounded queues

If logging to file/network, bound the queue to avoid OOM.

```ts
class BoundedQueue {
  private q: string[] = [];
  constructor(private max = 10000) {}
  push(line: string) {
    if (this.q.length >= this.max) {
      this.q.shift(); // drop oldest
      process.stderr.write('[log queue overflow, dropping]\n');
    }
    this.q.push(line);
  }
}
```

### 4.4 Don't stringify on every call if not needed

Libraries like pino accept objects and stringify lazily; if you must stringify, do it once.

---

## 5. Type-safety edge cases

### 5.1 Accept `unknown`, not `any`

```ts
interface Logger {
  info(obj: unknown, msg?: string): void;
  error(obj: unknown, msg?: string): void;
}
```

### 5.2 Typed child loggers / bindings

```ts
type LogFn = (obj: unknown, msg?: string) => void;

function createLogger(bindings: Record<string, unknown>): { info: LogFn; child: (b: Record<string, unknown>) => ReturnType<typeof createLogger> } {
  const merged = { ...bindings };
  return {
    info: (obj, msg) => sink({ ...merged, ...(obj as object) }, msg),
    child: (b) => createLogger({ ...merged, ...b }),
  };
}
```

### 5.3 Exhaustive level handling

```ts
type Level = 'trace' | 'debug' | 'info' | 'warn' | 'error' | 'fatal';
const LEVELS: Record<Level, number> = { trace: 10, debug: 20, info: 30, warn: 40, error: 50, fatal: 60 };
```

---

## 6. Environment / runtime edge cases

### 6.1 SSR / universal code (browser vs node)

```ts
const isBrowser = typeof window !== 'undefined';

const logger = isBrowser
  ? createBrowserLogger()
  : createNodeLogger();
```

### 6.2 Colorization only when TTY

```ts
import { isatty } from 'node:tty';

const useColor = isatty(process.stdout.fd) && !process.env.NO_COLOR;
```

### 6.3 Respect `LOG_LEVEL` env

```ts
const minLevel = (process.env.LOG_LEVEL as Level) ?? (isProd ? 'info' : 'debug');
```

### 6.4 Clock skew / monotonic time

Use `performance.now()` for durations, wall clock for timestamps.

```ts
const start = performance.now();
// work
logger.info({ durationMs: performance.now() - start }, 'done');
```

---

## 7. Testing edge cases

### 7.1 Inject logger dependency; don't import global singleton in tests

```ts
class Service {
  constructor(private log: Logger) {}
  run() { this.log.info('running'); }
}

// test
const fake: Logger = { info: jest.fn(), error: jest.fn(), /* ... */ };
const svc = new Service(fake);
```

### 7.2 Capture & assert structured output

```ts
it('logs request id', () => {
  const lines: string[] = [];
  const log = createLogger((l) => lines.push(l));
  withRequest('req-1', () => log.info({ foo: 1 }, 'hi'));
  expect(JSON.parse(lines[0])).toMatchObject({ requestId: 'req-1', foo: 1 });
});
```

### 7.3 Avoid leaking timers / handles in tests

If your logger uses intervals/streams, expose `close()` and call in `afterEach`.

---

## 8. Bonus: production-ready minimal logger skeleton

```ts
import { AsyncLocalStorage } from 'node:async_hooks';

type Level = 'debug' | 'info' | 'warn' | 'error';
const RANK: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };

export function createLogger(minLevel: Level = 'info') {
  const als = new AsyncLocalStorage<{ requestId?: string }>();
  const sink = (line: string) => process.stdout.write(line + '\n');

  const emit = (level: Level, obj: unknown, msg?: string) => {
    if (RANK[level] < RANK[minLevel]) return;
    try {
      const ctx = als.getStore();
      const normalized = deepNormalize(redact(obj));
      const record = {
        time: new Date().toISOString(),
        level,
        msg,
        requestId: ctx?.requestId,
        ...(typeof normalized === 'object' && normalized !== null ? normalized : { value: normalized }),
      };
      sink(safeStringify(record));
    } catch (e) {
      process.stderr.write(`[logger] ${(e as Error).message}\n`);
    }
  };

  return {
    debug: (o: unknown, m?: string) => emit('debug', o, m),
    info: (o: unknown, m?: string) => emit('info', o, m),
    warn: (o: unknown, m?: string) => emit('warn', o, m),
    error: (o: unknown, m?: string) => emit('error', o, m),
    runWithContext: <T>(id: string, fn: () => T) => als.run({ requestId: id }, fn),
    flush: (cb: () => void) => cb(),
  };
}
```

---

### Key takeaways

- Treat logging as a **boundary**: normalize, redact, and never trust input shapes.
- Keep the **hot path cheap**: level checks first, sampling, bounded queues.
- Make loggers **injectable** and **non-throwing**.
- Preserve **async context** and ensure **flush on exit**.
- In TS, type log payloads as `unknown` and use exhaustive level maps.

