### `loops.ts`

```ts
/* eslint-disable no-console */

// ---------- Types ----------
type User = {
  id: number;
  name: string;
  active: boolean;
};

const users: User[] = [
  { id: 1, name: "Alice", active: true },
  { id: 2, name: "Bob", active: false },
  { id: 3, name: "Carol", active: true },
];

// ---------- 1. Classic index-based for ----------
// Best when you need the index, must break/continue, or want max performance.
for (let i = 0; i < users.length; i++) {
  console.log(`[for] ${i}: ${users[i].name}`);
}

// ---------- 2. for...of (values) ----------
// Idiomatic for arrays, Sets, Maps, strings, and any iterable.
for (const user of users) {
  if (!user.active) continue;          // skip inactive
  console.log(`[for...of] active: ${user.name}`);
}

// ---------- 3. while ----------
// Use when the number of iterations is unknown up front.
let idx = 0;
while (idx < users.length) {
  console.log(`[while] id=${users[idx].id}`);
  idx++;
}

// ---------- 4. do...while ----------
// Guarantees at least one execution (input validation, retries, etc.).
let attempts = 0;
do {
  console.log(`[do...while] attempt ${attempts}`);
  attempts++;
} while (attempts < 1);

// ---------- 5. Array.prototype.forEach ----------
// Functional style; cannot break/continue (use every/some or a for loop if you need to).
users.forEach((user, index) => {
  console.log(`[forEach] ${index} -> ${user.name}`);
});

// ---------- 6. Transformations: map / filter / reduce ----------
// These are "loops" that return new data instead of side effects.
const activeNames: string[] = users
  .filter((u) => u.active)
  .map((u) => u.name.toUpperCase());

console.log("[map/filter]", activeNames);

const totalId = users.reduce((acc, u) => acc + u.id, 0);
console.log("[reduce] total id =", totalId);

// ---------- 7. for...in (object keys) ----------
// Use ONLY for plain objects, and guard with hasOwnProperty.
const config = { host: "localhost", port: 3000, debug: true };

for (const key in config) {
  if (Object.prototype.hasOwnProperty.call(config, key)) {
    const value = config[key as keyof typeof config];
    console.log(`[for...in] ${key} = ${value}`);
  }
}

// ---------- 8. Object.entries (safer alternative to for...in) ----------
for (const [key, value] of Object.entries(config)) {
  console.log(`[entries] ${key} = ${value}`);
}

// ---------- 9. Labeled statements (break/continue outer loops) ----------
outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) {
      console.log("[labeled] breaking outer at", i, j);
      break outer;
    }
    console.log(`[labeled] i=${i} j=${j}`);
  }
}

// ---------- 10. Async iteration (for await...of) ----------
// Works with async generators and async iterables.
async function* asyncNumbers(): AsyncGenerator<number> {
  for (let i = 0; i < 3; i++) {
    yield await Promise.resolve(i * 10);
  }
}

async function runAsyncLoop(): Promise<void> {
  for await (const value of asyncNumbers()) {
    console.log("[for await...of]", value);
  }
}

// ---------- 11. Generator (sync) with yield ----------
function* range(start: number, end: number): Generator<number> {
  for (let i = start; i < end; i++) yield i;
}
console.log("[generator]", [...range(0, 5)]);

// ---------- Entry point ----------
(async () => {
  await runAsyncLoop();
  console.log("done");
})();
```

---

### Key takeaways

| Construct | Use when | Gotchas |
|---|---|---|
| `for (let i = 0; ...)` | Need index, must `break`, hot paths | `let`/`const` only—never `var` |
| `for...of` | Iterating values of arrays/iterables | Cannot get index without `entries()` |
| `for...in` | Enumerating object keys | Includes inherited props; type carefully |
| `while` / `do...while` | Unknown iteration count | Risk of infinite loops; guard conditions |
| `forEach` | Side-effect-only transforms | Cannot `break`/`return` out of outer function |
| `map/filter/reduce` | Producing new data | Creates new arrays; avoid in tight loops if perf matters |
| `for await...of` | Async streams/generators | Must be inside `async` function |
| Generators | Lazy sequences | Consume with `for...of` or spread |

### TypeScript-specific tips

1. **Type the loop variable explicitly** when inference is weak:
   ```ts
   for (const [k, v] of Object.entries(obj) as [string, number][]) { ... }
   ```
2. **Prefer `const`** for `for...of` variables; use `let` only for index loops.
3. **Strict null checks**: when indexing arrays, TS widens to `T | undefined` under `noUncheckedIndexedAccess`. Use a helper or guard:
   ```ts
   const u = users[i];
   if (u) console.log(u.name);
   ```
4. **Avoid `for...in` on arrays**—it enumerates string keys and inherited properties. Use `for...of` or index loops instead.

