# Edge Cases When Using Memoization in TypeScript

Below are the most common (and subtle) edge cases, with explanations and runnable TypeScript examples.

---

## 1. Falsy return values are dropped

A naive cache check like `if (cached)` skips `0`, `""`, `false`, `null`.

```ts
// BAD
function memoizeBad(fn: (...a: any[]) => any) {
  const cache = new Map<string, any>();
  return (...args: any[]) => {
    const key = JSON.stringify(args);
    const cached = cache.get(key);
    if (cached) return cached; // ❌ 0, "", false are "missed"
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

// GOOD
function memoize(fn: (...a: any[]) => any) {
  const cache = new Map<string, any>();
  return (...args: any[]) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key); // ✅
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}
```

---

## 2. Object/array arguments and reference equality

Two different object literals with identical contents are different references, so a reference-keyed cache misses.

```ts
const cache = new Map<any, number>();
function area(rect: { w: number; h: number }) {
  if (cache.has(rect)) return cache.get(rect)!;
  const r = rect.w * rect.h;
  cache.set(rect, r);
  return r;
}

area({ w: 2, h: 3 }); // computes
area({ w: 2, h: 3 }); // computes again (different reference)
```

Options:
- **Value semantics**: stable serialize (`JSON.stringify` with sorted keys).
- **Reference semantics** (often correct for memoization of pure functions of identity): keep `Map`/`WeakMap` keyed by the object itself.

```ts
// Reference-keyed, no serialization cost, GC-friendly
function memoizeByRef<TArg extends object, TResult>(
  fn: (arg: TArg) => TResult
) {
  const cache = new WeakMap<TArg, TResult>();
  return (arg: TArg) => {
    if (cache.has(arg)) return cache.get(arg)!;
    const r = fn(arg);
    cache.set(arg, r);
    return r;
  };
}
```

---

## 3. `this` binding is lost

Extracting a method and memoizing it detaches `this`.

```ts
class Counter {
  base = 10;
  compute(x: number) { return this.base + x; }
}

const c = new Counter();
const memoized = memoize(c.compute); // ❌ `this` is undefined in strict mode
memoized(5); // TypeError

// FIX: bind
const memoizedOk = memoize(c.compute.bind(c));
```

For class methods, prefer per-instance caches so different instances don't share results:

```ts
function memoizeMethod<This, Args extends any[], Ret>(
  fn: (this: This, ...args: Args) => Ret
) {
  const instanceCaches = new WeakMap<This, Map<string, Ret>>();
  return function (this: This, ...args: Args): Ret {
    if (!instanceCaches.has(this)) instanceCaches.set(this, new Map());
    const cache = instanceCaches.get(this)!;
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key)!;
    const r = fn.apply(this, args);
    cache.set(key, r);
    return r;
  };
}
```

---

## 4. Async functions and Promises

Caching the *resolved value* instead of the promise causes duplicate concurrent work and unhandled rejections.

```ts
// BAD: caches value after await; two concurrent calls both run fn
async function memoizeAsyncBad(fn: (...a: any[]) => Promise<any>) {
  const cache = new Map<string, any>();
  return async (...args: any[]) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const r = await fn(...args);
    cache.set(key, r);
    return r;
  };
}

// GOOD: cache the promise; invalidate on rejection
function memoizeAsync(fn: (...a: any[]) => Promise<any>) {
  const cache = new Map<string, Promise<any>>();
  return (...args: any[]) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key)!;
    const p = fn(...args).catch((err) => {
      cache.delete(key); // don't poison cache with failures
      throw err;
    });
    cache.set(key, p);
    return p;
  };
}
```

Also consider: stale promises if inputs change, and memory growth from never-resolving promises.

---

## 5. Serialization pitfalls

`JSON.stringify` fails or behaves unexpectedly for many values.

```ts
const cases = [
  [{ a: 1, b: 2 }, { b: 2, a: 1 }], // key order differs → different keys
  [new Date("2020-01-01"), new Date("2020-01-01")], // becomes strings, OK but loses type
  [1n, 2n],                 // TypeError: BigInt not serializable
  [{ x: undefined }],       // undefined dropped → {} 
  [NaN, Infinity],          // becomes null
  [new Map([["a", 1]]), new Set([1, 2])], // becomes {}
  [() => 1, () => 2],      // becomes undefined
  [Symbol("x")],            // dropped
];

// Circular reference throws:
const o: any = {};
o.self = o;
JSON.stringify(o); // TypeError: Converting circular structure to JSON
```

A safer key serializer:

```ts
function stableKey(args: unknown[]): string {
  const seen = new WeakSet();
  return JSON.stringify(args, (_k, v) => {
    if (typeof v === "bigint") return { __type: "bigint", value: v.toString() };
    if (v instanceof Date) return { __type: "date", value: v.toISOString() };
    if (v instanceof Map) return { __type: "map", value: [...v.entries()] };
    if (v instanceof Set) return { __type: "set", value: [...v] };
    if (typeof v === "function") return { __type: "fn", value: v.toString() };
    if (typeof v === "symbol") return { __type: "symbol", value: v.toString() };
    if (v !== null && typeof v === "object") {
      if (seen.has(v)) return { __type: "circular" };
      seen.add(v);
    }
    if (v === undefined) return { __type: "undefined" };
    if (Number.isNaN(v)) return { __type: "nan" };
    if (v === -0) return { __type: "negzero" };
    return v;
  });
}
```

Even then, key ordering of plain objects matters—sort keys for true value equality:

```ts
function sortKeys(v: any): any {
  if (v && typeof v === "object" && !Array.isArray(v)) {
    return Object.keys(v)
      .sort()
      .reduce((acc, k) => ((acc[k] = sortKeys(v[k])), acc), {} as any);
  }
  if (Array.isArray(v)) return v.map(sortKeys);
  return v;
}
```

---

## 6. Mutable arguments change after the call

```ts
const arr = [1, 2, 3];
const m = memoize((a: number[]) => a.reduce((x, y) => x + y, 0));
m(arr); // 6, cached
arr.push(4);
m(arr); // returns stale 6
```

Fixes: document immutability, clone inputs, or key by a snapshot/hash. If mutation is expected, memoization is the wrong tool.

---

## 7. Unbounded cache / memory leaks

A plain `Map` grows forever. Use an LRU or `WeakMap`.

```ts
// LRU (minimal)
class LRU<K, V> {
  private map = new Map<K, V>();
  constructor(private capacity: number) {}
  get(key: K): V | undefined {
    if (!this.map.has(key)) return undefined;
    const v = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, v); // refresh
    return v;
  }
  set(key: K, value: V) {
    if (this.map.has(key)) this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity) {
      const first = this.map.keys().next().value;
      this.map.delete(first);
    }
  }
  has(key: K) { return this.map.has(key); }
}
```

`WeakMap` caches are GC'd when the key object is no longer referenced—ideal for per-object memoization, but **keys must be objects** (no primitives).

---

## 8. `NaN`, `-0`, and `Map`'s `SameValueZero`

`Map` uses SameValueZero, so `NaN` keys collapse and `-0`/`0` collapse. This is usually desirable, but surprising for numeric functions that distinguish them.

```ts
const m = new Map();
m.set(NaN, "a");
m.get(NaN); // "a"  (NaN === NaN is false, but Map treats them equal)
m.set(-0, "neg");
m.get(0);   // "neg"
```

If you need strict identity semantics, build the key from `Object.is`-aware tokens, or accept the default.

---

## 9. Prototype pollution with plain-object caches

```ts
const cache: Record<string, any> = {};
function bad(key: string) {
  if (cache[key]) return cache[key]; // ❌ key "__proto__" / "toString"
  ...
}
```

Always use `Map` (or `Object.create(null)`), and check with `.has()` not truthiness.

---

## 10. `undefined` vs absent arguments

`JSON.stringify([1, undefined])` produces `"[1,null]"`, colliding with an explicit `null`. Also default parameters: `f(1)` and `f(1, undefined)` may differ.

```ts
function f(a: number, b: number = 2) { return a + b; }
// f(1) === 3, f(1, undefined) === 3 (default applies) — same result here,
// but keying must not collapse distinct call shapes if it matters.
```

Use a serializer that preserves `undefined` (see case 5) and include `arguments.length` in the key when defaults matter.

---

## 11. Cross-instance leakage in class methods

A global cache keyed only by arguments leaks results between instances.

```ts
class User {
  constructor(public id: number) {}
  label(prefix: string) { return `${prefix}:${this.id}`; }
}

// BAD: global cache → instance B gets instance A's result
const badMemo = memoize((self: User, prefix: string) => self.label(prefix));

// GOOD: per-instance cache (see case 3 pattern)
```

---

## 12. Impure functions / side effects

Memoization assumes referential transparency. Memoizing a function with side effects (logging, DOM writes, network) silently skips them on cache hits. Also time-dependent or randomness-dependent functions.

```ts
const now = memoize(() => Date.now()); // ❌ returns stale timestamp forever
```

---

## 13. Cache invalidation and TTL

Memoized values can become stale when external state changes.

```ts
function memoizeTTL(fn: (...a: any[]) => any, ttlMs: number) {
  const cache = new Map<string, { value: any; expires: number }>();
  return (...args: any[]) => {
    const key = JSON.stringify(args);
    const entry = cache.get(key);
    if (entry && Date.now() < entry.expires) return entry.value;
    const value = fn(...args);
    cache.set(key, { value, expires: Date.now() + ttlMs });
    return value;
  };
}
```

For dependency-based invalidation, key the cache by a version/revision token.

---

## 14. Recursion and declaration order

A memoized recursive function must be assigned before recursion resolves; use `const` with a named function expression carefully.

```ts
// Works
const fib = memoize((n: number): number =>
  n < 2 ? n : fib(n - 1) + fib(n - 2)
);

// Risky: temporal dead zone if referenced before assignment
```

---

## 15. Error caching

Decide explicitly whether thrown errors / rejected promises should be cached. Usually **no** (case 4 deletes on rejection). For sync throws, wrap in try/catch and don't store.

```ts
function memoizeNoThrowCache(fn: (...a: any[]) => any) {
  const cache = new Map<string, any>();
  return (...args: any[]) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    let result;
    try {
      result = fn(...args);
    } catch (e) {
      throw e; // don't cache
    }
    cache.set(key, result);
    return result;
  };
}
```

---

## 16. Type-level concerns

- Generic type parameters are erased at runtime, so memoize by runtime args only.
- Overloaded functions: memoize the implementation signature; callers see overloads but the cache is untyped internally—add casts.
- `this`-typed functions need proper `ThisParameterType` handling (see case 3).

---

## A more robust, production-style implementation

Combining several fixes (reference+value keys, async, TTL, LRU, per-instance) is usually better than a one-size-fits-all. A pragmatic baseline:

```ts
type AnyFn = (...args: any[]) => any;

interface MemoOptions {
  ttlMs?: number;
  maxSize?: number;
}

export function memoize(fn: AnyFn, opts: MemoOptions = {}) {
  const { ttlMs = Infinity, maxSize = 512 } = opts;
  const cache = new Map<string, { value: any; expires: number }>();

  const evictIfNeeded = () => {
    if (cache.size <= maxSize) return;
    const oldest = cache.keys().next().value;
    cache.delete(oldest);
  };

  return function (this: any, ...args: any[]) {
    const key = stableKey(args); // from case 5
    const now = Date.now();
    const entry = cache.get(key);
    if (entry && now < entry.expires) {
      // refresh LRU order
      cache.delete(key);
      cache.set(key, entry);
      return entry.value;
    }
    const result = fn.apply(this, args);
    cache.set(key, { value: result, expires: now + ttlMs });
    evictIfNeeded();
    return result;
  };
}

export function memoizeAsync(fn: (...a: any[]) => Promise<any>, opts: MemoOptions = {}) {
  const { ttlMs = Infinity, maxSize = 512 } = opts;
  const cache = new Map<string, { promise: Promise<any>; expires: number }>();

  return function (this: any, ...args: any[]) {
    const key = stableKey(args);
    const now = Date.now();
    const entry = cache.get(key);
    if (entry && now < entry.expires) return entry.promise;

    const promise = fn.apply(this, args).catch((err) => {
      cache.delete(key);
      throw err;
    });

    cache.set(key, { promise, expires: now + ttlMs });
    if (cache.size > maxSize) cache.delete(cache.keys().next().value);
    return promise;
  };
}
```

### Summary checklist
- ✅ Use `.has()` not truthiness (falsy values).
- ✅ Decide value vs reference equality for object args.
- ✅ Preserve `this` (bind or per-instance cache).
- ✅ Cache promises, not resolved values, for async; invalidate on rejection.
- ✅ Handle serialization edge cases (circular, BigInt, NaN, -0, undefined, key order).
- ✅ Guard against mutation of cached inputs.
- ✅ Bound memory (LRU / WeakMap).
- ✅ Avoid prototype pollution (use `Map`).
- ✅ Don't memoize impure/time-dependent/random functions.
- ✅ Choose error-caching and TTL/invalidation policy deliberately.

Below is a complete, runnable TypeScript program that demonstrates the main facets of "memory management" in a garbage-collected runtime: **reuse pools**, **weak references / finalization**, **disposable resources**, **weakly-held private state**, **leak avoidance**, and **heap measurement**.

### Prerequisites

```bash
npm init -y
npm i -D typescript tsx @types/node
# Run with GC exposed so we can force collection in demos:
npx tsx --expose-gc memory-mgmt.ts
# or compile then run:
npx tsc memory-mgmt.ts --target es2022 --module nodenext --moduleResolution nodenext --esModuleInterop --skipLibCheck
node --expose-gc memory-mgmt.js
```

### `memory-mgmt.ts`

```ts
// memory-mgmt.ts
// Run: node --expose-gc --import tsx memory-mgmt.ts   (Node 22+)
//   or: npx tsx --expose-gc memory-mgmt.ts

import { EventEmitter } from 'node:events';

/* ------------------------------------------------------------------ *
 * 0. Runtime feature guards                                          *
 * ------------------------------------------------------------------ */
if (typeof Symbol.dispose === 'undefined') {
  (Symbol as any).dispose = Symbol('Symbol.dispose');
}

const gc = (globalThis as any).gc as (() => void) | undefined;
function forceGc(): void {
  gc?.();
}

/* ------------------------------------------------------------------ *
 * 1. Object pool: reuse instead of allocating / collecting            *
 * ------------------------------------------------------------------ */
class ObjectPool<T> {
  private free: T[] = [];
  constructor(
    private factory: () => T,
    private reset?: (o: T) => void,
    initial = 0,
  ) {
    for (let i = 0; i < initial; i++) this.free.push(this.factory());
  }
  acquire(): T {
    const o = this.free.pop();
    return o ?? this.factory();
  }
  release(o: T): void {
    this.reset?.(o);
    this.free.push(o);
  }
  size(): number {
    return this.free.length;
  }
}

/* ------------------------------------------------------------------ *
 * 2. Weak cache: entries do not keep keys/values alive                *
 * ------------------------------------------------------------------ */
class WeakCache<K extends object, V> {
  private map = new WeakMap<K, V>();
  private registry = new FinalizationRegistry<string>((label) => {
    // Observability hook: fires *eventually* after a key is collected.
    // Do NOT rely on timing; only use for metrics / cleanup of side resources.
    // console.debug('collected:', label);
  });

  set(key: K, value: V, label = 'entry'): void {
    this.map.set(key, value);
    this.registry.register(key, label, key); // unregister token = key
  }

  get(key: K): V | undefined {
    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  delete(key: K): boolean {
    this.registry.unregister(key);
    return this.map.delete(key);
  }
}

/* ------------------------------------------------------------------ *
 * 3. WeakRef: hold a value without preventing GC                     *
 * ------------------------------------------------------------------ */
class LazyImage {
  constructor(public src: string) {}
  decode(): Uint8Array {
    // pretend decoding
    return new Uint8Array(1024);
  }
}

class ImageCache {
  private refs = new Map<string, WeakRef<LazyImage>>();
  get(src: string): LazyImage {
    const ref = this.refs.get(src);
    const cached = ref?.deref();
    if (cached) return cached;
    const img = new LazyImage(src);
    this.refs.set(src, new WeakRef(img));
    return img;
  }
  prune(): number {
    let removed = 0;
    for (const [k, ref] of this.refs) {
      if (!ref.deref()) {
        this.refs.delete(k);
        removed++;
      }
    }
    return removed;
  }
}

/* ------------------------------------------------------------------ *
 * 4. Disposable resources: deterministic cleanup via `using`          *
 * ------------------------------------------------------------------ */
class FileHandle implements Disposable {
  private closed = false;
  constructor(public readonly path: string) {}
  write(data: string): void {
    if (this.closed) throw new Error('closed');
    // pretend write
    void data;
  }
  [Symbol.dispose](): void {
    if (this.closed) return;
    this.closed = true;
    console.log(`  [dispose] closed ${this.path}`);
  }
}

/* ------------------------------------------------------------------ *
 * 5. WeakMap-backed private state (no leak, auto-collected)           *
 * ------------------------------------------------------------------ */
const _counterState = new WeakMap<object, { count: number }>();

class Counter {
  constructor() {
    _counterState.set(this, { count: 0 });
  }
  inc(): void {
    _counterState.get(this)!.count++;
  }
  value(): number {
    return _counterState.get(this)!.count;
  }
}

/* ------------------------------------------------------------------ *
 * 6. Leak-avoidance patterns                                         *
 * ------------------------------------------------------------------ */

// 6a. Always pair on/off for emitters; or use AbortSignal.
function makeEmitterUsage(): () => void {
  const emitter = new EventEmitter();
  const handler = (n: number) => {
    void n;
  };
  emitter.on('data', handler);
  // Return a disposer so callers can detach (avoid retaining handler + closure).
  return () => emitter.off('data', handler);
}

// 6b. AbortController to cancel timers / fetches and remove listeners.
function withTimeout(ms: number): AbortController {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  // Remove the timer reference once aborted so it can be GC'd.
  controller.signal.addEventListener('abort', () => clearTimeout(timer), { once: true });
  return controller;
}

// 6c. Avoid capturing large scope in long-lived closures.
function makeProcessor(): (x: number) => number {
  // BAD:  `const big = new Array(1_000_000).fill(0); return x => big[x] + x;`
  // GOOD: keep only what is needed.
  return (x: number) => x * 2 + 1;
}

/* ------------------------------------------------------------------ *
 * 7. Buffer / typed-array pooling (avoid large alloc churn)           *
 * ------------------------------------------------------------------ */
class BufferPool {
  private pool: ArrayBuffer[] = [];
  acquire(minSize: number): ArrayBuffer {
    const idx = this.pool.findIndex((b) => b.byteLength >= minSize);
    if (idx >= 0) return this.pool.splice(idx, 1)[0];
    // Round up to reduce fragmentation.
    const size = 1 << Math.ceil(Math.log2(Math.max(minSize, 64)));
    return new ArrayBuffer(size);
  }
  release(buf: ArrayBuffer): void {
    this.pool.push(buf);
  }
  size(): number {
    return this.pool.length;
  }
}

/* ------------------------------------------------------------------ *
 * 8. Memory measurement                                              *
 * ------------------------------------------------------------------ */
function mem(label: string): void {
  const m = process.memoryUsage();
  console.log(label, {
    rss: `${(m.rss / 1_048_576).toFixed(2)} MB`,
    heapUsed: `${(m.heapUsed / 1_048_576).toFixed(2)} MB`,
    heapTotal: `${(m.heapTotal / 1_048_576).toFixed(2)} MB`,
    external: `${(m.external / 1_048_576).toFixed(2)} MB`,
  });
}

/* ------------------------------------------------------------------ *
 * Demo                                                               *
 * ------------------------------------------------------------------ */
async function main(): Promise<void> {
  mem('start');

  // --- Object pool ---
  const pool = new ObjectPool(
    () => ({ x: 0, y: 0 }),
    (o) => {
      o.x = 0;
      o.y = 0;
    },
    4,
  );
  const pt = pool.acquire();
  pt.x = 7;
  pt.y = 9;
  pool.release(pt);
  console.log('pool free slots:', pool.size());

  // --- Weak cache ---
  const cache = new WeakCache<object, number>();
  let key: { id: number } | null = { id: 1 };
  cache.set(key, 42, 'key-1');
  console.log('weak cache hit:', cache.get(key));
  key = null; // drop strong reference -> eligible for GC
  forceGc();
  await new Promise((r) => setTimeout(r, 50));
  forceGc();

  // --- WeakRef image cache ---
  const images = new ImageCache();
  const img = images.get('a.png');
  console.log('image decoded bytes:', img.decode().byteLength);
  // (img still referenced here; prune later)

  // --- Disposable ---
  console.log('disposable demo:');
  {
    using fh = new FileHandle('report.txt');
    fh.write('hello');
    // [Symbol.dispose] runs at end of block
  }

  // --- Counter (WeakMap state) ---
  const c = new Counter();
  c.inc();
  c.inc();
  console.log('counter:', c.value());

  // --- Emitter cleanup ---
  const disposeEmitter = makeEmitterUsage();
  disposeEmitter();

  // --- AbortController ---
  const ac = withTimeout(10);
  await new Promise((r) => setTimeout(r, 20));
  console.log('aborted:', ac.signal.aborted);

  // --- Buffer pool ---
  const bp = new BufferPool();
  const buf1 = bp.acquire(1000);
  const buf2 = bp.acquire(500);
  bp.release(buf1);
  bp.release(buf2);
  console.log('buffer pool size:', bp.size());

  // --- WeakRef pruning ---
  let tmp: LazyImage | null = images.get('b.png');
  void tmp;
  tmp = null;
  forceGc();
  await new Promise((r) => setTimeout(r, 50));
  console.log('pruned image refs:', images.prune());

  mem('end');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

### What this covers

| Concern | Technique |
|---|---|
| Allocation churn | **Object / buffer pools** (`acquire`/`release`) |
| Caches that shouldn't retain | **`WeakMap`**, **`WeakRef`**, **`FinalizationRegistry`** |
| Deterministic cleanup (files, locks, handles) | **`Disposable` + `using` blocks** (`Symbol.dispose`) |
| Private state without leaking | **`WeakMap<object, State>`** keyed by instance |
| Event/timer leaks | Pair `on`/`off`; **`AbortController`**; remove timers on abort |
| Closure capture leaks | Don't capture large scopes in long-lived callbacks |
| Observability | **`process.memoryUsage()`** + `--expose-gc` for forced collection in tests |

### Notes for production

- **Don't force GC in production.** `--expose-gc` is for diagnostics/benchmarks only.
- **Finalization is non-deterministic.** Never put correctness-critical cleanup there; use `Disposable` / `try…finally` / `using` instead.
- **Weak collections keys must be objects** (not primitives).
- **Node versioning:** `using`/`Symbol.dispose` need a recent V8 (Node 20+ parses it; Node 22+ has full `DisposableStack`). The polyfill guard keeps older runtimes from crashing on `Symbol.dispose` access; if `using` syntax itself is rejected by your engine, compile with `tsc` (it lowers the syntax) and run the emitted JS.
- **Memory profiling:** use `node --inspect`, Chrome DevTools heap snapshots, and `--heap-prof` for real leak hunts; `process.memoryUsage()` only gives coarse deltas.

# Memory Management in TypeScript

TypeScript runs on JavaScript engines (V8, SpiderMonkey, JavaScriptCore), so **memory management is identical to JavaScript**: it is **automatic via garbage collection (GC)**. TypeScript’s type system is erased at compile time and has no runtime effect on memory.

## 1. Core idea

- **No manual free/malloc.** You allocate objects, arrays, closures, etc.; the engine reclaims memory when objects become **unreachable**.
- **Reachability-based GC.** V8 (Node/Chrome) uses a generational collector: young generation (scavenge) for short-lived objects, old generation (mark-sweep/compact) for long-lived ones.
- **Your job is reference hygiene:** avoid keeping unnecessary references so the GC can collect.

TypeScript helps indirectly: strong typing makes leaks easier to spot (e.g., unintended global caches), but the runtime behavior is pure JS.

## 2. Key mechanisms & syntax

### Weak references and cleanup APIs (ES2021+)

```ts
// WeakRef: hold a reference without preventing collection
let big: { data: number[] } | null = { data: new Array(1_000_000).fill(0) };
const ref = new WeakRef(big);

big = null; // object may now be collected
const obj = ref.deref();
if (obj) console.log(obj.data.length); // possibly undefined later
```

```ts
// FinalizationRegistry: run cleanup when an object is collected
const registry = new FinalizationRegistry<string>((heldValue) => {
  console.log("cleaned up:", heldValue);
});

let target: object | null = { id: 42 };
registry.register(target, "resource-42");
target = null; // eventually triggers callback (not deterministic)
```

### WeakMap / WeakSet for caches

```ts
const cache = new WeakMap<object, ExpensiveResult>();

function compute(obj: object): ExpensiveResult {
  if (!cache.has(obj)) {
    cache.set(obj, doHeavyWork(obj));
  }
  return cache.get(obj)!;
}
// When `obj` is no longer referenced elsewhere, both it and its cache entry can be collected.
```

### Explicit resource management (TS 5.2+, ES2024)

For **deterministic cleanup of non-memory resources** (file handles, subscriptions), use `Symbol.dispose` and `using`:

```ts
class Connection implements Disposable {
  close() { /* release socket */ }
  [Symbol.dispose]() { this.close(); }
}

function run() {
  using conn = new Connection();
  // auto-disposed at end of scope, even on throw
}
```

This is about *resource lifetime*, not GC memory, but it complements memory hygiene.

## 3. Common leak patterns and fixes

### a) Forgotten event listeners / timers

```ts
class Widget {
  private controller = new AbortController();

  mount() {
    window.addEventListener("resize", this.onResize, {
      signal: this.controller.signal, // auto-removed on abort
    });
    this.timer = setInterval(() => this.tick(), 1000);
  }

  dispose() {
    this.controller.abort();
    clearInterval(this.timer);
  }
}
```

### b) Closures capturing large scopes

```ts
// Bad: closure keeps `huge` alive
function makeHandler(huge: BigData) {
  return () => console.log(huge.summary); // retains huge
}

// Better: extract only what's needed
function makeHandler(summary: string) {
  return () => console.log(summary);
}
```

### c) Global caches without eviction

```ts
// Bad: unbounded global Map
const globalCache = new Map<string, Data>();

// Better: bounded LRU or WeakMap when keys are objects
import { LRUCache } from "lru-cache";
const cache = new LRUCache<string, Data>({ max: 500 });
```

### d) Detached DOM nodes

```ts
// Bad: JS still references removed node
let node = document.getElementById("x")!;
node.remove();
// `node` keeps the subtree alive

// Fix
node = null as any; // or let it go out of scope
```

## 4. Large data & performance

- Use **typed arrays / ArrayBuffer** for binary data; they are more memory-efficient than arrays of numbers.
- In workers, use **transferable objects** to move buffers without copying:

```ts
const buf = new ArrayBuffer(1024 * 1024);
worker.postMessage(buf, [buf]); // ownership transferred, main thread loses access
```

- Stream large inputs instead of buffering all into memory.

## 5. Debugging memory issues

- **Chrome DevTools → Memory tab:** heap snapshots, allocation timelines, compare snapshots to find retained objects.
- **Node.js:** `node --inspect` + Chrome DevTools; `process.memoryUsage()` for RSS/heap.
- **Flags (dev only):** `--expose-gc` + `global.gc()` to force collection while investigating (never in production).
- Look for **retainers** in heap snapshot: who holds the reference chain.

```ts
console.log(process.memoryUsage());
// { rss, heapTotal, heapUsed, external, arrayBuffers }
```

## 6. TypeScript-specific tips

- Types don’t allocate memory; but **TS enums/const objects** and **decorators** can. Keep an eye on generated JS.
- Avoid `any` that hides accidental global retention.
- Use `noUnusedLocals` / `noUnusedParameters` to catch dead references (compile-time only, but helps hygiene).
- For long-lived singletons, document ownership and disposal paths.

## Summary

| Concern | Approach |
|---|---|
| Allocation | Automatic; engine manages |
| Cleanup trigger | Unreachability (GC) |
| Avoid leaks | Remove listeners, clear timers, null refs, bound caches |
| Object-keyed caches | `WeakMap` |
| Optional cleanup hooks | `FinalizationRegistry` (non-deterministic) |
| Deterministic resource cleanup | `using` + `Symbol.dispose` |
| Large binary data | `ArrayBuffer`, transferables, streaming |

In short: write TypeScript as normal JS, focus on **reference lifetime and cleanup boundaries**, and use Weak collections plus explicit disposal for resources that must be released promptly.

```ts
// ❌ Mistake: a long-lived event listener closes over a large array.
type Row = { id: number; blob: Uint8Array };

function installRowLogger(rows: Row[]) {
  const logSize = () => {
    // `rows` is captured by this closure.
    console.log(`rows: ${rows.length}`);
  };

  // `document` lives for the whole page lifetime, so the listener is
  // effectively permanent. That keeps `logSize` alive, which keeps `rows`
  // alive, which keeps every `blob` alive.
  document.addEventListener("click", logSize);
}
```

### Why this is a memory-management problem

JavaScript/TypeScript memory is managed by a garbage collector (GC). An object can be collected only when **no reachable path** exists from a GC root (global object, DOM, active stack, etc.) to that object.

In the snippet above:

1. `document` is a GC root-ish long-lived object.
2. `document` → event listener list → `logSize` closure.
3. `logSize` closure → its lexical environment → `rows`.
4. `rows` → all `Row` objects → all `Uint8Array` blobs.

So even after the caller drops its reference to `rows`, the closure still holds it. The GC cannot reclaim that memory. If `installRowLogger` is called repeatedly (e.g., per route/component), memory grows without bound.

---

### ✅ Corrected versions

#### Option 1: Avoid capturing the large payload

If you only need a count, store the primitive value, not the array.

```ts
type Row = { id: number; blob: Uint8Array };

function installRowLogger(rowCount: number) {
  const logSize = () => console.log(`rows: ${rowCount}`);
  document.addEventListener("click", logSize);

  // Caller can remove it later if the feature is torn down.
  return () => document.removeEventListener("click", logSize);
}
```

#### Option 2: Keep a removable listener and remove it on teardown

If you genuinely need access to `rows`, keep the listener attached only while the feature is active.

```ts
type Row = { id: number; blob: Uint8Array };

function installRowLogger(rows: Row[]) {
  const logSize = () => console.log(`rows: ${rows.length}`);

  document.addEventListener("click", logSize);

  // Return a cleanup function. Call it when the component/route unmounts.
  return () => document.removeEventListener("click", logSize);
}

// Usage:
const cleanup = installRowLogger(bigRows);
// ... later ...
cleanup(); // releases the closure and allows `bigRows` to be collected
```

#### Option 3: Use `WeakRef` when you want “best-effort” retention

If the listener should survive but must not pin the data, hold the data through a `WeakRef`. The GC may clear it when memory pressure occurs.

```ts
type Row = { id: number; blob: Uint8Array };

function installRowLogger(rowsRef: WeakRef<Row[]>) {
  const logSize = () => {
    const rows = rowsRef.deref();
    if (!rows) {
      console.log("rows were collected");
      return;
    }
    console.log(`rows: ${rows.length}`);
  };

  document.addEventListener("click", logSize);
  return () => document.removeEventListener("click", logSize);
}

// Caller:
const ref = new WeakRef(bigRows);
const cleanup = installRowLogger(ref);
```

#### Option 4: Use a bounded cache instead of an unbounded one

A similar mistake happens with caches. Prefer a size-limited cache, or `WeakMap` when keys are objects and you don’t want to pin them.

```ts
class LruCache<K, V> {
  private map = new Map<K, V>();

  constructor(private maxSize: number) {}

  get(key: K): V | undefined {
    const v = this.map.get(key);
    if (v === undefined) return undefined;
    // Move to end (most recently used).
    this.map.delete(key);
    this.map.set(key, v);
    return v;
  }

  set(key: K, value: V): void {
    if (this.map.has(key)) this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.maxSize) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
  }
}
```

### Key takeaways

- In JS/TS, “memory leaks” are usually **unintended retention**, not missing `free()`.
- Closures capture their entire lexical scope, not just the variables they use. (Engines may optimize, but you should not rely on that.)
- Anything attached to a long-lived object (`document`, `window`, a singleton service) should be explicitly removed during teardown.
- Prefer primitives/ids in long-lived callbacks; keep heavy data in short-lived scopes.
- Use `WeakRef`/`WeakMap` only when you intentionally want GC to be allowed to drop the value.

TypeScript does not have its own memory model. It compiles to JavaScript, so memory management is the JavaScript engine’s garbage collector. Most “TypeScript memory pitfalls” are therefore JavaScript pitfalls that show up in typed code, plus a few TS-specific habits (keeping references alive through closures, typed caches, framework code, etc.).

Below are the most common ones, with idiomatic TypeScript examples.

## 1. Implicit global variables

In non-strict code, assigning to an undeclared variable creates a global property. That object can never be collected.

```ts
// Bad: implicit global in non-strict code
function load(data: BigData) {
  cache = data; // no let/const/var -> global property
}

// Good: explicit binding + strict mode
function load(data: BigData) {
  const cache = data;
  return process(cache);
}
```

Fix: enable `"strict": true` and `"noImplicitAny"` in `tsconfig.json`. Globals are a lifetime leak.

## 2. Closures capturing more than needed

A closure keeps its entire lexical environment alive, even if it only uses one small field.

```ts
function makeLogger(big: { id: string; payload: Uint8Array }) {
  // Bad: captures the whole `big` object, including payload
  return () => console.log(big.id);
}

function makeLoggerFixed(big: { id: string; payload: Uint8Array }) {
  // Good: extract only what the closure needs
  const id = big.id;
  return () => console.log(id);
}
```

This matters for long-lived handlers, cached functions, and event callbacks.

## 3. Event listeners that are never removed

Listeners keep their callback (and everything it closes over) alive for the lifetime of the target.

```ts
class Panel {
  private readonly onResize = () => {
    this.recalculateLayout();
  };

  mount(el: HTMLElement) {
    // Bad if unmount never calls removeEventListener
    window.addEventListener("resize", this.onResize);
  }

  unmount() {
    // Good
    window.removeEventListener("resize", this.onResize);
  }
}
```

Modern pattern with `AbortController`:

```ts
const controller = new AbortController();

window.addEventListener("resize", onResize, { signal: controller.signal });
// later
controller.abort(); // removes listener
```

## 4. Timers and intervals

`setInterval` keeps running until explicitly cleared. Its callback retains scope.

```ts
// Bad
setInterval(() => {
  poll(serverUrl, hugeCache);
}, 5000);

// Good
const timer = setInterval(() => {
  poll(serverUrl);
}, 5000);

// on shutdown / unmount
clearInterval(timer);
```

For one-shot work, prefer `setTimeout` and keep the id so it can be cancelled.

## 5. Detached DOM nodes kept in JavaScript

Removing a node from the document does not free it if JavaScript still references it.

```ts
const detached: HTMLElement[] = [];

function detachButton() {
  const button = document.querySelector("#delete") as HTMLButtonElement;
  button.remove();          // removed from DOM
  detached.push(button);    // still retained by JS
}

// To free it:
detached.length = 0;
```

This is common in virtualized lists, drag-and-drop, and manual DOM caching.

## 6. Strong collections used as caches

`Map` and `Set` keep keys and values alive forever.

```ts
// Bad: unbounded cache
const cache = new Map<string, ParsedData>();

function get(key: string): ParsedData {
  if (!cache.has(key)) cache.set(key, parse(key));
  return cache.get(key)!;
}

// Better for object keys: WeakMap
const metadata = new WeakMap<HTMLElement, Metadata>();
metadata.set(element, meta); // collected when element is collected

// For bounded string-keyed caches, add eviction
class LruCache<K, V> {
  private readonly map = new Map<K, V>();
  constructor(private readonly limit: number) {}

  get(key: K): V | undefined { return this.map.get(key); }

  set(key: K, value: V): void {
    if (this.map.size >= this.limit) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
    this.map.set(key, value);
  }
}
```

Use `WeakMap`/`WeakSet` only when keys are objects and you do not need enumeration.

## 7. Subscriptions not unsubscribed

RxJS, DOM events-as-observables, and custom pub/sub all require cleanup.

```ts
class DataService {
  private readonly sub: Subscription;

  constructor(private readonly source: Observable<Data>) {
    // Bad if `destroy()` is never called
    this.sub = this.source.subscribe((data) => {
      this.state = data;
    });
  }

  destroy() {
    this.sub.unsubscribe();
  }
}
```

With React:

```ts
useEffect(() => {
  const subscription = data$.subscribe(setData);
  return () => subscription.unsubscribe();
}, [data$]);
```

The cleanup function is the memory-management hook.

## 8. Unbounded caches and memoization

Memoizing every input creates a map that grows forever.

```ts
const memo = new Map<number, Result>();

function expensive(n: number): Result {
  if (!memo.has(n)) memo.set(n, compute(n));
  return memo.get(n)!;
}

// Better: bounded memoization or WeakMap for object args
function memoize<T extends (...args: any[]) => any>(fn: T): T {
  const cache = new Map<string, ReturnType<T>>();
  return ((...args: Parameters<T>) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const value = fn(...args);
    if (cache.size > 1000) {
      const first = cache.keys().next().value;
      cache.delete(first);
    }
    cache.set(key, value);
    return value;
  }) as T;
}
```

## 9. Fetch / async work not cancelled

Promises cannot be cancelled, but fetch can be aborted. Long-lived requests retain closures and data.

```ts
function loadUser(id: string, signal: AbortSignal) {
  return fetch(`/users/${id}`, { signal }).then((r) => r.json());
}

// Caller
const controller = new AbortController();
loadUser("42", controller.signal).catch(() => {});

// On unmount / navigation
controller.abort();
```

Also avoid storing every resolved promise in a module-level array.

## 10. `console.log` retaining objects in DevTools

In Chromium-based browsers, objects logged to the console are retained by DevTools until the console is cleared. This can make heap snapshots misleading.

```ts
function debug(big: LargeObject) {
  console.log(big); // retained by DevTools
}

// Better for production diagnostics
console.log(big.id, big.summary); // primitive snapshots
```

Do not treat DevTools as proof of an application leak without testing in a clean profile.

## 11. Workers and message channels not terminated

Workers keep a thread and message ports alive.

```ts
const worker = new Worker(new URL("./worker.ts", import.meta.url));

worker.postMessage({ type: "start" });

// Shutdown
worker.terminate();
```

For `MessageChannel`, close ports:

```ts
const { port1, port2 } = new MessageChannel();
port1.close();
port2.close();
```

## 12. Framework component leaks (React example)

Components retain closures over props/state unless effects are cleaned up.

```tsx
function LiveChart({ source }: { source: Observable<number> }) {
  useEffect(() => {
    const subscription = source.subscribe((value) => {
      setValue(value);
    });

    // Bad: missing cleanup -> leak on unmount
    // return () => subscription.unsubscribe();

    return () => {
      subscription.unsubscribe();
    };
  }, [source]);

  return <div>{value}</div>;
}
```

Also avoid storing large props in context that is consumed by many components.

## 13. Large arrays, buffers, and accidental copies

Retaining a view into a large buffer keeps the whole buffer alive.

```ts
// Bad: slice creates a copy, but if you store the original buffer too, both live
function takeChunk(buffer: ArrayBuffer) {
  const view = new Uint8Array(buffer, 0, 1024);
  cache.push(buffer); // retains entire original buffer
  return view;
}

// Good: store only the chunk view if possible, and release source
function takeChunk(buffer: ArrayBuffer) {
  const copy = new Uint8Array(buffer.slice(0, 1024));
  return copy;
}
```

When done with large arrays:

```ts
largeArray.length = 0; // truncates and allows elements to be collected
// or
largeArray = null as any; // if variable scope is long-lived
```

Use typed arrays (`Uint8Array`, `Float64Array`) for numeric data to avoid boxed number objects.

## 14. Circular references and old-browser patterns

Modern engines collect cycles, but cycles involving external resources (DOM, sockets, native handles) can still delay collection.

```ts
// Usually fine in modern JS:
const a: any = {};
const b: any = {};
a.ref = b;
b.ref = a;

// Avoid attaching JS data to DOM nodes in older environments:
// (element as any).__data = hugeObject;
```

If you must attach data to DOM, use `WeakMap` keyed by the element.

## 15. `WeakRef` and `FinalizationRegistry` for optional caching

These are advanced tools for caches where you want to allow collection but may reuse an object if still alive.

```ts
type Entry = { data: LargeData };

const cache = new Map<string, WeakRef<Entry>>();
const registry = new FinalizationRegistry<string>((key) => {
  cache.delete(key);
});

function get(key: string): LargeData {
  const ref = cache.get(key);
  const entry = ref?.deref();
  if (entry) return entry.data;

  const fresh: Entry = { data: compute(key) };
  cache.set(key, new WeakRef(fresh));
  registry.register(fresh, key);
  return fresh.data;
}
```

Do not use `FinalizationRegistry` for correctness-critical cleanup; it is not guaranteed to run promptly.

## 16. TypeScript-specific cleanup habits

A few TS-shaped mistakes:

```ts
// Bad: keeping a large optional field around forever
class Session {
  token?: string;
  user?: User;
  auditLog?: AuditEntry[]; // grows forever

  logout() {
    this.token = undefined;
    this.user = undefined;
    this.auditLog = undefined; // help GC
  }
}

// Bad: `delete` is slow and changes object shape; reassignment is usually better
delete (obj as any).heavyField;
obj.heavyField = undefined;
```

Also, `const` does not mean immutable or collectable; it only prevents reassignment of the binding.

## Practical debugging checklist

- Enable strict mode; implicit globals are a classic leak.
- Take heap snapshots in Chrome/Firefox DevTools; compare retained sizes.
- Look for `(closure)`, `Detached HTMLDivElement`, and `(array)` in heap profiles.
- Search for `setInterval`, `addEventListener`, and `subscribe` in your codebase.
- Use `performance.measureUserAgentSpecificMemory()` in Chromium for page-level estimates.
- In tests, assert that cleanup functions run (e.g., `expect(unsubscribe).toHaveBeenCalled()`).

The biggest practical rule: **if an object is referenced by a long-lived scope, listener, timer, cache, subscription, or DevTools console, it is not garbage-collectable.** Most fixes are lifecycle cleanup, extraction of needed primitives from closures, bounded caching, and using weak references for non-essential metadata.

## Exercise

You are given a small in-memory session registry. It keeps user sessions alive, listens for global updates, and expires them after a TTL. The current implementation leaks memory:

```ts
class LeakySessionRegistry {
  private sessions = new Map<string, { id: string; payload: unknown }>();
  private emitter = new EventTarget();

  create(id: string, payload: unknown) {
    const session = { id, payload };
    this.sessions.set(id, session);

    // Leak 1: listener is never removed if destroy() is skipped
    this.emitter.addEventListener("update", () => {
      console.log("updated", session.id, session.payload);
    });

    // Leak 2: timer keeps running even after the session object is gone
    setTimeout(() => this.sessions.delete(id), 60_000);
    return session;
  }

  destroy(id: string) {
    this.sessions.delete(id);
  }
}
```

### Task

Refactor it into a `SafeSessionRegistry` that:

1. Does not retain a session after it has expired or been destroyed.
2. Removes event listeners automatically when a session is destroyed or garbage-collected.
3. Cleans up timers.
4. Still allows callers to retrieve a live session by id.
5. Uses `WeakRef` and `FinalizationRegistry` where appropriate.

---

## Step-by-step solution

### Step 1: Identify the leaks

- `sessions: Map<string, session>` holds a **strong reference** to every session.
- The event listener closure captures `session`, so even if the map is cleared, the listener keeps the session alive.
- `setTimeout` is not cleared in `destroy()`, so timers accumulate.
- There is no mechanism for cleanup when a session is garbage-collected externally.

### Step 2: Make session values weakly reachable

Store `WeakRef<Session>` instead of the session itself. The registry can still look up a session by id, but if nothing else references it, the GC may collect it.

```ts
private refs = new Map<string, WeakRef<Session>>();
```

### Step 3: Automate cleanup with `FinalizationRegistry`

When a session object is collected, the registry callback removes its id from all internal maps and aborts its listener.

```ts
private registry = new FinalizationRegistry<string>((id) => {
  this.cleanup(id);
});
```

### Step 4: Tie listeners to an `AbortController`

Instead of manually calling `removeEventListener`, create one `AbortController` per session and pass `{ signal }` to `addEventListener`. Aborting removes the listener and avoids closure-based leaks.

### Step 5: Track and clear timers

Store each timer handle and call `clearTimeout` in `destroy()` / `cleanup()`.

### Step 6: Implement `get()` defensively

`WeakRef.deref()` may return `undefined`. If it does, clean up stale bookkeeping and return `undefined`.

---

## Final solution

```ts
type Session = {
  id: string;
  payload: unknown;
};

export class SafeSessionRegistry {
  private readonly ttlMs: number;
  private readonly emitter = new EventTarget();

  private readonly refs = new Map<string, WeakRef<Session>>();
  private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();
  private readonly controllers = new Map<string, AbortController>();

  private readonly registry = new FinalizationRegistry<string>((id) => {
    this.cleanup(id);
  });

  constructor(ttlMs: number = 60_000) {
    this.ttlMs = ttlMs;
  }

  create(id: string, payload: unknown): Session {
    // Replace any existing session with the same id.
    this.destroy(id);

    const session: Session = { id, payload };
    const ref = new WeakRef(session);

    this.refs.set(id, ref);

    const controller = new AbortController();
    this.controllers.set(id, controller);

    // Listener is automatically removed when controller.abort() is called.
    this.emitter.addEventListener(
      "update",
      (event: Event) => {
        const live = ref.deref();
        if (!live) return;
        console.log("updated", live.id, live.payload, (event as CustomEvent).detail);
      },
      { signal: controller.signal }
    );

    // Register for finalization cleanup. The session object is the registration target.
    this.registry.register(session, id, session);

    const timer = setTimeout(() => this.destroy(id), this.ttlMs);
    // In Node.js, avoid keeping the process alive solely for expiry timers.
    (timer as { unref?: () => void }).unref?.();
    this.timers.set(id, timer);

    return session;
  }

  get(id: string): Session | undefined {
    const ref = this.refs.get(id);
    const session = ref?.deref();

    if (!session) {
      this.cleanup(id);
      return undefined;
    }

    return session;
  }

  destroy(id: string): void {
    const timer = this.timers.get(id);
    if (timer !== undefined) {
      clearTimeout(timer);
      this.timers.delete(id);
    }

    const controller = this.controllers.get(id);
    if (controller) {
      controller.abort();
      this.controllers.delete(id);
    }

    this.refs.delete(id);
  }

  private cleanup(id: string): void {
    // Finalizer-safe cleanup: timers and controllers may already be gone.
    this.destroy(id);
  }

  emitUpdate(detail?: unknown): void {
    this.emitter.dispatchEvent(new CustomEvent("update", { detail }));
  }
}
```

### Usage example

```ts
const registry = new SafeSessionRegistry(30_000);

const s = registry.create("user-1", { role: "admin" });
console.log(registry.get("user-1")); // live session

registry.emitUpdate("refresh");

registry.destroy("user-1");
console.log(registry.get("user-1")); // undefined
```

### Why this is memory-safe

- `WeakRef` allows sessions to be collected once callers drop them.
- `FinalizationRegistry` removes stale bookkeeping after collection.
- `AbortController` removes listeners without needing the original function reference.
- Timers are explicitly cleared.
- `get()` does not accidentally resurrect stale entries.

### Practical memory-debugging tips

- In browsers: take two heap snapshots in Chrome DevTools and compare retained sizes.
- In Node.js: call `process.memoryUsage()` before and after creating many sessions.
- Avoid storing large payloads in closures; capture only ids or small keys.
- Prefer weak collections (`WeakMap`, `WeakSet`, `WeakRef`) for caches keyed by objects.

## Memory management in TypeScript

TypeScript itself does **not** manage memory. It compiles to JavaScript, and memory management happens at runtime in the JavaScript engine (V8 in Node.js/Chrome, SpiderMonkey in Firefox, JavaScriptCore in Safari). The model is:

- **Stack**: primitive values and references (pointers to heap objects) for the current execution context.
- **Heap**: objects, arrays, functions, closures.
- **Garbage collection (GC)**: automatic reclamation of unreachable heap objects.
- **Reachability**: an object is kept alive if it is reachable from a set of roots (global object, current call stack, active closures, etc.).
- **Common GC strategies**:
  - **Mark-and-sweep**: mark all reachable objects, sweep unmarked ones.
  - **Generational GC**: young generation (short-lived) collected frequently and cheaply; old generation collected less often.
  - **Incremental/concurrent GC**: work is split to avoid long pauses.
- **Manual-ish hints in JS/TS**:
  - Drop references (`obj = null`) to make objects unreachable.
  - Use `WeakMap`/`WeakSet`/`WeakRef` so caches don't keep objects alive.
  - Use `FinalizationRegistry` for cleanup callbacks (not deterministic).
- **Common leaks**:
  - Accidental globals
  - Forgotten timers/listeners
  - Closures capturing large scopes
  - Detached DOM nodes (in browsers)

---

## Core implementation: a toy Mark-and-Sweep garbage collector

Below is a simplified, educational implementation of the **core** of mark-and-sweep GC: allocation, reference graph maintenance, root tracking, marking, and sweeping. It is not a real engine, but it demonstrates the algorithm and invariants.

```ts
// gc.ts
// A minimal mark-and-sweep garbage collector for an object graph.
// Real engines add generational, incremental, and concurrent optimizations.

export type ObjId = number;

export interface GCObject {
  id: ObjId;
  /** Outgoing references to other heap objects. */
  refs: Set<ObjId>;
  /** Optional label for debugging / tracing. */
  tag?: string;
}

export class MarkSweepGC {
  private objects = new Map<ObjId, GCObject>();
  private nextId: ObjId = 1;

  /** Root set: objects reachable without following heap references. */
  private roots = new Set<ObjId>();

  /** Allocate a new heap object and return its id. */
  allocate(tag?: string): ObjId {
    const id = this.nextId++;
    this.objects.set(id, { id, refs: new Set(), tag });
    return id;
  }

  /** Add a reference edge from -> to. Idempotent. */
  addReference(from: ObjId, to: ObjId): void {
    const obj = this.mustGet(from);
    if (!this.objects.has(to)) {
      throw new Error(`Reference target ${to} does not exist`);
    }
    obj.refs.add(to);
  }

  /** Remove a reference edge from -> to. */
  removeReference(from: ObjId, to: ObjId): void {
    const obj = this.mustGet(from);
    obj.refs.delete(to);
  }

  /** Register an object as a GC root (e.g., global, stack slot). */
  addRoot(id: ObjId): void {
    if (!this.objects.has(id)) throw new Error(`Unknown object ${id}`);
    this.roots.add(id);
  }

  /** Unregister a root. */
  removeRoot(id: ObjId): void {
    this.roots.delete(id);
  }

  /** Inspect object metadata (useful for tests/debugging). */
  get(id: ObjId): GCObject | undefined {
    return this.objects.get(id);
  }

  /** Number of live objects currently tracked. */
  size(): number {
    return this.objects.size;
  }

  /**
   * MARK phase:
   * Traverse the object graph starting from roots.
   * Returns the set of reachable object ids.
   */
  private mark(): Set<ObjId> {
    const marked = new Set<ObjId>();
    // Iterative DFS to avoid recursion-depth issues on large graphs.
    const stack: ObjId[] = [...this.roots];

    while (stack.length > 0) {
      const id = stack.pop()!;
      if (marked.has(id)) continue;

      const obj = this.objects.get(id);
      if (!obj) continue; // stale root or missing object

      marked.add(id);

      // Push all outgoing references for traversal.
      for (const ref of obj.refs) {
        if (!marked.has(ref)) stack.push(ref);
      }
    }

    return marked;
  }

  /**
   * SWEEP phase:
   * Delete every object not in the marked set.
   * Also clean up roots that pointed to freed objects.
   */
  collect(): { freed: ObjId[]; kept: number } {
    const marked = this.mark();
    const freed: ObjId[] = [];

    for (const id of [...this.objects.keys()]) {
      if (!marked.has(id)) {
        this.objects.delete(id);
        freed.push(id);
      }
    }

    // Remove roots that no longer point to live objects.
    for (const root of [...this.roots]) {
      if (!this.objects.has(root)) this.roots.delete(root);
    }

    return { freed, kept: this.objects.size };
  }

  private mustGet(id: ObjId): GCObject {
    const obj = this.objects.get(id);
    if (!obj) throw new Error(`Unknown object ${id}`);
    return obj;
  }
}
```

### Usage example

```ts
// example.ts
import { MarkSweepGC } from "./gc";

const gc = new MarkSweepGC();

// Allocate objects
const a = gc.allocate("A");
const b = gc.allocate("B");
const c = gc.allocate("C");
const d = gc.allocate("D"); // will become unreachable

// Build reference graph: A -> B -> C
gc.addReference(a, b);
gc.addReference(b, c);

// A is a root; D is not reachable from any root
gc.addRoot(a);

console.log("before collect:", gc.size()); // 4

const result = gc.collect();
console.log("freed:", result.freed); // [4] (D)
console.log("after collect:", gc.size()); // 3

// Drop root A, then collect again -> A, B, C become unreachable
gc.removeRoot(a);
const result2 = gc.collect();
console.log("freed2:", result2.freed); // [1,2,3] (order may vary)
console.log("after collect2:", gc.size()); // 0
```

### Key ideas illustrated

- **Reachability** is computed by graph traversal from roots.
- **Mark** avoids recursion via an explicit stack.
- **Sweep** removes only unmarked objects; marked objects survive.
- **Roots** model stack/global references; removing a root can make an entire subgraph collectible.
- **Cycles** are handled naturally: if a cycle is unreachable from roots, all nodes in it are unmarked and freed.

### Real-world notes

- V8 uses **generational GC**: most objects die young, so minor GCs are fast; long-lived objects are promoted.
- **WeakRef / FinalizationRegistry** let you observe collection without preventing it.
- **WeakMap/WeakSet** keys are held weakly, preventing leaks in caches.
- In TS/JS, you never call `free`; you make objects unreachable and let the engine schedule collection.

This toy implementation captures the conceptual core while staying small, typed, and testable.

TypeScript/JavaScript memory is managed by the host engine’s garbage collector (GC). There is no manual `free`, so “memory management” edge cases are mostly about **unintentional retention**, **weak-reference semantics**, **shared buffers**, **resource lifetimes**, and **engine limits**. Below are the important edge cases with runnable TypeScript examples.

---

## 1. Closures retaining large lexical scopes

A returned inner function keeps its entire enclosing scope alive, not just the variables it uses.

```ts
function makeHandler() {
  const huge = new Array(10_000_000).fill(0); // retained
  const small = 42;
  return () => small; // only uses small, but `huge` may be retained
}

const handler = makeHandler();
// `huge` can remain reachable through the closure's scope chain
```

**Fix:** extract only what is needed, or explicitly drop references.

```ts
function makeHandlerFixed() {
  const huge = new Array(10_000_000).fill(0);
  const result = huge.length;
  // `huge` goes out of scope here
  return () => result;
}
```

---

## 2. Event listeners not removed

An event listener closure can keep a large object graph alive even after the DOM node is removed.

```ts
const data = new Array(1_000_000).fill("x");

const button = document.querySelector<HTMLButtonElement>("#btn")!;
button.addEventListener("click", () => console.log(data.length));

// Later: button removed from DOM, but listener + `data` may stay reachable
// through the element's listener list if something still references `button`.
```

**Modern fix:** use `AbortController`.

```ts
const controller = new AbortController();
button.addEventListener("click", () => console.log(data.length), {
  signal: controller.signal,
});

// Cleanup:
controller.abort(); // removes listener
```

---

## 3. Timers and intervals

`setInterval` callbacks retain their closure indefinitely.

```ts
const cache = new Map<string, number>();

const id = setInterval(() => {
  cache.set(String(Date.now()), Math.random());
}, 1000);

// Memory grows forever unless:
clearInterval(id);
```

---

## 4. Unbounded caches / Maps

A normal `Map` keeps keys and values strongly reachable.

```ts
const cache = new Map<string, unknown>();

function get(key: string) {
  if (!cache.has(key)) cache.set(key, computeExpensive(key));
  return cache.get(key);
}
```

**Fix options:**

- **WeakMap** when keys are objects and can be GC’d:

```ts
const meta = new WeakMap<object, number>();

function attach(obj: object, value: number) {
  meta.set(obj, value); // entry disappears when obj is GC'd
}
```

Edge case: `WeakMap` keys **must be objects**; primitives throw.

```ts
const wm = new WeakMap();
// wm.set("key", 1); // TypeError: Invalid value used as weak map key
```

- **LRU / size-capped cache** when keys are strings/primitives.

---

## 5. WeakRef and FinalizationRegistry are not deterministic

`WeakRef` may return `undefined` after GC. Finalizers may run late or never.

```ts
let obj: { data: number[] } | null = { data: new Array(1_000_000) };

const ref = new WeakRef(obj);
const registry = new FinalizationRegistry((heldValue: string) => {
  console.log("finalized:", heldValue);
});

registry.register(obj, "my-object");
obj = null; // now eligible for GC

// Later:
const deref = ref.deref();
if (deref) {
  console.log("still alive", deref.data.length);
} else {
  console.log("collected");
}
```

**Edge cases:**
- Never rely on finalizers for correctness (e.g., releasing locks, closing files).
- Do not resurrect objects in finalizers as a normal pattern.
- `deref()` can become `undefined` between checks; always re-check.

---

## 6. Circular references

Modern GCs collect unreachable cycles, but leaks happen when part of the cycle is still reachable (global, DOM, closure).

```ts
let a: any = {};
let b: any = {};
a.ref = b;
b.ref = a;

// Collectible if both `a` and `b` become unreachable:
a = null;
b = null;
```

Leak version:

```ts
const root: any = {};
const a: any = {};
const b: any = {};
a.ref = b;
b.ref = a;
root.a = a; // keeps entire cycle alive
```

---

## 7. Typed arrays sharing underlying memory

Views into the same `ArrayBuffer` alias each other.

```ts
const buf = new ArrayBuffer(8);
const u8 = new Uint8Array(buf);
const u32 = new Uint32Array(buf);

u8[0] = 255;
console.log(u32[0]); // affected by byte 0 (endianness-dependent)

// subarray shares memory; slice copies
const sub = u8.subarray(0, 4);
sub[0] = 99; // u8[0] becomes 99

const copy = u8.slice(0, 4);
copy[0] = 0; // u8[0] unchanged
```

**Edge case:** modifying one view unexpectedly changes another. Use `slice` when independence is needed.

---

## 8. Detached / transferred ArrayBuffers

After transfer, the original buffer becomes detached; accessing it throws.

```ts
const buf = new ArrayBuffer(16);

// Transfer (modern API; availability depends on engine version)
const transferred = buf.transfer();
console.log(buf.byteLength); // 0
// new Uint8Array(buf); // TypeError: Cannot perform Construct on a detached ArrayBuffer

// Common transfer path: postMessage with transfer list
// worker.postMessage(buf, [buf]); // buf becomes detached in sender
```

Always treat a buffer as unusable after transfer.

---

## 9. Node.js Buffer specifics

Node `Buffer` pools and slicing can share memory; `allocUnsafe` may expose old data.

```ts
// May contain uninitialized/old memory (security risk)
const unsafe = Buffer.allocUnsafe(1024);

// Zero-filled
const safe = Buffer.alloc(1024);

// Shares underlying memory (like subarray)
const slice = safe.subarray(0, 16);
slice[0] = 1; // safe[0] becomes 1

// Copy explicitly
const copy = Buffer.from(safe.subarray(0, 16));
```

---

## 10. Stack overflow from deep recursion

JS/TS does not guarantee tail-call optimization.

```ts
function recurse(n: number, acc = 0): number {
  if (n <= 0) return acc;
  return recurse(n - 1, acc + n);
}

try {
  recurse(1_000_000); // RangeError: Maximum call stack size exceeded
} catch (e) {
  console.error(e);
}

// Iterative version
function sumTo(n: number): number {
  let acc = 0;
  for (let i = 1; i <= n; i++) acc += i;
  return acc;
}
```

---

## 11. Sparse arrays and huge lengths

`new Array(n)` creates a sparse array with large `length` but no elements; iteration skips holes.

```ts
const arr = new Array(1_000_000); // sparse, small memory for holes
arr[0] = 1;

console.log(arr.length); // 1_000_000
arr.forEach((x) => console.log(x)); // only logs 1

// Dense allocation can be huge
// const dense = new Array(1_000_000).fill(0); // allocates all slots
```

Engine limits: very large allocations can throw `RangeError`.

```ts
try {
  const x = new Array(2 ** 32); // invalid length
} catch (e) {
  console.error(e); // RangeError
}
```

---

## 12. `delete` vs. setting `undefined`

`delete` can deoptimize hidden classes and increase memory churn.

```ts
const obj: Record<string, number> = { a: 1, b: 2 };

// Avoid in hot paths:
delete obj.a;

// Preferred:
obj.a = undefined;
```

If you need true key removal, consider rebuilding the object or using `Map`.

---

## 13. Detached DOM nodes

A removed node remains in memory if referenced.

```ts
let node: HTMLElement | null = document.createElement("div");
document.body.appendChild(node);
document.body.removeChild(node);

// Still retained:
console.log(node.nodeName);

// Release:
node = null;
```

Also avoid closures capturing DOM nodes in long-lived callbacks.

---

## 14. Promise and async retention

Unresolved promises keep their executor closures alive.

```ts
let resolveFn!: (v: number) => void;
const p = new Promise<number>((res) => {
  resolveFn = res; // closure retained until resolved
});

// If resolveFn is never called and p is reachable, memory stays.
// Use AbortController / timeouts to avoid orphaned async work.
```

---

## 15. Web Workers and shared memory

Workers must be terminated; `SharedArrayBuffer` stays alive while any reference exists.

```ts
const worker = new Worker(new URL("./worker.ts", import.meta.url), { type: "module" });

// When done:
worker.terminate(); // frees worker memory

// Shared memory:
const sab = new SharedArrayBuffer(1024);
worker.postMessage(sab); // shared, not copied
// Memory freed only when all references (main + workers) are gone.
```

---

## 16. Resource disposal with `using` (TypeScript 5.2+)

Use the explicit resource management protocol for deterministic cleanup.

```ts
class FileHandle implements Disposable {
  private closed = false;

  constructor(private path: string) {}

  read() {
    if (this.closed) throw new Error("closed");
    return "data";
  }

  [Symbol.dispose]() {
    this.closed = true;
    console.log("disposed", this.path);
  }
}

function processFile() {
  using handle = new FileHandle("a.txt");
  console.log(handle.read());
  // [Symbol.dispose] called automatically at end of scope
}

processFile();
```

Async version:

```ts
class AsyncResource implements AsyncDisposable {
  async [Symbol.asyncDispose]() {
    await new Promise((r) => setTimeout(r, 10));
    console.log("async disposed");
  }
}

async function run() {
  await using res = new AsyncResource();
  // disposed at scope exit, even if exception thrown
}
```

**Edge cases:**
- Disposal runs on exceptions too.
- Nested `using` disposes in reverse order.
- Forgetting `using` and relying on GC/finalizers is unsafe.

---

## 17. Accidental globals (non-strict)

Assigning without declaration creates a global, retaining data.

```ts
function leak() {
  // @ts-ignore
  accidentalGlobal = new Array(1_000_000); // global retention
}

// TypeScript + strict mode / ESM prevents this; always use strict mode.
```

---

## 18. JSON.stringify and circular structures

Not a memory leak, but a common failure when trying to serialize retained graphs.

```ts
const a: any = {};
const b: any = { a };
a.b = b;

try {
  JSON.stringify(a); // TypeError: Converting circular structure to JSON
} catch (e) {
  console.error(e);
}
```

Use a replacer or a library that handles cycles.

---

## 19. Streams and backpressure (Node.js)

Unconsumed or un-destroyed streams can retain buffers.

```ts
import fs from "node:fs";

const stream = fs.createReadStream("huge.bin");

stream.on("data", (chunk) => {
  // process chunk; if slower than read speed, backpressure matters
});

stream.on("error", (err) => {
  stream.destroy(err); // release resources
});

stream.on("end", () => {
  // stream closed; buffers eligible for GC
});
```

---

## 20. Revocable proxies

After revocation, any access throws; references may still exist but are unusable.

```ts
const { proxy, revoke } = Proxy.revocable({ x: 1 }, {});
console.log(proxy.x); // 1
revoke();
try {
  console.log(proxy.x); // TypeError
} catch (e) {
  console.error(e);
}
```

---

### Practical checklist

- Remove listeners/timers or use `AbortController`.
- Prefer `WeakMap`/`WeakRef` for metadata and caches keyed by objects.
- Avoid `delete` in hot code; prefer `Map` or reassignment.
- Copy typed-array data with `slice`/`Buffer.from` when aliasing is dangerous.
- Terminate workers and destroy streams.
- Use `using`/`await using` for deterministic cleanup.
- Never rely on `FinalizationRegistry` for correctness.
- Re-check `WeakRef.deref()` for `undefined`.
- Convert deep recursion to iteration.
- Watch unbounded caches and global references.

These cover the common memory-management pitfalls you will actually hit in TypeScript applications.

Below is a single, runnable TypeScript file that demonstrates several real micro-optimizations, each with a “naive” and an “optimized” version, plus a small benchmark harness. Types are erased at runtime, so the wins come from the same places as in JavaScript (allocation avoidance, stable shapes, hoisting, typed arrays, buffer reuse).

Save as `micro.ts` and run with `npx tsx micro.ts` (or `npx ts-node micro.ts`).

```ts
// micro.ts
// Run: npx tsx micro.ts

// ---------- Helpers ----------
function bench(label: string, fn: () => number, iters = 2000): void {
  // Warm up so V8 can optimize (and de-opt) before measuring.
  for (let i = 0; i < 100; i++) fn();
  const times: number[] = [];
  for (let r = 0; r < 9; r++) {
    const t0 = performance.now();
    let acc = 0;
    for (let i = 0; i < iters; i++) acc += fn();
    // Prevent the compiler from deleting the work.
    if (acc === Number.NaN) console.log(acc);
    times.push(performance.now() - t0);
  }
  times.sort((a, b) => a - b);
  console.log(`${label.padEnd(28)} median ${times[4].toFixed(2)} ms`);
}

// ---------- 1. Allocation avoidance + hoisting + typed arrays ----------
// Naive: grows arrays, recomputes mean inside the loop, allocates closures.
function naiveVariance(input: number[]): number {
  const transformed: number[] = [];
  for (let i = 0; i < input.length; i++) {
    // new closure per element (bad)
    const t = ((v: number) => v * 2 + 1)(input[i]);
    transformed.push(t);
  }
  let mean = 0;
  for (let i = 0; i < transformed.length; i++) mean += transformed[i];
  mean /= transformed.length;

  let v = 0;
  for (let i = 0; i < transformed.length; i++) {
    const d = transformed[i] - mean;
    v += d * d;
  }
  return v / transformed.length;
}

// Optimized: typed input, reused scratch buffer, inlined transform, hoisted mean.
function optimizedVariance(input: Float64Array, scratch: Float64Array): number {
  const n = input.length;          // cache length
  const arr = input;               // cache reference
  const buf = scratch;             // reuse, no allocation

  let sum = 0;
  for (let i = 0; i < n; i++) {
    const t = arr[i] * 2 + 1;     // inlined, no closure
    buf[i] = t;
    sum += t;
  }
  const mean = sum / n;            // computed once, hoisted out of 2nd loop

  let v = 0;
  for (let i = 0; i < n; i++) {
    const d = buf[i] - mean;
    v += d * d;
  }
  return v / n;
}

// ---------- 2. Stable object shapes (hidden classes) ----------
// Bad: shape changes after creation -> deoptimizes.
function makePointBad(x: number, y: number, tag?: string) {
  const p: any = { x, y };
  if (tag) p.tag = tag; // conditional property -> new hidden class
  return p;
}

// Good: always same shape; optional fields initialized up front.
function makePointGood(x: number, y: number, tag: string | null = null) {
  return { x, y, tag };
}

// ---------- 3. Avoid `delete` (use Map or set to undefined) ----------
function dictBad(): number {
  const o: Record<string, number> = { a: 1, b: 2, c: 3 };
  delete o.b; // deoptimizes, changes shape
  return o.a + (o.c ?? 0);
}
function dictGood(): number {
  const m = new Map<string, number>([["a", 1], ["b", 2], ["c", 3]]);
  m.delete("b"); // Map.delete is designed for this
  return (m.get("a") ?? 0) + (m.get("c") ?? 0);
}

// ---------- 4. Hoist regex + reset lastIndex ----------
const RE_DIGITS = /\d+/g; // compiled once
function countDigitsBad(s: string): number {
  const re = /\d+/g; // recompiled every call
  let n = 0;
  while (re.exec(s)) n++;
  return n;
}
function countDigitsGood(s: string): number {
  RE_DIGITS.lastIndex = 0;
  let n = 0;
  while (RE_DIGITS.exec(s)) n++;
  return n;
}

// ---------- 5. Bulk copy with TypedArray.set ----------
function copyBad(src: number[], dst: number[]): void {
  for (let i = 0; i < src.length; i++) dst[i] = src[i];
}
function copyGood(src: Float64Array, dst: Float64Array): void {
  dst.set(src); // single native call
}

// ---------- 6. Avoid splice-in-loop (O(n^2)) ----------
function removeBad(arr: number[], value: number): number[] {
  const a = arr.slice();
  for (let i = 0; i < a.length; i++) {
    if (a[i] === value) a.splice(i--, 1); // O(n) each
  }
  return a;
}
function removeGood(arr: number[], value: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] !== value) out.push(arr[i]);
  }
  return out;
}

// ---------- Benchmark data ----------
const N = 200_000;
const dataNums = Array.from({ length: N }, (_, i) => (i * 37) % 1000);
const dataTyped = new Float64Array(dataNums);
const scratch = new Float64Array(N);
const sampleStr = "a1b23c456d7890".repeat(1000);

console.log("=== micro-optimization benchmarks ===");
bench("naiveVariance", () => naiveVariance(dataNums));
bench("optimizedVariance", () => optimizedVariance(dataTyped, scratch));

// Object shape micro (small, just timing construction)
bench("makePointBad", () => {
  let s = 0;
  for (let i = 0; i < 1000; i++) s += makePointBad(i, i, i % 2 ? "t" : undefined).x;
  return s;
});
bench("makePointGood", () => {
  let s = 0;
  for (let i = 0; i < 1000; i++) s += makePointGood(i, i, i % 2 ? "t" : null).x;
  return s;
});

bench("dictBad", () => dictBad());
bench("dictGood", () => dictGood());

bench("countDigitsBad", () => countDigitsBad(sampleStr));
bench("countDigitsGood", () => countDigitsGood(sampleStr));

// copy
const srcArr = dataNums;
const dstArr = new Array(N);
const srcTyped = dataTyped;
const dstTyped = new Float64Array(N);
bench("copyBad", () => { copyBad(srcArr, dstArr); return dstArr[0]; });
bench("copyGood", () => { copyGood(srcTyped, dstTyped); return dstTyped[0]; });

// remove
const removeInput = Array.from({ length: 5000 }, (_, i) => i % 7);
bench("removeBad", () => removeBad(removeInput, 3).length);
bench("removeGood", () => removeGood(removeInput, 3).length);

console.log("\nDone.");
```

### What each optimization does (and why)

1. **Allocation avoidance** — `transformed.push(...)` grows and reallocates; reusing a `Float64Array` scratch buffer removes per-call allocation and GC pressure. Typed arrays also store unboxed doubles, so no boxing.
2. **Hoisting invariants** — `mean` was recomputed conceptually inside work; computing it once and caching `length`/references avoids repeated property lookups and megamorphic access.
3. **Inlining small transforms** — avoids creating a closure per element (closures allocate and capture scope).
4. **Stable object shapes** — V8 (and SpiderMonkey) use hidden classes; adding properties conditionally creates new shapes and deoptimizes. Initialize all fields up front (use `null` instead of `undefined`-conditional).
5. **Avoid `delete`** — `delete` changes an object's shape and is slow; use `Map` for dynamic key sets, or set to `undefined` if shape stability matters less.
6. **Hoist regex** — `new RegExp`/literal inside a function can recompile; module-level constant + `lastIndex = 0` reuse.
7. **Bulk native copy** — `TypedArray.prototype.set` is a single C++ call vs. a JS loop.
8. **Avoid `splice` in loops** — `splice` is O(n), making removal O(n²); filter into a new array is O(n).
9. **TS-specific notes** — types are erased, so annotations don't help runtime. Prefer `import type` for type-only imports (smaller emit), avoid `enum` in hot paths (emits an object; use string unions or `as const` objects), and avoid decorators/`reflect-metadata` in tight loops.

### Practical guidance

- Measure first (`performance.now`, or `process.hrtime.bigint` in Node). Micro-opts only matter in hot paths; elsewhere they hurt readability.
- Don't fight the engine: modern V8 inlines small functions and optimizes loops well. Prefer clarity, then profile.
- Watch for **deopts**: `try/catch` around hot code, `arguments`, `with`, `eval`, and changing object shapes are common causes (use `--trace-deopt` in Node).
- For real throughput work, consider Web Workers / worker threads, SIMD (where available), and streaming instead of micro-tweaks.

# Micro-optimizations in TypeScript

Micro-optimizations are small, localized changes meant to squeeze out performance—either **runtime** (faster execution, less memory) or **compile-time** (faster `tsc`, smaller bundles). In TypeScript they split into two layers: **JavaScript-level** (because TS compiles to JS) and **TypeScript-specific** (type system & emit).

> ⚠️ Important caveat: modern engines (V8, SpiderMonkey) and bundlers already optimize most "micro" tricks. Many classic JS micro-opts are now myths. Measure with a profiler before applying.

---

## 1. The idea

- **Runtime**: reduce work inside hot loops—fewer property lookups, allocations, and branch mispredictions.
- **Compile-time / bundle**: erase types cheaply, inline constants, avoid shipping unused code.
- **Type-checking**: keep types shallow so `tsc` doesn't explode on complex conditional/mapped types.

Trade-off: readability vs. speed. Apply only to **measured hot paths**.

---

## 2. Syntax & patterns

### A. TypeScript-specific emit optimizations

**Type-only imports/exports** — erased entirely, no runtime module cost:
```ts
import type { User } from './types';
export type { User };
```

**`const enum`** — inlined at compile time (no runtime object):
```ts
const enum Dir { Up = 0, Down = 1 }
const d = Dir.Up; // compiles to: const d = 0;
```
> ⚠️ With `isolatedModules` (required by esbuild/swc/babel), `const enum` across files is unsafe—prefer `as const` objects or plain constants.

**`as const`** — narrows literals at compile time, zero runtime cost:
```ts
const ROUTES = ['/home', '/about'] as const;
type Route = typeof ROUTES[number]; // '/home' | '/about'
```

### B. Runtime hot-loop micro-optimizations

**Cache length & property access:**
```ts
// slower: re-reads .length and .items each iteration
for (let i = 0; i < arr.length; i++) sum += arr[i].value;

// faster: hoist lookups
const items = arr;
const n = items.length;
for (let i = 0; i < n; i++) sum += items[i].value;
```

**Local variable for repeated method/property:**
```ts
const push = out.push.bind(out);
for (const x of data) push(transform(x));
```

**Avoid `Array.prototype` methods in tight loops** (they allocate callbacks):
```ts
// slower
const doubled = arr.map(x => x * 2);

// faster in hot path (and avoids intermediate array if you mutate)
const n = arr.length;
for (let i = 0; i < n; i++) arr[i] *= 2;
```

**Typed arrays for numeric data:**
```ts
const buf = new Float64Array(1_000_000);
for (let i = 0; i < buf.length; i++) buf[i] = i * 0.5;
```

**Bitwise truncation** (JS-level; use with care—only works for 32-bit ints):
```ts
const i = (x / 2) | 0;   // truncates toward zero
// vs Math.floor(x / 2)   // slower historically; V8 now often equal
```

**Object shape stability** (V8 hidden classes): initialize all properties in constructor in same order:
```ts
class Point {
  x: number;
  y: number;
  constructor(x: number, y: number) {
    this.x = x;
    this.y = y; // always same order → stable hidden class
  }
}
```

### C. Type-checking performance (compile-time micro-opts)

**Prefer `interface` over `type` for object shapes** (better caching/memoization in `tsc`):
```ts
interface User { id: number; name: string; }   // preferred
type User = { id: number; name: string; };     // works, slightly slower in large codebases
```

**Avoid deep recursive conditional types** in hot type paths:
```ts
// expensive
type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;

// cheaper: limit depth or use a library utility
```

**Use `import type`** to prevent accidental runtime imports of type-only modules (helps bundlers tree-shake):
```ts
import type { Config } from './config';
```

### D. Bundle / module micro-optimizations

**Avoid barrel files** (`index.ts` re-exporting everything) — they defeat tree-shaking:
```ts
// bad: import { a } from './barrel' pulls all exports
// good: import { a } from './a'
```

**`sideEffects: false`** in `package.json` lets bundlers drop unused exports.

---

## 3. Typical use cases

| Use case | Technique |
|---|---|
| Parsing millions of CSV rows | Typed arrays + manual `for` loop + cached length |
| Game loop / animation frame | Stable object shapes, avoid allocations, reuse buffers |
| Large monorepo type-check | `interface`, shallow types, `skipLibCheck`, project references |
| Library shipping | `import type`, `sideEffects`, avoid `const enum` cross-file |
| Hot API serialization | Pre-allocate arrays, avoid `.map`/`.filter` chains |

---

## 4. What NOT to do (myths)

```ts
// Myth: ++i is faster than i++  → V8 optimizes both equally
// Myth: `!!x` vs `Boolean(x)` matters → no
// Myth: string concat with + vs template literals → negligible
// Myth: deleting properties is "free" → actually deopts hidden class
delete obj.temp; // bad: breaks hidden class; prefer obj.temp = undefined
```

---

## 5. A balanced example

```ts
// Before: readable but allocates
function sumValues(items: { value: number }[]): number {
  return items.reduce((a, b) => a + b.value, 0);
}

// After: micro-optimized hot path (only if profiled as bottleneck)
function sumValues(items: { value: number }[]): number {
  const n = items.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += items[i].value;
  return sum;
}
```

**Bottom line:** micro-optimize only after profiling; prefer algorithmic improvements (O(n) → O(1)) and let the JIT handle the rest. TypeScript's biggest "micro" wins are usually **type-only imports**, **const enums/as const**, and **avoiding barrel files**—all compile-time, zero runtime risk.

```ts
type Point = { x: number; y: number };

// Mistake: reusing one object to "avoid allocations"
function normalizePoints(points: Point[]): Point[] {
  const result: Point[] = [];
  const temp: Point = { x: 0, y: 0 };

  for (const p of points) {
    const len = Math.hypot(p.x, p.y);
    temp.x = p.x / len;
    temp.y = p.y / len;
    result.push(temp); // same reference pushed every time
  }

  return result;
}
```

```ts
type Point = { x: number; y: number };

// Corrected: create a fresh object per result; handle zero-length vectors
function normalizePoints(points: Point[]): Point[] {
  const result: Point[] = [];

  for (const p of points) {
    const len = Math.hypot(p.x, p.y);
    if (len === 0) {
      result.push({ x: 0, y: 0 });
      continue;
    }
    result.push({
      x: p.x / len,
      y: p.y / len,
    });
  }

  return result;
}
```

What was wrong:

- `result.push(temp)` stores the **same object reference** on every iteration. Because `temp` is mutated in place, every element of `result` ends up pointing to the final normalized vector. This is an aliasing bug caused by trying to micro-optimize allocations.
- The original also divides by `len` without checking for `0`, producing `NaN`/`Infinity` for zero-length input points.
- Modern JavaScript engines (V8, SpiderMonkey, JavaScriptCore) are very good at optimizing short-lived object allocations. Removing an allocation here usually saves far less than the cost of debugging a shared-state bug. If allocation truly becomes a bottleneck, that should be proven with profiling first; even then, a correct pooling strategy must clone or reset values before reuse.
- The corrected version prioritizes correctness and clarity: each result is an independent object, edge cases are handled explicitly, and the code remains easy for the engine and humans to reason about.

## Most common micro-optimization pitfalls in TypeScript

Micro-optimizations in TypeScript are especially tricky because TypeScript types are erased at runtime. Many “optimizations” only change compile-time behavior, while the actual runtime bottleneck is usually in the emitted JavaScript, V8 optimization decisions, memory allocation, or I/O/layout.

Below are common pitfalls, with bad/good code examples.

---

### 1. Measuring without accounting for JIT warmup and dead code elimination

V8 compiles code in tiers. The first run can be much slower or faster than steady state. Also, if a benchmark result is unused, V8 may remove the work.

**Bad:**

```ts
function sum(a: number[], b: number[]): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] + b[i];
  return s;
}

const a = Array.from({ length: 10_000 }, (_, i) => i);
const b = Array.from({ length: 10_000 }, (_, i) => i + 1);

const t0 = performance.now();
for (let i = 0; i < 100; i++) sum(a, b); // result is ignored
console.log(performance.now() - t0);
```

**Better:**

```ts
function bench(label: string, fn: () => number, iterations = 100_000) {
  // Warmup
  for (let i = 0; i < 1_000; i++) fn();

  const t0 = performance.now();
  let checksum = 0;
  for (let i = 0; i < iterations; i++) checksum += fn();
  const dt = performance.now() - t0;

  // Prevent dead-code elimination and make timing meaningful
  if (!Number.isFinite(checksum)) throw new Error("bad checksum");
  console.log(label, dt, "ms");
}

bench("sum", () => sum(a, b));
```

Also vary inputs. A function optimized for one shape or number range may deoptimize on another.

---

### 2. Confusing TypeScript types with runtime behavior

TypeScript types do not exist at runtime. Branded types, interfaces, generics, and type guards’ static narrowing have no direct runtime cost, but adding runtime checks to “enforce” types can.

**Bad: forcing runtime checks everywhere**

```ts
type UserId = string & { readonly __brand: "UserId" };

function processUserId(id: UserId) {
  if (typeof id !== "string") throw new Error("not a string"); // redundant
  return id.length;
}
```

**Better: validate at boundaries, trust internally**

```ts
type UserId = string & { readonly __brand: "UserId" };

function toUserId(raw: string): UserId {
  if (!raw.startsWith("u_")) throw new Error("invalid user id");
  return raw as UserId;
}

// Internal hot path assumes already validated
function processUserId(id: UserId) {
  return id.length;
}
```

---

### 3. Assuming `readonly`, `const`, or `as const` optimize runtime code

`readonly` is compile-time only. `const` on a binding does not make an object immutable, and `as const` does not freeze anything at runtime.

**Bad:**

```ts
interface Config {
  readonly host: string;
  readonly port: number;
}

const config: Config = { host: "localhost", port: 3000 };
// config.port = 4000; // compile-time error only
(config as any).port = 4000; // allowed at runtime
```

**Bad: freezing in a hot path**

```ts
function makePoint(x: number, y: number) {
  return Object.freeze({ x, y }); // freeze cost on every call
}
```

**Better: freeze once, or avoid freeze if not needed**

```ts
const POINT_ZERO = Object.freeze({ x: 0, y: 0 });

function makePoint(x: number, y: number) {
  return { x, y }; // normal object; mutate carefully by convention
}
```

---

### 4. Creating hidden-class churn by changing object shapes

V8 uses hidden classes. Adding properties conditionally, deleting properties, or initializing properties in different orders creates multiple shapes and deoptimizes property access.

**Bad:**

```ts
function makeRecord(x: number) {
  const o: any = {};
  o.id = x;
  if (x > 0) o.label = "positive"; // conditional property
  if (x < 0) delete o.id;          // delete creates slow dictionary mode
  return o;
}
```

**Better: fixed shape, consistent order**

```ts
interface RecordLike {
  id: number | undefined;
  label: string | undefined;
}

function makeRecord(x: number): RecordLike {
  return {
    id: x >= 0 ? x : undefined,
    label: x > 0 ? "positive" : undefined,
  };
}
```

If you need optional fields, still define them in the same order for all objects. Avoid `delete`; set to `undefined` or create a new object.

---

### 5. Sparse or mixed-type arrays

Holes and mixed values make arrays slower and larger. V8 tracks element kinds; a holey or object-backed array is less efficient than a packed numeric array.

**Bad:**

```ts
const a = new Array<number>(10_000);
a[0] = 1;
a[9_999] = 2; // holey array

const b = [1, 2, 3];
b.push("x"); // element kind generalizes to tagged/object-ish
```

**Better:**

```ts
const a = new Array(10_000).fill(0);
a[0] = 1;
a[9_999] = 2;

const b = [1, 2, 3]; // keep numeric-only

// For numeric hot paths:
const c = new Float64Array(10_000);
```

If values must be mixed, consider separate arrays or a typed structure instead of one polymorphic array.

---

### 6. Polymorphic property access and “god” helper functions

A function that operates on many different object shapes becomes megamorphic. V8 cannot optimize property access as well.

**Bad:**

```ts
function area(shape: any) {
  return shape.width * shape.height;
}

area({ width: 2, height: 3 });
area({ width: 4, height: 5, radius: 1 }); // different shape
area({ w: 1, h: 2 }); // different property names
```

**Better: monomorphic fast paths or specialized functions**

```ts
interface Rect { kind: "rect"; width: number; height: number; }
interface Square { kind: "square"; size: number; }

function rectArea(r: Rect) {
  return r.width * r.height;
}

function squareArea(s: Square) {
  return s.size * s.size;
}

function area(shape: Rect | Square) {
  switch (shape.kind) {
    case "rect": return rectArea(shape);
    case "square": return squareArea(shape);
  }
}
```

Discriminated unions also make the runtime branch predictable and type-safe.

---

### 7. Using `delete`, dynamic keys, or changing prototype

`delete` often moves an object into dictionary mode. Adding arbitrary keys at runtime can also deoptimize.

**Bad:**

```ts
const cache: Record<string, number> = {};
cache[key] = value;
delete cache[key]; // slow and shape-changing
```

**Better for dynamic keys: `Map`**

```ts
const cache = new Map<string, number>();
cache.set(key, value);
cache.delete(key);
```

For a small fixed set of keys, a normal object is usually faster. For arbitrary or frequently added/removed keys, use `Map`.

---

### 8. Repeated expensive property access, getters, or proxies

Getters and proxies execute code every access. Repeatedly calling them in a loop can dominate runtime.

**Bad:**

```ts
class Data {
  get expensiveValue() {
    return heavyCompute();
  }
}

const total = items.reduce((s, item) => s + item.expensiveValue, 0);
```

**Better: cache once per iteration or restructure**

```ts
for (const item of items) {
  const v = item.expensiveValue; // one access
  // use v multiple times
}
```

Avoid proxies in hot paths. They block many optimizations and add trap overhead.

---

### 9. Allocating functions inside loops

Creating closures or binding functions repeatedly allocates memory and can worsen GC pressure.

**Bad:**

```ts
for (const item of items) {
  button.addEventListener("click", () => handle(item)); // new function each loop
}
```

**Better: delegation or pre-bound handlers**

```ts
function handleClick(event: Event) {
  const target = event.currentTarget as HTMLButtonElement;
  const id = target.dataset.id;
  if (id) handle(id);
}

for (const button of buttons) {
  button.addEventListener("click", handleClick);
}
```

If you need per-item state, store it on the element or use a WeakMap instead of closures.

---

### 10. Using `arguments` or unstable parameter shapes

The legacy `arguments` object can be slower and complicates optimization. Mutating parameters can also deoptimize in some engines.

**Bad:**

```ts
function total() {
  let s = 0;
  for (let i = 0; i < arguments.length; i++) s += arguments[i];
  return s;
}
```

**Better: rest parameters and explicitarity**

```ts
function total(...values: number[]) {
  let s = 0;
  for (const v of values) s += v;
  return s;
}
```

For extremely hot functions, fixed parameters can be faster than rest arrays.

---

### 11. Put `eval`, `with`, or dynamic code in hot functions

`eval`, `with`, and runtime code generation can prevent or invalidate optimizations. Even if not directly in the loop, they can affect function-level optimization.

**Bad:**

```ts
function getValue(obj: any, key: string) {
  return eval(`obj.${key}`); // unsafe and slow
}
```

**Better:**

```ts
function getValue(obj: Record<string, unknown>, key: string) {
  return obj[key];
}
```

Avoid `with`. Avoid assigning to parameters in ways that create `arguments` aliasing. Keep hot functions simple and statically analyzable.

---

### 12. TypeScript enums where `const enum` or union literals are better

Regular enums compile to runtime objects. That adds an extra property lookup and can increase bundle size. `const enum` inlines values at compile time.

**Bad:**

```ts
enum Status {
  Active = 1,
  Inactive = 2,
}

function isActive(s: Status) {
  return s === Status.Active; // Status.Active becomes object lookup
}
```

**Better when using `tsc`:**

```ts
const enum Status {
  Active = 1,
  Inactive = 2,
}

function isActive(s: Status) {
  return s === Status.Active; // inlined to 1
}
```

**Caveat:** `const enum` requires TypeScript-aware compilation. Bundlers such as Babel or SWC may not inline it unless configured. A portable alternative is a frozen constants object plus a union type:

```ts
const Status = {
  Active: 1,
  Inactive: 2,
} as const;

type Status = (typeof Status)[keyof typeof Status];

function isActive(s: Status) {
  return s === Status.Active;
}
```

This still has one object lookup but is module-safe and tree-shakeable.

---

### 13. Compiling to an old target unnecessarily

Old targets cause helpers and downleveling. `for...of` over arrays may become iterator helpers, classes become constructor functions, spread becomes `concat`, etc.

**Bad `tsconfig.json`:**

```json
{
  "compilerOptions": {
    "target": "es5",
    "module": "commonjs"
  }
}
```

**Better for modern runtimes:**

```json
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "importHelpers": true
  }
}
```

Use `importHelpers: true` with `tslib` to avoid duplicating helpers. Only downlevel as much as your actual deployment requires.

---

### 14. Overusing object spread and array chaining

Spread and functional chaining are readable but allocate intermediate objects/arrays. In hot loops, this increases GC pressure.

**Bad:**

```ts
const result = items
  .filter(x => x.active)
  .map(x => ({ id: x.id, value: x.value * 2 }))
  .sort((a, b) => a.value - b.value);
```

**Better when measured necessary:**

```ts
const result: { id: number; value: number }[] = [];
for (const x of items) {
  if (!x.active) continue;
  result.push({ id: x.id, value: x.value * 2 });
}
result.sort((a, b) => a.value - b.value);
```

Do not mutate shared input arrays unless the API explicitly allows it. If you mutate, document ownership carefully.

---

### 15. Object pooling without measurement

Pooling can reduce GC pauses, but it can also retain memory, hide bugs, and make code harder. Modern generational GC is often better for short-lived objects.

**Bad:**

```ts
const pool: Point[] = [];

function acquirePoint() {
  return pool.pop() ?? { x: 0, y: 0 };
}

function releasePoint(p: Point) {
  p.x = 0;
  p.y = 0;
  pool.push(p); // may retain large graph if not reset fully
}
```

**Better: only pool when profiled and bounded**

```ts
class PointPool {
  private pool: Point[] = [];
  acquire(x = 0, y = 0): Point {
    const p = this.pool.pop();
    if (p) { p.x = x; p.y = y; return p; }
    return { x, y };
  }
  release(p: Point) {
    p.x = 0;
    p.y = 0;
    if (this.pool.length < 1024) this.pool.push(p);
  }
}
```

Set a maximum pool size and always reset all fields, including nested references.

---

### 16. Creating regexes or parsers repeatedly

Regex literals in loops may be reused by engines, but explicit construction and stateful `g`/`y` regexes are common bugs and can be slow.

**Bad:**

```ts
for (const line of lines) {
  if (/ERROR:\s*(.+)/.test(line)) { // hoisted by engine maybe, but not guaranteed/readable
    // ...
  }
}

const re = /x/g;
re.lastIndex = 0;
for (const s of strings) {
  re.test(s); // lastIndex state leaks across iterations
}
```

**Better:**

```ts
const errorRe = /ERROR:\s*(.+)/;

for (const line of lines) {
  const m = errorRe.exec(line);
  if (m) handle(m[1]);
}

// For global regexes, reset lastIndex or avoid stateful flags
const tokenRe = /token/g;
for (const s of strings) {
  tokenRe.lastIndex = 0;
  while (tokenRe.exec(s)) { /* ... */ }
}
```

---

### 17. Non-null assertions (`!`) hiding undefined in hot paths

`!` is erased. It does not remove a runtime check; it just stops the compiler from warning. Undefined values can become `NaN`, corrupted state, or slower deoptimized paths.

**Bad:**

```ts
function total(values: number[]) {
  let s = 0;
  for (let i = 0; i <= values.length; i++) { // off-by-one
    s += values[i]!; // no runtime validation
  }
  return s;
}
```

**Better: validate and narrow once**

```ts
function total(values: readonly number[]) {
  let s = 0;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v === undefined) continue; // or throw
    s += v;
  }
  return s;
}
```

If bounds are guaranteed, keep the loop simple and correct rather than adding assertions.

---

### 18. Assuming `Map` is always faster than objects

Objects are very fast for small fixed schemas. `Map` is better for dynamic keys, frequent deletion, or non-string keys. The wrong choice can hurt cache locality and memory.

**Bad for fixed small config:**

```ts
const config = new Map<string, number>();
config.set("width", 800);
config.set("height", 600);
const w = config.get("width"); // hash lookup
```

**Better:**

```ts
const config = { width: 800, height: 600 } as const;
const w = config.width; // direct property
```

**Bad for arbitrary runtime keys with deletion:**

```ts
const cache: Record<string, number> = {};
cache[key] = value;
delete cache[key];
```

**Better:**

```ts
const cache = new Map<string, number>();
cache.set(key, value);
cache.delete(key);
```

---

### 19. Modern class features with hidden costs

TC39 private fields (`#x`), decorators, accessors, and complex inheritance add wrappers and sometimes slower property access. They are often fine, but avoid them in the hottest paths unless measured.

**Potential pitfall:**

```ts
class Point {
  #x = 0;
  #y = 0;

  get x() { return this.#x; }
  set x(v: number) { this.#x = v; }
}
```

**Simpler hot-path representation:**

```ts
interface Point {
  x: number;
  y: number;
}

function distance(a: Point, b: Point) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.hypot(dx, dy);
}
```

Use classes where encapsulation helps; use plain objects/functions where raw property access matters and is profiled.

---

### 20. Browser-specific layout thrashing

In browser TypeScript code, repeatedly reading layout properties between writes forces synchronous layout.

**Bad:**

```ts
for (const el of elements) {
  const h = el.offsetHeight; // read
  el.style.height = `${h + 10}px`; // write
}
```

**Better: batch reads, then writes**

```ts
const heights = elements.map(el => el.offsetHeight);
elements.forEach((el, i) => {
  el.style.height = `${heights[i] + 10}px`;
});
```

For many updates, consider `requestAnimationFrame`, virtualization, or off-DOM construction.

---

## Practical checklist

Before micro-optimizing TypeScript:

1. **Measure first** with realistic data and warmup.
2. **Check the emitted JavaScript**, not only TypeScript source.
3. **Keep object shapes stable**; avoid `delete` and conditional properties.
4. **Use typed arrays** for numeric hot paths.
5. **Prefer monomorphic functions** over one generic helper for many shapes.
6. **Avoid per-iteration allocations** when GC is the bottleneck.
7. **Choose `Map` vs object based on key dynamism.**
8. **Set `target`/`module` appropriately** and use `importHelpers`.
9. **Do not freeze/pool/proxy unless profiled.**
10. **Keep type-only optimizations separate from runtime code.**

The biggest meta-pitfall is optimizing syntax instead of measuring. In modern TypeScript/V8 code, clarity plus a stable object model usually beats clever micro-tricks.

## Exercise

**Task:** Optimize the following TypeScript function that processes a large array of integers and returns the sum of the squares of all even numbers.

```ts
// Baseline (naïve) implementation
function sumSquaresOfEvens(nums: number[]): number {
  return nums
    .filter((n) => n % 2 === 0)
    .map((n) => n * n)
    .reduce((acc, v) => acc + v, 0);
}
```

**Constraints / goals**
- Input: `number[]` with up to ~10⁷ elements.
- Output: a single `number`.
- You may change the algorithm and loop style, but not the semantics.
- Measure with a benchmark, not just intuition.

---

## Step-by-step optimization

### Step 1 — Remove intermediate allocations

**Problem:** `filter` + `map` allocate two new arrays. For 10⁷ elements that’s ~160 MB of temporary arrays plus GC pressure.

**Fix:** Do it in one pass.

```ts
function v1(nums: number[]): number {
  let sum = 0;
  for (const n of nums) {
    if (n % 2 === 0) sum += n * n;
  }
  return sum;
}
```

**Gain:** Eliminates allocations; usually the biggest single win.

---

### Step 2 — Use an indexed loop with a cached length

**Problem:** `for...of` uses an iterator protocol. It’s clean, but an index loop can be slightly faster in hot numeric code because it avoids iterator object creation and gives the JIT more direct access to the backing store.

**Fix:** Cache `nums.length` so the property isn’t re-read each iteration.

```ts
function v2(nums: number[]): number {
  let sum = 0;
  const len = nums.length;
  for (let i = 0; i < len; i++) {
    const n = nums[i];
    if (n % 2 === 0) sum += n * n;
  }
  return sum;
}
```

---

### Step 3 — Hoist the element into a local and avoid repeated property reads

Already partially done in `v2` by reading `nums[i]` once into `n`. Also avoid recomputing `n * n` twice (not an issue here, but a good habit).

---

### Step 4 — Replace `% 2 === 0` with a bitwise test (for safe integers)

**Problem:** `%` is a relatively expensive operation compared to bitwise `&`. For values that are safe integers (within `Number.MAX_SAFE_INTEGER`), `(n & 1) === 0` is equivalent and cheaper.

```ts
function v3(nums: number[]): number {
  let sum = 0;
  const len = nums.length;
  for (let i = 0; i < len; i++) {
    const n = nums[i];
    if ((n & 1) === 0) sum += n * n;
  }
  return sum;
}
```

**Caveat:** Only valid for integers. If your data contains non-integers or values outside the safe-integer range, keep `% 2 === 0`.

---

### Step 5 — Consider loop unrolling / `while` (optional, often negligible today)

Some engines prefer `while` with a decrementing counter because it compiles to a single comparison:

```ts
function v4(nums: number[]): number {
  let sum = 0;
  let i = nums.length;
  while (i--) {
    const n = nums[i];
    if ((n & 1) === 0) sum += n * n;
  }
  return sum;
}
```

**Note:** This changes iteration order (doesn’t matter for a sum). Modern V8 often makes this a wash; measure before committing.

---

### Step 6 — (Optional) Typed arrays if data is truly numeric

If you control the input, store it as `Int32Array` / `Float64Array`. Indexing a typed array avoids boxing and can be faster:

```ts
function v5(nums: Int32Array): number {
  let sum = 0;
  const len = nums.length;
  for (let i = 0; i < len; i++) {
    const n = nums[i];
    if ((n & 1) === 0) sum += n * n;
  }
  return sum;
}
```

