// src/ports.ts
export interface Order {
  id: string;
  userId: string;
  total: number;       // in cents
  status: "pending" | "paid" | "shipped";
}

export interface OrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

export interface PaymentGateway {
  charge(userId: string, amountCents: number): Promise<{ ok: boolean; txnId?: string }>;
}

export interface Notifier {
  send(userId: string, message: string): Promise<void>;
}
```

### `src/order-service.ts` — system under test

```ts
// src/order-service.ts
import type { OrderRepository, PaymentGateway, Notifier, Order } from "./ports.js";

export class OrderService {
  constructor(
    private readonly repo: OrderRepository,
    private readonly payments: PaymentGateway,
    private readonly notifier: Notifier,
  ) {}

  /** Pay for an order; on success mark paid + notify user. */
  async pay(orderId: string): Promise<{ success: boolean; txnId?: string }> {
    const order = await this.repo.findById(orderId);
    if (!order) return { success: false };
    if (order.status !== "pending") return { success: false };

    const result = await this.payments.charge(order.userId, order.total);
    if (!result.ok) return { success: false };

    const paid: Order = { ...order, status: "paid" };
    await this.repo.save(paid);
    await this.notifier.send(order.userId, `Order ${orderId} paid: ${result.txnId}`);
    return { success: true, txnId: result.txnId };
  }
}
```

### `src/in-memory-repo.ts` — a *fake*

```ts
// src/in-memory-repo.ts
import type { Order, OrderRepository } from "./ports.js";

export class InMemoryOrderRepository implements OrderRepository {
  private store = new Map<string, Order>();

  seed(order: Order) { this.store.set(order.id, { ...order }); }

  async findById(id: string): Promise<Order | null> {
    const o = this.store.get(id);
    return o ? { ...o } : null;
  }

  async save(order: Order): Promise<void> {
    this.store.set(order.id, { ...order });
  }

  // test helper (not part of the interface)
  all(): Order[] { return [...this.store.values()]; }
}
```

### `test/order-service.test.ts` — all four doubles + vitest mocks

```ts
// test/order-service.test.ts
import { describe, it, expect, vi, beforeEach } from "vitest";
import { OrderService } from "../src/order-service.js";
import { InMemoryOrderRepository } from "../src/in-memory-repo.js";
import type { Order, PaymentGateway, Notifier } from "../src/ports.js";

// Reusable fixture
const sampleOrder: Order = { id: "o1", userId: "u1", total: 5000, status: "pending" };

describe("OrderService.pay", () => {
  // ---------- 1. FAKE: real-ish in-memory implementation ----------
  it("marks order as paid and persists via fake repository", async () => {
    const repo = new InMemoryOrderRepository();
    repo.seed(sampleOrder);

    // stub payment gateway: always succeeds
    const payments: PaymentGateway = {
      charge: async () => ({ ok: true, txnId: "txn-123" }),
    };
    // stub notifier: no-op
    const notifier: Notifier = { send: async () => {} };

    const svc = new OrderService(repo, payments, notifier);
    const res = await svc.pay("o1");

    expect(res).toEqual({ success: true, txnId: "txn-123" });
    expect(repo.all()).toEqual([{ ...sampleOrder, status: "paid" }]);
  });

  // ---------- 2. STUB: canned answers, no verification ----------
  it("returns failure when payment gateway declines", async () => {
    const repo: OrderRepository = {
      findById: async () => sampleOrder,
      save: async () => {},
    };
    const payments: PaymentGateway = {
      charge: async () => ({ ok: false }),   // canned decline
    };
    const notifier: Notifier = { send: async () => {} };

    const svc = new OrderService(repo, payments, notifier);
    const res = await svc.pay("o1");

    expect(res).toEqual({ success: false });
  });

  // ---------- 3. SPY: records calls for later assertion ----------
  it("notifies the user with txn id on success", async () => {
    const repo: OrderRepository = {
      findById: async () => sampleOrder,
      save: async () => {},
    };
    const payments: PaymentGateway = {
      charge: async () => ({ ok: true, txnId: "txn-999" }),
    };

    const sent: Array<{ userId: string; message: string }> = [];
    const notifier: Notifier = {
      send: async (userId, message) => { sent.push({ userId, message }); },
    };

    const svc = new OrderService(repo, payments, notifier);
    await svc.pay("o1");

    expect(sent).toEqual([{ userId: "u1", message: "Order o1 paid: txn-999" }]);
  });

  // ---------- 4. MOCK (vitest): verify interactions ----------
  it("charges the correct amount and saves exactly once", async () => {
    const repo = {
      findById: vi.fn().mockResolvedValue(sampleOrder),
      save: vi.fn().mockResolvedValue(undefined),
    };
    const payments = {
      charge: vi.fn().mockResolvedValue({ ok: true, txnId: "t" }),
    };
    const notifier = { send: vi.fn().mockResolvedValue(undefined) };

    const svc = new OrderService(repo as any, payments as any, notifier as any);
    await svc.pay("o1");

    expect(payments.charge).toHaveBeenCalledWith("u1", 5000);
    expect(repo.save).toHaveBeenCalledTimes(1);
    expect(repo.save).toHaveBeenCalledWith({ ...sampleOrder, status: "paid" });
    expect(notifier.send).toHaveBeenCalledOnce();
  });

  // ---------- edge cases ----------
  it("returns failure for unknown order (no charge attempted)", async () => {
    const repo = { findById: vi.fn().mockResolvedValue(null), save: vi.fn() };
    const payments = { charge: vi.fn() };
    const notifier = { send: vi.fn() };

    const svc = new OrderService(repo as any, payments as any, notifier as any);
    const res = await svc.pay("missing");

    expect(res).toEqual({ success: false });
    expect(payments.charge).not.toHaveBeenCalled();
  });

  it("does not notify when payment declines", async () => {
    const repo = {
      findById: vi.fn().mockResolvedValue(sampleOrder),
      save: vi.fn(),
    };
    const payments = { charge: vi.fn().mockResolvedValue({ ok: false }) };
    const notifier = { send: vi.fn() };

    const svc = new OrderService(repo as any, payments as any, notifier as any);
    await svc.pay("o1");

    expect(repo.save).not.toHaveBeenCalled();
    expect(notifier.send).not.toHaveBeenCalled();
  });

  it("rejects double-payment (idempotency guard)", async () => {
    const alreadyPaid: Order = { ...sampleOrder, status: "paid" };
    const repo = { findById: vi.fn().mockResolvedValue(alreadyPaid), save: vi.fn() };
    const payments = { charge: vi.fn() };
    const notifier = { send: vi.fn() };

    const svc = new OrderService(repo as any, payments as any, notifier as any);
    const res = await svc.pay("o1");

    expect(res).toEqual({ success: false });
    expect(payments.charge).not.toHaveBeenCalled();
  });
});
```

> Note: the `OrderRepository` type needs to be imported in the test file's stub example. Add:
> `import type { OrderRepository } from "../src/ports.js";`

