### 2. `src/mvc.ts` – full implementation

```ts
import { EventEmitter } from "events";
import * as readline from "readline";

/* ------------------------------------------------------------------ */
/*  MODEL                                                             */
/* ------------------------------------------------------------------ */

export interface Todo {
  id: number;
  title: string;
  done: boolean;
}

/**
 * The model owns the state and the rules.
 * It never knows about views or controllers.
 * It only announces that something changed.
 */
export class TodoModel extends EventEmitter {
  private todos: Todo[] = [];
  private nextId = 1;

  getAll(): Todo[] {
    // Return a copy so callers cannot mutate internal state.
    return this.todos.map((t) => ({ ...t }));
  }

  add(title: string): Todo {
    const trimmed = title.trim();
    if (!trimmed) throw new Error("Title cannot be empty");

    const todo: Todo = { id: this.nextId++, title: trimmed, done: false };
    this.todos.push(todo);
    this.emit("change");
    return { ...todo };
  }

  toggle(id: number): void {
    const todo = this.todos.find((t) => t.id === id);
    if (!todo) throw new Error(`Todo ${id} not found`);
    todo.done = !todo.done;
    this.emit("change");
  }

  remove(id: number): void {
    const index = this.todos.findIndex((t) => t.id === id);
    if (index === -1) throw new Error(`Todo ${id} not found`);
    this.todos.splice(index, 1);
    this.emit("change");
  }

  clearCompleted(): number {
    const before = this.todos.length;
    this.todos = this.todos.filter((t) => !t.done);
    const removed = before - this.todos.length;
    if (removed > 0) this.emit("change");
    return removed;
  }
}

/* ------------------------------------------------------------------ */
/*  VIEW                                                              */
/* ------------------------------------------------------------------ */

/**
 * The view knows how to render state and how to report errors.
 * It subscribes to the model but never mutates it.
 */
export class ConsoleView {
  constructor(private readonly model: TodoModel) {
    this.model.on("change", () => this.render());
  }

  render(): void {
    const todos = this.model.getAll();
    console.clear();
    console.log("=== TODO LIST (MVC demo) ===");
    if (todos.length === 0) {
      console.log("(empty)");
    } else {
      for (const t of todos) {
        console.log(`[${t.done ? "x" : " "}] ${t.id}. ${t.title}`);
      }
    }
    console.log("");
    console.log("Commands: add <text> | toggle <id> | remove <id> | clear | quit");
  }

  showError(message: string): void {
    console.error(`⚠  ${message}`);
  }

  showInfo(message: string): void {
    console.log(`ℹ  ${message}`);
  }
}

/* ------------------------------------------------------------------ */
/*  CONTROLLER                                                        */
/* ------------------------------------------------------------------ */

/**
 * The controller translates raw user input into model operations
 * and decides when the view should be told about problems.
 */
export class TodoController {
  constructor(
    private readonly model: TodoModel,
    private readonly view: ConsoleView
  ) {}

  handle(commandLine: string): boolean {
    const [cmd, ...rest] = commandLine.trim().split(/\s+/);
    const arg = rest.join(" ");

    try {
      switch (cmd) {
        case "add":
          if (!arg) throw new Error("Usage: add <text>");
          this.model.add(arg);
          break;

        case "toggle": {
          const id = Number(arg);
          if (Number.isNaN(id)) throw new Error("Usage: toggle <id>");
          this.model.toggle(id);
          break;
        }

        case "remove": {
          const id = Number(arg);
          if (Number.isNaN(id)) throw new Error("Usage: remove <id>");
          this.model.remove(id);
          break;
        }

        case "clear": {
          const n = this.model.clearCompleted();
          this.view.showInfo(`Removed ${n} completed item(s).`);
          break;
        }

        case "quit":
        case "exit":
          return false; // signal to stop the loop

        case "":
          break;

        default:
          throw new Error(`Unknown command: ${cmd}`);
      }
    } catch (err) {
      this.view.showError(err instanceof Error ? err.message : String(err));
    }

    return true;
  }
}

/* ------------------------------------------------------------------ */
/*  BOOTSTRAP / DEMO                                                  */
/* ------------------------------------------------------------------ */

function main(): void {
  const model = new TodoModel();
  const view = new ConsoleView(model);
  const controller = new TodoController(model, view);

  // Seed some data so the first render is interesting.
  model.add("Learn TypeScript");
  model.add("Implement MVC");
  model.toggle(1);

  // Interactive REPL
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: "> ",
  });

  rl.prompt();
  rl.on("line", (line) => {
    const keepGoing = controller.handle(line);
    if (!keepGoing) {
      rl.close();
      return;
    }
    rl.prompt();
  });

  rl.on("close", () => {
    console.log("Goodbye!");
    process.exit(0);
  });
}

// Only run when executed directly (not when imported as a module).
if (require.main === module) {
  main();
}
```

