### 5. Browser variant (sketch)

If you want the same structure in a browser, keep the classes identical and only swap the view:

```ts
class DomView {
  constructor(private model: TodoModel, private root: HTMLElement) {
    this.model.on("change", () => this.render());
    this.render();
  }
  render() {
    const items = this.model.getAll();
    this.root.innerHTML = items
      .map((t) => `<li data-id="${t.id}">${t.done ? "✔" : "○"} ${t.title}</li>`)
      .join("");
  }
}
```

The controller then wires DOM events (`click`, `submit`) to `model.add/toggle/remove`, exactly as the readline loop does above.

# Model–View–Controller (MVC) in TypeScript

## 1. The Idea

MVC splits an application into three roles so that **data**, **presentation**, and **input handling** evolve independently:

| Role | Responsibility | Typical TS form |
|------|----------------|-----------------|
| **Model** | Data + business rules + persistence | Classes, interfaces, repositories |
| **View** | Rendering / UI only | Components, templates, DOM updates |
| **Controller** | Receives input, calls model, selects view | Route handlers, event handlers |

**Data flow (classic):**
```
User input → Controller → Model (mutate) → Controller → View (render) → User
```

TypeScript adds **compile-time contracts**: interfaces define what each layer expects, so refactors are safer and IDEs can autocomplete across layers.

---

## 2. A Minimal, Complete Example (Node/Console)

Below is a tiny “Todo” app. It runs in Node and demonstrates the wiring.

### Model
```ts
// model.ts
export interface Task {
  id: number;
  title: string;
  done: boolean;
}

export class TaskModel {
  private tasks: Task[] = [];
  private nextId = 1;

  add(title: string): Task {
    const task: Task = { id: this.nextId++, title, done: false };
    this.tasks.push(task);
    return task;
  }

  toggle(id: number): void {
    const t = this.tasks.find(x => x.id === id);
    if (t) t.done = !t.done;
  }

  all(): readonly Task[] {
    return this.tasks;
  }
}
```

### View
```ts
// view.ts
import { Task } from "./model";

export class TaskView {
  render(tasks: readonly Task[]): void {
    console.clear();
    console.log("=== TODO LIST ===");
    tasks.forEach(t =>
      console.log(`${t.id}. [${t.done ? "x" : " "}] ${t.title}`)
    );
    console.log("=================\n");
  }

  prompt(): string {
    // In a real app this could be readline or DOM events
    return "add Buy milk | toggle 1 | quit";
  }
}
```

### Controller
```ts
// controller.ts
import { TaskModel } from "./model";
import { TaskView } from "./view";

export class TaskController {
  constructor(
    private readonly model: TaskModel,
    private readonly view: TaskView
  ) {}

  handle(command: string): boolean {
    const [action, ...rest] = command.split(" ");
    const arg = rest.join(" ");

    switch (action) {
      case "add":
        this.model.add(arg);
        break;
      case "toggle": {
        const id = Number(arg);
        if (Number.isNaN(id)) return true;
        this.model.toggle(id);
        break;
      }
      case "quit":
        return false;
      default:
        console.log("Unknown command");
    }

    this.view.render(this.model.all());
    return true;
  }
}
```

### Wiring (Entry Point)
```ts
// main.ts
import { TaskModel } from "./model";
import { TaskView } from "./view";
import { TaskController } from "./controller";

const model = new TaskModel();
const view = new TaskView();
const controller = new TaskController(model, view);

view.render(model.all());

// Simulated command loop (replace with readline in production)
const commands = ["add Buy milk", "add Write code", "toggle 1", "quit"];
for (const cmd of commands) {
  console.log(`> ${cmd}`);
  if (!controller.handle(cmd)) break;
}
```

**Why this is “TypeScript-y”:**
- `readonly Task[]` prevents the view from mutating model data.
- Constructor injection keeps layers decoupled and testable.
- `Task` interface is the single source of truth shared by all layers.

---

## 3. MVC in a Web/Express Context

A very common TS stack is **Express + a template engine + an ORM**.

```ts
// user.controller.ts
import { Request, Response } from "express";
import { UserService } from "./user.service"; // Model layer

export class UserController {
  constructor(private readonly service: UserService) {}

  async list(req: Request, res: Response): Promise<void> {
    const users = await this.service.findAll();
    res.render("users/index", { users }); // View = EJS/Pug template
  }

  async create(req: Request, res: Response): Promise<void> {
    await this.service.create(req.body);
    res.redirect("/users");
  }
}
```

```ts
// routes.ts
import { Router } from "express";
import { UserController } from "./user.controller";
import { UserService } from "./user.service";

const router = Router();
const controller = new UserController(new UserService());

router.get("/users", (req, res) => controller.list(req, res));
router.post("/users", (req, res) => controller.create(req, res));
export default router;
```

Here:
- **Model** = `UserService` + database entities.
- **View** = template files (`users/index.ejs`).
- **Controller** = `UserController` methods.

---

## 4. Frontend MVC-ish Patterns

Pure MVC is less common in modern SPAs, but the *idea* survives:

| Framework | MVC-ish mapping |
|-----------|-----------------|
| **React** | Components = View; hooks/custom hooks = Controller; state/stores = Model |
| **Vue** | `<template>` = View; `<script setup>` = Controller; Pinia store = Model |
| **Angular** | Templates = View; Component class = Controller; Services = Model |

Example (React + TS) keeping layers explicit:

```tsx
// model: types + API client
export interface Product { id: string; name: string; price: number; }
export const productApi = {
  list: (): Promise<Product[]> => fetch("/api/products").then(r => r.json()),
};

// controller: custom hook
export function useProducts() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    productApi.list().then(p => { setProducts(p); setLoading(false); });
  }, []);

  return { products, loading };
}

// view: component
export function ProductList() {
  const { products, loading } = useProducts();
  if (loading) return <p>Loading…</p>;
  return <ul>{products.map(p => <li key={p.id}>{p.name}</li>)}</ul>;
}
```

---

## 5. Typical Use Cases

1. **Server-rendered web apps** (Express/NestJS + templates) — classic MVC.
2. **Desktop apps** (Electron + TS) — views are HTML, controllers handle IPC.
3. **Game dev** (Phaser/Three.js) — model = game state, view = renderers, controller = input.
4. **CLI tools** — model = domain logic, view = terminal output, controller = arg parsing.
5. **API backends** — controllers = route handlers, models = services/ORM, “view” = JSON serializer.

---

## 6. Practical Tips for TypeScript

- **Define shared interfaces** in a `types/` folder; import into all layers.
- **Keep views “dumb”**: they should receive data and emit events, not call services directly.
- **Inject dependencies** via constructors; this makes unit testing with mocks trivial.
- **Use `readonly` and `as const`** to enforce unidirectional data flow.
- **Separate DTOs from domain models** when crossing boundaries (API ↔ DB).
- **Consider MVVM or Clean Architecture** if state becomes complex; MVC is a starting point, not a religion.

---

## 7. When *Not* to Use Strict MVC

- Highly interactive UIs where the controller/view boundary blurs (prefer component-based or MVVM).
- Micro-frontends where state is shared across apps (prefer a store like Redux/Zustand).
- Tiny scripts — the ceremony isn’t worth it.

---

### Quick Recap

MVC in TypeScript is mostly about **contracts + separation**:
- **Model** = typed data + rules.
- **View** = typed props/templates.
- **Controller** = typed handlers wiring them together.

The compiler then guarantees that a change in the model’s shape surfaces as type errors in the view and controller before runtime.

## Typical mistake

A common MVC mistake is letting each layer “reach into” the others: the model generates HTML, the view asks the model for markup, the controller reads DOM fields directly, performs persistence, and shows alerts. This makes the code hard to test and hard to change.

### Mistaken version

```ts
type Profile = { name: string; email: string };

class ProfileModel {
  constructor(public name: string, public email: string) {}

  // Wrong: the model knows about presentation.
  toCardHtml(): string {
    return `
      <section class="profile">
        <h2>${this.name}</h2>
        <p>${this.email}</p>
      </section>
    `;
  }

  // Wrong: persistence is mixed into the domain model.
  save(): void {
    localStorage.setItem("profile", JSON.stringify(this));
  }

  // Domain rule is okay here, but it is bundled with view/persistence concerns.
  update(name: string, email: string): void {
    if (!email.includes("@")) {
      throw new Error("Invalid email");
    }
    this.name = name;
    this.email = email;
  }
}

class ProfileView {
  constructor(private root: HTMLElement) {}

  // Wrong: the view delegates rendering to the model's HTML.
  render(model: ProfileModel): void {
    this.root.innerHTML = model.toCardHtml();
  }
}

class ProfileController {
  constructor(private model: ProfileModel, private view: ProfileView) {}

  onSaveClick(): void {
    // Wrong: controller knows specific DOM input IDs.
    const name = (document.getElementById("name") as HTMLInputElement).value;
    const email = (document.getElementById("email") as HTMLInputElement).value;

    this.model.update(name, email);
    this.model.save();          // Wrong: controller/model handle persistence directly
    this.view.render(this.model);
    alert("Saved!");            // Wrong: presentation feedback in controller
  }
}
```

Problems:

1. **Model contains presentation logic** via `toCardHtml()`.  
   The model should represent domain state and rules, not HTML.

2. **Model contains persistence logic** via `save()`.  
   Persistence is usually a separate concern, such as a repository or service.

3. **View depends on model-generated markup**.  
   The view should map plain data to DOM, not ask the model how it should look.

4. **Controller is coupled to DOM details and presentation feedback**.  
   It reads specific input IDs and calls `alert()`. That makes it hard to test and reuse.

---

## Corrected version

```ts
type Profile = { name: string; email: string };

// Model: state + domain rules only.
class ProfileModel {
  constructor(private profile: Profile) {}

  get current(): Readonly<Profile> {
    return this.profile;
  }

  update(next: Profile): void {
    if (!next.name.trim()) {
      throw new Error("Name is required");
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(next.email)) {
      throw new Error("Email is invalid");
    }
    this.profile = next;
  }
}

// Persistence is separated behind an interface.
interface ProfileRepository {
  save(profile: Profile): void;
}

class LocalStorageProfileRepository implements ProfileRepository {
  save(profile: Profile): void {
    localStorage.setItem("profile", JSON.stringify(profile));
  }
}

// View: owns DOM rendering and UI event capture.
class ProfileView {
  private root: HTMLElement;
  private submitHandler?: (profile: Profile) => void;

  constructor(root: HTMLElement) {
    this.root = root;

    this.root.addEventListener("submit", (event) => {
      event.preventDefault();
      const form = event.target as HTMLFormElement;
      const data = new FormData(form);

      this.submitHandler?.({
        name: String(data.get("name") ?? ""),
        email: String(data.get("email") ?? ""),
      });
    });
  }

  onSubmit(handler: (profile: Profile) => void): void {
    this.submitHandler = handler;
  }

  render(profile: Readonly<Profile>): void {
    this.root.innerHTML = `
      <form>
        <input name="name" value="${escapeHtml(profile.name)}" required />
        <input name="email" type="email" value="${escapeHtml(profile.email)}" required />
        <button type="submit">Save</button>
      </form>
      <output>Saved as ${escapeHtml(profile.name)} &lt;${escapeHtml(profile.email)}&gt;</output>
    `;
  }

  showError(message: string): void {
    const node = document.createElement("p");
    node.className = "error";
    node.textContent = message;
    this.root.append(node);
  }
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

// Controller: coordinates model, view, and repository. No DOM querying.
class ProfileController {
  constructor(
    private model: ProfileModel,
    private view: ProfileView,
    private repository: ProfileRepository,
  ) {
    this.view.onSubmit((profile) => this.save(profile));
    this.view.render(this.model.current);
  }

  private save(profile: Profile): void {
    try {
      this.model.update(profile);
      this.repository.save(this.model.current);
      this.view.render(this.model.current);
    } catch (error) {
      this.view.showError(error instanceof Error ? error.message : "Unknown error");
    }
  }
}

// Composition root
const appRoot = document.getElementById("app");
if (appRoot) {
  new ProfileController(
    new ProfileModel({ name: "", email: "" }),
    new ProfileView(appRoot),
    new LocalStorageProfileRepository(),
  );
}
```

