## Core implementation

```ts
// model.ts
export interface Todo {
  id: number;
  text: string;
  done: boolean;
}

/**
 * Model: pure state + domain operations.
 * Notifies subscribers (usually the View) after every change.
 */
export class TodoModel {
  private todos: Todo[] = [];
  private listeners = new Set<() => void>();
  private nextId = 1;

  getAll(): readonly Todo[] {
    return this.todos;
  }

  add(text: string): void {
    const trimmed = text.trim();
    if (!trimmed) return; // simple validation lives in the model

    // immutable update makes change detection and debugging easier
    this.todos = [...this.todos, { id: this.nextId++, text: trimmed, done: false }];
    this.notify();
  }

  toggle(id: number): void {
    this.todos = this.todos.map((todo) =>
      todo.id === id ? { ...todo, done: !todo.done } : todo
    );
    this.notify();
  }

  remove(id: number): void {
    this.todos = this.todos.filter((todo) => todo.id !== id);
    this.notify();
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener); // unsubscribe
  }

  private notify(): void {
    for (const listener of this.listeners) listener();
  }
}
```

```ts
// view.ts
import { Todo } from "./model";

export interface TodoViewHandlers {
  onAdd: (text: string) => void;
  onToggle: (id: number) => void;
  onRemove: (id: number) => void;
}

/**
 * View: renders state and translates DOM events into semantic callbacks.
 * It never mutates the model directly.
 */
export class TodoView {
  private form: HTMLFormElement;
  private input: HTMLInputElement;
  private list: HTMLUListElement;

  constructor(container: HTMLElement, private handlers: TodoViewHandlers) {
    container.innerHTML = `
      <form class="todo-form">
        <input class="todo-input" type="text" placeholder="New todo" aria-label="New todo" />
        <button type="submit">Add</button>
      </form>
      <ul class="todo-list"></ul>
    `;

    this.form = container.querySelector(".todo-form") as HTMLFormElement;
    this.input = container.querySelector(".todo-input") as HTMLInputElement;
    this.list = container.querySelector(".todo-list") as HTMLUListElement;

    this.bindEvents();
  }

  render(todos: readonly Todo[]): void {
    this.list.innerHTML = todos
      .map(
        (todo) => `
        <li data-id="${todo.id}" class="${todo.done ? "done" : ""}">
          <button class="toggle" type="button" aria-pressed="${todo.done}">
            ${todo.done ? "✓" : "○"}
          </button>
          <span class="text">${escapeHtml(todo.text)}</span>
          <button class="remove" type="button" aria-label="Remove">×</button>
        </li>
      `
      )
      .join("");
  }

  private bindEvents(): void {
    this.form.addEventListener("submit", (event) => {
      event.preventDefault();
      this.handlers.onAdd(this.input.value);
      this.input.value = "";
      this.input.focus();
    });

    // Event delegation keeps us from re-binding listeners on every render.
    this.list.addEventListener("click", (event) => {
      const target = event.target as HTMLElement;
      const item = target.closest("li[data-id]") as HTMLLIElement | null;
      if (!item) return;

      const id = Number(item.dataset.id);
      if (target.matches(".toggle")) this.handlers.onToggle(id);
      if (target.matches(".remove")) this.handlers.onRemove(id);
    });
  }
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}
```

```ts
// controller.ts
import { TodoModel } from "./model";
import { TodoView } from "./view";

/**
 * Controller: owns the wiring between Model and View.
 * It contains no DOM selectors and no business rules—only coordination.
 */
export class TodoController {
  private readonly model = new TodoModel();
  private readonly view: TodoView;

  constructor(root: HTMLElement) {
    this.view = new TodoView(root, {
      onAdd: (text) => this.handleAdd(text),
      onToggle: (id) => this.handleToggle(id),
      onRemove: (id) => this.handleRemove(id),
    });

    // initial paint
    this.view.render(this.model.getAll());

    // model changes -> view re-render
    this.model.subscribe(() => this.view.render(this.model.getAll()));
  }

  private handleAdd(text: string): void {
    this.model.add(text);
  }

  private handleToggle(id: number): void {
    this.model.toggle(id);
  }

  private handleRemove(id: number): void {
    this.model.remove(id);
  }
}
```

```ts
// main.ts
import { TodoController } from "./controller";

const root = document.getElementById("app");
if (!root) throw new Error("Missing #app container");

new TodoController(root);
```

### Notes you can mention in an interview
- **Immutability in the Model** makes debugging and undo/redo easier; in larger apps you might use a reducer or event sourcing.
- **Event delegation in the View** avoids leaking listeners across re-renders.
- **Controller as the only place that knows both Model and View** keeps dependencies one-directional and makes unit testing straightforward: test `TodoModel` without a DOM, test `TodoView` with fake handlers.
- If you need richer UI state (loading, errors), extend the Model or add a separate UI-state model rather than putting it in the View.

# Edge cases in TypeScript MVC

Below are the most common (and dangerous) edge cases, grouped by layer. Each shows a broken/naïve version and the idiomatic fix.

---

## 1. Model: stale async updates (race conditions)

A user clicks “Load A” then “Load B”; A resolves last and overwrites B.

```ts
class UserModel {
  private currentId: string | null = null;
  state: User | null = null;
  private listeners = new Set<(u: User | null) => void>();

  async load(id: string) {
    this.currentId = id;
    const data = await api.getUser(id);
    // Guard: ignore stale responses
    if (this.currentId !== id) return;
    this.state = data;
    this.notify();
  }

  private notify() { this.listeners.forEach(l => l(this.state)); }
  subscribe(l: (u: User | null) => void): () => void {
    this.listeners.add(l);
    return () => this.listeners.delete(l); // see #2
  }
}
```

**Key point:** always compare the request token/id before committing async results.

---

## 2. View: listener leaks on unmount

Forgetting to call the unsubscribe returned by `subscribe` keeps closures alive.

```ts
class UserView {
  private unsubs: Array<() => void> = [];

  mount(model: UserModel) {
    // WRONG: this.listeners never cleared
    // model.subscribe(u => this.render(u));

    // RIGHT: store and invoke on unmount
    this.unsubs.push(model.subscribe(u => this.render(u)));
  }

  unmount() {
    this.unsubs.forEach(u => u());
    this.unsubs = [];
  }

  private render(u: User | null) {
    // use textContent, never innerHTML with untrusted data (#3)
    this.nameEl.textContent = u?.name ?? '';
  }
}
```

---

## 3. View: XSS via `innerHTML`

```ts
// DANGEROUS
el.innerHTML = `<span>${user.bio}</span>`;

// SAFE
const span = document.createElement('span');
span.textContent = user.bio; // auto-escaped
el.replaceChildren(span);
```

If you must render HTML, sanitize with a library (DOMPurify) and type the input as `string`, never `any`.

---

## 4. Model: deep mutation not detected

Shallow equality checks miss nested changes.

```ts
// BROKEN: mutates in place, no notification
model.state.items.push(newItem);

// CORRECT: immutable update
updateItems(next: Item[]) {
  this.state = { ...this.state, items: [...this.state.items, ...next] };
  this.notify();
}
```

If you truly need mutable models, use a `Proxy` with deep traps or a library (Immer) — but keep the public API immutable.

---

## 5. Typing: branded IDs to prevent mix-ups

```ts
type UserId = string & { readonly __brand: 'UserId' };
type OrderId = string & { readonly __brand: 'OrderId' };

function toUserId(s: string): UserId {
  if (!/^u_\d+$/.test(s)) throw new Error('bad user id');
  return s as UserId;
}

// Controller signature now rejects wrong id types at compile time
class OrderController {
  constructor(private orders: OrderModel) {}
  loadForUser(userId: UserId) { this.orders.byUser(userId); }
}
```

---

## 6. Controller: transactional rollback on failure

Partial updates leave the model inconsistent.

```ts
class CheckoutController {
  constructor(private cart: CartModel, private orders: OrderModel) {}

  async submit() {
    const cartSnapshot = this.cart.snapshot();
    const orderSnapshot = this.orders.snapshot();
    try {
      const order = await this.orders.create(this.cart.items);
      this.cart.clear();
      return order;
    } catch (e) {
      // rollback both
      this.cart.restore(cartSnapshot);
      this.orders.restore(orderSnapshot);
      this.view.showError(e instanceof Error ? e.message : 'unknown');
      throw e;
    }
  }
}
```

Model must expose `snapshot()`/`restore()` (structured clone or immutable history).

---

## 7. Controller: request cancellation on unmount/retry

```ts
class SearchController {
  private abort?: AbortController;

  async search(q: string) {
    this.abort?.abort();
    this.abort = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`, {
        signal: this.abort.signal,
      });
      if (!res.ok) throw new Error(res.statusText);
      const data: SearchResult[] = await res.json();
      this.model.setResults(data);
    } catch (e) {
      if (e instanceof DOMException && e.name === 'AbortError') return; // expected
      this.view.showError(String(e));
    }
  }
}
```

---

## 8. Exhaustiveness in model reducers

Discriminated unions + `never` catch missing cases at compile time.

```ts
type Action =
  | { type: 'add'; payload: number }
  | { type: 'remove'; id: string }
  | { type: 'reset' };

function reduce(state: State, action: Action): State {
  switch (action.type) {
    case 'add':    return { ...state, count: state.count + action.payload };
    case 'remove': return { ...state, items: state.items.filter(i => i.id !== action.id) };
    case 'reset':  return initialState;
    default: {
      const _exhaustive: never = action; // compile error if a case is missing
      return _exhaustive;
    }
  }
}
```

---

## 9. Event bus: strictly typed payloads

```ts
type EventMap = {
  'user:login': { id: string; at: number };
  'cart:add': { sku: string; qty: number };
};

class EventBus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Set<(p: any) => void>>();

  on<K extends keyof E>(event: K, h: (p: E[K]) => void): () => void {
    if (!this.handlers.has(event)) this.handlers.set(event, new Set());
    this.handlers.get(event)!.add(h);
    return () => this.handlers.get(event)?.delete(h);
  }

  emit<K extends keyof E>(event: K, payload: E[K]) {
    this.handlers.get(event)?.forEach(h => h(payload));
  }
}

const bus = new EventBus<EventMap>();
bus.on('user:login', p => console.log(p.id));   // typed
// bus.emit('user:login', { id: 1 });            // compile error: id must be string
```

---

## 10. View: rendering before model is ready

Guard against null state and avoid “flash of empty”.

```ts
class ProfileView {
  render(user: User | null) {
    if (!user) {
      this.container.replaceChildren(this.skeleton());
      return;
    }
    // safe: user narrowed to non-null here
    this.nameEl.textContent = user.name;
    this.avatarEl.src = user.avatarUrl;
  }

  private skeleton() {
    const d = document.createElement('div');
    d.className = 'skeleton';
    return d;
  }
}
```

Pair with controller that sets a `loading` flag and view that renders skeleton.

---

## 11. Model: circular references / serialization

```ts
class GraphModel {
  nodes: Node[] = [];
  // JSON.stringify fails on cycles; provide a safe serializer
  toJSON() {
    const seen = new WeakSet();
    return JSON.stringify(this.nodes, (_k, v) => {
      if (typeof v === 'object' && v !== null) {
        if (seen.has(v)) return '[Circular]';
        seen.add(v);
      }
      return v;
    });
  }
}
```

---

## 12. Generic model constraints & strict null checks

```ts
interface HasId { id: string }

class Repository<T extends HasId> {
  private items = new Map<string, T>();

  get(id: string): T | undefined { return this.items.get(id); }

  // Force callers to handle missing
  require(id: string): T {
    const v = this.items.get(id);
    if (!v) throw new Error(`not found: ${id}`);
    return v;
  }
}

// tsconfig: "strict": true, "noUncheckedIndexedAccess": true
const arr: string[] = ['a'];
const x = arr[0]; // string | undefined (with noUncheckedIndexedAccess)
```

---

## 13. Controller: input validation at the boundary

Never trust view/controller inputs; validate with a schema.

```ts
import { z } from 'zod';

const CreateUser = z.object({
  email: z.string().email(),
  age: z.number().int().min(0).max(150),
});

class UserController {
  async create(raw: unknown) {
    const parsed = CreateUser.safeParse(raw);
    if (!parsed.success) {
      this.view.showErrors(parsed.error.flatten());
      return;
    }
    await this.model.create(parsed.data); // typed as {email, age}
  }
}
```

---

## 14. View: stale closures in callbacks

```ts
class CounterView {
  private count = 0;

  // BAD: captures initial count forever
  // btn.onclick = () => console.log(this.count);

  // GOOD: arrow method reads live `this`
  handleClick = () => {
    this.count++;
    this.render();
  };

  mount() {
    this.btn.addEventListener('click', this.handleClick);
  }
  unmount() {
    this.btn.removeEventListener('click', this.handleClick);
  }
}
```

Always keep a stable reference for add/removeEventListener.

---

## 15. Model: optimistic update with rollback

```ts
class LikeModel {
  state = { liked: false, count: 0 };

  async toggle() {
    const prev = { ...this.state };
    // optimistic
    this.state = { liked: !prev.liked, count: prev.count + (prev.liked ? -1 : 1) };
    this.notify();
    try {
      await api.toggleLike();
    } catch {
      this.state = prev; // rollback
      this.notify();
      throw new Error('like failed');
    }
  }
}
```

---

## Summary checklist

| Layer | Edge case | Fix |
|---|---|---|
| Model | stale async | token/id guard |
| Model | deep mutation | immutable updates |
| Model | cycles in JSON | custom serializer |
| View | listener leaks | store unsubs, call on unmount |
| View | XSS | `textContent`, sanitize |
| View | null state | skeleton + narrowing |
| View | stale closures | stable arrow methods |
| Controller | partial failure | snapshot/restore |
| Controller | cancellation | `AbortController` |
| Controller | bad input | schema validation (zod) |
| Cross | id mix-ups | branded types |
| Cross | missing reducer case | `never` exhaustiveness |
| Cross | untyped events | generic `EventMap` |
| Cross | strict null | `noUncheckedIndexedAccess` |

Enable `strict`, `noUncheckedIndexedAccess`, and `exactOptionalPropertyTypes` in `tsconfig.json` — most of these edge cases become compile-time errors instead of runtime bugs.

## TypeScript modules and imports — complete runnable example

This example shows a small multi-file project using **ES-style modules** in TypeScript, compiled to **CommonJS** so it runs directly with Node. It demonstrates:

- named exports / imports
- default exports / imports
- `import * as namespace`
- type-only imports
- barrel (re-export) files
- dynamic `import()`
- side-effect imports

### Project structure

```text
ts-modules-demo/
├── package.json
├── tsconfig.json
└── src/
    ├── main.ts
    ├── math.ts
    ├── types.ts
    ├── sideEffect.ts
    ├── index.ts          # barrel file
    └── utils/
        └── format.ts
```

### 1. `package.json`

```json
{
  "name": "ts-modules-demo",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "build": "tsc",
    "start": "node dist/main.js",
    "dev": "ts-node src/main.ts"
  },
  "devDependencies": {
    "typescript": "^5.4.0",
    "ts-node": "^10.9.0",
    "@types/node": "^20.0.0"
  }
}
```

### 2. `tsconfig.json`

```json
{
  "compilerOptions": {
    "target": "ES2020",
    "module": "commonjs",
    "moduleResolution": "node",
    "rootDir": "./src",
    "outDir": "./dist",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true
  },
  "include": ["src/**/*"]
}
```

> **Note:** With `"module": "commonjs"`, relative imports can omit file extensions.  
> If you switch to `"module": "NodeNext"` for native ESM, you must write extensions such as `./math.js` in source (TypeScript resolves them to `.ts`).

### 3. Source files

#### `src/math.ts`

```ts
// Named exports
export function add(a: number, b: number): number {
  return a + b;
}

export const PI = 3.141592653589793;

// Type export
export type Operation = (x: number, y: number) => number;

// Default export
export default function multiply(a: number, b: number): number {
  return a * b;
}
```

#### `src/utils/format.ts`

```ts
export function formatNumber(value: number, decimals = 2): string {
  return value.toFixed(decimals);
}

export function formatCurrency(value: number): string {
  return `$${value.toFixed(2)}`;
}
```

#### `src/types.ts`

```ts
export interface Point {
  x: number;
  y: number;
}

export type Coordinate = [number, number];
```

#### `src/sideEffect.ts`

```ts
// Runs when the module is first imported
console.log("[sideEffect] module loaded");

export {};
```

#### `src/index.ts` — barrel / re-export file

```ts
// Re-export all named exports from these modules
export * from './math';
export * from './utils/format';
export * from './types';

// Re-export the default export under an explicit name
export { default as multiply } from './math';
```

> `export *` does **not** re-export `default` automatically, so the extra line above is needed if you want `multiply` available from the barrel.

#### `src/main.ts`

```ts
// Side-effect import: executes sideEffect.ts
import './sideEffect';

// Default + named imports from a relative module
import multiply, { add, PI, type Operation } from './math';

// Namespace import
import * as mathModule from './math';

// Named imports from a nested module
import { formatNumber } from './utils/format';

// Type-only import
import type { Point } from './types';

// Mixed value/type import from a type module
import { Coordinate } from './types';

// Namespace import from the barrel
import * as app from './index';

// A value using the imported type
const subtract: Operation = (a, b) => a - b;

console.log("multiply(6, 7) =", multiply(6, 7));
console.log("add(2, 3) =", add(2, 3));
console.log("PI =", PI);
console.log("formatNumber(PI) =", formatNumber(PI));
console.log("mathModule.add(1, 2) =", mathModule.add(1, 2));
console.log("subtract(10, 4) =", subtract(10, 4));

const point: Point = { x: 10, y: 20 };
const coord: Coordinate = [3, 4];
console.log("point =", point);
console.log("coord =", coord);

// Using the barrel
console.log("app.formatCurrency(9.99) =", app.formatCurrency(9.99));
console.log("app.multiply(3, 4) =", app.multiply(3, 4));

// Dynamic import
async function demoDynamicImport(): Promise<void> {
  const math = await import('./math');
  console.log("dynamic import add(10, 20) =", math.add(10, 20));
  console.log("dynamic import default multiply(4, 5) =", math.default(4, 5));
}

void demoDynamicImport();
```

