## Core implementation (clean, idiomatic usage)

Below is a small, realistic module graph. Each file demonstrates a different “core” capability.

### `src/types.ts` — type-only exports
```ts
// Type-only module: everything here is compile-time only.
export type UserId = string & { readonly __brand: "UserId" };

export interface User {
  id: UserId;
  name: string;
  email?: string;
}

export type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };
```

### `src/math.ts` — named + default export
```ts
/** Named exports: explicit, tree-shakeable. */
export function add(a: number, b: number): number {
  return a + b;
}

export function multiply(a: number, b: number): number {
  return a * b;
}

/** Default export: convenience entry point. */
export default function sumAll(values: number[]): number {
  return values.reduce((acc, n) => acc + n, 0);
}
```

### `src/logger.ts` — class export + side-effect-free
```ts
export class Logger {
  constructor(private readonly prefix: string) {}

  info(msg: string): void {
    console.log(`[${this.prefix}] ${msg}`);
  }

  error(err: unknown): void {
    console.error(`[${this.prefix}]`, err);
  }
}
```

### `src/index.ts` — barrel (re-export hub)
```ts
// Re-export public API from feature modules.
export * from "./types";
export * from "./math";
export { Logger } from "./logger";

// Re-export a default under a named alias (interop-friendly).
export { default as sumAll } from "./math";
```

### `src/app.ts` — consuming modules (all import styles)
```ts
import { add, multiply, sumAll } from "./math";          // named
import Logger from "./logger";                           // default (if configured)
import * as MathNs from "./math";                        // namespace
import type { User, Result } from "./types";             // type-only
import { Logger as AppLogger } from "./index";           // via barrel

// Side-effect import (e.g., polyfill): import "./polyfills";

function makeUser(id: string, name: string): User {
  return { id: id as User["id"], name };
}

function main(): void {
  const logger = new AppLogger("app");
  logger.info(`2 + 3 = ${add(2, 3)}`);
  logger.info(`2 * 3 = ${multiply(2, 3)}`);
  logger.info(`sum = ${sumAll([1, 2, 3])}`);
  logger.info(`namespace add = ${MathNs.add(10, 20)}`);

  const user: User = makeUser("u1", "Ada");
  const result: Result<User> = { ok: true, value: user };
  if (result.ok) logger.info(`user=${result.value.name}`);
}

main();
```

### `src/dynamic.ts` — dynamic import (code splitting)
```ts
export async function loadHeavyFeature(): Promise<{ run: () => void }> {
  // Loaded on demand; bundler splits this into a separate chunk.
  const mod = await import("./heavyFeature");
  return mod;
}
```

### `src/heavyFeature.ts` — lazily loaded module
```ts
export function run(): void {
  console.log("heavy feature running");
}
```

