## 3. Main file: `src/main.ts`

```ts
import { Worker } from 'worker_threads';
import os from 'os';
import path from 'path';

interface WorkerInput {
  numbers: number[];
}

interface WorkerOutput {
  sum: number;
  threadId: number;
}

function runWorker(numbers: number[]): Promise<WorkerOutput> {
  return new Promise((resolve, reject) => {
    const worker = new Worker(path.join(__dirname, 'worker.js'), {
      workerData: { numbers } satisfies WorkerInput,
    });

    worker.on('message', (msg: WorkerOutput) => resolve(msg));
    worker.on('error', reject);
    worker.on('exit', (code) => {
      if (code !== 0) {
        reject(new Error(`Worker exited with code ${code}`));
      }
    });
  });
}

function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

async function parallelSum(all: number[]): Promise<number> {
  const cpuCount = os.cpus().length;
  const chunks = chunk(all, Math.ceil(all.length / cpuCount));

  console.log(`Using ${chunks.length} workers on ${cpuCount} CPUs`);

  const results = await Promise.all(chunks.map(runWorker));
  return results.reduce((total, r) => total + r.sum, 0);
}

(async () => {
  const data = Array.from({ length: 2_000_000 }, (_, i) => i);

  const t0 = performance.now();
  const total = await parallelSum(data);
  const ms = performance.now() - t0;

  console.log('Total:', total);
  console.log(`Time: ${ms.toFixed(2)} ms`);
})();
```

