## Key explanations

- **`__filename` as worker entry:** The same compiled file is reused; `isMainThread` branches behavior. This keeps deployment simple.
- **Chunking:** `ceil(n / workers)` ensures the last chunk may be smaller; all elements covered exactly once.
- **Error propagation:** Each worker promise rejects on `'error'` or bad exit code; `Promise.all` fails fast.
- **No shared memory needed:** For a reduction like sum of squares, message passing is simplest and safe. For huge arrays you could use `SharedArrayBuffer`, but then you must handle synchronization.
- **Cleanup:** Workers exit after `process.exit(0)`; Node reaps them. In long-lived servers you’d pool workers instead of spawning per call.

### Browser note
In browsers, use `Web Workers` with `new Worker(new URL('./worker.ts', import.meta.url))` and `postMessage`. The parallel pattern is identical; only the API differs.

## Interview-style explanation

TypeScript itself does not add a threading model. It compiles to JavaScript, and JavaScript runtimes are traditionally **single-threaded** with an event loop. So “multithreading in TypeScript” usually means using the runtime’s worker APIs:

- **Browser:** `Web Workers`
- **Node.js:** `worker_threads`

### Key concepts

1. **Concurrency vs. parallelism**
   - Concurrency: many tasks make progress via the event loop.
   - Parallelism: multiple CPU cores execute code simultaneously via worker threads.

2. **Workers are isolated**
   - Each worker has its own event loop, memory, and global scope.
   - Main thread and workers communicate by **message passing**.
   - Messages are structured-cloned by default.

3. **Shared memory is opt-in**
   - `SharedArrayBuffer` allows shared memory.
   - `Atomics` provides safe operations such as `Atomics.add`, `Atomics.wait`, and `Atomics.notify`.

4. **When to use workers**
   - Good for CPU-bound work: hashing, compression, image processing, heavy math.
   - Usually unnecessary for I/O: Node’s event loop already handles network/file I/O efficiently.

5. **Common pitfalls**
   - Serialization cost for large messages.
   - Race conditions when using shared memory.
   - Creating too many workers can hurt performance.
   - Worker startup cost, so use a **thread pool**.

---

## Core implementation: a Node.js worker thread pool

This example uses two files:

- `worker.ts`: runs inside each worker thread.
- `pool.ts`: main-thread pool that distributes CPU-bound tasks.

### `worker.ts`

```ts
import { parentPort } from 'worker_threads';

interface IncomingTask {
  id: number;
  n: number;
}

/**
 * CPU-bound example task.
 * Fibonacci is intentionally expensive to demonstrate parallelism.
 */
function fibonacci(n: number): number {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

parentPort!.on('message', (task: IncomingTask) => {
  try {
    const result = fibonacci(task.n);
    parentPort!.postMessage({ id: task.id, result });
  } catch (error) {
    parentPort!.postMessage({
      id: task.id,
      error: (error as Error).message,
    });
  }
});
```

### `pool.ts`

```ts
import os from 'os';
import path from 'path';
import { Worker } from 'worker_threads';

interface TaskMessage {
  id: number;
  n: number;
}

interface ResultMessage {
  id: number;
  result?: number;
  error?: string;
}

interface Job {
  id: number;
  payload: number;
  resolve: (value: number) => void;
  reject: (reason?: unknown) => void;
}

/**
 * A small fixed-size worker pool.
 *
 * Design notes:
 * - Workers are reused instead of created per task.
 * - Tasks are queued when all workers are busy.
 * - A failed/exited worker is removed and replaced.
 */
export class WorkerPool {
  private readonly workers = new Set<Worker>();
  private readonly available: Worker[] = [];
  private readonly queue: Job[] = [];
  private readonly jobs = new Map<number, Job>();
  private readonly currentJob = new Map<Worker, number>();

  private nextId = 0;
  private closing = false;

  constructor(
    private readonly size: number = os.cpus().length,
    private readonly workerPath: string = path.resolve(__dirname, 'worker.js')
  ) {
    for (let i = 0; i < this.size; i++) {
      this.spawnWorker();
    }
  }

  /**
   * Submit a CPU-bound number and receive its result.
   */
  run(payload: number): Promise<number> {
    const job: Job = {
      id: this.nextId++,
      payload,
      resolve: () => {},
      reject: () => {},
    };

    return new Promise<number>((resolve, reject) => {
      job.resolve = resolve;
      job.reject = reject;

      this.queue.push(job);
      this.drain();
    });
  }

  /**
   * Assign queued jobs to available workers.
   */
  private drain(): void {
    while (this.available.length > 0 && this.queue.length > 0) {
      const worker = this.available.pop()!;
      const job = this.queue.shift()!;

      this.jobs.set(job.id, job);
      this.currentJob.set(worker, job.id);

      const message: TaskMessage = {
        id: job.id,
        n: job.payload,
      };

      worker.postMessage(message);
    }
  }

  private spawnWorker(): void {
    const worker = new Worker(this.workerPath);

    worker.on('message', (msg: ResultMessage) => {
      this.onMessage(worker, msg);
    });

    worker.on('error', (err: Error) => {
      this.onError(worker, err);
    });

    worker.on('exit', (code: number) => {
      if (code !== 0) {
        console.error(`Worker exited unexpectedly with code ${code}`);
      }

      // If the worker is still tracked, its exit was unexpected.
      if (this.workers.has(worker) && !this.closing) {
        this.removeWorker(worker);
      }
    });

    this.workers.add(worker);
    this.available.push(worker);
    this.drain();
  }

  private onMessage(worker: Worker, msg: ResultMessage): void {
    const job = this.jobs.get(msg.id);

    if (job) {
      this.jobs.delete(msg.id);

      if (msg.error) {
        job.reject(new Error(msg.error));
      } else {
        job.resolve(msg.result!);
      }
    }

    this.currentJob.delete(worker);

    // Only reuse the worker if it is still part of the pool.
    if (this.workers.has(worker)) {
      this.available.push(worker);
      this.drain();
    }
  }

  private onError(worker: Worker, err: Error): void {
    const jobId = this.currentJob.get(worker);

    if (jobId !== undefined) {
      const job = this.jobs.get(jobId);

      if (job) {
        this.jobs.delete(jobId);
        job.reject(err);
      }

      this.currentJob.delete(worker);
    }

    this.removeWorker(worker);

    // Best-effort cleanup; ignore termination errors.
    worker.terminate().catch(() => {});
  }

  private removeWorker(worker: Worker): void {
    if (!this.workers.has(worker)) return;

    this.workers.delete(worker);
    this.available = this.available.filter((w) => w !== worker);

    // Replace the worker unless the pool is shutting down.
    if (!this.closing && this.workers.size < this.size) {
      this.spawnWorker();
    }
  }

  async close(): Promise<void> {
    this.closing = true;

    await Promise.all(
      [...this.workers].map((worker) => worker.terminate())
    );

    this.workers.clear();
    this.available.length = 0;

    // Reject anything still queued or in flight.
    for (const job of this.queue) {
      job.reject(new Error('WorkerPool is closed'));
    }
    this.queue.length = 0;

    for (const job of this.jobs.values()) {
      job.reject(new Error('WorkerPool is closed'));
    }
    this.jobs.clear();
    this.currentJob.clear();
  }
}

/**
 * Example usage.
 */
async function main(): Promise<void> {
  const pool = new WorkerPool(4);

  const inputs = [38, 39, 40, 41, 42];
  const results = await Promise.all(inputs.map((n) => pool.run(n)));

  console.log('Results:', results);

  await pool.close();
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
```

