// 5. Demo
// ============================================================================

function main() {
  console.log("greet:", greet("Alice"), "|", greet("Bob", "Dr."));
  console.log("displayName u2:", displayName(u2));
  console.log("avatarUrl u1:", avatarUrl(u1));
  console.log("processValue null:", processValue(null));
  console.log("processValue '  hi  ':", processValue("  hi  "));
  console.log("isDefined filter:", clean);

  console.log("name1:", name1);
  console.log("avatar1:", avatar1);
  console.log("summary:", summary);

  // Option demos
  const o = Some(5);
  console.log("map Some(5)*2:", map(o, (x) => x * 2));
  console.log("filter >10:", filter(o, (x) => x > 10));
  console.log("getOrElse None:", getOrElse(None as Option<number>, 0));
  console.log("zip:", zip(Some(1), Some("a")));
  console.log("toArray Some:", toArray(Some(42)));
  console.log("toArray None:", toArray(None as Option<number>));
  console.log("fold:", fold(Some(3), () => 0, (v) => v * 10));

  // Result demos
  const r1 = Ok(10);
  const r2 = Err<string>("boom");
  console.log("mapResult:", mapResult(r1, (x) => x + 1));
  console.log("unwrapOr Err:", unwrapOr(r2, 0));
  console.log("flatMapResult chain:",
    flatMapResult(r1, (x) => x > 5 ? Ok(x * 2) : Err("too small"))
  );
}

main();
```

