## Implementing the core: an `Optional<T>` (Maybe) monad

Below is a clean, well-commented implementation inspired by Java’s `Optional`, adapted to TypeScript’s null/undefined world. It gives you safe access, transformations, fallbacks, and explicit “no value” states.

```ts
// Optional.ts

/**
 * A value that may be present or absent.
 * Internally stores either a defined value of type T, or nothing (null/undefined).
 */
export type Maybe<T> = T | null | undefined;

export class Optional<T> {
  // Private constructor forces creation through static factories.
  private constructor(private readonly value: Maybe<T>) {}

  // ---------- Factories ----------

  /** Creates an Optional containing a non-null value. Throws if null/undefined. */
  static of<T>(value: T): Optional<T> {
    if (value === null || value === undefined) {
      throw new Error("Optional.of: value must not be null or undefined");
    }
    return new Optional<T>(value);
  }

  /** Creates an Optional from a possibly-null/undefined value. */
  static ofNullable<T>(value: Maybe<T>): Optional<T> {
    return new Optional<T>(value);
  }

  /** Creates an empty Optional. */
  static empty<T>(): Optional<T> {
    return new Optional<T>(undefined);
  }

  // ---------- State ----------

  /** True if a value is present (not null/undefined). */
  isPresent(): boolean {
    return this.value !== null && this.value !== undefined;
  }

  /** True if no value is present. */
  isEmpty(): boolean {
    return !this.isPresent();
  }

  // ---------- Access ----------

  /** Returns the value, or throws if absent. */
  get(): T {
    if (!this.isPresent()) {
      throw new Error("Optional.get: no value present");
    }
    return this.value as T;
  }

  /** Returns the value if present, otherwise the provided fallback. */
  orElse(other: T): T {
    return this.isPresent() ? (this.value as T) : other;
  }

  /** Returns the value if present, otherwise computes a fallback lazily. */
  orElseGet(supplier: () => T): T {
    return this.isPresent() ? (this.value as T) : supplier();
  }

  /** Returns the value if present, otherwise throws an error from the factory. */
  orElseThrow(errorFactory?: () => Error): T {
    if (!this.isPresent()) {
      throw errorFactory ? errorFactory() : new Error("Optional.orElseThrow: no value present");
    }
    return this.value as T;
  }

  // ---------- Transformations ----------

  /**
   * Maps the present value to a new type.
   * If empty, returns empty; if mapper returns null/undefined, result is empty.
   */
  map<U>(mapper: (value: T) => Maybe<U>): Optional<U> {
    if (!this.isPresent()) return Optional.empty<U>();
    return Optional.ofNullable(mapper(this.value as T));
  }

  /**
   * Like map, but mapper already returns an Optional (avoids nested Optional<Optional<U>>).
   */
  flatMap<U>(mapper: (value: T) => Optional<U>): Optional<U> {
    if (!this.isPresent()) return Optional.empty<U>();
    return mapper(this.value as T);
  }

  /** Keeps the value only if it satisfies the predicate; otherwise becomes empty. */
  filter(predicate: (value: T) => boolean): Optional<T> {
    if (!this.isPresent()) return this;
    return predicate(this.value as T) ? this : Optional.empty<T>();
  }

  // ---------- Side effects ----------

  /** Runs action if a value is present. */
  ifPresent(action: (value: T) => void): void {
    if (this.isPresent()) action(this.value as T);
  }

  /** Runs one of two callbacks depending on presence. */
  ifPresentOrElse(action: (value: T) => void, emptyAction: () => void): void {
    if (this.isPresent()) action(this.value as T);
    else emptyAction();
  }
}
```

