## Usage examples

```ts
import { Optional } from "./Optional";

// 1) Safe access with fallback
const nickname: string | undefined = undefined;
const display = Optional.ofNullable(nickname)
  .map((n) => n.trim())
  .filter((n) => n.length > 0)
  .orElse("Anonymous");

console.log(display); // "Anonymous"

// 2) Transform + default
const length = Optional.ofNullable("  hello  ")
  .map((s) => s.trim().length)
  .orElse(0);

console.log(length); // 5

// 3) flatMap for chained lookups
interface User { address?: { city?: string } }
const user: User = { address: { city: "NYC" } };

const city = Optional.ofNullable(user)
  .flatMap((u) => Optional.ofNullable(u.address))
  .flatMap((a) => Optional.ofNullable(a.city))
  .orElse("Unknown");

console.log(city); // "NYC"

// 4) Throwing when required
try {
  Optional.ofNullable<string>(undefined).orElseThrow(() => new Error("Missing required name"));
} catch (e) {
  console.error((e as Error).message); // "Missing required name"
}

// 5) Side effects
Optional.ofNullable(42).ifPresent((v) => console.log("found", v));
Optional.empty<number>().ifPresentOrElse(
  (v) => console.log(v),
  () => console.log("nothing here")
);
```

