## Bonus: small null-safe helpers (often asked in interviews)

```ts
// Null-safe property getter: get(obj, "a.b.c") without throwing
export function safeGet<T>(obj: unknown, path: string): T | undefined {
  return path.split(".").reduce<unknown>((acc, key) => {
    if (acc && typeof acc === "object" && key in (acc as object)) {
      return (acc as Record<string, unknown>)[key];
    }
    return undefined;
  }, obj) as T | undefined;
}

// Nullish coalescing helper (mirrors ??)
export function coalesce<T>(...values: Array<T | null | undefined>): T | undefined {
  for (const v of values) {
    if (v !== null && v !== undefined) return v;
  }
  return undefined;
}

// Example:
const cfg = { server: { port: 0 } }; // 0 is valid, so ?? (not ||) matters
console.log(safeGet<number>(cfg, "server.port") ?? 3000); // 0
```

### Interview takeaways to mention
- Prefer **type narrowing** (`if (x != null)`) and `?.`/`??` for readability.
- `Optional` is valuable at **boundaries** (API responses, DB rows, parsing), not everywhere.
- Keep null handling **explicit**; avoid silent `!` assertions.
- In TS, model “may be absent” with `T | null | undefined` or `Optional<T>` depending on team style.

# Observer Pattern in TypeScript — Complete Runnable Example

Below is a self-contained, idiomatic TypeScript implementation. It includes a **generic, type-safe** subject, multiple observers, unsubscription, one-time listeners, error isolation, and a small demo you can run directly.

## 1. The implementation (`observer.ts`)

```ts
// observer.ts
// Run with: npx ts-node observer.ts   (or compile with tsc)

/* ------------------------------------------------------------------ */
/* 1. Core abstractions                                                */
/* ------------------------------------------------------------------ */

/** A function that can be called to unsubscribe. */
export type Unsubscribe = () => void;

/** An observer is just a function receiving a typed payload. */
export type Observer<T> = (value: T) => void | Promise<void>;

/** Options for a subscription. */
export interface SubscribeOptions {
  /** If true, the observer is removed after the first emission. */
  once?: boolean;
}

/**
 * A minimal, type-safe Subject.
 * - T is the type of values it emits.
 */
export class Subject<T> {
  private observers = new Set<Observer<T>>();
  private onceObservers = new Set<Observer<T>>();

  /** Subscribe to future emissions. Returns an unsubscribe function. */
  subscribe(observer: Observer<T>, options: SubscribeOptions = {}): Unsubscribe {
    const bucket = options.once ? this.onceObservers : this.observers;
    bucket.add(observer);

    let active = true;
    return () => {
      if (!active) return;
      active = false;
      bucket.delete(observer);
    };
  }

  /** Emit a value to all current observers. */
  async next(value: T): Promise<void> {
    // Snapshot so observers can unsubscribe during iteration safely.
    const snapshot = [...this.observers, ...this.onceObservers];

    // Clear "once" observers before notifying (so re-entrant emits don't double-fire).
    this.onceObservers.clear();

    for (const observer of snapshot) {
      try {
        await observer(value);
      } catch (err) {
        // Isolate failures: one bad observer must not break the others.
        console.error("[Subject] observer threw:", err);
      }
    }
  }

  /** Remove every observer. */
  clear(): void {
    this.observers.clear();
    this.onceObservers.clear();
  }

  /** Number of active observers (useful for debugging / tests). */
  get size(): number {
    return this.observers.size + this.onceObservers.size;
  }
}
```

## 2. A domain model on top of it (`stock-ticker.ts`)

A realistic use case: a stock price subject that notifies dashboards, alerts, and a logger.

```ts
// stock-ticker.ts
import { Subject, Unsubscribe } from "./observer";

export interface PriceUpdate {
  symbol: string;
  price: number;
  timestamp: number;
}

export class StockTicker {
  // One subject per symbol keeps payloads small and typed.
  private subjects = new Map<string, Subject<PriceUpdate>>();

  private subjectFor(symbol: string): Subject<PriceUpdate> {
    let s = this.subjects.get(symbol);
    if (!s) {
      s = new Subject<PriceUpdate>();
      this.subjects.set(symbol, s);
    }
    return s;
  }

  /** Public read-only view of a symbol's stream. */
  stream(symbol: string): Subject<PriceUpdate> {
    return this.subjectFor(symbol);
  }

  /** Push a new price. */
  update(symbol: string, price: number): void {
    const payload: PriceUpdate = { symbol, price, timestamp: Date.now() };
    this.subjectFor(symbol).next(payload); // fire-and-forget async
  }

  /** Clean up a symbol entirely. */
  remove(symbol: string): void {
    const s = this.subjects.get(symbol);
    s?.clear();
    this.subjects.delete(symbol);
  }
}
```

## 3. Observers / consumers (`consumers.ts`)

```ts
// consumers.ts
import { PriceUpdate } from "./stock-ticker";

export function makeDashboard(name: string) {
  return (u: PriceUpdate) => {
    console.log(`[${name}] ${u.symbol} -> $${u.price.toFixed(2)}`);
  };
}

export function makeAlert(threshold: number) {
  return (u: PriceUpdate) => {
    if (u.price >= threshold) {
      console.log(`🚨 ALERT: ${u.symbol} crossed $${threshold}`);
    }
  };
}

export function makeLogger() {
  const log: PriceUpdate[] = [];
  const observer = (u: PriceUpdate) => {
    log.push(u);
  };
  return { observer, log };
}
```

## 4. Runnable demo (`main.ts`)

```ts
// main.ts
import { StockTicker } from "./stock-ticker";
import { makeDashboard, makeAlert, makeLogger } from "./consumers";

async function main() {
  const ticker = new StockTicker();

  // --- Subscribe multiple observers to AAPL ---
  const unsubDashboard = ticker.stream("AAPL").subscribe(makeDashboard("Dashboard"));
  ticker.stream("AAPL").subscribe(makeAlert(150));

  const { observer: loggerObs, log } = makeLogger();
  ticker.stream("AAPL").subscribe(loggerObs);

  // One-time observer: fires only on the next emit.
  ticker.stream("AAPL").subscribe(
    (u) => console.log("👁  first-seen observer fired once:", u.price),
    { once: true }
  );

  // --- Emit some prices ---
  console.log("== Emit 140 ==");
  await ticker.stream("AAPL").next({ symbol: "AAPL", price: 140, timestamp: Date.now() });

  console.log("\n== Emit 155 ==");
  await ticker.update("AAPL", 155); // uses ticker.update -> calls next internally

  // --- Unsubscribe dashboard, then emit again ---
  console.log("\n== Unsubscribe dashboard, emit 160 ==");
  unsubDashboard();
  await ticker.update("AAPL", 160);

  console.log("\n== Logger history ==");
  console.log(log);

  // --- Error isolation demo ---
  console.log("\n== Error isolation ==");
  ticker.stream("AAPL").subscribe(() => {
    throw new Error("boom");
  });
  await ticker.update("AAPL", 170); // other observers still run

  // --- Cleanup ---
  ticker.remove("AAPL");
  console.log("\nObservers after remove:", ticker.stream("AAPL").size);
}

main().catch(console.error);
```

> Note: `ticker.update` calls `next` without awaiting in the class above. For the demo I await `ticker.stream(...).next(...)` directly where I want ordering. If you want `update` to be awaitable, change its signature to `async update(...)` and `await this.subjectFor(symbol).next(payload)`.

## 5. How to run

```bash
mkdir observer-demo && cd observer-demo
npm init -y
npm i -D typescript ts-node @types/node
npx tsc --init
# paste the four files above, then:
npx ts-node main.ts
```

## 6. Design notes (why it's built this way)

| Concern | Choice | Reason |
|---|---|---|
| **Typing** | Generic `Subject<T>` + `Observer<T>` | Compile-time safety; no `any` in payloads. |
| **Unsubscribe** | Returns `Unsubscribe` fn + `Set` storage | Idiomatic TS/JS; O(1) removal; no listener arrays. |
| **Re-entrancy** | Snapshot array before notifying | An observer can subscribe/unsubscribe during `next` without corrupting iteration. |
| **`once`** | Separate `Set`, cleared before notify | Prevents double-firing if an emit triggers another emit. |
| **Errors** | `try/catch` per observer | One failing observer can't take down the subject or siblings. |
| **Async** | `await observer(value)` | Supports async observers; sequential (predictable ordering). Use `Promise.all` if you want concurrency. |
| **Memory leaks** | Explicit `unsubscribe` / `clear()` | Observers hold closures; always tear down on component unmount. |
| **Weak refs** | Not used here | If observers are short-lived objects, consider `WeakRef` + `FinalizationRegistry`, but it complicates typing. |

## 7. Optional: stricter variant (no `any`, exact types)

If you want an event-emitter style with multiple named events instead of one stream per subject, you can generalize:

```ts
type EventMap = Record<string, unknown>;

class TypedEmitter<Events extends EventMap> {
  private subjects = new Map<keyof Events, Subject<Events[keyof Events]>>();

  on<K extends keyof Events>(event: K, obs: Observer<Events[K]>): Unsubscribe {
    return this.subjectFor(event).subscribe(obs as Observer<Events[keyof Events]>);
  }
  emit<K extends keyof Events>(event: K, value: Events[K]): Promise<void> {
    return this.subjectFor(event).next(value);
  }
  private subjectFor<K extends keyof Events>(e: K): Subject<Events[K]> {
    // ...create lazily, cast internally
  }
}
```

That pattern is what libraries like `mitt` or `eventemitter3` provide; the `Subject<T>` above is the building block underneath.

---

### TL;DR
- **Subject** holds a `Set` of observers and exposes `subscribe`/`next`.
- **Observers** are plain functions `(value) => void | Promise<void>`.
- Always **snapshot before iterating**, **isolate errors**, and **return an unsubscribe handle**.
- For real apps, wrap subjects in domain objects (like `StockTicker`) and give each stream a clear lifecycle (`clear` on teardown).

# Observer Pattern in TypeScript

## Idea

The **Observer pattern** is a behavioral design pattern where an object (the *Subject*) maintains a list of dependents (*Observers*) and automatically notifies them whenever its state changes.  

**Core benefits**
- **Loose coupling** – the subject doesn’t know concrete observer types, only an interface.
- **Reactive updates** – observers react to changes without polling.
- **One-to-many** – one subject can notify many listeners.

---

## Basic Syntax (Classic OOP form)

```ts
// 1. Contracts
interface Observer<T> {
  update(data: T): void;
}

interface Subject<T> {
  subscribe(observer: Observer<T>): void;
  unsubscribe(observer: Observer<T>): void;
  notify(data: T): void;
}

// 2. Concrete subject
class TemperatureSensor implements Subject<number> {
  private observers = new Set<Observer<number>>();

  subscribe(o: Observer<number>) { this.observers.add(o); }
  unsubscribe(o: Observer<number>) { this.observers.delete(o); }

  private _temp = 0;
  set temperature(v: number) {
    this._temp = v;
    this.notify(v);
  }
  get temperature() { return this._temp; }

  notify(data: number) {
    this.observers.forEach(o => o.update(data));
  }
}

// 3. Concrete observer
class Display implements Observer<number> {
  update(temp: number) {
    console.log(`Display: ${temp}°C`);
  }
}

// Usage
const sensor = new TemperatureSensor();
const display = new Display();
sensor.subscribe(display);
sensor.temperature = 23;   // → Display: 23°C
```

**TypeScript specifics used here**
- `interface` for the contracts.
- `Set<Observer<T>>` prevents duplicate subscriptions.
- Generics (`<T>`) make it reusable for any payload type.

---

## Modern / Idiomatic TypeScript: Typed Event Emitter

In real TS codebases you usually want **named events with typed payloads**, not a single “update” channel.

```ts
// Define an event map
type AppEvents = {
  "user:login": { id: string; name: string };
  "user:logout": void;
  "cart:add": { productId: string; qty: number };
};

class EventEmitter<Events extends Record<string, unknown>> {
  private listeners = new Map<keyof Events, Set<Function>>();

  on<K extends keyof Events>(
    event: K,
    cb: (payload: Events[K]) => void
  ): () => void {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event)!.add(cb);
    // Return unsubscribe function (idiomatic TS)
    return () => this.listeners.get(event)?.delete(cb);
  }

  emit<K extends keyof Events>(event: K, payload: Events[K]): void {
    this.listeners.get(event)?.forEach(cb => cb(payload));
  }

  off<K extends keyof Events>(event: K, cb: Function): void {
    this.listeners.get(event)?.delete(cb);
  }
}

// Usage
const bus = new EventEmitter<AppEvents>();

const unsub = bus.on("user:login", ({ name }) => {
  console.log(`Welcome, ${name}`);
});

bus.emit("user:login", { id: "1", name: "Alice" });
unsub(); // clean up
```

**Why this is more “TypeScript-y”**
- `keyof Events` gives autocomplete for event names.
- Payload types are enforced at compile time.
- Returning an unsubscribe function avoids holding references to observers (helps GC).

---

## Typical Use Cases

| Scenario | How Observer fits |
|---|---|
| **UI frameworks** (React, Vue, Angular) | Components subscribe to store/state changes and re-render. |
| **DOM events** | `addEventListener` is literally the Observer pattern. |
| **State management** (Redux, Zustand, MobX) | Stores notify subscribers on state transitions. |
| **Real-time data** (WebSockets, SSE) | Incoming messages notify all registered handlers. |
| **Form validation** | Fields observe a validation service and update UI. |
| **Logging / metrics** | A subject emits events; multiple observers (console, remote logger, analytics) react independently. |

---

## Important Practical Details

### 1. Memory leaks
Always provide `unsubscribe` / `off`. Returning an unsubscribe function (as above) is the safest API.

### 2. Async observers
If observers do async work, decide on semantics:
- **Fire-and-forget** (common for UI): `forEach(cb => cb(payload))`
- **Await all**: `Promise.all(observers.map(o => o.update(payload)))`

### 3. Error isolation
Wrap each observer call so one failing observer doesn’t break others:

```ts
notify(data: T) {
  this.observers.forEach(o => {
    try { o.update(data); }
    catch (e) { console.error("Observer error:", e); }
  });
}
```

### 4. Ordering
`Set` preserves insertion order, but don’t rely on strict ordering for correctness—design observers to be independent.

### 5. RxJS (the “heavy” version)
For advanced needs (debounce, combine, backpressure), use **RxJS** Observables instead of hand-rolled observers:

```ts
import { Subject } from "rxjs";
const temps$ = new Subject<number>();
temps$.subscribe(t => console.log(t));
temps$.next(25);
```

---

## Summary

- **Classic form**: `Subject` + `Observer` interfaces with `subscribe/unsubscribe/notify`.
- **Modern TS form**: Generic `EventEmitter<Events>` with typed event names and payloads, returning unsubscribe functions.
- **Key concerns**: unsubscribe to avoid leaks, isolate errors, decide sync vs async, and consider RxJS for complex streams.

### Mistaken version

```ts
class EventBus {
  private handlers: Array<(event: string) => void> = [];

  on(handler: (event: string) => void): void {
    this.handlers.push(handler);
  }

  off(handler: (event: string) => void): void {
    const index = this.handlers.indexOf(handler);
    if (index !== -1) this.handlers.splice(index, 1);
  }

  emit(event: string): void {
    this.handlers.forEach((handler) => handler(event));
  }
}

// Bug demonstration
const bus = new EventBus();

const a = (e: string) => {
  console.log("A", e);
  bus.off(a); // A unsubscribes itself while emitting
};

const b = (e: string) => console.log("B", e);

bus.on(a);
bus.on(b);

bus.emit("hello");
// Often prints only "A hello"; B is skipped because the array shifted
// during forEach iteration.
```

### Corrected version

```ts
class EventBus {
  private handlers = new Set<(event: string) => void>();

  on(handler: (event: string) => void): () => void {
    this.handlers.add(handler);

    // Return an unsubscribe function so callers can clean up.
    return () => {
      this.handlers.delete(handler);
    };
  }

  emit(event: string): void {
    // Snapshot the current subscribers so the live collection can change
    // safely during notification.
    for (const handler of [...this.handlers]) {
      try {
        handler(event);
      } catch (error) {
        // One failing observer should not prevent others from running.
        console.error("Observer failed:", error);
      }
    }
  }
}

// Usage
const bus = new EventBus();

const unsubscribeA = bus.on((e) => {
  console.log("A", e);
  unsubscribeA(); // safe self-unsubscribe
});

const unsubscribeB = bus.on((e) => console.log("B", e));

bus.emit("hello");
// Prints both "A hello" and "B hello"

// Later cleanup is explicit and easy.
unsubscribeB();
```

### What was wrong and why

1. **Mutating the observer list while iterating**  
   In the mistaken version, `forEach` walks the array by index. If an observer unsubscribes itself (or another observer) during `emit`, `splice` shifts later elements left, so the next index can skip an observer. Using a snapshot (`[...this.handlers]`) fixes this because iteration happens over a stable copy.

2. **No unsubscribe handle returned**  
   Observers often need to unsubscribe later. Returning `() => void` makes cleanup straightforward and prevents leaks, especially in UI/component code.

3. **Unhandled exceptions break notification**  
   If one observer throws, `forEach` stops propagating to the rest. Wrapping each call in `try/catch` isolates failures.

4. **Duplicates possible with arrays**  
   Using a `Set` prevents the same function from being registered multiple times accidentally. If you truly need multiple registrations, you can keep an array, but then you should still snapshot before iterating and consider deduplication rules explicitly.

5. **Self-unsubscribe is now safe**  
   Because iteration uses a snapshot, deleting from the live `Set` during emission does not affect which handlers are invoked in the current emit cycle.

# Common Observer-Pattern Pitfalls in TypeScript (and how to avoid them)

Below are the pitfalls I see most often in real codebases, roughly ordered by frequency. Each has a short “bad” snippet and a “better” snippet.

> Assumption: examples use a small, RxJS-like `Subject`/`Observable` you might write yourself. The same ideas apply to RxJS, Node `EventEmitter`, DOM `addEventListener`, and framework reactivity.

---

## 1. Forgetting to unsubscribe → memory leaks

**Pitfall:** Observers are held by strong references. If you never unsubscribe, components/services stay alive and memory grows.

```ts
// ❌ Bad: subscription never torn down
class Component {
  constructor(private bus: EventBus<User>) {
    this.bus.on("login", (u) => this.handle(u)); // never removed
  }
}
```

```ts
// ✅ Better: store subscription and dispose in lifecycle
class Component {
  private sub?: Subscription;

  constructor(private bus: EventBus<User>) {
    this.sub = this.bus.on("login", (u) => this.handle(u));
  }

  destroy() {
    this.sub?.unsubscribe();
  }
}
```

**Rule:** every subscription must have a clear owner and teardown path (Angular `OnDestroy`, React cleanup, `AbortSignal`, etc.).

---

## 2. Mutating the observer list while notifying

**Pitfall:** An observer unsubscribes (or another subscribes) during `next()`, causing skipped observers or `ConcurrentModificationException`-style bugs.

```ts
// ❌ Bad: iterating array while observers mutate it
notify(value: T) {
  for (const o of this.observers) {
    o(value); // o may call unsubscribe -> splices array mid-loop
  }
}
```

```ts
// ✅ Better: snapshot + guard
notify(value: T) {
  const snapshot = [...this.observers];
  for (const o of snapshot) {
    if (this.observers.includes(o)) o(value); // still registered?
  }
}
```

Even better: use a `Set` and iterate a copy; mark subscriptions “closed” instead of splicing during dispatch.

---

## 3. One throwing observer breaks the rest

**Pitfall:** A single observer throws synchronously and aborts notification for everyone else.

```ts
// ❌ Bad
notify(v: T) {
  for (const o of this.observers) o(v); // throws -> rest skipped
}
```

```ts
// ✅ Better: isolate failures
notify(v: T) {
  for (const o of [...this.observers]) {
    try {
      o(v);
    } catch (e) {
      // report, don't rethrow
      this.onError?.(e);
    }
  }
}
```

If you want RxJS semantics, errors terminate the stream—make that explicit rather than accidental.

---

## 4. Reentrant / recursive notifications

**Pitfall:** Observer A calls `subject.next()` again synchronously, leading to deep reentrancy, stack overflow, or surprising ordering.

```ts
// ❌ Bad: synchronous reentrancy
subject.subscribe((x) => {
  if (x < 3) subject.next(x + 1); // reentrant
});
subject.next(0);
```

```ts
// ✅ Better: defer or queue
subject.subscribe((x) => {
  if (x < 3) queueMicrotask(() => subject.next(x + 1));
});
```

Or design your subject to reject/queue nested `next` calls.

---

## 5. Duplicate subscriptions

**Pitfall:** Calling `subscribe` twice (e.g., in `useEffect` without cleanup) registers the same handler twice.

```ts
// ❌ Bad
useEffect(() => {
  source$.subscribe(handler); // no cleanup -> duplicates on re-render
}, []);
```

```ts
// ✅ Better
useEffect(() => {
  const sub = source$.subscribe(handler);
  return () => sub.unsubscribe();
}, []);
```

Also consider deduplicating handlers or using a `Set` of observers if identity matters.

---

## 6. `this` binding loss

**Pitfall:** Passing a method reference loses `this`.

```ts
// ❌ Bad
bus.on("event", this.handle); // `this` is undefined
```

```ts
// ✅ Better
bus.on("event", (e) => this.handle(e));
// or
bus.on("event", this.handle.bind(this));
```

Arrow functions in class fields also work: `handle = (e: E) => {...}`.

---

## 7. Exposing a mutable Subject as “Observable”

**Pitfall:** Consumers can call `.next()` on your stream, breaking encapsulation.

```ts
// ❌ Bad
class Store {
  readonly state$ = new Subject<State>(); // anyone can next()
}
```

```ts
// ✅ Better: private Subject, public Observable
class Store {
  private readonly _state$ = new Subject<State>();
  readonly state$ = this._state$.asObservable();
}
```

---

## 8. Calling `next` after `complete`/`error`

**Pitfall:** Late emissions are silently ignored (or worse, throw) depending on implementation.

```ts
// ❌ Bad: no guard
next(v: T) {
  for (const o of this.observers) o(v);
}
```

```ts
// ✅ Better: closed flag
private closed = false;
next(v: T) {
  if (this.closed) return;
  for (const o of [...this.observers]) o(v);
}
complete() {
  this.closed = true;
  for (const o of [...this.observers]) o.complete?.();
  this.observers.clear();
}
```

---

## 9. Shared mutable payloads

**Pitfall:** Observers mutate the emitted object, corrupting state for other observers or future emissions.

```ts
// ❌ Bad
subject.next({ items: [1, 2] });
// observer does: payload.items.push(3) -> affects everyone
```

```ts
// ✅ Better: emit immutable snapshots
subject.next({ items: Object.freeze([1, 2]) });
// or clone on emit
next(v: T) { this.observers.forEach(o => o(structuredClone(v))); }
```

Combine with `Object.freeze` in dev and immutable updates in producers.

---

## 10. Sync vs async ambiguity

**Pitfall:** Observers can’t tell whether callbacks run synchronously or on a microtask; ordering and stack traces become unpredictable.

```ts
// ✅ Be explicit: document and keep consistent
class Subject<T> {
  // synchronous by default (like RxJS Subject)
  next(v: T) { ... }
}
// If you want async, use queueMicrotask/setTimeout consistently.
```

In RxJS, prefer `observeOn(asyncScheduler)` when you need async boundaries; don’t mix ad-hoc `setTimeout`.

---

## 11. No backpressure / slow consumers

**Pitfall:** A fast producer overwhelms a slow observer; events pile up or get dropped silently.

```ts
// ❌ Bad: unbounded buffering
source$.subscribe(slowHandler); // may OOM
```

```ts
// ✅ Better: choose a strategy explicitly
source$.pipe(
  bufferTime(100),          // batch
  // or throttleTime(50),   // drop
  // or mergeMap(x => ..., 4) concurrency limit
).subscribe(slowHandler);
```

If you write your own, add bounded queues and a defined overflow policy (drop oldest/newest/error).

---

## 12. Unsubscription not idempotent

**Pitfall:** Calling `unsubscribe()` twice throws or double-frees.

```ts
// ❌ Bad
unsubscribe() {
  const i = this.observers.indexOf(this.fn);
  this.observers.splice(i, 1); // -1 -> splice last? throws if not found
}
```

```ts
// ✅ Better
unsubscribe() {
  if (this.closed) return;
  this.closed = true;
  this.observers.delete(this.fn);
}
```

---

## 13. Circular observer dependencies

**Pitfall:** A depends on B’s event, B depends on A’s event → infinite loop or inconsistent state.

```ts
// ❌ Bad
a$.subscribe(() => b$.next(...));
b$.subscribe(() => a$.next(...));
```

**Fix:** Introduce a coordinator / reducer, or break cycles with explicit state machines. Log and detect reentrancy depth.

---

## 14. Losing errors in async observers

**Pitfall:** `async` observer returns a rejected promise that nobody awaits.

```ts
// ❌ Bad
source$.subscribe(async (x) => {
  await mayThrow(x); // unhandled rejection
});
```

```ts
// ✅ Better
source$.subscribe({
  next: async (x) => {
    try { await mayThrow(x); }
    catch (e) { handleError(e); }
  }
});
```

Or wrap with `from(promise)`/`catchError` in RxJS.

---

## 15. Race conditions with “latest value” reads

**Pitfall:** Observer reads shared state that has already changed by the time callback runs (especially with async scheduling).

```ts
// ❌ Bad
let current = 0;
source$.subscribe(async () => {
  await delay(10);
  console.log(current); // may not be the value at emission time
});
```

```ts
// ✅ Better: close over the emitted value
source$.subscribe((value) => {
  queueMicrotask(async () => {
    await delay(10);
    console.log(value); // snapshot
  });
});
```

---

## 16. Forgetting framework change-detection / batching

**Pitfall (Angular/React/Vue):** Observers update state outside the framework’s zone, so UI doesn’t re-render; or many emissions cause many renders.

```ts
// Angular: run inside NgZone or use async pipe
// React: batch updates or use useMemo/useEffect
// Vue: mutations must be tracked; use reactive/computed
```

Prefer framework-native reactivity (`async` pipe, `toSignal`, `useSyncExternalStore`) over manual subscriptions.

---

# A small, safer base implementation

```ts
type Unsubscribe = () => void;

export class Subject<T> {
  private observers = new Set<(v: T) => void>();
  private closed = false;

  subscribe(fn: (v: T) => void): Unsubscribe {
    if (this.closed) throw new Error("Subject is closed");
    this.observers.add(fn);
    return () => this.observers.delete(fn);
  }

  next(v: T) {
    if (this.closed) return;
    // snapshot to allow mutation during dispatch
    const snap = [...this.observers];
    for (const o of snap) {
      if (!this.observers.has(o)) continue; // removed during dispatch
      try {
        o(v);
      } catch (e) {
        // delegate to your error channel; don't kill the loop
        console.error("observer error", e);
      }
    }
  }

  asObservable() {
    return {
      subscribe: (fn: (v: T) => void) => this.subscribe(fn),
    };
  }

  complete() {
    if (this.closed) return;
    this.closed = true;
    const snap = [...this.observers];
    this.observers.clear();
    for (const o of snap) o.complete?.();
  }
}
```

### Quick checklist

- [ ] Every subscription has an owner and teardown.
- [ ] Dispatch iterates a snapshot; observers can unsubscribe safely.
- [ ] Errors are contained per observer.
- [ ] Payloads are immutable (or cloned).
- [ ] Reentrancy is either forbidden or explicitly deferred.
- [ ] Subjects are private; expose read-only observables.
- [ ] Async observers handle their own errors.
- [ ] Backpressure strategy is documented.
- [ ] Framework integration uses native async helpers.

If you tell me your stack (RxJS, Node EventEmitter, Angular, React, Vue, or a custom bus), I can narrow this to the pitfalls that matter most there.

## Exercise

**Build a small "Weather Station" using the Observer pattern.**

Requirements:
- A `WeatherStation` holds a temperature.
- Multiple displays can subscribe to it.
- When the temperature changes, every subscribed display is notified and re-renders.
- Displays can be unsubscribed at runtime.
- Add at least two different display types (e.g., a console logger and a high-temperature alert).

---

## Step-by-step solution

### Step 1 — Define the contracts

The Observer pattern has two roles: a **Subject** (the thing being watched) and **Observers** (things that react). We express both as interfaces so concrete classes stay decoupled.

```typescript
// observer.ts
export interface Observer {
  update(temperature: number): void;
}

export interface Subject {
  attach(observer: Observer): void;
  detach(observer: Observer): void;
  notify(): void;
}
```

### Step 2 — Implement the concrete subject

The `WeatherStation` keeps a list of observers and broadcasts whenever `setTemperature` is called. Using a `Set` avoids duplicate subscriptions; filtering on detach keeps it simple and readable.

```typescript
// weather-station.ts
import { Observer, Subject } from "./observer";

export class WeatherStation implements Subject {
  private observers = new Set<Observer>();
  private temperature = 0;

  attach(observer: Observer): void {
    this.observers.add(observer);
  }

  detach(observer: Observer): void {
    this.observers.delete(observer);
  }

  notify(): void {
    for (const observer of this.observers) {
      observer.update(this.temperature);
    }
  }

  setTemperature(value: number): void {
    if (value === this.temperature) return; // avoid noisy no-op notifications
    this.temperature = value;
    this.notify();
  }

  getTemperature(): number {
    return this.temperature;
  }
}
```

### Step 3 — Implement concrete observers

Each observer decides *how* to react. The subject doesn't know about alerts or console output — that's the whole point of the pattern.

```typescript
// displays.ts
import { Observer } from "./observer";

export class ConsoleDisplay implements Observer {
  update(temperature: number): void {
    console.log(`[ConsoleDisplay] Temperature is now ${temperature}°C`);
  }
}

export class AlertDisplay implements Observer {
  constructor(private readonly threshold: number) {}

  update(temperature: number): void {
    if (temperature > this.threshold) {
      console.warn(`[AlertDisplay] ⚠ HIGH TEMP: ${temperature}°C (threshold ${this.threshold}°C)`);
    } else {
      console.log(`[AlertDisplay] OK: ${temperature}°C`);
    }
  }
}

export class StatsDisplay implements Observer {
  private readings: number[] = [];

  update(temperature: number): void {
    this.readings.push(temperature);
    const avg = this.readings.reduce((a, b) => a + b, 0) / this.readings.length;
    console.log(`[StatsDisplay] avg=${avg.toFixed(1)}°C over ${this.readings.length} readings`);
  }
}
```

### Step 4 — Wire it up and demonstrate

```typescript
// main.ts
import { WeatherStation } from "./weather-station";
import { ConsoleDisplay, AlertDisplay, StatsDisplay } from "./displays";

const station = new WeatherStation();

const consoleDisplay = new ConsoleDisplay();
const alertDisplay = new AlertDisplay(30);
const statsDisplay = new StatsDisplay();

station.attach(consoleDisplay);
station.attach(alertDisplay);
station.attach(statsDisplay);

station.setTemperature(22);   // all three react
station.setTemperature(35);   // alert fires
station.detach(consoleDisplay);
station.setTemperature(18);   // console no longer reacts
```

Expected output (roughly):

```
