## Overview

Below is a **self-contained TypeScript profiling harness** that combines several complementary techniques:

1. **High-resolution timing** (`performance.now()`)  
2. **Performance marks/measures** (`performance.mark` / `performance.measure`) – these show up as labeled ranges in Chrome DevTools / `perf_hooks` observers.  
3. **CPU profiling** via the `node:inspector` `Profiler` domain – emits a `.cpuprofile` you can open in Chrome DevTools (flame chart).  
4. **Heap snapshots** via `node:v8` – for memory/retention analysis.  
5. **Event-loop lag** monitor – detects blocking on the main thread.  
6. **Memory usage** reporter.

It runs under `tsx`/`ts-node` with no extra config beyond `@types/node`.

---

### `profile.ts`

```ts
// profile.ts
import { performance, PerformanceObserver } from 'node:perf_hooks';
import { Session } from 'node:inspector';
import { writeHeapSnapshot } from 'node:v8';
import { writeFileSync } from 'node:fs';
import { cpus } from 'node:os';

/* ------------------------------------------------------------------ *
 * 1. High-resolution timing helpers
 * ------------------------------------------------------------------ */

export function time<T>(label: string, fn: () => T): T;
export function time<T>(label: string, fn: () => Promise<T>): Promise<T>;
export function time<T>(label: string, fn: () => T | Promise<T>): T | Promise<T> {
  const start = performance.now();
  const finish = (result: T) => {
    console.log(`[time] ${label}: ${(performance.now() - start).toFixed(3)} ms`);
    return result;
  };
  try {
    const r = fn();
    if (r instanceof Promise) return r.then(finish) as Promise<T>;
    return finish(r);
  } catch (e) {
    console.log(`[time] ${label}: FAILED after ${(performance.now() - start).toFixed(3)} ms`);
    throw e;
  }
}

/* ------------------------------------------------------------------ *
 * 2. Performance marks / measures (visible in DevTools timelines)
 * ------------------------------------------------------------------ */

const observer = new PerformanceObserver((list) => {
  for (const e of list.getEntries()) {
    console.log(`[measure] ${e.name}: ${e.duration.toFixed(3)} ms`);
  }
});
observer.observe({ entryTypes: ['measure'] });

export function measured<T>(name: string, fn: () => T): T;
export function measured<T>(name: string, fn: () => Promise<T>): Promise<T>;
export function measured<T>(name: string, fn: () => T | Promise<T>): T | Promise<T> {
  const startMark = `${name}::start`;
  const endMark = `${name}::end`;
  performance.mark(startMark);
  const finish = (result: T) => {
    performance.mark(endMark);
    performance.measure(name, startMark, endMark);
    return result;
  };
  try {
    const r = fn();
    if (r instanceof Promise) return r.then(finish) as Promise<T>;
    return finish(r);
  } catch (e) {
    performance.mark(endMark);
    performance.measure(`${name} (threw)`, startMark, endMark);
    throw e;
  }
}

/* ------------------------------------------------------------------ *
 * 3. Event-loop lag monitor (detects main-thread blocking)
 * ------------------------------------------------------------------ */

export function startLagMonitor(intervalMs = 100, thresholdMs = 5) {
  let last = performance.now();
  const id = setInterval(() => {
    const now = performance.now();
    const lag = now - last - intervalMs;
    if (lag > thresholdMs) {
      console.log(`[eventloop] lag ~${lag.toFixed(1)} ms (main thread blocked)`);
    }
    last = now;
  }, intervalMs);
  id.unref();
  return () => clearInterval(id);
}

/* ------------------------------------------------------------------ *
 * 4. Memory reporter
 * ------------------------------------------------------------------ */

export function logMemory(label: string) {
  const m = process.memoryUsage();
  const mb = (n: number) => (n / 1024 / 1024).toFixed(1) + ' MB';
  console.log(
    `[mem] ${label}: rss=${mb(m.rss)} heapUsed=${mb(m.heapUsed)} ` +
    `heapTotal=${mb(m.heapTotal)} external=${mb(m.external)}`,
  );
}

/* ------------------------------------------------------------------ *
 * 5. CPU profiling via inspector -> .cpuprofile (open in Chrome DevTools)
 * ------------------------------------------------------------------ */

export async function cpuProfile(
  label: string,
  fn: () => void | Promise<void>,
  samplingIntervalUs = 100,
): Promise<void> {
  const session = new Session();
  session.connect();

  const post = <P = unknown>(method: string, params?: unknown) =>
    new Promise<P>((resolve, reject) => {
      session.post(method, params as any, (err, result) => {
        if (err) reject(err);
        else resolve(result as P);
      });
    });

  await post('Profiler.enable');
  await post('Profiler.setSamplingInterval', { interval: samplingIntervalUs });
  await post('Profiler.start');

  await fn();

  const { profile } = await post<{ profile: unknown }>('Profiler.stop');
  session.disconnect();

  const file = `${label}.cpuprofile`;
  writeFileSync(file, JSON.stringify(profile));
  console.log(`[cpu] wrote ${file}  (load in Chrome DevTools → Performance)`);
}

/* ------------------------------------------------------------------ *
 * 6. Heap snapshot
 * ------------------------------------------------------------------ */

export function heapSnapshot(label: string): string {
  const file = writeHeapSnapshot(`${label}.heapsnapshot`);
  console.log(`[heap] wrote ${file}`);
  return file;
}

/* ------------------------------------------------------------------ *
 * Demo workload
 * ------------------------------------------------------------------ */

function fib(n: number): number {
  if (n < 2) return n;
  return fib(n - 1) + fib(n - 2);
}

function sortWork(n: number): number {
  const arr = Array.from({ length: n }, () => Math.random());
  arr.sort((a, b) => a - b);
  return arr[n - 1];
}

async function ioWork(ms: number) {
  await new Promise((r) => setTimeout(r, ms));
}

async function main() {
  console.log('CPUs available:', cpus().length);
  const stopLag = startLagMonitor();

  logMemory('start');

  // Sync CPU-bound, manually timed
  time('fib(38)', () => fib(38));

  // Sync with marks/measures
  measured('sort-100k', () => sortWork(100_000));

  // Async example
  await time('io+cpu', async () => {
    await ioWork(20);
    return measured('sort-50k-async', () => sortWork(50_000));
  });

  logMemory('before-snapshot');
  heapSnapshot('before');

  // Full CPU profile around a heavier workload
  await cpuProfile('heavy-workload', async () => {
    time('fib(40)', () => fib(40));
    measured('sort-200k', () => sortWork(200_000));
    await ioWork(10);
  });

  heapSnapshot('after');
  logMemory('end');

  stopLag();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

