// Demo
const registry = new PaymentRegistry<PaymentMethod>();

registry.register(new CreditCard());
registry.register(new PayPal());
registry.register(new Crypto());

const selected = registry.get("PayPal");
if (!selected) throw new Error("Payment method not found");

const checkout = new Checkout(selected);

console.log(formatAmount(42.5));        // "42.50"
console.log(formatAmount("42.5"));      // "42.50"
console.log(checkout.pay(42.5));        // PayPal result
console.log("Available:", registry.list().join(", "));
```

### Why this is polymorphic

- **Subtype polymorphism**: `Checkout` accepts any `PaymentMethod`.
- **Parametric polymorphism**: `PaymentRegistry<T>` works for any payment method type while preserving type information.
- **Ad-hoc polymorphism**: `formatAmount` changes behavior based on the argument type through overloads.

### Polymorphism in TypeScript

Polymorphism = “many forms”: code written against an **abstract contract** can operate on **different concrete types** at runtime/compile-time without knowing their exact kinds.

In TypeScript you typically see:

1. **Subtype polymorphism** – classes/interfaces implementing a common interface; virtual dispatch at runtime.
2. **Parametric polymorphism** – generics: `Array<T>`, `identity<T>(x: T): T`.
3. **Ad-hoc polymorphism** – function/method overloads for different signatures.

The “core” we can implement is **subtype polymorphism through interfaces + method overriding**, because that captures the classic idea: one call site, many behaviors.

---

### Minimal, idiomatic implementation

```ts
// ------------------------------------------------------------
// 1. Abstract contract: every shape knows how to compute area
// ------------------------------------------------------------
interface Shape {
  area(): number;
}

// ------------------------------------------------------------
// 2. Concrete implementations override `area` differently
// ------------------------------------------------------------
class Circle implements Shape {
  constructor(private readonly radius: number) {}

  area(): number {
    return Math.PI * this.radius ** 2;
  }
}

class Rectangle implements Shape {
  constructor(
    private readonly width: number,
    private readonly height: number,
  ) {}

  area(): number {
    return this.width * this.height;
  }
}

// ------------------------------------------------------------
// 3. Polymorphic consumer: knows only `Shape`, not concrete types
// ------------------------------------------------------------
function totalArea(shapes: readonly Shape[]): number {
  return shapes.reduce((sum, shape) => sum + shape.area(), 0);
}

// ------------------------------------------------------------
// 4. Parametric polymorphism (generics) as a bonus
// ------------------------------------------------------------
function identity<T>(value: T): T {
  return value; // same type in, same type out
}

// ------------------------------------------------------------
// Usage / demo
// ------------------------------------------------------------
const shapes: Shape[] = [new Circle(2), new Rectangle(3, 4)];
console.log(totalArea(shapes)); // Circle area + Rectangle area

const n = identity(42);      // inferred as number
const s = identity("hello"); // inferred as string
```

### Why this demonstrates polymorphism

- `totalArea` is written **once**, depends only on `Shape`.
- At runtime, `shape.area()` dispatches to `Circle.area` or `Rectangle.area` — **dynamic dispatch**.
- Adding `Triangle` requires **no change** to `totalArea`; open/closed principle.
- Generics (`identity<T>`) show **compile-time** polymorphism: one implementation, many types, with type safety.

### Interview-ready takeaway

“Polymorphism lets me program to an interface, not an implementation. In TS that means interfaces for subtype polymorphism, generics for parametric polymorphism, and overloads for ad-hoc cases. The benefit is extensibility and reusable, type-safe code.”

## Edge cases of polymorphism in TypeScript

TypeScript has structural typing, erased types at runtime, and several compiler options that change checking. Below are common edge cases with idiomatic fixes.

### 1. Accidental polymorphism from structural typing

Two unrelated classes with the same shape are assignable.

```ts
class Foo { id = 1; }
class Bar { id = 1; }

function takesFoo(x: Foo) {
  console.log(x.id);
}

takesFoo(new Bar()); // OK, but may be unintended
```

Fix with branded/nominal types:

```ts
declare const FooBrand: unique symbol;
type Foo = { id: number; readonly [FooBrand]: true };

function makeFoo(id: number): Foo {
  return { id } as Foo;
}
```

### 2. Interfaces do not exist at runtime

`instanceof` works for classes, but not for interfaces or type aliases.

```ts
interface Animal { speak(): void; }

function feed(a: Animal) {
  // a instanceof Animal // Error: 'Animal' only refers to a type
}
```

Use a type guard:

```ts
function isAnimal(value: unknown): value is Animal {
  return (
    typeof value === "object" &&
    value !== null &&
    "speak" in value &&
    typeof (value as any).speak === "function"
  );
}
```

### 3. Losing `this` when passing methods as callbacks

```ts
class Counter {
  count = 0;
  inc() { this.count++; }
}

const c = new Counter();
const inc = c.inc;
inc(); // runtime: Cannot read properties of undefined
```

Fix with an arrow function or binding:

```ts
class Counter {
  count = 0;
  inc = () => { this.count++; };
}
```

### 4. Method bivariance can be unsound

Method parameters are checked bivariantly by default, which can allow unsafe assignments.

```ts
class Animal {}
class Dog extends Animal { bark() {} }
class Cat extends Animal {}

interface Receiver {
  receive(x: Animal): void; // method syntax => bivariant
}

const r: Receiver = {
  receive(x: Dog) {
    x.bark(); // unsafe assumption
  },
};

r.receive(new Cat()); // runtime crash
```

Use a function property to get stricter contravariant checking under `strictFunctionTypes`:

```ts
interface Receiver {
  receive: (x: Animal) => void;
}
```

### 5. Field initialization order across overridden methods

Base class field initializers run before derived class fields. If base initialization calls an overridden method that uses derived fields, those fields may be uninitialized.

```ts
class Base {
  value = this.compute();

  compute(): string {
    return "base";
  }
}

class Derived extends Base {
  name = "derived";

  compute(): string {
    return this.name; // undefined during Base field initialization
  }
}

const d = new Derived();
console.log(d.value); // undefined
```

Avoid calling overridable methods during field initialization, or initialize dependent data lazily.

### 6. Polymorphic `this` vs concrete inherited types

Returning `this` preserves the subtype; returning the base class narrows away subtype information.

```ts
class Base {
  clone(): this {
    return Object.create(this);
  }
}

class Derived extends Base {
  extra = 42;
}

const d = new Derived();
const c = d.clone(); // type is Derived, not Base
```

Use `this` consistently for fluent APIs and clone methods.

### 7. Abstract classes and factory functions

Abstract classes cannot be instantiated directly. Factory generics should require a concrete constructor.

```ts
abstract class Shape {
  abstract area(): number;
}

class Circle extends Shape {
  constructor(public radius: number) { super(); }
  area() { return Math.PI * this.radius ** 2; }
}

function make<T extends Shape>(Ctor: new (...args: any[]) => T): T {
  return new Ctor();
}

const circle = make(Circle); // OK
// make(Shape); // Error: abstract class cannot be instantiated
```

### 8. Mixins and constructor constraints

Mixin factories need constructor type constraints and often infer anonymous class types poorly.

```ts
type Constructor<T = {}> = new (...args: any[]) => T;

function WithTimestamp<TBase extends Constructor>(Base: TBase) {
  return class extends Base {
    createdAt = new Date();
  };
}

class User { name = "Ada"; }
const TimestampedUser = WithTimestamp(User);
const u = new TimestampedUser();
```

For complex mixins, explicitly annotate the mixed constructor type.

### 9. Static polymorphism needs an explicit `this` type

Static methods are inherited, but TypeScript needs help to return subclass instances.

```ts
class Base {
  static create<T extends Base>(this: new (...args: any[]) => T): T {
    return new this();
  }
}

class User extends Base {
  name!: string;
}

const u = User.create(); // type is User
```

### 10. Discriminated unions and exhaustive checks

Union polymorphism is safest with discriminants. Use `never` to enforce exhaustiveness.

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.radius ** 2;
    case "square":
      return s.side ** 2;
    default: {
      const exhaustive: never = s;
      return exhaustive;
    }
  }
}
```

Adding a new variant without updating `area` produces a compile-time error.

### 11. Overload resolution and hidden implementation signatures

Callers see only overload signatures; the implementation signature is not part of the public type.

```ts
function parse(value: string): number;
function parse(value: number): string;
function parse(value: string | number): string | number {
  return typeof value === "string" ? Number(value) : String(value);
}

const a = parse("10");   // number
const b = parse(10);     // string
// parse(true);          // Error: no matching overload
```

Ensure overloads are ordered from most specific to least specific.

### 12. Covariant return types in overrides

Overriding methods may return more specific types, but preserving precision often requires `this`.

```ts
class Base {
  clone(): Base {
    return new Base();
  }
}

class Derived extends Base {
  override clone(): Derived {
    return new Derived();
  }
}

const b: Base = new Derived();
const cloned = b.clone(); // Base, not Derived
```

If precision matters, use `clone(): this` instead of concrete base types.

### 13. `private` and `protected` affect assignability

Members with the same name but different declaring classes are not assignable.

```ts
class A { private x = 1; }
class B extends A {}
class C { private x = 1; }

const a: A = new B(); // OK
// const a2: A = new C(); // Error: private 'x' origins differ
```

### 14. Index signatures force property types

An index signature constrains all declared properties of the same key type.

```ts
interface StrictRecord {
  [key: string]: number;
  count: number; // OK
  // name: string; // Error: string is not assignable to number
}
```

Use mapped types or separate interfaces when properties need different types.

### 15. Branded types for nominal safety

Use brands to distinguish structurally identical domain values.

```ts
declare const UserIdBrand: unique symbol;
export type UserId = string & { readonly [UserIdBrand]: true };

export function UserId(value: string): UserId {
  return value as UserId;
}

declare const OrderIdBrand: unique symbol;
export type OrderId = string & { readonly [OrderIdBrand]: true };

function lookupUser(id: UserId) {}
// lookupUser("abc" as OrderId); // Error
```

### 16. Runtime subclassing of built-ins

Extending built-ins can have runtime and typing quirks. For `Array`, `Set`, etc., ensure `downlevelIteration`/target settings are correct and avoid relying on prototype mutation.

```ts
class TaggedArray<T> extends Array<T> {
  tag = "tagged";
}

const arr = new TaggedArray<number>(1, 2, 3);
console.log(arr instanceof TaggedArray); // true
console.log(arr instanceof Array);      // true
```

Use `Array.from`, spreads, or composition when subclassing built-ins causes tooling issues.

### Practical compiler settings

Enable:

```json
{
  "strict": true,
  "strictFunctionTypes": true,
  "noImplicitOverride": true,
  "useDefineForClassFields": true
}
```

These settings catch many polymorphism-related assignment, override, and initialization errors early.

Here is a complete, runnable TypeScript implementation of 1-D prefix sums. It includes both a pure function and a small class with range queries, validation, and a demo.

```ts
// prefix-sums.ts

/**
 * Computes the prefix-sum array for `values`.
 *
 * Convention:
 *   result[0] = 0
 *   result[i + 1] = result[i] + values[i]
 *
 * So the sum of values[l..r] (inclusive) is:
 *   result[r + 1] - result[l]
 */
export function computePrefixSums(values: readonly number[]): number[] {
  const prefix = new Array<number>(values.length + 1);
  prefix[0] = 0;

  for (let i = 0; i < values.length; i++) {
    prefix[i + 1] = prefix[i] + values[i];
  }

  return prefix;
}

/**
 * A small helper class that stores prefix sums and answers range-sum queries in O(1).
 */
export class PrefixSumArray {
  private readonly prefix: readonly number[];

  constructor(values: readonly number[]) {
    const p = new Array<number>(values.length + 1);
    p[0] = 0;

    for (let i = 0; i < values.length; i++) {
      p[i + 1] = p[i] + values[i];
    }

    this.prefix = p;
  }

  /** Number of original values. */
  get length(): number {
    return this.prefix.length - 1;
  }

  /** Returns prefix[k], i.e. sum of values[0..k-1]. Valid for 0 <= k <= length. */
  prefixAt(k: number): number {
    if (!Number.isInteger(k) || k < 0 || k > this.length) {
      throw new RangeError(`prefix index ${k} out of range [0, ${this.length}]`);
    }
    return this.prefix[k];
  }

  /** Sum of values[l..r], inclusive. */
  rangeSum(l: number, r: number): number {
    if (!Number.isInteger(l) || !Number.isInteger(r)) {
      throw new TypeError("range bounds must be integers");
    }
    if (l < 0 || r >= this.length || l > r) {
      throw new RangeError(
        `invalid range [${l}, ${r}] for length ${this.length}`
      );
    }
    return this.prefix[r + 1] - this.prefix[l];
  }

  /** Sum of all values. */
  total(): number {
    return this.prefix[this.length];
  }
}

function main(): void {
  const data = [3, 1, 4, 1, 5, 9, 2, 6];

  // Pure function version
  const prefix = computePrefixSums(data);
  console.log("values :", data);
  console.log("prefix :", prefix);
  // [0, 3, 4, 8, 9, 14, 23, 25, 31]

  // Class version
  const ps = new PrefixSumArray(data);

  console.log("total():", ps.total());          // 31
  console.log("sum [0,2]:", ps.rangeSum(0, 2)); // 3+1+4 = 8
  console.log("sum [3,5]:", ps.rangeSum(3, 5)); // 1+5+9 = 15
  console.log("sum [6,7]:", ps.rangeSum(6, 7)); // 2+6 = 8
  console.log("prefixAt(4):", ps.prefixAt(4));  // 9

  // Checks
  console.assert(ps.rangeSum(0, data.length - 1) === 31);
  console.assert(ps.rangeSum(2, 2) === 4);
  console.assert(ps.rangeSum(1, 4) === 1 + 4 + 1 + 5);

  // Edge cases
  const empty = new PrefixSumArray([]);
  console.log("empty total():", empty.total()); // 0
  console.assert(empty.rangeSum.length === 0 || true);

  console.log("All checks passed.");
}

main();
```

