### Common Interview Follow-ups

#### 1. Subarray with target sum
```typescript
function countSubarraysWithSum(nums: number[], target: number): number {
  // Map from prefix sum -> frequency seen so far.
  const seen = new Map<number, number>([[0, 1]]);
  let running = 0;
  let count = 0;

  for (const x of nums) {
    running += x;
    // If (running - target) existed earlier, those subarrays sum to target.
    count += seen.get(running - target) ?? 0;
    seen.set(running, (seen.get(running) ?? 0) + 1);
  }
  return count;
}
```

#### 2. Longest subarray with sum ≤ K (positive numbers)
```typescript
function longestSubarraySumAtMostK(nums: number[], k: number): number {
  let best = 0;
  let left = 0;
  let running = 0;

  for (let right = 0; right < nums.length; right++) {
    running += nums[right];
    // Shrink from left while over budget.
    while (running > k && left <= right) {
      running -= nums[left++];
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

#### 3. 2D Prefix Sum (matrix)
```typescript
class MatrixPrefixSum {
  private readonly ps: number[][];

  constructor(matrix: number[][]) {
    const m = matrix.length;
    const n = matrix[0]?.length ?? 0;
    // ps has (m+1) x (n+1) with zero border.
    this.ps = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        this.ps[i + 1][j + 1] =
          matrix[i][j] +
          this.ps[i][j + 1] +
          this.ps[i + 1][j] -
          this.ps[i][j];
      }
    }
  }

  /** Sum of rectangle (r1,c1)..(r2,c2) inclusive. */
  rectSum(r1: number, c1: number, r2: number, c2: number): number {
    return (
      this.ps[r2 + 1][c2 + 1] -
      this.ps[r1][c2 + 1] -
      this.ps[r2 + 1][c1] +
      this.ps[r1][c1]
    );
  }
}
```

