---

### 2. Child process (IPC worker)

`src/child.ts`

```ts
// Runs in a separate process started with fork().
// It receives a message, does CPU work, replies, then exits.

interface Request {
  numbers: number[];
}

interface Response {
  sum: number;
  squares: number[];
}

process.on('message', (msg: Request) => {
  const sum = msg.numbers.reduce((a, b) => a + b, 0);
  const squares = msg.numbers.map((n) => n * n);

  const result: Response = { sum, squares };
  process.send?.(result);

  // Explicit exit so the parent sees a clean code 0.
  process.exit(0);
});

// If the parent dies, avoid a zombie.
process.on('disconnect', () => process.exit(0));
```

---

### 3. Parent process

`src/parent.ts`

```ts
import { fork, spawn, ChildProcess } from 'child_process';
import path from 'path';

const isWin = process.platform === 'win32';

function linePrefixer(
  stream: NodeJS.ReadableStream,
  label: string,
  out: NodeJS.WritableStream
): void {
  let buffer = '';
  stream.on('data', (chunk: Buffer) => {
    buffer += chunk.toString();
    const parts = buffer.split('\n');
    buffer = parts.pop() ?? '';
    for (const line of parts) out.write(`[${label}] ${line}\n`);
  });
  stream.on('end', () => {
    if (buffer) out.write(`[${label}] ${buffer}\n`);
  });
}

// ---------- 1) Fork + IPC ----------
const childPath = path.join(__dirname, 'child.js'); // compiled output
const worker: ChildProcess = fork(childPath, [], {
  stdio: ['inherit', 'inherit', 'inherit', 'ipc'],
});

worker.send({ numbers: [1, 2, 3, 4, 5] });

worker.on('message', (msg) => {
  console.log('IPC result from child:', msg);
});

worker.on('error', (err) => {
  console.error('Failed to start child:', err);
});

worker.on('exit', (code, signal) => {
  console.log(`\nChild exited (code=${code}, signal=${signal})`);
});

// ---------- 2) Spawn external command ----------
const cmd = isWin ? 'cmd.exe' : 'ls';
const args = isWin ? ['/c', 'dir', '/b'] : ['-la'];

const proc = spawn(cmd, args, {
  stdio: ['ignore', 'pipe', 'pipe'],
  shell: false,
});

linePrefixer(proc.stdout!, 'out', process.stdout);
linePrefixer(proc.stderr!, 'err', process.stderr);

proc.on('error', (err) => {
  console.error('Spawn error:', err.message);
});

proc.on('exit', (code, signal) => {
  console.log(`Spawned process exited (code=${code}, signal=${signal})`);
});

// ---------- 3) Signal propagation ----------
const forward = (sig: NodeJS.Signals) => {
  console.log(`\nParent received ${sig}, forwarding to child…`);
  if (!worker.killed) worker.kill(sig);
  if (!proc.killed) proc.kill(sig);
};

process.on('SIGINT', () => forward('SIGINT'));
process.on('SIGTERM', () => forward('SIGTERM'));

// Exit parent with an error code if any child failed.
let exitCode = 0;
worker.on('exit', (c) => { if (c !== 0 && c !== null) exitCode = c ?? 1; });
proc.on('exit', (c) => { if (c !== 0 && c !== null) exitCode = c ?? 1; });

process.on('exit', () => {
  process.exitCode = exitCode;
});
```

