## Key concepts explained

| Concept | Why it matters |
|---|---|
| `fork()` | Creates a child Node process with an **IPC channel**; ideal for CPU-bound work without blocking the event loop. |
| `spawn()` | Launches an arbitrary executable with streamed `stdout`/`stderr`; good for CLI tools and long-running jobs. |
| `stdio: 'pipe'` | Lets the parent read output incrementally instead of buffering everything. |
| `process.send` / `'message'` | Typed IPC messages between parent and child. |
| Signal forwarding | Prevents orphaned/zombie children when the parent is terminated. |
| Exit-code propagation | Makes the parent reflect child failures in shell scripts/CI. |

---

## Final solution files

- `src/child.ts` — IPC worker computing sum/squares.
- `src/parent.ts` — forks worker, spawns `ls`/`dir`, streams output, forwards signals, propagates exit code.

Compile with `npx tsc`, run with `node dist/parent.js`.

## Concepts (Node.js / TypeScript context)

**Process** — the OS instance running your program. In Node you interact via the global `process`: `process.pid`, `process.argv`, `process.env`, `process.exitCode`, signals (`process.on('SIGTERM', …)`), and stdio streams.

**Subprocess** — a child OS process spawned by the parent. Node exposes this through the `child_process` module:
- `spawn(cmd, args, opts)` — launches directly (no shell by default), streams stdout/stderr. Best for long-running or large output.
- `exec(cmd, opts)` — runs through a shell, buffers all output (cap ~1MB by default). Convenient but risky with untrusted input.
- `execFile(file, args)` — like `exec` but no shell (safer).
- `fork(modulePath)` — specialized `spawn` that creates a new Node instance with an IPC channel (`process.send` / `process.on('message')`).

Key concerns in production:
- **Backpressure & memory** — buffer limits; prefer streams + caps.
- **Lifecycle** — `exit` (process ended) vs `close` (stdio flushed). Use `close` to read final output.
- **Signals** — `SIGTERM` (graceful), `SIGKILL` (forced), `SIGINT` (Ctrl-C).
- **Timeouts / cancellation** — `AbortSignal` + kill escalation.
- **Cleanup** — track children; kill them on parent exit to avoid orphans/zombies.
- **Security** — avoid `shell: true` with untrusted input.

---

## Implementation (core runner + supervisor)

```ts
// process-runner.ts
import {
  spawn,
  type ChildProcess,
  type ChildProcessWithoutNullStreams,
} from 'node:child_process';

// ---------- Public types ----------

export type RunEncoding = 'utf8' | 'ascii' | 'base64';

export interface RunOptions {
  /** Arguments for the command (used with spawn; ignored if shell=true and command contains spaces is on you). */
  args?: string[];
  /** Working directory. */
  cwd?: string;
  /** Environment variables merged over process.env. */
  env?: NodeJS.ProcessEnv;
  /** Hard timeout after which the child is killed. */
  timeoutMs?: number;
  /** Grace period between SIGTERM and SIGKILL when killing. */
  killGraceMs?: number;
  /** Max bytes captured for stdout/stderr each. Excess is truncated. */
  maxOutputBytes?: number;
  /** Abort signal for cancellation. */
  signal?: AbortSignal;
  /** Run through a shell (less safe; needed for pipes/redirections). */
  shell?: boolean;
  /** stdio encoding. */
  encoding?: RunEncoding;
  /** Detach from parent (survives parent exit). Default false. */
  detached?: boolean;
}

export interface RunResult {
  command: string;
  code: number | null;          // exit code, null if terminated by signal
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
  stdoutTruncated: boolean;
  stderrTruncated: boolean;
  killed: boolean;              // terminated by timeout/abort/kill
  durationMs: number;
}

export class ProcessError extends Error {
  constructor(
    message: string,
    public readonly result?: Partial<RunResult>,
    public readonly cause?: unknown,
  ) {
    super(message);
    this.name = 'ProcessError';
  }
}

// ---------- Core runner ----------

const DEFAULTS = {
  timeoutMs: 0,
  killGraceMs: 3000,
  maxOutputBytes: 10 * 1024 * 1024, // 10 MB
  encoding: 'utf8' as RunEncoding,
};

/**
 * Spawn a command and resolve with a structured result.
 * Resolves (not rejects) on non-zero exit codes; rejects only on spawn
 * failures, timeouts configured to throw, or aborts.
 */
export function runCommand(
  command: string,
  options: RunOptions = {},
): Promise<RunResult> {
  const opts = { ...DEFAULTS, ...options };
  const start = Date.now();

  return new Promise<RunResult>((resolve, reject) => {
    let child: ChildProcess;
    try {
      child = spawn(command, opts.args ?? [], {
        cwd: opts.cwd,
        env: { ...process.env, ...opts.env },
        shell: opts.shell ?? false,
        detached: opts.detached ?? false,
        // Pipe all stdio so we can capture + control.
        stdio: ['ignore', 'pipe', 'pipe'],
      });
    } catch (err) {
      reject(new ProcessError('Failed to spawn process', undefined, err));
      return;
    }

    const stdoutChunks: Buffer[] = [];
    const stderrChunks: Buffer[] = [];
    let stdoutBytes = 0;
    let stderrBytes = 0;
    let stdoutTruncated = false;
    let stderrTruncated = false;
    let killed = false;
    let finished = false;

    const finish = (result: RunResult) => {
      if (finished) return;
      finished = true;
      clearTimeout(timeoutHandle);
      abortListener?.();
      resolve(result);
    };

    const killChild = (signal: NodeJS.Signals) => {
      if (child.killed) return;
      try {
        // For detached process groups, kill the whole group.
        if (opts.detached && child.pid) {
          process.kill(-child.pid, signal);
        } else {
          child.kill(signal);
        }
      } catch {
        /* ignore: may already be dead */
      }
    };

    const escalateKill = () => {
      killChild('SIGTERM');
      setTimeout(() => {
        if (!finished) killChild('SIGKILL');
      }, opts.killGraceMs).unref();
    };

    // Timeout
    let timeoutHandle: NodeJS.Timeout | undefined;
    if (opts.timeoutMs && opts.timeoutMs > 0) {
      timeoutHandle = setTimeout(() => {
        killed = true;
        escalateKill();
      }, opts.timeoutMs);
      timeoutHandle.unref();
    }

    // AbortSignal support
    let abortListener: (() => void) | undefined;
    if (opts.signal) {
      if (opts.signal.aborted) {
        killed = true;
        // Defer so spawn error path is uniform
        process.nextTick(() => escalateKill());
      }
      abortListener = () => {
        killed = true;
        escalateKill();
      };
      opts.signal.addEventListener('abort', abortListener, { once: true });
    }

    const capture = (
      stream: NodeJS.ReadableStream | null,
      chunks: Buffer[],
      onBytes: (n: number) => void,
      onTrunc: () => void,
      counter: { v: number },
    ) => {
      if (!stream) return;
      stream.on('data', (chunk: Buffer) => {
        if (counter.v >= opts.maxOutputBytes) {
          if (!onTrunc()) return;
          // ensure flag set once
          return;
        }
        const remaining = opts.maxOutputBytes - counter.v;
        if (chunk.length <= remaining) {
          chunks.push(chunk);
          counter.v += chunk.length;
        } else {
          chunks.push(chunk.subarray(0, remaining));
          counter.v = opts.maxOutputBytes;
          onTrunc();
        }
      });
    };

    const stdoutCounter = { v: 0 };
    const stderrCounter = { v: 0 };
    // Track truncation via closure booleans
    let stdoutTruncSet = false;
    let stderrTruncSet = false;

    capture(
      child.stdout,
      stdoutChunks,
      () => stdoutBytes,
      () => { if (!stdoutTruncSet) { stdoutTruncSet = true; stdoutTruncated = true; } return true; },
      stdoutCounter,
    );
    capture(
      child.stderr,
      stderrChunks,
      () => stderrBytes,
      () => { if (!stderrTruncSet) { stderrTruncSet = true; stderrTruncated = true; } return true; },
      stderrCounter,
    );

    child.on('error', (err) => {
      finish({
        command,
        code: null,
        signal: null,
        stdout: Buffer.concat(stdoutChunks).toString(opts.encoding),
        stderr: Buffer.concat(stderrChunks).toString(opts.encoding),
        stdoutTruncated,
        stderrTruncated,
        killed,
        durationMs: Date.now() - start,
      });
      // Surface spawn errors (ENOENT etc.) as rejection
      reject(new ProcessError('Process failed to start', undefined, err));
    });

    child.on('close', (code, signal) => {
      finish({
        command,
        code,
        signal: signal as NodeJS.Signals | null,
        stdout: Buffer.concat(stdoutChunks).toString(opts.encoding),
        stderr: Buffer.concat(stderrChunks).toString(opts.encoding),
        stdoutTruncated,
        stderrTruncated,
        killed,
        durationMs: Date.now() - start,
      });
    });
  });
}

// ---------- Supervisor: track + clean up children ----------

export class ProcessSupervisor {
  private children = new Set<ChildProcess>();

  spawn(command: string, args: string[] = [], opts: RunOptions = {}): ChildProcessWithoutNullStreams {
    const child = spawn(command, args, {
      ...opts,
      stdio: ['ignore', 'pipe', 'pipe'],
    }) as ChildProcessWithoutNullStreams;
    this.children.add(child);
    const remove = () => this.children.delete(child);
    child.on('close', remove);
    child.on('error', remove);
    return child;
  }

  killAll(signal: NodeJS.Signals = 'SIGTERM'): void {
    for (const c of this.children) {
      try { c.kill(signal); } catch { /* ignore */ }
    }
  }

  size(): number { return this.children.size; }
}

// Install global cleanup so children don't outlive the parent.
let globalSupervisor: ProcessSupervisor | null = null;
export function getGlobalSupervisor(): ProcessSupervisor {
  if (!globalSupervisor) {
    globalSupervisor = new ProcessSupervisor();
    const cleanup = () => globalSupervisor?.killAll('SIGTERM');
    process.on('exit', cleanup);
    process.on('SIGINT', () => { cleanup(); process.exit(130); });
    process.on('SIGTERM', () => { cleanup(); process.exit(143); });
    process.on('uncaughtException', () => { cleanup(); process.exit(1); });
  }
  return globalSupervisor;
}
```

### Usage example

```ts
import { runCommand } from './process-runner';

async function main() {
  const res = await runCommand('node', {
    args: ['--version'],
    timeoutMs: 5_000,
  });
  console.log(res); // { code: 0, stdout: 'v20.x.x\n', ... }

  // Shell pipeline (trusted only)
  const ls = await runCommand('sh', {
    args: ['-c', 'ls -la | head -n 5'],
    shell: false,
  });
  console.log(ls.stdout);

  // Cancellation
  const ac = new AbortController();
  const p = runCommand('sleep', { args: ['10'], signal: ac.signal });
  setTimeout(() => ac.abort(), 100);
  try { await p; } catch (e) { console.log('aborted'); }
}

main().catch(console.error);
```

### Notes on correctness

- We resolve on `close` (not `exit`) so stdout/stderr are fully flushed.
- Timeout uses `SIGTERM` then `SIGKILL` after a grace period; `.unref()` prevents the timer from keeping the event loop alive.
- Output is capped per stream to avoid OOM on chatty children; truncation flags are set.
- `AbortSignal` is supported and mirrors timeout behavior.
- The supervisor + global handlers prevent orphaned children and zombie processes when the parent exits.
- For IPC between Node processes, prefer `fork()` + `process.send`/`on('message')` instead of parsing stdout.

When working with processes and subprocesses in TypeScript (usually through Node.js `child_process`), the main risks are around **lifecycles, streams, signals, platform differences, and security**. The examples below assume Node.js + TypeScript.

## 1. Distinguish `error`, `exit`, and `close`

A failed spawn emits `error`; process completion emits `exit`; stdio completion emits `close`. Handle all three and guard against double resolution.

```ts
import { spawn, ChildProcess } from "node:child_process";

interface RunResult {
  code: number | null;
  signal: NodeJS.Signals | null;
  stdout: string;
  stderr: string;
}

function run(file: string, args: string[]): Promise<RunResult> {
  return new Promise((resolve, reject) => {
    const child: ChildProcess = spawn(file, args, {
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let settled = false;

    const finish = (fn: () => void) => {
      if (settled) return;
      settled = true;
      fn();
    };

    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");

    child.stdout?.on("data", (chunk: string) => (stdout += chunk));
    child.stderr?.on("data", (chunk: string) => (stderr += chunk));

    // Spawn failure: ENOENT, permission error, etc.
    child.on("error", (err) => finish(() => reject(err)));

    // Final stdio flush point.
    child.on("close", (code, signal) => {
      finish(() => resolve({ code, signal, stdout, stderr }));
    });
  });
}
```

## 2. Treat `null` exit codes as signal termination

A process killed by a signal often has `code === null` and `signal !== null`.

```ts
function assertSuccess(result: RunResult): void {
  if (result.signal !== null) {
    throw new Error(`Process terminated by signal ${result.signal}`);
  }
  if (result.code !== 0) {
    throw new Error(`Process failed with exit code ${result.code}: ${result.stderr}`);
  }
}
```

## 3. Avoid shell injection: prefer `spawn`/`execFile` with argument arrays

`exec` builds a shell command string. User input can inject commands.

```ts
// Dangerous
import { exec } from "node:child_process";
exec(`grep ${userInput} file.txt`, callback);

// Safer
import { execFile } from "node:child_process";
execFile("grep", [userInput, "file.txt"], (err, stdout) => {
  if (err) throw err;
});
```

Also prevent argument injection with `--`:

```ts
// User input could be "-rf" or "--help"
spawn("rm", ["--", userInput]);
```

## 4. Handle Windows `.cmd`/`.bat` wrappers

On Windows, commands such as `npm` are often `.cmd` files and cannot be spawned directly without a shell.

```ts
import { spawn } from "node:child_process";

const npm = process.platform === "win32" ? "npm.cmd" : "npm";

const child = spawn(npm, ["run", "build"], {
  stdio: "inherit",
  windowsHide: true,
});
```

If you use `shell: true`, you reintroduce quoting and injection concerns.

## 5. Consume stdout/stderr to avoid pipe deadlock

If a child writes a lot to stdout/stderr and nobody reads, its pipe buffer fills and the process blocks.

```ts
const child = spawn("ffmpeg", ["-i", input, "output.mp4"], {
  stdio: ["ignore", "pipe", "pipe"],
});

child.stdout.on("data", (data: Buffer) => {
  // consume or stream
});

child.stderr.on("data", (data: Buffer) => {
  // ffmpeg writes progress to stderr
});
```

For very large output, stream instead of buffering:

```ts
import { pipeline } from "node:stream/promises";
import { createWriteStream } from "node:fs";
import { spawn } from "node:child_process";

const child = spawn("tar", ["cf", "-", "directory"]);
await pipeline(child.stdout, createWriteStream("archive.tar"));

const [code] = await new Promise<[number | null]>((resolve) => {
  child.on("close", (code) => resolve([code]));
});

if (code !== 0) throw new Error(`tar exited with ${code}`);
```

## 6. Handle `EPIPE` when writing to stdin

If the child exits early, writing to `stdin` can throw `EPIPE`.

```ts
const child = spawn("sort", [], { stdio: ["pipe", "pipe", "pipe"] });

child.stdin.on("error", (err: NodeJS.ErrnoException) => {
  if (err.code !== "EPIPE") throw err;
  // Expected if sort exited before all input was consumed.
});

child.stdin.write("banana\n");
child.stdin.write("apple\n");
child.stdin.end();
```

Also respect backpressure:

```ts
const ok = child.stdin.write(largeChunk);
if (!ok) {
  await new Promise<void>((resolve) => child.stdin.once("drain", resolve));
}
```

## 7. Implement timeouts with escalation

Do not rely only on `SIGTERM`; some processes ignore it. Escalate to `SIGKILL`.

```ts
function runWithTimeout(file: string, args: string[], timeoutMs: number): Promise<RunResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(file, args, { stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let exited = false;

    const timer = setTimeout(() => {
      if (exited) return;
      child.kill("SIGTERM");

      const killTimer = setTimeout(() => {
        if (!exited) child.kill("SIGKILL");
      }, 2000);

      child.on("exit", () => clearTimeout(killTimer));
    }, timeoutMs);

    child.stdout?.on("data", (d: Buffer) => (stdout += d.toString()));
    child.stderr?.on("data", (d: Buffer) => (stderr += d.toString()));

    child.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });

    child.on("close", (code, signal) => {
      exited = true;
      clearTimeout(timer);
      resolve({ code, signal, stdout, stderr });
    });
  });
}
```

Modern Node versions also support `signal` in spawn options, but manual escalation remains useful for compatibility and tree-killing.

## 8. Kill process trees, not just the direct child

A shell or wrapper may spawn grandchildren. Killing only the parent can orphan them.

```ts
import { spawn } from "node:child_process";

const child = spawn("sh", ["-c", "long-running-child & wait"], {
  detached: true,
  stdio: "ignore",
});

// Unix: negative PID targets the process group.
function killTree(pid: number, signal: NodeJS.Signals = "SIGTERM") {
  try {
    process.kill(-pid, signal);
  } catch {
    // Fall back for non-group leaders / unsupported platforms.
    try {
      process.kill(pid, signal);
    } catch {
      // Already exited.
    }
  }
}

// killTree(child.pid!);
```

On Windows, use `taskkill /PID <pid> /T /F` or a library such as `tree-kill`. Process groups and signals behave differently there.

## 9. Avoid orphaned detached children

`detached: true` plus `unref()` lets the parent exit while the child continues. Use intentionally, and avoid accidental daemons.

```ts
const child = spawn("node", ["daemon.js"], {
  detached: true,
  stdio: "ignore",
});

// Child becomes independent.
child.unref();
```

If the parent should own the child’s lifetime, do not detach/unref; instead kill children during shutdown.

## 10. Forward parent signals to children

When the parent receives `SIGINT` or `SIGTERM`, forward it to managed children.

```ts
import { spawn, ChildProcess } from "node:child_process";

const children = new Set<ChildProcess>();

function track(child: ChildProcess) {
  children.add(child);
  child.on("exit", () => children.delete(child));
}

const child = spawn("node", ["worker.js"], { stdio: "inherit" });
track(child);

function shutdown(signal: NodeJS.Signals) {
  for (const c of children) {
    try {
      c.kill(signal);
    } catch {
      // ignore
    }
  }
}

process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));
```

Also prefer setting `process.exitCode` over calling `process.exit()` immediately, so async cleanup can finish.

## 11. Use `fork` IPC carefully

`fork` creates an IPC channel. Messages must be serializable, and channel state can change.

```ts
import { fork, ChildProcess } from "node:child_process";

const child = fork("./worker.ts", [], {
  serialization: "advanced", // supports more types than JSON
});

const accepted = child.send({ type: "job", id: 42 }, (err) => {
  if (err) console.error("Send failed:", err);
});

if (!accepted) {
  console.warn("IPC channel is full or closed");
}

child.on("message", (msg: unknown) => {
  if (typeof msg === "object" && msg !== null && "type" in msg) {
    console.log("worker message:", msg);
  }
});

child.on("disconnect", () => {
  console.log("IPC disconnected");
});

child.on("exit", (code, signal) => {
  console.log("worker exited", code, signal);
});
```

Edge cases: circular objects fail serialization; large messages can block; `send` returns `false` under backpressure.

## 12. Validate `cwd` and control environment

A missing `cwd` throws `ENOENT`. Inherited environment can leak secrets to untrusted subprocesses.

```ts
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";

const cwd = "/opt/app";

if (!existsSync(cwd)) {
  throw new Error(`Working directory does not exist: ${cwd}`);
}

// Allowlist environment instead of passing everything.
const env = {
  PATH: process.env.PATH,
  NODE_ENV: process.env.NODE_ENV,
};

const child = spawn("node", ["script.js"], { cwd, env });
```

## 13. Handle TTY, colors, and inherited stdio

If a process needs interactive input or a TTY, pipes will not work.

```ts
spawn("vim", ["file.txt"], { stdio: "inherit" });
```

With inherited stdio, you cannot capture output. If you need both interaction and capture, use a PTY library such as `node-pty`.

## 14. Type stdout/stderr correctly

Depending on `stdio`, TypeScript’s `ChildProcess` types differ. If you declare `stdio: ["ignore", "pipe", "pipe"]`, stdout/stderr are non-null.

```ts
import { spawn } from "node:child_process";

const child = spawn("node", ["--version"], {
  stdio: ["ignore", "pipe", "pipe"],
});

// child.stdout and child.stderr are typed as Readable, not null.
child.stdout.setEncoding("utf8");
child.stdout.on("data", (chunk: string) => console.log(chunk.trim()));
```

If using optional stdio, guard with `child.stdout?.on(...)`.

## 15. Handle binary output correctly

Do not assume UTF-8. Either leave streams as buffers or set encoding deliberately.

```ts
const child = spawn("cat", ["image.png"], { stdio: ["ignore", "pipe", "ignore"] });

child.stdout.on("data", (chunk: Buffer) => {
  // Handle raw bytes.
});
```

For text:

```ts
child.stdout.setEncoding("utf8");
child.stdout.on("data", (chunk: string) => {
  // chunk is string
});
```

## 16. Limit concurrency to avoid resource exhaustion

Spawning too many processes can exhaust file descriptors or memory.

```ts
import pLimit from "p-limit";
import { run } from "./run";

const limit = pLimit(4);

await Promise.all(
  files.map((file) =>
    limit(() => run("ffmpeg", ["-i", file, `${file}.mp4`]))
  )
);
```

## 17. Avoid zombie processes

A child that exits but whose exit status is never collected can become a zombie on Unix. Always await or listen for `exit`/`close`.

```ts
const child = spawn("short-lived-task", []);

await new Promise<void>((resolve) => {
  child.on("exit", () => resolve());
});
```

## 18. Be careful with `exec`’s `maxBuffer`

`exec` buffers all output in memory and fails if it exceeds `maxBuffer`.

```ts
import { exec } from "node:child_process";

exec("some-command", { maxBuffer: 10 * 1024 * 1024 }, (err, stdout) => {
  if (err) throw err;
});
```

Prefer `spawn` for streaming or large output.

## 19. Use `stream/promises` and `finished` for reliable completion

When piping child output, track both stream completion and process exit.

```ts
import { finished } from "node:stream/promises";
import { spawn } from "node:child_process";
import { createWriteStream } from "node:fs";

const child = spawn("producer", []);
const out = createWriteStream("out.bin");

child.stdout.pipe(out);

await Promise.all([
  finished(child.stdout),
  new Promise<void>((resolve, reject) => {
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`exit ${code}`));
    });
  }),
]);
```

## 20. Add a reusable safe runner

A small wrapper reduces repeated edge-case handling.

```ts
import { spawn, ChildProcess } from "node:child_process";

export interface SafeRunOptions {
  timeoutMs?: number;
  cwd?: string;
  env?: NodeJS.ProcessEnv;
}

export async function safeRun(
  file: string,
  args: string[],
  options: SafeRunOptions = {}
): Promise<{ code: number | null; signal: NodeJS.Signals | null; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    const child: ChildProcess = spawn(file, args, {
      cwd: options.cwd,
      env: options.env,
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let exited = false;

    const timer =
      options.timeoutMs !== undefined
        ? setTimeout(() => {
            if (!exited) child.kill("SIGTERM");
            setTimeout(() => {
              if (!exited) child.kill("SIGKILL");
            }, 2000);
          }, options.timeoutMs)
        : undefined;

    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");

    child.stdout?.on("data", (d: string) => (stdout += d));
    child.stderr?.on("data", (d: string) => (stderr += d));

    child.on("error", (err) => {
      if (timer) clearTimeout(timer);
      reject(err);
    });

    child.on("close", (code, signal) => {
      exited = true;
      if (timer) clearTimeout(timer);
      resolve({ code, signal, stdout, stderr });
    });
  });
}
```

## Practical checklist

- Handle both `error` and `close`.
- Check `signal`, not just `code`.
- Use argument arrays, not shell strings.
- Quote/validate paths and use `--`.
- Consume or stream stdout/stderr.
- Catch `EPIPE` on stdin.
- Escalate `SIGTERM` to `SIGKILL`.
- Kill process trees on Unix/Windows appropriately.
- Forward parent signals to children.
- Validate `cwd` and allowlist `env`.
- Avoid accidental detached orphans.
- Type stdio and encoding deliberately.
- Limit concurrency.
- Use `maxBuffer` carefully or stream.
- Collect every child’s exit status.

## Pure functions in TypeScript

A **pure function** has two properties:

1. **Deterministic**: the same inputs always produce the same output.
2. **No side effects**: it does not mutate external state, perform I/O, read the clock, use randomness, or depend on mutable global state.

A good way to write pure TypeScript code is to:

- use `readonly` types,
- return new objects/arrays instead of mutating,
- keep I/O, time, randomness, and storage at the “edges” of the program,
- inject non-deterministic values such as `now` or `random` as parameters.

Below is a complete, runnable example using an immutable shopping-cart domain. Money is stored in integer cents to avoid floating-point errors.

### `pure.ts`

```ts
import assert from "node:assert/strict";

/* -------------------------------------------------------------------------- */
/* Domain types                                                               */
/* -------------------------------------------------------------------------- */

type CartItem = {
  readonly sku: string;
  readonly priceCents: number;
  readonly quantity: number;
};

type Cart = {
  readonly items: readonly CartItem[];
};

type Discount = {
  readonly percent: number; // e.g. 10 means 10%
};

/* -------------------------------------------------------------------------- */
/* Pure utility functions                                                     */
/* -------------------------------------------------------------------------- */

/** Add two integers. */
const add = (a: number, b: number): number => a + b;

/** Multiply two integers. */
const multiply = (a: number, b: number): number => a * b;

/** Calculate the total price for one cart line. */
const lineTotalCents = (item: CartItem): number =>
  multiply(item.priceCents, item.quantity);

/** Sum all line totals. */
const subtotalCents = (items: readonly CartItem[]): number =>
  items.reduce((sum, item) => add(sum, lineTotalCents(item)), 0);

/** Apply a percentage discount. Returns a new discounted amount. */
const applyDiscountCents = (amountCents: number, discount: Discount): number => {
  if (discount.percent < 0 || discount.percent > 100) {
    throw new RangeError("Discount percent must be between 0 and 100");
  }
  return Math.round(amountCents * (1 - discount.percent / 100));
};

/** Apply a tax rate. Rate is a fraction, e.g. 0.08 for 8%. */
const applyTaxCents = (amountCents: number, taxRate: number): number => {
  if (taxRate < 0) {
    throw new RangeError("Tax rate cannot be negative");
  }
  return Math.round(amountCents * (1 + taxRate));
};

/** Calculate the final cart total. */
const cartTotalCents = (
  cart: Cart,
  discount: Discount,
  taxRate: number
): number => {
  const subtotal = subtotalCents(cart.items);
  const discounted = applyDiscountCents(subtotal, discount);
  return applyTaxCents(discounted, taxRate);
};

/* -------------------------------------------------------------------------- */
/* Pure immutable state updates                                               */
/* -------------------------------------------------------------------------- */

/** Return a new cart with an item added. The original cart is unchanged. */
const addItem = (cart: Cart, item: CartItem): Cart => ({
  items: [...cart.items, item],
});

/** Return a new cart without items matching the predicate. */
const removeWhere = (
  cart: Cart,
  predicate: (item: CartItem) => boolean
): Cart => ({
  items: cart.items.filter((item) => !predicate(item)),
});

/** Return a new cart with quantities updated immutably. */
const updateQuantity = (
  cart: Cart,
  sku: string,
  quantity: number
): Cart => ({
  items: cart.items.map((item) =>
    item.sku === sku ? { ...item, quantity } : item
  ),
});

/* -------------------------------------------------------------------------- */
/* Pure functions with injected non-determinism                               */
/* -------------------------------------------------------------------------- */

/** Pure because `now` is passed in instead of calling Date.now(). */
const isExpired = (expiresAtMs: number, nowMs: number): boolean =>
  nowMs >= expiresAtMs;

/**
 * Pure Fisher-Yates shuffle.
 * The randomness comes from the injected `random` function.
 * If `random` is deterministic, the whole function is deterministic.
 */
const shuffle = <T>(
  items: readonly T[],
  random: () => number
): readonly T[] => {
  const result = [...items];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
};

/* -------------------------------------------------------------------------- */
/* Impure boundary / shell                                                    */
/* -------------------------------------------------------------------------- */

/**
 * This is intentionally impure: it reads the current time.
 * It delegates the actual decision to the pure `isExpired`.
 */
const isExpiredNow = (expiresAtMs: number): boolean =>
  isExpired(expiresAtMs, Date.now());

/* -------------------------------------------------------------------------- */
/* Demonstration and tests                                                    */
/* -------------------------------------------------------------------------- */

function main(): void {
  const emptyCart: Cart = { items: [] };

  const cart = addItem(
    addItem(emptyCart, { sku: "apple", priceCents: 100, quantity: 2 }),
    { sku: "banana", priceCents: 50, quantity: 3 }
  );

  // Original cart remains empty: no mutation.
  assert.deepStrictEqual(emptyCart, { items: [] });

  const total = cartTotalCents(cart, { percent: 10 }, 0.08);

  console.log("Cart:", JSON.stringify(cart, null, 2));
  console.log("Total cents:", total);

  // Assertions
  assert.equal(lineTotalCents({ sku: "x", priceCents: 100, quantity: 2 }), 200);
  assert.equal(subtotalCents(cart.items), 350);
  assert.equal(applyDiscountCents(350, { percent: 10 }), 315);
  assert.equal(applyTaxCents(315, 0.08), 340); // 315 * 1.08 = 340.2 -> 340
  assert.equal(total, 340);

  // Immutable update
  const updated = updateQuantity(cart, "apple", 5);
  assert.equal(
    cart.items.find((i) => i.sku === "apple")?.quantity,
    2,
    "original cart must not change"
  );
  assert.equal(
    updated.items.find((i) => i.sku === "apple")?.quantity,
    5,
    "updated cart has new quantity"
  );

  // Pure shuffle with deterministic random source
  const deterministicRandom = (() => {
    let seed = 42;
    return () => {
      seed = (seed * 1664525 + 1013904223) % 2 ** 32;
      return seed / 2 ** 32;
    };
  })();

  const shuffledOnce = shuffle(["a", "b", "c", "d"], deterministicRandom);
  // Calling again with a fresh generator state would differ;
  // this demonstrates deterministic behavior when state is controlled.
  console.log("Shuffled:", shuffledOnce);

  // Expiry is pure when time is injected
  assert.equal(isExpired(1000, 999), false);
  assert.equal(isExpired(1000, 1000), true);

  console.log("All assertions passed.");
}

main();
```

### How to run

Save the file as `pure.ts`, then:

