## Purity checklist

- No input mutation.
- No global variables.
- No console or network calls inside core functions.
- Deterministic output.
- New arrays and objects are created for transformed results.

## Pure Functions in TypeScript (interview-style)

A **pure function** is a function that satisfies two rules:

1. **Deterministic**: given the same inputs, it always returns the same output.
2. **No side effects**: it does not mutate external state, perform I/O, or depend on mutable globals.

### Why they matter
- **Referential transparency**: you can replace a call with its result without changing program behavior.
- **Testability**: no mocking of clocks, DBs, or random sources.
- **Memoization**: safe to cache results.
- **Parallelism**: no shared mutable state to race on.

### TypeScript-specific ways to *encourage* purity
- Mark inputs as `readonly` / `ReadonlyArray<T>` / `Readonly<T>` to prevent accidental mutation.
- Avoid `any`, global state, and impure APIs (`Date.now`, `Math.random`, `console.log`) in the core.
- Return new objects/arrays instead of mutating.
- Use `as const` and strict types to make data flow explicit.

---

## Core implementation: a tiny “pure function” toolkit

Below is a small, self-contained module that implements common pure-function building blocks.  
It favors immutability, explicit types, and zero mutation of inputs.

```ts
// pure.ts

/* ---------- Basic combinators ---------- */

/** Identity: returns its argument unchanged. */
export function identity<T>(value: T): T {
  return value;
}

/** Constant: turns a value into a nullary (no-arg) function. */
export function constant<T>(value: T): () => T {
  return () => value;
}

/** Compose two unary functions right-to-left: (f ∘ g)(x) = f(g(x)) */
export function compose<A, B, C>(
  f: (b: B) => C,
  g: (a: A) => B,
): (a: A) => C {
  return (a) => f(g(a));
}

/** Pipe two unary functions left-to-right: (f |> g)(x) = g(f(x)) */
export function pipe<A, B, C>(
  f: (a: A) => B,
  g: (b: B) => C,
): (a: A) => C {
  return (a) => g(f(a));
}

/* ---------- Currying ---------- */

/** Curry a binary function into two unary functions. */
export function curry2<A, B, C>(
  fn: (a: A, b: B) => C,
): (a: A) => (b: B) => C {
  return (a) => (b) => fn(a, b);
}

/* ---------- Memoization (pure cache) ---------- */

/**
 * Memoize a unary pure function.
 * - `key` lets callers define a stable cache key (important for objects).
 * - Inputs are never mutated; results are cached by key.
 */
export function memoizeUnary<A, B>(
  fn: (a: A) => B,
  key: (a: A) => string = (a) => JSON.stringify(a),
): (a: A) => B {
  const cache = new Map<string, B>();

  return (a: A): B => {
    const k = key(a);
    if (cache.has(k)) {
      return cache.get(k)!; // safe: we just checked has()
    }
    const result = fn(a);
    cache.set(k, result);
    return result;
  };
}

/* ---------- Pure collection helpers (no mutation) ---------- */

/** Pure map: returns a new array, never mutates input. */
export function pureMap<A, B>(
  items: readonly A[],
  fn: (item: A, index: number) => B,
): B[] {
  const out: B[] = [];
  for (let i = 0; i < items.length; i++) {
    out.push(fn(items[i], i));
  }
  return out;
}

/** Pure filter: returns a new array. */
export function pureFilter<A>(
  items: readonly A[],
  pred: (item: A, index: number) => boolean,
): A[] {
  const out: A[] = [];
  for (let i = 0; i < items.length; i++) {
    if (pred(items[i], i)) out.push(items[i]);
  }
  return out;
}

/** Pure reduce: folds without mutating accumulator externally. */
export function pureReduce<A, B>(
  items: readonly A[],
  reducer: (acc: B, item: A, index: number) => B,
  initial: B,
): B {
  let acc = initial;
  for (let i = 0; i < items.length; i++) {
    acc = reducer(acc, items[i], i);
  }
  return acc;
}

/* ---------- Immutability helper ---------- */

/** Deep-freeze an object graph to prevent accidental mutation. */
export function deepFreeze<T extends object>(obj: T): Readonly<T> {
  Object.freeze(obj);
  for (const key of Object.keys(obj)) {
    const val = (obj as Record<string, unknown>)[key];
    if (val && typeof val === "object") {
      deepFreeze(val as object);
    }
  }
  return obj;
}
```

