## Demo / sanity check

```ts
// demo.ts
import { compose, pipe, curry2, memoizeUnary, pureMap, pureFilter, pureReduce, deepFreeze } from "./pure";

// 1) Composition
const double = (x: number) => x * 2;
const inc = (x: number) => x + 1;

const doubleThenInc = pipe(double, inc); // left-to-right
const incThenDouble = compose(double, inc); // right-to-left

console.log(doubleThenInc(3)); // 7
console.log(incThenDouble(3)); // 8

// 2) Currying
const add = (a: number, b: number) => a + b;
const add5 = curry2(add)(5);
console.log(add5(10)); // 15

// 3) Memoization (pure function: factorial)
const factorial = (n: number): number =>
  n <= 1 ? 1 : n * factorial(n - 1);

const memoFactorial = memoizeUnary(factorial);
console.log(memoFactorial(5)); // 120
console.log(memoFactorial(5)); // 120 (cached)

// 4) Pure collection ops
const nums = [1, 2, 3, 4] as const;
const doubled = pureMap(nums, (x) => x * 2);
const evens = pureFilter(nums, (x) => x % 2 === 0);
const sum = pureReduce(nums, (acc, x) => acc + x, 0);

console.log(doubled); // [2, 4, 6, 8]
console.log(evens);   // [2, 4]
console.log(sum);     // 10
console.log(nums);    // unchanged: [1, 2, 3, 4]

// 5) Immutability guard
const data = deepFreeze({ user: { name: "Ada", scores: [10, 20] } });
// data.user.name = "X"; // ❌ TypeScript/JS runtime error in strict mode
```

### Interview talking points (quick recap)
- Pure functions enable **memoization**, **referential transparency**, and **safe concurrency**.
- In TS, enforce purity with `readonly`, new arrays/objects, and avoiding global/time/random APIs in core logic.
- Separate **pure core** (business logic) from **impure shell** (I/O, DB, time, logging) for maximum testability.

# Edge Cases When Using Pure Functions in TypeScript

A “pure” function must satisfy two rules: **(1) same inputs → same output**, and **(2) no observable side effects** (no mutation of inputs, no I/O, no global state). TypeScript’s type system does *not* enforce purity, so these pitfalls are runtime concerns. Below are the major edge cases, with bad/good code.

---

## 1. Mutating input objects/arrays (the #1 bug)

```ts
// ❌ Impure: mutates the input
function addItemBad(cart: string[], item: string): string[] {
  cart.push(item);          // side effect on caller's array
  return cart;
}

// ✅ Pure: returns a new array
function addItemGood(cart: readonly string[], item: string): string[] {
  return [...cart, item];
}
```

**Edge cases:**
- `readonly` is compile-time only; runtime mutation still possible.
- Nested objects: shallow copy (`{...obj}`) is not enough.

```ts
// ❌ Shallow copy still shares nested reference
function renameBad(user: { name: string; address: { city: string } }) {
  const u = { ...user };
  u.address.city = "NYC"; // mutates original!
  return u;
}

// ✅ Deep-ish copy for the part you change
function renameGood(user: { name: string; address: { city: string } }) {
  return { ...user, address: { ...user.address, city: "NYC" } };
}
```

---

## 2. Non-deterministic built-ins

```ts
// ❌ Impure
const now = () => Date.now();
const rnd = () => Math.random();
const id  = () => crypto.randomUUID();

// ✅ Pure: inject the value as an argument
const formatTimestamp = (ms: number) => new Date(ms).toISOString();
```

**Edge:** `Date` objects are mutable (`date.setHours(...)`). Treat them as inputs you must not mutate; clone when needed.

```ts
function addDays(date: Date, n: number): Date {
  const d = new Date(date); // clone
  d.setDate(d.getDate() + n);
  return d;
}
```

---

## 3. Stateful closures / captured mutable state

```ts
// ❌ Closure captures mutable counter
let counter = 0;
const inc = () => ++counter; // impure

// ✅ Pure: state is an argument
const incPure = (n: number) => n + 1;
```

**Edge:** Even a `const` binding to an object is mutable.

```ts
const cache = new Map<string, number>();
const getOrCompute = (k: string): number => {
  if (cache.has(k)) return cache.get(k)!;
  const v = k.length * 2;
  cache.set(k, v); // side effect → impure
  return v;
};
```

If you want memoization, either accept impurity explicitly or return a new cache.

---

## 4. Throwing exceptions

Throwing is an observable effect (control flow) and breaks referential transparency in many contexts.

```ts
// ❌ Throws on some inputs
function divide(a: number, b: number): number {
  if (b === 0) throw new Error("div by zero");
  return a / b;
}

// ✅ Pure: model failure in the return type
type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };
function divide(a: number, b: number): Result<number, "DIV_BY_ZERO"> {
  if (b === 0) return { ok: false, error: "DIV_BY_ZERO" };
  return { ok: true, value: a / b };
}
```

**Edge:** `NaN` propagation. `0/0` is `NaN` without throwing; `NaN` is not equal to itself.

```ts
function safeDivide(a: number, b: number): number | null {
  if (b === 0 || !Number.isFinite(a) || !Number.isFinite(b)) return null;
  const r = a / b;
  return Number.isFinite(r) ? r : null; // guards Infinity/NaN
}
```

---

## 5. Floating point & special numeric values

```ts
// ❌ -0 vs 0, NaN, Infinity
function normalize(x: number) { return x + 0; } // -0 stays -0? actually -0+0 = +0 in JS? careful

// ✅ Normalize explicitly
function normalizeNum(x: number): number {
  if (x === 0) return 0;          // collapses -0 to +0
  if (!Number.isFinite(x)) return x; // keep Infinity/-Infinity? decide policy
  return x;
}
```

**Edge:** `Object.is(-0, 0)` is `false` but `-0 === 0` is `true`. If purity requires bit-identical output, handle `-0`.

---

## 6. `this` binding and method calls

```ts
const obj = {
  x: 5,
  // ❌ depends on `this`
  getDouble() { return this.x * 2; },
};

// ✅ Pure free function
const getDouble = (x: number) => x * 2;
```

**Edge:** Passing methods as callbacks loses `this`:

```ts
const arr = [1,2,3];
// arr.map(obj.getDouble) // `this` is undefined in strict mode
arr.map((v) => obj.getDouble()); // or bind
```

---

## 7. Global / ambient state

```ts
// ❌ Reads environment
function apiUrl() { return process.env.API_URL ?? "http://localhost"; }

// ✅ Inject config
function apiUrl(env: { API_URL?: string }) {
  return env.API_URL ?? "http://localhost";
}
```

**Edge:** `Intl` formatting depends on runtime locale/timezone.

```ts
// ❌ Locale-dependent output
const fmt = (d: Date) => d.toLocaleString();

// ✅ Pin locale/timezone
const fmt = (d: Date) => d.toLocaleString("en-US", { timeZone: "UTC" });
```

---

## 8. RegExp with `g`/`y` flags (stateful `lastIndex`)

```ts
const re = /a/g;
// ❌ Mutates re.lastIndex
function countA(s: string) {
  let n = 0, m;
  while ((m = re.exec(s))) n++;
  return n;
}

// ✅ Create a fresh regex inside, or reset lastIndex
function countAPure(s: string): number {
  const re = /a/g; // fresh instance per call
  let n = 0;
  while (re.exec(s)) n++;
  return n;
}
```

---

## 9. Sorting / in-place array methods

```ts
// ❌ Mutates input
function sortedBad(xs: number[]) { return xs.sort((a,b)=>a-b); }

// ✅ Copy first
function sortedGood(xs: readonly number[]): number[] {
  return [...xs].sort((a, b) => a - b);
}
```

**Edge:** `Array.prototype.sort` comparator must be consistent; inconsistent comparators produce engine-dependent (impure-ish) results.

---

## 10. Generators / iterators with hidden state

```ts
// ❌ Generator holds state across .next() calls
function* counter() { let i = 0; while (true) yield i++; }

// ✅ Pure function returning array (or accept seed)
const range = (n: number): number[] => Array.from({ length: n }, (_, i) => i);
```

---

## 11. Object identity & referential transparency

Pure functions returning new objects break `===` equality even when values are equal.

```ts
const a = makeUser("a");
const b = makeUser("a");
a === b; // false — even though "pure"

// ✅ If identity matters, document it; use structural equality helpers
function eqUser(x: {id:string}, y:{id:string}) { return x.id === y.id; }
```

**Edge:** Memoization based on reference equality won’t dedupe structurally equal inputs unless you use a deep-key cache.

---

## 12. `JSON` serialization edge cases

```ts
// ❌ Throws on BigInt, drops undefined, reorders keys
function clone<T>(x: T): T { return JSON.parse(JSON.stringify(x)); }

// ✅ Use structuredClone (still has limits: functions, DOM nodes)
function cloneSafe<T>(x: T): T { return structuredClone(x); }
```

**Edge:** `structuredClone` throws on functions and certain objects; not a universal deep clone.

---

## 13. Map / Set mutation & key equality

```ts
// Map uses SameValueZero: NaN === NaN for keys, -0 === 0
const m = new Map<number, string>();
m.set(NaN, "x");
m.get(NaN); // "x" — surprising but deterministic

// ✅ Normalize keys before using as Map keys
const key = (n: number) => (n === 0 ? 0 : n); // collapse -0
```

---

## 14. WeakRef / finalizers (nondeterministic GC)

```ts
// ❌ Behavior depends on GC timing
const wr = new WeakRef(obj);
function get() { return wr.deref(); } // may be undefined nondeterministically
```

Avoid in pure logic; treat as impure by definition.

---

## 15. Async purity

`async` functions returning `Promise` are pure only if the awaited operations are pure.

```ts
// ❌ Network I/O
async function fetchUser(id: string) {
  const r = await fetch(`/users/${id}`);
  return r.json();
}

// ✅ Pure async: only transforms already-available data
async function parseUser(json: string): Promise<User> {
  return JSON.parse(json) as User; // JSON.parse is deterministic
}
```

**Edge:** Even `Promise.resolve().then(...)` scheduling can be considered a side effect in strict purity; usually we treat “no I/O + deterministic value” as pure enough.

---

## 16. Type-level vs runtime: `readonly` lies at boundaries

```ts
type User = { readonly name: string };
function greet(u: User) { /* u.name = "x" is a TS error */ }

const u = { name: "a" } as User;
// runtime: u is still mutable; another reference can mutate it
```

**Edge:** Defensive copy at API boundaries if you need true purity.

```ts
function greetPure(u: Readonly<{ name: string }>) {
  const name = u.name; // read only
  return `hi ${name}`;
}
```

---

## 17. Default parameters with mutable defaults

```ts
// ❌ Shared mutable default across calls
function push(x: number, arr = sharedArr) { arr.push(x); return arr; }

// ✅ Create default inside
function pushPure(x: number, arr?: number[]) {
  const a = arr ?? [];
  return [...a, x];
}
```

---

## 18. Currying capturing intermediate state

```ts
// ❌ Partial application captures mutable arg
const makeAdder = (x: number) => (y: number) => x + y; // actually pure if x immutable primitive

// Danger: if x is an object and you mutate it later
const cfg = { factor: 2 };
const scale = (n: number) => n * cfg.factor; // impure via closure over mutable cfg
```

---

## 19. Sorting stability & comparator consistency

```ts
// ❌ Inconsistent comparator → engine-dependent order
arr.sort((a, b) => (a.id < b.id ? -1 : 1)); // returns 0 never, unstable-ish

// ✅ Return 0 for equal
arr.sort((a, b) => a.id === b.id ? 0 : a.id < b.id ? -1 : 1);
```

---

## 20. `Symbol` / `BigInt` edge cases

```ts
// BigInt division throws on 0n (not NaN)
function divBigInt(a: bigint, b: bigint): bigint | null {
  if (b === 0n) return null;
  return a / b;
}

// Symbol: no implicit coercion; String(sym) is deterministic
const s = Symbol("x");
String(s); // "Symbol(x)" — deterministic for same description
```

---

## 21. Prototype / `__proto__` pollution

```ts
// ❌ Merging untrusted input can pollute Object.prototype
function merge(target: any, src: any) {
  for (const k in src) target[k] = src[k]; // dangerous
}

// ✅ Use null-proto object or explicit allowlist
function mergeSafe<T extends object>(a: T, b: Partial<T>): T {
  return { ...a, ...b };
}
```

---

## 22. Console / logging (side effect)

```ts
// ❌
function compute(x: number) { console.log(x); return x * 2; }

// ✅ Keep pure; log at call site
function computePure(x: number) { return x * 2; }
```

---

## 23. Memoization correctness

```ts
// ❌ Cache keyed by reference; mutable input breaks memo
const cache = new Map<object, number>();
function size(obj: { items: number[] }) {
  if (cache.has(obj)) return cache.get(obj)!;
  const v = obj.items.length;
  cache.set(obj, v);
  return v;
}
// If caller mutates obj.items, cache is stale.

// ✅ Either accept impurity, or key by a stable serialized key
```

---

## 24. `Object.freeze` doesn’t make deep-pure

```ts
const o = Object.freeze({ nested: { x: 1 } });
// o.nested.x = 2 still works! freeze is shallow.
```

Use deep freeze or treat as readonly convention.

---

## Summary checklist for pure TS functions

| Concern | Mitigation |
|---|---|
| Input mutation | Return new structures; use `readonly` params |
| Output identity | Document; use structural equality |
| Non-determinism | Inject `Date`, `random`, env as args |
| Exceptions | Return `Result`/`null`/`undefined` |
| `NaN`/`-0`/`Infinity` | Normalize or validate |
| `this` | Use arrow/free functions |
| Global state | Inject config |
| Locale/timezone | Pin in `Intl` |
| Stateful RegExp | Fresh instance or reset `lastIndex` |
| In-place sort/reverse | Copy first |
| Deep clone | `structuredClone`, know its limits |
| Async | Only transform; no I/O inside |
| Memoization | Key by value, not reference, if inputs mutable |

---

### A “pure-ish” utility template

```ts
type Result<T, E = string> =
  | { ok: true; value: T }
  | { ok: false; error: E };

export function transformUser(
  input: Readonly<{ name: string; age: number }>,
  nowMs: number, // injected clock
): Result<{ name: string; age: number; adult: boolean }, "INVALID_AGE"> {
  if (!Number.isFinite(input.age) || input.age < 0) {
    return { ok: false, error: "INVALID_AGE" };
  }
  return {
    ok: true,
    value: {
      name: input.name.trim(),
      age: input.age,
      adult: input.age >= 18,
    },
  };
}
```

This keeps determinism, avoids mutation, avoids exceptions, and makes dependencies explicit — the practical essence of purity in TypeScript.

Here is a complete, runnable TypeScript implementation of a **seeded, deterministic pseudo-random number generator (PRNG)**. It uses **xoshiro128\*\*** for good statistical quality and exposes convenient helpers for floats, integers, booleans, array shuffling, sampling, and Gaussian numbers.

> Note: this is **not cryptographically secure**. For passwords, tokens, or security-sensitive values, use Node’s `crypto` module (`crypto.randomInt`, `crypto.randomUUID`, etc.).

## `random.ts`

```ts
/**
 * A seeded pseudo-random number generator for TypeScript/JavaScript.
 *
 * Algorithm: xoshiro128** (good quality, small state, fast).
 * Seed can be a number or a string. The same seed always produces the
 * same sequence.
 */
export class Random {
  private readonly s: Uint32Array;

  constructor(seed?: number | string) {
    const numericSeed =
      typeof seed === "string"
        ? Random.hashString(seed)
        : (seed ?? Random.defaultSeed());

    const splitmix = Random.splitmix32(numericSeed);

    this.s = new Uint32Array(4);
    for (let i = 0; i < 4; i++) {
      this.s[i] = splitmix();
    }

    // xoshiro must not have an all-zero state.
    if (this.s[0] === 0 && this.s[1] === 0 && this.s[2] === 0 && this.s[3] === 0) {
      this.s[0] = 1;
    }
  }

  /** Returns an unsigned 32-bit integer in [0, 2^32). */
  nextUint32(): number {
    const result = (Random.rotl(Math.imul(this.s[1], 5) >>> 0, 7) * 9) >>> 0;

    const t = (this.s[1] << 9) >>> 0;

    this.s[2] ^= this.s[0];
    this.s[3] ^= this.s[1];
    this.s[1] ^= this.s[2];
    this.s[0] ^= this.s[3];
    this.s[2] ^= t;
    this.s[3] = Random.rotl(this.s[3], 11);

    return result;
  }

  /** Returns a float in [0, 1). */
  next(): number {
    return this.nextUint32() / 0x100000000; // divide by 2^32
  }

  /** Returns a float in [min, max). */
  nextFloat(min = 0, max = 1): number {
    if (!Number.isFinite(min) || !Number.isFinite(max)) {
      throw new RangeError("Bounds must be finite numbers");
    }
    if (max <= min) {
      throw new RangeError("max must be greater than min");
    }
    return min + this.next() * (max - min);
  }

  /**
   * Returns an integer in [min, maxExclusive).
   * Both bounds must be integers.
   */
  nextInt(min: number, maxExclusive: number): number {
    if (!Number.isInteger(min) || !Number.isInteger(maxExclusive)) {
      throw new RangeError("Bounds must be integers");
    }
    if (maxExclusive <= min) {
      throw new RangeError("maxExclusive must be greater than min");
    }

    const span = maxExclusive - min;
    return min + Math.floor(this.next() * span);
  }

  /** Returns true with the given probability (default 0.5). */
  nextBoolean(probability = 0.5): boolean {
    if (probability < 0 || probability > 1) {
      throw new RangeError("probability must be in [0, 1]");
    }
    return this.next() < probability;
  }

  /** Picks a uniformly random element from a non-empty array. */
  choice<T>(items: readonly T[]): T {
    if (items.length === 0) {
      throw new Error("Cannot choose from an empty array");
    }
    return items[this.nextInt(0, items.length)]!;
  }

  /** Returns a shuffled copy of the input array. */
  shuffle<T>(items: readonly T[]): T[] {
    const copy = [...items];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = this.nextInt(0, i + 1);
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }

  /** Returns `count` distinct randomly chosen elements. */
  sample<T>(items: readonly T[], count: number): T[] {
    if (!Number.isInteger(count) || count < 0 || count > items.length) {
      throw new RangeError("Invalid sample count");
    }

    const copy = [...items];
    const result: T[] = [];

    for (let i = 0; i < count; i++) {
      const j = this.nextInt(i, copy.length);
      [copy[i], copy[j]] = [copy[j], copy[i]];
      result.push(copy[i]);
    }

    return result;
  }

  /** Standard normal distribution using the Box-Muller transform. */
  nextGaussian(mean = 0, standardDeviation = 1): number {
    if (standardDeviation < 0) {
      throw new RangeError("standardDeviation must be non-negative");
    }

    let u = 0;
    let v = 0;
    while (u === 0) u = this.next();
    while (v === 0) v = this.next();

    const magnitude = standardDeviation * Math.sqrt(-2 * Math.log(u));
    const z = magnitude * Math.cos(2 * Math.PI * v);
    return mean + z;
  }

  /** Exponential distribution with the given rate (lambda). */
  nextExponential(rate = 1): number {
    if (rate <= 0) {
      throw new RangeError("rate must be positive");
    }
    return -Math.log(1 - this.next()) / rate;
  }

  // ---------- seeding helpers ----------

  private static rotl(x: number, k: number): number {
    return ((x << k) | (x >>> (32 - k))) >>> 0;
  }

  private static splitmix32(seed: number): () => number {
    let z = seed >>> 0;

    return () => {
      z = (z + 0x9e3779b9) >>> 0;

      let t = z;
      t = Math.imul(t ^ (t >>> 16), 0x85ebca6b) >>> 0;
      t = Math.imul(t ^ (t >>> 13), 0xc2b2ae35) >>> 0;
      return (t ^ (t >>> 16)) >>> 0;
    };
  }

  private static hashString(value: string): number {
    // FNV-1a 32-bit
    let hash = 0x811c9dc5 >>> 0;
    for (let i = 0; i < value.length; i++) {
      hash ^= value.charCodeAt(i);
      hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    return hash;
  }

  private static defaultSeed(): number {
    // Good enough for non-cryptographic default seeding.
    return (Date.now() ^ (Math.random() * 0x100000000)) >>> 0;
  }
}

// ---------- runnable demo ----------

function main(): void {
  const rng = new Random(42);

  console.log("floats:", rng.next(), rng.next(), rng.next());
  console.log("int [0,10):", rng.nextInt(0, 10));
  console.log("float [5,10):", rng.nextFloat(5, 10));
  console.log("boolean:", rng.nextBoolean(0.25));
  console.log("gaussian:", rng.nextGaussian(100, 15));

  const items = ["apple", "banana", "cherry", "date"];
  console.log("choice:", rng.choice(items));
  console.log("shuffle:", rng.shuffle(items));
  console.log("sample:", rng.sample(items, 2));

  // Determinism check
  const a = new Random("hello");
  const b = new Random("hello");
  console.log("same seed same first value:", a.next() === b.next());
}

if (require.main === module) {
  main();
}
```

