## `src/reader.ts`

```ts
import * as ts from "typescript";
import * as fs from "node:fs";
import * as path from "node:path";

export type Language = "typescript" | "javascript";

export interface SecretFinding {
  file: string;
  line: number;
  kind: string;
}

export interface DeclarationInfo {
  name: string;
  kind: string;
  exported: boolean;
  location: { line: number; column: number };
  snippet: string;
}

export interface ModuleInfo {
  file: string;
  language: Language;
  imports: string[];
  exports: string[];
  declarations: DeclarationInfo[];
  findings: SecretFinding[];
  skipped?: string;
}

const SOURCE_EXTENSIONS = new Set([".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"]);
const MAX_FILE_BYTES = 1_000_000; // guard against huge / generated files

const SECRET_PATTERNS: Array<{ name: string; regex: RegExp }> = [
  { name: "AWS Access Key", regex: /AKIA[0-9A-Z]{16}/g },
  { name: "Private Key Block", regex: /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/g },
  {
    name: "Hard-coded secret assignment",
    regex: /(api[_-]?key|secret|token|password)\s*[:=]\s*["'][^"']{12,}["']/gi,
  },
];

function isSourceFile(filePath: string): boolean {
  const ext = path.extname(filePath).toLowerCase();
  if (!SOURCE_EXTENSIONS.has(ext)) return false;
  if (filePath.endsWith(".d.ts")) return false;
  return true;
}

function collectFiles(root: string): string[] {
  const out: string[] = [];
  const stack: string[] = [root];

  while (stack.length) {
    const dir = stack.pop()!;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        // Never walk into dependency or hidden folders.
        if (entry.name === "node_modules" || entry.name.startsWith(".")) continue;
        stack.push(full);
      } else if (entry.isFile() && isSourceFile(full)) {
        out.push(full);
      }
    }
  }
  return out;
}

function hasModifier(node: ts.Node, kind: ts.SyntaxKind): boolean {
  const modifiers = ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined;
  return !!modifiers?.some((m) => m.kind === kind);
}

function declarationName(node: ts.Node, sf: ts.SourceFile): string {
  if (
    ts.isFunctionDeclaration(node) ||
    ts.isClassDeclaration(node) ||
    ts.isInterfaceDeclaration(node) ||
    ts.isEnumDeclaration(node) ||
    ts.isTypeAliasDeclaration(node)
  ) {
    return node.name?.text ?? "<anonymous>";
  }

  if (ts.isVariableStatement(node)) {
    const decl = node.declarationList.declarations[0];
    if (decl && ts.isIdentifier(decl.name)) return decl.name.text;
    return "<variable>";
  }

  return "<unknown>";
}

function declarationKind(node: ts.Node): string {
  if (ts.isFunctionDeclaration(node)) return "function";
  if (ts.isClassDeclaration(node)) return "class";
  if (ts.isInterfaceDeclaration(node)) return "interface";
  if (ts.isTypeAliasDeclaration(node)) return "type";
  if (ts.isEnumDeclaration(node)) return "enum";
  if (ts.isVariableStatement(node)) return "variable";
  return "declaration";
}

function snippetOf(node: ts.Node, sf: ts.SourceFile): string {
  const text = node.getText(sf).replace(/\s+/g, " ").trim();
  return text.length > 180 ? text.slice(0, 177) + "..." : text;
}

function scanForSecrets(text: string, relativeFile: string): SecretFinding[] {
  const findings: SecretFinding[] = [];
  const lines = text.split(/\r?\n/);

  lines.forEach((line, index) => {
    for (const pattern of SECRET_PATTERNS) {
      pattern.regex.lastIndex = 0;
      if (pattern.regex.test(line)) {
        findings.push({
          file: relativeFile,
          line: index + 1,
          kind: pattern.name,
        });
      }
    }
  });

  return findings;
}

function handleStatement(
  node: ts.Node,
  sf: ts.SourceFile,
  imports: Set<string>,
  exports: Set<string>,
  declarations: DeclarationInfo[],
): void {
  // Imports
  if (ts.isImportDeclaration(node)) {
    if (node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      imports.add(node.moduleSpecifier.text);
    }
    return;
  }

  // Re-exports / named exports
  if (ts.isExportDeclaration(node)) {
    if (node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      exports.add(`* from ${node.moduleSpecifier.text}`);
    } else if (node.exportClause && ts.isNamedExports(node.exportClause)) {
      for (const el of node.exportClause.elements) exports.add(el.name.text);
    }
    return;
  }

  if (ts.isExportAssignment(node)) {
    exports.add("default");
    return;
  }

  // Namespaces / modules: recurse one level for top-level declarations.
  if (ts.isModuleDeclaration(node) && node.body && ts.isModuleBlock(node.body)) {
    for (const stmt of node.body.statements) {
      handleStatement(stmt, sf, imports, exports, declarations);
    }
    return;
  }

  // Ordinary declarations
  if (
    ts.isFunctionDeclaration(node) ||
    ts.isClassDeclaration(node) ||
    ts.isInterfaceDeclaration(node) ||
    ts.isTypeAliasDeclaration(node) ||
    ts.isEnumDeclaration(node) ||
    ts.isVariableStatement(node)
  ) {
    const name = declarationName(node, sf);
    const exported = hasModifier(node, ts.SyntaxKind.ExportKeyword);

    if (exported) exports.add(name);

    const { line, character } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
    declarations.push({
      name,
      kind: declarationKind(node),
      exported,
      location: { line: line + 1, column: character + 1 },
      snippet: snippetOf(node, sf),
    });
  }
}

function parseModule(filePath: string, root: string): ModuleInfo {
  const relativeFile = path.relative(root, filePath);
  const text = fs.readFileSync(filePath, "utf8");

  // Size guard before doing any heavy parsing.
  if (Buffer.byteLength(text, "utf8") > MAX_FILE_BYTES) {
    return {
      file: relativeFile,
      language: "javascript",
      imports: [],
      exports: [],
      declarations: [],
      findings: [],
      skipped: "file too large",
    };
  }

  const ext = path.extname(filePath).toLowerCase();
  const language: Language =
    ext === ".ts" || ext === ".tsx" ? "typescript" : "javascript";

  const scriptKind =
    language === "typescript"
      ? ext === ".tsx"
        ? ts.ScriptKind.TSX
        : ts.ScriptKind.TS
      : ext === ".jsx"
        ? ts.ScriptKind.JSX
        : ts.ScriptKind.JS;

  const sf = ts.createSourceFile(filePath, text, ts.ScriptTarget.Latest, true, scriptKind);

  const imports = new Set<string>();
  const exports = new Set<string>();
  const declarations: DeclarationInfo[] = [];

  sf.forEachChild((node) =>
    handleStatement(node, sf, imports, exports, declarations),
  );

  return {
    file: relativeFile,
    language,
    imports: [...imports].sort(),
    exports: [...exports].sort(),
    declarations,
    findings: scanForSecrets(text, relativeFile),
  };
}

export function readCodebase(root: string): ModuleInfo[] {
  const absRoot = path.resolve(root);

  let stat: fs.Stats;
  try {
    stat = fs.statSync(absRoot);
  } catch {
    throw new Error(`Path does not exist: ${absRoot}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`Not a directory: ${absRoot}`);
  }

  return collectFiles(absRoot)
    .map((file) => parseModule(file, absRoot))
    .sort((a, b) => a.file.localeCompare(b.file));
}
```

