  const fields = parseFields(fieldStr);
  if (fields === null) return null;

  if (message.trim() === '' && fieldStr.trim() === '') {
    // line with no message and no fields is probably malformed
    return null;
  }

  return {
    timestamp,
    level,
    message: message.trim(),
    fields,
  };
}
