```ts
// parseLog.ts
export interface LogEntry {
  timestamp: string;
  level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
  message: string;
  fields: Record<string, string>;
}

type Level = LogEntry['level'];

const OUTER_RE = /^\[([^\]]+)\]\s+(DEBUG|INFO|WARN|ERROR):\s*(.*)$/;
const TS_RE    = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
const FIELD_RE = /^\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*([^,]+?)\s*$/;

function isValidTimestamp(ts: string): boolean {
  if (!TS_RE.test(ts)) return false;
  const [datePart, timePart] = ts.split(' ');
  const [y, m, d] = datePart.split('-').map(Number);
  const [hh, mm, ss] = timePart.split(':').map(Number);
  if (m < 1 || m > 12) return false;
  if (d < 1 || d > 31) return false;
  if (hh > 23 || mm > 59 || ss > 59) return false;
  const dt = new Date(`${datePart}T${timePart}`);
  return !isNaN(dt.getTime());
}

function parseFields(input: string): Record<string, string> | null {
  const out: Record<string, string> = {};
  if (input.trim() === '') return out;

  for (const part of input.split(',')) {
    const m = part.match(FIELD_RE);
    if (!m) return null;
    const key = m[1];
    const value = m[2].trim();
    if (value === '') return null;
    out[key] = value;
  }
  return out;
}

export function parseLogLine(line: string): LogEntry | null {
  const outer = line.match(OUTER_RE);
  if (!outer) return null;

  const timestamp = outer[1];
  const level = outer[2] as Level;
  const rest = outer[3];

  if (!isValidTimestamp(timestamp)) return null;

  let message = rest.trim();
  let fields: Record<string, string> = {};

  const lastOpen = rest.lastIndexOf('(');
  if (lastOpen !== -1 && rest.endsWith(')') && lastOpen < rest.length - 2) {
    const candidateMsg   = rest.slice(0, lastOpen).trim();
    const candidateFieldStr = rest.slice(lastOpen + 1, -1);

    // Only commit to "fields mode" if the parenthetical actually parses
    // as fields. This keeps "hello (world)" as a plain message.
    const parsed = parseFields(candidateFieldStr);
    const looksLikeFields =
      candidateFieldStr.trim() === '' || candidateFieldStr.includes('=');

    if (parsed !== null && looksLikeFields) {
      message = candidateMsg;
      fields = parsed;
    }
  }

  // Reject lines that are effectively empty
  if (message === '' && Object.keys(fields).length === 0) return null;

  return { timestamp, level, message, fields };
}
```

### Test harness

```ts
const cases: [string, unknown][] = [
  ['[2024-01-15 14:32:01] ERROR: Connection timeout (user=alice, retries=3)',
   { timestamp: '2024-01-15 14:32:01', level: 'ERROR', message: 'Connection timeout', fields: { user: 'alice', retries: '3' } }],
  ['[2024-02-02 00:00:00] INFO: Server started',
   { timestamp: '2024-02-02 00:00:00', level: 'INFO', message: 'Server started', fields: {} }],
  ['[2024-01-15 14:32:01] DEBUG: hello (world)',
   { timestamp: '2024-01-15 14:32:01', level: 'DEBUG', message: 'hello (world)', fields: {} }],
  ['[2024-13-40 25:61:61] WARN: x', null],
  ['[2024-01-15 14:32:01] FOO: x', null],
  ['not a log line', null],
  ['[2024-01-15 14:32:01] INFO: bad (x=)', null],
];

for (const [input, expected] of cases) {
  const got = parseLogLine(input as string);
  console.log(JSON.stringify(got) === JSON.stringify(expected) ? 'PASS' : 'FAIL', input, '=>', got);
}
```

### Key takeaways
- **Anchor** the regex (`^` … `$`) so partial matches don't sneak through.
- **Validate** timestamp beyond digits — ranges + `Date` parse.
- **Don't trust** the trailing parenthetical blindly: only commit to field parsing when its contents look like fields; otherwise keep the whole remainder as the message.
- **Trim** values and keys consistently; return `null` on any malformed part rather than partially succeeding.

## Regular expressions in TypeScript

A regular expression in TypeScript is just the standard JavaScript regex engine with TypeScript types on top. You usually write patterns as **regex literals** or create them with the **`RegExp` constructor**.

```ts
// Literal (preferred when pattern is static)
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Constructor (useful when pattern is dynamic)
const word = "error";
const re = new RegExp(`\\b${escapeRegExp(word)}\\b`, "gi");
```

Important TypeScript types:

```ts
const m: RegExpExecArray | null = /(\d{4})-(\d{2})-(\d{2})/.exec("2025-08-10");
const matches: RegExpMatchArray | null = "a1 b2".match(/\d/g);
```

### Core syntax

| Piece | Meaning | Example |
|---|---|---|
| `.` | Any char except newline (`s` flag includes newline) | `/a.c/` |
| `^`, `$` | Start / end of input or line (`m` flag) | `/^start/` |
| `*`, `+`, `?` | 0+, 1+, 0/1 | `/a+/` |
| `{n,m}` | Repetition range | `/a{2,4}/` |
| `[...]` | Character class | `/[a-z]/i` |
| `(...)` | Capturing group | `/(\d+)/` |
| `(?:...)` | Non-capturing group | `/(?:ab)+/` |
| `(?<name>...)` | Named group | `/(?<year>\d{4})/` |
| `a|b` | Alternation | `/cat|dog/` |
| `\d`, `\w`, `\s` | Digit / word / whitespace | `/\w+/` |
| `(?=...)`, `(?!...)` | Lookahead | `/foo(?=bar)/` |
| `(?<=...)`, `(?<!...)` | Lookbehind | `/(?<=\$)\d+/` |

Useful flags:

- `g`: global search, updates `lastIndex`
- `i`: case-insensitive
- `m`: multiline `^` / `$`
- `s`: dot matches newline
- `u`: Unicode-aware
- `y`: sticky matching from `lastIndex`
- `d`: record group start/end indices
- `v`: newer Unicode set notation

### Common methods

```ts
const re = /\d+/g;

re.test("abc123");        // true
re.exec("abc123");        // ["123", index: 3, ...]
"abc123".match(re);       // ["123"]
"abc123".search(re);      // 3
"a1b2".replace(/\d/g, "X"); // "aXbX"
[..."a1b2".matchAll(/\d/g)]; // iterable of RegExpExecArray
"a,b;c".split(/[;,]/);    // ["a", "b", "c"]
```

### Important pitfalls

Always remember that **`RegExp.prototype.lastIndex` is mutable** for global/sticky regexes.

```ts
const re = /a/g;
re.test("a");
re.lastIndex; // 1
re.test("a"); // false, because search starts at index 1
```

Safe helper:

```ts
function isMatch(re: RegExp, input: string): boolean {
  const flags = re.flags.includes("g") ? re.flags : re.flags + "g";
  return new RegExp(re.source, flags).test(input);
}
```

Always escape dynamic text:

```ts
function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
```

Avoid catastrophic backtracking: prefer possessive/atomic-like patterns, non-greedy quantifiers when appropriate, and anchors.

