## Mini regex engine in TypeScript

The following is a compact educational regex engine supporting literals, `.`, character classes, groups, alternation, quantifiers (`*`, `+`, `?`, `{n,m}`, lazy variants), and anchors.

```ts
type CharRange = { from: number; to: number };

type Node =
  | { kind: "literal"; value: string }
  | { kind: "dot" }
  | { kind: "class"; ranges: CharRange[]; negated: boolean }
  | { kind: "concat"; children: Node[] }
  | { kind: "alt"; options: Node[] }
  | { kind: "quant"; child: Node; min: number; max: number | null; greedy: boolean }
  | { kind: "group"; child: Node; index: number; name?: string }
  | { kind: "anchor"; at: "start" | "end" };

interface Flags {
  ignoreCase: boolean;
  multiline: boolean;
  dotAll: boolean;
}

interface Context {
  input: string;
  flags: Flags;
  captures: (string | undefined)[];
  named: Record<string, string | undefined>;
  end: number;
}

function parseFlags(flags: string): Flags {
  return {
    ignoreCase: flags.includes("i"),
    multiline: flags.includes("m"),
    dotAll: flags.includes("s"),
  };
}

class Parser {
  private i = 0;
  captureCount = 0;

  constructor(private readonly pattern: string) {}

  parse(): Node {
    const node = this.alternative();
    if (this.i !== this.pattern.length) {
      throw new Error(`Unexpected trailing pattern at index ${this.i}`);
    }
    return node;
  }

  private get len(): number {
    return this.pattern.length;
  }

  private peek(offset = 0): string {
    return this.pattern[this.i + offset] ?? "";
  }

  private readCodePoint(): number {
    const cp = this.pattern.codePointAt(this.i)!;
    this.i += cp > 0xffff ? 2 : 1;
    return cp;
  }

  private alternative(): Node {
    const sequences = [this.sequence()];
    while (this.peek() === "|") {
      this.i++;
      sequences.push(this.sequence());
    }
    return sequences.length === 1
      ? sequences[0]
      : { kind: "alt", options: sequences };
  }

  private sequence(): Node {
    const children: Node[] = [];
    while (
      !this.atEnd() &&
      this.peek() !== ")" &&
      this.peek() !== "|"
    ) {
      children.push(this.quantified());
    }
    if (children.length === 0) {
      return { kind: "concat", children: [] };
    }
    if (children.length === 1) {
      return children[0];
    }
    return { kind: "concat", children };
  }

  private atEnd(): boolean {
    return this.i >= this.len;
  }

  private quantified(): Node {
    const atom = this.atom();
    const q = this.peek();

    if (q === "*" || q === "+" || q === "?") {
      this.i++;
      let greedy = true;
      if (this.peek() === "?") {
        greedy = false;
        this.i++;
      }

      const min = q === "+" ? 1 : 0;
      const max = q === "?" ? 1 : null;

      return { kind: "quant", child: atom, min, max, greedy };
    }

    if (q === "{") {
      this.i++;
      const min = this.readNumber();
      let max: number | null = min;

      if (this.peek() === ",") {
        this.i++;
        if (/\d/.test(this.peek())) {
          max = this.readNumber();
        } else {
          max = null;
        }
      }

      if (this.peek() !== "}") {
        throw new Error("Expected '}' in quantifier");
      }
      this.i++;

      let greedy = true;
      if (this.peek() === "?") {
        greedy = false;
        this.i++;
      }

      return { kind: "quant", child: atom, min, max, greedy };
    }

    return atom;
  }

  private readNumber(): number {
    const start = this.i;
    while (/\d/.test(this.peek())) this.i++;
    if (start === this.i) {
      throw new Error("Expected number in quantifier");
    }
    return Number(this.pattern.slice(start, this.i));
  }

  private atom(): Node {
    const c = this.peek();

    if (c === "(") {
      this.i++;
      let capturing = true;
      let name: string | undefined;

      if (this.peek() === "?") {
        this.i++;
        const type = this.peek();
        if (type === ":") {
          capturing = false;
          this.i++;
        } else if (type === "<") {
          this.i++;
          const start = this.i;
          while (this.i < this.len && this.peek() !== ">") this.i++;
          if (this.peek() !== ">") {
            throw new Error("Expected '>' in named group");
          }
          name = this.pattern.slice(start, this.i);
          this.i++;
          capturing = true;
        } else {
          throw new Error("Unsupported group type");
        }
      }

      const child = this.alternative();
      if (this.peek() !== ")") {
        throw new Error("Expected ')'");
      }
      this.i++;

      const index = capturing ? ++this.captureCount : -1;
      return { kind: "group", child, index, name };
    }

    if (c === "[") {
      return this.parseClass();
    }

    if (c === ".") {
      this.i++;
      return { kind: "dot" };
    }

    if (c === "^") {
      this.i++;
      return { kind: "anchor", at: "start" };
    }

    if (c === "$") {
      this.i++;
      return { kind: "anchor", at: "end" };
    }

    if (c === "\\") {
      return this.parseEscapeAtom();
    }

    this.i++;
    return { kind: "literal", value: c };
  }

  private parseEscapeAtom(): Node {
    this.i++; // backslash
    const c = this.pattern[this.i++];

    switch (c) {
      case "d":
        return { kind: "class", ranges: [{ from: 48, to: 57 }], negated: false };
      case "D":
        return { kind: "class", ranges: [{ from: 48, to: 57 }], negated: true };
      case "w":
        return {
          kind: "class",
          ranges: [
            { from: 48, to: 57 },
            { from: 65, to: 90 },
            { from: 95, to: 95 },
            { from: 97, to: 122 },
          ],
          negated: false,
        };
      case "W":
        return {
          kind: "class",
          ranges: [
            { from: 48, to: 57 },
            { from: 65, to: 90 },
            { from: 95, to: 95 },
            { from: 97, to: 122 },
          ],
          negated: true,
        };
      case "s":
        return {
          kind: "class",
          ranges: [
            { from: 9, to: 13 },
            { from: 32, to: 32 },
          ],
          negated: false,
        };
      case "S":
        return {
          kind: "class",
          ranges: [
            { from: 9, to: 13 },
            { from: 32, to: 32 },
          ],
          negated: true,
        };
      case "n":
        return { kind: "literal", value: "\n" };
      case "t":
        return { kind: "literal", value: "\t" };
      case "r":
        return { kind: "literal", value: "\r" };
      default:
        return { kind: "literal", value: c };
    }
  }

  private parseClass(): Node {
    this.i++; // [
    let negated = false;

    if (this.peek() === "^") {
      negated = true;
      this.i++;
    }

    const ranges: CharRange[] = [];
    const addRange = (from: number, to: number) => {
      ranges.push({ from: Math.min(from, to), to: Math.max(from, to) });
    };

    while (this.i < this.len && this.peek() !== "]") {
      if (this.peek() === "\\") {
        this.i++;
        const c = this.pattern[this.i++];

        switch (c) {
          case "d":
            addRange(48, 57);
            continue;
          case "w":
            addRange(48, 57);
            addRange(65, 90);
            addRange(95, 95);
            addRange(97, 122);
            continue;
          case "s":
            addRange(9, 13);
            addRange(32, 32);
            continue;
          case "n":
            addRange(10, 10);
            continue;
          case "t":
            addRange(9, 9);
            continue;
          case "r":
            addRange(13, 13);
            continue;
          default:
            addRange(c.codePointAt(0)!, c.codePointAt(0)!);
            continue;
        }
      }

      const start = this.readCodePoint();
      if (
        this.peek() === "-" &&
        this.i + 1 < this.len &&
        this.pattern[this.i + 1] !== "]"
      ) {
        this.i++; // -
        const end = this.readCodePoint();
        addRange(start, end);
      } else {
        addRange(start, start);
      }
    }

    if (this.peek() !== "]") {
      throw new Error("Expected ']' in character class");
    }
    this.i++;

    return { kind: "class", ranges, negated };
  }
}

function matchNode(
  node: Node,
  i: number,
  ctx: Context,
  cont: (pos: number) => boolean
): boolean {
  switch (node.kind) {
    case "literal": {
      if (i + node.value.length > ctx.input.length) return false;

      if (ctx.flags.ignoreCase) {
        const actual = ctx.input.slice(i, i + node.value.length);
        if (actual.toLowerCase() !== node.value.toLowerCase()) return false;
      } else if (!ctx.input.startsWith(node.value, i)) {
        return false;
      }

      return cont(i + node.value.length);
    }

    case "dot": {
      if (i >= ctx.input.length) return false;
      const ch = ctx.input[i];
      if (ch === "\n" && !ctx.flags.dotAll) return false;
      return cont(i + 1);
    }

    case "class": {
      if (i >= ctx.input.length) return false;

      const cp = ctx.input.codePointAt(i)!;
      const len = cp > 0xffff ? 2 : 1;

      let inRange = node.ranges.some((r) => cp >= r.from && cp <= r.to);

      if (ctx.flags.ignoreCase) {
        const other =
          cp >= 65 && cp <= 90
            ? cp + 32
            : cp >= 97 && cp <= 122
              ? cp - 32
              : cp;

        if (!inRange) {
          inRange = node.ranges.some((r) => other >= r.from && other <= r.to);
        }
      }

      const matched = node.negated ? !inRange : inRange;
      if (!matched) return false;

      return cont(i + len);
    }

    case "anchor": {
      if (node.at === "start") {
        if (ctx.flags.multiline) {
          if (i !== 0 && ctx.input[i - 1] !== "\n") return false;
        } else if (i !== 0) {
          return false;
        }
        return cont(i);
      }

      // end anchor
      if (ctx.flags.multiline) {
        if (i !== ctx.input.length && ctx.input[i] !== "\n") return false;
      } else if (i !== ctx.input.length) {
        return false;
      }
      return cont(i);
    }

    case "group": {
      const start = i;
      const oldCapture = node.index > 0 ? ctx.captures[node.index] : undefined;

      return matchNode(node.child, i, ctx, (pos) => {
        if (node.index > 0) {
          ctx.captures[node.index] = ctx.input.slice(start, pos);
          if (node.name) ctx.named[node.name] = ctx.captures[node.index];
        }

        const ok = cont(pos);
        if (!ok && node.index > 0) {
          ctx.captures[node.index] = oldCapture;
        }
        return ok;
      });
    }

    case "concat": {
      const go = (k: number, pos: number): boolean => {
        if (k === node.children.length) return cont(pos);
        return matchNode(node.children[k], pos, ctx, (nextPos) =>
          go(k + 1, nextPos)
        );
      };
      return go(0, i);
    }

    case "alt": {
      return node.options.some((option) => matchNode(option, i, ctx, cont));
    }

    case "quant": {
      const maxCount =
        node.max === null
          ? ctx.input.length - i + 1
          : node.max;

      const effectiveMax = Math.max(node.min, Math.min(maxCount, 10000));
      const counts: number[] = [];

      if (node.greedy) {
        for (let c = effectiveMax; c >= node.min; c--) counts.push(c);
      } else {
        for (let c = node.min; c <= effectiveMax; c++) counts.push(c);
      }

      const tryCount = (count: number): boolean => {
        const repeat = (k: number, pos: number): boolean => {
          if (k === count) return cont(pos);
          return matchNode(node.child, pos, ctx, (nextPos) =>
            repeat(k + 1, nextPos)
          );
        };
        return repeat(0, i);
      };

      return counts.some(tryCount);
    }
  }
}

interface MiniMatch {
  index: number;
  full: string;
  groups: (string | undefined)[];
  namedGroups: Record<string, string | undefined>;
}

class MiniRegExp {
  private readonly ast: Node;
  private readonly captureCount: number;
  private readonly flags: Flags;

  constructor(pattern: string, flags = "") {
    const parser = new Parser(pattern);
    this.ast = parser.parse();
    this.captureCount = parser.captureCount;
    this.flags = parseFlags(flags);
  }

  exec(input: string, fromIndex = 0): MiniMatch | null {
    for (let start = fromIndex; start <= input.length; start++) {
      const ctx: Context = {
        input,
        flags: this.flags,
        captures: new Array(this.captureCount + 1).fill(undefined),
        named: {},
        end: start,
      };

      const ok = matchNode(this.ast, start, ctx, (pos) => {
        ctx.end = pos;
        return true;
      });

      if (ok) {
        ctx.captures[0] = input.slice(start, ctx.end);
        return {
          index: start,
          full: ctx.captures[0] ?? "",
          groups: ctx.captures.slice(1),
          namedGroups: ctx.named,
        };
      }

      if (start > fromIndex && this.flags.sticky) break;
    }

    return null;
  }

  test(input: string): boolean {
    return this.exec(input, 0) !== null;
  }
}

// Example usage:
const mini = new MiniRegExp("(?<name>\\w+) (?<year>\\d{4})", "i");
console.log(mini.exec("Ada 2025"));
// { index: 0, full: "Ada 2025", groups: ["Ada", "2025"], namedGroups: { name: "Ada", year: "2025" } }
```

### How the engine works

1. **Parser** turns the pattern string into an AST.
2. `matchNode` uses recursive backtracking:
   - literals, dots, and classes consume one position;
   - `concat` tries children left-to-right;
   - `alt` tries each alternative;
   - `quant` tries repetition counts from greedy or lazy order;
   - groups save slices for captures.
3. `exec` tries the AST at successive input positions, exactly like a basic regex search.

This is intentionally small. Production engines add bytecode compilation, Unicode property escapes, lookarounds, backreferences, atomic groups, and much stronger performance optimizations.

When using regular expressions in TypeScript/JavaScript, most bugs are not syntax errors—they are state, Unicode, typing, and backtracking edge cases. The examples below focus on patterns that fail in production.

## 1. Escape dynamic text before building a `RegExp`

If user input contains regex metacharacters, `new RegExp(input)` can match the wrong thing or throw.

```ts
function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsLiteral(text: string, needle: string): boolean {
  if (needle.length === 0) return false;
  const re = new RegExp(escapeRegExp(needle), "g");
  return re.test(text);
}
```

## 2. Reuse of `/g` regexes causes `lastIndex` bugs

A global regex is stateful. Reusing the same instance across calls or in loops can skip matches.

```ts
// Dangerous: shared state
const shared = /foo/g;

function bad(text: string) {
  return shared.test(text); // lastIndex persists between calls
}

// Safer: clone or use matchAll
function countOccurrences(text: string, needle: string): number {
  const re = new RegExp(escapeRegExp(needle), "g");
  return [...text.matchAll(re)].length;
}
```

## 3. `matchAll` requires `g` or `y`

`String.prototype.matchAll` throws if the regex is not global or sticky.

```ts
function allMatches(re: RegExp, text: string): RegExpMatchArray[] {
  const flags = re.flags.includes("g") ? re.flags : `${re.flags}g`;
  const cloned = new RegExp(re.source, flags);
  return [...text.matchAll(cloned)];
}
```

## 4. Zero-width matches can create infinite loops

Patterns such as `/\b/g`, `/^/gm`, or `/(?=a)/g` can match empty strings. Manual `exec` loops must advance `lastIndex`.

```ts
function wordBoundaryPositions(text: string): number[] {
  const re = /\b/g;
  const positions: number[] = [];
  let match: RegExpExecArray | null;

  while ((match = re.exec(text)) !== null) {
    positions.push(match.index);

    // Prevent an infinite loop on an empty match.
    if (match[0].length === 0) {
      re.lastIndex++;
    }
  }

  return positions;
}
```

## 5. Catastrophic backtracking / ReDoS

Nested quantifiers can make matching exponential on certain inputs.

```ts
// Dangerous on input like "aaaaaaaaaaaaaaaaab"
const dangerous = /^(a+)+$/;

// Safer: flatten the pattern
const safer = /^a+$/;

function safeValidate(input: string): boolean {
  if (input.length > 10_000) return false;
  return safer.test(input);
}
```

JavaScript has no native regex timeout. For untrusted patterns or very large input, use a simpler grammar, length limits, a vetted library such as `safe-regex`, or run matching in a worker that can be terminated.

## 6. Unicode and surrogate pairs

Without the `u` flag, `.` matches UTF-16 code units, not full Unicode code points. `\w` is still ASCII-only even with `u`.

```ts
const text = "Café 😀 123";

// Misses accented letters and emoji
console.log(text.match(/\w+/g)); // ["Caf", "123"]

// Treat code points correctly
console.log(text.match(/\p{L}+|\p{N}+/gu)); // ["Café", "😀", "123"]

// Emoji matching
console.log(text.match(/\p{Extended_Pictographic}/gu)); // ["😀"]

// Without u, this matches a surrogate half
console.log("😀".match(/./)?.[0].length); // 1
console.log("😀".match(/./u)?.[0].length); // 2? code point length in JS UTF-16: emoji length is 2
```

For manual character iteration, use `for...of`, which iterates code points:

```ts
for (const char of "a😀b") {
  console.log(char); // "a", "😀", "b"
}
```

## 7. Replacement strings interpret `$` patterns

`String.prototype.replace` treats `$&`, `$$`, `$1`, etc. as special replacement syntax. If the replacement comes from variables or user input, use a replacer function.

```ts
function renderTemplate(template: string, userName: string): string {
  // Dangerous if userName contains "$&" or "$1"
  // return template.replace(/{{name}}/g, userName);

  // Safe: returned string is not interpreted for $ patterns
  return template.replace(/{{name}}/g, () => userName);
}
```

## 8. Optional capture groups are not guaranteed at runtime

TypeScript types capture groups as `string`, but optional groups may be `undefined` at runtime.

```ts
const match = input.match(/^(?<area>\d{3})-(?<line>\d{4})$/);

if (!match) {
  throw new Error("No match");
}

// TS sees string | undefined because groups itself is optional
const area = match.groups?.area;
const line = match.groups?.line;

if (!area || !line) {
  throw new Error("Expected both capture groups");
}

// Helper for required groups
function requiredGroup(match: RegExpMatchArray, name: string): string {
  const value = match.groups?.[name];
  if (value === undefined) {
    throw new Error(`Missing required capture group: ${name}`);
  }
  return value;
}
```

Also note that entries of `RegExpMatchArray` may be `undefined` for non-participating groups at runtime even when TypeScript says `string`.

## 9. Invalid patterns and duplicate flags throw at runtime

`new RegExp` can throw `SyntaxError`. Flags can also be duplicated or unsupported.

```ts
function compileRegex(pattern: string, flags = ""): RegExp | null {
  if (pattern.length === 0) return null;
  if (new Set(flags).size !== flags.length) return null; // duplicate flags

  try {
    return new RegExp(pattern, flags);
  } catch (error) {
    if (error instanceof SyntaxError) return null;
    throw error;
  }
}
```

TypeScript will not validate regex syntax at compile time.

## 10. Anchors and line endings

With the `m` flag, `^` and `$` apply to line boundaries, but `\r\n` can leave `\r` attached to the previous line.

```ts
const text = "ERROR: something\r\nINFO: done";

// Normalize line endings first
const normalized = text.replace(/\r\n?/g, "\n");

const errors = normalized
  .split("\n")
  .filter((line) => /^ERROR:/i.test(line));
```

Alternatively, avoid `m` and process `text.split(/\r?\n/)` directly.

## 11. Overlapping matches require manual scanning

Regex engines consume matched text, so they do not find overlapping matches by default.

```ts
function overlappingMatches(pattern: RegExp, text: string): RegExpExecArray[] {
  const flags = pattern.flags.includes("y")
    ? pattern.flags
    : `${pattern.flags}y`;

  const re = new RegExp(pattern.source, flags);
  const result: RegExpExecArray[] = [];

  for (let i = 0; i < text.length; i++) {
    re.lastIndex = i;
    const match = re.exec(text);
    if (match) {
      result.push(match);
    }
  }

  return result;
}

// Find "aa" in "aaaa": positions 0, 1, 2
console.log(overlappingMatches(/aa/y, "aaaa").map((m) => m.index));
```

## 12. Sticky flag means “must match exactly here”

The `y` flag requires the match to start exactly at `lastIndex`. It does not skip ahead.

```ts
const re = /bar/y;

re.lastIndex = 4;
console.log(re.exec("foo bar baz")?.[0]); // "bar"

re.lastIndex = 5;
console.log(re.exec("foo bar baz")); // null
```

This is useful for lexers and tokenizers, but it is a common source of unexpected `null` results.

## 13. TypeScript typing gaps for newer regex features

Features such as the `d` flag and `indices` require sufficiently modern TypeScript lib settings.

```ts
const match = "2025-01-02".match(
  /(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})/d
);

if (match?.indices?.groups?.year) {
  const [start, end] = match.indices.groups.year;
  console.log(start, end);
}
```

TypeScript may type capture values as `string` even when runtime values are `undefined`. For production code, validate with small helper functions:

```ts
function getCapture(match: RegExpMatchArray, index: number): string {
  const value = match[index];
  if (value === undefined) {
    throw new Error(`Missing capture at index ${index}`);
  }
  return value;
}
```

## Practical checklist

- Escape all dynamic user input.
- Clone regexes or reset `lastIndex` before reuse.
- Use `matchAll` instead of manual `exec` where possible.
- Guard zero-width loops with `lastIndex++`.
- Avoid nested quantifiers and validate input length.
- Use the `u` flag for Unicode-aware matching.
- Use replacer functions for dynamic replacements.
- Validate capture groups before use.
- Wrap `new RegExp` in `try/catch`.
- Normalize `\r\n` before line-based anchor logic.
- Use sticky scanning for overlapping matches.

