Save it as `return-values.ts`:

```ts
// return-values.ts
// Run with: npx tsx return-values.ts

// 1. Basic explicit and inferred return types.
function add(a: number, b: number): number {
  return a + b;
}

function greet(name: string) {
  // Inferred return type: string
  return `Hello, ${name}`;
}

// 2. No meaningful return value: void.
function logMessage(message: string): void {
  console.log(message);
}

// 3. Never returns normally: never.
function fail(message: string): never {
  throw new Error(message);
}

// 4. Returning multiple values with a labeled tuple.
function minMax(values: readonly number[]): [min: number, max: number] | null {
  if (values.length === 0) return null;

  let min = values[0];
  let max = values[0];
  for (const value of values) {
    if (value < min) min = value;
    if (value > max) max = value;
  }
  return [min, max];
}

// 5. A Result type for success/failure without throwing.
type Result<T, E = Error> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

function ok<T>(value: T): Result<T> {
  return { ok: true, value };
}

function err<E = Error>(error: E): Result<never, E> {
  return { ok: false, error };
}

function parsePositiveInt(input: string): Result<number> {
  const n = Number(input);
  if (!Number.isInteger(n) || n <= 0) {
    return err(new Error(`Invalid positive integer: ${input}`));
  }
  return ok(n);
}

// 6. Function overloads.
function stringify(value: string): string;
function stringify(value: number): string;
function stringify(value: boolean): string;
function stringify(value: unknown): string {
  return String(value);
}

// 7. Async functions always return a Promise.
async function loadConfig(path: string): Promise<Result<{ port: number }>> {
  if (path.trim() === "") {
    return err(new Error("Config path must not be empty"));
  }

  // Simulate async work.
  await new Promise((resolve) => setTimeout(resolve, 10));
  return ok({ port: 3000 });
}

// 8. Generators: Generator<Yielded, Returned, Next>.
function* countdown(n: number): Generator<number, "done", unknown> {
  for (let i = n; i > 0; i--) {
    yield i;
  }
  return "done";
}

// 9. Type guard with a boolean return and type predicate.
function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

// 10. Exhaustive handling with never.
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    default: {
      const exhaustive: never = shape;
      return exhaustive;
    }
  }
}

async function main(): Promise<void> {
  console.log("add:", add(2, 3));
  console.log("greet:", greet("TypeScript"));

  logMessage("This function returns void.");

  const range = minMax([3, 1, 4, 1, 5]);
  if (range !== null) {
    const [min, max] = range;
    console.log("min/max:", min, max);
  }

  const parsed = parsePositiveInt("42");
  if (parsed.ok) {
    console.log("parsed value:", parsed.value);
  } else {
    console.error("parse error:", parsed.error.message);
  }

  console.log("stringify:", stringify(true));
  console.log("config:", await loadConfig("app.json"));

  console.log("countdown:");
  const generator = countdown(3);
  for (const value of generator) {
    console.log("  ", value);
  }

  const unknownValue: unknown = "hello";
  if (isNonEmptyString(unknownValue)) {
    console.log("non-empty string length:", unknownValue.length);
  }

  console.log("circle area:", area({ kind: "circle", radius: 2 }));

  try {
    fail("Something went wrong");
  } catch (error) {
    console.log("caught:", (error as Error).message);
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
