# Sliding Window Technique in TypeScript

The sliding window pattern maintains a contiguous range `[left, right]` over a sequence and slides it efficiently (usually O(n)) instead of re-scanning. Two flavors:

- **Fixed-size window**: window length is constant `k`.
- **Variable-size window**: window grows/shrinks based on a condition.

Below is a complete, runnable program (`sliding-window.ts`) with both flavors, plus a classic "minimum window substring" example.

```ts
// sliding-window.ts
// Run with: npx ts-node sliding-window.ts   (or compile with tsc then node)

/* ============================================================
 * 1. Fixed-size window: maximum sum of any subarray of size k
 * ============================================================ */
function maxSumSubarray(nums: number[], k: number): number {
  if (nums.length < k || k <= 0) return 0;

  let windowSum = 0;
  for (let i = 0; i < k; i++) windowSum += nums[i];

  let best = windowSum;
  // Slide: add incoming element, drop outgoing element
  for (let right = k; right < nums.length; right++) {
    const left = right - k;
    windowSum += nums[right] - nums[left];
    if (windowSum > best) best = windowSum;
  }
  return best;
}

/* ============================================================
 * 2. Variable-size window: longest substring without repeating chars
 *    (expand right, shrink left while invalid)
 * ============================================================ */
function lengthOfLongestSubstring(s: string): number {
  const lastSeen = new Map<string, number>(); // char -> last index
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    // If seen inside current window, jump left past it
    if (lastSeen.has(ch) && lastSeen.get(ch)! >= left) {
      left = lastSeen.get(ch)! + 1;
    }
    lastSeen.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

/* ============================================================
 * 3. Variable-size window: smallest subarray with sum >= target
 * ============================================================ */
function minSubarrayLen(target: number, nums: number[]): number {
  let left = 0;
  let sum = 0;
  let best = Infinity;

  for (let right = 0; right < nums.length; right++) {
    sum += nums[right];
    while (sum >= target) {
      best = Math.min(best, right - left + 1);
      sum -= nums[left++];
    }
  }
  return best === Infinity ? 0 : best;
}

/* ============================================================
 * 4. Classic: Minimum Window Substring (LeetCode 76)
 *    Smallest window in `s` containing all chars of `t`
 * ============================================================ */
function minWindow(s: string, t: string): string {
  if (t.length > s.length) return "";

  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);

  let have = 0; // how many required chars are satisfied
  const required = need.size;
  const window = new Map<string, number>();
  let left = 0;
  let bestLen = Infinity;
  let bestStart = 0;

  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    window.set(c, (window.get(c) ?? 0) + 1);
    if (need.has(c) && window.get(c) === need.get(c)) have++;

    while (have === required) {
      const len = right - left + 1;
      if (len < bestLen) {
        bestLen = len;
        bestStart = left;
      }
      const lc = s[left];
      window.set(lc, window.get(lc)! - 1);
      if (need.has(lc) && window.get(lc)! < need.get(lc)!) have--;
      left++;
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}

/* ============================================================
 * Demo
 * ============================================================ */
function main(): void {
  console.log("maxSumSubarray([2,1,5,1,3,2], 3) =", maxSumSubarray([2, 1, 5, 1, 3, 2], 3)); // 9
  console.log("lengthOfLongestSubstring('abcabcbb') =", lengthOfLongestSubstring("abcabcbb")); // 3
  console.log("minSubarrayLen(7, [2,3,1,2,4,3]) =", minSubarrayLen(7, [2, 3, 1, 2, 4, 3])); // 2
  console.log("minWindow('ADOBECODEBANC', 'ABC') =", minWindow("ADOBECODEBANC", "ABC")); // "BANC"
}

main();
```

## Key ideas

| Concept | Fixed-size | Variable-size |
|---|---|---|
| Pointers | `right` increments; `left = right - k + 1` | `right` always increments; `left` moves only when condition violated/satisfied |
| Update cost | O(1) per step by reusing previous sum | Each element added once and removed at most once ⇒ O(n) total |
| When to shrink | Never (size fixed) | `while (invalid)` or `while (valid && can shrink)` |
| State | Single accumulator (sum) | Frequency map + counters (e.g. `have`/`required`) |

## Invariants to keep in mind

1. **Every element is processed a constant number of times** — that's what guarantees O(n). Avoid nested loops that re-scan the whole window.
2. **Shrink condition** must be expressed in terms of window *state*, not index arithmetic, otherwise you'll get off-by-one bugs.
3. **Map hygiene**: when decrementing counts, delete zero entries (or compare carefully) so `required`/`have` logic stays correct. In the code above I keep entries and compare against `need`, which is safe.
4. **Empty/edge cases**: `k > n`, empty `t`, target larger than total sum — all handled explicitly.

## Complexity

- Time: **O(n)** for all four examples (each pointer moves at most n steps).
- Space: O(min(n, alphabet size)) for the maps; O(1) for the numeric ones.

You can drop this file into any TS project and run `npx ts-node sliding-window.ts`. If you'd like, I can also add a generic reusable `SlidingWindow<T>` class or property-based tests.

## Sliding window in TypeScript

### Idea

You maintain a **contiguous subarray/substring** defined by two pointers (usually `left` and `right`).  
- **Expand** by moving `right` (add element).  
- **Contract** by moving `left` (remove element) when an invariant is violated (e.g., too many distinct chars, sum too large).  

Each pointer moves only forward, so total work is **O(n)** even though there are nested loops.

Two common variants:
- **Fixed size** `k`: window length stays `k`; slide by adding new right element and removing old left.
- **Variable size**: grow until invalid, then shrink until valid again; track best answer.

---

### Syntax patterns you’ll see

```ts
// Fixed size
let sum = 0;
for (let i = 0; i < k; i++) sum += arr[i];
// slide
for (let i = k; i < arr.length; i++) {
  sum += arr[i] - arr[i - k];
}

// Variable size
let left = 0;
for (let right = 0; right < s.length; right++) {
  // add s[right]
  while (invalid()) {
    // remove s[left++]
  }
  // update answer with [left, right]
}
```

Counts are usually stored in `Map<K, number>` or a plain object/record.

---

### Example 1 — Fixed size: max sum of subarray of length `k`

```ts
function maxSumSubarray(arr: number[], k: number): number {
  if (arr.length < k) return 0;

  let sum = 0;
  for (let i = 0; i < k; i++) sum += arr[i];
  let best = sum;

  for (let i = k; i < arr.length; i++) {
    sum += arr[i] - arr[i - k]; // slide window
    best = Math.max(best, sum);
  }
  return best;
}
```

---

### Example 2 — Variable size: longest substring without repeating chars

```ts
function lengthOfLongestSubstring(s: string): number {
  const last = new Map<string, number>(); // char -> last index
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    const prev = last.get(ch);
    if (prev !== undefined && prev >= left) {
      left = prev + 1; // shrink past duplicate
    }
    last.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

---

### Example 3 — Variable size: minimum window substring

```ts
function minWindow(s: string, t: string): string {
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);

  const window = new Map<string, number>();
  let have = 0;
  const required = need.size;
  let left = 0;
  let bestStart = 0;
  let bestLen = Infinity;

  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    window.set(c, (window.get(c) ?? 0) + 1);

    if (need.has(c) && window.get(c) === need.get(c)) have++;

    while (have === required) {
      if (right - left + 1 < bestLen) {
        bestLen = right - left + 1;
        bestStart = left;
      }
      const lc = s[left];
      window.set(lc, window.get(lc)! - 1);
      if (need.has(lc) && window.get(lc)! < need.get(lc)!) have--;
      left++;
    }
  }

  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}
```

---

### Typical use cases

- **Subarray/substring optimization**: max/min sum with length constraint, longest/shortest substring satisfying property.
- **Frequency constraints**: at most K distinct characters, anagram detection, “contains all chars of T”.
- **Two-pointer on sorted data**: pair sums, removing duplicates, merging intervals.
- **Rate/limit style problems**: longest segment where condition holds (e.g., max consecutive ones after flipping at most K zeros).

### Practical tips

- Decide whether the window is **inclusive** `[left, right]` (common in substrings) or **half-open** `[left, right)`.
- Keep an invariant (e.g., “window has no duplicates”, “sum ≤ limit”) and shrink until it’s restored.
- Use `Map` for arbitrary keys; for lowercase letters only, a `number[]` of size 26 is faster.
- Watch for off-by-one when updating answer: usually after restoring validity, or right after adding `right` for “at most” problems.

```ts
// Typical mistake: shrink the window by only one step when a duplicate is found.
function longestUniqueSubstringBad(s: string): number {
  const chars = new Set<string>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    if (chars.has(s[right])) {
      // BUG: removing only s[left] once is not enough.
      // The previous occurrence of s[right] may be several positions
      // to the right of `left`.
      chars.delete(s[left]);
      left++;
    }

    chars.add(s[right]);
    best = Math.max(best, right - left + 1);
  }

  return best;
}
```

```ts
// Corrected version: shrink until the duplicate is actually removed.
function longestUniqueSubstring(s: string): number {
  const chars = new Set<string>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    // Shrink from the left until s[right] is no longer in the window.
    while (chars.has(s[right])) {
      chars.delete(s[left]);
      left++;
    }

    chars.add(s[right]);
    best = Math.max(best, right - left + 1);
  }

  return best;
}
```

### What was wrong

The buggy version assumes that when `s[right]` is already in the current window, moving `left` forward **once** will remove that duplicate. That is only true when the duplicate is exactly at `left`.

Consider `s = "abba"`:

- `right = 0`, char `a`: window becomes `a`
- `right = 1`, char `b`: window becomes `ab`
- `right = 2`, char `b`: duplicate found  
  buggy code deletes `s[0] = a`, so `left = 1`, set becomes `{b}`  
  then adds `b`, set remains `{b}`  
  window is treated as indices `1..2`, i.e. `"bb"`, but the set no longer records that there are two `b`s
- `right = 3`, char `a`: `a` is not in set, so it gets added  
  window is treated as indices `1..3`, i.e. `"bba"`, but `"bba"` contains a repeated `b`

The invariant “the set contains exactly the characters in `s[left..right]`” is broken. Once that invariant breaks, later length calculations can be too large.

### Why the corrected version works

The corrected version uses `while (chars.has(s[right]))` instead of `if`. It keeps shrinking the window from the left until the duplicate of `s[right]` is removed. This preserves the invariant:

> After the `while` loop, `chars` contains exactly the unique characters in `s[left..right - 1]`, and `s[right]` is not among them.

Then adding `s[right]` makes the window `s[left..right]` valid.

This is still `O(n)` overall because each character is added to the set at most once and removed at most once, even though the `while` loop can run multiple times in one outer iteration.

### A common alternative

For this particular problem, you can also track the last seen index of each character:

```ts
function longestUniqueSubstringWithMap(s: string): number {
  const lastSeen = new Map<string, number>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const char = s[right];
    const previousIndex = lastSeen.get(char);

    if (previousIndex !== undefined && previousIndex >= left) {
      left = previousIndex + 1;
    }

    lastSeen.set(char, right);
    best = Math.max(best, right - left + 1);
  }

  return best;
}
```

This avoids explicitly shrinking the window and is also `O(n)`, but the key idea is the same: when a duplicate appears, move `left` far enough to exclude the previous occurrence.

Below are common pitfalls when implementing sliding windows in TypeScript, with bad vs. good code for each.

## 1. Off-by-one in fixed-size window add/remove

**Pitfall:** removing the wrong element or updating the answer one step too early/late.

```ts
// BAD
function maxSumFixedBad(nums: number[], k: number): number {
  let sum = 0;
  let best = -Infinity;

  for (let right = 0; right < nums.length; right++) {
    sum += nums[right]!;

    // BUG: removes one position too late and updates before window is full
    if (right > k) sum -= nums[right - k - 1]!;
    if (right >= k - 1) best = Math.max(best, sum);
  }
  return best;
}

// GOOD
function maxSumFixedGood(nums: number[], k: number): number {
  if (k <= 0 || k > nums.length) return 0; // edge case

  let sum = 0;
  let best = -Infinity;

  for (let right = 0; right < nums.length; right++) {
    sum += nums[right]!;

    // Remove the element leaving the window: index right - k
    if (right >= k) sum -= nums[right - k]!;

    // Window [right-k+1, right] is full only when right >= k-1
    if (right >= k - 1) best = Math.max(best, sum);
  }
  return best;
}
```

---

## 2. Variable-size window: shrinking at the wrong time or with `if` instead of `while`

**Pitfall:** a single `if` only fixes one violation; invalid windows can persist. Also updating the answer before restoring validity.

```ts
// BAD: only shrinks once; answer captured while window may still be invalid
function longestWithoutRepeatBad(s: string): number {
  const seen = new Set<string>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right]!;
    if (seen.has(ch)) {
      seen.delete(s[left]!);
      left++; // only one step
    }
    seen.add(ch);
    best = Math.max(best, right - left + 1); // may count invalid window
  }
  return best;
}

// GOOD: shrink until invariant restored, then measure
function longestWithoutRepeatGood(s: string): number {
  const seen = new Set<string>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right]!;

    while (seen.has(ch)) {
      seen.delete(s[left]!);
      left++;
    }

    seen.add(ch);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

---

## 3. Frequency maps: forgetting zero counts or decrementing below zero

**Pitfall:** leaving zero-count keys makes “distinct count” wrong; decrementing before checking can create negative counts.

```ts
// BAD
function minWindowWithAllCharsBad(s: string, t: string): string {
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);

  let have = 0;
  const window = new Map<string, number>();

  let left = 0;
  let best = { start: 0, len: Infinity };

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    window.set(c, (window.get(c) ?? 0) + 1);

    // BUG: counts zero entries as satisfying need
    if ((window.get(c) ?? 0) <= (need.get(c) ?? 0)) have++;

    while (have === need.size) {
      if (right - left + 1 < best.len) {
        best = { start: left, len: right - left + 1 };
      }

      const lc = s[left]!;
      // BUG: never removes zero entries; have may stay stale
      window.set(lc, (window.get(lc) ?? 0) - 1);
      if ((window.get(lc) ?? 0) < (need.get(lc) ?? 0)) have--;
      left++;
    }
  }

  return best.len === Infinity ? "" : s.slice(best.start, best.start + best.len);
}

// GOOD
function minWindowWithAllCharsGood(s: string, t: string): string {
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);

  const required = need.size;
  let formed = 0;
  const window = new Map<string, number>();

  let left = 0;
  let bestStart = 0;
  let bestLen = Infinity;

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    window.set(c, (window.get(c) ?? 0) + 1);

    if (need.has(c) && window.get(c) === need.get(c)) formed++;

    while (formed === required) {
      if (right - left + 1 < bestLen) {
        bestStart = left;
        bestLen = right - left + 1;
      }

      const lc = s[left]!;
      window.set(lc, (window.get(lc) ?? 0) - 1);

      // Clean up zero so has() / size reflect reality
      if (window.get(lc) === 0) window.delete(lc);

      if (need.has(lc) && (window.get(lc) ?? 0) < (need.get(lc) ?? 0)) {
        formed--;
      }
      left++;
    }
  }

  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}
```

