## 4. Using `Set` when counts matter

**Pitfall:** a `Set` cannot represent “at most K duplicates” or “remove one occurrence but keep another.”

```ts
// BAD for "longest substring with at most 2 distinct-like count rules"
function atMostKDistinctBad(s: string, k: number): number {
  const set = new Set<string>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    set.add(s[right]!);
    while (set.size > k) {
      set.delete(s[left]!); // BUG: deletes all occurrences conceptually
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

// GOOD: use counts
function atMostKDistinctGood(s: string, k: number): number {
  const counts = new Map<string, number>();
  let distinct = 0;
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    const prev = counts.get(c) ?? 0;
    if (prev === 0) distinct++;
    counts.set(c, prev + 1);

    while (distinct > k) {
      const lc = s[left]!;
      const next = (counts.get(lc) ?? 0) - 1;
      counts.set(lc, next);
      if (next === 0) distinct--;
      left++;
    }

    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

---

## 5. O(n²) hidden work inside the window

**Pitfall:** calling `Array.prototype.includes`, `indexOf`, or `slice` inside the loop destroys linear time.

```ts
// BAD: O(n^2)
function noRepeatSubstringBad(s: string): number {
  let best = 0;
  for (let right = 0; right < s.length; right++) {
    for (let left = 0; left <= right; left++) {
      const window = s.slice(left, right + 1);
      if (new Set(window).size === window.length) {
        best = Math.max(best, window.length);
      }
    }
  }
  return best;
}

// GOOD: maintain state incrementally
function noRepeatSubstringGood(s: string): number {
  const lastSeen = new Map<string, number>();
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    const prevIndex = lastSeen.get(c);
    if (prevIndex !== undefined && prevIndex >= left) {
      left = prevIndex + 1;
    }
    lastSeen.set(c, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

---

## 6. Not handling empty arrays, `k <= 0`, or `k > n`

**Pitfall:** division, negative lengths, or reading `nums[right - k]` out of range.

```ts
// BAD
function avgFixedBad(nums: number[], k: number): number[] {
  const out: number[] = [];
  let sum = 0;

  for (let right = 0; right < nums.length; right++) {
    sum += nums[right]!;
    if (right >= k) sum -= nums[right - k]!; // when k=0, right-k === right, wrong
    out.push(sum / k); // division by zero when k=0
  }
  return out;
}

// GOOD
function avgFixedGood(nums: number[], k: number): number[] {
  if (k <= 0 || k > nums.length) return [];

  const out: number[] = [];
  let sum = 0;

  for (let right = 0; right < nums.length; right++) {
    sum += nums[right]!;

    if (right >= k) sum -= nums[right - k]!;

    if (right >= k - 1) {
      out.push(sum / k);
    }
  }
  return out;
}
```

