## 7. TypeScript indexing and `noUncheckedIndexedAccess`

**Pitfall:** with strict indexing settings, `nums[right]` is `number | undefined`. Non-null assertions hide real bugs; missing checks crash at runtime.

```ts
// tsconfig: "noUncheckedIndexedAccess": true

// BAD: assumes presence
function sumWindowBad(nums: number[], k: number): number {
  let sum = 0;
  for (let i = 0; i < k; i++) {
    sum += nums[i]!; // assertion may hide undefined
  }
  return sum;
}

// GOOD: validate or use a bounds-safe helper
function sumWindowGood(nums: number[], k: number): number {
  if (k < 0 || k > nums.length) {
    throw new RangeError("k out of bounds");
  }

  let sum = 0;
  for (let i = 0; i < k; i++) {
    const value = nums[i];
    if (value === undefined) throw new Error("unexpected undefined");
    sum += value;
  }
  return sum;
}
```

Also prefer `Map.get` checks:

```ts
const count = counts.get(char);
if (count === undefined) {
  // not present
} else {
  // safe to use count
}
```

