## 8. Mutating shared state between calls

**Pitfall:** reusing a `Map`, `Set`, or array across invocations causes cross-test contamination.

```ts
// BAD: module-level mutable state
const globalSeen = new Set<string>();

function hasUniqueBad(s: string): boolean {
  globalSeen.clear(); // easy to forget
  for (const c of s) {
    if (globalSeen.has(c)) return false;
    globalSeen.add(c);
  }
  return true;
}

// GOOD: local state per call
function hasUniqueGood(s: string): boolean {
  const seen = new Set<string>();
  for (const c of s) {
    if (seen.has(c)) return false;
    seen.add(c);
  }
  return true;
}
```

---

## 9. Forgetting to update the answer after the final shrink

**Pitfall:** in variable windows, the best valid window may occur right before the loop ends, but if you only update inside `while`, you may miss it.

```ts
// BAD: only updates inside while; misses trailing valid window
function longestValidBad(s: string): number {
  let left = 0;
  let best = 0;
  const counts = new Map<string, number>();

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    counts.set(c, (counts.get(c) ?? 0) + 1);

    while ((counts.get(c) ?? 0) > 2) {
      // shrink...
      left++;
      best = Math.max(best, right - left + 1); // updated only while shrinking
    }
  }
  return best;
}

// GOOD: update after ensuring validity
function longestValidGood(s: string): number {
  let left = 0;
  let best = 0;
  const counts = new Map<string, number>();

  for (let right = 0; right < s.length; right++) {
    const c = s[right]!;
    counts.set(c, (counts.get(c) ?? 0) + 1);

    while ((counts.get(c) ?? 0) > 2) {
      const lc = s[left]!;
      counts.set(lc, (counts.get(lc) ?? 0) - 1);
      left++;
    }

    // window is valid here
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

