## 10. Incorrect shrink stopping condition (`left <= right` vs `left < right`)

**Pitfall:** empty windows, negative lengths, or infinite loops when over-shrinking.

```ts
// BAD: can make left > right + 1 and produce negative lengths
function shrinkBad(s: string): number {
  let left = 0;
  let best = 0;
  const seen = new Set<string>();

  for (let right = 0; right < s.length; right++) {
    while (seen.has(s[right]!)) {
      seen.delete(s[left]!);
      left++; // no guard
    }
    seen.add(s[right]!);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

// GOOD: guard shrink and handle empty windows defensively
function shrinkGood(s: string): number {
  let left = 0;
  let best = 0;
  const seen = new Set<string>();

  for (let right = 0; right < s.length; right++) {
    const ch = s[right]!;

    while (left <= right && seen.has(ch)) {
      seen.delete(s[left]!);
      left++;
    }

    // If left > right, window is empty; add current char fresh
    if (left > right) left = right;

    seen.add(ch);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

