```ts
import net from 'node:net';
import type { TcpServerOptions } from './types.js';

export function createTcpServer(opts: TcpServerOptions): net.Server {
  const server = net.createServer((socket) => {
    const remote = `${socket.remoteAddress}:${socket.remotePort}`;
    console.log(`[server] client connected: ${remote}`);

    socket.setEncoding('utf8');
    socket.setNoDelay(true);          // disable Nagle for low latency
    socket.setKeepAlive(true, 30000); // keep-alive probes

    let buffer = '';

    socket.on('data', (chunk: string) => {
      buffer += chunk;

      // Line-delimited framing: process complete lines only
      let newlineIndex: number;
      while ((newlineIndex = buffer.indexOf('\n')) !== -1) {
        const line = buffer.slice(0, newlineIndex).trimEnd();
        buffer = buffer.slice(newlineIndex + 1);

        if (line.length === 0) continue;
        console.log(`[server] recv from ${remote}: ${line}`);

        const reply = `echo: ${line}\n`;
        const ok = socket.write(reply, 'utf8');

        // Backpressure: if the kernel buffer is full, wait for 'drain'
        if (!ok) {
          socket.pause();
          socket.once('drain', () => socket.resume());
        }
      }
    });

    socket.on('end', () => console.log(`[server] client ended: ${remote}`));
    socket.on('close', (hadError) =>
      console.log(`[server] client closed: ${remote} (error=${hadError})`),
    );
    socket.on('error', (err) => console.error(`[server] socket error ${remote}:`, err.message));
  });

  if (opts.maxConnections !== undefined) {
    server.maxConnections = opts.maxConnections;
  }

  server.on('error', (err) => console.error('[server] error:', err.message));
  return server;
}
```

## `src/tcpClient.ts`

```ts
import net from 'node:net';

export interface TcpClientOptions {
  host: string;
  port: number;
  messages?: string[];
}

export function connectTcp(opts: TcpClientOptions): net.Socket {
  const socket = net.createConnection({ host: opts.host, port: opts.port }, () => {
    console.log(`[client] connected to ${opts.host}:${opts.port}`);

    const messages = opts.messages ?? ['hello', 'world', 'quit'];
    for (const m of messages) {
      socket.write(`${m}\n`, 'utf8');
    }
  });

  socket.setEncoding('utf8');
  socket.setNoDelay(true);

  let buffer = '';
  socket.on('data', (chunk: string) => {
    buffer += chunk;
    let idx: number;
    while ((idx = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 1);
      console.log(`[client] received: ${line}`);
    }
  });

  socket.on('error', (err) => console.error('[client] error:', err.message));
  socket.on('close', (hadError) =>
    console.log(`[client] closed (error=${hadError})`),
  );

  // Auto-close after a short delay so the demo terminates
  setTimeout(() => {
    if (!socket.destroyed) socket.end();
  }, 1500);

  return socket;
}
```

## `src/udpDemo.ts`

```ts
import dgram from 'node:dgram';

export function udpDemo(port: number): void {
  const sock = dgram.createSocket('udp4');

  sock.on('message', (msg, rinfo) => {
    const text = msg.toString('utf8');
    console.log(`[udp] ${rinfo.address}:${rinfo.port} -> ${text}`);
    // echo back
    sock.send(`ack: ${text}`, rinfo.port, rinfo.address, (err) => {
      if (err) console.error('[udp] send error:', err.message);
    });
  });

  sock.on('listening', () => {
    const addr = sock.address();
    console.log(`[udp] listening on ${addr.address}:${addr.port}`);
  });

  sock.on('error', (err) => console.error('[udp] error:', err.message));

  sock.bind(port);

  // Send a datagram to ourselves to demonstrate round-trip
  setTimeout(() => {
    sock.send('ping', port, '127.0.0.1', (err) => {
      if (err) console.error('[udp] initial send error:', err.message);
    });
  }, 300);

  setTimeout(() => {
    sock.close(() => console.log('[udp] socket closed'));
  }, 2000);
}
```

## `src/index.ts`

```ts
import { createTcpServer } from './tcpServer.js';
import { connectTcp } from './tcpClient.js';
import { udpDemo } from './udpDemo.js';

const mode = (process.argv[2] ?? 'server').toLowerCase();
const port = Number(process.argv[3] ?? 4000);

function shutdown(server?: net.Server): void {
  // dynamic import avoided by inline type
  if (server) {
    server.close(() => {
      console.log('[main] server closed');
      process.exit(0);
    });
    // Force exit if close hangs
    setTimeout(() => process.exit(0), 3000).unref();
  } else {
    process.exit(0);
  }
}

// Lazy import type only for typing; use require-style guard below
import net from 'node:net';

switch (mode) {
  case 'server': {
    const server = createTcpServer({ port });
    server.listen(port, '0.0.0.0', () => {
      console.log(`[main] TCP server listening on 0.0.0.0:${port}`);
    });
    process.on('SIGINT', () => shutdown(server));
    process.on('SIGTERM', () => shutdown(server));
    break;
  }
  case 'client': {
    const host = process.argv[4] ?? '127.0.0.1';
    connectTcp({ host, port });
    break;
  }
  case 'udp': {
    udpDemo(port);
    break;
  }
  default:
    console.error(`Unknown mode: ${mode}. Use: server | client | udp`);
    process.exit(1);
}
```

