## 5. A tiny typed protocol (length-prefixed JSON)

Because TCP is a stream, you need framing. Example: 4-byte length + JSON.

```ts
// protocol.ts
import net from 'node:net';

function send(socket: net.Socket, payload: unknown) {
  const json = Buffer.from(JSON.stringify(payload));
  const header = Buffer.alloc(4);
  header.writeUInt32BE(json.length, 0);
  socket.write(Buffer.concat([header, json]));
}

function createParser(onMessage: (msg: any) => void) {
  let buf = Buffer.alloc(0);
  return (chunk: Buffer) => {
    buf = Buffer.concat([buf, chunk]);
    while (buf.length >= 4) {
      const len = buf.readUInt32BE(0);
      if (buf.length < 4 + len) break;
      const body = buf.subarray(4, 4 + len);
      buf = buf.subarray(4 + len);
      onMessage(JSON.parse(body.toString()));
    }
  };
}

// usage
const server = net.createServer((sock) => {
  const parse = createParser((msg) => {
    console.log('msg:', msg);
    send(sock, { ok: true, echo: msg });
  });
  sock.on('data', parse);
});
server.listen(5000);
```

