### Notes / pitfalls
- **Partial data**: always buffer and split on `\n`; never assume one `data` event = one message.
- **Backpressure**: for high throughput, check `socket.write()` return value and pause/resume; omitted here for clarity.
- **Encoding**: `setEncoding("utf8")` makes `data` a string; otherwise you get `Buffer` and must decode.
- **Cleanup**: `socket.end()` sends FIN; `socket.destroy()` forcefully closes. Use `end()` for graceful shutdown.
- **Security**: this is plaintext TCP; for production use TLS (`tls` module) and validate inputs.

## Sockets & Networking in TypeScript — Interview-Style Answer

### 1. Core concepts

- **Socket**: an endpoint for communication identified by `(IP, port)`. In practice it’s a file descriptor / handle managed by the OS.
- **Transport protocols**
  - **TCP**: connection-oriented, reliable, ordered byte stream. Good default for APIs, DBs, chat.
  - **UDP**: connectionless datagrams, no guarantees, lower latency. Good for games, DNS, telemetry.
- **Client/server model**: server `bind()` + `listen()` + `accept()`; client `connect()`. After accept/connect, both sides read/write.
- **Byte-stream problem**: TCP has **no message boundaries**. If you send two JSON objects, the receiver may get them in one `data` event or split across many. Real protocols need **framing** (length prefix, delimiter, or HTTP).
- **Backpressure**: `socket.write()` returns `false` when the kernel buffer is full; wait for `'drain'`.
- **Node.js specifics**: networking is non-blocking and event-loop driven. TypeScript adds types for `net`, `dgram`, `Buffer`, and events.

### 2. Design we’ll implement

A small **length-prefixed JSON protocol** over TCP:

```
[4 bytes: payload length (big-endian)] [JSON payload]
```

We’ll build:

- `FramedSocket` — wraps `net.Socket`, reassembles TCP stream into messages.
- `TcpServer` — accepts connections, emits typed `FramedSocket`s.
- `connectClient` — dials and returns a `FramedSocket`.
- A tiny UDP echo example.

---

### 3. TypeScript implementation

```ts
// net-core.ts
import {
  createServer,
  createConnection,
  Socket,
  Server,
} from "node:net";
import { EventEmitter } from "node:events";

const MAX_MESSAGE_BYTES = 10 * 1024 * 1024; // 10 MiB guard

// ---------- Typed event helpers ----------
interface FramedEvents {
  message: (msg: unknown) => void;
  error: (err: Error) => void;
  close: () => void;
  drain: () => void;
}

export class FramedSocket extends EventEmitter {
  private buf: Buffer = Buffer.alloc(0);
  private destroyed = false;

  constructor(private readonly sock: Socket) {
    super();

    // Reassemble the TCP byte stream into framed messages.
    sock.on("data", (chunk: Buffer) => this.onData(chunk));
    sock.on("error", (err) => this.emit("error", err));
    sock.on("close", () => {
      this.destroyed = true;
      this.emit("close");
    });
    sock.on("drain", () => this.emit("drain"));
  }

  /** Send one JSON-serializable value. Returns false if backpressured. */
  send(value: unknown): boolean {
    if (this.destroyed) throw new Error("socket closed");
    const payload = Buffer.from(JSON.stringify(value), "utf8");
    if (payload.length > MAX_MESSAGE_BYTES) {
      throw new Error("message too large");
    }
    const header = Buffer.allocUnsafe(4);
    header.writeUInt32BE(payload.length, 0);
    return this.sock.write(Buffer.concat([header, payload]));
  }

  close(): void {
    this.sock.end(); // graceful FIN
  }

  forceClose(): void {
    this.sock.destroy();
  }

  private onData(chunk: Buffer): void {
    this.buf = Buffer.concat([this.buf, chunk]);

    // Drain as many complete frames as are available.
    while (this.buf.length >= 4) {
      const len = this.buf.readUInt32BE(0);
      if (len > MAX_MESSAGE_BYTES) {
        this.sock.destroy(new Error(`frame too large: ${len}`));
        return;
      }
      if (this.buf.length < 4 + len) break; // wait for rest

      const payloadBuf = this.buf.subarray(4, 4 + len);
      this.buf = this.buf.subarray(4 + len);

      try {
        const msg = JSON.parse(payloadBuf.toString("utf8"));
        this.emit("message", msg);
      } catch (e) {
        this.emit("error", e as Error);
      }
    }
  }
}

// Make EventEmitter typings nicer for consumers.
export interface FramedSocket extends EventEmitter {
  on<E extends keyof FramedEvents>(event: E, cb: FramedEvents[E]): this;
  emit<E extends keyof FramedEvents>(event: E, ...args: Parameters<FramedEvents[E]>): boolean;
}

// ---------- Server ----------
export class TcpServer extends EventEmitter {
  private server: Server;
  private listening = false;

  constructor(private readonly port: number, private readonly host = "0.0.0.0") {
    super();
    this.server = createServer((sock) => {
      const framed = new FramedSocket(sock);
      const remote = `${sock.remoteAddress}:${sock.remotePort}`;
      this.emit("connection", framed, remote);

      // Propagate errors so one bad client doesn't crash the process.
      framed.on("error", (err) => this.emit("clientError", err, remote));
    });
  }

  /** Resolve when listening; reject on bind error. */
  start(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.listening) return resolve();
      this.server.once("error", reject);
      this.server.listen(this.port, this.host, () => {
        this.listening = true;
        this.server.off("error", reject);
        resolve();
      });
    });
  }

  stop(): Promise<void> {
    return new Promise((resolve) => this.server.close(() => resolve()));
  }
}

export interface TcpServer extends EventEmitter {
  on(event: "connection", cb: (s: FramedSocket, remote: string) => void): this;
  on(event: "clientError", cb: (err: Error, remote: string) => void): this;
}

// ---------- Client ----------
export function connectClient(
  host: string,
  port: number,
  timeoutMs = 5000
): Promise<FramedSocket> {
  return new Promise((resolve, reject) => {
    const sock = createConnection({ host, port }, () => {
      resolve(new FramedSocket(sock));
    });

    const timer = setTimeout(() => {
      sock.destroy(new Error("connect timeout"));
    }, timeoutMs);

    sock.once("connect", () => clearTimeout(timer));
    sock.on("error", (err) => {
      clearTimeout(timer);
      reject(err);
    });
  });
}
```

