## 9. Proxy tunneling and TLS-in-TLS

When using an HTTP CONNECT proxy, upgrade the tunneled socket to TLS separately.

```ts
import http from 'http';
import tls from 'tls';

async function connectViaProxy(proxyHost: string, proxyPort: number, targetHost: string, targetPort: number) {
  const req = http.request({
    host: proxyHost,
    port: proxyPort,
    method: 'CONNECT',
    path: `${targetHost}:${targetPort}`,
  });

  const socket = await new Promise<any>((resolve, reject) => {
    req.on('connect', (res, socket) => {
      if (res.statusCode !== 200) {
        socket.destroy();
        reject(new Error(`Proxy CONNECT failed: ${res.statusCode}`));
        return;
      }
      resolve(socket);
    });
    req.on('error', reject);
    req.end();
  });

  // TLS over the proxy tunnel
  const tlsSocket = tls.connect({
    socket,
    servername: targetHost,
    rejectUnauthorized: true,
  });

  return tlsSocket;
}
```

Edge cases:
- proxy authentication (`Proxy-Authorization`)
- `407 Proxy Authentication Required`
- proxy drops idle tunnels

