## 11. WebSocket lifecycle, backpressure, and reconnect

```ts
import WebSocket from 'ws';

type WsClientOptions = {
  url: string;
  maxPayload?: number;
};

class ResilientWebSocket {
  private ws?: WebSocket;
  private attempt = 0;
  private closedByUser = false;

  constructor(private opts: WsClientOptions) {}

  connect() {
    this.closedByUser = false;
    this.ws = new WebSocket(this.opts.url, {
      handshakeTimeout: 10_000,
      maxPayload: this.opts.maxPayload ?? 1024 * 1024,
    });

    this.ws.on('open', () => {
      this.attempt = 0;
      console.log('WS open');
    });

    // Application-level heartbeat
    this.ws.on('ping', (data) => this.ws?.pong(data));

    this.ws.on('message', (data) => {
      // process message; check isBinary if needed
    });

    this.ws.on('close', (code, reason) => {
      if (this.closedByUser) return;
      const delay = Math.min(30_000, 1000 * 2 ** this.attempt) + Math.random() * 1000;
      this.attempt++;
      setTimeout(() => this.connect(), delay);
    });

    this.ws.on('error', (err) => {
      console.error('WS error:', err.message);
      // 'close' will follow; reconnect there
    });
  }

  send(payload: string | Buffer) {
    if (this.ws?.readyState !== WebSocket.OPEN) {
      throw new Error('WebSocket not open');
    }
    // ws handles internal backpressure; for very large payloads stream or chunk
    this.ws.send(payload, (err) => {
      if (err) console.error('WS send error:', err);
    });
  }

  close() {
    this.closedByUser = true;
    this.ws?.close(1000, 'client closing');
  }
}
```

Edge cases:
- abnormal close codes
- missing pong / dead connections
- server-side `verifyClient` / origin checks
- max payload enforcement
- bufferedAmount backpressure

