## 14. Security edge cases

- **DNS rebinding:** If your service fetches user-provided URLs, validate that resolved IPs are not private/loopback/link-local.
- **SSRF:** Block metadata IPs such as `169.254.169.254`.
- **Untrusted input as host/port:** validate and allowlist.
- **TLS downgrade:** enforce `minVersion`.
- **Compression bombs / huge bodies:** enforce size limits.
- **WebSocket origin validation:** check `Origin` header in `verifyClient`.

```ts
import WebSocket from 'ws';
import http from 'http';

const wss = new WebSocket.Server({
  port: 8081,
  verifyClient: (info: { origin: string; req: http.IncomingMessage }, cb) => {
    const allowed = ['https://app.example.com'];
    cb(allowed.includes(info.origin), 403, 'Forbidden origin');
  },
});
```

---

## Practical checklist

- Always attach `error` listeners to sockets and servers.
- Treat TCP as a stream: implement framing.
- Respect `write()` backpressure.
- Set timeouts and enable keepalive.
- Retry only idempotent operations on `ECONNRESET`.
- Use SNI, certificate validation, and minimum TLS versions.
- Handle DNS/IPv6 fallbacks.
- Implement exponential backoff with jitter for reconnects.
- Enforce payload and header size limits.
- Shut down gracefully and avoid leaking sockets.

If you are using a specific stack (e.g., Fastify, NestJS, gRPC, socket.io), many of these concerns are partially handled by the framework, but the underlying TCP/TLS edge cases still apply at the transport boundary.

Here is a complete, runnable TypeScript file with several sorting algorithms. It uses generics, supports custom comparators, keeps the built-in array unchanged (returns sorted copies), and includes small tests/assertions.

```ts
// sorts.ts
// Run with: npx ts-node sorts.ts
// Or compile: tsc sorts.ts && node sorts.js

type CompareFn<T> = (a: T, b: T) => number;

function defaultCompare<T>(a: T, b: T): number {
  const x = a as any;
  const y = b as any;
  return x < y ? -1 : x > y ? 1 : 0;
}

/* ---------- Bubble sort ---------- */
function bubbleSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  const a = arr.slice();
  let swapped = true;

  for (let pass = 0; pass < a.length - 1 && swapped; pass++) {
    swapped = false;
    for (let j = 0; j < a.length - 1 - pass; j++) {
      if (compare(a[j], a[j + 1]) > 0) {
        [a[j], a[j + 1]] = [a[j + 1], a[j]];
        swapped = true;
      }
    }
  }
  return a;
}

/* ---------- Selection sort ---------- */
function selectionSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  const a = arr.slice();
  const n = a.length;

  for (let i = 0; i < n - 1; i++) {
    let minIndex = i;
    for (let j = i + 1; j < n; j++) {
      if (compare(a[j], a[minIndex]) < 0) minIndex = j;
    }
    if (minIndex !== i) {
      [a[i], a[minIndex]] = [a[minIndex], a[i]];
    }
  }
  return a;
}

/* ---------- Insertion sort ---------- */
function insertionSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  const a = arr.slice();

  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    while (j >= 0 && compare(a[j], key) > 0) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key;
  }
  return a;
}

/* ---------- Merge sort (stable) ---------- */
function mergeSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  if (arr.length <= 1) return arr.slice();

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid), compare);
  const right = mergeSort(arr.slice(mid), compare);
  return merge(left, right, compare);
}

function merge<T>(left: T[], right: T[], compare: CompareFn<T>): T[] {
  const result: T[] = [];
  let i = 0;
  let j = 0;

  while (i < left.length && j < right.length) {
    // Use <= for stability.
    if (compare(left[i], right[j]) <= 0) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }
  while (i < left.length) result.push(left[i++]);
  while (j < right.length) result.push(right[j++]);
  return result;
}

/* ---------- Quick sort ---------- */
function quickSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  const a = arr.slice();

  const qs = (low: number, high: number): void => {
    if (low >= high) return;

    // Lomuto partition with middle pivot.
    const pivotIndex = Math.floor((low + high) / 2);
    const pivotValue = a[pivotIndex];

    [a[pivotIndex], a[high]] = [a[high], a[pivotIndex]];

    let storeIndex = low;
    for (let i = low; i < high; i++) {
      if (compare(a[i], pivotValue) <= 0) {
        [a[i], a[storeIndex]] = [a[storeIndex], a[i]];
        storeIndex++;
      }
    }
    [a[storeIndex], a[high]] = [a[high], a[storeIndex]];

    qs(low, storeIndex - 1);
    qs(storeIndex + 1, high);
  };

  qs(0, a.length - 1);
  return a;
}

/* ---------- Heap sort ---------- */
function heapSort<T>(
  arr: readonly T[],
  compare: CompareFn<T> = defaultCompare as CompareFn<T>
): T[] {
  const a = arr.slice();
  const n = a.length;

  const siftDown = (heapSize: number, root: number): void => {
    let largest = root;
    const left = 2 * root + 1;
    const right = 2 * root + 2;

    if (left < heapSize && compare(a[left], a[largest]) > 0) largest = left;
    if (right < heapSize && compare(a[right], a[largest]) > 0) largest = right;

    if (largest !== root) {
      [a[root], a[largest]] = [a[largest], a[root]];
      siftDown(heapSize, largest);
    }
  };

  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) siftDown(n, i);

  for (let end = n - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end], a[0]];
    siftDown(end, 0);
  }
  return a;
}

/* ---------- Counting sort (integers) ---------- */
function countingSort(arr: readonly number[]): number[] {
  if (arr.length === 0) return [];

  const min = Math.min(...arr);
  const max = Math.max(...arr);
  const range = max - min + 1;
  const count = new Array<number>(range).fill(0);

  for (const value of arr) count[value - min]++;
  const result: number[] = [];
  for (let value = min; value <= max; value++) {
    for (let c = 0; c < count[value - min]; c++) result.push(value);
  }
  return result;
}

/* ---------- Radix sort (integers, incl. negatives) ---------- */
function radixSort(arr: readonly number[]): number[] {
  if (arr.length === 0) return [];

  const min = Math.min(...arr);
  const offset = min < 0 ? -min : 0;
  const shifted = arr.map((x) => x + offset);
  const max = Math.max(...shifted);

  let output = shifted.slice();
  for (let exp = 1; Math.floor(max / exp) > 0; exp *= 10) {
    const count = new Array<number>(10).fill(0);
    for (const x of output) count[Math.floor(x / exp) % 10]++;
    for (let i = 1; i < 10; i++) count[i] += count[i - 1];

    const temp = new Array<number>(output.length);
    for (let i = output.length - 1; i >= 0; i--) {
      const digit = Math.floor(output[i] / exp) % 10;
      temp[count[digit] - 1] = output[i];
      count[digit]--;
    }
    output = temp;
  }

  return output.map((x) => x - offset);
}

/* ---------- Helpers / tests ---------- */
function isSorted<T>(arr: readonly T[], compare: CompareFn<T> = defaultCompare as CompareFn<T>): boolean {
  for (let i = 1; i < arr.length; i++) {
    if (compare(arr[i - 1], arr[i]) > 0) return false;
  }
  return true;
}

function runTests() {
  const data = [38, 27, 43, 3, 9, 82, 10, 27, 3];

  const algorithms = [
    ["bubble", bubbleSort],
    ["selection", selectionSort],
    ["insertion", insertionSort],
    ["merge", mergeSort],
    ["quick", quickSort],
    ["heap", heapSort],
  ] as const;

  console.log("Input:", data);
  for (const [name, sort] of algorithms) {
    const sorted = sort(data);
    console.log(`${name.padEnd(10)}:`, sorted, isSorted(sorted) ? "OK" : "FAIL");
  }

  const integers = [170, 45, 75, -90, -802, 24, 2, 66, -5];
  console.log("\nInput:", integers);
  console.log("counting  :", countingSort(integers), isSorted(countingSort(integers)) ? "OK" : "FAIL");
  console.log("radix     :", radixSort(integers), isSorted(radixSort(integers)) ? "OK" : "FAIL");

  // Generic object sorting + stability check.
  const people = [
    { id: 2, name: "Bob" },
    { id: 1, name: "Alice" },
    { id: 2, name: "Charlie" },
    { id: 1, name: "Zoe" },
  ];

  const byId = (a: { id: number }, b: { id: number }) => a.id - b.id;
  const sortedPeople = mergeSort(people, byId);
  console.log("\nPeople by id (stable):", sortedPeople);

  // Empty / single element edge cases.
  console.log("\nEdge cases:");
  console.log(bubbleSort([]));
  console.log(quickSort([42]));
}

runTests();
```

### Notes

- **Mutating vs pure:** These functions do not mutate the input; they clone with `slice()` and return a new array. If you want in-place versions, remove `slice()` and change the parameter type from `readonly T[]` to `T[]`.
- **Stability:** Merge sort is stable. The Lomuto quick sort here is not guaranteed stable. Heap, selection, and shell-style variants are generally unstable.
- **Custom comparator:** Pass a function like `(a, b) => a.age - b.age` for objects.
- **Complexity summary:**
  - Bubble/selection/insertion: `O(n²)` time, `O(1)` extra space for in-place versions.
  - Merge sort: `O(n log n)` time, `O(n)` extra space.
  - Quick sort: average `O(n log n)`, worst `O(n²)`; `O(log n)` recursive stack.
  - Heap sort: `O(n log n)` time, `O(1)` extra space.
  - Counting sort: `O(n + k)` time, `O(k)` space for integer range `k`.
  - Radix sort: `O(d · (n + b))` time, `O(n + b)` space.

For production TypeScript/JavaScript code, `Array.prototype.sort` (or `toSorted` for immutable sorting) is usually preferred because engines implement highly optimized hybrid algorithms such as Timsort.

## Sorting in TypeScript

### 1. The idea

Sorting means reordering a collection so its elements follow a defined order (ascending, descending, or custom). In TypeScript you usually:

- **Use the built-in `Array.prototype.sort()`** for almost everything.
- **Write a custom comparator** when the default ordering is wrong.
- **Implement classic algorithms** for learning, interviews, or special constraints (stability, memory, known data range).

TypeScript adds **static typing** to comparators and generic algorithms, catching mistakes like comparing incompatible types.

---

### 2. Built-in sort (the common case)

#### Basic syntax

```ts
const nums = [3, 1, 4, 1, 5];
nums.sort((a, b) => a - b); // ascending
// nums is now [1, 1, 3, 4, 5]
```

The comparator returns:
- `< 0` → `a` before `b`
- `0` → equal
- `> 0` → `b` before `a`

#### Descending

```ts
nums.sort((a, b) => b - a);
```

#### Sorting strings (avoid default lexicographic pitfalls)

```ts
const names = ["bob", "Alice", "charlie"];

// default sort is case-sensitive / code-point based
names.sort(); // ["Alice", "bob", "charlie"] (not intuitive)

// better: locale-aware, case-insensitive
names.sort((a, b) => a.localeCompare(b));
```

#### Sorting objects

```ts
interface User {
  name: string;
  age: number;
}

const users: User[] = [
  { name: "Ada", age: 30 },
  { name: "Bob", age: 25 },
];

users.sort((a, b) => a.age - b.age);
```

#### Important properties

- **Mutates in place** and returns the same array.
- **Stable** in modern engines (ES2019+): equal elements keep relative order.
- Default comparator converts elements to strings, so `[10, 2, 1]` becomes `["1","10","2"]` → always pass a comparator for numbers.

---

### 3. Reusable comparator type

```ts
type Comparator<T> = (a: T, b: T) => number;

const byAge: Comparator<User> = (a, b) => a.age - b.age;
const byName: Comparator<User> = (a, b) => a.name.localeCompare(b.name);

users.sort(byAge);
```

---

### 4. Classic algorithms in TypeScript

These are useful for interviews or when you need a specific behavior (e.g., stable merge sort, non-mutating output).

#### Insertion sort (in-place, good for small/nearly sorted data)

```ts
function insertionSort<T>(arr: T[], compare: Comparator<T>): T[] {
  for (let i = 1; i < arr.length; i++) {
    const key = arr[i];
    let j = i - 1;
    while (j >= 0 && compare(arr[j], key) > 0) {
      arr[j + 1] = arr[j];
      j--;
    }
    arr[j + 1] = key;
  }
  return arr;
}
```

#### Merge sort (stable, O(n log n), extra memory)

```ts
function merge<T>(left: T[], right: T[], compare: Comparator<T>): T[] {
  const result: T[] = [];
  let i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (compare(left[i], right[j]) <= 0) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }

  return result.concat(left.slice(i), right.slice(j));
}

function mergeSort<T>(arr: T[], compare: Comparator<T>): T[] {
  if (arr.length <= 1) return arr.slice();

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid), compare);
  const right = mergeSort(arr.slice(mid), compare);

  return merge(left, right, compare);
}
```

#### Quick sort (fast average case, not stable)

```ts
function quickSort<T>(arr: T[], compare: Comparator<T>): T[] {
  if (arr.length <= 1) return arr.slice();

  const pivot = arr[Math.floor(arr.length / 2)];
  const left = arr.filter(x => compare(x, pivot) < 0);
  const middle = arr.filter(x => compare(x, pivot) === 0);
  const right = arr.filter(x => compare(x, pivot) > 0);

  return [
    ...quickSort(left, compare),
    ...middle,
    ...quickSort(right, compare),
  ];
}
```

#### Counting sort (integers in a known range, O(n + k))

```ts
function countingSort(arr: number[]): number[] {
  if (arr.length === 0) return [];

  const min = Math.min(...arr);
  const max = Math.max(...arr);
  const range = max - min + 1;
  const count = new Array<number>(range).fill(0);

  for (const n of arr) count[n - min]++;

  const result: number[] = [];
  for (let i = 0; i < range; i++) {
    for (let c = 0; c < count[i]; c++) {
      result.push(i + min);
    }
  }

  return result;
}
```

---

### 5. Typical use cases

| Use case | Recommended approach |
|---|---|
| Sort table columns | `array.sort((a,b) => ...)` with typed comparator |
| Sort by multiple fields | Chain comparators: `a.age - b.age \|\| a.name.localeCompare(b.name)` |
| Need stable order of equal items | Built-in sort (modern) or merge sort |
| Large numeric datasets | Built-in sort (engine-optimized) |
| Small or nearly sorted arrays | Insertion sort |
| Integers in small range | Counting / radix sort |
| Prepare for binary search | Sort first, then `binarySearch` |
| Immutable state (React/Redux) | `[...arr].sort(...)` or `toSorted()` |

#### Non-mutating sort (modern TS/JS)

```ts
const sorted = [...users].sort(byAge);
// or
const sorted2 = users.toSorted(byAge); // ES2023, returns new array
```

---

### 6. Best practices

- **Always provide a comparator** for numbers/objects.
- **Use `localeCompare`** for user-facing strings.
- **Avoid `NaN` in comparators**; normalize data first.
- **Prefer built-in sort** unless you have a measured reason.
- **Type comparators** with generics for reuse.
- **Copy before sorting** when immutability matters.

---

### 7. Quick reference example

```ts
type Comparator<T> = (a: T, b: T) => number;

interface Product {
  name: string;
  price: number;
}

const products: Product[] = [
  { name: "Pen", price: 2 },
  { name: "Book", price: 12 },
  { name: "Pencil", price: 2 },
];

// Multi-criteria: price asc, then name asc
products.sort((a, b) =>
  a.price - b.price || a.name.localeCompare(b.name)
);

console.log(products);
// [{ name: "Pen", price: 2 }, { name: "Pencil", price: 2 }, { name: "Book", price: 12 }]
```

This covers the core ideas, syntax, and practical patterns for sorting in TypeScript.

A common mistake is relying on JavaScript/TypeScript’s default `Array.prototype.sort()` for numbers. The default sort converts elements to strings and compares UTF-16 code units, so numeric ordering breaks.

### Mistaken version

```ts
const scores: number[] = [10, 2, 1, 20];

// Mistake: no comparator, so values are compared as strings.
scores.sort();

console.log(scores); // [1, 10, 2, 20]
```

### Corrected version

```ts
const scores: number[] = [10, 2, 1, 20];

// Create a sorted copy instead of mutating the original array.
const sortedScores: number[] = [...scores].sort((a, b) => {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
});

console.log(sortedScores); // [1, 2, 10, 20]
console.log(scores);       // [10, 2, 1, 20] unchanged
```

### What was wrong and why

1. **Default sort is lexicographic, not numeric**  
   Without a comparator, `sort()` coerces numbers to strings. That makes `"10"` sort before `"2"` because `"1"` comes before `"2"` in UTF-16 ordering.

2. **The comparator must return a number**  
   A correct comparator returns a negative number when `a` should come first, a positive number when `b` should come first, and `0` when they are equivalent. Returning a boolean, as in `arr.sort((a, b) => a < b)`, is a type error in TypeScript and, even where tolerated, does not provide the required three-way ordering.

3. **`a - b` is common but not always ideal**  
   For ordinary integers, `(a, b) => a - b` works well. For very large values, floating-point subtraction can lose precision or produce `NaN`-like edge cases. The explicit `<` / `>` / `===` comparator avoids that.

4. **`sort()` mutates the original array**  
   In the mistaken version, `scores` itself is reordered. If the original order matters, sort a copy with `[...scores]` or `scores.slice()`.

5. **Stability and consistency matter**  
   A comparator should be consistent: if it says `a < b`, then it should not later say `b < a` for the same pair. Inconsistent comparators can produce implementation-dependent or unstable results. Returning `-1`, `0`, or `1` based on a total order keeps sorting deterministic.

## Common pitfalls when sorting in TypeScript

Below are the most frequent mistakes, why they bite, and idiomatic fixes.

### 1. Relying on the default lexicographic sort for numbers
`Array.prototype.sort()` converts elements to strings by default.

```ts
const nums = [10, 2, 1, 21];

// Pitfall: string ordering
console.log([...nums].sort()); // [1, 10, 2, 21]

// Fix: numeric comparator
const sorted = [...nums].sort((a, b) => a - b); // [1, 2, 10, 21]
```

### 2. Mutating the caller’s array
`sort()` is in-place. Returning the same reference surprises callers.

```ts
function getSorted(input: number[]): number[] {
  return input.sort((a, b) => a - b); // mutates input
}

// Fix: copy first
function getSortedSafe(input: readonly number[]): number[] {
  return [...input].sort((a, b) => a - b);
}
```

### 3. Comparator returns a boolean instead of a number
A boolean is coerced to `0`/`1`, which breaks ordering and can make equal elements appear “greater.”

```ts
const users = [{ age: 30 }, { age: 20 }];

// Pitfall
users.sort((a, b) => a.age > b.age); // wrong: boolean coercion

// Fix
users.sort((a, b) => a.age - b.age);
```

For non-numeric keys, return `-1 / 0 / 1` (or use `Math.sign`):

```ts
items.sort((a, b) => Math.sign(a.score - b.score));
```

### 4. Non-transitive or inconsistent comparators
If `compare(a,b) < 0` and `compare(b,c) < 0` but `compare(a,c) >= 0`, engines may produce different orders or even throw in strict mode.

```ts
// Pitfall: random comparator
arr.sort(() => Math.random() - 0.5); // undefined behavior

// Fix: deterministic, transitive comparator
arr.sort((a, b) => a.id - b.id);
```

### 5. `NaN` in the comparator
`NaN` makes the result of `<`/`>` comparisons false, so sorting becomes unpredictable.

```ts
const data = [3, NaN, 1, 2];

// Pitfall
data.sort((a, b) => a - b); // NaN poisons comparisons

// Fix: normalize NaN (example: push NaNs to end)
data.sort((a, b) => {
  if (Number.isNaN(a) && Number.isNaN(b)) return 0;
  if (Number.isNaN(a)) return 1;
  if (Number.isNaN(b)) return -1;
  return a - b;
});
```

### 6. Comparing floating-point values with `===`-style assumptions
Direct subtraction can collapse distinct values or produce `-0`.

```ts
const pts = [0.1 + 0.2, 0.3];

// Pitfall: tiny differences, unstable grouping
pts.sort((a, b) => a - b);

// Better for “bucketing”: compare with tolerance when grouping,
// but for pure ordering prefer direct numeric compare unless you need epsilon.
pts.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
```

### 7. Sorting `null` / `undefined` without handling them
`undefined - number` is `NaN`.

```ts
const maybe: (number | null)[] = [5, null, 2, null];

// Pitfall
maybe.sort((a, b) => (a ?? 0) - (b ?? 0)); // loses null distinction

// Fix: explicit ordering policy
maybe.sort((a, b) => {
  if (a === null && b === null) return 0;
  if (a === null) return 1;   // nulls last
  if (b === null) return -1;
  return a - b;
});
```

### 8. Assuming stability for equal keys (pre-ES2019 or custom sorts)
Modern `Array.prototype.sort` is stable, but if you implement your own sort (or target old engines), equal elements may reorder.

```ts
// If you need stable sort of objects by score:
const ranked = items
  .map((item, index) => ({ item, index }))
  .sort((a, b) => a.item.score - b.item.score || a.index - b.index)
  .map(x => x.item);
```

### 9. Multi-key sorting done incorrectly
Chaining `sort` calls or forgetting to short-circuit breaks priority.

```ts
type User = { lastName: string; firstName: string; age: number };

// Pitfall: last sort wins, not priority
users.sort((a, b) => a.age - b.age);
users.sort((a, b) => a.lastName.localeCompare(b.lastName));

// Fix: one comparator with short-circuit
users.sort((a, b) => {
  const byLast = a.lastName.localeCompare(b.lastName);
  if (byLast !== 0) return byLast;
  const byFirst = a.firstName.localeCompare(b.firstName);
  if (byFirst !== 0) return byFirst;
  return a.age - b.age;
});
```

### 10. Locale sorting performance and correctness
`localeCompare` is correct for user-facing text but slower and locale-dependent.

```ts
const words = ['ä', 'z', 'a'];

// Pitfall: default sort puts 'ä' after 'z' in many locales' code-unit order
words.sort(); // ['a', 'z', 'ä'] (code-unit order)

// Fix for UI: explicit locale
words.sort((a, b) => a.localeCompare(b, 'de'));

// Fix for speed/internal keys: normalize once
const normalized = words.map(w => ({ w, key: w.normalize('NFC').toLowerCase() }));
normalized.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
```

### 11. Sorting `Date` objects by reference
`Date` objects compare by reference, not value.

```ts
const dates = [new Date('2024-01-02'), new Date('2024-01-01')];

// Pitfall
dates.sort(); // compares object references, meaningless

// Fix
dates.sort((a, b) => a.getTime() - b.getTime());
```

### 12. Mixing `bigint` and `number`
TypeScript allows mixed arrays only with unions; arithmetic mixes are invalid/errors.

```ts
const mixed: (number | bigint)[] = [1n, 2, 3n];

// Pitfall: a - b is not allowed / coerces badly
// mixed.sort((a, b) => a - b); // type error or runtime issues

// Fix: compare within a common domain
mixed.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
```

### 13. Type narrowing inside comparators
The comparator’s parameters may be a union; accessing a property that exists on only one member fails narrowing.

```ts
type Item = { kind: 'a'; value: number } | { kind: 'b'; label: string };

// Pitfall
items.sort((x, y) => x.value - y.value); // 'value' not on 'b'

// Fix: narrow first
items.sort((x, y) => {
  if (x.kind === 'a' && y.kind === 'a') return x.value - y.value;
  return x.kind.localeCompare(y.kind);
});
```

### 14. Mutating elements during sort
Changing keys while sorting invalidates invariants and can infinite-loop or corrupt order.

```ts
// Pitfall
arr.sort((a, b) => {
  a.priority += 1; // mutating during comparison
  return a.priority - b.priority;
});

// Fix: compute a stable key beforehand
const keyed = arr.map(x => ({ x, key: computeKey(x) }));
keyed.sort((a, b) => a.key - b.key);
```

### 15. Quadratic sorts / recursion limits on large inputs
Bubble/insertion sort are fine for tiny arrays; naive quicksort can hit stack limits.

```ts
// Pitfall for large n: O(n^2) or deep recursion
function bubbleSort<T>(a: T[], cmp: (x: T, y: T) => number) { /* ... */ }

// Fix: use built-in sort (Timsort-ish, O(n log n)) or iterative merge sort
const sorted = [...large].sort(cmp);
```

### 16. Sorting already-sorted or nearly-sorted data with the wrong algorithm
Built-in sort is adaptive; custom “always quicksort” may be slower on nearly sorted input.

```ts
// Prefer built-in for general use; only custom sort when you have measured needs.
```

### 17. Duplicate keys and “stability of original index” assumptions
If equal keys must preserve insertion order, explicitly include the index (see #8).

### Quick safe template
```ts
function safeSort<T>(
  input: readonly T[],
  compare: (a: T, b: T) => number
): T[] {
  return input
    .map((value, index) => ({ value, index }))
    .sort((a, b) => compare(a.value, b.value) || a.index - b.index)
    .map(x => x.value);
}
```

Use this when you need: immutability, stability, and a clean comparator contract.

## Exercise

**Task:** Implement a **stable, multi-key sorter** in TypeScript.

Given an array of objects and a list of sort keys (each with a field name, direction, and optional custom comparator), return a **new** sorted array without mutating the input. Requirements:

- Sort by keys in priority order (first key = primary).
- Support `asc` / `desc`.
- Be **stable**: equal elements keep their original relative order.
- Worst-case **O(n log n)** time.

---

## Step-by-step solution

### Step 1 — Define the public API

We describe each sort key and the function signature.

```ts
type Direction = 'asc' | 'desc';

interface SortKey<T> {
  key: keyof T;
  direction?: Direction;
  compare?: (a: T[keyof T], b: T[keyof T]) => number;
}

function multiKeySort<T>(items: readonly T[], keys: readonly SortKey<T>[]): T[];
```

### Step 2 — Build a single comparator from the keys

Iterate keys in order; the first non-zero result wins. Flip sign for `desc`.

```ts
function compareByKeys<T>(a: T, b: T, keys: readonly SortKey<T>[]): number {
  for (const spec of keys) {
    const dir = spec.direction ?? 'asc';
    const raw = spec.compare
      ? spec.compare(a[spec.key], b[spec.key])
      : defaultCompare(a[spec.key], b[spec.key]);
    if (raw !== 0) return dir === 'desc' ? -raw : raw;
  }
  return 0; // equal according to all keys -> stable tie
}
```

### Step 3 — A sensible default comparator

Handle numbers, dates, booleans, null/undefined, and fall back to string comparison.

```ts
function defaultCompare(a: unknown, b: unknown): number {
  if (a === b) return 0;
  if (a == null) return b == null ? 0 : -1;
  if (b == null) return 1;
  if (typeof a === 'number' && typeof b === 'number') return a - b;
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  if (typeof a === 'boolean' && typeof b === 'boolean') return Number(a) - Number(b);
  return String(a).localeCompare(String(b));
}
```

### Step 4 — Implement a stable merge sort

Merge sort is stable and O(n log n) worst-case. Stability comes from using `<=` when taking from the left half: on ties we prefer the element that was originally earlier.

```ts
function mergeSort<T>(arr: T[], compare: (a: T, b: T) => number): T[] {
  if (arr.length <= 1) return arr.slice();

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid), compare);
  const right = mergeSort(arr.slice(mid), compare);
  return merge(left, right, compare);
}

function merge<T>(left: T[], right: T[], compare: (a: T, b: T) => number): T[] {
  const out: T[] = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (compare(left[i], right[j]) <= 0) out.push(left[i++]); // <= keeps stability
    else out.push(right[j++]);
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}
```

### Step 5 — Wire it together

```ts
function multiKeySort<T>(items: readonly T[], keys: readonly SortKey<T>[]): T[] {
  const compare = (a: T, b: T) => compareByKeys(a, b, keys);
  return mergeSort([...items], compare);
}
```

### Step 6 — Verify with a practical example

```ts
interface Employee {
  name: string;
  dept: string;
  salary: number;
}

const staff: Employee[] = [
  { name: 'Zoe',  dept: 'Eng',   salary: 90 },
  { name: 'Amy',  dept: 'Sales', salary: 70 },
  { name: 'Bob',  dept: 'Eng',   salary: 90 }, // tie with Zoe on (dept, salary)
  { name: 'Carl', dept: 'Eng',   salary: 80 },
];

const sorted = multiKeySort(staff, [
  { key: 'dept',   direction: 'asc' },
  { key: 'salary', direction: 'desc' },
  { key: 'name',   direction: 'asc' },
]);

console.log(sorted);
// [
//   { name: 'Zoe',  dept: 'Eng',   salary: 90 },  // Zoe before Bob (stable tie-break by name? here name asc => Bob? wait)
// ...
// ]
```

> Note: with `name asc` as the final key, `Bob` sorts before `Zoe`. To demonstrate **stability**, remove the `name` key: Zoe and Bob tie on `(dept, salary)` and keep original order (Zoe, then Bob).

