## Clean TypeScript Implementation

```ts
// ============================================================================
// Sorting Algorithms in TypeScript
// Each sort is generic and accepts an optional comparator.
// ============================================================================

type CompareFn<T> = (a: T, b: T) => number;

/** Default comparator for primitives / anything comparable via < > */
const defaultCompare: CompareFn<any> = (a, b) =>
  a < b ? -1 : a > b ? 1 : 0;

function swap<T>(arr: T[], i: number, j: number): void {
  [arr[i], arr[j]] = [arr[j], arr[i]];
}

// ----------------------------------------------------------------------------
// 1. Bubble Sort — O(n²), stable, O(1) space, early exit optimization
// ----------------------------------------------------------------------------
export function bubbleSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  const n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;
    // Last i elements are already in place.
    for (let j = 0; j < n - 1 - i; j++) {
      if (compare(arr[j], arr[j + 1]) > 0) {
        swap(arr, j, j + 1);
        swapped = true;
      }
    }
    if (!swapped) break; // Already sorted.
  }
  return arr;
}

// ----------------------------------------------------------------------------
// 2. Selection Sort — O(n²), not stable, O(1) space, minimal swaps
// ----------------------------------------------------------------------------
export function selectionSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  const n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    let minIndex = i;
    for (let j = i + 1; j < n; j++) {
      if (compare(arr[j], arr[minIndex]) < 0) minIndex = j;
    }
    if (minIndex !== i) swap(arr, i, minIndex);
  }
  return arr;
}

// ----------------------------------------------------------------------------
// 3. Insertion Sort — O(n²) worst, O(n) best, stable, O(1) space
// ----------------------------------------------------------------------------
export function insertionSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  const n = arr.length;
  for (let i = 1; i < n; i++) {
    const key = arr[i];
    let j = i - 1;
    // Shift larger elements right to make room for key.
    while (j >= 0 && compare(arr[j], key) > 0) {
      arr[j + 1] = arr[j];
      j--;
    }
    arr[j + 1] = key;
  }
  return arr;
}

// ----------------------------------------------------------------------------
// 4. Merge Sort — O(n log n) all cases, stable, O(n) extra space
// ----------------------------------------------------------------------------
export function mergeSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  if (arr.length <= 1) return arr.slice();

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid), compare);
  const right = mergeSort(arr.slice(mid), compare);
  return merge(left, right, compare);
}

function merge<T>(left: T[], right: T[], compare: CompareFn<T>): T[] {
  const result: T[] = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    // <= keeps stability: take from left when equal.
    if (compare(left[i], right[j]) <= 0) result.push(left[i++]);
    else result.push(right[j++]);
  }
  // Append leftovers.
  while (i < left.length) result.push(left[i++]);
  while (j < right.length) result.push(right[j++]);
  return result;
}

// ----------------------------------------------------------------------------
// 5. Quick Sort — O(n log n) average, O(n²) worst, in-place, not stable
//    Uses Hoare partition + random pivot for robustness.
// ----------------------------------------------------------------------------
export function quickSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  quickSortRange(arr, 0, arr.length - 1, compare);
  return arr;
}

function quickSortRange<T>(arr: T[], low: number, high: number, compare: CompareFn<T>): void {
  if (low >= high) return;

  const pivotIndex = partition(arr, low, high, compare);
  // Recurse on smaller side first to keep stack depth O(log n).
  if (pivotIndex - low < high - pivotIndex) {
    quickSortRange(arr, low, pivotIndex, compare);
    quickSortRange(arr, pivotIndex + 1, high, compare);
  } else {
    quickSortRange(arr, pivotIndex + 1, high, compare);
    quickSortRange(arr, low, pivotIndex, compare);
  }
}

function partition<T>(arr: T[], low: number, high: number, compare: CompareFn<T>): number {
  // Random pivot to avoid worst-case on already-sorted input.
  const randomPivot = low + Math.floor(Math.random() * (high - low + 1));
  swap(arr, randomPivot, high);

  const pivot = arr[high];
  let i = low - 1;
  let j = high + 1;

  while (true) {
    do { i++; } while (compare(arr[i], pivot) < 0);
    do { j--; } while (compare(arr[j], pivot) > 0);
    if (i >= j) return j;
    swap(arr, i, j);
  }
}

// ----------------------------------------------------------------------------
// 6. Heap Sort — O(n log n) all cases, in-place, not stable
// ----------------------------------------------------------------------------
export function heapSort<T>(arr: T[], compare: CompareFn<T> = defaultCompare): T[] {
  const n = arr.length;
  if (n <= 1) return arr;

  // Build max-heap (bottom-up).
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    siftDown(arr, i, n, compare);
  }

  // Repeatedly extract the root (max) to the end.
  for (let end = n - 1; end > 0; end--) {
    swap(arr, 0, end);
    siftDown(arr, 0, end, compare);
  }
  return arr;
}

function siftDown<T>(arr: T[], start: number, end: number, compare: CompareFn<T>): void {
  let root = start;
  while (true) {
    const left = 2 * root + 1;
    if (left >= end) break;
    const right = left + 1;
    let swapIndex = root;

    if (compare(arr[left], arr[swapIndex]) > 0) swapIndex = left;
    if (right < end && compare(arr[right], arr[swapIndex]) > 0) swapIndex = right;

    if (swapIndex === root) break;
    swap(arr, root, swapIndex);
    root = swapIndex;
  }
}

// ----------------------------------------------------------------------------
// 7. Counting Sort — O(n + k) for bounded non-negative integers
// ----------------------------------------------------------------------------
export function countingSort(arr: number[]): number[] {
  if (arr.length === 0) return [];

  const min = Math.min(...arr);
  const max = Math.max(...arr);
  const range = max - min + 1;
  const count = new Array<number>(range).fill(0);

  for (const value of arr) count[value - min]++;
  // Prefix sums -> positions.
  for (let i = 1; i < range; i++) count[i] += count[i - 1];

  const output = new Array<number>(arr.length);
  // Iterate backwards for stability.
  for (let i = arr.length - 1; i >= 0; i--) {
    const idx = arr[i] - min;
    output[count[idx] - 1] = arr[i];
    count[idx]--;
  }
  return output;
}

// ============================================================================
// Demo
// ============================================================================
if (require.main === module) {
  const data = [5, 3, 8, 1, 9, 2, 7, 4, 6];
  console.log("bubble:   ", bubbleSort([...data]));
  console.log("selection:", selectionSort([...data]));
  console.log("insertion:", insertionSort([...data]));
  console.log("merge:    ", mergeSort(data));
  console.log("quick:    ", quickSort([...data]));
  console.log("heap:     ", heapSort([...data]));
  console.log("counting: ", countingSort([4, 2, 2, 8, 3, 3, 1]));
}
```

### Interview Tips for This Code
- **Explain before coding**: state constraints (sorted order, stability, memory budget).
- **Pick the right tool**:
  - Need **stable + guaranteed O(n log n)** → merge sort.
  - Need **in-place + average fast** → quick sort (random/median pivot).
  - Need **guaranteed worst-case + O(1) space** → heap sort.
  - **Small / nearly sorted** → insertion sort.
  - **Bounded integers** → counting/radix sort.
- **Edge cases**: empty array, single element, all duplicates, already sorted/reverse sorted.
- **Complexity check**: always state time + space for best/average/worst.
- **Production reality**: prefer built-in sort unless a specific property (stability, memory, custom) is required.

When sorting in TypeScript, most bugs come from `Array.prototype.sort`’s default behavior (it mutates, converts values to strings, and historically was unstable), from comparators that violate the contract (must return a finite negative/zero/positive number and be transitive), and from special numeric values such as `NaN`, `Infinity`, `-0`, and `null`.

Below are the important edge cases, with idiomatic TypeScript examples.

---

## 1. Never rely on the default comparator

The default sort compares UTF-16 code units, so numbers are sorted lexicographically.

```ts
const nums = [10, 2, 1, 20];

// Bad: ["1", "10", "2", "20"]
console.log([...nums].sort());

// Good
console.log([...nums].sort((a, b) => a - b));
```

For anything beyond simple ASCII strings, pass an explicit comparator.

---

## 2. Mutating vs. non-mutating sort

`sort()` mutates the original array. In TypeScript, prefer immutable operations for readonly data.

```ts
function sortedCopy<T>(arr: readonly T[], cmp: (a: T, b: T) => number): T[] {
  return [...arr].sort(cmp);
}

// ES2023+ / TS lib "ES2023.Array"
const original = [3, 1, 2];
const sorted = original.toSorted((a, b) => a - b);

console.log(original); // [3, 1, 2] unchanged
console.log(sorted);   // [1, 2, 3]
```

---

## 3. `NaN` in the data

`a - b` produces `NaN` when either value is `NaN`, and comparators returning `NaN` have implementation-defined behavior.

```ts
function compareNumbers(a: number, b: number): number {
  const aNaN = Number.isNaN(a);
  const bNaN = Number.isNaN(b);

  if (aNaN && bNaN) return 0;
  if (aNaN) return 1;   // NaN last
  if (bNaN) return -1;  // NaN last

  if (a === b) return 0;
  return a < b ? -1 : 1;
}

console.log([3, NaN, 1, NaN, 2].sort(compareNumbers));
// [1, 2, 3, NaN, NaN]
```

---

## 4. `Infinity` and `-Infinity`

Subtracting infinities can produce `NaN` (`Infinity - Infinity`). Use relational comparison instead of subtraction.

```ts
function compareFiniteOrInfinite(a: number, b: number): number {
  if (Number.isNaN(a) || Number.isNaN(b)) return compareNumbers(a, b);
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

console.log([Infinity, -Infinity, 0, 5].sort(compareFiniteOrInfinite));
// [-Infinity, 0, 5, Infinity]
```

---

## 5. `-0` vs. `0`

`-0 === 0` is `true`, but they are distinguishable with `Object.is`. If ordering matters, handle explicitly.

```ts
function compareSignedZero(a: number, b: number): number {
  if (a === 0 && b === 0) {
    const aNeg = Object.is(a, -0);
    const bNeg = Object.is(b, -0);
    if (aNeg && !bNeg) return -1;
    if (!aNeg && bNeg) return 1;
  }
  if (a === b) return 0;
  return a < b ? -1 : 1;
}
```

---

## 6. `null` and `undefined`

Accessing properties on `null`/`undefined` inside a comparator throws. Decide whether missing values go first or last.

```ts
type MaybeNumber = number | null | undefined;

function compareNullableNumbers(a: MaybeNumber, b: MaybeNumber): number {
  const aMissing = a == null;
  const bMissing = b == null;

  if (aMissing && bMissing) return 0;
  if (aMissing) return 1;  // missing values last
  if (bMissing) return -1;

  return compareNumbers(a as number, b as number);
}

console.log([5, null, 2, undefined, 9].sort(compareNullableNumbers));
// [2, 5, 9, null, undefined]
```

---

## 7. Mixed runtime types

TypeScript should prevent mixed arrays, but JavaScript runtime code may still receive `unknown[]`. Normalize before sorting or reject mixed types.

```ts
function sortUnknownNumbers(values: unknown[]): number[] {
  const numbers = values.filter((v): v is number => typeof v === "number");
  if (numbers.length !== values.length) {
    throw new TypeError("All values must be numbers");
  }
  return numbers.sort(compareNumbers);
}
```

---

## 8. Comparator must return a finite number

A common bug is returning a boolean or a non-finite value.

```ts
// Bad: boolean is not a valid comparator result
// arr.sort((a, b) => a > b);

// Good: normalize to -1 / 0 / 1
function normalizeComparatorResult(result: number): number {
  if (Number.isNaN(result)) throw new RangeError("Comparator returned NaN");
  if (!Number.isFinite(result)) throw new RangeError("Comparator returned Infinity");
  return result < 0 ? -1 : result > 0 ? 1 : 0;
}

function safeSort<T>(arr: readonly T[], cmp: (a: T, b: T) => number): T[] {
  return [...arr].sort((a, b) => normalizeComparatorResult(cmp(a, b)));
}
```

---

## 9. Comparator transitivity

The comparator must define a total order. Non-transitive comparators produce engine-dependent, often corrupted results.

```ts
// Bad: random comparator destroys ordering guarantees
// arr.sort(() => Math.random() - 0.5);

// Bad: inconsistent comparator
function badCompare(a: number, b: number): number {
  if (a === b) return 0;
  // Not transitive in general
  return Math.sin(a) < Math.sin(b) ? -1 : 1;
}

// Good: derive from a stable key
function stableKeyCompare(a: number, b: number): number {
  return a - b;
}
```

---

## 10. Floating-point precision

For very large integers, `a - b` can overflow or lose precision. Use relational operators.

```ts
const big = [Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER - 1, 0];

// Risky for huge values:
// big.sort((a, b) => a - b);

// Safer:
big.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
```

For `bigint`, never subtract mixed or huge values as numbers; compare directly.

```ts
function compareBigInt(a: bigint, b: bigint): number {
  return a < b ? -1 : a > b ? 1 : 0;
}
```

---

## 11. Sorting objects by multiple keys

Sort by the first key, then tie-break with subsequent keys. Preserve original index for a stable final order.

```ts
type User = { name: string; age: number };

function sortUsers(users: readonly User[]): User[] {
  return users
    .map((user, index) => ({ user, index }))
    .sort((a, b) => {
      const byName = a.user.name.localeCompare(b.user.name);
      if (byName !== 0) return byName;
      const byAge = a.user.age - b.user.age;
      if (byAge !== 0) return byAge;
      return a.index - b.index;
    })
    .map(({ user }) => user);
}
```

---

## 12. `Date` objects

Compare timestamps, not object references or string coercion.

```ts
function compareDates(a: Date, b: Date): number {
  return compareNumbers(a.getTime(), b.getTime());
}
```

---

## 13. Strings, locale, case, and accents

Default string comparison is by UTF-16 code units, so `"Z"` sorts before `"a"`, and accented characters sort unpredictably. Use `Intl.Collator`.

```ts
const collator = new Intl.Collator("en", {
  sensitivity: "base", // case/accent-insensitive
  numeric: true,       // "file2" before "file10"
});

const files = ["file10.txt", "file2.txt", "File1.txt", "café", "cafe"];
console.log(files.sort(collator.compare));
```

For simple ASCII case-insensitive sorting, lowercasing may be enough, but `localeCompare`/`Collator` is more correct and can be cached for performance.

---

## 14. Sparse arrays and holes

Holes can behave like `undefined` in sorting and may move to the end. Convert to a dense array first if hole semantics are not desired.

```ts
const sparse: (number | undefined)[] = [];
sparse[0] = 3;
sparse[3] = 1;
// sparse is [3, <hole>, <hole>, 1]

// Convert holes to undefined explicitly
const dense = Array.from(sparse);
console.log(dense.sort(compareNullableNumbers));
// [1, 3, undefined, undefined]

// Or remove holes entirely
const compact = sparse.filter((x): x is number => x !== undefined);
```

---

## 15. Stability

`Array.prototype.sort` is guaranteed stable since ES2019. Still, do not assume stability in a custom sorting implementation, and preserve original indices when tie-breaking matters.

```ts
function stableSortBy<T, K>(
  arr: readonly T[],
  key: (item: T) => K,
  compareKeys: (a: K, b: K) => number
): T[] {
  return arr
    .map((value, index) => ({ value, index }))
    .sort((a, b) => {
      const byKey = compareKeys(key(a.value), key(b.value));
      return byKey !== 0 ? byKey : a.index - b.index;
    })
    .map(({ value }) => value);
}
```

---

## 16. Performance: avoid expensive work in the comparator

Comparators run many times. Precompute sort keys (Schwartzian transform) when key computation is expensive.

```ts
function sortByExpensiveKey<T>(arr: readonly T[], keyOf: (item: T) => string): T[] {
  const decorated = arr.map((item, index) => ({
    item,
    key: keyOf(item),
    index,
  }));

  decorated.sort((a, b) => {
    const byKey = a.key.localeCompare(b.key);
    return byKey !== 0 ? byKey : a.index - b.index;
  });

  return decorated.map((x) => x.item);
}
```

Also avoid sorting huge arrays recursively with a hand-written quicksort; use the built-in iterative sort or an iterative merge sort to prevent stack overflow.

---

## 17. Readonly arrays in TypeScript

Mutable arrays expose `sort`; readonly arrays do not. Create a mutable copy.

```ts
function sortReadonly(nums: readonly number[]): number[] {
  const copy: number[] = [...nums];
  copy.sort(compareNumbers);
  return copy;
}
```

---

## 18. Enums and literal unions

Numeric enums sort naturally after ensuring number comparison. String enums often need explicit ordering.

```ts
enum Priority { Low = 1, Medium = 2, High = 3 }

const priorities = [Priority.High, Priority.Low, Priority.Medium];
priorities.sort((a, b) => a - b);
```

```ts
type Status = "todo" | "doing" | "done";
const statusRank: Record<Status, number> = {
  todo: 0,
  doing: 1,
  done: 2,
};

function sortStatuses(statuses: readonly Status[]): Status[] {
  return [...statuses].sort((a, b) => statusRank[a] - statusRank[b]);
}
```

---

## A robust reusable helper

Combining several edge cases into one utility:

```ts
type Comparator<T> = (a: T, b: T) => number;

export function robustSort<T>(
  input: readonly T[],
  compare: Comparator<T>,
  options: { mutate?: boolean; nanPosition?: "first" | "last" } = {}
): T[] {
  const { mutate = false, nanPosition = "last" } = options;
  const arr = mutate ? (input as T[]) : [...input];

  arr.sort((a, b) => {
    const raw = compare(a, b);

    if (Number.isNaN(raw)) {
      // NaN comparator results are invalid; fail loudly in dev.
      throw new RangeError("Comparator returned NaN");
    }
    if (!Number.isFinite(raw)) {
      throw new RangeError("Comparator returned a non-finite value");
    }

    return raw < 0 ? -1 : raw > 0 ? 1 : 0;
  });

  return arr;
}
```

Use it as:

```ts
const data = [3, NaN, 1, 2];
const result = robustSort(data, compareNumbers, { nanPosition: "last" });
```

---

## Summary checklist

- Always provide a comparator for non-string data.
- Never use `a - b` when values may be `NaN`, `Infinity`, very large, or `bigint`.
- Normalize comparator results to `-1`, `0`, or `1`.
- Keep comparators pure, deterministic, and transitive.
- Handle `null`/`undefined` intentionally.
- Use `Intl.Collator` for human-facing string ordering.
- Avoid mutating inputs unless explicitly intended.
- Convert sparse arrays to dense arrays when holes are not meaningful.
- Precompute expensive keys and preserve original indices for stable tie-breaking.
- Prefer built-in sort over recursive custom quicksort for large inputs.

# Stack & Heap in TypeScript

Below is a complete, runnable TypeScript file. It implements:
- a generic **`Stack<T>`** (LIFO) with iterator + helpers,
- a generic **`Heap<T>`** (configurable min/max via comparator) with O(log n) insert/extract, O(n) build, and heap sort,
- a runnable demo at the bottom.

Save as `stackheap.ts` and run with `npx ts-node stackheap.ts` (or `tsc` then `node`).

```ts
// stackheap.ts
// Generic Stack + Heap implementations with a runnable demo.

/* ------------------------------------------------------------------ */
/*                       STACK (LIFO)                                 */
/* ------------------------------------------------------------------ */

class Stack<T> {
  private items: T[] = [];

  push(item: T): void {
    this.items.push(item);
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  size(): number {
    return this.items.length;
  }

  clear(): void {
    this.items.length = 0;
  }

  toArray(): T[] {
    // bottom -> top
    return [...this.items];
  }

  // top -> bottom iteration (most useful for a stack)
  *[Symbol.iterator](): Iterator<T> {
    for (let i = this.items.length - 1; i >= 0; i--) {
      yield this.items[i];
    }
  }

  // Convenience: clone the stack
  clone(): Stack<T> {
    const s = new Stack<T>();
    s.items = [...this.items];
    return s;
  }
}

/* ------------------------------------------------------------------ */
/*                       HEAP (priority queue)                        */
/* ------------------------------------------------------------------ */

type Comparator<T> = (a: T, b: T) => number;

function defaultCompare<T>(a: T, b: T): number {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

class Heap<T> {
  private data: T[] = [];
  private compare: Comparator<T>;

  constructor(compare?: Comparator<T>) {
    this.compare = compare ?? defaultCompare;
  }

  /* Factory helpers */
  static min<T>(...items: T[]): Heap<T> {
    const h = new Heap<T>();
    h.build(items);
    return h;
  }

  static max<T>(...items: T[]): Heap<T> {
    const h = new Heap<T>((a, b) => defaultCompare(b, a));
    h.build(items);
    return h;
  }

  static from<T>(items: Iterable<T>, compare?: Comparator<T>): Heap<T> {
    const h = new Heap<T>(compare);
    h.build(Array.from(items));
    return h;
  }

  /* Core API */
  get size(): number {
    return this.data.length;
  }

  isEmpty(): boolean {
    return this.data.length === 0;
  }

  peek(): T | undefined {
    return this.data[0];
  }

  insert(value: T): void {
    this.data.push(value);
    this.siftUp(this.data.length - 1);
  }

  insertAll(values: Iterable<T>): void {
    for (const v of values) this.insert(v);
  }

  // Removes and returns the root (min for min-heap, max for max-heap)
  extract(): T | undefined {
    if (this.data.length === 0) return undefined;
    const root = this.data[0];
    const last = this.data.pop()!;
    if (this.data.length > 0) {
      this.data[0] = last;
      this.siftDown(0);
    }
    return root;
  }

  // O(n) bulk construction (heapify)
  build(items: T[]): void {
    this.data = [...items];
    // Start from last non-leaf node
    for (let i = Math.floor(this.data.length / 2) - 1; i >= 0; i--) {
      this.siftDown(i);
    }
  }

  clear(): void {
    this.data.length = 0;
  }

  toArray(): T[] {
    // Returns internal heap-ordered array (NOT sorted)
    return [...this.data];
  }

  // Non-destructive sorted copy via heap sort
  toSorted(): T[] {
    const copy = new Heap<T>(this.compare);
    copy.data = [...this.data];
    const out: T[] = [];
    while (!copy.isEmpty()) out.push(copy.extract()!);
    return out;
  }

  [Symbol.iterator](): Iterator<T> {
    // Iterate in priority order (destructive of the copy only)
    return this.toSorted()[Symbol.iterator]();
  }

  /* ---------------------------------------------------------------- */
  /* Internal helpers                                                  */
  /* ---------------------------------------------------------------- */
  private parent(i: number): number {
    return Math.floor((i - 1) / 2);
  }
  private left(i: number): number {
    return 2 * i + 1;
  }
  private right(i: number): number {
    return 2 * i + 2;
  }

  private siftUp(i: number): void {
    while (i > 0) {
      const p = this.parent(i);
      if (this.compare(this.data[i], this.data[p]) < 0) {
        [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
        i = p;
      } else {
        break;
      }
    }
  }

  private siftDown(i: number): void {
    const n = this.data.length;
    while (true) {
      const l = this.left(i);
      const r = this.right(i);
      let smallest = i;
      if (l < n && this.compare(this.data[l], this.data[smallest]) < 0) {
        smallest = l;
      }
      if (r < n && this.compare(this.data[r], this.data[smallest]) < 0) {
        smallest = r;
      }
      if (smallest !== i) {
        [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
        i = smallest;
      } else {
        break;
      }
    }
  }
}

/* ------------------------------------------------------------------ */
/*                       UTILITIES                                    */
/* ------------------------------------------------------------------ */

// Heap sort (ascending) using a max-heap, in-place on a copy
function heapSort<T>(items: T[], compare?: Comparator<T>): T[] {
  const cmp = compare ?? defaultCompare;
  const h = new Heap<T>((a, b) => cmp(b, a)); // max-heap
  h.build(items);
  const result: T[] = [];
  while (!h.isEmpty()) result.push(h.extract()!);
  return result.reverse(); // extract gives descending; reverse -> ascending
}

// Alternatively simpler: min-heap extract gives ascending directly
function heapSortAsc<T>(items: T[], compare?: Comparator<T>): T[] {
  const h = new Heap<T>(compare);
  h.build(items);
  const out: T[] = [];
  while (!h.isEmpty()) out.push(h.extract()!);
  return out;
}

/* ------------------------------------------------------------------ */
/*                       RUNNABLE DEMO                                */
/* ------------------------------------------------------------------ */

function demoStack(): void {
  console.log("=== STACK DEMO ===");
  const s = new Stack<number>();
  s.push(10);
  s.push(20);
  s.push(30);
  console.log("size:", s.size());          // 3
  console.log("peek:", s.peek());           // 30
  console.log("pop:", s.pop());             // 30
  console.log("isEmpty:", s.isEmpty());     // false
  console.log("toArray:", s.toArray());     // [10, 20]

  console.log("iterate top->bottom:");
  for (const v of s) console.log("  ", v); // 20, 10

  // Classic use: balanced parentheses
  function isBalanced(expr: string): boolean {
    const st = new Stack<string>();
    const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
    for (const ch of expr) {
      if (ch === "(" || ch === "[" || ch === "{") st.push(ch);
      else if (ch in pairs) {
        if (st.pop() !== pairs[ch]) return false;
      }
    }
    return st.isEmpty();
  }
  console.log("balanced '{[()]}' :", isBalanced("{[()]}")); // true
  console.log("balanced '{[(])}'  :", isBalanced("{[(])}"));  // false
}

function demoHeap(): void {
  console.log("\n=== HEAP DEMO ===");

  // Min-heap
  const minH = Heap.min(5, 3, 8, 1, 9, 2);
  console.log("min peek:", minH.peek()); // 1
  console.log("extracts (min):", [...Array(6)].map(() => minH.extract()));
  // [1,2,3,5,8,9]

  // Max-heap
  const maxH = Heap.max(5, 3, 8, 1, 9, 2);
  console.log("max peek:", maxH.peek()); // 9
  console.log("extracts (max):", [...Array(6)].map(() => maxH.extract()));
  // [9,8,5,3,2,1]

  // Custom comparator: heap of objects by priority (lower number = higher priority)
  interface Task { name: string; priority: number; }
  const taskHeap = new Heap<Task>((a, b) => a.priority - b.priority);
  taskHeap.insertAll([
    { name: "email", priority: 3 },
    { name: "deploy", priority: 1 },
    { name: "review", priority: 2 },
  ]);
  console.log("\nTask scheduling (by priority):");
  while (!taskHeap.isEmpty()) {
    console.log("  ", taskHeap.extract()!.name);
  }
  // deploy, review, email

  // Build from array in O(n)
  const h = Heap.from([4, 10, 3, 5, 1], (a, b) => a - b);
  console.log("\nbuilt min-heap peek:", h.peek()); // 1

  // Heap sort
  const unsorted = [7, 2, 9, 4, 1, 8, 3];
  console.log("heapSortAsc:", heapSortAsc(unsorted)); // [1,2,3,4,7,8,9]
  console.log("original unchanged:", unsorted);

  // Iteration in priority order (non-destructive)
  const h2 = Heap.min(4, 1, 7, 3);
  console.log("iterate min-heap:", [...h2]); // [1,3,4,7]
  console.log("size after iterate:", h2.size); // unchanged
}

function main(): void {
  demoStack();
  demoHeap();
  console.log("\nAll demos completed.");
}

main();
```

### Design notes

- **Stack** uses a plain `T[]` and `push`/`pop` (O(1) amortized). Iteration is top→bottom, which is the most natural order for a stack.
- **Heap** is a binary heap stored in an array. `siftUp`/`siftDown` give O(log n) insert/extract; `build` heapifies in O(n). The comparator makes it reusable for min, max, or custom priorities (e.g. tasks by priority).
- `extract()` on an empty heap returns `undefined` rather than throwing — convenient for draining loops. Change to `throw` if you prefer strict semantics.
- `toSorted()` / `[Symbol.iterator]` work on a copy, so iterating never mutates the heap.
- `heapSortAsc` shows the canonical “build heap then repeatedly extract” pattern.

