# Stacks and Queues in TypeScript

Below is a complete, runnable example. It includes:

- A generic `Stack<T>` (array-backed, O(1) push/pop)
- A generic `Queue<T>` (head-pointer backed, amortized O(1) enqueue/dequeue with compaction)
- Interfaces so you can swap implementations
- A bonus `Deque<T>` (double-ended queue)
- A demo with assertions

Save as `stacks-queues.ts` and run with `npx ts-node stacks-queues.ts` (or compile with `tsc`).

```ts
// ============================================================
// stacks-queues.ts
// ============================================================

// ---------------- Interfaces ----------------

export interface IStack<T> {
  push(item: T): this;
  pop(): T | undefined;
  peek(): T | undefined;
  isEmpty(): boolean;
  size(): number;
  clear(): void;
  toArray(): T[];
}

export interface IQueue<T> {
  enqueue(item: T): this;
  dequeue(): T | undefined;
  peek(): T | undefined;       // front element
  isEmpty(): boolean;
  size(): number;
  clear(): void;
  toArray(): T[];
}

// ---------------- Stack ----------------

export class Stack<T> implements IStack<T> {
  private items: T[] = [];

  push(item: T): this {
    this.items.push(item);
    return this;
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  /** Pop and throw if empty (strict variant). */
  popOrThrow(): T {
    const v = this.items.pop();
    if (v === undefined && this.items.length === 0) {
      // Note: undefined could be a legitimate stored value; guard by length first.
    }
    if (this.items.length === 0 && v === undefined) {
      throw new Error("Stack underflow: cannot pop from empty stack");
    }
    return v as T;
  }

  peek(): T | undefined {
    return this.items.length === 0 ? undefined : this.items[this.items.length - 1];
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  size(): number {
    return this.items.length;
  }

  clear(): void {
    this.items.length = 0;
  }

  toArray(): T[] {
    return [...this.items];
  }

  [Symbol.iterator](): Iterator<T> {
    // Iterate from top to bottom (LIFO order of removal).
    let i = this.items.length;
    return {
      next: (): IteratorResult<T> => {
        if (i <= 0) return { value: undefined as any, done: true };
        i--;
        return { value: this.items[i], done: false };
      },
    };
  }

  toString(): string {
    return `Stack(${this.items.length}) [${this.items.map(String).join(", ")}]`;
  }
}

// ---------------- Queue (head pointer + compaction) ----------------

export class Queue<T> implements IQueue<T> {
  private items: T[] = [];
  private head = 0; // index of the logical front

  enqueue(item: T): this {
    this.items.push(item);
    return this;
  }

  dequeue(): T | undefined {
    if (this.head >= this.items.length) return undefined;

    const value = this.items[this.head];
    this.head++;

    // Compact when wasted space exceeds half the buffer.
    if (this.head > 0 && this.head * 2 >= this.items.length) {
      this.items = this.items.slice(this.head);
      this.head = 0;
    }
    return value;
  }

  peek(): T | undefined {
    return this.head >= this.items.length ? undefined : this.items[this.head];
  }

  isEmpty(): boolean {
    return this.head >= this.items.length;
  }

  size(): number {
    return this.items.length - this.head;
  }

  clear(): void {
    this.items = [];
    this.head = 0;
  }

  toArray(): T[] {
    return this.items.slice(this.head);
  }

  [Symbol.iterator](): Iterator<T> {
    let i = this.head;
    const items = this.items;
    const end = items.length;
    return {
      next: (): IteratorResult<T> => {
        if (i >= end) return { value: undefined as any, done: true };
        return { value: items[i++], done: false };
      },
    };
  }

  toString(): string {
    return `Queue(${this.size()}) [${this.toArray().map(String).join(", ")}]`;
  }
}

// ---------------- Deque (double-ended queue) ----------------

export class Deque<T> {
  private items: T[] = [];
  private head = 0;

  pushFront(item: T): this { this.items.unshift(item); return this; } // O(n); see note
  pushBack(item: T): this  { this.items.push(item); return this; }
  popFront(): T | undefined {
    if (this.head >= this.items.length) return undefined;
    // keep simple: use array shift on compacted view
    const v = this.items[this.head];
    this.head++;
    if (this.head * 2 >= this.items.length) {
      this.items = this.items.slice(this.head);
      this.head = 0;
    }
    return v;
  }
  popBack(): T | undefined { return this.items.pop(); }

  peekFront(): T | undefined {
    return this.head >= this.items.length ? undefined : this.items[this.head];
  }
  peekBack(): T | undefined {
    return this.items.length === 0 ? undefined : this.items[this.items.length - 1];
  }
  isEmpty(): boolean { return this.head >= this.items.length && this.items.length === 0 || this.head >= this.items.length; }
  size(): number { return this.items.length - this.head; }
  clear(): void { this.items = []; this.head = 0; }
  toArray(): T[] { return this.items.slice(this.head); }
}

// ---------------- Circular-buffer Queue (strict O(1)) ----------------

export class CircularQueue<T> implements IQueue<T> {
  private buffer: (T | undefined)[];
  private capacity: number;
  private head = 0;
  private tail = 0;
  private count = 0;

  constructor(capacity: number) {
    if (capacity <= 0) throw new Error("capacity must be > 0");
    this.capacity = capacity;
    this.buffer = new Array(capacity);
  }

  enqueue(item: T): this {
    if (this.count === this.capacity) throw new Error("Queue is full");
    this.buffer[this.tail] = item;
    this.tail = (this.tail + 1) % this.capacity;
    this.count++;
    return this;
  }

  dequeue(): T | undefined {
    if (this.count === 0) return undefined;
    const value = this.buffer[this.head];
    this.buffer[this.head] = undefined;
    this.head = (this.head + 1) % this.capacity;
    this.count--;
    return value;
  }

  peek(): T | undefined {
    return this.count === 0 ? undefined : this.buffer[this.head];
  }

  isEmpty(): boolean { return this.count === 0; }
  size(): number { return this.count; }
  clear(): void { this.buffer.fill(undefined); this.head = 0; this.tail = 0; this.count = 0; }
  toArray(): T[] {
    const out: T[] = [];
    for (let i = 0; i < this.count; i++) {
      out.push(this.buffer[(this.head + i) % this.capacity] as T);
    }
    return out;
  }
}

// ---------------- Demo / self-test ----------------

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error("ASSERT FAILED: " + msg);
}

function demoStack(): void {
  const s = new Stack<number>();
  assert(s.isEmpty(), "stack empty initially");
  s.push(1).push(2).push(3);
  assert(s.size() === 3, "size 3");
  assert(s.peek() === 3, "peek 3");
  assert(s.pop() === 3, "pop 3");
  assert(s.pop() === 2, "pop 2");
  assert(s.pop() === 1, "pop 1");
  assert(s.pop() === undefined, "pop empty -> undefined");
  assert(s.isEmpty(), "empty after pops");

  // LIFO iteration
  const s2 = new Stack<string>();
  s2.push("a").push("b").push("c");
  const popped: string[] = [];
  for (const v of s2) popped.push(v);
  assert(popped.join(",") === "c,b,a", "iterator top->bottom");

  // storing undefined legitimately
  const s3 = new Stack<number | undefined>();
  s3.push(undefined);
  assert(s3.size() === 1, "undefined stored");
  assert(s3.pop() === undefined && s3.size() === 0, "pop undefined works");

  console.log("Stack OK:", s2.toString());
}

function demoQueue(): void {
  const q = new Queue<string>();
  assert(q.isEmpty(), "queue empty");
  q.enqueue("a").enqueue("b").enqueue("c");
  assert(q.size() === 3, "size 3");
  assert(q.peek() === "a", "peek a");
  assert(q.dequeue() === "a", "dequeue a");
  assert(q.dequeue() === "b", "dequeue b");
  assert(q.dequeue() === "c", "dequeue c");
  assert(q.dequeue() === undefined, "dequeue empty");
  assert(q.isEmpty(), "empty");

  // FIFO iteration
  const q2 = new Queue<number>();
  q2.enqueue(1).enqueue(2).enqueue(3);
  const out: number[] = [];
  for (const v of q2) out.push(v);
  assert(out.join(",") === "1,2,3", "iterator FIFO");

  // compaction keeps memory bounded
  const q3 = new Queue<number>();
  for (let i = 0; i < 1000; i++) q3.enqueue(i);
  for (let i = 0; i < 999; i++) q3.dequeue();
  assert(q3.size() === 1 && q3.peek() === 999, "compaction keeps tail");
  console.log("Queue OK:", q2.toString());
}

function demoDeque(): void {
  const d = new Deque<number>();
  d.pushBack(2).pushFront(1).pushBack(3);
  assert(d.toArray().join(",") === "1,2,3", "deque order");
  assert(d.popFront() === 1, "popFront");
  assert(d.popBack() === 3, "popBack");
  assert(d.peekFront() === 2 && d.peekBack() === 2, "single element");
  console.log("Deque OK:", d.toArray().join(","));
}

function demoCircular(): void {
  const cq = new CircularQueue<number>(3);
  cq.enqueue(1).enqueue(2).enqueue(3);
  let threw = false;
  try { cq.enqueue(4); } catch { threw = true; }
  assert(threw, "circular full throws");
  assert(cq.dequeue() === 1, "dequeue 1");
  cq.enqueue(4);
  assert(cq.toArray().join(",") === "2,3,4", "wrap-around");
  console.log("CircularQueue OK:", cq.toString?.() ?? cq.toArray().join(","));
}

function main(): void {
  demoStack();
  demoQueue();
  demoDeque();
  demoCircular();
  console.log("\nAll demos passed.");
}

main();
```

## Design notes

- **Stack** is a thin wrapper over `Array` with `push`/`pop` at the end — true O(1) amortized per operation.
- **Queue** uses a *head pointer* instead of `Array.shift()` (which is O(n)). Periodic *compaction* (`slice`) reclaims memory; cost is amortized O(1) per dequeue. Wasted space never exceeds ~2× live size.
- **CircularQueue** gives strict O(1) enqueue/dequeue with a fixed capacity — the right choice when you need predictable latency (e.g., bounded buffers, ring buffers).
- **Deque** above uses `unshift` for `pushFront`, which is O(n). For a production deque, use a doubly-linked list or a chunked (unrolled) deque. I kept it simple for clarity.
- Returning `this` from mutators enables chaining (`s.push(1).push(2)`).
- `pop()`/`dequeue()` return `undefined` on empty rather than throwing — friendlier for control flow; use `popOrThrow`-style helpers if you prefer strictness.
- Iterators yield in natural removal order: stack top→bottom, queue front→back.

## Complexity summary

| Operation | Stack | Queue (head ptr) | CircularQueue |
|-----------|-------|------------------|---------------|
| push/enqueue | O(1) amortized | O(1) amortized | O(1) |
| pop/dequeue  | O(1) | O(1) amortized | O(1) |
| peek         | O(1) | O(1) | O(1) |
| size/isEmpty | O(1) | O(1) | O(1) |

# Stacks and Queues in TypeScript

## The core idea

- **Stack** — *Last-In, First-Out (LIFO)*.  
  You push items on top and pop items from the top. Think of a stack of plates: the last plate you put on is the first one you take off.

- **Queue** — *First-In, First-Out (FIFO)*.  
  You enqueue items at the back and dequeue them from the front. Think of a line at a checkout: the first person in line is the first served.

Both are abstract data types: the *interface* (push/pop, enqueue/dequeue) matters more than the underlying storage.

---

## Stack in TypeScript

### Basic idea and syntax

The simplest stack in JS/TS is just an array used with `push` and `pop`:

```ts
const stack: number[] = [];

stack.push(1);
stack.push(2);
stack.push(3);

console.log(stack.pop()); // 3  (LIFO)
console.log(stack.pop()); // 2
console.log(stack);      // [1]
```

A reusable, typed stack class:

```ts
class Stack<T> {
  private items: T[] = [];

  push(item: T): void {
    this.items.push(item);
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  get size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  clear(): void {
    this.items.length = 0;
  }
}

const s = new Stack<string>();
s.push("a");
s.push("b");
console.log(s.peek()); // "b"
console.log(s.pop());  // "b"
console.log(s.size);   // 1
```

### Performance note

`push` and `pop` on a JS array are **O(1) amortized**, so an array-backed stack is efficient and idiomatic.

---

## Queue in TypeScript

### The naive (but slow) way

Using an array with `push` + `shift` works, but `shift()` is **O(n)** because it reindexes every element:

```ts
const q: number[] = [];
q.push(1);
q.push(2);
console.log(q.shift()); // 1  (FIFO)  -- O(n) cost
```

### Efficient queue with a head pointer

A common TS pattern keeps a head index and only occasionally trims the backing array:

```ts
class Queue<T> {
  private items: T[] = [];
  private head = 0;

  enqueue(item: T): void {
    this.items.push(item);
  }

  dequeue(): T | undefined {
    if (this.head >= this.items.length) return undefined;
    const value = this.items[this.head++];
    // Periodically compact to avoid unbounded growth of the backing array
    if (this.head > 1024 && this.head * 2 >= this.items.length) {
      this.items = this.items.slice(this.head);
      this.head = 0;
    }
    return value;
  }

  peek(): T | undefined {
    return this.items[this.head];
  }

  get size(): number {
    return this.items.length - this.head;
  }

  isEmpty(): boolean {
    return this.size === 0;
  }
}

const q = new Queue<number>();
q.enqueue(10);
q.enqueue(20);
q.enqueue(30);
console.log(q.dequeue()); // 10
console.log(q.peek());     // 20
console.log(q.size);       // 2
```

### Alternative: two-stack queue (amortized O(1))

```ts
class TwoStackQueue<T> {
  private inStack: T[] = [];
  private outStack: T[] = [];

  enqueue(item: T): void {
    this.inStack.push(item);
  }

  dequeue(): T | undefined {
    if (this.outStack.length === 0) {
      while (this.inStack.length) {
        this.outStack.push(this.inStack.pop()!);
      }
    }
    return this.outStack.pop();
  }

  peek(): T | undefined {
    if (this.outStack.length === 0) {
      while (this.inStack.length) {
        this.outStack.push(this.inStack.pop()!);
      }
    }
    return this.outStack[this.outStack.length - 1];
  }

  isEmpty(): boolean {
    return this.inStack.length === 0 && this.outStack.length === 0;
  }
}
```

For most app code the head-pointer version is simpler and fast enough; the two-stack version shines when you need strict amortized O(1) and avoid slicing.

---

## Typical use cases

### Stacks

| Use case | Why a stack fits |
|---|---|
| **Undo / redo** | Each action is pushed; undo pops the last action. |
| **Expression evaluation / parsing** | Parentheses matching, postfix (RPN) evaluation, AST traversal. |
| **DFS (depth-first search)** | Explicit stack replaces recursion or controls traversal order. |
| **Backtracking** | Push choices, pop on failure (N-queens, maze solving). |
| **Call stack (runtime)** | Function calls are pushed/popped by the engine. |
| **Browser history (back)** | Back button pops the previous page. |

Undo example:

```ts
class TextEditor {
  private content = "";
  private history: string[] = [];

  type(text: string): void {
    this.history.push(this.content);
    this.content += text;
  }

  undo(): void {
    const prev = this.history.pop();
    if (prev !== undefined) this.content = prev;
  }

  get text(): string {
    return this.content;
  }
}

const ed = new TextEditor();
ed.type("Hello");
ed.type(" World");
console.log(ed.text); // "Hello World"
ed.undo();
console.log(ed.text); // "Hello"
```

Parentheses checker (classic stack problem):

```ts
function isBalanced(s: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };

  for (const ch of s) {
    if (ch === "(" || ch === "[" || ch === "{") {
      stack.push(ch);
    } else if (ch in pairs) {
      if (stack.pop() !== pairs[ch]) return false;
    }
  }
  return stack.length === 0;
}

console.log(isBalanced("{[()]}")); // true
console.log(isBalanced("{[(])}")); // false
```

### Queues

| Use case | Why a queue fits |
|---|---|
| **BFS (breadth-first search)** | Process nodes level by level. |
| **Task / job scheduling** | FIFO fairness; worker pulls next job. |
| **Message queues / event buffering** | Decouple producers and consumers. |
| **Rate limiting / throttling** | Track requests in a sliding window. |
| **Print spooling / I/O buffering** | Serve requests in arrival order. |
| **Async task queues** | Promises/microtasks conceptually use queues. |

BFS example:

```ts
interface GraphNode {
  id: string;
  neighbors: string[];
}

function bfs(start: string, graph: Map<string, string[]>): string[] {
  const visited = new Set<string>();
  const q = new Queue<string>();
  const order: string[] = [];

  q.enqueue(start);
  visited.add(start);

  while (!q.isEmpty()) {
    const node = q.dequeue()!;
    order.push(node);
    for (const next of graph.get(node) ?? []) {
      if (!visited.has(next)) {
        visited.add(next);
        q.enqueue(next);
      }
    }
  }
  return order;
}

const g = new Map<string, string[]>([
  ["A", ["B", "C"]],
  ["B", ["D"]],
  ["C", ["D"]],
  ["D", []],
]);
console.log(bfs("A", g)); // ["A", "B", "C", "D"]
```

Sliding-window rate limiter (queue of timestamps):

```ts
class RateLimiter {
  private timestamps: number[] = [];
  private readonly windowMs: number;
  private readonly max: number;

  constructor(windowMs: number, max: number) {
    this.windowMs = windowMs;
    this.max = max;
  }

  allow(): boolean {
    const now = Date.now();
    // drop old timestamps (FIFO)
    while (this.timestamps.length && now - this.timestamps[0] > this.windowMs) {
      this.timestamps.shift();
    }
    if (this.timestamps.length < this.max) {
      this.timestamps.push(now);
      return true;
    }
    return false;
  }
}
```

(For high throughput, replace the array with the head-pointer queue above.)

---

## Deque (double-ended queue)

When you need push/pop on **both** ends, use a deque. JS arrays support this with `push`/`pop` (right) and `unshift`/`shift` (left), but `unshift`/`shift` are O(n). For heavy use, use a linked list or a library.

```ts
class Deque<T> {
  private items: T[] = [];
  private head = 0;

  pushFront(item: T): void { this.items.unshift(item); } // simple, O(n)
  pushBack(item: T): void { this.items.push(item); }
  popFront(): T | undefined { return this.head < this.items.length ? this.items[this.head++] : this.items.shift(); }
  popBack(): T | undefined { return this.items.pop(); }
}
```

For production, prefer a well-tested library (e.g. `double-ended-queue`) or a circular buffer.

---

## TypeScript tips

1. **Generics** (`Stack<T>`, `Queue<T>`) give type safety and reuse.
2. **Return `T | undefined`** for pop/dequeue to model empty containers without throwing.
3. **Prefer interfaces** when you want to swap implementations:
   ```ts
   interface QueueLike<T> {
     enqueue(item: T): void;
     dequeue(): T | undefined;
     peek(): T | undefined;
     isEmpty(): boolean;
   }
   ```
4. **Don't mutate shared state** unexpectedly; keep storage `private`.
5. **Measure** if performance matters: `shift`/`unshift` are O(n); use head-pointer queues or linked lists for large data.

---

## Summary

- **Stack = LIFO**: `push`/`pop` on top; array-backed, O(1). Great for undo, parsing, DFS, backtracking.
- **Queue = FIFO**: `enqueue` at back, `dequeue` at front; prefer head-pointer or two-stack implementations over `shift()` for performance. Great for BFS, scheduling, buffering, rate limiting.
- In TS, wrap them in generic classes with safe `T | undefined` returns and clear interfaces, and choose the backing structure based on expected size and operation mix.

A common mistake is accidentally giving a **queue** stack (LIFO) behavior by using the wrong array method.

### Mistaken version

```ts
class SimpleQueue<T> {
  private items: T[] = [];

  enqueue(item: T): void {
    this.items.push(item);
  }

  dequeue(): T | undefined {
    // Mistake: pop() removes from the END, making this LIFO
    return this.items.pop();
  }
}

const q = new SimpleQueue<number>();
q.enqueue(1);
q.enqueue(2);
q.enqueue(3);

console.log(q.dequeue()); // 3, but a queue should return 1
console.log(q.dequeue()); // 2
console.log(q.dequeue()); // 1
```

### Corrected version

```ts
class SimpleQueue<T> {
  private items: T[] = [];

  enqueue(item: T): void {
    this.items.push(item);
  }

  dequeue(): T | undefined {
    // Correct: shift() removes from the FRONT, making this FIFO
    return this.items.shift();
  }
}

const q = new SimpleQueue<number>();
q.enqueue(1);
q.enqueue(2);
q.enqueue(3);

console.log(q.dequeue()); // 1
console.log(q.dequeue()); // 2
console.log(q.dequeue()); // 3
```

### What was wrong and why

- A **queue** is **FIFO**: First In, First Out.
- `push()` adds to the end of the array.
- `pop()` removes from the end of the array, so `push` + `pop` creates **LIFO** behavior, which is a **stack**, not a queue.
- `shift()` removes from the beginning of the array, so `push` + `shift` creates correct **FIFO** behavior.

The reverse mistake can happen with stacks too: using `shift()` instead of `pop()` makes a stack behave like a queue.

### Practical note

`Array.prototype.shift()` works correctly but is **O(n)** because every remaining element must move down one index. For small cases this is fine, but for large or performance-sensitive queues, a better approach is to keep a `head` index:

```ts
class EfficientQueue<T> {
  private items: T[] = [];
  private head = 0;

  enqueue(item: T): void {
    this.items.push(item);
  }

  dequeue(): T | undefined {
    if (this.head >= this.items.length) {
      return undefined;
    }

    const value = this.items[this.head];
    this.head += 1;

    // Occasionally compact the array to avoid unbounded growth
    if (this.head > 1000 && this.head * 2 >= this.items.length) {
      this.items = this.items.slice(this.head);
      this.head = 0;
    }

    return value;
  }
}
```

This keeps dequeue fast while still preserving FIFO order.

Below are the most common pitfalls when working with stacks and queues in TypeScript, with concrete code showing the problem and the better approach.

---

## 1. Using `Array.prototype.shift()` for a queue (O(n) removal)

Arrays in JS/TS are dynamic arrays. `shift()` removes the first element and re-indexes everything, so each dequeue is **O(n)**.

**Pitfall**

```ts
const queue: number[] = [];

queue.push(1);
queue.push(2);
queue.push(3);

const first = queue.shift(); // O(n) — reindexes 2,3
console.log(first, queue);   // 1, [2,3]
```

**Better**

Use a linked-list–based queue, or a head-indexed buffer:

```ts
class Queue<T> {
  private buf: (T | undefined)[] = [];
  private head = 0;
  private tail = 0;

  enqueue(v: T) { this.buf[this.tail++] = v; }
  dequeue(): T | undefined {
    if (this.head === this.tail) return undefined;
    const v = this.buf[this.head];
    this.buf[this.head++] = undefined; // help GC
    if (this.head === this.tail) { this.head = this.tail = 0; this.buf.length = 0; }
    return v;
  }
  size() { return this.tail - this.head; }
}
```

---

## 2. Ignoring that `pop()` / `shift()` return `T | undefined`

TypeScript’s lib types reflect reality: popping an empty container yields `undefined`. Code that assumes a value often crashes at runtime.

**Pitfall**

```ts
const stack: number[] = [];
const top = stack.pop();     // type: number | undefined
console.log(top + 1);        // TS error, and runtime NaN if bypassed
// @ts-ignore
console.log((top as number) + 1); // runtime crash
```

**Better**

Narrow or default:

```ts
const top = stack.pop();
if (top === undefined) {
  throw new Error("stack underflow");
}
console.log(top + 1);

// or
const top2 = stack.pop() ?? 0;
```

---

## 3. Mutating a stack/queue while iterating

Iterating over the underlying array while pushing/popping changes indices and skips elements.

**Pitfall**

```ts
const stack = [1, 2, 3, 4];

// Remove all even numbers
for (const x of stack) {
  if (x % 2 === 0) stack.splice(stack.indexOf(x), 1);
}
console.log(stack); // [1, 3, 4] — 4 skipped!
```

**Better**

Iterate over a snapshot, or build a new collection:

```ts
const stack = [1, 2, 3, 4];
const next = stack.filter(x => x % 2 !== 0);
console.log(next); // [1, 3]
```

---

## 4. Memory leak with a “head pointer” queue

A common optimized queue keeps `head`/`tail` indices but never trims. The backing array grows forever even after dequeues.

**Pitfall**

```ts
class LeakyQueue<T> {
  private a: (T | undefined)[] = [];
  private head = 0;
  private tail = 0;
  enqueue(v: T) { this.a[this.tail++] = v; }
  dequeue() { return this.a[this.head++]; } // head grows; array never shrinks
}
```

After 1M enqueues/dequeues, `a.length` is still ~1M.

**Better**

Reset and compact when empty, or slice compact periodically:

```ts
dequeue(): T | undefined {
  if (this.head === this.tail) return undefined;
  const v = this.a[this.head];
  this.a[this.head++] = undefined;
  if (this.head === this.tail) {
    this.head = 0; this.tail = 0; this.a.length = 0;
  } else if (this.head > 1024 && this.head > this.tail / 2) {
    this.a = this.a.slice(this.head);
    this.tail -= this.head;
    this.head = 0;
  }
  return v;
}
```

---

## 5. Confusing LIFO and FIFO (push/pop vs push/shift)

Beginners often mix stack and queue semantics, e.g. `push` + `shift` (queue) but call it a stack, or `unshift` + `pop`.

**Pitfall**

```ts
const data: number[] = [];
data.push(1); data.push(2); data.push(3);

// Intended stack (LIFO), but used FIFO:
const wrong = data.shift(); // 1, not 3
```

**Better**

Name operations explicitly and keep invariants:

```ts
class Stack<T> {
  private a: T[] = [];
  push(v: T) { this.a.push(v); }
  pop() { return this.a.pop(); }   // LIFO
  peek() { return this.a[this.a.length - 1]; }
}

class Queue<T> {
  private a: T[] = [];
  enqueue(v: T) { this.a.push(v); }
  dequeue() { return this.a.shift(); } // FIFO (small queues only)
}
```

---

## 6. Async task queues without backpressure

Pushing async work into an array and “processing later” without awaiting can cause unbounded memory growth and unhandled rejections.

**Pitfall**

```ts
const taskQueue: (() => Promise<void>)[] = [];

function addTask(fn: () => Promise<void>) {
  taskQueue.push(fn); // unbounded
}

setInterval(() => {
  const t = taskQueue.shift();
  t?.(); // fire-and-forget; errors lost
}, 10);
```

**Better**

Use a bounded async queue with concurrency control:

```ts
class AsyncQueue {
  private q: (() => Promise<void>)[] = [];
  private running = 0;
  constructor(private concurrency = 2, private max = 100) {}

  async add(fn: () => Promise<void>) {
    if (this.q.length >= this.max) throw new Error("queue full");
    this.q.push(fn);
    this.pump();
  }

  private async pump() {
    while (this.running < this.concurrency && this.q.length) {
      const fn = this.q.shift()!;
      this.running++;
      fn()
        .catch(err => console.error("task error", err))
        .finally(() => { this.running--; this.pump(); });
    }
  }
}
```

---

## 7. Storing references without copying (shared mutable state)

Stacks/queues of objects store references. Popping and mutating the returned object mutates the original if it’s still referenced elsewhere.

**Pitfall**

```ts
type User = { name: string };
const q: User[] = [{ name: "Ada" }];
const u = q.shift()!; // same reference
u.name = "Grace";
// original object (if still referenced elsewhere) changed
```

**Better**

Clone on enqueue or dequeue depending on ownership:

```ts
function enqueueCopy<T>(q: T[], v: T) {
  q.push(structuredClone(v));
}
```

Or document that the queue owns the object and callers must not retain references.

---

## 8. Off-by-one errors in circular buffers

Ring buffers are great, but index math (`(i + 1) % cap`) and full-vs-empty ambiguity (head==tail) bite people.

**Pitfall**

```ts
class Ring<T> {
  private a: (T | undefined)[] = new Array(4);
  private h = 0, t = 0, n = 4;
  push(v: T) {
    this.a[this.t] = v;
    this.t = (this.t + 1) % this.n;
    if (this.t === this.h) this.h = (this.h + 1) % this.n; // drops silently
  }
  pop(): T | undefined {
    if (this.h === this.t) return undefined; // empty? or full? ambiguous
    const v = this.a[this.h];
    this.h = (this.h + 1) % this.n;
    return v;
  }
}
```

**Better**

Track size explicitly to remove ambiguity:

```ts
class Ring<T> {
  private a: (T | undefined)[];
  private h = 0, t = 0, size = 0;
  constructor(private cap: number) { this.a = new Array(cap); }

  push(v: T) {
    if (this.size === this.cap) throw new Error("full");
    this.a[this.t] = v;
    this.t = (this.t + 1) % this.cap;
    this.size++;
  }

  pop(): T | undefined {
    if (this.size === 0) return undefined;
    const v = this.a[this.h];
    this.a[this.h] = undefined;
    this.h = (this.h + 1) % this.cap;
    this.size--;
    return v;
  }
}
```

---

## 9. Recursive DFS causing stack overflow instead of an explicit stack

Deep graphs/lists can overflow the JS call stack. An explicit stack avoids that.

**Pitfall**

```ts
function dfs(node: Node | null) {
  if (!node) return;
  console.log(node.val);
  dfs(node.left);   // deep recursion → RangeError on large trees
  dfs(node.right);
}
```

**Better**

Use an explicit stack:

```ts
function dfs(root: Node | null) {
  const stack: Node[] = [];
  if (root) stack.push(root);
  while (stack.length) {
    const n = stack.pop()!;
    console.log(n.val);
    if (n.right) stack.push(n.right);
    if (n.left) stack.push(n.left);
  }
}
```

---

## 10. Generic ambiguity with `T | undefined`

If your stack type is `Stack<number | undefined>`, then `pop()` returns `(number | undefined) | undefined`, making “empty” indistinguishable from a stored `undefined`.

**Pitfall**

```ts
const s = new Stack<number | undefined>();
s.push(undefined);
const v = s.pop(); // (number | undefined) | undefined — was it empty?
```

**Better**

Keep `undefined` out of the element type; use a sentinel or `Result`:

```ts
class Stack<T> {
  private a: T[] = [];
  push(v: T) { this.a.push(v); }
  pop(): T | undefined { return this.a.pop(); } // only undefined means empty
}

// If you genuinely need optional values, store a wrapper:
type Cell<T> = { value: T | undefined; present: boolean };
```

---

## 11. Priority queues implemented with `Array.prototype.sort()`

Sorting on every insert is O(n log n) per operation; for many items it’s slow. Use a binary heap.

**Pitfall**

```ts
const pq: number[] = [];
function insert(x: number) {
  pq.push(x);
  pq.sort((a, b) => a - b); // O(n log n) each
}
```

**Better**

Use a heap (min-heap example):

```ts
class MinHeap {
  private a: number[] = [];
  push(x: number) {
    this.a.push(x);
    let i = this.a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.a[p] <= this.a[i]) break;
      [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
      i = p;
    }
  }
  pop(): number | undefined {
    if (!this.a.length) return undefined;
    const top = this.a[0];
    const last = this.a.pop()!;
    if (this.a.length) {
      this.a[0] = last;
      let i = 0;
      while (true) {
        let s = i;
        const l = 2 * i + 1, r = 2 * i + 2;
        if (l < this.a.length && this.a[l] < this.a[s]) s = l;
        if (r < this.a.length && this.a[r] < this.a[s]) s = r;
        if (s === i) break;
        [this.a[i], this.a[s]] = [this.a[s], this.a[i]];
        i = s;
      }
    }
    return top;
  }
}
```

---

## 12. Forgetting to handle “peek” vs “pop”

Many bugs come from consuming an element when only inspection was intended.

**Pitfall**

```ts
const stack = [1, 2, 3];
if (stack[stack.length - 1] > 2) {
  // intended to just check, but later code calls pop()
}
const v = stack.pop(); // now consumed; logic breaks
```

**Better**

Provide and use `peek()` separately; never overload pop with inspection:

```ts
class Stack<T> {
  private a: T[] = [];
  push(v: T) { this.a.push(v); }
  pop() { return this.a.pop(); }
  peek() { return this.a[this.a.length - 1]; } // non-mutating
  isEmpty() { return this.a.length === 0; }
}
```

---

### Quick checklist

- Prefer O(1) enqueue/dequeue (linked list or head+tail buffer).
- Always treat `pop()`/`dequeue()` as possibly `undefined`.
- Don’t mutate while iterating; build new arrays.
- Compact or reset long-lived queues to avoid leaks.
- Keep `undefined` out of element types.
- Use explicit stacks for deep traversal.
- Use heaps for priority queues.
- Separate `peek` from `pop`.

If you want, I can also provide a complete, production-ready `Stack` and `Queue` implementation in TypeScript with tests.

## Exercise

**Build a `PrintManager` in TypeScript** that combines a **queue** (pending documents, FIFO) and a **stack** (recently printed documents, LIFO for undo):

- `enqueue(doc)` — add a document to the end of the pending queue.
- `processNext()` — dequeue and “print” the next document; push it onto the printed stack.
- `undoLastPrint()` — pop the last printed document and put it back at the **front** of the pending queue (so it prints next).
- `peekPending()` / `peekPrinted()` — inspection helpers.
- Handle empty cases gracefully (return `undefined` / throw? We'll return `undefined` for peeks and `false` for failed ops).

---

## Step-by-step solution

### 1. Choose underlying structures
- Pending docs need **FIFO** → use an array as a queue with `push` (enqueue) and `shift` (dequeue).  
  (For large scale you’d use a linked list / deque; array is fine for teaching.)
- Printed history needs **LIFO undo** → use an array as a stack with `push` / `pop`.

### 2. Define types
```ts
type Doc = { id: string; title: string };
```

### 3. Implement the class
Key invariants:
- A document is either *pending* or *printed*, never both.
- `undoLastPrint` moves from stack → front of queue (unshift), preserving FIFO for the rest.

### 4. Edge cases
- `processNext` on empty queue → return `undefined`.
- `undoLastPrint` on empty stack → return `undefined`.
- `enqueue` always succeeds.

### 5. Complexity (array-based)
- `enqueue`: O(1) amortized
- `processNext`: O(n) due to `shift` (queue dequeue). For production use a real deque.
- `undoLastPrint`: O(n) due to `unshift`.

---

## Final solution

```ts
// print-manager.ts

export type Doc = { id: string; title: string };

export class PrintManager {
  private pending: Doc[] = [];   // queue: FIFO (front = index 0)
  private printed: Doc[] = [];   // stack: LIFO (top = last index)

  /** Add a document to the end of the pending queue. */
  enqueue(doc: Doc): void {
    this.pending.push(doc);
  }

  /** Print (dequeue) the next pending document. Returns it, or undefined if none. */
  processNext(): Doc | undefined {
    if (this.pending.length === 0) return undefined;
    const doc = this.pending.shift()!;   // dequeue from front
    this.printed.push(doc);              // push onto stack
    return doc;
  }

  /** Undo the last print: move it back to the FRONT of the pending queue. */
  undoLastPrint(): Doc | undefined {
    if (this.printed.length === 0) return undefined;
    const doc = this.printed.pop()!;     // pop from stack
    this.pending.unshift(doc);            // enqueue at front
    return doc;
  }

  /** Peek at the next document to be printed (front of queue). */
  peekPending(): Doc | undefined {
    return this.pending[0];
  }

  /** Peek at the last printed document (top of stack). */
  peekPrinted(): Doc | undefined {
    return this.printed[this.printed.length - 1];
  }

  get pendingCount(): number { return this.pending.length; }
  get printedCount(): number { return this.printed.length; }
}

// ---------- Demo / quick tests ----------
if (require.main === module) {
  const pm = new PrintManager();

  pm.enqueue({ id: "1", title: "Resume.pdf" });
  pm.enqueue({ id: "2", title: "CoverLetter.pdf" });
  pm.enqueue({ id: "3", title: "Portfolio.pdf" });

  console.log("peek pending:", pm.peekPending()?.title); // Resume.pdf

  console.log("printed:", pm.processNext()?.title);     // Resume.pdf
  console.log("printed:", pm.processNext()?.title);     // CoverLetter.pdf

  console.log("undo:", pm.undoLastPrint()?.title);      // CoverLetter.pdf
  console.log("next pending:", pm.peekPending()?.title); // CoverLetter.pdf (moved to front)

  console.log("printed count:", pm.printedCount);       // 1
  console.log("pending count:", pm.pendingCount);       // 2
}
```

### How the two structures cooperate
- **Queue (`pending`)** guarantees documents print in arrival order.
- **Stack (`printed`)** guarantees “undo” always reverses the most recent print, not an arbitrary one.
- Combining them gives a small but realistic workflow: FIFO scheduling + LIFO undo, which is exactly where stacks and queues show up together in real systems (job queues with “undo last job”, browser history with back/forward, etc.).

### Suggested follow-ups
1. Replace arrays with a real deque (e.g., `deque` package or doubly-linked list) to make `processNext`/`undo` O(1).
2. Add `redo()` using a second stack for redone documents.
3. Add capacity limits and eviction (queue overflow policy).

## Stacks & Queues in TypeScript

### Conceptual overview

**Stack — LIFO (Last In, First Out)**
- You push onto the top and pop from the top.
- Think: a stack of plates, the call stack, undo history, bracket matching.
- Core ops: `push`, `pop`, `peek`, `isEmpty`, `size` — all ideally **O(1)**.

**Queue — FIFO (First In, First Out)**
- You enqueue at the rear and dequeue from the front.
- Think: a line at a coffee shop, task scheduling, BFS traversal.
- Core ops: `enqueue`, `dequeue`, `peek` (front), `isEmpty`, `size` — all ideally **O(1)**.

> ⚠️ A naive `Array`-based queue using `shift()` is **O(n)** per dequeue. In an interview, mention this and fix it with a **singly linked list** (head + tail) or a **ring buffer**. Stacks are fine on top of arrays (`push`/`pop` are amortized O(1)).

---

### Clean implementation

```typescript
// ─────────────────────────────────────────────────────────────
// Node shared by both stack and queue (singly linked list)
// ─────────────────────────────────────────────────────────────
class Node<T> {
  constructor(public value: T, public next: Node<T> | null = null) {}
}

// ─────────────────────────────────────────────────────────────
// Stack — LIFO, backed by a singly linked list (O(1) all ops)
// ─────────────────────────────────────────────────────────────
class Stack<T> {
  private top: Node<T> | null = null;
  private _size = 0;

  /** Push onto the top — O(1) */
  push(value: T): void {
    this.top = new Node(value, this.top);
    this._size++;
  }

  /** Remove and return the top element — O(1) */
  pop(): T | undefined {
    if (!this.top) return undefined;
    const value = this.top.value;
    this.top = this.top.next;
    this._size--;
    return value;
  }

  /** Look at the top without removing — O(1) */
  peek(): T | undefined {
    return this.top?.value;
  }

  isEmpty(): boolean {
    return this._size === 0;
  }

  size(): number {
    return this._size;
  }

  /** Iterate from top → bottom (does not mutate) */
  *[Symbol.iterator](): Iterator<T> {
    let cur = this.top;
    while (cur) {
      yield cur.value;
      cur = cur.next;
    }
  }
}

// ─────────────────────────────────────────────────────────────
// Queue — FIFO, backed by a singly linked list with head + tail
// ─────────────────────────────────────────────────────────────
class Queue<T> {
  private head: Node<T> | null = null; // dequeue from here
  private tail: Node<T> | null = null; // enqueue here
  private _size = 0;

  /** Enqueue at the rear — O(1) */
  enqueue(value: T): void {
    const node = new Node(value);
    if (!this.tail) {
      // empty queue: head and tail point to the same node
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this._size++;
  }

  /** Remove and return the front element — O(1) */
  dequeue(): T | undefined {
    if (!this.head) return undefined;
    const value = this.head.value;
    this.head = this.head.next;
    if (!this.head) this.tail = null; // queue became empty
    this._size--;
    return value;
  }

  /** Look at the front without removing — O(1) */
  peek(): T | undefined {
    return this.head?.value;
  }

  isEmpty(): boolean {
    return this._size === 0;
  }

  size(): number {
    return this._size;
  }

  /** Iterate from front → rear (does not mutate) */
  *[Symbol.iterator](): Iterator<T> {
    let cur = this.head;
    while (cur) {
      yield cur.value;
      cur = cur.next;
    }
  }
}
```

---

### Usage & complexity

```typescript
// Stack example
const s = new Stack<number>();
s.push(1); s.push(2); s.push(3);
console.log(s.pop());   // 3
console.log(s.peek());  // 2
console.log([...s]);    // [2, 1]

// Queue example
const q = new Queue<string>();
q.enqueue("a"); q.enqueue("b"); q.enqueue("c");
console.log(q.dequeue()); // "a"
console.log(q.peek());    // "b"
console.log([...q]);      // ["b", "c"]
```

| Operation | Stack | Queue |
|-----------|-------|-------|
| push/enqueue | O(1) | O(1) |
| pop/dequeue  | O(1) | O(1) |
| peek         | O(1) | O(1) |
| isEmpty/size | O(1) | O(1) |
| Space        | O(n) | O(n) |

---

### Interview talking points

1. **Why linked list over array?** Arrays give O(1) stack ops but O(n) queue dequeue via `shift()`. Linked list keeps every op O(1) with no reallocation.
2. **Ring buffer alternative:** For a bounded queue, use a fixed-size array with `head`/`tail` indices (`(i + 1) % capacity`) — great cache locality, O(1) ops, but fixed capacity.
3. **Generics (`<T>`)** make the structures type-safe and reusable.
4. **Edge cases handled:** empty pop/dequeue returns `undefined` (could also throw); tail reset on last dequeue; size tracked for O(1) `size()`.
5. **Common follow-ups:** implement `min-stack` (track min via parallel stack or node augmentation), or `circular queue`.

---

### Bonus: O(1) Min-Stack (common follow-up)

```typescript
class MinStack<T extends number> {
  private stack: { value: T; min: T }[] = [];

  push(value: T): void {
    const min = this.stack.length
      ? Math.min(value, this.stack[this.stack.length - 1].min)
      : value;
    this.stack.push({ value, min });
  }

  pop(): T | undefined {
    return this.stack.pop()?.value;
  }

  peek(): T | undefined {
    return this.stack[this.stack.length - 1]?.value;
  }

  getMin(): T | undefined {
    return this.stack[this.stack.length - 1]?.min;
  }
}
```

# Edge cases for stacks and queues in TypeScript

Below are the most common (and a few subtle) edge cases, with idiomatic TypeScript examples.

---

## 1. Empty collection: underflow on `pop` / `dequeue`

**Problem:** Calling `pop()`/`dequeue()` on an empty structure.

**Options:** throw, or return `undefined` (safer for callers). Pick one policy and be consistent.

```ts
class SafeStack<T> {
  private items: T[] = [];

  push(x: T): void {
    this.items.push(x);
  }

  // Policy A: throw (fail fast)
  popOrThrow(): T {
    if (this.items.length === 0) throw new Error("Stack underflow");
    return this.items.pop()!;
  }

  // Policy B: nullable (convenient for loops)
  pop(): T | undefined {
    return this.items.pop();
  }

  peek(): T | undefined {
    return this.items.at(-1);
  }
}
```

---

## 2. Bounded capacity: overflow

**Problem:** Fixed-size stack/queue (ring buffer) must reject or overwrite when full.

```ts
class BoundedStack<T> {
  private buf: (T | undefined)[];
  private top = -1;
  private readonly cap: number;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.cap = capacity;
    this.buf = new Array(capacity);
  }

  push(x: T): void {
    if (this.top + 1 >= this.cap) throw new Error("Stack overflow");
    this.buf[++this.top] = x;
  }

  pop(): T | undefined {
    if (this.top < 0) return undefined;
    const v = this.buf[this.top];
    this.buf[this.top--] = undefined; // help GC
    return v;
  }
}
```

---

## 3. Queue implemented with `Array.shift()` is O(n)

**Problem:** `arr.shift()` reindexes every element. For large queues this is a performance edge case.

**Fix:** use a circular buffer or linked list.

```ts
class CircularQueue<T> {
  private buf: (T | undefined)[];
  private head = 0;
  private tail = 0;
  private count = 0;
  private readonly cap: number;

  constructor(capacity: number) {
    if (capacity <= 0) throw new RangeError("capacity must be > 0");
    this.cap = capacity;
    this.buf = new Array(capacity);
  }

  enqueue(x: T): void {
    if (this.count === this.cap) throw new Error("Queue full");
    this.buf[this.tail] = x;
    this.tail = (this.tail + 1) % this.cap;
    this.count++;
  }

  dequeue(): T | undefined {
    if (this.count === 0) return undefined;
    const v = this.buf[this.head];
    this.buf[this.head] = undefined; // avoid memory leak
    this.head = (this.head + 1) % this.cap;
    this.count--;
    return v;
  }

  peek(): T | undefined {
    return this.count === 0 ? undefined : this.buf[this.head];
  }
}
```

Edge to test: capacity `1`, and wrap-around (`enqueue, dequeue, enqueue`).

---

## 4. Generics and `undefined` as a valid item

**Problem:** If `T` can be `undefined`, you cannot distinguish “empty” from “stored undefined”.

**Fix:** track size/count separately (as above) instead of relying on `undefined` checks.

```ts
const q = new CircularQueue<number | undefined>(2);
q.enqueue(undefined);
console.log(q.dequeue()); // undefined, but size went 1 -> 0 correctly
```

---

## 5. Reference aliasing / mutation of stored objects

**Problem:** Stacks/queues store references; mutating an object after push affects the stored value.

```ts
class Stack<T> {
  private items: T[] = [];
  push(x: T) { this.items.push(x); }
  pop() { return this.items.pop(); }
}

const s = new Stack<{ n: number }>();
const o = { n: 1 };
s.push(o);
o.n = 999;
console.log(s.pop()?.n); // 999 (surprising if you expected a snapshot)
```

**Fix (if immutability needed):** clone on push/pop, or document “stores references.”

```ts
push(x: T) { this.items.push(structuredClone(x)); }
```

---

## 6. Memory leaks in fixed buffers

**Problem:** In ring buffers, overwritten slots may keep references alive if not cleared.

**Fix:** set slot to `undefined` on dequeue/overwrite (shown in `CircularQueue`).

---

## 7. Iteration while mutating

**Problem:** Mutating during `for...of` can skip/duplicate items.

```ts
class Stack<T> {
  private items: T[] = [];
  push(x: T) { this.items.push(x); }
  pop() { return this.items.pop(); }
  *[Symbol.iterator](): Iterator<T> {
    // snapshot to be safe
    const snap = [...this.items];
    for (let i = snap.length - 1; i >= 0; i--) yield snap[i];
  }
}
```

Use a snapshot iterator; otherwise document “do not mutate during iteration.”

---

## 8. Concurrency / async interleaving

JavaScript is single-threaded, but `await` yields control. A check-then-act across an `await` can race.

```ts
async function unsafePopIfNonEmpty(stack: Stack<number>) {
  if (!stack.isEmpty()) {
    await doSomething(); // another task may pop here
    return stack.pop();  // may be undefined now
  }
}
```

**Fix:** make operations synchronous and atomic; if async work is needed, queue tasks instead of sharing mutable state directly.

---

## 9. Serialization (`JSON.stringify`)

Class instances serialize as `{}` unless you implement `toJSON`.

```ts
class Stack<T> {
  private items: T[] = [];
  push(x: T) { this.items.push(x); }
  toJSON() { return [...this.items]; }
  static fromJSON<T>(arr: T[]): Stack<T> {
    const s = new Stack<T>();
    arr.forEach(x => s.push(x));
    return s;
  }
}
```

---

## 10. Equality / search (`contains`)

**Problem:** `===` vs deep equality. Decide and document.

```ts
contains(x: T, eq: (a: T, b: T) => boolean = Object.is): boolean {
  return this.items.some(v => eq(v, x));
}
```

---

## 11. Deque: operations at both ends

**Problem:** Using arrays for both ends is inefficient (`unshift`/`shift` are O(n)).

**Fix:** use a doubly linked list or a deque library; if array-backed, only push/pop at one end.

---

## 12. Priority queue ties

**Problem:** Equal priorities: FIFO order? stable? Define tie-break rule.

```ts
type Item<T> = { value: T; priority: number; seq: number };

class PriorityQueue<T> {
  private heap: Item<T>[] = [];
  private seq = 0;

  enqueue(value: T, priority: number) {
    this.heap.push({ value, priority, seq: this.seq++ });
    this.bubbleUp(this.heap.length - 1);
  }

  private bubbleUp(i: number) {
    // compare priority asc, then seq asc for stable FIFO among equal priorities
  }
}
```

---

## 13. Off-by-one in capacity checks

Always test:
- capacity `1`
- exactly full then one more (overflow)
- empty then dequeue (underflow)
- enqueue/dequeue until wrap-around in circular buffers

```ts
const q = new CircularQueue<number>(1);
q.enqueue(1);
console.log(q.dequeue()); // 1
q.enqueue(2);             // must not throw (wrap-around)
console.log(q.dequeue()); // 2
```

---

## 14. Readonly / defensive APIs

Expose read-only views to prevent external mutation:

```ts
get items(): readonly T[] {
  return this.items; // private field shadowed? use different name
}
```

Better: return a copy or `ReadonlyArray<T>`.

---

## Summary checklist

- Underflow policy (throw vs `undefined`)
- Overflow policy for bounded structures
- O(1) queue operations (avoid `shift`)
- Wrap-around correctness in ring buffers
- Clearing slots for GC
- `undefined` as valid data (track count)
- Reference vs value semantics
- Snapshot iteration
- Async interleaving
- Serialization (`toJSON`)
- Equality semantics
- Stable tie-breaking in priority queues
- Capacity edge values (0, 1, full, empty)

If you want, I can provide a single production-ready `Deque<T>` and `Stack<T>` implementation combining these safeguards.

## Static vs. Instance Members in TypeScript

| Aspect | Instance members | Static members |
|---|---|---|
| Belong to | Each object (`this`) | The class itself |
| Access | `obj.prop`, `this.prop` | `ClassName.prop`, `this.prop` inside static methods (where `this` is the class) |
| Lifetime | Created per instance | Created once when class is defined |
| Typical use | State/behavior of an object | Factories, counters, constants, helpers |

### Complete runnable example

Save as `members.ts`:

```ts
// ---- Base class demonstrating both kinds of members ----
class Counter {
  // ---- instance state ----
  private value: number;

  // ---- static state (shared across all instances) ----
  static totalCreated: number = 0;
  static readonly MAX = 1000;

  // private static field (truly private at runtime via #)
  static #secretSalt = "s3cr3t";

  constructor(initial = 0) {
    if (initial > Counter.MAX) {
      throw new Error(`initial exceeds MAX (${Counter.MAX})`);
    }
    this.value = initial;
    Counter.totalCreated++;
  }

  // ---- instance methods ----
  increment(by = 1): this {
    this.value += by;
    return this; // fluent API
  }

  get valueSnapshot(): number {
    return this.value;
  }

  // instance method can reach static members via the class name
  describe(): string {
    return `Counter#${Counter.totalCreated} value=${this.value}`;
  }

  // ---- static methods ----
  static create(initial?: number): Counter {
    return new Counter(initial);
  }

  static get total(): number {
    return Counter.totalCreated;
  }

  // static method demonstrating `this` = the class (polymorphic)
  static describeClass(): string {
    return `I am ${this.name}, created ${this.totalCreated} instances so far`;
  }

  // static helper using private static field
  static hash(n: number): string {
    return `${Counter.#secretSalt}:${n}`;
  }

  // ---- static initialization block (runs once when class is defined) ----
  static {
    console.log("[Counter] class initialized, MAX =", Counter.MAX);
  }
}

// ---- Inheritance: static members are inherited and `this` is polymorphic ----
class Animal {
  static species = "Animal";
  static describe(): string {
    // `this` refers to the subclass when called as Dog.describe()
    return `species=${this.species}, name=${this.name}`;
  }
  constructor(public name: string) {}
}

class Dog extends Animal {
  static species = "Dog";
  bark(): string {
    return `${this.name} says woof`;
  }
}

// ---- Runnable demo ----
function main(): void {
  console.log("=== Static blocks ran above ===");

  const c1 = new Counter(5);
  const c2 = Counter.create(10);

  c1.increment().increment(3);
  console.log("c1 value:", c1.valueSnapshot);          // 9
  console.log("c2 value:", c2.valueSnapshot);          // 10
  console.log("total created:", Counter.total);        // 2
  console.log("describe c1:", c1.describe());
  console.log("hash(42):", Counter.hash(42));

  // polymorphic static `this`
  console.log(Animal.describe()); // species=Animal, name=Animal
  console.log(Dog.describe());    // species=Dog, name=Dog

  const rex = new Dog("Rex");
  console.log(rex.bark());

  // note: instance and static can share a name (different objects)
  console.log("Counter name (static-ish via class):", Counter.name);
}

main();
```

### Compile & run

```bash
# TypeScript 4.4+ (static blocks) and a recent Node
npm i -D typescript ts-node
npx tsc members.ts --target es2022 --module commonjs --strict
node members.js

# or directly
npx ts-node members.ts
```

Expected output (order of logs):

```
[Counter] class initialized, MAX = 1000
=== Static blocks ran above ===
c1 value: 9
c2 value: 10
total created: 2
describe c1: Counter#2 value=9
hash(42): s3cr3t:42
species=Animal, name=Animal
species=Dog, name=Dog
Rex says woof
Counter name (static-ish via class): Counter
```

### Key points / pitfalls

1. **`this` differs by context.** In an instance method, `this` is the instance. In a static method, `this` is the class constructor (and is polymorphic under inheritance), so `this.species` resolves to the subclass’s static field.
2. **Static members are not on instances.** `c1.total` is a type error; use `Counter.total`.
3. **Private static fields.** `static #secretSalt` is a hard-private runtime field (not just TS `private`, which is erased). Access only inside the class.
4. **Static blocks** run once, in declaration order, after static field initializers above them; useful for complex one-time setup.
5. **Initialization order.** Static fields initialize top-to-bottom when the class is defined; instance fields initialize during construction, after `super()` in subclasses.
6. **Shared mutable static state** is global-ish state—avoid mutating it from instances unless intentional (e.g., counters, caches).
7. **Same name on static & instance** is legal because they live on different objects (class vs. prototype), but it’s confusing—avoid it.
8. **Abstract static methods** are not supported in TypeScript; use interfaces or factory patterns instead.

This example covers factories, counters, constants, private static state, static blocks, polymorphic static `this`, and inheritance.

## Core idea

- **Instance members** belong to an *object instance*. Each `new Foo()` gets its own copy of instance fields/methods, and they can access `this` (the instance).
- **Static members** belong to the *class itself* (the constructor function). There is exactly one copy, shared across all instances, and they are accessed via the class name (or via `this` inside static context, which refers to the class).

```ts
class Person {
  // instance field
  name: string;

  // static field (shared by all)
  static species = "Homo sapiens";

  constructor(name: string) {
    this.name = name;
  }

  // instance method
  greet() {
    return `Hi, I'm ${this.name}`;
  }

  // static method
  static createAnonymous() {
    return new Person("Anonymous");
  }
}

const p = new Person("Alice");
p.greet();            // "Hi, I'm Alice"
Person.species;       // "Homo sapiens"
Person.createAnonymous(); // Person { name: "Anonymous" }
```

## Syntax essentials

| Kind | Declaration | Access |
|------|-------------|--------|
| Instance field | `name: string;` | `obj.name` |
| Instance method | `greet() {...}` | `obj.greet()` |
| Static field | `static count = 0;` | `ClassName.count` |
| Static method | `static fromJSON(...) {...}` | `ClassName.fromJSON(...)` |
| Static block | `static { ... }` | runs once at class load |

```ts
class Counter {
  private static total = 0;   // shared
  private id: number;          // per instance

  constructor() {
    Counter.total++;
    this.id = Counter.total;
  }

  static getTotal() {
    return Counter.total;
  }

  getId() {
    return this.id;
  }
}
```

## `this` rules (important)

- Inside an **instance method**, `this` is the instance.
- Inside a **static method**, `this` is the **class constructor** (so static methods can call other statics via `this.foo()` — useful for inheritance).

```ts
class Base {
  static kind = "base";
  static describe() {
    return `kind=${this.kind}`; // `this` is the class
  }
}

class Derived extends Base {
  static kind = "derived";
}

Derived.describe(); // "kind=derived"  (polymorphic static)
```

## Typical use cases

### 1. Factories / named constructors
```ts
class User {
  constructor(public id: number, public name: string) {}

  static fromJSON(raw: string): User {
    const { id, name } = JSON.parse(raw);
    return new User(id, name);
  }
}
```

### 2. Counters / registries / caches (shared state)
```ts
class Service {
  private static cache = new Map<string, Service>();

  static get(key: string) {
    if (!Service.cache.has(key)) Service.cache.set(key, new Service());
    return Service.cache.get(key)!;
  }
}
```

### 3. Constants and pure utilities
```ts
class Math2D {
  static readonly PI2 = Math.PI * 2;
  static clamp(x: number, lo: number, hi: number) {
    return Math.min(Math.max(x, lo), hi);
  }
}
```

### 4. Static initialization block (TS 4.4+ / ES2022)
Runs once when the class is defined — handy for complex static setup.
```ts
class Config {
  static readonly env: Record<string, string>;

  static {
    Config.env = (globalThis as any).__ENV__ ?? {};
  }
}
```

## Common pitfalls

- **Static cannot access instance state** directly; you need an instance:
  ```ts
  class Foo {
    static bad() { return this.value; } // TS error: Property 'value' does not exist on type 'typeof Foo'
    value = 1;
  }
  ```
- **Arrow-function instance fields** capture instance `this` but cost memory per instance:
  ```ts
  class A { onClick = () => this.do(); } // instance-bound, safe as callback
  ```
- **Don’t overuse static** for “global” mutable state — it hurts testability and tree-shaking. Prefer module-level functions/consts or DI.
- Static members are **not part of the instance type** in most interfaces, but they *are* on the constructor type: `typeof ClassName`.

## Typing note

```ts
type Ctor = typeof Person; // includes static members
type Instance = Person;     // instance members only
```

That distinction (`typeof ClassName` vs `ClassName`) is how you type “a class value” vs “an instance” in TypeScript.

Here is a small TypeScript example with a common static/instance confusion.

### Mistaken version

```ts
class BankAccount {
  static accountCount = 0; // shared by the class
  balance = 0;             // owned by each instance

  constructor(initialBalance: number) {
    this.balance = initialBalance;

    // Mistake 1: `accountCount` is static, so it lives on the class,
    // not on an instance. `this.accountCount` is not the shared counter.
    this.accountCount++;
  }

  deposit(amount: number) {
    this.balance += amount;

    // Mistake 2: `balance` is an instance property, so it cannot be
    // accessed through the class name like a static member.
    BankAccount.balance += amount;
  }

  static getTotalAccounts(): number {
    // Mistake 3: a static method has no instance `this`.
    // Here, `this` refers to the class constructor, not an account.
    return this.balance;
  }
}
```

### Corrected version

```ts
class BankAccount {
  static accountCount = 0; // shared class state
  balance = 0;             // per-instance state

  constructor(initialBalance: number) {
    this.balance = initialBalance;
    BankAccount.accountCount++; // update shared static state via the class
  }

  deposit(amount: number) {
    this.balance += amount; // update this particular instance
  }

  getBalance(): number {
    return this.balance;
  }

  static getTotalAccounts(): number {
    return BankAccount.accountCount; // read shared static state
  }
}
```

### What was wrong and why

1. **Static members belong to the class, not instances.**  
   `accountCount` is declared with `static`, so every `BankAccount` instance shares one value. It should be accessed as `BankAccount.accountCount`, not `this.accountCount` from an instance method or constructor. Depending on TypeScript settings, `this.accountCount` may be a compile error because the instance type does not contain that property.

2. **Instance members belong to each object, not the class.**  
   `balance` is an ordinary instance property, so each account has its own `balance`. It must be accessed through an instance, such as `this.balance` inside an instance method. `BankAccount.balance` is wrong because the class constructor itself does not have a single shared `balance`.

3. **`this` means different things in static vs. instance methods.**  
   In an instance method or constructor, `this` refers to the current object. In a static method, `this` refers to the class constructor. Therefore, `this.balance` inside `getTotalAccounts` does not refer to any account's balance; it looks for a static `balance`, which does not exist.

4. **Keep responsibilities separated.**  
   Shared/global state such as `accountCount` should be static and updated through the class. Per-object state such as `balance` should be instance state and updated through `this`. Mixing those access patterns creates type errors, logical bugs, or accidental shared mutable state.

# Common Pitfalls with Static and Instance Members in TypeScript

Below are frequent mistakes, why they happen, and idiomatic fixes. Examples assume `strict` mode.

---

## 1. Losing `this` when extracting a method

Both instance and static methods rely on `this`. Passing them as callbacks detaches the receiver.

```ts
class Counter {
  count = 0;
  inc() { this.count++; }          // instance method
  static total = 0;
  static add() { this.total++; }   // static method
}

const c = new Counter();
const inc = c.inc;
inc(); // TypeError: Cannot read properties of undefined (reading 'count')

const add = Counter.add;
add(); // TypeError: Cannot read properties of undefined (reading 'total')
```

**Fix:** bind explicitly, or use an arrow class field when you need lexical `this`.

```ts
const inc = c.inc.bind(c);
const add = Counter.add.bind(Counter);
```

---

## 2. Static members cannot reference class type parameters

Static members belong to the constructor value, not to any instance, so they have no `T`.

```ts
class Box<T> {
  value: T;
  constructor(value: T) { this.value = value; }

  // Error: Static members cannot reference class type parameters.
  // static defaultValue: T = ...;

  // OK: make the method itself generic
  static make<U>(x: U): Box<U> { return new Box(x); }
}
```

---

## 3. `abstract static` is not supported

TypeScript does not allow abstract static members. If you need “static polymorphism,” use an abstract class with instance hooks, or a separate factory/interface.

```ts
abstract class Base {
  // Error: Modifiers 'abstract' and 'static' cannot be used together.
  // abstract static create(): Base;
}
```

Workaround:

```ts
abstract class Base {
  abstract create(): Base; // instance factory hook
}
```

---

## 4. Hard-coding the class name in a static factory

`this` in a static method is the constructor that was used to call it, which may be a subclass.

```ts
class Animal {
  static create() { return new Animal(); } // always Animal
}
class Dog extends Animal {}

const x = Dog.create();
console.log(x instanceof Dog); // false (surprise)
```

**Fix:** use `this` / `new.target`-style construction.

```ts
class Animal {
  static create() { return new this(); }
}
class Dog extends Animal {}

console.log(Dog.create() instanceof Dog); // true
```

---

## 5. Static field initialization order and TDZ

Static fields initialize top-to-bottom. Referencing the class name inside its own static initializer hits the temporal dead zone.

```ts
class A {
  static x = A.y + 1; // ReferenceError: Cannot access 'A' before initialization
  static y = 5;
}
```

**Fix:** order fields correctly, use `this`, or use a `static` block.

```ts
class A {
  static y = 5;
  static x = this.y + 1; // 6
}

// Or:
class B {
  static x: number;
  static y = 5;
  static { this.x = this.y + 1; }
}
```

---

## 6. Static and instance members share names but not storage

They live in different “namespaces” (`Constructor` vs prototype/instance). Refactoring can make this confusing.

```ts
class Foo {
  static bar = "static";
  bar = "instance";
}

const f = new Foo();
Foo.bar; // "static"
f.bar;   // "instance"
```

This is legal, but mixing them often indicates a design smell (e.g., a value that should be either configuration or per-instance state, not both).

---

## 7. Non-enumerability surprises

Static methods and class fields are non-enumerable. `Object.keys` will not list them.

```ts
class A {
  static m() {}
  static x = 1;
}

console.log(Object.keys(A));              // []
console.log(Object.getOwnPropertyNames(A)); // includes 'm', 'x', 'prototype', 'name', 'length'
```

If you need to iterate static API surface, use `Object.getOwnPropertyNames` / `getOwnPropertyDescriptors`, not `Object.keys`.

---

## 8. `super` in static methods keeps dynamic `this`

In a static method, `super.method()` calls the base implementation but with `this` set to the derived class.

```ts
class Base {
  static x = 10;
  static getX() { return this.x; }
}
class Derived extends Base {
  static x = 20;
  static getX() { return super.getX(); } // not 10!
}

console.log(Derived.getX()); // 20
```

If you truly want the base value, call `Base.getX()` explicitly.

---

## 9. Arrow class fields vs methods: different `this` and `super` rules

Instance arrow fields capture the instance lexically; they are not on the prototype and cannot be overridden polymorphically the same way.

```ts
class Foo {
  value = 0;

  // arrow instance field: `this` is always this instance
  inc = () => { this.value++; };

  // normal method: `this` depends on call site
  dec() { this.value--; }
}
```

Static arrow fields similarly capture the class:

```ts
class Logger {
  static tag = "[app]";
  static log = (msg: string) => console.log(this.tag, msg);
}
const log = Logger.log;
log("hi"); // works, `this` is Logger
```

Pitfalls:

- Arrow fields are created per instance (memory cost) and are not inherited/overridable via prototype.
- You cannot use `super` inside an arrow field initializer the way you can in a constructor/method.
- Mixing arrow fields and methods makes `instanceof`/subclass behavior harder to reason about.

---

## 10. Mutable static state is not shared across subclasses the way you expect

Because assignment creates an own property, subclasses shadow inherited static data on first write.

```ts
class Base {
  static count = 0;
  static inc() { this.count++; }
}
class A extends Base {}
class B extends Base {}

A.inc();
B.inc();

console.log(Base.count); // 0  (unchanged!)
console.log(A.count);   // 1
console.log(B.count);   // 1
```

If you want shared mutable state, keep it in a module-level variable or a single owner, not inherited static fields.

---

## 11. Confusing “static this” with instance `this`

A static method’s `this` is the class, not an instance. Trying to read instance fields from it fails.

```ts
class User {
  name = "Ada";
  static greet() {
    // `this` is `User`, not a User instance
    console.log(this.name); // undefined
  }
}
```

To access instance data, you need an instance:

```ts
class User {
  name = "Ada";
  static greet(u: User) { console.log(u.name); }
}
```

Conversely, from an instance method you can reach static members via `this.constructor`:

```ts
class User {
  static defaultRole = "user";
  role = (this.constructor as typeof User).defaultRole;
}
```

Use this carefully; it is dynamic and can be surprising with subclasses.

---

## 12. `private static` (TS-only) vs `#private static` (runtime)

TypeScript’s `private static` is erased at runtime; `#private static` is truly private.

```ts
class Foo {
  private static pseudo = 2; // erased: Foo.pseudo exists at runtime
  static #secret = 1;       // truly private: not accessible even at runtime
}

// Runtime leak:
console.log((Foo as any).pseudo); // 2

// Error at compile time and runtime:
// Foo.#secret; // not accessible
```

Pitfalls:

- Do not use `private static` for security or for hiding implementation details from untrusted code.
- `#private static` cannot be accessed by subclasses, even via `super`.
- Mixing both in one class is legal but hard to audit.

---

## Bonus: interfaces cannot declare static members

If you try to “interface” statics, TypeScript won’t allow it.

```ts
interface WithStatic {
  // static create(): WithStatic; // not allowed
}

// Use an abstract class or a factory type instead:
type Factory<T> = { create(): T };
```

---

### Quick checklist

- Bind or arrow-wrap any method passed as a callback.
- Never reference class type params from static code.
- Use `this` in static factories, not the class name.
- Keep static mutable state out of inherited hierarchies.
- Prefer `#private` when you need real runtime privacy.
- Remember static/non-static members are separate namespaces and separately enumerable.

## Exercise

Create a TypeScript class `Logger` that satisfies these rules:

1. Each `Logger` instance has a unique `id` (number) and a `name` (string).
2. The class tracks **how many loggers have ever been created** in a **static** member `totalCreated`.
3. Each instance tracks **how many messages it has logged** in an **instance** member `messageCount`.
4. Provide:
   - an instance method `log(message: string): string` that increments `messageCount` and returns a formatted string like `[id:name] message`
   - a static method `getTotalCreated(): number`
   - a static method `resetTotalCreated(): void` (for tests) that sets `totalCreated` back to `0`

---

## Step-by-step solution

### Step 1 — Decide what is static vs instance

- `totalCreated` is shared across **all** instances → `static`.
- `id`, `name`, `messageCount` belong to **each object** → instance properties.

```ts
class Logger {
  private static totalCreated = 0;   // shared
  private id: number;               // per instance
  private name: string;             // per instance
  private messageCount = 0;         // per instance
}
```

### Step 2 — Assign an id in the constructor and bump the static counter

When `new Logger(...)` runs, increment the static counter first, then use it as the new instance's id.

```ts
constructor(name: string) {
  Logger.totalCreated += 1;
  this.id = Logger.totalCreated;
  this.name = name;
}
```

### Step 3 — Implement instance logging behavior

`log` should update **this** instance’s counter and return a formatted string.

```ts
log(message: string): string {
  this.messageCount += 1;
  return `[${this.id}:${this.name}] ${message}`;
}
```

### Step 4 — Add static helpers

Static methods are called on the class itself, not on instances. They can read/write static members.

```ts
static getTotalCreated(): number {
  return Logger.totalCreated;
}

static resetTotalCreated(): void {
  Logger.totalCreated = 0;
}
```

### Step 5 — Add a getter for messageCount (optional but useful)

Expose instance state without allowing direct mutation from outside.

```ts
get messagesLogged(): number {
  return this.messageCount;
}
```

### Step 6 — Put it together and test mental model

```ts
const a = new Logger("auth");
const b = new Logger("db");

console.log(a.log("started"));   // [1:auth] started
console.log(b.log("connected")); // [2:db] connected
console.log(Logger.getTotalCreated()); // 2
console.log(a.messagesLogged);   // 1
```

---

## Final solution

```ts
class Logger {
  private static totalCreated = 0;

  private readonly id: number;
  private readonly name: string;
  private messageCount = 0;

  constructor(name: string) {
    Logger.totalCreated += 1;
    this.id = Logger.totalCreated;
    this.name = name;
  }

  log(message: string): string {
    this.messageCount += 1;
    return `[${this.id}:${this.name}] ${message}`;
  }

  get messagesLogged(): number {
    return this.messageCount;
  }

  static getTotalCreated(): number {
    return Logger.totalCreated;
  }

  static resetTotalCreated(): void {
    Logger.totalCreated = 0;
  }
}

// --- Demo usage ---
Logger.resetTotalCreated();

const authLogger = new Logger("auth");
const dbLogger = new Logger("db");

console.log(authLogger.log("service started"));   // [1:auth] service started
console.log(dbLogger.log("connection opened"));   // [2:db] connection opened
console.log(authLogger.log("token refreshed"));   // [1:auth] token refreshed

console.log("Total loggers created:", Logger.getTotalCreated()); // 2
console.log("auth messages:", authLogger.messagesLogged);          // 2
console.log("db messages:", dbLogger.messagesLogged);            // 1
```

### Key takeaways

- **Static members** (`totalCreated`, `getTotalCreated`, `resetTotalCreated`) belong to the **class** and are shared by all instances.
- **Instance members** (`id`, `name`, `messageCount`, `log`, `messagesLogged`) belong to **each object**.
- Inside instance methods, use `this` for instance state.
- Inside static methods, use the class name (or `this` in static context) for static state.

## Static vs Instance Members in TypeScript

### Core idea

- **Instance members** belong to *an object created with `new`*. Each instance gets its own copy (for fields) and accesses them through `this`. They model **per-object state and behavior**.
- **Static members** belong to the *class/constructor function itself*. There is exactly one copy shared by all instances. They model **class-level state, factories, registries, and utilities**.

### Key differences

| Aspect | Instance | Static |
|---|---|---|
| Ownership | Object instance | Constructor function |
| Access syntax | `obj.method()` / `this.field` | `ClassName.method()` / `ClassName.field` |
| `this` inside | The instance | The class (constructor) |
| State sharing | Per instance | Shared globally for that class |
| Can access instance state? | Yes | No (no instance `this`) |
| Can access static state? | Yes, via `ClassName.x` or `this.constructor.x` | Yes, directly |
| Lifetime | Lives with instance | Lives with module/class load |
| Inheritance | Inherited via prototype chain | Inherited via constructor chain |

### TypeScript notes

- `static` can be combined with `readonly`, `private`, `protected`, `public`.
- Static fields are initialized when the class is loaded; instance fields when `new` runs.
- Static **blocks** (`static { ... }`) allow complex one-time initialization.
- Arrow-function instance methods preserve `this` when passed as callbacks; regular methods do not.
- Static dispatch follows the constructor chain, so overridden statics in subclasses resolve dynamically when called as `this.constructor.x` from an instance method.

---

## Implementation: a small domain model using both

```ts
/**
 * BankAccount demonstrates the split between:
 *  - static members: registry + id generation (class-level concerns)
 *  - instance members: balance + operations (per-account concerns)
 */
class BankAccount {
  // ---------- STATIC (shared, class-level) ----------

  /** Monotonic id generator; private so external code cannot desync it. */
  private static nextId = 1;

  /** Global registry of all accounts; enables lookup without a DB. */
  private static readonly accounts = new Map<number, BankAccount>();

  /** Complex one-time setup (TS 4.7+ static block). */
  static {
    // Could load seed data, configure limits, etc.
    // Kept minimal here to stay focused on the concept.
  }

  /** Factory: controlled construction + registration. */
  static create(initialBalance: number = 0): BankAccount {
    return new BankAccount(initialBalance);
  }

  /** Lookup by id (class-level query). */
  static findById(id: number): BankAccount | undefined {
    return BankAccount.accounts.get(id);
  }

  /** Aggregate over all instances (class-level computation). */
  static totalAccounts(): number {
    return BankAccount.accounts.size;
  }

  static totalBalance(): number {
    let sum = 0;
    for (const acc of BankAccount.accounts.values()) {
      sum += acc.getBalance(); // static can call instance methods on instances
    }
    return sum;
  }

  // ---------- INSTANCE (per-object) ----------

  /** Assigned once during construction; readonly after that. */
  public readonly id: number;

  /** Private per-account state. */
  private balance: number;

  constructor(initialBalance: number = 0) {
    if (initialBalance < 0) throw new Error("initial balance cannot be negative");

    this.id = BankAccount.nextId++;          // instance field initialized from static state
    this.balance = initialBalance;

    BankAccount.accounts.set(this.id, this);  // register this instance statically
  }

  /** Instance behavior operating on instance state. */
  deposit(amount: number): void {
    if (amount <= 0) throw new Error("deposit amount must be positive");
    this.balance += amount;
  }

  /** Instance behavior reading instance state. */
  getBalance(): number {
    return this.balance;
  }

  /**
   * Instance method that reaches static state through the constructor.
   * Using `this.constructor` keeps dispatch dynamic under inheritance.
   */
  unregister(): void {
    // `this.constructor` is the actual runtime class (subclass-safe).
    const ctor = this.constructor as typeof BankAccount;
    ctor.accounts.delete(this.id);
  }
}

// ---------- Usage ----------

const a = BankAccount.create(100);
const b = new BankAccount(50); // direct construction also works

a.deposit(25);
console.log(a.getBalance());          // 125
console.log(BankAccount.findById(a.id) === a); // true
console.log(BankAccount.totalAccounts());      // 2
console.log(BankAccount.totalBalance());       // 175

b.unregister();
console.log(BankAccount.totalAccounts());      // 1
```

### Pitfalls worth calling out in an interview

1. **Losing `this`**  
   ```ts
   const fn = a.getBalance;
   fn(); // `this` is undefined (strict mode) -> bug
   ```
   Fix: bind it, or make it an arrow function property.

2. **Static fields are not on instances**  
   `a.id` works, but `a.totalAccounts` is `undefined` unless you go through the class.  
   (You *can* reach statics via `a.constructor.totalAccounts()`, but that’s usually a code smell.)

3. **Shadowing**  
   An instance property with the same name as a static member does not override the static one; they live on different objects (instance vs constructor).

4. **Inheritance dispatch**  
   Static members are inherited, but `this` inside a static method refers to the *called* class, which enables polymorphic factories:
   ```ts
   class Base { static create() { return new this(); } }
   class Child extends Base {}
   Child.create() instanceof Child; // true
   ```

5. **Initialization order**  
   Static initializers run top-to-bottom at class load; instance initializers run per `new`. Don’t let static code depend on instance state, and be careful with circular class references.

---

### Minimal “core” reimplementation (to show understanding)

If asked to implement the *mechanism* itself (how JS/TS stores these), the essence is:

```ts
function makeClass() {
  // The constructor function IS the class object.
  const Ctor: any = function (this: any, ...args: any[]) {
    // instance initialization
    this.id = Ctor.nextId++;
    Ctor.instances.set(this.id, this);
  };

  // static members live on the function object
  Ctor.nextId = 1;
  Ctor.instances = new Map();
  Ctor.findById = (id: number) => Ctor.instances.get(id);

  // instance members live on the prototype
  Ctor.prototype.getBalance = function () {
    return this.balance;
  };

  return Ctor;
}
```

That’s the underlying model: **static = properties of the constructor function; instance = properties of the prototype / assigned in constructor**. TypeScript’s `class` syntax is syntactic sugar over exactly this, plus type checking.

## Edge cases with static and instance members in TypeScript

Below are the most important edge cases, grouped by theme, with runnable-ish examples.

---

### 1. Static members cannot use class type parameters

Static members belong to the constructor function, so they exist once for the whole family of `T`s. Referencing `T` there is illegal.

```ts
class Box<T> {
  value: T;

  // ❌ Error: Static members cannot reference class type parameters.
  // static defaultValue: T;

  // ✅ Use a generic static method instead, or widen the type.
  static defaultValue: unknown;
}
```

**Fix:** make the static member a method that accepts/returns the needed type, or move the generic parameter to the method.

```ts
class Box<T> {
  value: T;
  constructor(value: T) { this.value = value; }

  static create<T>(value: T): Box<T> {
    return new Box(value);
  }
}
```

---

### 2. `this` in a static method is the *constructor*, not an instance

This enables polymorphic factories, but it surprises people.

```ts
class Base {
  static create(): Base {
    // `this` is the constructor that was actually called
    return new this();
  }
}

class Derived extends Base {}

const a = Base.create();     // Base
const b = Derived.create();  // Derived ✅
```

**Edge case: losing `this`.** Destructuring or passing as a callback breaks it.

```ts
class Logger {
  static level = "info";
  static log(msg: string) {
    console.log(`[${this.level}]`, msg);
  }
}

const log = Logger.log;
// log("hi"); // ❌ `this` is undefined at runtime (strict mode)

// ✅ Bind or use a static class field with an arrow function
class Logger2 {
  static level = "info";
  static log = (msg: string) => {
    console.log(`[${Logger2.level}]`, msg);
  };
}
const log2 = Logger2.log;
log2("hi"); // works, but note `this` is no longer polymorphic
```

---

### 3. Static and instance members may share a name (confusing, but legal)

They live on different objects (constructor vs. prototype), so TypeScript allows it. Avoid it for readability.

```ts
class Counter {
  count = 0;          // instance
  static count = 100; // static

  show() {
    console.log(this.count);      // 0 (instance)
    console.log(Counter.count);   // 100 (static)
  }
}
```

---

### 4. Static members are inherited and can call `super`

```ts
class Base {
  static greet() { return "base"; }
}

class Derived extends Base {
  static greet() {
    return `${super.greet()} -> derived`; // ✅
  }
}

Derived.greet(); // "base -> derived"
```

**Edge case:** `super` only works inside a static method of the subclass. From a free function you must call `Base.greet()` explicitly.

---

### 5. Accessing statics from an instance is not type-safe without casts

`this.constructor` is typed as `any`/`Function` in many contexts.

```ts
class Widget {
  static version = "1.0";

  getVersionFromInstance() {
    // ❌ Property 'version' does not exist on type 'Function'
    // return this.constructor.version;

    // ✅ explicit cast
    return (this.constructor as typeof Widget).version;
  }
}
```

Better: just reference the class by name inside instance methods when possible.

---

### 6. Initialization order and “temporal dead zone”-like behavior

Static fields initialize top-down during class evaluation.

```ts
class Config {
  // ❌ At evaluation time `Config.b` may be undefined
  static a = Config.b + 1;
  static b = 2;
}

// ✅ Use a static block to orchestrate initialization
class Config2 {
  static a: number;
  static b = 2;
  static {
    this.a = this.b + 1;
  }
}
```

---

### 7. Static blocks and private static state

Use `#` for truly private static storage; `private` is compile-time only and can be bypassed.

```ts
class SecretHolder {
  static #secret = 42;

  static reveal() {
    return this.#secret; // ✅ only accessible inside the class
  }
}

// SecretHolder.#secret; // ❌ Syntax/compile error
```

**Edge case:** subclasses cannot access private statics, even with `protected` intent. Use `protected static` if subclass access is needed.

---

### 8. Static members are NOT part of `implements`

An interface only describes the instance side. TypeScript will not enforce static members against `implements`.

```ts
interface HasBar {
  bar(): void;
}

class Foo implements HasBar {
  bar() {}          // instance side satisfied
  // static bar() {} // not checked by `implements`
}

// ✅ To enforce a static contract, type a constructor value:
interface FooCtor {
  new (): Foo;
  bar(): void;
}

const Foo2: FooCtor = class Foo2 {
  bar() {}
  static bar() {}
};
```

---

### 9. Abstract classes cannot declare `abstract static`

You cannot force subclasses to implement a static method through the type system directly.

```ts
abstract class Base {
  abstract instanceMethod(): void; // ✅
  // static abstract foo(): void;  // ❌ 'abstract' cannot be used with 'static'

  static helper() {} // concrete static only
}
```

**Workaround:** type the constructor at call sites (see example 8), or use a factory function with a constraint.

---

### 10. No static members in interfaces; use declaration merging carefully

Classes and namespaces merge, which can simulate “static” additions. This can surprise tooling/serialization.

```ts
class Point {
  constructor(public x: number, public y: number) {}
}

namespace Point {
  export const origin = new Point(0, 0); // behaves like a static property
}

Point.origin; // works
```

Be careful: merged namespace members are not instance members and do not appear in `keyof Point` the same way in all contexts.

---

### 11. `keyof` splits instance vs. static views

```ts
class User {
  id = 0;
  static create() {}
}

type InstanceKeys = keyof User;          // "id"
type StaticKeys = keyof typeof User;     // "create" | "name" | "prototype" | ...
```

Edge case: `"prototype"` and built-ins appear in `keyof typeof Class` in many targets—filter them out if enumerating real static APIs.

---

### 12. Readonly static objects are shallowly readonly

```ts
class Config {
  static readonly opts = { debug: false };
}

// Config.opts = {} as any; // ❌ cannot reassign
Config.opts.debug = true;    // ✅ allowed (shallow)
```

Use `as const` or `Readonly<T>` for deeper protection, and prefer factory functions for runtime safety.

---

### 13. Decorators and metadata depend on static vs instance

With experimental decorators, a decorator on a static member receives the constructor as `target`; on an instance member it receives the prototype.

```ts
function log(target: any, propertyKey: string) {
  // target === Class for static, === Class.prototype for instance
  console.log("decorated", propertyKey, "on", target.constructor?.name ?? "prototype");
}

class Demo {
  @log static a = 1;
  @log        b = 2;
}
```

Edge case: with `useDefineForClassFields`, initialization semantics differ and decorator behavior/order may change—test across `tsconfig` targets.

---

### 14. Static getters/setters and inheritance gotchas

```ts
class Base {
  static get value() { return "base"; }
}

class Derived extends Base {
  static get value() { return super.value + "!" ; }
}

Derived.value; // "base!"
```

Edge case: you cannot “override” a static getter with a plain static property in a subclass—types won’t allow it because the accessor pair must match.

---

### 15. Factories + `new.target`

When static factory methods create instances, prefer returning `new this()` so subclassing preserves the concrete type (example 2). If you must use `new TargetClass()`, you hardcode the base type and break polymorphism.

```ts
class Base {
  static make(): Base {
    // ❌ Always Base, even when called as Derived.make()
    return new Base();
  }
}
```

---

### 16. Runtime enumerability

`Object.keys(Class)` returns *own, enumerable* static properties only; inherited statics from `Base` are not “own” of `Derived`.

```ts
class Base { static x = 1; }
class Derived extends Base { static y = 2; }

Object.keys(Derived); // ["y"] only (x is inherited, not own)
Object.getOwnPropertyNames(Derived); // includes non-enumerable built-ins + y
```

If you need all static APIs, walk the prototype chain manually.

---

### 17. Serialization and `JSON.stringify`

Instance methods/statics are ignored by `JSON.stringify` (only enumerable own props serialize). Static data that should travel needs explicit extraction.

```ts
class User {
  static source = "db";
  name = "Ada";
}

const u = new User();
JSON.stringify(u); // '{"name":"Ada"}' — static `source` omitted
```

---

### 18. Binding `this` for static callbacks in APIs

Frameworks often receive methods as callbacks. Static methods are unbound by default.

```ts
class Handler {
  static run() { /* uses this */ }
}

setTimeout(Handler.run, 0); // ❌ this lost

// ✅
setTimeout(() => Handler.run(), 0);
// or
setTimeout(Handler.run.bind(Handler), 0);
```

---

### Summary checklist

- Don’t reference instance type parameters from statics.  
- Remember `this` means the constructor in static methods; bind or arrow-wrap callbacks.  
- Cast `this.constructor` when crossing from instance to static.  
- Initialize statics in declaration order or use static blocks.  
- Use `#` for real private statics; `private` is compile-time only.  
- Don’t expect `implements` to check static members—type constructors explicitly.  
- Watch `keyof typeof Class` for inherited/built-in keys.  
- Keep readonly static objects deeply frozen if immutability matters.  
- Test static field/decorator behavior across `target` and `useDefineForClassFields`.

These are the edge cases that bite most often in production TypeScript.

# Static Typing in TypeScript: Complete Runnable Example

Static typing means types are checked **before** the program runs. TypeScript compiles to JavaScript, so the types disappear at runtime, but during development they catch mistakes like passing a `number` where a `string` is expected, using an unknown property, or forgetting a `case` in a `switch`.

Below is one complete example that demonstrates:

- primitive and literal types
- branded IDs
- enums and string unions
- interfaces and type aliases
- `readonly`, optional, and computed properties
- generics and interfaces
- classes with private state
- union types and discriminated unions
- type guards and narrowing
- exhaustiveness checks
- function overloads
- utility types (`Pick`, `Omit`, `Partial`, `Record`)
- a generic repository implementation

## `example.ts`

```ts
// ---------- Branded primitive types ----------
// A branded type prevents accidental mixing of different "kinds" of strings.
type UserId = string & { readonly __brand: "UserId" };

function makeUserId(raw: string): UserId {
  if (raw.trim().length === 0) {
    throw new Error("UserId cannot be empty");
  }
  return raw as UserId;
}

// ---------- Enums ----------
enum Role {
  Admin = "admin",
  Member = "member",
  Guest = "guest",
}

// ---------- Core domain types ----------
interface User {
  readonly id: UserId;
  name: string;
  email: string;
  role: Role;
  createdAt: Date;
}

type OrderStatus = "pending" | "paid" | "shipped" | "cancelled";

interface OrderItem {
  sku: string;
  name: string;
  price: number;
  quantity: number;
}

interface Order {
  id: string;
  userId: UserId;
  items: OrderItem[];
  status: OrderStatus;
  total: number;
}

// ---------- Utility types ----------
type UserPreview = Pick<User, "id" | "name" | "role">;
type UserUpdate = Partial<Omit<User, "id" | "createdAt">>;

// ---------- Generic repository abstraction ----------
interface Repository<T extends { id: string }> {
  get(id: string): T | undefined;
  save(entity: T): void;
  list(): readonly T[];
}

class InMemoryRepository<T extends { id: string }> implements Repository<T> {
  private readonly store = new Map<string, T>();

  get(id: string): T | undefined {
    return this.store.get(id);
  }

  save(entity: T): void {
    this.store.set(entity.id, entity);
  }

  list(): readonly T[] {
    return [...this.store.values()];
  }
}

// ---------- Services ----------
class UserService {
  constructor(private readonly users: Repository<User>) {}

  create(input: Omit<User, "id" | "createdAt">): User {
    const user: User = {
      id: makeUserId("user-" + Math.random().toString(36).slice(2)),
      createdAt: new Date(),
      ...input,
    };
    this.users.save(user);
    return user;
  }

  byId(id: UserId): User | undefined {
    return this.users.get(id);
  }

  update(id: UserId, changes: UserUpdate): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;

    const updated: User = {
      ...existing,
      ...changes,
      id: existing.id,
      createdAt: existing.createdAt,
    };

    this.users.save(updated);
    return updated;
  }
}

class OrderService {
  constructor(
    private readonly orders: Repository<Order>,
    private readonly users: UserService,
  ) {}

  create(input: { userId: UserId; items: OrderItem[] }): Order {
    const user = this.users.byId(input.userId);
    if (!user) throw new Error("Cannot create order for unknown user");

    const order: Order = {
      id: "order-" + Math.random().toString(36).slice(2),
      userId: input.userId,
      items: input.items,
      status: "pending",
      total: input.items.reduce(
        (sum, item) => sum + item.price * item.quantity,
        0,
      ),
    };

    this.orders.save(order);
    return order;
  }

  markPaid(orderId: string): Order {
    const order = this.orders.get(orderId);
    if (!order) throw new Error("Order not found");

    const updated: Order = { ...order, status: "paid" };
    this.orders.save(updated);
    return updated;
  }
}

// ---------- Discriminated union ----------
type PaymentResult =
  | { kind: "success"; transactionId: string }
  | { kind: "failure"; reason: string };

function processPayment(order: Order): PaymentResult {
  if (order.items.length === 0) {
    return { kind: "failure", reason: "Order has no items" };
  }
  if (order.total <= 0) {
    return { kind: "failure", reason: "Order total must be positive" };
  }
  return {
    kind: "success",
    transactionId: "txn-" + Math.random().toString(36).slice(2),
  };
}

// ---------- Type guard ----------
function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;

  const candidate = value as Partial<Order>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.userId === "string" &&
    Array.isArray(candidate.items) &&
    typeof candidate.status === "string" &&
    typeof candidate.total === "number"
  );
}

// ---------- Exhaustiveness checking ----------
function describeStatus(status: OrderStatus): string {
  switch (status) {
    case "pending":
      return "Awaiting payment";
    case "paid":
      return "Paid";
    case "shipped":
      return "Shipped";
    case "cancelled":
      return "Cancelled";
    default: {
      // TypeScript knows `status` is `never` here.
      const exhaustive: never = status;
      throw new Error(`Unhandled order status: ${exhaustive}`);
    }
  }
}

// ---------- Function overloads ----------
function formatMoney(amount: number): string;
function formatMoney(amount: number, currency: string): string;
function formatMoney(amount: number, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
  }).format(amount);
}

// ---------- Generic helper ----------
function groupBy<T, K extends string | number>(
  items: readonly T[],
  key: (item: T) => K,
): Record<K, T[]> {
  const result = {} as Record<K, T[]>;

  for (const item of items) {
    const groupKey = key(item);
    (result[groupKey] ??= []).push(item);
  }

  return result;
}

// ---------- Main ----------
function main(): void {
  const users = new InMemoryRepository<User>();
  const orders = new InMemoryRepository<Order>();

  const userService = new UserService(users);
  const orderService = new OrderService(orders, userService);

  const alice = userService.create({
    name: "Alice",
    email: "alice@example.com",
    role: Role.Admin,
  });

  const order = orderService.create({
    userId: alice.id,
    items: [
      {
        sku: "book-ts",
        name: "TypeScript Handbook",
        price: 39.99,
        quantity: 1,
      },
      {
        sku: "hoodie",
        name: "Developer Hoodie",
        price: 49.99,
        quantity: 2,
      },
    ],
  });

  const paidOrder = orderService.markPaid(order.id);

  // Update with a partial, type-safe patch.
  userService.update(alice.id, { role: Role.Member });

  const payment = processPayment(paidOrder);

  console.log("User preview (Pick):");
  const preview: UserPreview = {
    id: alice.id,
    name: alice.name,
    role: alice.role,
  };
  console.log(preview);

  console.log("\nOrder:");
  console.log({
    id: paidOrder.id,
    status: describeStatus(paidOrder.status),
    total: formatMoney(paidOrder.total),
    isOrder: isOrder(paidOrder),
  });

  console.log("\nPayment result (discriminated union):");
  if (payment.kind === "success") {
    console.log("Transaction:", payment.transactionId);
  } else {
    console.log("Failed:", payment.reason);
  }

  console.log("\nUsers grouped by role:");
  console.log(groupBy(users.list(), (user) => user.role));
}

main();
```

