## 3. Writing statistical helpers (idiomatic TS)

### 3.1 Basic aggregates

```ts
type NumArray = readonly number[];

export function mean(xs: NumArray): number {
  if (xs.length === 0) throw new Error("empty");
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function median(xs: NumArray): number {
  if (xs.length === 0) throw new Error("empty");
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

export function mode(xs: NumArray): number[] {
  const counts = new Map<number, number>();
  for (const v of xs) counts.set(v, (counts.get(v) ?? 0) + 1);
  const max = Math.max(...counts.values());
  return [...counts].filter(([, c]) => c === max).map(([v]) => v);
}
```

**Why `readonly number[]`?**  
Callers can pass `number[]`, `readonly number[]`, or tuples; the function promises not to mutate.

### 3.2 Variance / standard deviation

```ts
export function variance(xs: NumArray, population = true): number {
  const m = mean(xs);
  const sq = xs.reduce((acc, v) => acc + (v - m) ** 2, 0);
  const denom = population ? xs.length : xs.length - 1;
  return sq / denom;
}

export const stdDev = (xs: NumArray, population = true) =>
  Math.sqrt(variance(xs, population));
```

### 3.3 Generic numeric helpers (works with `bigint`? usually not; keep `number`)

```ts
function clamp<T extends number>(v: T, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}
```

### 3.4 Weighted mean (overloads for clarity)

```ts
function weightedMean(values: number[], weights: number[]): number;
function weightedMean(pairs: [number, number][]): number;
function weightedMean(a: any, b?: any): number {
  let vals: number[], ws: number[];
  if (Array.isArray(a[0])) {
    [vals, ws] = a.reduce(([v,w],[x,wt])=>[[...v,x],[...w,wt]], [[],[]]);
  } else { vals = a; ws = b; }
  const num = vals.reduce((s,v,i)=>s+v*ws[i],0);
  const den = ws.reduce((s,w)=>s+w,0);
  return num/den;
}
```

