## 5. Typical use cases

### A. Data normalization (z-scores)

```ts
function zScores(xs: number[]): number[] {
  const m = mean(xs);
  const sd = stdDev(xs);
  return xs.map(x => (x - m) / sd);
}
```

### B. Percentiles / quantiles

```ts
function quantile(xs: number[], q: number): number {
  const s = [...xs].sort((a,b)=>a-b);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos), hi = Math.ceil(pos);
  return s[lo] + (s[hi]-s[lo])*(pos-lo);
}
```

### C. Correlation (Pearson)

```ts
function pearson(x: number[], y: number[]): number {
  const mx = mean(x), my = mean(y);
  const num = x.reduce((s,xi,i)=>s+(xi-mx)*(y[i]-my),0);
  const den = Math.sqrt(
    x.reduce((s,xi)=>s+(xi-mx)**2,0) *
    y.reduce((s,yi)=>s+(yi-my)**2,0)
  );
  return den === 0 ? 0 : num/den;
}
```

### D. Monte Carlo / simulation

```ts
function estimatePi(n: number): number {
  let inside = 0;
  for (let i=0;i<n;i++){
    const x=Math.random(), y=Math.random();
    if (x*x+y*y <= 1) inside++;
  }
  return (4*inside)/n;
}
```

### E. Financial rounding (avoid float drift)

```ts
function roundMoney(v: number): number {
  return Math.round(v * 100) / 100;
}
```

