## 8. Minimal “stats toolkit” you can drop into a project

```ts
// stats.ts
export const sum = (xs: readonly number[]) =>
  xs.reduce((a,b)=>a+b,0);

export const mean = (xs: readonly number[]) =>
  xs.length ? sum(xs)/xs.length : NaN;

export const variance = (xs: readonly number[], pop=true) => {
  const m = mean(xs);
  const ss = xs.reduce((a,x)=>a+(x-m)**2,0);
  return ss/(pop?xs.length:xs.length-1);
};

export const stdDev = (xs: readonly number[], pop=true) =>
  Math.sqrt(variance(xs,pop));

export const covariance = (x: readonly number[], y: readonly number[]) => {
  if (x.length !== y.length) throw new Error("length mismatch");
  const mx=mean(x), my=mean(y);
  return x.reduce((s,xi,i)=>s+(xi-mx)*(y[i]-my),0)/x.length;
};
```

Usage:

```ts
import { mean, stdDev, covariance } from "./stats";

const a = [10, 20, 30];
const b = [1, 2, 3];
console.log(mean(a));          // 20
console.log(stdDev(a));        // ~8.16
console.log(covariance(a,b));  // ~6.67
```

---

### Summary

* **Idea:** TS gives you a typed `Math` object + a type system to express numeric contracts; statistics are just pure functions over `number[]`.
* **Syntax:** lean on `readonly`, generics, rest params, tuples, and `as const`.
* **Use cases:** normalization, percentiles, correlation, simulation, finance.
* **Practice:** guard empty arrays, copy before sort, validate finiteness, and reach for `simple-statistics`/`mathjs` when complexity grows.

## Typical mistake

```ts
function sampleStdDev(values: number[]): number {
  const n = values.length;
  const mean = values.reduce((sum, x) => sum + x, 0) / n;
  const variance = values.reduce((sum, x) => sum + (x - mean) ** 2, 0) / n;
  return Math.sqrt(variance);
}
```

### What is wrong

1. **Wrong denominator for a *sample* standard deviation**  
   Dividing by `n` gives the **population** variance. For a sample, the unbiased estimator divides by `n - 1` (Bessel’s correction).

2. **No guard for `n === 0` or `n === 1`**  
   - `n === 0`: `0 / 0` produces `NaN`, and the result silently becomes `NaN`.  
   - `n === 1`: sample variance is undefined because division by zero occurs.

3. **Potential numerical inaccuracy**  
   The two-pass formula can lose precision for large values or values with a large mean because `(x - mean) ** 2` may involve subtracting close numbers. Welford’s algorithm is more stable.

4. **No validation of input values**  
   `Infinity` or `NaN` in the array will propagate into the result without a clear signal.

---

## Corrected version

```ts
function sampleStdDev(values: readonly number[]): number | null {
  const n = values.length;

  // A sample standard deviation is undefined for fewer than 2 values.
  if (n < 2) return null;

  // Welford's online algorithm: numerically stable and single pass.
  let mean = 0;
  let m2 = 0; // sum of squared deviations

  for (let i = 0; i < n; i++) {
    const x = values[i];

    // Reject non-finite values explicitly instead of letting NaN spread.
    if (!Number.isFinite(x)) {
      throw new RangeError("sampleStdDev: all values must be finite numbers");
    }

    const delta = x - mean;
    mean += delta / (i + 1);

    const delta2 = x - mean;
    m2 += delta * delta2;
  }

  const sampleVariance = m2 / (n - 1);
  return Math.sqrt(sampleVariance);
}

// Example
const data = [10, 12, 23, 23, 16, 23, 21, 16];
console.log(sampleStdDev(data)); // ≈ 5.099...
```

---

## Why the corrected version is better

- Uses `n - 1` instead of `n`, matching the definition of **sample** standard deviation.
- Returns `null` for `n < 2`, making the undefined case explicit instead of returning `NaN`.
- Uses **Welford’s algorithm**, which updates the mean incrementally and avoids many catastrophic-cancellation problems.
- Validates that every input is finite, preventing silent `NaN` propagation.
- Accepts `readonly number[]`, so it does not accidentally mutate or require ownership of the input array.

### Quick rule of thumb

- Use denominator `n` for **population** statistics.
- Use denominator `n - 1` for **sample** statistics.
- Prefer numerically stable algorithms when values are large, clustered, or have a large mean.
- Always handle empty/single-element inputs deliberately in statistical code.

Here are common pitfalls when doing statistics/math in TypeScript, with idiomatic fixes.

## 1. Floating-point equality

JavaScript/TypeScript `number` is IEEE-754 double precision. Many decimal values are not exact.

```ts
console.log(0.1 + 0.2 === 0.3); // false

function nearlyEqual(a: number, b: number, eps = 1e-10): boolean {
  return Math.abs(a - b) <= eps * Math.max(1, Math.abs(a), Math.abs(b));
}

console.log(nearlyEqual(0.1 + 0.2, 0.3)); // true
```

Use tolerance-based comparisons for computed statistics. Also use `Number.isNaN` instead of `=== NaN`.

```ts
const x = NaN;
console.log(x === NaN);        // false
console.log(Number.isNaN(x));  // true
```

## 2. Sorting numbers lexicographically

`Array.prototype.sort` converts elements to strings by default.

```ts
const values = [10, 2, 1, 20];

console.log([...values].sort());        // [1, 10, 2, 20]
console.log([...values].sort((a, b) => a - b)); // [1, 2, 10, 20]
```

Always pass a numeric comparator. Also avoid mutating the original array when computing statistics.

```ts
function median(values: readonly number[]): number {
  if (values.length === 0) throw new Error("Cannot compute median of empty array");

  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);

  return sorted.length % 2 === 1
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}
```

## 3. `reduce` without an initial value

Calling `reduce` on an empty array throws. Type inference can also be awkward.

```ts
const empty: number[] = [];

// Throws: Reduce of empty array with no initial value
// empty.reduce((a, b) => a + b);

function sum(values: readonly number[]): number {
  return values.reduce<number>((total, value) => total + value, 0);
}

function mean(values: readonly number[]): number {
  if (values.length === 0) throw new Error("Cannot compute mean of empty array");
  return sum(values) / values.length;
}
```

## 4. Division by zero and empty inputs

Statistics code often divides by count, variance, or standard deviation.

```ts
function safeDivide(numerator: number, denominator: number): number {
  if (!Number.isFinite(numerator) || !Number.isFinite(denominator)) {
    throw new TypeError("Inputs must be finite numbers");
  }
  if (denominator === 0) {
    throw new Error("Division by zero");
  }
  return numerator / denominator;
}
```

Always validate array length before computing mean, variance, correlation, etc.

## 5. `Math.max(...hugeArray)` stack overflow

Spreading a very large array into `Math.max` can exceed call-stack limits.

```ts
const huge = Array.from({ length: 200_000 }, (_, i) => i);

// Risky for very large arrays:
// Math.max(...huge);

const max = huge.reduce((a, b) => Math.max(a, b), -Infinity);
const min = huge.reduce((a, b) => Math.min(a, b), Infinity);
```

## 6. Population vs. sample variance

Using `n` instead of `n - 1` gives population variance; using `n - 1` gives sample variance. Mixing them is a common statistical bug.

```ts
function variance(values: readonly number[], sample = false): number {
  if (values.length === 0) throw new Error("Empty array");
  if (sample && values.length < 2) throw new Error("Need at least 2 values for sample variance");

  const avg = mean(values);
  const squaredDiffs = values.map(v => (v - avg) ** 2);
  const sumSquaredDiffs = sum(squaredDiffs);

  const denominator = sample ? values.length - 1 : values.length;
  return sumSquaredDiffs / denominator;
}

function standardDeviation(values: readonly number[], sample = false): number {
  return Math.sqrt(variance(values, sample));
}
```

## 7. Catastrophic cancellation in mean/variance

The naive “sum of squares” formula can lose precision for large or shifted data.

```ts
// Less stable:
function naiveVariance(values: readonly number[]): number {
  const n = values.length;
  const sumX = sum(values);
  const sumX2 = sum(values.map(x => x * x));
  return (sumX2 - (sumX * sumX) / n) / n;
}

// More stable: Welford's online algorithm
function welfordVariance(values: readonly number[]): number {
  let mean = 0;
  let m2 = 0;

  values.forEach((x, i) => {
    const delta = x - mean;
    mean += delta / (i + 1);
    const delta2 = x - mean;
    m2 += delta * delta2;
  });

  return values.length === 0 ? NaN : m2 / values.length;
}
```

For serious numerical work, prefer stable algorithms or a vetted library such as `simple-statistics`, `mathjs`, or `d3-array`.

## 8. NaN and Infinity propagation

Invalid operations silently produce `NaN` or `Infinity`, which then spread through later calculations.

```ts
console.log(Math.sqrt(-1)); // NaN
console.log(1 / 0);         // Infinity
console.log(NaN + 5);       // NaN

function assertFinite(value: number, label = "value"): void {
  if (!Number.isFinite(value)) {
    throw new Error(`${label} must be finite, got ${value}`);
  }
}

function assertFiniteArray(values: readonly number[]): void {
  if (!values.every(Number.isFinite)) {
    throw new TypeError("All values must be finite numbers");
  }
}
```

Validate inputs at API boundaries instead of discovering `NaN` in final output.

## 9. Median, percentiles, and interpolation ambiguity

There are multiple percentile definitions. Also, even-count medians require averaging two middle values.

```ts
function percentile(sorted: readonly number[], p: number): number {
  if (sorted.length === 0) throw new Error("Empty array");
  if (p < 0 || p > 1) throw new RangeError("p must be between 0 and 1");

  const ordered = [...sorted].sort((a, b) => a - b);

  if (ordered.length === 1) return ordered[0];

  const index = (ordered.length - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);

  if (lower === upper) return ordered[lower];

  return ordered[lower] + (ordered[upper] - ordered[lower]) * (index - lower);
}
```

Document which percentile method your code uses. Do not mix Excel, NumPy, and custom definitions silently.

## 10. Mode is not always unique

A dataset can have multiple modes or no meaningful mode.

```ts
function modes(values: readonly number[]): number[] {
  if (values.length === 0) return [];

  const counts = new Map<number, number>();

  for (const value of values) {
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }

  const maxCount = Math.max(...counts.values());
  if (maxCount === 1) return []; // no repeated value

  return [...counts.entries()]
    .filter(([, count]) => count === maxCount)
    .map(([value]) => value);
}
```

Note: `Map` uses `SameValueZero`, so `NaN` keys are treated as equal. Floating-point values that differ by tiny amounts will be treated as different modes.

## 11. Correlation with zero variance

Pearson correlation divides by the product of standard deviations. If either variable is constant, the denominator is zero.

```ts
function pearson(xs: readonly number[], ys: readonly number[]): number {
  if (xs.length !== ys.length || xs.length < 2) {
    throw new Error("Arrays must have the same length and at least 2 values");
  }

  const mx = mean(xs);
  const my = mean(ys);

  let numerator = 0;
  let dx2 = 0;
  let dy2 = 0;

  for (let i = 0; i < xs.length; i++) {
    const dx = xs[i] - mx;
    const dy = ys[i] - my;
    numerator += dx * dy;
    dx2 += dx * dx;
    dy2 += dy * dy;
  }

  const denominator = Math.sqrt(dx2 * dy2);

  if (denominator === 0) {
    throw new Error("Correlation is undefined when one variable has zero variance");
  }

  return numerator / denominator;
}
```

## 12. `toFixed` returns a string and rounding is not “financial rounding”

`toFixed` is useful for display, but it returns a string and may surprise you with floating-point representation.

```ts
const value = 1.005;

console.log(value.toFixed(2)); // "1.00" or "1.01" depending on representation
console.log(Number(value.toFixed(2))); // number, but still not exact decimal arithmetic

// Better for display:
console.log(new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
}).format(value));
```

For money, billing, or exact decimal requirements, use a decimal library such as `decimal.js` or `big.js` instead of native `number`.

## 13. Rounding negative numbers

`Math.round` rounds half toward positive infinity, not necessarily “away from zero” or “banker’s rounding.”

```ts
console.log(Math.round(1.5));   // 2
console.log(Math.round(-1.5));  // -1

function roundHalfAwayFromZero(value: number, decimals = 0): number {
  const factor = 10 ** decimals;
  const scaled = value * factor;
  const rounded = scaled >= 0
    ? Math.floor(scaled + 0.5)
    : Math.ceil(scaled - 0.5);
  return rounded / factor;
}
```

Define rounding behavior explicitly in statistical reports.

## 14. Random number range and security mistakes

`Math.random()` is not cryptographically secure and returns `[0, 1)`. Common off-by-one errors occur in integer ranges.

```ts
// [0, 1)
const r = Math.random();

// Inclusive integer range [min, max]
function randomInt(min: number, max: number): number {
  if (!Number.isInteger(min) || !Number.isInteger(max) || min > max) {
    throw new RangeError("Invalid integer range");
  }
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Cryptographically secure integer in [0, maxExclusive)
function secureRandomInt(maxExclusive: number): number {
  if (!Number.isInteger(maxExclusive) || maxExclusive <= 0) {
    throw new RangeError("maxExclusive must be a positive integer");
  }

  const maxUint32 = 0x1_0000_0000;
  const limit = maxUint32 - (maxUint32 % maxExclusive);
  const buffer = new Uint32Array(1);

  let value: number;
  do {
    crypto.getRandomValues(buffer);
    value = buffer[0];
  } while (value >= limit);

  return value % maxExclusive;
}
```

Use `crypto.getRandomValues` or `crypto.randomUUID` for security-sensitive sampling, tokens, or random IDs.

## 15. BigInt and `number` do not mix

TypeScript correctly prevents mixing `bigint` and `number` in arithmetic, but large integer precision is still a pitfall with `number`.

```ts
const a = 9007199254740992; // 2^53
const b = 9007199254740993;

console.log(a === b); // true, precision lost

const x = 9007199254740993n;
const y = 1n;

// const bad = x + 1; // Type error
const good = x + y;   // 9007199254740994n
```

Use `bigint` for exact large integers, but keep it separate from floating-point statistics. Convert carefully and validate ranges.

## 16. Null, undefined, and loose input data

Real datasets often contain missing or invalid values. Statistical functions should not silently coerce them.

```ts
function cleanNumbers(values: readonly unknown[]): number[] {
  return values.filter((v): v is number =>
    typeof v === "number" && Number.isFinite(v)
  );
}

const raw = [1, 2, null, "3", NaN, 4];
const clean = cleanNumbers(raw); // [1, 2, 4]
```

Decide explicitly whether to drop, impute, or reject missing values. Do not let `null + 1` become `1`.

## 17. Date/time math and time zones

Date differences are in milliseconds, and calendar math is affected by time zones and DST.

```ts
const start = new Date("2024-03-09T00:00:00-05:00");
const end = new Date("2024-03-10T00:00:00-04:00");

const days = (end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24);
console.log(days); // 1, but calendar-day logic may differ
```

For calendar-aware statistics, use a date library such as `date-fns`, `luxon`, or `Temporal` when available.

## Practical checklist

- Validate all inputs with `Number.isFinite`.
- Sort numeric arrays with `(a, b) => a - b`.
- Copy arrays before sorting.
- Guard empty arrays and zero denominators.
- Distinguish population vs. sample formulas.
- Use stable algorithms for variance/standard deviation.
- Avoid spreading huge arrays into `Math.max`/`Math.min`.
- Do not use native `number` for exact decimal money calculations.
- Document percentile, rounding, and mode behavior.
- Use secure randomness for security-sensitive code.

For production statistical code, consider `simple-statistics`, `d3-array`, `mathjs`, or `ml-matrix` rather than reimplementing every formula.

## Exercise

**Task:** Write a small, reusable TypeScript module that computes common descriptive statistics for a numeric array and a Pearson correlation between two arrays.

Requirements:
- Functions: `mean`, `median`, `variance` (population), `stdDev` (sample, `n-1`), `min`, `max`, `pearson`.
- Handle edge cases: empty arrays, mismatched lengths, non-finite values.
- Return `null` when a statistic is undefined (e.g., empty input, zero variance).
- Keep everything typed and pure (no mutation).

---

## Step-by-step solution

### 1. Define types and validation helpers

```ts
export type StatResult = number | null;

const isFiniteNumber = (x: unknown): x is number =>
  typeof x === "number" && Number.isFinite(x);

const assertFiniteArray = (xs: number[]): void => {
  if (!Array.isArray(xs) || xs.some((x) => !isFiniteNumber(x))) {
    throw new TypeError("Input must be an array of finite numbers");
  }
};
```

### 2. Basic aggregates

```ts
export function mean(xs: number[]): StatResult {
  assertFiniteArray(xs);
  if (xs.length === 0) return null;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function min(xs: number[]): StatResult {
  assertFiniteArray(xs);
  return xs.length === 0 ? null : Math.min(...xs);
}

export function max(xs: number[]): StatResult {
  assertFiniteArray(xs);
  return xs.length === 0 ? null : Math.max(...xs);
}
```

### 3. Median (sort without mutating original)

```ts
export function median(xs: number[]): StatResult {
  assertFiniteArray(xs);
  if (xs.length === 0) return null;
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}
```

### 4. Variance and standard deviation

Population variance uses `n`; sample standard deviation uses `n-1`.

```ts
export function variance(xs: number[]): StatResult {
  const m = mean(xs);
  if (m === null || xs.length === 0) return null;
  const sumSq = xs.reduce((acc, x) => acc + (x - m) ** 2, 0);
  return sumSq / xs.length; // population variance
}

export function stdDev(xs: number[]): StatResult {
  const v = variance(xs);
  if (v === null) return null;
  // sample std dev uses n-1; convert population variance accordingly
  if (xs.length < 2) return null;
  const sampleVariance = (v * xs.length) / (xs.length - 1);
  return Math.sqrt(sampleVariance);
}
```

### 5. Pearson correlation

```ts
export function pearson(xs: number[], ys: number[]): StatResult {
  assertFiniteArray(xs);
  assertFiniteArray(ys);
  if (xs.length === 0 || xs.length !== ys.length) return null;

  const mx = mean(xs);
  const my = mean(ys);
  if (mx === null || my === null) return null;

  let num = 0;
  let dx2 = 0;
  let dy2 = 0;
  for (let i = 0; i < xs.length; i++) {
    const dx = xs[i] - mx;
    const dy = ys[i] - my;
    num += dx * dy;
    dx2 += dx * dx;
    dy2 += dy * dy;
  }
  const denom = Math.sqrt(dx2 * dy2);
  return denom === 0 ? null : num / denom;
}
```

