## Final solution (complete module)

```ts
// stats.ts
export type StatResult = number | null;

const isFiniteNumber = (x: unknown): x is number =>
  typeof x === "number" && Number.isFinite(x);

const assertFiniteArray = (xs: number[]): void => {
  if (!Array.isArray(xs) || xs.some((x) => !isFiniteNumber(x))) {
    throw new TypeError("Input must be an array of finite numbers");
  }
};

export function mean(xs: number[]): StatResult {
  assertFiniteArray(xs);
  if (xs.length === 0) return null;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function min(xs: number[]): StatResult {
  assertFiniteArray(xs);
  return xs.length === 0 ? null : Math.min(...xs);
}

export function max(xs: number[]): StatResult {
  assertFiniteArray(xs);
  return xs.length === 0 ? null : Math.max(...xs);
}

export function median(xs: number[]): StatResult {
  assertFiniteArray(xs);
  if (xs.length === 0) return null;
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

export function variance(xs: number[]): StatResult {
  const m = mean(xs);
  if (m === null || xs.length === 0) return null;
  const sumSq = xs.reduce((acc, x) => acc + (x - m) ** 2, 0);
  return sumSq / xs.length;
}

export function stdDev(xs: number[]): StatResult {
  const v = variance(xs);
  if (v === null || xs.length < 2) return null;
  const sampleVariance = (v * xs.length) / (xs.length - 1);
  return Math.sqrt(sampleVariance);
}

export function pearson(xs: number[], ys: number[]): StatResult {
  assertFiniteArray(xs);
  assertFiniteArray(ys);
  if (xs.length === 0 || xs.length !== ys.length) return null;

  const mx = mean(xs);
  const my = mean(ys);
  if (mx === null || my === null) return null;

  let num = 0;
  let dx2 = 0;
  let dy2 = 0;
  for (let i = 0; i < xs.length; i++) {
    const dx = xs[i] - mx;
    const dy = ys[i] - my;
    num += dx * dy;
    dx2 += dx * dx;
    dy2 += dy * dy;
  }
  const denom = Math.sqrt(dx2 * dy2);
  return denom === 0 ? null : num / denom;
}
```

