## Core implementation (TypeScript)

```ts
/**
 * Core statistics & math utilities.
 * All functions are pure and do not mutate their inputs.
 */

export type NumericArray = number[];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function assertNonEmpty(xs: number[], fn: string): void {
  if (xs.length === 0) throw new Error(`${fn}: input array must not be empty`);
}

function assertSameLength(a: number[], b: number[], fn: string): void {
  if (a.length !== b.length || a.length === 0) {
    throw new Error(`${fn}: arrays must have the same non-zero length`);
  }
}

// ---------------------------------------------------------------------------
// Basic arithmetic
// ---------------------------------------------------------------------------

/** Kahan summation for better floating-point accuracy. */
export function sum(xs: number[]): number {
  let total = 0;
  let compensation = 0; // running correction
  for (const x of xs) {
    const y = x - compensation;
    const t = total + y;
    compensation = (t - total) - y;
    total = t;
  }
  return total;
}

export function mean(xs: number[]): number {
  assertNonEmpty(xs, "mean");
  return sum(xs) / xs.length;
}

export function median(xs: number[]): number {
  assertNonEmpty(xs, "median");
  const sorted = [...xs].sort((a, b) => a - b);
  const n = sorted.length;
  const mid = Math.floor(n / 2);
  return n % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

/** Returns all modes (multimodal data is possible). */
export function mode(xs: number[]): number[] {
  assertNonEmpty(xs, "mode");
  const counts = new Map<number, number>();
  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1);
  const maxCount = Math.max(...counts.values());
  return [...counts.entries()]
    .filter(([, c]) => c === maxCount)
    .map(([v]) => v);
}

// ---------------------------------------------------------------------------
// Dispersion
// ---------------------------------------------------------------------------

export function variance(xs: number[], sample = false): number {
  assertNonEmpty(xs, "variance");
  const m = mean(xs);
  const sq = xs.reduce((acc, x) => acc + (x - m) ** 2, 0);
  const denom = sample ? xs.length - 1 : xs.length;
  if (denom <= 0) throw new Error("variance: sample variance requires at least 2 values");
  return sq / denom;
}

export function std(xs: number[], sample = false): number {
  return Math.sqrt(variance(xs, sample));
}

export function min(xs: number[]): number {
  assertNonEmpty(xs, "min");
  return Math.min(...xs);
}

export function max(xs: number[]): number {
  assertNonEmpty(xs, "max");
  return Math.max(...xs);
}

export function range(xs: number[]): number {
  return max(xs) - min(xs);
}

/**
 * Percentile via linear interpolation (method used by NumPy default).
 * p in [0, 100].
 */
export function percentile(xs: number[], p: number): number {
  assertNonEmpty(xs, "percentile");
  if (p < 0 || p > 100) throw new Error("percentile: p must be in [0, 100]");
  const sorted = [...xs].sort((a, b) => a - b);
  if (p === 0) return sorted[0];
  if (p === 100) return sorted[sorted.length - 1];

  const idx = (p / 100) * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  const weight = idx - lo;
  return sorted[lo] * (1 - weight) + sorted[hi] * weight;
}

export function quartiles(xs: number[]): { q1: number; median: number; q3: number } {
  return {
    q1: percentile(xs, 25),
    median: percentile(xs, 50),
    q3: percentile(xs, 75),
  };
}

export function iqr(xs: number[]): number {
  const q = quartiles(xs);
  return q.q3 - q.q1;
}

// ---------------------------------------------------------------------------
// Shape
// ---------------------------------------------------------------------------

export function skewness(xs: number[]): number {
  assertNonEmpty(xs, "skewness");
  const m = mean(xs);
  const s = std(xs, false); // population std for shape measures
  if (s === 0) return NaN;
  return xs.reduce((acc, x) => acc + ((x - m) / s) ** 3, 0) / xs.length;
}

/** Excess kurtosis (normal distribution has 0). */
export function kurtosis(xs: number[]): number {
  assertNonEmpty(xs, "kurtosis");
  const m = mean(xs);
  const s = std(xs, false);
  if (s === 0) return NaN;
  const fourth = xs.reduce((acc, x) => acc + ((x - m) / s) ** 4, 0) / xs.length;
  return fourth - 3;
}

// ---------------------------------------------------------------------------
// Association & regression
// ---------------------------------------------------------------------------

export function covariance(xs: number[], ys: number[], sample = false): number {
  assertSameLength(xs, ys, "covariance");
  const mx = mean(xs);
  const my = mean(ys);
  const sumProd = xs.reduce((acc, x, i) => acc + (x - mx) * (ys[i] - my), 0);
  const denom = sample ? xs.length - 1 : xs.length;
  if (denom <= 0) throw new Error("covariance: sample variant requires at least 2 values");
  return sumProd / denom;
}

export function correlation(xs: number[], ys: number[]): number {
  // Pearson r is scale-invariant, so population denominators cancel cleanly.
  const cov = covariance(xs, ys, false);
  const sx = std(xs, false);
  const sy = std(ys, false);
  if (sx === 0 || sy === 0) return NaN; // no linear relationship definable
  return cov / (sx * sy);
}

export function linearRegression(
  xs: number[],
  ys: number[]
): { slope: number; intercept: number } {
  assertSameLength(xs, ys, "linearRegression");
  if (xs.length < 2) throw new Error("linearRegression: need at least 2 points");
  const mx = mean(xs);
  const my = mean(ys);
  const sxx = xs.reduce((acc, x) => acc + (x - mx) ** 2, 0);
  const sxy = xs.reduce((acc, x, i) => acc + (x - mx) * (ys[i] - my), 0);
  const slope = sxx === 0 ? NaN : sxy / sxx;
  const intercept = my - slope * mx;
  return { slope, intercept };
}

// ---------------------------------------------------------------------------
// General math utilities
// ---------------------------------------------------------------------------

export function factorial(n: number): number {
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("factorial: requires a non-negative integer");
  }
  if (n > 170) return Infinity; // beyond JS safe numeric range
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result;
}

export function gcd(a: number, b: number): number {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b !== 0) [a, b] = [b, a % b];
  return a;
}

export function lcm(a: number, b: number): number {
  if (a === 0 || b === 0) return 0;
  return Math.abs(a * b) / gcd(a, b);
}

export function isPrime(n: number): boolean {
  if (!Number.isInteger(n) || n < 2) return false;
  if (n % 2 === 0) return n === 2;
  const limit = Math.sqrt(n);
  for (let i = 3; i <= limit; i += 2) {
    if (n % i === 0) return false;
  }
  return true;
}

export const clamp = (x: number, lo: number, hi: number): number =>
  Math.min(Math.max(x, lo), hi);

export const lerp = (a: number, b: number, t: number): number =>
  a + (b - a) * t;

export function randomInt(min: number, max: number): number {
  if (!Number.isInteger(min) || !Number.isInteger(max) || min > max) {
    throw new Error("randomInt: min/max must be integers with min <= max");
  }
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

/** Normal (Gaussian) probability density function. */
export function normalPdf(x: number, mu = 0, sigma = 1): number {
  if (sigma <= 0) throw new Error("normalPdf: sigma must be > 0");
  const z = (x - mu) / sigma;
  return Math.exp(-0.5 * z * z) / (sigma * Math.sqrt(2 * Math.PI));
}

// ---------------------------------------------------------------------------
// Optional convenience wrapper
// ---------------------------------------------------------------------------

export class DescriptiveStats {
  constructor(private readonly data: number[]) {
    if (data.length === 0) throw new Error("DescriptiveStats: data must not be empty");
  }

  get mean() { return mean(this.data); }
  get median() { return median(this.data); }
  get modes() { return mode(this.data); }
  get variance() { return variance(this.data, false); }
  get sampleVariance() { return variance(this.data, true); }
  get std() { return std(this.data, false); }
  get sampleStd() { return std(this.data, true); }
  get min() { return min(this.data); }
  get max() { return max(this.data); }
  get range() { return range(this.data); }
  get skewness() { return skewness(this.data); }
  get kurtosis() { return kurtosis(this.data); }

  percentile(p: number): number {
    return percentile(this.data, p);
  }
}
```

