/* ------------------------------------------------------------------ */

// Avoid repeated concatenation in hot loops; use array + join
const lines: string[] = [];
for (let i = 0; i < 5; i++) lines.push(`line ${i}`);
const big = lines.join("\n");
console.log("big text bytes:", new TextEncoder().encode(big).length);

// Streaming-ish chunk processing
function* chunks(str: string, size: number): Generator<string> {
  for (let i = 0; i < str.length; i += size) yield str.slice(i, i + size);
}
console.log("chunks:", [...chunks("abcdefghij", 3)]);

/* ------------------------------------------------------------------ */
/* 12. Utility: safe truncation by grapheme                            */
/* ------------------------------------------------------------------ */

function truncateGraphemes(s: string, max: number, suffix = "…"): string {
  const segs = [...new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(s)].map(x => x.segment);
  if (segs.length <= max) return s;
  return segs.slice(0, max).join("") + suffix;
}

console.log("trunc:", truncateGraphemes("Hello 👨‍👩‍👧‍👦 world", 6));
