export class Account {
  private balance: number;
  private readonly mutex = new AsyncMutex();

  constructor(initial: number) {
    if (initial < 0) throw new Error("initial balance must be >= 0");
    this.balance = initial;
  }

  async withdraw(amount: number): Promise<boolean> {
    if (amount < 0) throw new Error("amount must be >= 0");

    await this.mutex.acquire();
    try {
      if (this.balance < amount) return false;

      // Critical section: any await here is protected
      await this.auditLog(amount);

      this.balance -= amount;
      return true;
    } finally {
      this.mutex.release();
    }
  }

  get balance(): number {
    return this.balance;
  }

  private async auditLog(amount: number): Promise<void> {
    await new Promise((r) => setTimeout(r, 5));
  }
}

// demo.ts
import { Account } from "./account";

async function main() {
  const acc = new Account(100);
  const results = await Promise.all(
    Array.from({ length: 10 }, () => acc.withdraw(30))
  );
