main();
```

### Why this works

- `acquire()` serializes entry into the critical section.
- The hand-off (`next()` without setting `locked=false`) prevents a waiter from being preempted by a newly arriving caller.
- `finally` guarantees release even on thrown errors.
- All reads and writes of `balance` happen while the mutex is held, so the check-then-act sequence is atomic with respect to other `withdraw` calls.

## Synchronization and locks in TypeScript

### What problem do locks solve?
TypeScript (JavaScript) is **single-threaded on the main thread** and uses an **event loop**. “Concurrency” usually comes from:

- `async/await` and promises
- timers / I/O callbacks
- Web Workers / Node.js `worker_threads`
- Shared memory via `SharedArrayBuffer`

So TypeScript does not usually need OS-level mutexes for normal object access. Instead, we use **cooperative async locks**:

- **Mutex**: only one async task can hold it at a time.
- **Semaphore**: at most `N` tasks can hold it at a time.
- **Read/write lock**: many readers or one writer.
- **Condition variable**: wait until some state becomes true.

These are *not preemptive*. If a task never calls `release()`, everyone waits forever. Therefore every acquisition must be released in a `finally` block.

### Important TypeScript/JS realities
1. **No true thread blocking on the main thread** — `Atomics.wait` would block the whole page/tab.
2. **Locks are cooperative** — they serialize async critical sections, not CPU instructions.
3. **Shared memory needs real atomics** — use `SharedArrayBuffer` + `Atomics` in workers.
4. **Avoid deadlocks** — always acquire locks in a consistent global order.
5. **Avoid reentrancy confusion** — a simple mutex is usually non-reentrant. If the same async chain acquires it twice, it deadlocks.

---

## Clean implementation

Below is a small, production-style async synchronization toolkit.

```ts
/**
 * AsyncMutex
 *
 * A cooperative mutual-exclusion lock for async code.
 *
 * Usage:
 *   const mutex = new AsyncMutex();
 *   await mutex.acquire();
 *   try {
 *     // critical section
 *   } finally {
 *     mutex.release();
 *   }
 *
 * Or use withLock() to avoid forgetting release().
 */
export class AsyncMutex {
  private locked = false;
  private readonly waiters: Array<() => void> = [];

  /**
   * Acquire the lock. Resolves when this caller becomes the owner.
   */
  acquire(): Promise<void> {
    if (!this.locked) {
      this.locked = true;
      return Promise.resolve();
    }

    // Queue a resolver. release() will call it later.
    return new Promise<void>((resolve) => {
      this.waiters.push(resolve);
    });
  }

  /**
   * Release the lock. If waiters exist, hand ownership to the next one.
   * The lock stays locked until no waiters remain.
   */
  release(): void {
    const next = this.waiters.shift();

    if (next) {
      // Ownership transfers directly to the next waiter.
      next();
    } else {
      this.locked = false;
    }
  }

  /**
   * Run a critical section with automatic release.
   */
  async withLock<T>(fn: () => T | Promise<T>): Promise<T> {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }

  /**
   * Optional: cancellable acquisition. Useful for timeouts or aborting UI work.
   */
  acquireWithSignal(signal?: AbortSignal): Promise<void> {
    if (signal?.aborted) {
      return Promise.reject(new DOMException("Aborted", "AbortError"));
    }

    if (!this.locked) {
      this.locked = true;
      return Promise.resolve();
    }

    return new Promise<void>((resolve, reject) => {
      const onAbort = () => {
        // Remove this waiter if still queued.
        const index = this.waiters.indexOf(resolveWrapped);
        if (index >= 0) this.waiters.splice(index, 1);
        reject(new DOMException("Aborted", "AbortError"));
      };

      const resolveWrapped = () => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      };

      this.waiters.push(resolveWrapped);
      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }
}
```

```ts
/**
 * AsyncSemaphore
 *
 * Allows up to `permits` concurrent holders.
 */
export class AsyncSemaphore {
  private permits: number;
  private readonly waiters: Array<() => void> = [];

  constructor(permits: number) {
    if (!Number.isInteger(permits) || permits < 0) {
      throw new RangeError("permits must be a non-negative integer");
    }
    this.permits = permits;
  }

  async acquire(): Promise<void> {
    if (this.permits > 0) {
      this.permits--;
      return;
    }

    return new Promise<void>((resolve) => {
      this.waiters.push(resolve);
    });
  }

  release(): void {
    const next = this.waiters.shift();

    if (next) {
      // Hand the permit directly to the next waiter.
      next();
    } else {
      this.permits++;
    }
  }

  async withPermit<T>(fn: () => T | Promise<T>): Promise<T> {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }

  get availablePermits(): number {
    return this.permits;
  }
}
```

```ts
/**
 * AsyncReadWriteLock
 *
 * Many readers OR one writer.
 * This implementation prefers writers to avoid writer starvation.
 */
export class AsyncReadWriteLock {
  private readers = 0;
  private writerActive = false;

  private readonly readWaiters: Array<() => void> = [];
  private readonly writeWaiters: Array<() => void> = [];

  async acquireRead(): Promise<void> {
    if (!this.writerActive && this.writeWaiters.length === 0) {
      this.readers++;
      return;
    }

    return new Promise<void>((resolve) => {
      this.readWaiters.push(() => {
        this.readers++;
        resolve();
      });
    });
  }

  releaseRead(): void {
    this.readers--;

    if (this.readers === 0 && this.writeWaiters.length > 0) {
      const nextWriter = this.writeWaiters.shift()!;
      this.writerActive = true;
      nextWriter();
    }
  }

  async acquireWrite(): Promise<void> {
    if (!this.writerActive && this.readers === 0) {
      this.writerActive = true;
      return;
    }

    return new Promise<void>((resolve) => {
      this.writeWaiters.push(() => {
        this.writerActive = true;
        resolve();
      });
    });
  }

  releaseWrite(): void {
    this.writerActive = false;

    // Prefer waking writers first to avoid starvation.
    if (this.writeWaiters.length > 0) {
      const nextWriter = this.writeWaiters.shift()!;
      this.writerActive = true;
      nextWriter();
      return;
    }

    // Wake all waiting readers.
    while (this.readWaiters.length > 0) {
      const nextReader = this.readWaiters.shift()!;
      nextReader();
    }
  }

  async withRead<T>(fn: () => T | Promise<T>): Promise<T> {
    await this.acquireRead();
    try {
      return await fn();
    } finally {
      this.releaseRead();
    }
  }

  async withWrite<T>(fn: () => T | Promise<T>): Promise<T> {
    await this.acquireWrite();
    try {
      return await fn();
    } finally {
      this.releaseWrite();
    }
  }
}
```

