## Example: protecting shared state

```ts
import { AsyncMutex } from "./locks";

class BankAccount {
  private balance = 100;
  private readonly mutex = new AsyncMutex();

  async withdraw(amount: number): Promise<boolean> {
    return this.mutex.withLock(async () => {
      if (this.balance < amount) return false;
      // Simulate async work, e.g. database call.
      await delay(10);
      this.balance -= amount;
      return true;
    });
  }

  async getBalance(): Promise<number> {
    return this.mutex.withLock(() => this.balance);
  }
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
```

Without the mutex, two concurrent withdrawals could both see `balance = 100` and both succeed.

