## 3. The tests (`tests/cart.test.ts`)

```ts
import { ShoppingCart } from '../src/cart';

describe('ShoppingCart', () => {
  it('starts empty with total 0', () => {
    const cart = new ShoppingCart();
    expect(cart.total()).toBe(0);
    expect(cart.itemCount()).toBe(0);
  });

  it('adds an item and computes total', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1.5);
    expect(cart.total()).toBe(1.5);
    expect(cart.itemCount()).toBe(1);
  });

  it('multiplies price by quantity', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1.5, 3);
    expect(cart.total()).toBe(4.5);
  });

  it('merges quantities for the same product', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1.5, 2);
    cart.add('apple', 1.5, 3);
    expect(cart.itemCount()).toBe(5);
    expect(cart.total()).toBe(7.5);
  });

  it('removes a partial quantity', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1.5, 5);
    cart.remove('apple', 2);
    expect(cart.itemCount()).toBe(3);
    expect(cart.total()).toBe(4.5);
  });

  it('removes the whole line when quantity exceeds stock', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1.5, 2);
    cart.remove('apple'); // remove all
    expect(cart.total()).toBe(0);
    expect(cart.itemCount()).toBe(0);
  });

  it('applies a percentage discount', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 10, 2);
    cart.applyDiscount(10);
    expect(cart.total()).toBe(18);
  });

  it('rounds totals to 2 decimals (avoids float drift)', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 0.1, 3); // 0.30000000000000004 in JS
    expect(cart.total()).toBe(0.3);
  });

  it('validates inputs', () => {
    const cart = new ShoppingCart();
    expect(() => cart.add('', 1)).toThrow();
    expect(() => cart.add('x', 0)).toThrow();
    expect(() => cart.add('x', 1, 0)).toThrow();
    expect(() => cart.add('x', 1, 1.5)).toThrow();
    expect(() => cart.applyDiscount(150)).toThrow();
    cart.add('apple', 1, 2);
    expect(() => cart.remove('apple', 0)).toThrow();
  });

  it('clears everything', () => {
    const cart = new ShoppingCart();
    cart.add('apple', 1, 2);
    cart.applyDiscount(5);
    cart.clear();
    expect(cart.total()).toBe(0);
    expect(cart.itemCount()).toBe(0);
  });
});
```

Run `npm test` now → **all red** (module/methods don’t exist). That’s the intended first step.

---

## 4. The implementation (`src/cart.ts`)

Written to satisfy the tests above with the smallest reasonable API:

```ts
export interface CartLine {
  readonly productId: string;
  readonly price: number;
  quantity: number;
}

export class ShoppingCart {
  private readonly lines = new Map<string, CartLine>();
  private discountPercent = 0;

  add(productId: string, price: number, quantity = 1): void {
    if (!productId || typeof productId !== 'string') {
      throw new Error('productId must be a non-empty string');
    }
    if (!Number.isFinite(price) || price <= 0) {
      throw new Error('price must be a positive finite number');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('quantity must be a positive integer');
    }

    const existing = this.lines.get(productId);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.lines.set(productId, { productId, price, quantity });
    }
  }

  remove(productId: string, quantity: number = Infinity): void {
    const existing = this.lines.get(productId);
    if (!existing) return;

    if (quantity !== Infinity) {
      if (!Number.isInteger(quantity) || quantity <= 0) {
        throw new Error('quantity must be a positive integer');
      }
    }

    if (quantity >= existing.quantity) {
      this.lines.delete(productId);
    } else {
      existing.quantity -= quantity;
    }
  }

  applyDiscount(percent: number): void {
    if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
      throw new Error('discount must be between 0 and 100');
    }
    this.discountPercent = percent;
  }

  total(): number {
    let subtotal = 0;
    for (const line of this.lines.values()) {
      subtotal += line.price * line.quantity;
    }
    const discounted = subtotal * (1 - this.discountPercent / 100);
    return Math.round(discounted * 100) / 100;
  }

  itemCount(): number {
    let count = 0;
    for (const line of this.lines.values()) count += line.quantity;
    return count;
  }

  clear(): void {
    this.lines.clear();
    this.discountPercent = 0;
  }
}
```

Run `npm test` now → **all green**.

