```ts
// discount.ts
export type CustomerType = 'regular' | 'premium' | 'vip';

const customerDiscounts: Record<CustomerType, number> = {
  regular: 0,
  premium: 0.05,
  vip: 0.1,
};

const couponDiscounts: Record<string, number> = {
  SAVE10: 0.1,
  SAVE20: 0.2,
};

const validCustomerTypes = new Set<CustomerType>([
  'regular',
  'premium',
  'vip',
]);

export function calculateFinalPrice(
  price: number,
  customerType: CustomerType,
  couponCode?: string
): number {
  if (!Number.isFinite(price) || price < 0) {
    throw new Error('Price must be a non-negative finite number');
  }

  if (!validCustomerTypes.has(customerType)) {
    throw new Error('Invalid customer type');
  }

  const customerDiscount = customerDiscounts[customerType];
  const couponDiscount = couponCode
    ? couponDiscounts[couponCode] ?? 0
    : 0;

  const finalPrice =
    price * (1 - customerDiscount) * (1 - couponDiscount);

  return Math.max(0, Math.round(finalPrice * 100) / 100);
}
```

