import { performance } from 'perf_hooks';

// ---------- Types ----------

export interface Complexity {
  time: string;
  space: string;
}

export interface Measurement {
  ms: number;
  heapDeltaBytes: number;
}

// ---------- Measurement helpers ----------

export function measure<T>(fn: () => T): { result: T } & Measurement {
  if (typeof global.gc === 'function') global.gc();
  const beforeHeap = process.memoryUsage().heapUsed;
  const t0 = performance.now();
  const result = fn();
  const t1 = performance.now();
  const afterHeap = process.memoryUsage().heapUsed;
  return { result, ms: t1 - t0, heapDeltaBytes: afterHeap - beforeHeap };
}

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 === 1 ? s[m] : (s[m - 1] + s[m]) / 2;
}

// ---------- Algorithms with documented (theoretical) complexity ----------

// O(1) time, O(1) space
export function constantTime(arr: number[]): number {
  return arr.length === 0 ? 0 : arr[0];
}

// O(n) time, O(1) space
export function linearSum(arr: number[]): number {
  let s = 0;
  for (const x of arr) s += x;
  return s;
}

// O(n^2) time, O(1) space
export function quadraticPairs(arr: number[]): number {
  let c = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < arr.length; j++) c++;
  }
  return c;
}

// O(log n) time, O(1) space
export function binarySearch(sorted: number[], target: number): number {
  let lo = 0;
  let hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

// O(n log n) time, O(n) space (recursive + merge buffers)
export function mergeSort(arr: number[]): number[] {
  if (arr.length <= 1) return arr.slice();
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  const out: number[] = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    out.push(left[i] <= right[j] ? left[i++] : right[j++]);
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

// O(2^n) time, O(n) space (call stack)
export function fibNaive(n: number): number {
  if (n <= 1) return n;
  return fibNaive(n - 1) + fibNaive(n - 2);
}

// ---------- Space-complexity demonstrations ----------

// O(n) extra space
export function makeLinearBuffer(n: number): number[] {
  return new Array<number>(n).fill(0);
}

// O(n^2) extra space
export function makeMatrix(n: number): number[][] {
  const m: number[][] = [];
  for (let i = 0; i < n; i++) m.push(new Array<number>(n).fill(0));
  return m;
}

// ---------- Benchmark harness ----------

interface AlgoSpec {
  name: string;
  complexity: Complexity;
  maxN: number;
  run: (n: number) => void;
}

const algos: AlgoSpec[] = [
  {
    name: 'constantTime (arr[0])',
    complexity: { time: 'O(1)', space: 'O(1)' },
    maxN: 1_000_000,
    run: (n) => {
