      linearSum(arr);
    },
  },
  {
    name: 'binarySearch',
    complexity: { time: 'O(log n)', space: 'O(1)' },
    maxN: 2_000_000,
    run: (n) => {
      const arr = Array.from({ length: n }, (_, i) => i);
      binarySearch(arr, Math.floor(n / 2));
    },
  },
  {
    name: 'mergeSort',
    complexity: { time: 'O(n log n)', space: 'O(n)' },
    maxN: 200_000,
    run: (n) => {
      const arr = Array.from({ length: n }, () => Math.random());
      mergeSort(arr);
    },
  },
  {
    name: 'quadraticPairs',
    complexity: { time: 'O(n^2)', space: 'O(1)' },
    maxN: 1_500,
    run: (n) => {
      const arr = Array.from({ length: n }, (_, i) => i);
      quadraticPairs(arr);
    },
  },
  {
    name: 'fibNaive',
    complexity: { time: 'O(2^n)', space: 'O(n)' },
    maxN: 38,
    run: (n) => {
      fibNaive(n);
    },
  },
];

function sizesFor(maxN: number): number[] {
  const out: number[] = [];
  let n = 8;
  // for tiny maxN (e.g. fib), keep linear-ish steps
  if (maxN < 64) {
    for (let x = 5; x <= maxN; x += 5) out.push(x);
    if (out[out.length - 1] !== maxN) out.push(maxN);
    return Array.from(new Set(out));
  }
  while (n <= maxN) {
    out.push(n);
    n *= 2;
  }
  if (out[out.length - 1] !== maxN) out.push(maxN);
  return out;
}

function inferFromRatios(ratios: number[]): string {
  if (ratios.length === 0) return 'n/a';
  const r = ratios[ratios.length - 1];
  if (r <= 1.2) return 'O(1)';
  if (r <= 2.2) return 'O(log n) or O(n)';
  if (r <= 3.0) return 'O(n log n)';
  if (r <= 5.0) return 'O(n^2)';
  return 'O(2^n) or worse';
}

function fmtBytes(b: number): string {
  if (!Number.isFinite(b)) return 'n/a';
  const sign = b < 0 ? '-' : '';
  const abs = Math.abs(b);
  if (abs < 1024) return `${sign}${abs.toFixed(0)} B`;
  if (abs < 1024 * 1024) return `${sign}${(abs / 1024).toFixed(1)} KB`;
  return `${sign}${(abs / 1024 / 1024).toFixed(2)} MB`;
}

// ---------- Main ----------

function main(): void {
