        `matrix(√n≈${Math.min(n, 200)}) heapΔ=${fmtBytes(tQuad.heapDeltaBytes)}`
    );
  }
  console.log();

  // Time benchmarks
  for (const spec of algos) {
    console.log(`\n=== ${spec.name}  [declared ${spec.complexity.time}, ${spec.complexity.space}] ===`);
    const sizes = sizesFor(spec.maxN);
    const times: number[] = [];
    const ratios: number[] = [];

    // warmup
    measure(() => spec.run(sizes[0]));

    console.log('  n'.padStart(10), 'time(ms)'.padStart(12), 'heapΔ'.padStart(12));
    for (const n of sizes) {
      const reps = n <= 100 ? 7 : 3;
      const msSamples: number[] = [];
      const heapSamples: number[] = [];
      for (let i = 0; i < reps; i++) {
        const m = measure(() => spec.run(n));
        msSamples.push(m.ms);
        heapSamples.push(m.heapDeltaBytes);
