## 3. Deadlock and serialization failures need bounded, jittered retries

**Problem:** Retrying blindly can amplify load; retrying non-retryable errors (unique constraint) is wrong.

```ts
type RetryableDbError = { code?: string };

function isRetryable(err: unknown): boolean {
  const e = err as RetryableDbError;
  // PostgreSQL: 40001 serialization_failure, 40P01 deadlock_detected
  // MySQL: 1213 deadlock, 1205 lock wait timeout
  return (
    e?.code === "40001" ||
    e?.code === "40P01" ||
    e?.code === "1213" ||
    e?.code === "1205"
  );
}

async function withRetry<T>(
  fn: () => Promise<T>,
  maxAttempts = 5,
  baseMs = 25
): Promise<T> {
  let lastErr: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (!isRetryable(err) || attempt === maxAttempts) throw err;
      const jitter = Math.random() * baseMs;
      const delay = baseMs * 2 ** (attempt - 1) + jitter;
      await new Promise((r) => setTimeout(r, delay));
    }
  }
  throw lastErr;
}

// Usage
await withRetry(() =>
  prisma.$transaction(
    async (tx) => {
      // writes that may deadlock under contention
    },
    { isolationLevel: "Serializable" }
  )
);
```

**Edge note:** A retry must re-run the **entire** transaction body, including reads. Never retry only the failed statement while keeping earlier reads.

---

## 4. Idempotency for operations that may be retried

**Problem:** If `COMMIT` result is unknown, the client may retry and double-apply side effects.

```ts
interface PaymentInput {
  idempotencyKey: string;
  from: string;
  to: string;
  amount: number;
}

async function transferIdempotent(
  tx: { query: (sql: string, params: unknown[]) => Promise<{ rows: any[] }> },
  input: PaymentInput
) {
  // Unique constraint on idempotency_key makes this safe
  const existing = await tx.query(
    "SELECT status, result FROM idempotency_records WHERE key = $1",
    [input.idempotencyKey]
  );

  if (existing.rows.length > 0) {
    return existing.rows[0].result; // replay prior result
  }

  // perform business write + record idempotency in same transaction
  await tx.query("UPDATE accounts SET balance = balance - $1 WHERE id = $2", [
    input.amount,
    input.from,
  ]);
  await tx.query("UPDATE accounts SET balance = balance + $1 WHERE id = $2", [
    input.amount,
    input.to,
  ]);
  const result = { ok: true };
  await tx.query(
    "INSERT INTO idempotency_records (key, status, result) VALUES ($1, $2, $3)",
    [input.idempotencyKey, "completed", JSON.stringify(result)]
  );
  return result;
}
```

---

## 5. Stale reads after rollback

**Problem:** Application objects mutate across failed transaction attempts.

```ts
async function moveMoneyBad(pool: Pool) {
  const acct = { balance: 100 }; // mutable closure state updated before commit
  await safeTransfer(pool, "a", "b", 10);
  acct.balance -= 10; // if transfer later fails/rolls back, local state is wrong
}

async function moveMoneyGood(pool: Pool) {
  // Re-read authoritative state inside the transaction; do not trust stale objects
  const result = await withRetry(() =>
    pool.connect().then(async (client) => {
      try {
        await client.query("BEGIN");
        const { rows } = await client.query(
          "SELECT balance FROM accounts WHERE id = $1",
          ["a"]
        );
        const balance = rows[0].balance;
        if (balance < 10) throw new Error("insufficient");
        await client.query("UPDATE accounts SET balance = balance - 10 WHERE id = $1", ["a"]);
        await client.query("COMMIT");
        return balance - 10;
      } catch (e) {
        await client.query("ROLLBACK");
        throw e;
      } finally {
        client.release();
      }
    })
  );
  return result;
}
```

