## 6. Constraint violations are usually not retryable

```ts
function isUniqueViolation(err: unknown): boolean {
  return (err as any)?.code === "23505"; // PostgreSQL
}

async function createUser(tx: any, email: string) {
  try {
    return await tx.user.create({ data: { email } });
  } catch (err) {
    if (isUniqueViolation(err)) {
      // Domain-level handling, not a retry
      throw new Error(`email already exists: ${email}`);
    }
    throw err;
  }
}
```

---

## 7. Isolation level anomalies: lost update / phantom reads

**Problem:** Default `READ COMMITTED` prevents dirty reads but not lost updates.

```ts
// Lost update example fixed with optimistic locking
async function updateProduct(tx: any, id: string, patch: { price: number }) {
  const current = await tx.product.findUnique({ where: { id } });
  if (!current) throw new Error("not found");

  const updated = await tx.product.updateMany({
    where: { id, version: current.version }, // optimistic check
    data: { price: patch.price, version: { increment: 1 } },
  });

  if (updated.count === 0) {
    throw new Error("concurrent modification; retry transaction");
  }
}
```

Range consistency (phantoms) under Serializable:

```ts
await prisma.$transaction(
  async (tx) => {
    const available = await tx.seat.count({ where: { status: "available" } });
    if (available < 1) throw new Error("sold out");
    await tx.seat.updateMany({
      where: { status: "available" },
      data: { status: "held" },
      take: 1, // if supported by adapter
    });
  },
  { isolationLevel: "Serializable" }
);
```

Use `SELECT ... FOR UPDATE` when pessimistic locking is needed:

```ts
await client.query("SELECT balance FROM accounts WHERE id = $1 FOR UPDATE", [id]);
```

---

## 8. Do not hold transactions open across external I/O

**Problem:** DB locks held while calling payment gateways exhaust connections.

```ts
// ❌ Bad: payment call inside transaction
await prisma.$transaction(async (tx) => {
  await tx.order.update({ where: { id }, data: { status: "paying" } });
  await stripe.charges.create({ amount }); // slow + unreliable
  await tx.order.update({ where: { id }, data: { status: "paid" } });
});

// ✅ Good: transactional outbox / saga
async function placeOrder(pool: Pool, orderId: string) {
  // 1. Short transaction: persist intent + outbox event
  await withRetry(() =>
    pool.connect().then(async (c) => {
      try {
        await c.query("BEGIN");
        await c.query("UPDATE orders SET status = 'pending_payment' WHERE id = $1", [orderId]);
        await c.query(
          "INSERT INTO outbox (aggregate_id, type, payload) VALUES ($1, $2, $3)",
          [orderId, "PaymentRequested", JSON.stringify({ orderId })]
        );
        await c.query("COMMIT");
      } catch (e) {
        await c.query("ROLLBACK");
        throw e;
      } finally {
        c.release();
      }
    })
  );

  // 2. External call outside transaction
  // (worker processes outbox; or call here with idempotency key)
}
```

