## 9. Transaction context propagation across async boundaries

**Problem:** In TypeScript, passing `tx` manually is error-prone; losing it silently runs queries outside the transaction.

```ts
import { AsyncLocalStorage } from "node:async_hooks";

const txStorage = new AsyncLocalStorage<{ query: (s: string, p?: unknown[]) => Promise<any> }>();

async function runInTx<T>(client: any, fn: () => Promise<T>): Promise<T> {
  await client.query("BEGIN");
  const store = { query: (s: string, p?: unknown[]) => client.query(s, p) };
  try {
    const result = await txStorage.run(store, fn);
    await client.query("COMMIT");
    return result;
  } catch (e) {
    await client.query("ROLLBACK");
    throw e;
  }
}

function q(sql: string, params?: unknown[]) {
  const tx = txStorage.getStore();
  if (!tx) throw new Error("query outside transaction");
  return tx.query(sql, params);
}

// Now deeply nested helpers use q(...) without threading tx manually.
```

**Edge note:** Ensure every `await` stays inside the same async context; avoid “fire and forget” promises that escape the transaction scope.

---

## 10. Savepoint rollback vs full rollback

```ts
async function importBatch(tx: any, rows: Array<{ email: string }>) {
  const failures: string[] = [];

  for (const row of rows) {
    await tx.$executeRaw`SAVEPOINT row_sp`;
    try {
      await tx.user.create({ data: { email: row.email } });
      await tx.$executeRaw`RELEASE SAVEPOINT row_sp`;
    } catch (err) {
      await tx.$executeRaw`ROLLBACK TO SAVEPOINT row_sp`;
      failures.push(row.email);
    }
  }

  // Decide whether entire batch should commit
  if (failures.length > rows.length / 2) {
    throw new Error("too many failures; rolling back whole batch");
  }
  return { failures };
}
```

**Edge note:** Some drivers auto-release savepoints; verify behavior. Do not assume `ROLLBACK TO SAVEPOINT` clears locks acquired after the savepoint in all engines.

---

## 11. Retry storms and circuit breaking

```ts
let consecutiveFailures = 0;

async function carefulTransaction<T>(fn: () => Promise<T>): Promise<T> {
  if (consecutiveFailures > 20) {
    throw new Error("transaction circuit open");
  }
  try {
    const r = await withRetry(fn);
    consecutiveFailures = 0;
    return r;
  } catch (e) {
    consecutiveFailures++;
    throw e;
  }
}
```

