## 13. “Unknown commit state” handling

```ts
async function transferWithUnknownCommitHandling(pool: Pool, input: PaymentInput) {
  try {
    return await withRetry(() => runTransferTransaction(pool, input));
  } catch (err) {
    // If commit's result is unknown, do NOT blindly retry the whole side effect.
    // Check idempotency record / reconcile instead.
    const status = await checkIdempotencyStatus(pool, input.idempotencyKey);
    if (status === "completed") return { ok: true, replayed: true };
    throw err; // surface for reconciliation job
  }
}
```

