Below is a self-contained TypeScript file that demonstrates the two most common variants of the two-pointer technique:

1. **Opposite ends** (move inward from both sides) – used for sorted arrays, palindromes, container problems.
2. **Same direction / fast & slow** (both move right, one faster) – used for in-place deduplication, cycle detection, partitioning.

I also include a small test harness so you can run it with `npx ts-node` or compile with `tsc`.

---

### `two-pointers.ts`

```ts
// two-pointers.ts
// Run with: npx ts-node two-pointers.ts
// Or compile: tsc two-pointers.ts && node two-pointers.js

/* ------------------------------------------------------------------ */
/* 1. Opposite ends: Two Sum on a sorted array                         */
/* ------------------------------------------------------------------ */

/**
 * Returns indices [i, j] such that nums[i] + nums[j] === target.
 * Assumes nums is sorted in non-decreasing order.
 * Time: O(n), Space: O(1)
 */
function twoSumSorted(nums: number[], target: number): [number, number] | null {
  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const sum = nums[left] + nums[right];

    if (sum === target) {
      return [left, right];
    }
    if (sum < target) {
      left++;          // need a larger sum → move left pointer right
    } else {
      right--;         // need a smaller sum → move right pointer left
    }
  }
  return null;
}

/* ------------------------------------------------------------------ */
/* 2. Opposite ends: Maximum area between two lines (container water)  */
/* ------------------------------------------------------------------ */

/**
 * Classic "Container With Most Water" problem.
 * Time: O(n), Space: O(1)
 */
function maxArea(heights: number[]): number {
  let left = 0;
  let right = heights.length - 1;
  let best = 0;

  while (left < right) {
    const width = right - left;
    const h = Math.min(heights[left], heights[right]);
    best = Math.max(best, width * h);

    // Move the pointer at the shorter line inward; the taller one
    // might still form a better area with a future partner.
    if (heights[left] < heights[right]) {
      left++;
    } else {
      right--;
    }
  }
  return best;
}

/* ------------------------------------------------------------------ */
/* 3. Opposite ends: Palindrome check on a string                      */
/* ------------------------------------------------------------------ */

function isPalindrome(s: string): boolean {
  // Normalize: keep only alphanumeric, lowercase.
  const cleaned = s.toLowerCase().replace(/[^a-z0-9]/g, "");
  let left = 0;
  let right = cleaned.length - 1;

  while (left < right) {
    if (cleaned[left] !== cleaned[right]) return false;
    left++;
    right--;
  }
  return true;
}

/* ------------------------------------------------------------------ */
/* 4. Same direction (fast & slow): Remove duplicates in-place          */
/* ------------------------------------------------------------------ */

/**
 * Removes duplicates from a sorted array in-place.
 * Returns the new length; the first `length` elements are unique.
 * Time: O(n), Space: O(1)
 */
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;

  let slow = 0; // last position of the unique prefix
  for (let fast = 1; fast < nums.length; fast++) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast];
    }
  }
  return slow + 1;
}

/* ------------------------------------------------------------------ */
/* 5. Same direction: Move all zeros to the end (stable)               */
/* ------------------------------------------------------------------ */

function moveZeros(nums: number[]): void {
  let slow = 0; // position to place next non-zero
  for (let fast = 0; fast < nums.length; fast++) {
    if (nums[fast] !== 0) {
      [nums[slow], nums[fast]] = [nums[fast], nums[slow]];
      slow++;
    }
  }
}

/* ------------------------------------------------------------------ */
/* 6. Same direction: Partition array by a predicate (stable-ish)      */
/* ------------------------------------------------------------------ */

/**
 * Move all elements satisfying `pred` to the front.
 * Returns the count of elements that satisfy the predicate.
 */
function partition<T>(arr: T[], pred: (x: T) => boolean): number {
  let slow = 0;
  for (let fast = 0; fast < arr.length; fast++) {
    if (pred(arr[fast])) {
      [arr[slow], arr[fast]] = [arr[fast], arr[slow]];
      slow++;
    }
  }
  return slow;
}

/* ------------------------------------------------------------------ */
/* Demo / tests                                                        */
/* ------------------------------------------------------------------ */

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(`FAIL: ${msg}`);
  console.log(`PASS: ${msg}`);
}

function main(): void {
  // --- Two Sum ---
  const nums = [1, 2, 3, 4, 6];
  const res = twoSumSorted(nums, 7);
  assert(res !== null && nums[res[0]] + nums[res[1]] === 7, "twoSumSorted basic");
  assert(twoSumSorted([1, 2, 3], 10) === null, "twoSumSorted none");

  // --- Max Area ---
  assert(maxArea([1, 8, 6, 2, 5, 4, 8, 3, 7]) === 49, "maxArea classic");
  assert(maxArea([1, 1]) === 1, "maxArea small");

  // --- Palindrome ---
  assert(isPalindrome("A man, a plan, a canal: Panama") === true, "palindrome true");
  assert(isPalindrome("race a car") === false, "palindrome false");

  // --- Remove Duplicates ---
  const dup = [1, 1, 2, 2, 3];
  const newLen = removeDuplicates(dup);
  assert(newLen === 3 && dup.slice(0, newLen).join(",") === "1,2,3", "removeDuplicates");

  // --- Move Zeros ---
  const z = [0, 1, 0, 3, 12];
  moveZeros(z);
  assert(z.join(",") === "1,3,12,0,0", "moveZeros");

  // --- Partition ---
  const p = [3, 1, 4, 1, 5, 9, 2, 6];
  const cnt = partition(p, (x) => x % 2 === 0);
  assert(cnt === 3 && p.slice(0, cnt).every((x) => x % 2 === 0), "partition evens");

  console.log("\nAll checks passed.");
}

main();
```

