### 3) Fast/slow — Remove duplicates in-place (sorted array)

```ts
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;
  let slow = 0;
  for (let fast = 1; fast < nums.length; fast++) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast];
    }
  }
  return slow + 1; // new logical length
}

// const a = [1,1,2,2,3]; removeDuplicates(a) -> 3, a = [1,2,3,2,3]
```

---

### 4) Fast/slow — Partition (Dutch national flag style)

Move all zeros to the front without extra memory:

```ts
function moveZeros(nums: number[]): void {
  let slow = 0;
  for (let fast = 0; fast < nums.length; fast++) {
    if (nums[fast] !== 0) {
      [nums[slow], nums[fast]] = [nums[fast], nums[slow]];
      slow++;
    }
  }
}
```

---

### 5) Sliding window — Longest substring without repeating chars

```ts
function lengthOfLongestSubstring(s: string): number {
  const seen = new Map<string, number>(); // char -> last index
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (seen.has(ch) && seen.get(ch)! >= left) {
      left = seen.get(ch)! + 1; // shrink window
    }
    seen.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
```

Here `left` and `right` both move rightward; the window expands/shrinks based on state.

---

### 6) Floyd’s cycle detection (two pointers on a linked list)

```ts
interface ListNode { val: number; next: ListNode | null; }

function hasCycle(head: ListNode | null): boolean {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}
```

---

### TypeScript-specific tips

- **Typing indices:** use `number`, and guard bounds with `while (left < right)` or `for`.
- **Null safety:** with `--strict`, narrow `ListNode | null` before `.next`.
- **Immutability:** if you must not mutate input, copy first or return new arrays.
- **Generic version:** many two-pointer routines work over `T[]` with a comparator:

```ts
function reverseInPlace<T>(arr: T[]): void {
  let l = 0, r = arr.length - 1;
  while (l < r) [arr[l++], arr[r--]] = [arr[r], arr[l]];
}
```

### When to reach for it

- Input is **sorted** or can be sorted.
- You need **in-place** O(1) extra space.
- Problem asks for **pairs/triplets**, **ranges**, **subarrays**, or **partitioning**.
- You see O(n²) nested loops that compare symmetric positions.

### Pitfalls

- Off-by-one: prefer `left < right` for pairs; `left <= right` only when a single element is a valid answer.
- Forgetting to advance both pointers in some branches (infinite loop).
- Mutating when the problem expects a new array.
- Assuming sortedness when it isn’t guaranteed — sort first (O(n log n)) if allowed.

## Typical two-pointer mistake

A very common mistake is **not advancing the scanning pointer in every iteration**, which can create an infinite loop or skip work.

### ❌ Incorrect version

```ts
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;

  let slow = 0; // end of the unique prefix
  let fast = 1; // scanner

  while (fast < nums.length) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast];
      fast++; // advanced only in this branch
    }
    // BUG: when nums[fast] === nums[slow], fast is never incremented
  }

  return slow + 1;
}
```

### ✅ Corrected version

```ts
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;

  let slow = 0; // end of the unique prefix
  let fast = 1; // scanner

  while (fast < nums.length) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast];
    }
    fast++; // always advance the scanner
  }

  return slow + 1;
}
```

### What was wrong and why

- **`fast` must move through every element.** Its job is to inspect the whole array once, so it needs to advance on **every** loop iteration.
- In the buggy version, `fast++` was placed inside the `if` block. When `nums[fast] === nums[slow]`, the `if` was skipped, so `fast` stayed in place forever.
- That produced an infinite loop whenever a duplicate was encountered immediately after the current unique element.
- Moving `fast++` outside the conditional makes the loop progress by exactly one element each time, giving the expected `O(n)` single pass while `slow` only advances when a new unique value is found.

### Why the corrected logic works

- `slow` points to the last unique element kept so far.
- `fast` explores the rest of the array.
- If `nums[fast]` is different, it becomes the next unique value and `slow` moves forward.
- If it is the same, we simply skip it.
- Because `fast` always increments, the loop terminates after `nums.length - 1` iterations, and the new length is `slow + 1`.

# Common Pitfalls with the Two-Pointer Technique in TypeScript

Below are the most frequent mistakes, each with a short "buggy" vs "fixed" example. Examples assume a sorted array unless noted.

---

## 1. Assuming the input is already sorted

Two-pointer (left/right) only works on **sorted** data for search/sum problems.

```ts
// ❌ Bug: works on [2,7,11,15] but fails on [7,2,15,11]
function twoSumUnsorted(nums: number[], target: number): number[] {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l] + nums[r];
    if (s === target) return [l, r];
    if (s < target) l++; else r--;
  }
  return [];
}

// ✅ Fix: sort a copy (keep original indices if needed)
function twoSumSorted(nums: number[], target: number): number[] {
  const indexed = nums.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  let l = 0, r = indexed.length - 1;
  while (l < r) {
    const s = indexed[l].v + indexed[r].v;
    if (s === target) return [indexed[l].i, indexed[r].i];
    if (s < target) l++; else r--;
  }
  return [];
}
```

---

## 2. Off-by-one in the loop condition

`l <= r` vs `l < r` changes whether a single middle element is considered.

```ts
// ❌ Bug: misses the case where the answer is a single element (e.g. square root)
function isPerfectSquareBad(n: number): boolean {
  let l = 1, r = n;
  while (l < r) {          // never checks l === r properly in some variants
    const m = Math.floor((l + r) / 2);
    if (m * m === n) return true;
    if (m * m < n) l = m + 1; else r = m - 1;
  }
  return l * l === n; // fragile
}

// ✅ Fix: use l <= r for "find exact" binary-search style
function isPerfectSquare(n: number): boolean {
  if (n < 1) return false;
  let l = 1, r = n;
  while (l <= r) {
    const m = Math.floor((l + r) / 2);
    const sq = m * m;
    if (sq === n) return true;
    if (sq < n) l = m + 1; else r = m - 1;
  }
  return false;
}
```

---

## 3. Infinite loop from not advancing pointers

Forgetting `l++` / `r--` (or advancing both) stalls the loop.

```ts
// ❌ Bug: when nums[l] + nums[r] === target but not returning, pointers never move
function pairSumBad(nums: number[], target: number): [number, number] | null {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l] + nums[r];
    if (s === target) {
      // forgot to return or move
      continue;
    }
    if (s < target) l++; else r--;
  }
  return null;
}

// ✅ Fix: always make progress; return or advance
function pairSum(nums: number[], target: number): [number, number] | null {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l] + nums[r];
    if (s === target) return [nums[l], nums[r]];
    if (s < target) l++; else r--;
  }
  return null;
}
```

