## 5. Mutating the input array

Sorting in place surprises callers; two-pointer often needs sorted data.

```ts
// ❌ Bug: mutates caller's array
function containsPairBad(nums: number[], target: number): boolean {
  nums.sort((a, b) => a - b); // mutation!
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l] + nums[r];
    if (s === target) return true;
    if (s < target) l++; else r--;
  }
  return false;
}

// ✅ Fix: copy first
function containsPair(nums: number[], target: number): boolean {
  const a = [...nums].sort((x, y) => x - y);
  let l = 0, r = a.length - 1;
  while (l < r) {
    const s = a[l] + a[r];
    if (s === target) return true;
    if (s < target) l++; else r--;
  }
  return false;
}
```

