## 7. TypeScript: possibly-undefined element access

With `noUncheckedIndexedAccess`, `nums[i]` is `number | undefined`.

```ts
// ❌ Bug: TS error under noUncheckedIndexedAccess
function sumEnds(nums: number[]): number {
  const l = 0, r = nums.length - 1;
  return nums[l] + nums[r]; // number | undefined
}

// ✅ Fix: non-null assertion only when bounds are guaranteed, or guard
function sumEndsSafe(nums: number[]): number | null {
  if (nums.length < 2) return null;
  const l = 0;
  const r = nums.length - 1;
  const a = nums[l];
  const b = nums[r];
  if (a === undefined || b === undefined) return null;
  return a + b;
}
