## 8. Wrong comparison operator (strict vs loose)

Especially with duplicates and "at most / at least" conditions.

```ts
// ❌ Bug: should move the smaller height; using <= moves both incorrectly
function maxAreaBad2(height: number[]): number {
  let l = 0, r = height.length - 1, best = 0;
  while (l < r) {
    best = Math.max(best, Math.min(height[l]!, height[r]!) * (r - l));
    if (height[l]! <= height[r]!) l++;  // when equal, moving both loses combos
    else r--;
  }
  return best;
}

// ✅ Fix: move one side on equality (either is fine, but be consistent)
function maxArea(height: number[]): number {
  let l = 0, r = height.length - 1, best = 0;
  while (l < r) {
    const hl = height[l]!, hr = height[r]!;
    best = Math.max(best, Math.min(hl, hr) * (r - l));
    if (hl < hr) l++; else r--; // on equality move either one
  }
  return best;
}
```

