## 9. Modifying the array while iterating with two pointers

Removing/inserting shifts indices and breaks pointer invariants.

```ts
// ❌ Bug: splice shifts elements; r becomes stale
function removeDuplicatesBad(nums: number[]): number {
  let l = 0, r = 1;
  while (r < nums.length) {
    if (nums[r] === nums[l]) {
      nums.splice(r, 1); // 💥 indices shift
    } else {
      l = r; r++;
    }
  }
  return nums.length;
}

// ✅ Fix: write in place with a slow pointer, no splice
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;
  let slow = 0;
  for (let fast = 1; fast < nums.length; fast++) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast]!;
    }
  }
  return slow + 1;
}
```

