  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l]! + nums[r]!;
    if (s === target) return [l, r];
    if (s < target) l++; else r--;
  }
  // implicit undefined
}

// ✅ Fix: explicit null/undefined + correct return type
function findPair(nums: number[], target: number): [number, number] | null {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const s = nums[l]! + nums[r]!;
    if (s === target) return [l, r];
    if (s < target) l++; else r--;
  }
  return null;
}
```

