# Edge Cases in the Two-Pointer Technique (TypeScript)

Below are the edge cases that bite people in practice, grouped by category, each with runnable TypeScript.

## 1. Empty, single-element, and two-element inputs

The most common crash is `arr[mid]` on an empty array or assuming `left < right` implies at least 3 elements.

```ts
function twoSumSorted(nums: number[], target: number): [number, number] | null {
  // Defensive: handle arrays too small for a pair
  if (!Array.isArray(nums) || nums.length < 2) return null;

  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }
  return null;
}

// Edge cases
console.log(twoSumSorted([], 5));          // null
console.log(twoSumSorted([7], 7));         // null
console.log(twoSumSorted([1, 2], 3));      // [0, 1]
console.log(twoSumSorted([1, 2], 10));     // null
```

## 2. Loop boundary: `left < right` vs `left <= right`

- Use `left < right` when the two pointers must refer to **distinct** elements (pairs, swaps).
- Use `left <= right` when a single middle element is meaningful (binary search, partitioning around a pivot that may be the answer).

```ts
// Distinct pairs -> strict <
function isPalindrome(s: string): boolean {
  let l = 0, r = s.length - 1;
  while (l < r) {
    if (s[l] !== s[r]) return false;
    l++; r--;
  }
  return true; // covers "", "a", "aa"
}

// Single-middle matters -> <=
function findPeak(nums: number[]): number {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const mid = Math.floor((l + r) / 2);
    if (nums[mid] < nums[mid + 1]) l = mid + 1;
    else r = mid;
  }
  return l; // works even when array has 1 element
}
```

## 3. Duplicates and "skip duplicates" discipline

When you find a match, you often must advance **both** pointers past duplicates to avoid duplicate results — but only advance one side when values don't match.

```ts
function threeSum(nums: number[]): number[][] {
  const res: number[][] = [];
  nums.sort((a, b) => a - b);

  for (let i = 0; i < nums.length - 2; i++) {
    // Skip duplicate first elements
    if (i > 0 && nums[i] === nums[i - 1]) continue;

    let l = i + 1, r = nums.length - 1;
    while (l < r) {
      const sum = nums[i] + nums[l] + nums[r];
      if (sum === 0) {
        res.push([nums[i], nums[l], nums[r]]);

        // Skip duplicates on BOTH sides after a hit
        while (l < r && nums[l] === nums[l + 1]) l++;
        while (l < r && nums[r] === nums[r - 1]) r--;
        l++; r--;
      } else if (sum < 0) {
        l++;
      } else {
        r--;
      }
    }
  }
  return res;
}

console.log(threeSum([-1, 0, 1, 2, -1, -4]));
// [[-1, -1, 2], [-1, 0, 1]]
console.log(threeSum([0, 0, 0, 0])); // [[0, 0, 0]]
```

Pitfall: skipping duplicates **before** checking the match, or only skipping on one side, produces duplicate triples or skips valid pairs.

## 4. No match / not-found contract

Decide and document the return type (`null`, `[]`, `-1`, `undefined`). Mixing these is a common source of `undefined` crashes downstream.

```ts
function removeDuplicates(nums: number[]): number {
  if (nums.length === 0) return 0;
  let write = 1;
  for (let read = 1; read < nums.length; read++) {
    if (nums[read] !== nums[read - 1]) {
      nums[write++] = nums[read];
    }
  }
  return write; // new length; caller must slice
}

// Caller must respect the returned length — common bug:
const a = [1, 1, 2];
const n = removeDuplicates(a);
console.log(a.slice(0, n)); // [1, 2]  (not the whole array)
```

## 5. Numeric overflow in sum comparisons

TS `number` is IEEE-754 double; safe integers only up to `2^53 - 1`. Adding two large values can lose precision or become `Infinity`.

```ts
function twoSumNoOverflow(nums: number[], target: number): [number, number] | null {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    // Avoid nums[l] + nums[r] overflow / precision loss:
    // compare nums[l] ? target - nums[r]
    const need = target - nums[r];
    if (nums[l] === need) return [l, r];
    if (nums[l] < need) l++;
    else r--;
  }
  return null;
}

// Demonstration of precision trap
console.log(9007199254740992 + 1);              // 9007199254740992 (lost)
console.log(twoSumNoOverflow([9007199254740990, 2], 9007199254740992)); // [0,1]
```

For genuinely huge values, use `BigInt`:

```ts
function twoSumBigInt(nums: bigint[], target: bigint): [number, number] | null {
  let l = 0, r = nums.length - 1;
  while (l < r) {
    const sum = nums[l] + nums[r];
    if (sum === target) return [l, r];
    if (sum < target) l++; else r--;
  }
  return null;
}
```

## 6. Input mutation & side effects

Two-pointer often sorts or rewrites in place. Decide whether the function owns the input.

```ts
function sortedSquares(nums: number[]): number[] {
  // nums is assumed sorted, possibly with negatives.
  // We write into a fresh array to avoid mutating caller's data.
  const n = nums.length;
  const out = new Array<number>(n);
  let l = 0, r = n - 1, k = n - 1;

  while (l <= r) {
    const ls = nums[l] * nums[l];
    const rs = nums[r] * nums[r];
    if (ls > rs) { out[k--] = ls; l++; }
    else         { out[k--] = rs; r--; }
  }
  return out;
}

const input = [-4, -1, 0, 3, 10];
const result = sortedSquares(input);
console.log(input);  // unchanged: [-4, -1, 0, 3, 10]
console.log(result); // [0, 1, 9, 16, 100]
```

## 7. Null/undefined and non-array inputs (defensive TS)

Runtime JS can pass anything; even in TS, `any`/`unknown` boundaries need guards.

```ts
function reverseInPlace<T>(arr: T[] | null | undefined): T[] | null {
  if (!Array.isArray(arr)) return null; // null, undefined, string, etc.
  let l = 0, r = arr.length - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++; r--;
  }
  return arr;
}

console.log(reverseInPlace(null));        // null
console.log(reverseInPlace("abc" as any)); // null
console.log(reverseInPlace([1, 2, 3]));   // [3, 2, 1]
```

## 8. Type narrowing for generics / readonly arrays

`readonly` arrays can't be swapped in place; accept mutable or copy first.

```ts
function moveZeros(nums: number[]): void {
  let write = 0;
  for (let read = 0; read < nums.length; read++) {
    if (nums[read] !== 0) {
      nums[write++] = nums[read];
    }
  }
  for (; write < nums.length; write++) nums[write] = 0;
}

// For readonly input, copy first:
function moveZerosPure(nums: readonly number[]): number[] {
  const out = [...nums];
  moveZeros(out);
  return out;
}
```

## 9. String edge cases: Unicode and case

JS strings are UTF-16; emojis and combining characters break naive indexing. Also case folding.

```ts
function isPalindromeString(s: string): boolean {
  // Normalize for case + combining marks, then work on code points
  const chars = [...s.normalize("NFKC").toLowerCase()]
    .filter(c => /\p{L}|\p{N}/u.test(c));

  let l = 0, r = chars.length - 1;
  while (l < r) {
    if (chars[l] !== chars[r]) return false;
    l++; r--;
  }
  return true;
}

console.log(isPalindromeString("A man, a plan, a canal: Panama")); // true
console.log(isPalindromeString("😀😀"));                              // true
console.log(isPalindromeString("😀😁"));                              // false
// Naive version would mishandle surrogate pairs:
console.log("😀".length); // 2 (UTF-16 code units)
```

## 10. Fast / slow pointer (cycle detection)

Edge cases: empty list, single node, self-loop, tail pointing to head, and the "meeting then reset" reset step.

```ts
interface ListNode { val: number; next: ListNode | null; }

function hasCycle(head: ListNode | null): boolean {
  let slow: ListNode | null = head;
  let fast: ListNode | null = head;
  while (fast !== null && fast.next !== null) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

function findCycleStart(head: ListNode | null): ListNode | null {
  // Phase 1: detect meeting point
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) break;
  }
  if (!fast || !fast.next) return null; // no cycle

  // Phase 2: reset one pointer to head
  let p = head;
  while (p !== slow) {
    p = p!.next;
    slow = slow!.next;
  }
  return p;
}

// Edge: single node with self-loop
const n: ListNode = { val: 1, next: null };
n.next = n;
console.log(hasCycle(n));        // true
console.log(findCycleStart(n)); // n

// Edge: two nodes, second points to first
const a: ListNode = { val: 1, next: null };
const b: ListNode = { val: 2, next: a };
a.next = b; // cycle a<->b? actually a->b->a
// (works regardless)
```

Pitfall: forgetting `fast.next` null check causes a null-deref; forgetting phase-2 reset returns the meeting point, not the cycle start.

## 11. Sliding window with two pointers: shrink condition

When the window is invalid, shrink and re-check **before** updating the answer, otherwise you record invalid states.

```ts
function longestSubstringWithoutRepeating(s: string): number {
  const seen = new Map<string, number>();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (seen.has(ch) && seen.get(ch)! >= left) {
      left = seen.get(ch)! + 1; // shrink
    }
    seen.set(ch, right);
    best = Math.max(best, right - left + 1); // only update after valid
  }
  return best;
}

console.log(longestSubstringWithoutRepeating(""));        // 0
console.log(longestSubstringWithoutRepeating("aaaa"));   // 1
console.log(longestSubstringWithoutRepeating("abcabcbb")); // 3
```

## 12. Off-by-one when pointers cross with "inclusive" ranges

Common in partition/quicksort-style code.

```ts
function partition(arr: number[], low: number, high: number): number {
  const pivot = arr[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
  return i + 1;
}

// Edge: low === high (single element) -> returns low correctly
const t = [3];
console.log(partition(t, 0, 0)); // 0
console.log(t);                 // [3]
```

## 13. Sorted precondition

Many two-pointer algorithms assume sorted input. Validate or sort defensively; otherwise results are wrong silently.

```ts
function isSorted(nums: number[]): boolean {
  for (let i = 1; i < nums.length; i++) if (nums[i - 1] > nums[i]) return false;
  return true;
}

function twoSumSortedSafe(nums: number[], target: number): [number, number] | null {
  if (!isSorted(nums)) {
    // Option A: throw; Option B: sort a copy (loses index meaning)
    const copy = [...nums].sort((a, b) => a - b);
    // ... run on copy; indices now refer to sorted order
  }
  // ... (omitted for brevity)
  return null;
}
```

## 14. Equal elements / all-same arrays

Tests "skip duplicates" logic and min/max window logic.

```ts
function minWindowSubstring(s: string, t: string): string {
  if (s.length === 0 || t.length === 0) return "";
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  let missing = t.length;
  let left = 0, bestStart = 0, bestLen = Infinity;

  for (let right = 0; right < s.length; right++) {
    const rc = s[right];
    if (need.has(rc) && need.get(rc)! > 0) missing--;
    need.set(rc, (need.get(rc) ?? 0) - 1);

    while (missing === 0) {
      if (right - left + 1 < bestLen) {
        bestLen = right - left + 1;
        bestStart = left;
      }
      const lc = s[left++];
      need.set(lc, (need.get(lc) ?? 0) + 1);
      if (need.get(lc)! > 0) missing++;
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}

console.log(minWindowSubstring("ADOBECODEBANC", "ABC")); // "BANC"
console.log(minWindowSubstring("aaaa", "aa"));            // "aa"
console.log(minWindowSubstring("a", "aa"));               // ""
```

## 15. Pointers as indices into different structures

When pointers live in two different arrays (merge), handle unequal lengths and trailing elements.

```ts
function mergeSorted(a: number[], b: number[]): number[] {
  const out: number[] = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) out.push(a[i++]);
    else out.push(b[j++]);
  }
  // Drain leftovers — easy to forget
  while (i < a.length) out.push(a[i++]);
  while (j < b.length) out.push(b[j++]);
  return out;
}

console.log(mergeSorted([], [1, 2]));   // [1, 2]
console.log(mergeSorted([1, 3], []));   // [1, 3]
console.log(mergeSorted([1, 2], [2, 3])); // [1, 2, 2, 3]
```

## Summary checklist

| Edge case | Guard |
|---|---|
| Empty / 1 element | `length < 2` early return |
| Boundary condition | `left < right` for pairs, `left <= right` for single-middle |
| Duplicates | skip on both sides after a hit |
| No match | consistent `null`/`[]`/`-1` contract |
| Overflow | compare via subtraction, or use `BigInt` |
| Mutation | copy input or document in-place |
| Null/unknown input | `Array.isArray` guard |
| Readonly arrays | copy before in-place ops |
| Unicode strings | spread into code points + normalize |
| Fast/slow pointers | check `fast && fast.next`; reset phase |
| Sliding window | update answer only after validity restored |
| Partition indices | verify `low === high` case |
| Sorted precondition | validate or sort a copy |
| Unequal merge lengths | drain both leftovers |

The single most common bug is the **loop boundary combined with the "skip duplicates" discipline** — getting either wrong yields either missed elements or infinite loops. Always trace through `[]`, `[x]`, `[x, x]`, and `[x, y]` by hand before trusting a two-pointer implementation.

# Implementing Type Checking in TypeScript

TypeScript performs **static type checking** at compile time. You can use it in three ways:

1. **CLI / project** – `tsc` with a `tsconfig.json`.
2. **Programmatic** – the TypeScript Compiler API (`ts.createProgram`, `getTypeChecker`, diagnostics).
3. **From scratch** – a small type checker for a toy language (to understand the mechanics).

Below is a complete, runnable example of **programmatic type checking**, plus a minimal hand-written checker.

---

## 1. Programmatic type checking with the Compiler API

### Install
```bash
npm init -y
npm install typescript
npm install -D ts-node @types/node
```

### `check.ts`
```ts
import * as ts from "typescript";
import * as path from "path";

const fileName = path.resolve(process.cwd(), "example.ts");

const source = `
function add(a: number, b: number): number {
  return a + b;
}

const ok: number = add(1, 2);          // fine
const bad: string  = add(1, 2);        // type error
const oops = add("x", 2);              // type error
`;

const options: ts.CompilerOptions = {
  noEmit: true,
  strict: true,
  target: ts.ScriptTarget.ES2020,
  module: ts.ModuleKind.CommonJS,
};

// Base host delegates to disk (so lib.d.ts etc. resolve normally)
const baseHost = ts.createCompilerHost(options);

const host: ts.CompilerHost = {
  ...baseHost,
  fileExists(f) {
    return f === fileName || baseHost.fileExists(f);
  },
  readFile(f) {
    return f === fileName ? source : baseHost.readFile(f);
  },
  getSourceFile(f, languageVersion, onError, shouldCreateNewSourceFile) {
    if (f === fileName) {
      return ts.createSourceFile(f, source, languageVersion, true);
    }
    return baseHost.getSourceFile(f, languageVersion, onError, shouldCreateNewSourceFile);
  },
};

const program = ts.createProgram([fileName], options, host);
const checker = program.getTypeChecker();

// ---- 1) Collect diagnostics (the actual "type checking" result) ----
const diagnostics = ts.getPreEmitDiagnostics(program);

console.log("=== Diagnostics ===");
if (diagnostics.length === 0) {
  console.log("No type errors.");
} else {
  for (const d of diagnostics) {
    const file = d.file ?? { fileName };
    const { line, character } = ts.getLineAndCharacterOfPosition(file, d.start ?? 0);
    const msg = ts.flattenDiagnosticMessageText(d.messageText, "\n");
    console.log(`${file.fileName}:${line + 1}:${character + 1} - ${msg}`);
  }
}

// ---- 2) Inspect inferred types of nodes ----
console.log("\n=== Inferred types ===");

function visit(node: ts.Node) {
  if (ts.isVariableDeclaration(node) && node.initializer) {
    const t = checker.getTypeAtLocation(node.initializer);
    console.log(
      `${node.name.getText()} : ${checker.typeToString(t)}`
    );
  }
  if (ts.isCallExpression(node)) {
    const t = checker.getTypeAtLocation(node);
    console.log(`call ${node.getText()} : ${checker.typeToString(t)}`);
  }
  ts.forEachChild(node, visit);
}

const sf = program.getSourceFile(fileName)!;
visit(sf);
```

### Run
```bash
npx ts-node check.ts
```

### Expected output
```
=== Diagnostics ===
example.ts:9:7 - Type 'number' is not assignable to type 'string'.
example.ts:10:16 - Argument of type 'string' is not assignable to parameter of type 'number'.

=== Inferred types ===
ok : number
bad : number
oops : number
call add(1, 2) : number
call add("x", 2) : number
```

### Key ideas
- `ts.createProgram` builds the typed AST + symbol table.
- `ts.getPreEmitDiagnostics(program)` returns all type errors, just like `tsc`.
- `checker.getTypeAtLocation(node)` returns the resolved `Type` of any node; `typeToString` renders it.
- The compiler host is pluggable, so you can type-check in-memory strings (shown above) or virtual file systems.

---

