## 3. A tiny type checker from scratch (to see the mechanics)

This checks a minimal expression language with `number`, `boolean`, `+`, and `if`.

```ts
type Type = "number" | "boolean";

type Expr =
  | { kind: "num"; value: number }
  | { kind: "bool"; value: boolean }
  | { kind: "var"; name: string }
  | { kind: "add"; left: Expr; right: Expr }
  | { kind: "if"; cond: Expr; then: Expr; else: Expr };

type Env = Record<string, Type>;

class TypeError extends Error {}

function check(e: Expr, env: Env): Type {
  switch (e.kind) {
    case "num":  return "number";
    case "bool": return "boolean";
    case "var": {
      const t = env[e.name];
      if (!t) throw new TypeError(`Unknown variable: ${e.name}`);
      return t;
    }
    case "add": {
      const l = check(e.left, env);
      const r = check(e.right, env);
      if (l !== "number" || r !== "number")
        throw new TypeError(`'+' requires numbers, got ${l} and ${r}`);
      return "number";
    }
    case "if": {
      const c = check(e.cond, env);
      if (c !== "boolean") throw new TypeError(`Condition must be boolean, got ${c}`);
      const t = check(e.then, env);
      const e2 = check(e.else, env);
      if (t !== e2) throw new TypeError(`Branches differ: ${t} vs ${e2}`);
      return t;
    }
  }
}

// Demo
const expr: Expr = {
  kind: "if",
  cond: { kind: "bool", value: true },
  then: { kind: "add", left: { kind: "num", value: 1 }, right: { kind: "num", value: 2 } },
  else: { kind: "num", value: 0 },
};

console.log(check(expr, {})); // "number"

// A failing case:
try {
  check({ kind: "add", left: { kind: "bool", value: true }, right: { kind: "num", value: 1 } }, {});
} catch (e) {
  console.log((e as Error).message); // '+' requires numbers, got boolean and number
}
```

### Run
```bash
npx ts-node mini.ts
```

---

## 4. Concepts worth knowing

| Concept | In TypeScript |
|---|---|
| **Structural typing** | Compatibility is by shape, not name (`{x:number}` assignable to `{x:number}`). |
| **Type inference** | `let x = 1` → `number`; contextual typing in callbacks. |
| **Widening / narrowing** | `let x = "a"` → `string`; `const x = "a"` → `"a"`; control-flow narrowing in `if`. |
| **Generics** | `function id<T>(x: T): T` with inference at call sites. |
| **Union / intersection** | `string \| number`, `A & B`. |
| **Conditional / mapped types** | Type-level computation (`T extends U ? X : Y`). |
| **Soundness** | TS is intentionally unsound in places (`any`, bivariant callbacks) for ergonomics. |

### Common pitfalls
- `any` disables checking; prefer `unknown` + narrowing.
- `as` casts bypass the checker — avoid in library code.
- Array indexing returns `T` even when out of bounds unless `noUncheckedIndexedAccess`.
- `== null` narrows both `null` and `undefined`.

---

## Summary

- For real projects, use `tsc` + `tsconfig.json`.
- For tooling (linters, refactoring, custom diagnostics), use the **Compiler API** (`createProgram`, `getTypeChecker`, `getPreEmitDiagnostics`).
- The mini checker illustrates the core algorithm: recursively compute a type for each node, unify/compare at operators, and throw on mismatch.

This gives you both a production-ready type-checking setup and an understanding of how type checking actually works under the hood.

# TypeScript Type Checking

TypeScript adds **static type checking** on top of JavaScript: types are checked at compile time and then **erased** from the emitted JavaScript. The goal is to catch mistakes (wrong arguments, missing properties, unsafe operations) before runtime while keeping JavaScript’s flexibility.

## 1. The idea

- **Gradual typing**: you can annotate as much or as little as you want; unannotated code is inferred.
- **Structural typing**: compatibility is based on shape, not declared name.
- **Compile-time only**: types do not exist at runtime; `instanceof`/`typeof` and runtime validation are still needed for untrusted input.
- **Inference first**: TypeScript often infers the type, so you annotate mainly at boundaries (function signatures, public APIs, ambiguous cases).

```ts
// Inferred: number
const price = 19.99;

// Explicit annotation
const tax: number = 0.08;
```

## 2. Basic syntax

### Primitive and common types

```ts
let isActive: boolean = true;
let count: number = 42;
let name: string = "Ada";
let ids: number[] = [1, 2, 3];
let pair: [string, number] = ["age", 30]; // tuple
```

### Special types

```ts
let anything: any = "avoid when possible";     // disables checking
let unknownValue: unknown = fetchData();       // must narrow before use
function log(msg: string): void { console.log(msg); }
function fail(): never { throw new Error("boom"); }
```

### Unions, literals, and intersections

```ts
type Status = "idle" | "loading" | "error"; // union of literals
type Id = string | number;

type User = { id: Id; name: string };
type Admin = User & { permissions: string[] }; // intersection
```

## 3. Functions

Annotate parameters and return types at boundaries; locals can be inferred.

```ts
function add(a: number, b: number): number {
  return a + b;
}

// Optional, default, rest
function greet(name: string, title?: string): string {
  return title ? `${title} ${name}` : name;
}

function sum(...nums: number[]): number {
  return nums.reduce((a, b) => a + b, 0);
}
```

Arrow functions and callbacks:

```ts
const double = (x: number): number => x * 2;

const names = ["a", "b"].map((s: string): string => s.toUpperCase());
```

## 4. Objects: `interface` vs `type`

Both describe shapes; `interface` is extendable and good for public APIs, `type` is more flexible (unions, mapped types).

```ts
interface Product {
  id: number;
  name: string;
  price: number;
  description?: string; // optional
  readonly sku: string; // cannot be reassigned
}

type CartItem = {
  product: Product;
  quantity: number;
};
```

Structural compatibility:

```ts
interface Point { x: number; y: number; }
const p: Point = { x: 1, y: 2, z: 3 }; // extra property allowed here? 
// In assignment to typed variable, excess property check applies for object literals:
const q: Point = { x: 1, y: 2, extra: 3 }; // error in strict checks for literals
```

## 5. Generics

Reusable, type-safe abstractions:

```ts
function first<T>(items: T[]): T | undefined {
  return items[0];
}

interface Box<T> {
  value: T;
}

const numBox: Box<number> = { value: 42 };
```

Constraints:

```ts
function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}
```

## 6. Narrowing

TypeScript narrows types based on runtime checks:

```ts
function printId(id: string | number) {
  if (typeof id === "string") {
    console.log(id.toUpperCase()); // narrowed to string
  } else {
    console.log(id.toFixed(2));    // narrowed to number
  }
}
```

Discriminated unions are idiomatic for state machines:

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle": return Math.PI * s.radius ** 2;
    case "rect":   return s.width * s.height;
  }
}
```

## 7. Utility types

Transform existing types instead of duplicating:

```ts
interface Todo {
  id: number;
  title: string;
  done: boolean;
}

type TodoUpdate = Partial<Todo>;              // all optional
type TodoPreview = Pick<Todo, "id" | "title">; // subset
type TodoCreate = Omit<Todo, "id">;           // remove id
type ById = Record<number, Todo>;             // dictionary
```

## 8. Typical use cases

### API boundaries and data models

```ts
interface ApiResponse<T> {
  data: T;
  status: number;
}

async function fetchUser(id: number): Promise<ApiResponse<User>> {
  const res = await fetch(`/api/users/${id}`);
  return res.json();
}
```

### React props (common in frontend)

```ts
type ButtonProps = {
  label: string;
  onClick: () => void;
  variant?: "primary" | "secondary";
};

function Button({ label, onClick, variant = "primary" }: ButtonProps) {
  return <button onClick={onClick}>{label}</button>;
}
```

### Exhaustiveness checks

```ts
function assertNever(x: never): never {
  throw new Error("Unexpected: " + x);
}

// Combined with discriminated union switch ensures all cases handled.
```

## 9. Strictness and configuration

Enable `strict: true` in `tsconfig.json` for best results:

```json
{
  "compilerOptions": {
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true
  }
}
```

Key behaviors:
- `strictNullChecks`: `null`/`undefined` are not assignable to other types unless allowed.
- `noImplicitAny`: forces you to annotate when inference fails.
- `strictFunctionTypes`: checks function parameter bivariance more safely.

## 10. Runtime vs compile time (important)

Types never run. For external input, validate at runtime:

```ts
function isUser(x: unknown): x is User {
  return typeof x === "object" && x !== null
    && "id" in x && typeof (x as any).id === "number"
    && "name" in x && typeof (x as any).name === "string";
}

const raw: unknown = JSON.parse(input);
if (isUser(raw)) {
  console.log(raw.name); // narrowed
}
```

## Summary

- Annotate boundaries, infer locals.
- Use unions/literals for states, generics for reuse, utility types for transformations.
- Rely on narrowing for safe runtime branching.
- Keep `strict` on; validate untrusted data at runtime because types are erased.

## Mistake

```ts
// ❌ Mistake: `user` is optional, but we access `.name` without checking.
function greet(user?: { name: string }) {
  console.log(user.name.toUpperCase());
}

greet(); // Runtime: Cannot read properties of undefined
```

TypeScript with `strictNullChecks` enabled will actually flag this at compile time (`'user' is possibly 'undefined'`), but the mistake often appears in codebases where `strict` is off, or where developers “fix” the error with a non-null assertion:

```ts
// ❌ Still wrong: silences the compiler, crashes at runtime
function greet(user?: { name: string }) {
  console.log(user!.name.toUpperCase());
}
```

## Corrected version

```ts
// ✅ Handle the undefined case explicitly
function greet(user?: { name: string }) {
  if (!user) {
    console.log("Hello, guest!");
    return;
  }
  console.log(user.name.toUpperCase());
}

greet();                 // "Hello, guest!"
greet({ name: "ada" });  // "ADA"
```

## What was wrong and why

1. **Optional parameter means `undefined` is a valid input.**  
   The type `user?: { name: string }` is shorthand for `user: { name: string } | undefined`. Accessing `.name` on `undefined` is a runtime `TypeError`.

2. **Non-null assertions (`!`) don’t add safety.**  
   `user!` tells TypeScript “trust me, it’s not null/undefined.” It removes the compile-time check but does nothing at runtime. If the assumption is ever wrong, you get a crash instead of a compile error.

3. **The fix is real narrowing, not assertion.**  
   `if (!user)` narrows the type from `{ name: string } | undefined` to `{ name: string }` inside the rest of the function. TypeScript can then prove `.name` is safe to access.

### Related pitfalls worth enabling

- **`strictNullChecks`** (part of `strict`): makes optional/possibly-undefined values explicit.
- **`noUncheckedIndexedAccess`**: makes array/object index access possibly `undefined`, e.g. `arr[0]` becomes `T | undefined`. This catches another very common variant of the same bug:

```ts
const names = ["ada", "grace"];
const first = names[0]; // without noUncheckedIndexedAccess: string
                        // with it: string | undefined
console.log(first.toUpperCase()); // ❌ possibly undefined
```

Corrected:

```ts
const first = names[0];
if (first) console.log(first.toUpperCase());
```

# Common TypeScript Type-Checking Pitfalls

Below are the most frequent pitfalls, grouped by area. Each includes a small example showing the problem and the safer alternative.

---

## 1. Not enabling `strict` (and related flags)

Without `strict: true`, TypeScript allows implicit `any`, null assignment to non-null types, and unsafe `this`.

**Problem (`tsconfig.json`):**
```json
{ "compilerOptions": { "strict": false } }
```
```ts
function greet(name) {          // implicit any
  return "hi " + name.toUpperCase();
}
const x: string = null;        // allowed
```

**Fix:**
```json
{
  "compilerOptions": {
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitReturns": true,
    "noFallthroughCasesInSwitch": true
  }
}
```

---

## 2. Abusing `any`

`any` disables checking entirely and propagates.

```ts
function parse(input: any) {
  return input.foo.bar; // no errors, crashes at runtime
}
```

**Prefer `unknown` + narrowing:**
```ts
function parse(input: unknown) {
  if (typeof input === "object" && input !== null && "foo" in input) {
    // narrow further...
  }
}
```

---

## 3. Type assertions (`as`) that lie

Assertions override the compiler; they don't convert.

```ts
const value = JSON.parse(raw) as { id: number };
value.id.toFixed(); // compiles, may be undefined at runtime
```

**Safer:** validate at boundaries (zod/io-ts) or use `satisfies` (TS 4.9+):
```ts
const cfg = { port: 3000 } satisfies { port: number; host?: string };
```

---

## 4. Non-null assertion `!`

```ts
const el = document.getElementById("app")!; // lies if missing
el.textContent = "x";
```

**Fix:** check:
```ts
const el = document.getElementById("app");
if (!el) throw new Error("missing #app");
el.textContent = "x";
```

---

## 5. `@ts-ignore` vs `@ts-expect-error`

`@ts-ignore` silently hides future errors.

```ts
// @ts-ignore
doSomething(wrongType);
```

**Prefer `@ts-expect-error`** (errors if the next line is *not* actually an error):
```ts
// @ts-expect-error
doSomething(wrongType);
```

---

## 6. Structural typing & excess property checks

Excess property checks only apply to **fresh object literals**, not variables.

```ts
type User = { name: string };

function save(u: User) {}

const extra = { name: "a", age: 30 };
save(extra);           // OK! (structural typing)
save({ name: "a", age: 30 }); // Error: excess property
```

**Implication:** don't rely on excess checks for security; validate at runtime.

---

## 7. Confusing `{}`, `Object`, and `object`

```ts
let a: {} = 42;        // {} accepts almost anything except null/undefined
let b: Object = "str"; // same
let c: object = { x: 1 }; // only non-primitives
```

Use precise types (`Record<string, unknown>`, specific interfaces) instead of `{}`.

---

## 8. `null` / `undefined` under `strictNullChecks`

```ts
function len(s: string) { return s.length; }
len(maybeString); // error if maybeString: string | null
```

Common mistake: forgetting optional chaining / guards:
```ts
// bad
const n = obj && obj.child.name;
// good
const n = obj?.child?.name;
```

---

## 9. Enum pitfalls

Numeric enums have reverse mappings and allow unsafe assignment.

```ts
enum Status { Ok, Fail }
const s: Status = 999; // allowed for numeric enums!
```

**Prefer string enums or `as const`:**
```ts
const Status = { Ok: "ok", Fail: "fail" } as const;
type Status = (typeof Status)[keyof typeof Status];
```

---

## 10. Union narrowing & missing discriminants

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(s: Shape) {
  if (s.kind === "circle") return Math.PI * s.radius ** 2;
  // TS narrows correctly here
}
```

**Pitfall:** non-discriminated unions force manual narrowing:
```ts
type Bad = { radius: number } | { side: number };
function area2(s: Bad) {
  if ("radius" in s) return Math.PI * s.radius ** 2;
  return s.side ** 2;
}
```
Always add a `kind`/`type` discriminant.

---

## 11. `instanceof` only works with classes

```ts
interface Foo { bar: number }
function isFoo(x: unknown): x is Foo {
  return typeof x === "object" && x !== null && "bar" in x; // can't use instanceof
}
```

Interfaces have no runtime representation.

---

## 12. Narrowing lost via destructuring / reassignment

```ts
function f(x: string | number) {
  if (typeof x === "string") {
    const y = x;        // narrowed
    x = 123;            // reassignment widens x back to string | number
    // x.toUpperCase(); // error
  }
}
```

Also, narrowing doesn't survive property access on mutable variables:
```ts
let o: { x: string | number } = { x: "a" };
if (typeof o.x === "string") {
  o.x = 1; // allowed; narrowing on o.x is invalidated
}
```

---

## 13. Exhaustiveness with `never`

```ts
type Color = "red" | "blue";
function hex(c: Color): string {
  switch (c) {
    case "red": return "#f00";
    case "blue": return "#00f";
    default:
      const _exhaustive: never = c; // errors if a case is added later
      return _exhaustive;
  }
}
```

Forgetting this means new union members silently fall through.

---

## 14. Array & tuple widening

```ts
const arr = [1, 2, 3];        // number[] (widened)
const tuple = [1, "a"] as const; // readonly [1, "a"]
```

Function returning tuples needs annotation:
```ts
function coords(): [number, number] {
  return [1, 2]; // without annotation: number[]
}
```

---

## 15. `readonly` & mutability / covariance

```ts
function take(arr: number[]) {}
const ro: readonly number[] = [1, 2];
take(ro); // error: readonly not assignable to mutable
```

Mutable arrays are not safe to pass where readonly is expected? Actually readonly is assignable to... no: mutable expects mutability. Use `readonly` in params:
```ts
function take(arr: readonly number[]) {}
```

Also, arrays are covariant, so `string[]` assignable to `(string | number)[]` can cause unsound writes—`readonly` helps.

---

## 16. Function parameter bivariance

By default (without `strictFunctionTypes`), callback params are bivariant.

```ts
type Handler = (x: Animal) => void;
const h: Handler = (x: Dog) => {}; // unsound assignment allowed
```

Enable `strictFunctionTypes` (part of `strict`) to make params contravariant.

---

## 17. Overload ordering

Overloads are matched top-down; put most specific first.

```ts
function f(x: string): string;
function f(x: any): number;   // too broad first would shadow
function f(x: any) { return x; }
```

---

## 18. Generics: inference & constraints

```ts
function first<T>(arr: T[]): T | undefined { return arr[0]; }
first([1, 2, 3]); // T inferred as number

// Pitfall: no constraint
function len<T>(x: T) { return x.length; } // error
function len2<T extends { length: number }>(x: T) { return x.length; }
```

Defaults and `const` type params (TS 5.0+):
```ts
function make<T = string>(x: T) {}
```

---

## 19. `noUncheckedIndexedAccess`

Without it, indexing assumes defined:

```ts
const arr = [1, 2];
const x = arr[10]; // number (should be number | undefined)
```

Enable the flag; then narrow:
```ts
const x = arr[10];
if (x !== undefined) { /* use x */ }
```

Same for `Record`/index signatures.

---

## 20. `unknown` vs `any` in catch (TS 4.4+)

```ts
try { ... } catch (e) {
  // e is unknown under useUnknownInCatchVariables
  console.log(e.message); // error
  if (e instanceof Error) console.log(e.message); // ok
}
```

---

## 21. Floating promises & thenables

```ts
async function main() {
  fetch("/api"); // floating promise: unhandled rejection
}
```

Enable `noFloatingPromises` (via eslint) or await:
```ts
await fetch("/api");
```

Also, `forEach` with async callbacks doesn't await:
```ts
items.forEach(async (x) => await save(x)); // doesn't await
// use for...of
for (const x of items) await save(x);
```

---

## 22. `this` typing

```ts
const obj = {
  value: 42,
  get: function () { return this.value; }
};
const fn = obj.get;
fn(); // this is undefined at runtime; TS may not catch without noImplicitThis
```

Annotate:
```ts
function get(this: { value: number }) { return this.value; }
```

---

## 23. Type-only imports / `isolatedModules`

With bundlers, type-only imports must be marked:

```ts
import type { Foo } from "./foo";   // erased at compile time
import { type Bar, baz } from "./bar"; // inline type import
```

Otherwise runtime "X is not defined" errors.

---

## 24. `satisfies` vs `as` (TS 4.9+)

```ts
const routes = {
  home: "/",
  about: "/about"
} as const; // readonly, but loses contextual type check

const routes2 = {
  home: "/",
  about: "/about"
} satisfies Record<string, `/${string}`>;
// keeps inferred literal types AND validates shape
```

---

## 25. Circular / recursive types

Deeply recursive types can hit "Type instantiation is excessively deep" or stack overflows.

```ts
type Json = string | number | boolean | null | Json[] | { [k: string]: Json };
```
Usually fine, but complex mapped/conditional recursion may need restructuring or `interface` (lazy evaluation).

---

## Quick checklist

- Enable `strict` + `noUncheckedIndexedAccess` + `exactOptionalPropertyTypes`.
- Avoid `any`; use `unknown` + narrowing.
- Avoid `as` and `!`; validate at boundaries.
- Use `@ts-expect-error`, not `@ts-ignore`.
- Add discriminants to unions; exhaust with `never`.
- Use `as const` / `satisfies` to preserve literals.
- Mark type-only imports.
- Prefer `readonly` params and `const` assertions.

These cover the bulk of real-world type-checking surprises in TypeScript.

## Exercise

Write a type-safe `handleEvent` function for this discriminated union:

```ts
type Event =
  | { type: "click"; x: number; y: number }
  | { type: "keypress"; key: string }
  | { type: "scroll"; delta: number };
```

Requirements:

1. Accept only `Event`.
2. Return a human-readable `string`.
3. Use TypeScript’s narrowing so accessing `x`, `key`, or `delta` is type-safe.
4. Make the switch **exhaustive**: if someone later adds a new event variant, TypeScript should error unless the new case is handled.

---

## Step-by-step solution

### Step 1: Define the discriminated union

The `type` field is the discriminant. TypeScript can narrow the whole object based on `event.type`.

```ts
type Event =
  | { type: "click"; x: number; y: number }
  | { type: "keypress"; key: string }
  | { type: "scroll"; delta: number };
```

### Step 2: Write the function with a switch

Inside each `case`, TypeScript narrows `event` to the matching variant.

```ts
function handleEvent(event: Event): string {
  switch (event.type) {
    case "click":
      // event is { type: "click"; x: number; y: number }
      return `Clicked at (${event.x}, ${event.y})`;

    case "keypress":
      // event is { type: "keypress"; key: string }
      return `Pressed key: ${event.key}`;

    case "scroll":
      // event is { type: "scroll"; delta: number }
      return `Scrolled by ${event.delta}`;
  }
}
```

At this point, TypeScript may complain that the function can implicitly return `undefined` because it does not yet know the switch is exhaustive. That is why Step 3 matters.

### Step 3: Add exhaustiveness checking with `never`

In the `default` branch, assign `event` to a variable typed as `never`. If all variants are handled, `event` is narrowed to `never` there, so the assignment compiles. If a new variant is added later, `event` is no longer `never`, and TypeScript errors.

```ts
function handleEvent(event: Event): string {
  switch (event.type) {
    case "click":
      return `Clicked at (${event.x}, ${event.y})`;

    case "keypress":
      return `Pressed key: ${event.key}`;

    case "scroll":
      return `Scrolled by ${event.delta}`;

    default: {
      const _exhaustiveCheck: never = event;
      throw new Error(`Unhandled event type: ${JSON.stringify(_exhaustiveCheck)}`);
    }
  }
}
```

### Step 4: Verify behavior

```ts
const e1: Event = { type: "click", x: 10, y: 20 };
const e2: Event = { type: "keypress", key: "Enter" };
const e3: Event = { type: "scroll", delta: -120 };

console.log(handleEvent(e1)); // Clicked at (10, 20)
console.log(handleEvent(e2)); // Pressed key: Enter
console.log(handleEvent(e3)); // Scrolled by -120
```

If you add a new variant:

```ts
type Event =
  | { type: "click"; x: number; y: number }
  | { type: "keypress"; key: string }
  | { type: "scroll"; delta: number }
  | { type: "resize"; width: number; height: number };
```

TypeScript will report an error in the `default` branch because `event` is no longer assignable to `never`. You must add:

```ts
case "resize":
  return `Resized to ${event.width}x${event.height}`;
```

---

## Final solution

```ts
type Event =
  | { type: "click"; x: number; y: number }
  | { type: "keypress"; key: string }
  | { type: "scroll"; delta: number };

function handleEvent(event: Event): string {
  switch (event.type) {
    case "click":
      return `Clicked at (${event.x}, ${event.y})`;

    case "keypress":
      return `Pressed key: ${event.key}`;

    case "scroll":
      return `Scrolled by ${event.delta}`;

    default: {
      const _exhaustiveCheck: never = event;
      throw new Error(
        `Unhandled event: ${JSON.stringify(_exhaustiveCheck)}`
      );
    }
  }
}
```

This is idiomatic TypeScript: a discriminated union gives safe property access, and the `never` exhaustiveness check forces every new variant to be handled at compile time.

## Explanation: how TypeScript type checks

TypeScript’s checker is **static, structural, and gradual**:

1. **Types are shapes, not names.**  
   `{ x: number }` is assignable to `{ x: number }` even if declared with different type aliases. Nominal behavior is simulated with branded types.

2. **Assignability, not equality, is the core operation.**  
   Most type errors reduce to: “is the source type assignable to the target type?”

3. **Control-flow narrowing.**  
   Inside `if (typeof x === "string")`, `x` is narrowed to `string`. TypeScript tracks possible types per control-flow path.

4. **Inference.**  
   `let x = 5` infers `number` by widening `5`; `const x = 5` can keep the literal type `5`.

5. **Contextual typing.**  
   In `const f: (n: number) => number = (n) => n + 1`, the expected function type helps infer `n`.

6. **Soundness compromises.**  
   Arrays are covariant, function parameters are bivariant in some cases, `any` disables checking, and type assertions can lie. These make the system practical but not fully sound.

The implementation below models the core: a structural `isAssignable`, expression checking, statement checking, basic inference/widening, contextual object checks, and limited control-flow narrowing.

---

## Mini TypeScript-like type checker

```ts
// ============================================================================
// 1. TYPE MODEL
// ============================================================================

export type PrimitiveName =
  | "any"
  | "unknown"
  | "never"
  | "void"
  | "undefined"
  | "null"
  | "boolean"
  | "number"
  | "string"
  | "symbol"
  | "bigint"
  | "object";

export type Type =
  | { kind: "primitive"; name: PrimitiveName }
  | { kind: "literal"; value: string | number | boolean | null | undefined }
  | { kind: "object"; properties: Map<string, Type>; optional: Set<string>; indexSignature?: Type }
  | { kind: "array"; element: Type }
  | { kind: "function"; params: Type[]; returnType: Type }
  | { kind: "union"; types: Type[] }
  | { kind: "intersection"; types: Type[] }
  | { kind: "typeVar"; name: string; constraint?: Type };

export const Types = {
  any: (): Type => ({ kind: "primitive", name: "any" }),
  unknown: (): Type => ({ kind: "primitive", name: "unknown" }),
  never: (): Type => ({ kind: "primitive", name: "never" }),
  void: (): Type => ({ kind: "primitive", name: "void" }),
  undefined: (): Type => ({ kind: "primitive", name: "undefined" }),
  null: (): Type => ({ kind: "primitive", name: "null" }),
  boolean: (): Type => ({ kind: "primitive", name: "boolean" }),
  number: (): Type => ({ kind: "primitive", name: "number" }),
  string: (): Type => ({ kind: "primitive", name: "string" }),

  literal: (value: string | number | boolean | null | undefined): Type => ({
    kind: "literal",
    value,
  }),

  object: (
    properties: Map<string, Type> | Record<string, Type>,
    optional: Set<string> = new Set(),
    indexSignature?: Type
  ): Type => {
    const map =
      properties instanceof Map
        ? properties
        : new Map(Object.entries(properties));
    return { kind: "object", properties: map, optional, indexSignature };
  },

  array: (element: Type): Type => ({ kind: "array", element }),

  fn: (params: Type[], returnType: Type): Type => ({
    kind: "function",
    params,
    returnType,
  }),

  union: (types: Type[]): Type => {
    const flat: Type[] = [];
    for (const t of types) {
      if (t.kind === "union") flat.push(...t.types);
      else flat.push(t);
    }
    // Remove duplicates by structural key.
    const seen = new Set<string>();
    const unique = flat.filter((t) => {
      const key = JSON.stringify(t);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
    if (unique.length === 1) return unique[0];
    return { kind: "union", types: unique };
  },

  intersection: (types: Type[]): Type => ({ kind: "intersection", types }),
};

// ============================================================================
// 2. CORE ASSIGNABILITY
// ============================================================================

/**
 * Structural assignability: can a value of `source` be used where `target`
 * is expected?
 */
export function isAssignable(source: Type, target: Type, seen = new Set<string>()): boolean {
  const cycleKey = `${JSON.stringify(source)}=>${JSON.stringify(target)}`;
  if (seen.has(cycleKey)) return true; // recursive types: assume safe after first visit
  seen.add(cycleKey);

  // Gradual typing escape hatches.
  if (target.kind === "primitive" && target.name === "any") return true;
  if (source.kind === "primitive" && source.name === "any") return true;
  if (source.kind === "primitive" && source.name === "never") return true; // never is bottom
  if (target.kind === "primitive" && target.name === "unknown") return true; // unknown is top

  // unknown is only assignable to unknown/any.
  if (source.kind === "primitive" && source.name === "unknown") {
    return target.kind === "primitive" && target.name === "unknown";
  }

  // Unions and intersections.
  if (source.kind === "union") {
    // Every possible source value must fit the target.
    return source.types.every((t) => isAssignable(t, target, seen));
  }
  if (target.kind === "union") {
    // Source fits if it fits at least one member.
    return target.types.some((t) => isAssignable(source, t, seen));
  }
  if (source.kind === "intersection") {
    // An intersection is assignable if any constituent is.
    return source.types.some((t) => isAssignable(t, target, seen));
  }
  if (target.kind === "intersection") {
    // Source must satisfy every constituent.
    return target.types.every((t) => isAssignable(source, t, seen));
  }

  // Literal types.
  if (source.kind === "literal") {
    if (target.kind === "literal") {
      return source.value === target.value && typeof source.value === typeof target.value;
    }
    if (target.kind === "primitive") {
      if (target.name === "string") return typeof source.value === "string";
      if (target.name === "number") return typeof source.value === "number";
      if (target.name === "boolean") return typeof source.value === "boolean";
      if (target.name === "null") return source.value === null;
      if (target.name === "undefined") return source.value === undefined;
      if (target.name === "void") return source.value === undefined || source.value === null;
      return false;
    }
    return false;
  }

  // Primitive to primitive.
  if (source.kind === "primitive" && target.kind === "primitive") {
    if (source.name === target.name) return true;
    if (source.name === "undefined" && target.name === "void") return true;
    return false;
  }

  // Arrays are covariant in their element type (a deliberate TS soundness compromise).
  if (source.kind === "array" && target.kind === "array") {
    return isAssignable(source.element, target.element, seen);
  }

  // Objects are checked structurally.
  if (source.kind === "object" && target.kind === "object") {
    for (const [name, targetType] of target.properties) {
      const sourceType = source.properties.get(name);
      const targetOptional = target.optional.has(name);

      if (!sourceType) {
        if (targetOptional) continue;
        // A source index signature can satisfy a missing named property.
        if (source.indexSignature && isAssignable(source.indexSignature, targetType, seen)) continue;
        return false;
      }

      if (!isAssignable(sourceType, targetType, seen)) return false;
    }

    // Index signatures.
    if (target.indexSignature) {
      const sourceIndex = source.indexSignature;
      if (sourceIndex) {
        if (!isAssignable(sourceIndex, target.indexSignature, seen)) return false;
      } else {
        for (const sourceType of source.properties.values()) {
          if (!isAssignable(sourceType, target.indexSignature, seen)) return false;
        }
      }
    }

    // Extra source properties are allowed (structural subtyping).
    return true;
  }

  // Functions: return type is covariant, parameters are contravariant.
  if (source.kind === "function" && target.kind === "function") {
    if (!isAssignable(source.returnType, target.returnType, seen)) return false;

    // Target's parameters must be acceptable to the source function.
    for (let i = 0; i < target.params.length; i++) {
      const targetParam = target.params[i];
      const sourceParam = source.params[i] ?? Types.any();
      if (!isAssignable(targetParam, sourceParam, seen)) return false;
    }
    return true;
  }

  // Type variables / generics: simplified constraint-based checking.
  if (source.kind === "typeVar" || target.kind === "typeVar") {
    if (source.kind === "typeVar" && target.kind === "typeVar") {
      return source.name === target.name;
    }
    if (source.kind === "typeVar") {
      const constraint = source.constraint ?? Types.unknown();
      return isAssignable(constraint, target, seen);
    }
    const constraint = target.constraint ?? Types.unknown();
    return isAssignable(source, constraint, seen);
  }

  return false;
}

// ============================================================================
// 3. AST FOR A SMALL LANGUAGE
// ============================================================================

export type Expr =
  | { kind: "literal"; value: string | number | boolean | null | undefined }
  | { kind: "variable"; name: string }
  | { kind: "property"; object: Expr; name: string }
  | { kind: "index"; object: Expr; index: Expr }
  | { kind: "call"; callee: Expr; args: Expr[] }
  | { kind: "binary"; op: string; left: Expr; right: Expr }
  | { kind: "unary"; op: "typeof" | "!" | "-"; operand: Expr }
  | { kind: "object"; properties: { key: string; value: Expr }[] }
  | { kind: "array"; elements: Expr[] }
  | { kind: "function"; params: { name: string; type: Type }[]; returnType: Type; body: Stmt[] }
  | { kind: "conditional"; test: Expr; consequent: Expr; alternate: Expr }
  | { kind: "assertion"; expr: Expr; type: Type };

export type Stmt =
  | { kind: "let"; name: string; typeAnnotation?: Type; init?: Expr }
  | { kind: "assign"; target: Expr; value: Expr }
  | { kind: "if"; test: Expr; thenBranch: Stmt[]; elseBranch?: Stmt[] }
  | { kind: "while"; test: Expr; body: Stmt[] }
  | { kind: "return"; value?: Expr }
  | { kind: "expr"; expr: Expr }
  | { kind: "function"; name: string; params: { name: string; type: Type }[]; returnType: Type; body: Stmt[] };

// ============================================================================
// 4. TYPE CHECKER
// ============================================================================

export interface Diagnostic {
  message: string;
}

export class TypeChecker {
  private scopes: Map<string, Type>[] = [new Map()];
  private functions = new Map<string, Type>();
  private currentReturnType: Type | null = null;
  public diagnostics: Diagnostic[] = [];

  // ---------- scope helpers ----------

  private pushScope(): void {
    this.scopes.push(new Map());
  }

  private popScope(): void {
    this.scopes.pop();
  }

  private declare(name: string, type: Type): void {
    this.scopes[this.scopes.length - 1].set(name, type);
  }

  private lookup(name: string): Type | undefined {
    for (let i = this.scopes.length - 1; i >= 0; i--) {
      const found = this.scopes[i].get(name);
      if (found) return found;
    }
    return this.functions.get(name);
  }

  private error(message: string): void {
    this.diagnostics.push({ message });
  }

  // ---------- public entry ----------

  public checkProgram(statements: Stmt[]): Diagnostic[] {
    for (const stmt of statements) this.checkStmt(stmt);
    return this.diagnostics;
  }

  // ---------- statements ----------

  private checkStmts(statements: Stmt[]): void {
    for (const stmt of statements) this.checkStmt(stmt);
  }

  private checkStmt(stmt: Stmt): void {
    switch (stmt.kind) {
      case "let": {
        let type: Type;

        if (stmt.init) {
          const initType = this.checkExpr(stmt.init);

          if (stmt.typeAnnotation) {
            if (!isAssignable(initType, stmt.typeAnnotation)) {
              this.error(
                `Type '${JSON.stringify(initType)}' is not assignable to annotation '${JSON.stringify(
                  stmt.typeAnnotation
                )}'`
              );
            }
            type = stmt.typeAnnotation;
          } else {
            // Inference + widening: `let x = 5` becomes number, not literal 5.
            type = this.widen(initType);
          }
        } else {
          type = stmt.typeAnnotation ?? Types.undefined();
        }

        this.declare(stmt.name, type);
        break;
      }

      case "assign": {
        const targetType = this.checkExpr(stmt.target);
        const valueType = this.checkExpr(stmt.value);
        if (!isAssignable(valueType, targetType)) {
          this.error(
            `Type '${JSON.stringify(valueType)}' is not assignable to '${JSON.stringify(targetType)}'`
          );
        }
        break;
      }

      case "if": {
        const testType = this.checkExpr(stmt.test);
        if (
          !isAssignable(testType, Types.boolean()) &&
          testType.kind !== "primitive" &&
          !(testType.kind === "primitive" && (testType.name === "any" || testType.name === "unknown"))
        ) {
          // Allow truthy checks on non-booleans, but still catch obvious mistakes.
          if (!(testType.kind === "primitive" && testType.name === "any")) {
            this.error(`Condition type '${JSON.stringify(testType)}' is not boolean-like`);
          }
        }

        const thenNarrows = this.getNarrows(stmt.test, true);
        const elseNarrows = this.getNarrows(stmt.test, false);

        this.pushScope();
        for (const [name, type] of thenNarrows) this.declare(name, type);
        this.checkStmts(stmt.thenBranch);
        this.popScope();

        if (stmt.elseBranch) {
          this.pushScope();
          for (const [name, type] of elseNarrows) this.declare(name, type);
          this.checkStmts(stmt.elseBranch);
          this.popScope();
        }
        break;
      }

      case "while": {
        const testType = this.checkExpr(stmt.test);
        if (!isAssignable(testType, Types.boolean()) && !(testType.kind === "primitive" && testType.name === "any")) {
          this.error(`While condition type '${JSON.stringify(testType)}' is not boolean-like`);
        }
        this.checkStmts(stmt.body);
        break;
      }

      case "return": {
        const returnType = stmt.value ? this.checkExpr(stmt.value) : Types.undefined();
        if (this.currentReturnType && !isAssignable(returnType, this.currentReturnType)) {
          this.error(
            `Returned type '${JSON.stringify(returnType)}' is not assignable to '${JSON.stringify(
              this.currentReturnType
            )}'`
          );
        }
        break;
      }

      case "expr":
        this.checkExpr(stmt.expr);
        break;

      case "function": {
        const fnType = Types.fn(
          stmt.params.map((p) => p.type),
          stmt.returnType
        );

        // Allow recursion: declare before checking body.
        this.declare(stmt.name, fnType);
        this.functions.set(stmt.name, fnType);

        const previousReturnType = this.currentReturnType;
        this.currentReturnType = stmt.returnType;

        this.pushScope();
        for (const param of stmt.params) this.declare(param.name, param.type);
        this.checkStmts(stmt.body);
        this.popScope();

        this.currentReturnType = previousReturnType;
        break;
      }
    }
  }

  // ---------- expressions ----------

  private checkExpr(expr: Expr, expected?: Type): Type {
    switch (expr.kind) {
      case "literal": {
        // Keep literal types for precision; widening happens in `let`.
        if (expr.value === null) return Types.literal(null);
        if (expr.value === undefined) return Types.literal(undefined);
        if (typeof expr.value === "string") return Types.literal(expr.value);
        if (typeof expr.value === "number") return Types.literal(expr.value);
        if (typeof expr.value === "boolean") return Types.literal(expr.value);
        return Types.unknown();
      }

      case "variable": {
        const type = this.lookup(expr.name);
        if (!type) {
          this.error(`Cannot find name '${expr.name}'`);
          return Types.any();
        }
        return type;
      }

      case "property": {
        const objectType = this.checkExpr(expr.object);

        // Distribute over unions: (A | B).x => A.x | B.x
        if (objectType.kind === "union") {
          const memberTypes = objectType.types.map((member) => {
            if (member.kind !== "object") return Types.any();
            const prop = member.properties.get(expr.name);
            if (!prop) {
              this.error(`Property '${expr.name}' does not exist on type`);
              return Types.any();
            }
            return member.optional.has(expr.name) ? Types.union([prop, Types.undefined()]) : prop;
          });
          return Types.union(memberTypes);
        }

        if (objectType.kind !== "object") {
          this.error(`Cannot access property '${expr.name}' on non-object type`);
          return Types.any();
        }

        const propType = objectType.properties.get(expr.name);
        if (!propType) {
          this.error(`Property '${expr.name}' does not exist on type`);
          return Types.any();
        }

        return objectType.optional.has(expr.name)
          ? Types.union([propType, Types.undefined()])
          : propType;
      }

      case "index": {
        const objectType = this.checkExpr(expr.object);
        const indexType = this.checkExpr(expr.index);

        if (objectType.kind === "array") {
          if (!isAssignable(indexType, Types.number())) {
            this.error("Array index must be a number");
          }
          return objectType.element;
        }

        if (objectType.kind === "object" && objectType.indexSignature) {
          return objectType.indexSignature;
        }

        this.error("Type is not indexable");
        return Types.any();
      }

      case "call": {
        const calleeType = this.checkExpr(expr.callee);

        if (calleeType.kind !== "function") {
          this.error("Expression is not callable");
          return Types.any();
        }

        if (expr.args.length > calleeType.params.length) {
          this.error("Too many arguments");
        }

        for (let i = 0; i < expr.args.length; i++) {
          const argType = this.checkExpr(expr.args[i], calleeType.params[i]);
          const paramType = calleeType.params[i] ?? Types.any();
          if (!isAssignable(argType, paramType)) {
            this.error(
              `Argument of type '${JSON.stringify(argType)}' is not assignable to parameter of type '${JSON.stringify(
                paramType
              )}'`
            );
          }
        }

        return calleeType.returnType;
      }

      case "binary": {
        const leftType = this.checkExpr(expr.left);
        const rightType = this.checkExpr(expr.right);

        // Arithmetic.
        if (["+", "-", "*", "/", "%"].includes(expr.op)) {
          if (expr.op === "+" && (this.isStringLike(leftType) || this.isStringLike(rightType))) {
            return Types.string();
          }
          if (!isAssignable(leftType, Types.number()) || !isAssignable(rightType, Types.number())) {
            this.error("Arithmetic operands must be numbers");
          }
          return Types.number();
        }

        // Comparisons.
        if (["===", "!==", "==", "!=", "<", ">", "<=", ">="].includes(expr.op)) {
          return Types.boolean();
        }

        // Logical operators: approximate with union for truthiness-dependent types.
        if (expr.op === "&&") return rightType;
        if (expr.op === "||") return Types.union([leftType, rightType]);

        this.error(`Unknown binary operator '${expr.op}'`);
        return Types.any();
      }

      case "unary": {
        const operandType = this.checkExpr(expr.operand);
        if (expr.op === "typeof") return Types.string();
        if (expr.op === "-") {
          if (!isAssignable(operandType, Types.number())) this.error("Unary minus requires a number");
          return Types.number();
        }
        if (expr.op === "!") return Types.boolean();
        return Types.any();
      }

      case "object": {
        const props = new Map<string, Type>();
        const optional = new Set<string>();

        for (const prop of expr.properties) {
          // Contextual typing: if expected is an object, use its property type.
          let expectedPropType: Type | undefined;
          if (expected?.kind === "object") {
            expectedPropType = expected.properties.get(prop.key) ?? expected.indexSignature;
          }

          const propType = this.checkExpr(prop.value, expectedPropType);
          props.set(prop.key, propType);

          // Excess property check for object literals.
          if (expected?.kind === "object") {
            const allowed =
              expected.properties.has(prop.key) || Boolean(expected.indexSignature);
            if (!allowed) {
              this.error(`Object literal may not specify unknown property '${prop.key}'`);
            }

            const targetType = expected.properties.get(prop.key) ?? expected.indexSignature;
            if (targetType && !isAssignable(propType, targetType)) {
              this.error(
                `Property '${prop.key}' of type '${JSON.stringify(propType)}' is not assignable to '${JSON.stringify(
                  targetType
                )}'`
              );
            }
          }
        }

        return Types.object(props, optional);
      }

      case "array": {
        const elementTypes = expr.elements.map((e) => this.checkExpr(e));
        const elementType = elementTypes.length ? Types.union(elementTypes) : Types.never();
        const arrayType = Types.array(elementType);

        // Contextual element checking.
        if (expected?.kind === "array") {
          for (const elType of elementTypes) {
            if (!isAssignable(elType, expected.element)) {
              this.error(
                `Array element type '${JSON.stringify(elType)}' is not assignable to '${JSON.stringify(
                  expected.element
                )}'`
              );
            }
          }
        }

        return arrayType;
      }

      case "function": {
        const fnType = Types.fn(
          expr.params.map((p) => p.type),
          expr.returnType
        );

        const previousReturnType = this.currentReturnType;
        this.currentReturnType = expr.returnType;

        this.pushScope();
        for (const param of expr.params) this.declare(param.name, param.type);
        this.checkStmts(expr.body);
        this.popScope();

        this.currentReturnType = previousReturnType;
        return fnType;
      }

      case "conditional": {
        this.checkExpr(expr.test);
        const consequentType = this.checkExpr(expr.consequent);
        const alternateType = this.checkExpr(expr.alternate);
        return Types.union([consequentType, alternateType]);
      }

      case "assertion": {
        const sourceType = this.checkExpr(expr.expr);
        // A real checker checks whether the assertion is sufficiently overlapping.
        // Here we trust the assertion but still record the source type.
        if (!isAssignable(sourceType, expr.type) && !isAssignable(expr.type, sourceType)) {
          this.error("Assertion may be a mistake: types do not sufficiently overlap");
        }
        return expr.type;
      }
    }
  }

  // ---------- helpers ----------

  private widen(type: Type): Type {
    if (type.kind === "literal") {
      if (typeof type.value === "string") return Types.string();
      if (typeof type.value === "number") return Types.number();
      if (typeof type.value === "boolean") return Types.boolean();
      if (type.value === null) return Types.null();
      if (type.value === undefined) return Types.undefined();
    }
    if (type.kind === "array") {
      return Types.array(this.widen(type.element));
    }
    if (type.kind === "object") {
      const props = new Map<string, Type>();
      for (const [key, value] of type.properties) props.set(key, this.widen(value));
      return Types.object(props, new Set(type.optional));
    }
    if (type.kind === "union") {
      return Types.union(type.types.map((t) => this.widen(t)));
    }
    return type;
  }

  private isStringLike(type: Type): boolean {
    if (type.kind === "primitive" && type.name === "string") return true;
    if (type.kind === "literal" && typeof type.value === "string") return true;
    return false;
  }

  /**
   * Limited control-flow narrowing.
   * Handles:
   *   - typeof x === "string"
   *   - truthiness of a variable
   */
  private getNarrows(test: Expr, truthyBranch: boolean): Map<string, Type> {
    const result = new Map<string, Type>();

    // typeof x === "string" / !== "string"
    if (test.kind === "binary" && (test.op === "===" || test.op === "!==")) {
      const positive = test.op === "===";
      const inThisBranch = positive === truthyBranch;

      const left = test.left;
      const right = test.right;

      if (
        left.kind === "unary" &&
        left.op === "typeof" &&
        left.operand.kind === "variable" &&
        right.kind === "literal" &&
        typeof right.value === "string"
      ) {
        const name = left.operand.name;
        const current = this.lookup(name);
        if (!current) return result;

        const narrowedTo = primitiveFromString(right.value);
        if (inThisBranch) {
          result.set(name, intersectWithType(current, narrowedTo));
        } else {
          result.set(name, excludeType(current, narrowedTo));
        }
      }
    }

    // Truthiness narrowing: `if (x)` removes null/undefined/false/0/"".
    if (test.kind === "variable" && truthyBranch) {
      const name = test.name;
      const current = this.lookup(name);
      if (current) result.set(name, removeFalsy(current));
    }

    return result;
  }
}

// ============================================================================
// 5. NARROWING HELPERS
// ============================================================================

function primitiveFromString(name: string): Type {
  switch (name) {
    case "string": return Types.string();
    case "number": return Types.number();
    case "boolean": return Types.boolean();
    case "undefined": return Types.undefined();
    case "object": return Types.primitive("object" as any);
    default: return Types.unknown();
  }
}

function removeFalsy(type: Type): Type {
  if (type.kind === "union") {
    const filtered = type.types.filter((t) => !isFalsyType(t));
    return filtered.length ? Types.union(filtered) : Types.never();
  }
  return isFalsyType(type) ? Types.never() : type;
}

function isFalsyType(type: Type): boolean {
  if (type.kind === "literal") {
    return (
      type.value === null ||
      type.value === undefined ||
      type.value === false ||
      type.value === 0 ||
      type.value === ""
    );
  }
  if (type.kind === "primitive") {
    return type.name === "null" || type.name === "undefined" || type.name === "void";
  }
  return false;
}

function intersectWithType(source: Type, target: Type): Type {
  // For narrowing, represent `x is string` as an intersection when x was broader.
  if (isAssignable(source, target)) return target;
  if (isAssignable(target, source)) return source;
  return Types.intersection([source, target]);
}

function excludeType(source: Type, excluded: Type): Type {
  if (source.kind === "union") {
    const filtered = source.types.filter((t) => !isAssignable(t, excluded));
    return filtered.length ? Types.union(filtered) : Types.never();
  }
  if (isAssignable(source, excluded)) return Types.never();
  return source;
}
```

