## Example usage

```ts
const checker = new TypeChecker();

checker.checkProgram([
  {
    kind: "let",
    name: "user",
    init: {
      kind: "object",
      properties: [
        { key: "name", value: { kind: "literal", value: "Ada" } },
        { key: "age", value: { kind: "literal", value: 36 } },
      ],
    },
  },
  {
    kind: "if",
    test: {
      kind: "binary",
      op: "===",
      left: { kind: "unary", op: "typeof", operand: { kind: "property", object: { kind: "variable", name: "user" }, name: "name" } },
      right: { kind: "literal", value: "string" },
    },
    thenBranch: [
      {
        kind: "expr",
        expr: {
          kind: "call",
          callee: { kind: "variable", name: "console.log" },
          args: [{ kind: "property", object: { kind: "variable", name: "user" }, name: "name" }],
        },
      },
    ],
  },
]);

console.log(checker.diagnostics);
```

