## What this implementation intentionally omits

A production TypeScript checker also handles:

- **Full generic inference** and constraint solving
- **Overload resolution**
- **Conditional, mapped, and template literal types**
- **Module resolution and declaration files**
- **Flow-sensitive narrowing across loops and closures**
- **Excess property checks at deeper levels**
- **Definite assignment analysis**
- **JSX and decorator semantics**

But the core idea remains the same: **parse to AST, infer types, then prove assignability structurally.**

# Edge Cases When Using Type Checking in TypeScript

Below are the most common (and dangerous) edge cases, grouped by theme, with runnable examples. Assume `strict: true` unless noted.

---

## 1. Null / undefined (strictNullChecks)

```ts
function greet(name: string | null) {
  // ❌ Error: 'name' is possibly 'null'
  console.log(name.toUpperCase());

  // ✅ Narrow first
  if (name !== null) console.log(name.toUpperCase());
}
```

**Edge case:** Optional chaining narrows inside the expression but not across statements:

```ts
const arr: string[] | null = get();
arr?.push("x");   // ok
// arr.push("x"); // still possibly null — narrowing didn't persist
```

**Edge case:** `== null` narrows both `null` and `undefined`:

```ts
function f(x: string | null | undefined) {
  if (x != null) x.toUpperCase(); // x is string here
}
```

---

## 2. `any` silently disables checking

```ts
const data: any = fetchSomething();
data.foo.bar.baz(); // no error, runtime crash possible

// Better: unknown + narrowing
const data2: unknown = fetchSomething();
if (typeof data2 === "object" && data2 !== null && "foo" in data2) {
  // still need deeper checks
}
```

**Edge case:** Implicit `any` from untyped params:

```ts
function add(a, b) { return a + b; } // with noImplicitAny, error
```

**Edge case:** `JSON.parse` returns `any`:

```ts
const parsed = JSON.parse('{"x":1}'); // any
// Fix:
const parsed2 = JSON.parse('{"x":1}') as { x: number };
```

---

## 3. Union narrowing & exhaustiveness

```ts
type Shape =
  | { kind: "circle"; r: number }
  | { kind: "square"; side: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle": return Math.PI * s.r ** 2;
    case "square": return s.side ** 2;
  }
  // With noFallthroughCasesInSwitch + exhaustiveness check:
  const _exhaustive: never = s; // error if a new variant added
  return _exhaustive;
}
```

**Edge case:** Truthiness narrowing is unsound for `0`/`""`:

```ts
function f(x: string | number) {
  if (x) {
    // x is string | number, but could be "" or 0 removed? Actually truthiness narrows to truthy subset
  }
}
// Better for strings:
if (x !== "") { ... }
```

**Edge case:** `in` operator narrowing:

```ts
type A = { a: number };
type B = { b: string };
function f(x: A | B) {
  if ("a" in x) x.a.toFixed(); // x is A
}
```

---

## 4. Type guards

```ts
function isString(x: unknown): x is string {
  return typeof x === "string";
}

// Assertion function (throws instead of returning boolean)
function assertString(x: unknown): asserts x is string {
  if (typeof x !== "string") throw new Error("not string");
}
```

**Edge case:** Custom guards can lie; compiler trusts them:

```ts
function isNumber(x: unknown): x is number {
  return true; // unsound but compiles
}
```

**Edge case:** `instanceof` only works with classes, not interfaces:

```ts
interface Foo { x: number }
// "x instanceof Foo" is invalid
```

---

## 5. Structural typing surprises

```ts
interface Point { x: number; y: number; }
const p: Point = { x: 1, y: 2, z: 3 }; // ❌ excess property on literal
const o = { x: 1, y: 2, z: 3 };
const p2: Point = o; // ✅ allowed (structural) — extra props ok via variable
```

**Edge case:** Freshness/excess property checks only on object literals.

**Edge case:** Two structurally identical types are interchangeable even if named differently:

```ts
type UserId = string;
type PostId = string;
let u: UserId = "u1";
let p: PostId = u; // ✅ no error — no nominal typing
// Fix: branded types
type Brand<T, B> = T & { __brand: B };
type UserId2 = Brand<string, "UserId">;
```

---

## 6. `Object` vs `object` vs `{}`

```ts
let a: Object = 5;        // allows primitives (boxed)
let b: object = 5;        // ❌ only non-primitives
let c: {} = 5;            // allows anything except null/undefined
let d: Record<string, never> = {}; // truly empty object
```

**Edge case:** `{}` is not "empty object"; use `Record<string, never>` or a specific shape.

---

## 7. Generics: inference, constraints, variance

```ts
function wrap<T>(x: T): T[] { return [x]; }
// T inferred as literal in some contexts
const r = wrap("hi"); // T = "hi" (literal) in TS 5+? Actually widened to string? depends)
```

**Edge case:** Generic constraints with `extends`:

```ts
function get<T extends { length: number }>(x: T): number {
  return x.length;
}
get("abc");     // T = string
get([1,2,3]);  // T = number[]
```

**Edge case:** Variance in function parameters (strictFunctionTypes):

```ts
type F = (x: string | number) => void;
const g: (x: string) => void = (x) => {}; // ❌ under strictFunctionTypes, contravariant mismatch
```

**Edge case:** Inference fails and falls back to `{}` or `unknown`:

```ts
function f<T>(x: T): T { return x; }
const r = f(); // T = unknown (with noImplicitAny-ish) — actually error: Expected 1 arguments
```

**Edge case:** Generic defaults:

```ts
function create<T = string>(x?: T): T { return x as T; }
```

---

## 8. Literal widening & `as const`

```ts
let x = "hello";       // type: string (widened)
const y = "hello";     // type: "hello" (literal)
const obj = { a: 1 };  // a: number
const obj2 = { a: 1 } as const; // a: 1, readonly

function f(x: "a" | "b") {}
const v = "a";
f(v); // ❌ v is string, not "a"|"b"
f(v as const); // or declare const v = "a"
```

**Edge case:** Array literal widening:

```ts
const arr = ["a", "b"]; // string[]
const arr2 = ["a", "b"] as const; // readonly ["a", "b"]
```

---

## 9. Tuples, arrays, rest

```ts
type T = [string, number];
const t: T = ["a", 1];
// t[2] = "x"; // ❌ (with noUncheckedIndexedAccess, t[0] is string | undefined)

// Rest in tuples
type R = [string, ...number[], boolean];
```

**Edge case:** `noUncheckedIndexedAccess` makes `arr[i]` include `undefined`:

```ts
const arr = [1,2,3];
const x = arr[0]; // number | undefined under flag
```

**Edge case:** Readonly tuples prevent mutation but indexing still works.

---

## 10. Enums

```ts
enum E { A, B }
let e: E = E.A;
// Reverse mapping exists for numeric enums
const name = E[0]; // "A"

const enum CE { A, B } // inlined at compile time; can't iterate at runtime
```

**Edge case:** String enums have no reverse mapping; numeric enums allow any number assignable:

```ts
enum N { A = 0 }
let n: N = 999; // ✅ allowed (numeric enum assignability) — dangerous
```

**Edge case:** `const enum` with `isolatedModules` is forbidden.

---

## 11. `void`, `undefined`, `never`

```ts
function f(): void { return undefined; } // ok
function g(): void { return; }           // ok
// function h(): void { return 1; }      // ❌

// void in callbacks is special: return value ignored
type Cb = () => void;
const cb: Cb = () => 42; // ✅ allowed
```

**Edge case:** `never` is bottom type; assignable to everything, nothing assignable to it (except never):

```ts
function fail(): never { throw new Error(); }
const x: never = fail(); // ok
```

**Edge case:** Unreachable code after `never`-returning call is still analyzed.

---

## 12. `this` typing

```ts
function f(this: { x: number }) {
  return this.x;
}
// f(); // ❌ 'this' context lost

class C {
  x = 1;
  m() { setTimeout(function() { console.log(this.x); }, 0); } // 'this' is any/undefined at runtime
  m2() { setTimeout(() => console.log(this.x), 0); } // arrow preserves
}
```

**Edge case:** Method shorthand vs arrow in objects:

```ts
const o = {
  x: 1,
  m() { return this.x; },     // this typed
  m2: () => this.x,           // 'this' is outer (often global) — error in strict
};
```

---

## 13. Overloads

```ts
function parse(x: string): number;
function parse(x: number): string;
function parse(x: string | number): string | number {
  return typeof x === "string" ? Number(x) : String(x);
}
const r = parse("1"); // number (overload resolution)
```

**Edge case:** Overload signatures must be compatible with implementation; last signature is implementation, not public.

**Edge case:** Overloaded arrow functions aren't supported directly.

---

## 14. Mapped / conditional / template literal types

```ts
type Keys = "a" | "b";
type M = { [K in Keys]: K extends "a" ? number : string };

// Template literal
type EventName = `on${Capitalize<string>}`; // too broad maybe
type Prefixed<T extends string> = `get${Capitalize<T>}`;
```

**Edge case:** Distribution of conditional types over unions:

```ts
type ToArray<T> = T extends any ? T[] : never;
type R = ToArray<string | number>; // string[] | number[] (distributed)
type R2 = [T] extends [any] ? T[] : never; // (string|number)[] (non-distributed)
```

**Edge case:** `infer` constraints (TS 5.0+):

```ts
type First<T extends any[]> = T extends [infer F, ...any[]] ? F : never;
```

---

## 15. Runtime/compile-time mismatches

```ts
// Object.keys returns string[]
const o = { a: 1, b: 2 };
Object.keys(o).forEach(k => {
  console.log(o[k]); // ❌ Element implicitly has 'any' type (with noImplicitAny)
});
// Fix:
(o[k as keyof typeof o]);

// fetch
const res = await fetch("/api");
const data = await res.json(); // any
```

**Edge case:** `Array.prototype.includes` with unions:

```ts
const arr: ("a" | "b")[] = ["a"];
arr.includes("c"); // ❌ Argument not assignable (TS 4.8+ with stricter includes)
```

**Edge case:** `Set.has`, `Map.get` similar strictness.

---

## 16. Type-only imports/exports & isolatedModules

```ts
import type { Foo } from "./foo";
import { type Bar, baz } from "./bar";

// With isolatedModules (e.g., Babel/SWC), `export { Foo }` re-exporting a type
// requires `export type { Foo }`.
```

**Edge case:** `verbatimModuleSyntax` (TS 5.0) enforces `import type` for type-only imports.

---

## 17. Promises & async

```ts
async function f(): Promise<number> { return 42; }
const p = f(); // Promise<number>
// Floating promise (no-floating-promises lint not built-in, but)
async function g() {
  f(); // unhandled promise — lint with eslint-plugin-promise
}

// Promise.all infers tuple for array literal
const [a, b] = await Promise.all([Promise.resolve(1), Promise.resolve("x")]);
// a: number, b: string
```

**Edge case:** `Promise.all` on a non-literal array widens to union:

```ts
const arr = [Promise.resolve(1), Promise.resolve("x")]; // (Promise<number>|Promise<string>)[]
const r = await Promise.all(arr); // (number|string)[]
```

---

## 18. Index signatures & excess props

```ts
interface Dict { [key: string]: number; }
const d: Dict = { a: 1, b: 2 };
d.c; // number (not number | undefined) unless noUncheckedIndexedAccess

// Mixing index signature with known props
interface Mixed {
  a: string;
  [key: string]: number | string; // index must include 'a's type
}
```

---

## 19. `satisfies` operator (TS 4.9+)

```ts
const palette = {
  red: [255, 0, 0],
  green: "#00ff00",
} satisfies Record<string, string | number[]>;

// palette.red is number[] (not widened), but checked against constraint
palette.red.push(1); // ok
```

**Edge case:** Use `satisfies` to keep narrow inference while validating shape.

---

## 20. `keyof`, indexed access, and `in` mapped keys

```ts
type T = { a: number; b: string };
type K = keyof T; // "a" | "b"
type V = T[K];    // number | string

// keyof of union is intersection of keys
type U = { a: number } | { b: string };
type KU = keyof U; // never
```

**Edge case:** `keyof` on primitive gives keys of boxed type (`keyof number` → methods).

---

## 21. Decorators & metadata (experimental)

Under `experimentalDecorators`, type info may not reflect runtime. With TS 5.0+ standard decorators, typing differs. Edge case: decorator metadata (`reflect-metadata`) is loosely typed.

---

## 22. Type assertion vs cast

```ts
const x = "123" as unknown as number; // double assertion bypasses safety
const y = <number>someValue; // JSX-incompatible syntax
```

**Edge case:** `as` doesn't convert at runtime; `Number(x)` does.

---

## 23. `readonly` & mutation

```ts
interface R { readonly x: number; }
const r: R = { x: 1 };
// r.x = 2; // ❌
const arr: readonly number[] = [1,2,3];
// arr.push(4); // ❌
// But deep mutation still allowed unless readonly recursively
```

**Edge case:** `DeepReadonly` not built-in; implement via mapped type.

---

## 24. `Function`, `object`, callable signatures

```ts
let f: Function = () => {}; // too loose; callable with any args
// Prefer specific signature:
type Fn = (x: number) => string;
```

---

## 25. Ambient / global augmentation

```ts
// global.d.ts
declare global {
  interface Window { myLib: any; }
}
export {};
```

**Edge case:** Missing `export {}` makes file a script, polluting global scope differently.

---

## 26. Module resolution & path mapping

Edge cases: `baseUrl`, `paths`, `moduleResolution: "bundler"` vs `"node"`. Types may resolve to wrong package; use `types` field and `exports` in package.json.

---

## 27. `noEmit`, `isolatedModules` interactions

- `const enum` + `isolatedModules` → error.
- Type-only re-exports need `export type`.

---

## 28. `this` in generic classes & `infer this`

```ts
class Box<T> {
  value: T;
  constructor(v: T) { this.value = v; }
  map<U>(fn: (x: T) => U): Box<U> { return new Box(fn(this.value)); }
}
```

---

## 29. Discriminated unions with optional discriminants

```ts
type E = { type: "a"; x: number } | { type: "b" };
function f(e: E) {
  if (e.type === "a") e.x; // ok
  // if discriminant missing in some variant, narrowing weakens
}
```

---

## 30. `Awaited`, `ReturnType`, inference of async

```ts
type R = Awaited<ReturnType<typeof asyncFn>>; // unwraps Promise
```

---

## Summary checklist

| Pitfall | Mitigation |
|---|---|
| `any` / implicit any | `unknown`, `noImplicitAny` |
| null/undefined | `strictNullChecks`, narrow |
| Union exhaustiveness | `never` check + `noFallthroughCasesInSwitch` |
| Structural typing | branded types |
| Literal widening | `as const`, `const` |
| Index access | `noUncheckedIndexedAccess` |
| Runtime JSON | validate with zod/io-ts |
| Enums numeric assignability | prefer union of literals |
| Floating promises | eslint `no-floating-promises` |
| `Object.keys` typing | cast keys |

**Recommendation:** Enable `strict`, `noUncheckedIndexedAccess`, `exactOptionalPropertyTypes`, `noImplicitOverride`, `verbatimModuleSyntax`, and pair with runtime validation (zod) at boundaries. TypeScript's type system is compile-time only; types do not exist at runtime.

Below is a complete, runnable TypeScript file that demonstrates several kinds of type conversion:

- primitive conversion with validation
- parsing booleans, numbers, dates, enums, and unions
- converting DTOs to domain models
- type guards (`value is T`)
- branded/nominal types
- safe conversion wrappers

Save it as `type-conversions.ts`.

```ts
// type-conversions.ts
// Run with: npx ts-node type-conversions.ts
// Or:      npx tsc --strict --target es2022 type-conversions.ts && node type-conversions.js

/* ----------------------------- Primitive conversions ----------------------------- */

export function toNumber(value: unknown): number {
  switch (typeof value) {
    case "number": {
      if (!Number.isFinite(value)) {
        throw new RangeError("Cannot convert non-finite number");
      }
      return value;
    }

    case "string": {
      const trimmed = value.trim();
      if (trimmed === "") {
        throw new TypeError("Empty string cannot be converted to a number");
      }
      const parsed = Number(trimmed);
      if (Number.isNaN(parsed)) {
        throw new TypeError(`Cannot convert string to number: ${JSON.stringify(value)}`);
      }
      return parsed;
    }

    case "boolean":
      return value ? 1 : 0;

    case "bigint": {
      const asNumber = Number(value);
      if (!Number.isSafeInteger(asNumber)) {
        throw new RangeError("BigInt is too large to convert safely to number");
      }
      return asNumber;
    }

    case "undefined":
      throw new TypeError("Cannot convert undefined to number");

    case "symbol":
      throw new TypeError("Cannot convert symbol to number");

    case "function":
    case "object": {
      if (value === null) return 0;
      return toNumber(String(value));
    }

    default: {
      // Exhaustiveness check: if a new primitive type is added, this fails to compile.
      const _exhaustive: never = value;
      throw new Error(`Unhandled type: ${String(_exhaustive)}`);
    }
  }
}

export function toString(value: unknown): string {
  if (value === null) return "null";
  if (value === undefined) return "undefined";

  switch (typeof value) {
    case "string":
      return value;
    case "number":
    case "boolean":
    case "bigint":
    case "symbol":
      return String(value);
    case "function":
      return value.toString();
    case "object": {
      try {
        return JSON.stringify(value);
      } catch {
        return String(value);
      }
    }
    default: {
      const _exhaustive: never = value;
      throw new Error(`Unhandled type: ${String(_exhaustive)}`);
    }
  }
}

export function toBoolean(value: unknown): boolean {
  if (typeof value === "boolean") return value;

  if (typeof value === "number") {
    if (Number.isNaN(value)) throw new TypeError("NaN cannot be converted to boolean");
    return value !== 0;
  }

  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (["true", "1", "yes", "y", "on"].includes(normalized)) return true;
    if (["false", "0", "no", "n", "off", ""].includes(normalized)) return false;
    throw new TypeError(`Cannot convert string to boolean: ${JSON.stringify(value)}`);
  }

  if (value === null || value === undefined) return false;

  // Objects, functions, symbols, and bigint follow normal truthiness.
  return Boolean(value);
}

/* ----------------------------- Domain parsing ----------------------------- */

export function parseBoolean(value: unknown): boolean {
  // Alias with a name that makes intent explicit in application code.
  return toBoolean(value);
}

export type Status = "pending" | "done" | "failed";

export function toStatus(value: unknown): Status {
  const normalized = toString(value).trim().toLowerCase();
  if (normalized === "pending" || normalized === "done" || normalized === "failed") {
    return normalized;
  }
  throw new TypeError(`Invalid status: ${JSON.stringify(value)}`);
}

export enum Role {
  Admin = "admin",
  User = "user",
  Guest = "guest",
}

export function toRole(value: unknown): Role {
  const normalized = toString(value).trim().toLowerCase();
  const roles = Object.values(Role) as string[];

  if (roles.includes(normalized)) {
    return normalized as Role;
  }

  throw new TypeError(`Invalid role: ${JSON.stringify(value)}`);
}

export function toDate(value: unknown): Date {
  if (value instanceof Date) {
    const time = value.getTime();
    if (Number.isNaN(time)) throw new TypeError("Invalid Date object");
    return new Date(time); // Return a copy to avoid mutation.
  }

  if (typeof value === "number") {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) throw new TypeError("Invalid timestamp");
    return date;
  }

  if (typeof value === "string") {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) throw new TypeError(`Invalid date string: ${value}`);
    return date;
  }

  throw new TypeError(`Cannot convert value to Date: ${toString(value)}`);
}

/* ----------------------------- Branded / nominal types ----------------------------- */

// A branded type is still a string at runtime, but TypeScript treats it as distinct.
export type Email = string & { readonly __brand: "Email" };

export function toEmail(value: unknown): Email {
  const email = toString(value).trim();
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailPattern.test(email)) {
    throw new TypeError(`Invalid email: ${JSON.stringify(email)}`);
  }

  return email as Email;
}

export type UserId = number & { readonly __brand: "UserId" };

export function toUserId(value: unknown): UserId {
  const id = toNumber(value);

  if (!Number.isInteger(id) || id <= 0) {
    throw new TypeError(`Invalid user id: ${JSON.stringify(value)}`);
  }

  return id as UserId;
}

/* ----------------------------- DTO -> domain model conversion ----------------------------- */

export interface UserDto {
  id: string;
  age: string;
  active: string;
  tags?: unknown;
}

export interface User {
  id: UserId;
  age: number;
  active: boolean;
  tags: string[];
}

export function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

export function isUserDto(value: unknown): value is UserDto {
  if (typeof value !== "object" || value === null) return false;

  const candidate = value as Record<string, unknown>;

  return (
    typeof candidate.id === "string" &&
    typeof candidate.age === "string" &&
    typeof candidate.active === "string" &&
    (candidate.tags === undefined || Array.isArray(candidate.tags))
  );
}

export function toUser(value: unknown): User {
  if (!isUserDto(value)) {
    throw new TypeError("Invalid UserDto");
  }

  const dto = value;

  return {
    id: toUserId(dto.id),
    age: toNumber(dto.age),
    active: toBoolean(dto.active),
    tags: isStringArray(dto.tags) ? dto.tags : [],
  };
}

/* ----------------------------- Generic conversion helper ----------------------------- */

export type Converter<T> = (value: unknown) => T;

export function convert<T>(value: unknown, converter: Converter<T>): T {
  return converter(value);
}

/* ----------------------------- Type guards for narrowing ----------------------------- */

export function isUser(value: unknown): value is User {
  try {
    // Reuse validation logic without throwing in the guard itself.
    const candidate = value as Partial<User>;

    return (
      typeof candidate?.id === "number" &&
      typeof candidate?.age === "number" &&
      typeof candidate?.active === "boolean" &&
      Array.isArray(candidate?.tags) &&
      candidate.tags.every((tag) => typeof tag === "string")
    );
  } catch {
    return false;
  }
}

/* ----------------------------- Demonstration ----------------------------- */

function main(): void {
  console.log("=== Primitive conversions ===");
  console.log(toNumber("42"));        // 42
  console.log(toNumber(true));       // 1
  console.log(toString(123));        // "123"
  console.log(toString({ a: 1 }));  // '{"a":1}'
  console.log(toBoolean("yes"));     // true
  console.log(toBoolean(0));         // false

  console.log("\n=== Domain values ===");
  console.log(toStatus("DONE"));     // "done"
  console.log(toRole("admin"));      // Role.Admin
  console.log(toDate("2025-01-01T00:00:00.000Z").toISOString());

  console.log("\n=== Branded types ===");
  const email = toEmail("alice@example.com");
  const userId = toUserId("99");
  console.log(email, userId);

  // TypeScript prevents accidental mixing of branded and plain values:
  // const wrong: UserId = 99; // Compile-time error

  console.log("\n=== DTO conversion ===");
  const dto: unknown = {
    id: "7",
    age: "30",
    active: "true",
    tags: ["typescript", "conversions"],
  };

  const user = toUser(dto);
  console.log(user);

  console.log("\n=== Type guard ===");
  if (isUser(user)) {
    console.log(`User ${user.id} has ${user.tags.length} tags`);
  }

  console.log("\n=== Generic converter ===");
  const port = convert(process.env.PORT ?? "3000", toNumber);
  console.log("Port:", port);

  console.log("\n=== Error handling ===");
  const badInputs: unknown[] = ["not-a-number", "maybe", "not-an-email", { bad: true }];

  for (const input of badInputs) {
    try {
      toEmail(input);
      console.log("Accepted:", input);
    } catch (error) {
      console.log("Rejected:", input, "->", (error as Error).message);
    }
  }
}

main();
```

## How to run

With `ts-node`:

```bash
npm install -D typescript ts-node
npx ts-node type-conversions.ts
```

Or compile first:

```bash
npx tsc --strict --target es2022 --module commonjs type-conversions.ts
node type-conversions.js
```

## Key ideas shown

1. **Compile-time types are not runtime values.**  
   TypeScript types disappear after compilation. Conversions that receive `unknown` data, such as JSON or environment variables, must validate at runtime.

2. **Use `unknown` instead of `any`.**  
   This forces validation before use and makes conversion functions safer.

3. **Type guards narrow types.**  
   `value is T` lets TypeScript know a value has a specific shape after the check.

4. **Branded types simulate nominal typing.**  
   `UserId` and `Email` are still numbers/strings at runtime, but TypeScript will not let you accidentally assign a plain `number` or `string` to them.

5. **DTO conversion centralizes mapping logic.**  
   Instead of scattering `as User` assertions across the codebase, one `toUser` function performs validation and conversion.

6. **Validation should throw meaningful errors.**  
   Conversion functions should fail fast when input cannot be safely converted.

This example is intentionally broad. In production, you might split these utilities into separate modules and add a schema validation library such as Zod or io-ts for larger applications.

## Type Conversions in TypeScript

TypeScript has **two different ideas** that are often confused:

1. **Type assertions** (compile-time): you tell the compiler “trust me, this value has this type.” They are erased at runtime and **do not convert** anything.
2. **Runtime conversions / coercion**: actual value transformations using JavaScript functions like `Number()`, `String()`, `Boolean()`, `parseInt()`, etc.

Below is a thorough tour of both.

---

### 1. The core idea of type assertions

Because TS types are erased at runtime, when you have a value typed too broadly (e.g. `unknown`, `any`, `Element`), you can **assert** a more specific type so the compiler allows member access.

```ts
const input = document.querySelector("#name") as HTMLInputElement;
input.value = "Ada"; // OK, because we asserted HTMLInputElement
```

Nothing changes at runtime: if `input` is actually `null` or a `<div>`, you still get a runtime error. Assertions are a **contract you are taking responsibility for**.

---

### 2. Assertion syntax

#### A. `as` (recommended, works everywhere including JSX)

```ts
const x = someValue as string;
```

#### B. Angle brackets (not usable in `.tsx` files)

```ts
const x = <string>someValue;
```

#### C. Double assertion (escape hatch)

When direct assertion is blocked by the compiler (no overlap), route through `unknown`:

```ts
const n = "42" as unknown as number; // compiles, but unsound
```

#### D. Non-null assertion `!`

Tells TS “this is not `null` / `undefined`”:

```ts
const el = document.getElementById("app")!; // Element, not Element | null
el.textContent = "hi";
```

#### E. `as const` (const assertion)

Makes literals readonly and as narrow as possible:

```ts
const roles = ["admin", "user"] as const;
// type: readonly ["admin", "user"]

const config = { port: 3000, host: "localhost" } as const;
// port: 3000 (literal), not number
```

Useful for tuple types, enum-like arrays, and discriminated unions.

#### F. `satisfies` (TS 4.9+)

Checks that a value matches a type **without widening** it:

```ts
type Route = { path: string; handler: () => void };

const r = {
  path: "/",
  handler() { console.log("home"); }
} satisfies Route;

// r.handler keeps its precise contextual type, but is validated against Route
```

Unlike `as`, `satisfies` errors if the value does not fit, and preserves the inferred literal type.

---

### 3. Typical use cases for assertions

#### A. DOM and browser APIs

```ts
const canvas = document.querySelector("canvas") as HTMLCanvasElement;
const ctx = canvas.getContext("2d")!; // null is possible at runtime
```

#### B. Parsing / deserializing untyped data

```ts
type User = { id: number; name: string };

const raw: unknown = JSON.parse(responseText);
const user = raw as User; // you are promising the shape; validate in real apps
```

Better: validate first, then assert:

```ts
function isUser(x: unknown): x is User {
  return typeof x === "object" && x !== null &&
         typeof (x as any).id === "number" &&
         typeof (x as any).name === "string";
}

if (isUser(raw)) {
  // raw is now User via type guard — no assertion needed
}
```

#### C. Narrowing union types after a check the compiler can’t track

```ts
function handle(e: Event) {
  const target = e.target as HTMLButtonElement;
  target.disabled = true;
}
```

#### D. Working with `any` from legacy code

```ts
const legacy: any = getFromOldLib();
const safe = legacy as { value: number };
console.log(safe.value.toFixed(2));
```

#### E. Const assertions for discriminated unions / routing tables

```ts
const actions = [
  { type: "add", amount: 1 },
  { type: "remove", id: 2 },
] as const;

type Action = (typeof actions)[number];
```

---

### 4. Runtime conversions (actual value transformation)

These are real JavaScript operations and change the value/type at runtime.

```ts
// String -> Number
const n1 = Number("42");        // 42
const n2 = parseInt("42px", 10); // 42
const n3 = parseFloat("3.14");   // 3.14
const n4 = +"42";                // 42 (unary +)

// Number -> String
const s1 = String(42);           // "42"
const s2 = (42).toString();      // "42"
const s3 = `${42}`;              // "42"

// Anything -> Boolean
const b1 = Boolean(0);           // false
const b2 = !!value;              // common idiom

// JSON round-trip (shallow clone + type boundary)
const copy = JSON.parse(JSON.stringify(obj));
```

#### Truthy/falsy gotchas

```ts
Number("")       // 0
Number("abc")    // NaN
Boolean("false") // true  (non-empty string)
parseInt("08")    // 8 (modern engines), but always pass radix 10
```

---

### 5. Pitfalls and best practices

| Pitfall | Fix |
|---|---|
| Asserting without validation | Use type guards / schema validation (Zod, io-ts) |
| `as any` sprinkled everywhere | Prefer `unknown` + narrowing |
| Double assertion to bypass errors | Treat as code smell; reconsider design |
| Angle brackets in `.tsx` | Use `as` |
| Non-null `!` hiding real nulls | Prefer optional chaining / explicit checks |
| Confusing assertion with conversion | Remember: `as` is erased; `Number()` is real |

#### Safe pattern: validate, then use

```ts
import { z } from "zod";

const UserSchema = z.object({ id: z.number(), name: z.string() });
type User = z.infer<typeof UserSchema>;

const raw: unknown = JSON.parse(text);
const user: User = UserSchema.parse(raw); // runtime validation + typed result
```

---

### 6. Quick reference

```ts
// Assertion (compile-time only)
const a = value as Foo;
const b = <Foo>value;            // not in JSX
const c = value as unknown as Foo; // escape hatch
const d = value!;                 // non-null
const e = value as const;         // literal/readonly

// Validation without widening
const f = value satisfies Foo;

// Runtime conversion
const g = Number(str);
const h = String(num);
const i = Boolean(x);
```

**Rule of thumb:** Use `as` only when you have evidence the compiler lacks. When data crosses a boundary (network, DOM, `JSON.parse`), prefer runtime validation. Use `as const` and `satisfies` to keep literal precision without losing safety.

### Mistake

```ts
function addOne(value: unknown): number {
  // Unsafe cast: tells TypeScript to trust us, but does nothing at runtime
  return (value as number) + 1;
}

console.log(addOne("42")); // "421" at runtime (string concatenation)
console.log(addOne(true)); // 2 at runtime
```

**What goes wrong**

- `value as number` is only a compile-time assertion. It does **not** convert the value.
- At runtime, `"42"` remains a string, so `+ 1` performs string concatenation and returns `"421"`.
- `true` becomes `2` because `true + 1 === 2`, which is rarely what you want.

### Corrected version

```ts
function addOne(value: unknown): number {
  const n = Number(value);

  if (Number.isNaN(n)) {
    throw new TypeError(`Expected a numeric value, got ${String(value)}`);
  }

  return n + 1;
}

console.log(addOne("42")); // 43
console.log(addOne(42));    // 43
// addOne("hello") throws
```

### Why this is better

- `Number(value)` performs a **real runtime conversion**, not just a type assertion.
- `Number.isNaN` safely rejects inputs that do not represent valid numbers (`"hello"`, `undefined`, objects, etc.).
- Throwing a clear error prevents silently wrong results.

### Extra notes / common pitfalls

- Prefer `Number.isNaN` over global `isNaN`; global `isNaN` coerces first (`isNaN("hello")` is `true`, but `isNaN(null)` is `false`).
- `parseInt`/`parseFloat` are lenient: `parseInt("42px")` returns `42`. Use them only when that parsing behavior is intentional, and always pass a radix (`parseInt(str, 10)`).
- `Boolean("false")` is `true` because any non-empty string is truthy. Convert booleans explicitly when needed.
- For stricter validation, consider schema libraries like Zod instead of manual checks.

## Exercise

**Task:** Implement `normalizeUser(input: unknown): User` that converts untrusted, loosely-typed data into a strict `User` object.

```ts
type User = {
  id: number;
  name: string;
  age: number | null;
  isActive: boolean;
  tags: string[];
};
```

Conversion rules:
- `id`: accept `number` or numeric `string`; otherwise throw.
- `name`: coerce to `string`, trim; empty → `"Anonymous"`.
- `age`: accept `number`/numeric `string`; invalid/missing → `null`; clamp to `0..120`.
- `isActive`: truthy-ish (`true`, `"true"`, `1`, `"1"`, `"yes"`) → `true`, else `false`.
- `tags`: if string, split on commas; if array, stringify each; otherwise `[]`.

---

## Step-by-step solution

### 1. Define the target type and a small set of guards/helpers

```ts
type User = {
  id: number;
  name: string;
  age: number | null;
  isActive: boolean;
  tags: string[];
};

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
```

### 2. Safe primitive converters

```ts
function toNumber(v: unknown): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const n = Number(v.trim());
    return Number.isFinite(n) ? n : null;
  }
  if (typeof v === "boolean") return v ? 1 : 0;
  return null;
}

function toString(v: unknown): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  return "";
}

function toBool(v: unknown): boolean {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    return s === "true" || s === "1" || s === "yes" || s === "y";
  }
  return false;
}
```

### 3. Implement `normalizeUser`

```ts
function normalizeUser(input: unknown): User {
  if (!isRecord(input)) {
    throw new TypeError("normalizeUser expects an object");
  }

  // id
  const rawId = input.id;
  const idNum = toNumber(rawId);
  if (idNum === null) {
    throw new TypeError(`Invalid id: ${String(rawId)}`);
  }
  const id = Math.trunc(idNum);

  // name
  const nameRaw = toString(input.name);
  const name = nameRaw.trim() || "Anonymous";

  // age
  const ageNum = toNumber(input.age);
  const age = ageNum === null ? null : Math.min(120, Math.max(0, Math.trunc(ageNum)));

  // isActive
  const isActive = toBool(input.isActive);

  // tags
  let tags: string[] = [];
  const rawTags = input.tags;
  if (Array.isArray(rawTags)) {
    tags = rawTags.map((t) => toString(t).trim()).filter(Boolean);
  } else if (typeof rawTags === "string") {
    tags = rawTags
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
  }

  return { id, name, age, isActive, tags };
}
```

### 4. Usage / tests

```ts
const samples: unknown[] = [
  { id: "42", name: "  Ada  ", age: "28", isActive: "yes", tags: "ts,js" },
  { id: 7, name: "", age: 150, isActive: 0, tags: ["a", 2, null] },
  { id: true, name: 123, age: "abc", isActive: "no", tags: 99 },
];

for (const s of samples) {
  console.log(normalizeUser(s));
}
```

Expected output (approx):
```ts
{ id: 42, name: "Ada", age: 28, isActive: true, tags: ["ts", "js"] }
{ id: 7, name: "Anonymous", age: 120, isActive: false, tags: ["a", "2"] }
{ id: 1, name: "123", age: null, isActive: false, tags: [] }
```

### Key takeaways
- **Narrow `unknown` first** with guards before touching properties.
- **Centralize conversions** (`toNumber`, `toString`, `toBool`) so edge cases live in one place.
- **Normalize, don’t just cast**: clamping, trimming, and fallbacks make data safe for downstream code.
- **Never trust input shape**; validate and convert at boundaries.

---

## Final solution (copy-paste ready)

```ts
type User = {
  id: number;
  name: string;
  age: number | null;
  isActive: boolean;
  tags: string[];
};

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function toNumber(v: unknown): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const n = Number(v.trim());
    return Number.isFinite(n) ? n : null;
  }
  if (typeof v === "boolean") return v ? 1 : 0;
  return null;
}

function toString(v: unknown): string {
  if (v === null || v === undefined) return "";
  if (typeof v === "string") return v;
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  return "";
}

function toBool(v: unknown): boolean {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    return s === "true" || s === "1" || s === "yes" || s === "y";
  }
  return false;
}

export function normalizeUser(input: unknown): User {
  if (!isRecord(input)) throw new TypeError("normalizeUser expects an object");

  const idNum = toNumber(input.id);
  if (idNum === null) throw new TypeError(`Invalid id: ${String(input.id)}`);

  const name = toString(input.name).trim() || "Anonymous";

  const ageNum = toNumber(input.age);
  const age = ageNum === null ? null : Math.min(120, Math.max(0, Math.trunc(ageNum)));

  const isActive = toBool(input.isActive);

  let tags: string[] = [];
  const rawTags = input.tags;
  if (Array.isArray(rawTags)) {
    tags = rawTags.map((t) => toString(t).trim()).filter(Boolean);
  } else if (typeof rawTags === "string") {
    tags = rawTags.split(",").map((t) => t.trim()).filter(Boolean);
  }

  return { id: Math.trunc(idNum), name, age, isActive, tags };
}
```

## Type conversions in TypeScript (interview-style)

I’d separate this into **compile-time** conversions (TypeScript’s type system) and **runtime** conversions (JavaScript coercion + our own helpers).

### 1) Compile-time conversions (TypeScript only)
- **Type assertions**: `value as T`, `<T>value`, `value!` (non-null), `satisfies`.
- **Narrowing**: `typeof`, `instanceof`, `in`, equality checks, custom type guards (`x is T`).
- **Utility/mapped types**: `Partial<T>`, `Required<T>`, `Readonly<T>`, `Pick<T,K>`, `Omit<T,K>`, `Record<K,V>`.
- **Conditional/template-literal types**: transform shapes at the type level.

These do **not** change runtime values; they only refine what the compiler believes.

### 2) Runtime conversions (JavaScript coercion)
- **Implicit coercion**: `+value`, `value + ""`, `!!value`, template strings.
- **Explicit coercion**: `Number()`, `String()`, `Boolean()`, `parseInt()`, `parseFloat()`.
- **Pitfalls**: `Number(null) === 0`, `Number(undefined) === NaN`, `Number("") === 0`, `Boolean("false") === true`.

### 3) A clean core implementation
Below is a small, reusable conversion core: primitive coercions with predictable rules, type guards, and a dispatcher.

```ts
// ---------- Type guards (compile-time narrowing) ----------

export function isString(v: unknown): v is string {
  return typeof v === "string";
}

export function isNumber(v: unknown): v is number {
  return typeof v === "number" && !Number.isNaN(v);
}

export function isBoolean(v: unknown): v is boolean {
  return typeof v === "boolean";
}

export function isNullish(v: unknown): v is null | undefined {
  return v === null || v === undefined;
}

// ---------- Primitive coercions (runtime) ----------

/** Convert anything to a finite-ish number with explicit rules. */
export function toNumber(value: unknown): number {
  if (isNumber(value)) return value;

  if (value === null) return 0;          // explicit: null -> 0
  if (value === undefined) return NaN;   // explicit: undefined -> NaN
  if (isBoolean(value)) return value ? 1 : 0;

  if (isString(value)) {
    const trimmed = value.trim();
    if (trimmed === "") return 0;        // explicit: "" -> 0
    const n = Number(trimmed);
    return n;                            // NaN if invalid
  }

  // Objects: rely on valueOf/toString via Number()
  try {
    return Number(value as any);
  } catch {
    return NaN;
  }
}

/** Convert anything to a string. */
export function toString(value: unknown): string {
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "symbol") return value.toString();
  if (typeof value === "bigint") return value.toString() + "n";
  return String(value);
}

/** Convert anything to a boolean using truthiness, but documented. */
export function toBoolean(value: unknown): boolean {
  // Note: Boolean("false") is true; that's intended JS behavior.
  return Boolean(value);
}

// ---------- Dispatcher ----------

export type PrimitiveTarget = "string" | "number" | "boolean";

export function convert(value: unknown, target: PrimitiveTarget): string | number | boolean {
  switch (target) {
    case "string":
      return toString(value);
    case "number":
      return toNumber(value);
    case "boolean":
      return toBoolean(value);
    default: {
      // Exhaustiveness check
      const _exhaustive: never = target;
      throw new Error(`Unsupported target: ${_exhaustive}`);
    }
  }
}

// ---------- Example usage ----------

const samples: unknown[] = [42, "  3.14  ", "", null, undefined, true, "false", { a: 1 }];

for (const s of samples) {
  console.log({
    value: s,
    asNumber: convert(s, "number"),
    asString: convert(s, "string"),
    asBoolean: convert(s, "boolean"),
  });
}
```

### Why this design
- **Predictable rules**: we document edge cases (`null`, `""`, `undefined`) instead of relying on surprise coercion.
- **Type safety**: type guards narrow `unknown` to concrete types; the dispatcher is exhaustive.
- **Extensible**: you can add `"bigint"`, `"date"`, or custom converters without changing the public API much.

### Compile-time conversion examples (no runtime change)

```ts
type User = { id: number; name: string; email?: string };

// Make all fields required and readonly at the type level
type StrictUser = Readonly<Required<User>>;

// Narrow via a custom guard
function isUser(v: unknown): v is User {
  return typeof v === "object" && v !== null && "id" in v && "name" in v;
}

// Type assertion when you *know* more than the compiler
const raw = JSON.parse('{"id":1,"name":"Ada"}') as User;
```

If you want, I can extend this into a **schema-driven converter** (e.g., convert API payloads into typed domain models with validation).

TypeScript has **two different kinds of “conversion”**:

1. **Compile-time type assertions/casts** (`as`, `!`, generic `as T`) change only the type checker’s view. The runtime value is unchanged.
2. **Runtime value conversions** (`Number`, `String`, `parseInt`, `Boolean`, `!!`, `String()`, etc.) actually transform values and have coercion rules.

Most bugs come from mixing these two.

## 1. `as` does not validate or transform anything

```ts
const input: unknown = "hello";

// Compiles, but `n` is still a string at runtime.
const n = input as number;

// Runtime error: toFixed is not a function
console.log(n.toFixed(2));
```

**Edge case:** asserting non-overlapping types usually requires going through `unknown`, which makes the lie explicit but still unsafe.

```ts
const x = "abc" as unknown as number; // compiles, nonsense at runtime
```

## 2. Non-null assertion `!` can lie

```ts
function getName(): string | null {
  return null;
}

// Compiles, then crashes at runtime.
const upper = getName()!.toUpperCase();
```

Safer:

```ts
const name = getName();
if (name !== null) {
  console.log(name.toUpperCase());
}
```

## 3. Runtime numeric coercion has surprising zeros and NaN

```ts
Number("");        // 0
Number(null);      // 0
Number(undefined); // NaN
Number(true);      // 1
Number("  42  ");  // 42
Number("42px");    // NaN

parseInt("42px", 10);   // 42  (partial parse)
parseInt("08", 10);     // 8
parseInt("10.5", 10);   // 10
parseInt("abc", 10);    // NaN

// Global isNaN coerces first; Number.isNaN does not.
isNaN("abc" as any);        // true
Number.isNaN("abc" as any); // false
```

Always use an explicit radix and prefer `Number.isNaN` and `Number.isFinite`.

## 4. Boolean coercion treats many values as true

```ts
Boolean("false"); // true
Boolean("0");     // true
!!"0";            // true
Boolean(0);       // false
Boolean("");      // false
Boolean(null);    // false
Boolean(undefined); // false
```

If you mean “is this defined and non-empty,” write that explicitly instead of relying on truthiness.

## 5. String conversion of null/undefined

```ts
String(null);      // "null"
String(undefined); // "undefined"
String({ a: 1 });  // "[object Object]"
String([1, 2]);    // "1,2"
```

This is especially dangerous in templates or logging.

```ts
const value: unknown = undefined;
const s = `${value}`; // "undefined", not an error
```

## 6. `JSON.parse` returns `any`, not your interface

```ts
interface User {
  id: number;
  name: string;
}

const raw = '{"id":"1","name":"Ada"}';

// Compiles, but `id` is a string at runtime.
const user = JSON.parse(raw) as User;

// Later code may assume number
const nextId = user.id + 1; // "11" at runtime
```

Safer boundary:

```ts
const parsed: unknown = JSON.parse(raw);

function isUser(x: unknown): x is User {
  return (
    typeof x === "object" &&
    x !== null &&
    typeof (x as any).id === "number" &&
    typeof (x as any).name === "string"
  );
}

if (isUser(parsed)) {
  console.log(parsed.id + 1);
}
```

For real applications, use a validation library (Zod, io-ts, Valibot).

## 7. Enums and reverse mappings

Numeric enums allow reverse lookup; string enums do not.

```ts
enum Status {
  Pending,
  Active,
}

const s = 99 as Status; // compiles, but 99 is not a real status
console.log(Status[s]);  // undefined at runtime

// Reverse mapping exists for numeric enums:
console.log(Status[0]); // "Pending"

enum Direction {
  Up = "UP",
  Down = "DOWN",
}

// No reverse mapping:
// Direction["UP"] is not defined as expected
```

Never cast arbitrary numbers/strings to enums without validation.

## 8. Union types require narrowing, not casting

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(shape: Shape): number {
  // Casting one member to another is unsafe:
  // const circle = shape as { kind: "circle"; radius: number };

  if (shape.kind === "circle") {
    return Math.PI * shape.radius ** 2;
  }

  return shape.side ** 2;
}
```

Exhaustive checking with `never`:

```ts
function area2(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    default:
      const exhaustive: never = shape;
      return exhaustive;
  }
}
```

If you later add a triangle variant, the `default` branch becomes a compile-time error.

## 9. `any` disables checking; `unknown` forces safe handling

```ts
const data: any = fetchSomething();

// No compiler help; mistakes silently pass.
const user = data as { id: number };
console.log(user.id.toFixed(2)); // may crash

// unknown requires narrowing.
const safer: unknown = fetchSomething();
if (typeof safer === "object" && safer !== null && "id" in safer) {
  // still need deeper checks before using as number
}
```

## 10. Object keys are strings, not keyof

```ts
const obj = { a: 1, b: 2 } as const;

// Object.keys returns string[]
Object.keys(obj).forEach((key) => {
  // obj[key] is a type error or unsafe
});

// Common cast, still only safe for plain objects you control:
const keys = Object.keys(obj) as Array<keyof typeof obj>;
keys.forEach((key) => {
  console.log(obj[key]); // number
});
```

Edge case: `Object.keys` ignores inherited and symbol keys and only returns enumerable string keys.

## 11. Array casts do not change runtime contents

```ts
const mixed: any[] = [1, "two", true];

// Compiles, but runtime array is still mixed.
const numbers = mixed as number[];
numbers.forEach((n) => console.log(n.toFixed(2))); // crash on "two"
```

Also, tuple casts can overstate length and positions:

```ts
const pair = [1, "a"] as [number, string];
pair.push("extra"); // allowed at runtime; tuple type may not reflect it
```

## 12. Readonly can be bypassed by assertion

```ts
const arr = [1, 2, 3] as readonly number[];

// Cast removes readonly from the type, but mutates the same object.
const mutable = arr as number[];
mutable.push(4);

console.log(arr); // [1, 2, 3, 4]
```

This is a common source of accidental mutation.

## 13. Class instance assertions are structural, not runtime

```ts
class UserAccount {
  id = 1;
  greet() {
    return "hi";
  }
}

const plain = { id: 1, greet: () => "hi" };

// Compiles because shape matches, but it is not an instance.
const account = plain as UserAccount;

console.log(account instanceof UserAccount); // false
```

If you need a real instance, construct it:

```ts
const real = new UserAccount();
```

## 14. Function casts can mismatch call-time values

```ts
const fn = ((x: string) => x.length) as (x: number) => number;

// Compiles, but passes a number where string behavior is expected.
const result = fn(123); // runtime: (123).length is undefined
```

## 15. Generic `as T` hides mismatched implementations

```ts
function parseAs<T>(value: unknown): T {
  return value as T;
}

// T is number, but runtime value is a string.
const n = parseAs<number>("not a number");
```

Prefer constrained generics plus runtime checks.

## 16. Type predicates can be wrong

```ts
function isNumber(x: unknown): x is number {
  return typeof x === "string"; // wrong predicate
}

const value: unknown = "hello";

if (isNumber(value)) {
  // TypeScript believes value is number
  console.log(value.toFixed(2)); // runtime crash
}
```

Type predicates are trusted by the compiler; implement them carefully.

## 17. Optional and missing properties

With `exactOptionalPropertyTypes`, these differ:

```ts
type Options = {
  timeout?: number;
};

const a: Options = {};                 // okay
const b: Options = { timeout: undefined }; // may error under exactOptionalPropertyTypes
```

Also, property access on possibly undefined values:

```ts
const map: Record<string, number> = {};
const value = map.missing; // type is number, but runtime undefined

// Safer:
const safe = map.missing ?? 0;
```

## 18. Index signatures and prototype surprises

```ts
const obj: Record<string, number> = Object.create(null);
obj.a = 1;

// Object.keys is okay, but `in` checks inherited keys too.
console.log("toString" in obj); // true for normal objects, false for null-proto
```

Use `Object.hasOwn(obj, key)` when you only want own properties.

## 19. Branded types can be bypassed

```ts
type UserId = string & { readonly brand: unique symbol };

// Compiles, but no real branding at runtime.
const id = "123" as UserId;
```

Brands are compile-time only. If you need real distinction, use classes or runtime tags.

## 20. `as const` changes inference, not runtime

```ts
const config = {
  port: 3000,
  host: "localhost",
} as const;

// config.port is 3000, not number
// config.host is "localhost", not string
```

This is useful for literal narrowing, but remember the object is still mutable unless frozen:

```ts
const mutable = config as { port: number; host: string };
mutable.port = 4000; // mutates the same object
```

## 21. `satisfies` (TS 4.9+) checks without widening as much

```ts
const settings = {
  port: "3000",
} satisfies { port: string | number };

// settings.port is "3000", not string | number
```

Use `satisfies` when you want validation while preserving precise inferred types. Use `as` only when you truly need to override inference.

## 22. Date conversion edge cases

```ts
const d = new Date("not a date");
console.log(d.getTime()); // NaN

const maybeDate = new Date("2024-01-01");
console.log(maybeDate.toISOString()); // okay

// Without `new`, Date returns a string, not a Date object.
const s = Date("2024-01-01");
console.log(typeof s); // "string"
```

## 23. Map and Set conversions

```ts
const entries = [["a", 1], ["b", 2]] as [string, number][];
const map = new Map(entries);

// Converting an object to a Map:
const obj = { a: 1, b: 2 };
const fromObj = new Map(Object.entries(obj));
// Values are strings? No: Object.entries values are number here, but typed broadly.
```

Edge: `Object.entries` types values as the object’s value type in modern TS, but runtime coercion may still surprise if input was parsed loosely.

## 24. `const` assertions with arrays and widening returns

```ts
function getModes() {
  return ["read", "write"] as const;
}

const modes = getModes(); // readonly ["read", "write"]
```

Without `as const`, it may widen to `string[]`, losing literal precision.

## Practical recommendations

- Treat `as` as an **escape hatch**, not a conversion function.
- Validate at trust boundaries: network responses, `localStorage`, query params, `JSON.parse`, environment variables.
- Prefer `unknown` over `any`.
- Use type guards with runtime checks, or a validation library.
- Use `satisfies` for config objects when you want checking plus precise inference.
- Use `Number.isNaN`, `Number.isFinite`, and explicit radix in `parseInt`.
- Avoid non-null assertions unless the invariant is provable locally.
- For enum-like values, prefer string literal unions and validate membership.

```ts
const allowed = new Set(["pending", "active"] as const);

function parseStatus(input: string): "pending" | "active" {
  if (!allowed.has(input as any)) {
    throw new Error(`Invalid status: ${input}`);
  }
  return input as "pending" | "active";
}
```

Even here, the final assertion is acceptable only because validation happened immediately before it.

Here is a complete, runnable TypeScript module that implements several core Unicode operations: UTF-8 encoding/decoding, UTF-16/code-point traversal, scalar-value validation, normalization, and grapheme-aware segmentation.

`unicode.ts`

```ts
// unicode.ts
// A small, self-contained Unicode utility module for TypeScript/Node.

export type CodePoint = number;

const MAX_CODE_POINT = 0x10ffff;
const SURROGATE_START = 0xd800;
const SURROGATE_END = 0xdfff;

/* ------------------------------------------------------------------ */
/* Basic classification                                               */
/* ------------------------------------------------------------------ */

export function isScalarValue(cp: number): boolean {
  return (
    Number.isInteger(cp) &&
    cp >= 0 &&
    cp <= MAX_CODE_POINT &&
    !(cp >= SURROGATE_START && cp <= SURROGATE_END)
  );
}

export function isHighSurrogate(unit: number): boolean {
  return unit >= 0xd800 && unit <= 0xdbff;
}

export function isLowSurrogate(unit: number): boolean {
  return unit >= 0xdc00 && unit <= 0xdfff;
}

/* ------------------------------------------------------------------ */
/* Code-point iteration over UTF-16 JavaScript strings                 */
/* ------------------------------------------------------------------ */

export function* codePoints(text: string): Generator<CodePoint> {
  for (let i = 0; i < text.length; ) {
    const cp = text.codePointAt(i);
    if (cp === undefined) break;
    yield cp;
    i += cp > 0xffff ? 2 : 1;
  }
}

export function toArray(text: string): CodePoint[] {
  return [...codePoints(text)];
}

export function fromCodePoints(points: Iterable<CodePoint>): string {
  let result = "";
  for (const cp of points) {
    if (!isScalarValue(cp)) {
      throw new RangeError(`Invalid Unicode scalar value: U+${cp.toString(16).toUpperCase()}`);
    }
    result += String.fromCodePoint(cp);
  }
  return result;
}

export function codePointCount(text: string): number {
  let count = 0;
  for (const _ of codePoints(text)) count++;
  return count;
}

export function reverseByCodePoints(text: string): string {
  return fromCodePoints([...codePoints(text)].reverse());
}

/* ------------------------------------------------------------------ */
/* UTF-8 encode / decode                                              */
/* ------------------------------------------------------------------ */

export function encodeUtf8(text: string): Uint8Array {
  const out: number[] = [];

  for (const ch of text) {
    const cp = ch.codePointAt(0)!;

    if (!isScalarValue(cp)) {
      throw new RangeError(`Cannot encode non-scalar U+${cp.toString(16)}`);
    }

    if (cp <= 0x7f) {
      out.push(cp);
    } else if (cp <= 0x7ff) {
      out.push(0xc0 | (cp >> 6));
      out.push(0x80 | (cp & 0x3f));
    } else if (cp <= 0xffff) {
      out.push(0xe0 | (cp >> 12));
      out.push(0x80 | ((cp >> 6) & 0x3f));
      out.push(0x80 | (cp & 0x3f));
    } else {
      out.push(0xf0 | (cp >> 18));
      out.push(0x80 | ((cp >> 12) & 0x3f));
      out.push(0x80 | ((cp >> 6) & 0x3f));
      out.push(0x80 | (cp & 0x3f));
    }
  }

  return new Uint8Array(out);
}

export function decodeUtf8(bytes: Uint8Array): string {
  let result = "";
  let i = 0;

  while (i < bytes.length) {
    const b0 = bytes[i];
    let cp = 0;
    let len = 0;

    if (b0 <= 0x7f) {
      cp = b0;
      len = 1;
    } else if ((b0 & 0xe0) === 0xc0) {
      cp = b0 & 0x1f;
      len = 2;
    } else if ((b0 & 0xf0) === 0xe0) {
      cp = b0 & 0x0f;
      len = 3;
    } else if ((b0 & 0xf8) === 0xf0) {
      cp = b0 & 0x07;
      len = 4;
    } else {
      throw new Error(`Invalid UTF-8 leading byte: 0x${b0.toString(16)}`);
    }

    if (i + len > bytes.length) {
      throw new Error("Truncated UTF-8 sequence");
    }

    for (let j = 1; j < len; j++) {
      const b = bytes[i + j];
      if ((b & 0xc0) !== 0x80) {
        throw new Error("Invalid UTF-8 continuation byte");
      }
      cp = (cp << 6) | (b & 0x3f);
    }

    // Reject overlong encodings and invalid scalars.
    if (len === 2 && cp < 0x80) throw new Error("Overlong UTF-8 sequence");
    if (len === 3 && cp < 0x800) throw new Error("Overlong UTF-8 sequence");
    if (len === 4 && cp < 0x10000) throw new Error("Overlong UTF-8 sequence");

    if (!isScalarValue(cp)) {
      throw new Error(`Invalid Unicode scalar value in UTF-8: U+${cp.toString(16)}`);
    }

    result += String.fromCodePoint(cp);
    i += len;
  }

  return result;
}

/* ------------------------------------------------------------------ */
/* UTF-16 helpers                                                     */
/* ------------------------------------------------------------------ */

export function encodeUtf16CodeUnits(text: string): number[] {
  const units: number[] = [];
  for (let i = 0; i < text.length; i++) {
    units.push(text.charCodeAt(i));
  }
  return units;
}

export function decodeUtf16CodeUnits(units: number[]): string {
  // String.fromCharCode handles surrogate pairs when they appear adjacent.
  return String.fromCharCode(...units);
}

/* ------------------------------------------------------------------ */
/* Normalization (delegates to the runtime, which implements UAX #15) */
/* ------------------------------------------------------------------ */

export type NormalizationForm = "NFC" | "NFD" | "NFKC" | "NFKD";

export function normalize(text: string, form: NormalizationForm = "NFC"): string {
  return text.normalize(form);
}

/* ------------------------------------------------------------------ */
/* Grapheme segmentation (UAX #29)                                     */
/* ------------------------------------------------------------------ */

export function graphemes(text: string): string[] {
  // Node 20+ / modern browsers provide Intl.Segmenter.
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const segmenter = new (Intl as any).Segmenter(undefined, {
      granularity: "grapheme",
    });
    return [...segmenter.segment(text)].map((s: any) => s.segment);
  }

  // Fallback: code points (not true graphemes, but better than UTF-16 units).
  return [...codePoints(text)].map((cp) => String.fromCodePoint(cp));
}

export function graphemeCount(text: string): number {
  return graphemes(text).length;
}

/* ------------------------------------------------------------------ */
/* Demo / tests                                                       */
/* ------------------------------------------------------------------ */

function assertEqual<T>(actual: T, expected: T, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${label}: expected ${e}, got ${a}`);
  }
  console.log(`PASS: ${label}`);
}

function main(): void {
  console.log("Unicode TypeScript demo\n");

  const emojiText = "Hello 👨‍👩‍👧‍👦 café 😊";
  console.log("Original:", emojiText);
  console.log("UTF-16 .length:", emojiText.length);
  console.log("Code points:", codePointCount(emojiText));
  console.log("Graphemes:", graphemeCount(emojiText));
  console.log("Grapheme list:", graphemes(emojiText));

  // Code points
  const cps = toArray(emojiText);
  assertEqual(fromCodePoints(cps), emojiText, "round-trip code points");

  // Reversal should operate on code points, not UTF-16 units.
  assertEqual(reverseByCodePoints("ab😀cd"), "dc😀ba", "reverseByCodePoints");

  // UTF-8 round trip
  const bytes = encodeUtf8(emojiText);
  assertEqual(decodeUtf8(bytes), emojiText, "UTF-8 round trip");
  console.log("UTF-8 byte length:", bytes.length);

  // Selected UTF-8 byte checks
  assertEqual(Array.from(encodeUtf8("A")), [0x41], "ASCII UTF-8");
  assertEqual(Array.from(encodeUtf8("é")), [0xc3, 0xa9], "2-byte UTF-8");
  assertEqual(Array.from(encodeUtf8("😀")), [0xf0, 0x9f, 0x98, 0x80], "4-byte UTF-8");

  // Normalization
  const composed = "é"; // U+00E9
  const decomposed = "e\u0301"; // e + combining acute
  assertEqual(normalize(decomposed, "NFC"), composed, "NFD-ish to NFC");
  assertEqual(normalize(composed, "NFD"), decomposed, "NFC to NFD");

  // Invalid scalar rejection
  let threw = false;
  try {
    fromCodePoints([0xd800]);
  } catch {
    threw = true;
  }
  assertEqual(threw, true, "reject surrogate scalar");

  // Grapheme cluster: family emoji with ZWJ should be one grapheme where supported.
  const family = "👨‍👩‍👧‍👦";
  console.log("Family grapheme count:", graphemeCount(family));
  if (graphemeCount(family) !== 1) {
    console.log("Note: runtime may not support full grapheme segmentation; got", graphemeCount(family));
  }

  console.log("\nAll assertions passed.");
}

main();
