## Core implementation (clean, commented)

Below is a small, dependency-free Unicode core for TypeScript. It focuses on **code points**, **surrogate pairs**, **UTF-8**, and **normalization**.

```ts
// unicode.ts

/** A UTF-16 code unit (0..0xFFFF). */
export type CodeUnit = number;

/** A Unicode scalar value (0..0x10FFFF, excluding surrogates). */
export type CodePoint = number;

export const UNICODE_MAX_CODE_POINT = 0x10FFFF;

/* ---------------- Surrogate helpers ---------------- */

export function isHighSurrogate(cu: CodeUnit): boolean {
  return cu >= 0xd800 && cu <= 0xdbff;
}

export function isLowSurrogate(cu: CodeUnit): boolean {
  return cu >= 0xdc00 && cu <= 0xdfff;
}

export function isSurrogate(cu: CodeUnit): boolean {
  return cu >= 0xd800 && cu <= 0xdfff;
}

/** Combine a valid surrogate pair into one code point. */
export function combineSurrogatePair(high: CodeUnit, low: CodeUnit): CodePoint {
  if (!isHighSurrogate(high) || !isLowSurrogate(low)) {
    throw new RangeError("Invalid surrogate pair");
  }
  return ((high - 0xd800) << 10) + (low - 0xdc00) + 0x10000;
}

/** Split a BMP-or-above code point into UTF-16 code units. */
export function splitCodePoint(cp: CodePoint): CodeUnit[] {
  if (cp < 0 || cp > UNICODE_MAX_CODE_POINT || isSurrogate(cp)) {
    throw new RangeError("Invalid code point");
  }
  if (cp <= 0xffff) return [cp];
  const adjusted = cp - 0x10000;
  return [0xd800 + (adjusted >> 10), 0xdc00 + (adjusted & 0x3ff)];
}

/* ---------------- Code-point iteration ---------------- */

/**
 * Iterate Unicode code points of a JS string.
 * Handles surrogate pairs; lone surrogates are yielded as-is.
 */
export function* codePoints(str: string): Generator<CodePoint> {
  let i = 0;
  const n = str.length;
  while (i < n) {
    const cu = str.charCodeAt(i);
    if (isHighSurrogate(cu) && i + 1 < n && isLowSurrogate(str.charCodeAt(i + 1))) {
      yield combineSurrogatePair(cu, str.charCodeAt(i + 1));
      i += 2;
    } else {
      yield cu;
      i += 1;
    }
  }
}

export function codePointLength(str: string): number {
  let count = 0;
  for (const _ of codePoints(str)) count++;
  return count;
}

export function toCodePointArray(str: string): CodePoint[] {
  return [...codePoints(str)];
}

export function fromCodePoints(cps: Iterable<CodePoint>): string {
  let out = "";
  for (const cp of cps) out += String.fromCodePoint(cp);
  return out;
}

/* ---------------- Normalization ---------------- */

export type NormalizationForm = "NFC" | "NFD" | "NFKC" | "NFKD";

export function normalize(str: string, form: NormalizationForm = "NFC"): string {
  return str.normalize(form);
}

/* ---------------- UTF-8 encode/decode ---------------- */

export function utf8Encode(str: string): Uint8Array {
  // Prefer native implementation when available.
  if (typeof TextEncoder !== "undefined") {
    return new TextEncoder().encode(str);
  }

  const bytes: number[] = [];
  for (const cp of codePoints(str)) {
    if (cp <= 0x7f) {
      bytes.push(cp);
    } else if (cp <= 0x7ff) {
      bytes.push(0xc0 | (cp >> 6));
      bytes.push(0x80 | (cp & 0x3f));
    } else if (cp <= 0xffff) {
      bytes.push(0xe0 | (cp >> 12));
      bytes.push(0x80 | ((cp >> 6) & 0x3f));
      bytes.push(0x80 | (cp & 0x3f));
    } else {
      bytes.push(0xf0 | (cp >> 18));
      bytes.push(0x80 | ((cp >> 12) & 0x3f));
      bytes.push(0x80 | ((cp >> 6) & 0x3f));
      bytes.push(0x80 | (cp & 0x3f));
    }
  }
  return new Uint8Array(bytes);
}

export function utf8Decode(bytes: Uint8Array): string {
  if (typeof TextDecoder !== "undefined") {
    return new TextDecoder().decode(bytes);
  }

  const cps: CodePoint[] = [];
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i++];
    let cp: CodePoint;
    if (b0 < 0x80) {
      cp = b0;
    } else if ((b0 & 0xe0) === 0xc0) {
      cp = ((b0 & 0x1f) << 6) | (bytes[i++] & 0x3f);
    } else if ((b0 & 0xf0) === 0xe0) {
      cp =
        ((b0 & 0x0f) << 12) |
        ((bytes[i++] & 0x3f) << 6) |
        (bytes[i++] & 0x3f);
    } else {
      cp =
        ((b0 & 0x07) << 18) |
        ((bytes[i++] & 0x3f) << 12) |
        ((bytes[i++] & 0x3f) << 6) |
        (bytes[i++] & 0x3f);
    }
    cps.push(cp);
  }
  return fromCodePoints(cps);
}

/* ---------------- Grapheme helper (runtime-dependent) ---------------- */

/**
 * Count user-perceived characters (grapheme clusters).
 * Falls back to code-point count if Intl.Segmenter is unavailable.
 */
export function graphemeLength(str: string): number {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const seg = new (Intl as any).Segmenter(undefined, { granularity: "grapheme" });
    let n = 0;
    for (const _ of seg.segment(str)) n++;
    return n;
  }
  return codePointLength(str);
}
```

### Usage example

```ts
import {
  codePointLength,
  toCodePointArray,
  utf8Encode,
  utf8Decode,
  normalize,
  graphemeLength,
} from "./unicode";

const emoji = "👨‍👩‍👧‍👦"; // family emoji (multiple code points + ZWJ)
console.log(emoji.length);          // UTF-16 code units
console.log(codePointLength(emoji)); // code points
console.log(graphemeLength(emoji));  // 1 user-perceived character

const bytes = utf8Encode("café");
console.log(utf8Decode(bytes));     // "café"

// Normalization example
const a = "e\u0301"; // e + combining acute
const b = "\u00e9";  // precomposed é
console.log(a === b);              // false
console.log(normalize(a) === normalize(b)); // true
```

### What I’d also mention in an interview

- **TypeScript types** don’t change runtime behavior; you can model branded types like `type Utf8Bytes = Uint8Array & { readonly __utf8: true }`, but enforcement is compile-time only.
- **Regex**: `/\p{Script=Latin}/u`, `\p{Emoji}`, etc. Require the `u` (or `v`) flag.
- **JSON/HTTP**: UTF-8 is the default wire format; `TextEncoder`/`TextDecoder` are the right tools.
- **Database/storage**: decide whether you store UTF-8 bytes or normalized NFC strings; consistency matters for search and uniqueness.
- **Performance**: code-point iteration is O(n); for hot paths, cache results or use native APIs.

If you want, I can also implement a **UTF-16 ↔ UTF-32 converter**, a **Unicode property escape helper**, or a **grapheme-aware `slice`** that never splits clusters.

