```ts
export interface Product {
  id: string;
  name: string;
  price: number; // in cents, integer, >= 0
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export type Discount =
  | { kind: "percent"; value: number }   // 0..100
  | { kind: "fixed"; value: number };    // cents

export class ShoppingCart {
  private readonly items = new Map<string, CartItem>();
  private discount: Discount | null = null;

  add(product: Product, quantity = 1): void {
    if (!product?.id) throw new Error("Product must have an id");
    if (product.price < 0 || !Number.isInteger(product.price)) {
      throw new Error("Price must be a non-negative integer (cents)");
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error("Quantity must be a positive integer");
    }

    const existing = this.items.get(product.id);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.set(product.id, { product, quantity });
    }
  }

  remove(productId: string): boolean {
    return this.items.delete(productId);
  }

  updateQuantity(productId: string, quantity: number): void {
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new Error("Quantity must be a non-negative integer");
    }
    const item = this.items.get(productId);
    if (!item) throw new Error(`Item not in cart: ${productId}`);
    if (quantity === 0) {
      this.items.delete(productId);
    } else {
      item.quantity = quantity;
    }
  }

  get itemsList(): CartItem[] {
    return [...this.items.values()];
  }

  get subtotal(): number {
    let total = 0;
    for (const { product, quantity } of this.items.values()) {
      total += product.price * quantity;
    }
    return total;
  }

  applyDiscount(code: string): void {
    const normalized = code.trim().toUpperCase();
    switch (normalized) {
      case "SAVE10":
        this.discount = { kind: "percent", value: 10 };
        break;
      case "FIVEOFF":
        this.discount = { kind: "fixed", value: 500 };
        break;
      default:
        throw new Error(`Unknown discount code: ${code}`);
    }
  }

  clearDiscount(): void {
    this.discount = null;
  }

  get discountAmount(): number {
    if (!this.discount) return 0;
    if (this.discount.kind === "percent") {
      return Math.round(this.subtotal * (this.discount.value / 100));
    }
    return Math.min(this.discount.value, this.subtotal);
  }

  get total(): number {
    return Math.max(0, this.subtotal - this.discountAmount);
  }

  clear(): void {
    this.items.clear();
    this.discount = null;
  }

  get isEmpty(): boolean {
    return this.items.size === 0;
  }
}
```

## 5. Tests — `tests/cart.test.ts`

```ts
import { describe, it, expect, beforeEach } from "vitest";
import { ShoppingCart } from "../src/cart";
import type { Product } from "../src/cart";

const apple: Product = { id: "apple", name: "Apple", price: 120 };
const banana: Product = { id: "banana", name: "Banana", price: 80 };

describe("ShoppingCart", () => {
  let cart: ShoppingCart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe("add", () => {
    it("adds a new product with default quantity 1", () => {
      cart.add(apple);
      expect(cart.itemsList).toEqual([{ product: apple, quantity: 1 }]);
    });

    it("accumulates quantity when adding the same product twice", () => {
      cart.add(apple, 2);
      cart.add(apple, 3);
      expect(cart.itemsList).toHaveLength(1);
      expect(cart.itemsList[0]?.quantity).toBe(5);
    });

    it("throws on non-positive or non-integer quantity", () => {
      expect(() => cart.add(apple, 0)).toThrow(/positive integer/);
      expect(() => cart.add(apple, 1.5)).toThrow(/positive integer/);
      expect(() => cart.add(apple, -1)).toThrow(/positive integer/);
    });

    it("throws on invalid price", () => {
      expect(() => cart.add({ id: "x", name: "X", price: -1 })).toThrow(/non-negative/);
      expect(() => cart.add({ id: "x", name: "X", price: 1.5 })).toThrow(/non-negative/);
    });

    it("throws when product has no id", () => {
      expect(() => cart.add({ id: "", name: "X", price: 10 })).toThrow(/id/);
    });
  });

  describe("remove / updateQuantity", () => {
    beforeEach(() => cart.add(apple, 2));

    it("removes an existing item", () => {
      expect(cart.remove("apple")).toBe(true);
      expect(cart.isEmpty).toBe(true);
    });

    it("returns false when removing a missing item", () => {
      expect(cart.remove("nope")).toBe(false);
    });

    it("updates quantity", () => {
      cart.updateQuantity("apple", 5);
      expect(cart.itemsList[0]?.quantity).toBe(5);
    });

    it("deletes item when quantity set to 0", () => {
      cart.updateQuantity("apple", 0);
      expect(cart.isEmpty).toBe(true);
    });

    it("throws when updating missing item", () => {
      expect(() => cart.updateQuantity("nope", 1)).toThrow(/not in cart/);
    });

    it("throws on invalid quantity", () => {
      expect(() => cart.updateQuantity("apple", -1)).toThrow(/non-negative/);
      expect(() => cart.updateQuantity("apple", 1.2)).toThrow(/non-negative/);
    });
  });

  describe("totals", () => {
    it("computes subtotal", () => {
      cart.add(apple, 2);   // 240
      cart.add(banana, 3);  // 240
      expect(cart.subtotal).toBe(480);
    });

    it("returns 0 for empty cart", () => {
      expect(cart.subtotal).toBe(0);
      expect(cart.total).toBe(0);
    });

    it("applies percent discount", () => {
      cart.add(apple, 2); // 240
      cart.applyDiscount("save10");
      expect(cart.discountAmount).toBe(24);
      expect(cart.total).toBe(216);
    });

    it("applies fixed discount capped at subtotal", () => {
      cart.add(apple, 1); // 120
      cart.applyDiscount("FIVEOFF"); // 500 cents
      expect(cart.discountAmount).toBe(120);
      expect(cart.total).toBe(0);
    });

    it("throws on unknown discount code", () => {
      expect(() => cart.applyDiscount("NOPE")).toThrow(/Unknown discount/);
    });

    it("clearDiscount removes discount", () => {
      cart.add(apple, 1);
      cart.applyDiscount("SAVE10");
      cart.clearDiscount();
      expect(cart.discountAmount).toBe(0);
      expect(cart.total).toBe(120);
    });

    it("clear resets everything", () => {
      cart.add(apple, 1);
      cart.applyDiscount("SAVE10");
      cart.clear();
      expect(cart.isEmpty).toBe(true);
      expect(cart.discountAmount).toBe(0);
    });
  });

  describe("parameterized: quantity × price", () => {
    it.each([
      [1, 100, 100],
      [3, 50, 150],
      [10, 0, 0]
    ])("qty=%i price=%i => subtotal=%i", (qty, price, expected) => {
      const p: Product = { id: "p", name: "P", price };
      cart.add(p, qty);
      expect(cart.subtotal).toBe(expected);
    });
  });
});
```

