## Unit Testing in TypeScript — Interview Answer

**What it is:** Unit testing verifies the smallest testable units (functions/classes) in isolation, fast and deterministic.

**Core concepts:**
- **AAA pattern:** Arrange (setup), Act (call), Assert (verify).
- **Isolation:** Replace dependencies with mocks/stubs/spies so one unit’s failure isn’t caused by another.
- **Determinism:** No real network/time/randomness; control inputs.
- **Coverage & regression:** Tests document behavior and catch regressions.
- **TypeScript specifics:** Use strong types for fixtures, generics in matchers (`expect<T>`), async tests with `Promise`, and typed mocks.

**Common tools:** Jest, Vitest, Mocha + Chai. Under the hood they all do the same three things: **register tests → run them → assert & report**.

Below is a minimal, dependency-free implementation of that core in TypeScript.

```ts
// minimal-test-core.ts
// A tiny unit-testing core: registration (describe/it), assertions (expect),
// async runner, reporting, and a simple spy. Run with: npx ts-node minimal-test-core.ts

/* ----------------------------- Types ----------------------------- */

type TestFn = () => void | Promise<void>;

interface TestEntry {
  name: string;
  fn: TestFn;
}

interface Suite {
  name: string;
  tests: TestEntry[];
}

interface TestResult {
  name: string;
  passed: boolean;
  error?: Error;
  durationMs: number;
}

/* ----------------------------- Errors ----------------------------- */

class AssertionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "AssertionError";
  }
}

/* ----------------------------- State ----------------------------- */

const suites: Suite[] = [];
let currentSuite: Suite | null = null;

/* ----------------------------- Registration ----------------------------- */

/** Group related tests; creates a suite scope. */
function describe(suiteName: string, fn: () => void): void {
  const suite: Suite = { name: suiteName, tests: [] };
  const previous = currentSuite;
  currentSuite = suite;
  suites.push(suite);
  try {
    fn(); // tests registered here are pushed into `suite`
  } finally {
    currentSuite = previous;
  }
}

/** Register a single test case. Must be called inside describe(). */
function it(testName: string, fn: TestFn): void {
  if (!currentSuite) {
    throw new Error("it() must be called inside describe()");
  }
  currentSuite.tests.push({ name: testName, fn });
}

/* ----------------------------- Assertions ----------------------------- */

/** Deep equality for toEqual (handles arrays/objects/primitives). */
function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (typeof a !== "object" || a === null || typeof b !== "object" || b === null) {
    return false;
  }
  const ka = Object.keys(a as object);
  const kb = Object.keys(b as object);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => deepEqual((a as any)[k], (b as any)[k]));
}

/** Generic expectation wrapper; T gives type-safe matchers. */
class Expectation<T> {
  constructor(private readonly actual: T) {}

  /** Strict equality (===). */
  toBe(expected: T): void {
    if (this.actual !== expected) {
      throw new AssertionError(
        `Expected ${String(this.actual)} to be ${String(expected)}`
      );
    }
  }

  /** Deep equality for objects/arrays. */
  toEqual(expected: T): void {
    if (!deepEqual(this.actual, expected)) {
      throw new AssertionError(
        `Expected ${JSON.stringify(this.actual)} to equal ${JSON.stringify(expected)}`
      );
    }
  }

  toBeTruthy(): void {
    if (!this.actual) {
      throw new AssertionError(`Expected truthy, got ${String(this.actual)}`);
    }
  }

  toBeFalsy(): void {
    if (this.actual) {
      throw new AssertionError(`Expected falsy, got ${String(this.actual)}`);
    }
  }

  /** Asserts that a function throws. */
  toThrow(matcher?: string | RegExp | (new (...args: any[]) => Error)): void {
    if (typeof this.actual !== "function") {
      throw new AssertionError("toThrow requires a function as the actual value");
    }
    let thrown: unknown;
    try {
      (this.actual as (...a: any[]) => unknown)();
    } catch (e) {
      thrown = e;
    }
    if (thrown === undefined) {
      throw new AssertionError("Expected function to throw, but it did not");
    }
    if (matcher === undefined) return;

    const message = thrown instanceof Error ? thrown.message : String(thrown);

    if (matcher instanceof RegExp) {
      if (!matcher.test(message)) {
        throw new AssertionError(`Expected throw matching ${matcher}, got "${message}"`);
      }
    } else if (typeof matcher === "string") {
      if (!message.includes(matcher)) {
        throw new AssertionError(`Expected throw containing "${matcher}", got "${message}"`);
      }
    } else if (typeof matcher === "function") {
      if (!(thrown instanceof matcher)) {
        throw new AssertionError(`Expected throw instance of ${matcher.name}`);
      }
    }
  }
}

/** Entry point for assertions. */
function expect<T>(actual: T): Expectation<T> {
  return new Expectation(actual);
}

/* ----------------------------- Spies (minimal mock) ----------------------------- */

interface Spy<T extends (...args: any[]) => any> {
  calls: Parameters<T>[];
  restore: () => void;
}

/** Spy on a method of an object; records calls and delegates to original. */
function spyOn<T extends object, K extends keyof T & string>(
  obj: T,
  method: K
): Spy<T[K] extends (...a: any[]) => any ? T[K] : never> {
  const original = obj[method] as (...a: any[]) => any;
  const calls: any[][] = [];
  (obj as any)[method] = (...args: any[]) => {
    calls.push(args);
    return original?.apply(obj, args);
  };
  return {
    calls,
    restore: () => {
      (obj as any)[method] = original;
    },
  } as any;
}

/* ----------------------------- Runner ----------------------------- */

/** Run all registered suites; print a summary; return results. */
async function runTests(): Promise<TestResult[]> {
  const results: TestResult[] = [];

  for (const suite of suites) {
    for (const test of suite.tests) {
      const start = Date.now();
      try {
        await test.fn(); // supports sync + async tests
        results.push({
          name: `${suite.name} > ${test.name}`,
          passed: true,
          durationMs: Date.now() - start,
        });
      } catch (err) {
        results.push({
          name: `${suite.name} > ${test.name}`,
          passed: false,
          error: err instanceof Error ? err : new Error(String(err)),
          durationMs: Date.now() - start,
        });
      }
    }
  }

  const passed = results.filter((r) => r.passed).length;
  const failed = results.length - passed;

  console.log(`\n${passed} passed, ${failed} failed\n`);
  for (const r of results) {
    console.log(`${r.passed ? "✓" : "✗"} ${r.name} (${r.durationMs}ms)`);
    if (!r.passed && r.error) {
      console.log(`   └─ ${r.error.name}: ${r.error.message}`);
    }
  }
  return results;
}

/* ----------------------------- Example Usage ----------------------------- */

describe("Math", () => {
  it("adds numbers", () => {
    expect(1 + 2).toBe(3);
  });

  it("compares objects deeply", () => {
    expect({ a: [1, 2], b: { c: 3 } }).toEqual({ a: [1, 2], b: { c: 3 } });
  });

  it("handles async code", async () => {
    const value = await Promise.resolve(42);
    expect(value).toBe(42);
  });

  it("asserts thrown errors", () => {
    expect(() => {
      throw new TypeError("bad input");
    }).toThrow(TypeError);
  });
});

describe("Spy", () => {
  it("records calls", () => {
    const obj = { greet: (name: string) => `hi ${name}` };
    const spy = spyOn(obj, "greet");

    expect(obj.greet("Ada")).toBe("hi Ada");
    expect(spy.calls.length).toBe(1);
    expect(spy.calls[0][0]).toBe("Ada");

    spy.restore();
  });
});

// Run when executed directly.
runTests();
```

**How to run:**
```bash
npm i -D ts-node typescript
npx ts-node minimal-test-core.ts
```

**Interview talking points to add verbally:**
- Prefer **pure functions** and dependency injection so units are trivially testable.
- Use **test doubles** (mocks for behavior verification, stubs for predetermined responses).
- Keep tests **fast, isolated, readable** (one assertion concept per test).
- In real projects, use Jest/Vitest for parallelization, coverage, snapshot testing, and TS support out of the box.

Below are the most common edge cases that break TypeScript unit tests, grouped by theme. Examples use **Jest** (the same patterns apply to Vitest with minor import differences). Each snippet is self-contained and runnable.

---

## 1. Async timing & unhandled rejections

### a) Forgetting to `await` (false positives)
```ts
// BAD: test passes even if promise rejects
it('saves user', () => {
  saveUser({ id: 1 }); // returns Promise<void>
});

// GOOD
it('saves user', async () => {
  await expect(saveUser({ id: 1 })).resolves.toBeUndefined();
});
