# Value vs. Reference Semantics in TypeScript

In TypeScript (and JavaScript), **primitives** (`number`, `string`, `boolean`, `null`, `undefined`, `symbol`, `bigint`) have **value semantics** — assignment copies the value. **Objects** (`object`, arrays, functions, classes) have **reference semantics** — assignment copies a pointer, so mutations are shared.

Below is a single, runnable file that (1) demonstrates both, and (2) implements **value semantics for objects** via deep cloning, structural equality, and an immutable `Value<T>` wrapper with copy-on-write updates.

Save as `value-ref.ts` and run with `npx tsx value-ref.ts` (or `bun run value-ref.ts` / `deno run value-ref.ts`).

```ts
// value-ref.ts
// ─────────────────────────────────────────────────────────────
// 1. Built-in value semantics (primitives)
// ─────────────────────────────────────────────────────────────

function demoPrimitives(): void {
  let a = 42;
  let b = a;          // copy the value
  b = 100;
  console.log("primitives:", a, b); // 42 100  -> independent

  const s1 = "hi";
  const s2 = s1;
  // s2 = s1 + "!" would just rebind; no mutation possible on string
  console.log("strings:", s1, s2);
}

// ─────────────────────────────────────────────────────────────
// 2. Built-in reference semantics (objects)
// ─────────────────────────────────────────────────────────────

function demoReferences(): void {
  const p1 = { x: 1, y: 2 };
  const p2 = p1;        // copy the reference
  p2.x = 99;
  console.log("refs:", p1, p2); // both show x: 99

  const arr1 = [1, 2, 3];
  const arr2 = arr1;
  arr2.push(4);
  console.log("arrays:", arr1, arr2); // both [1,2,3,4]
}

// ─────────────────────────────────────────────────────────────
// 3. Implementing value semantics for objects
// ─────────────────────────────────────────────────────────────

// ---- 3a. Deep clone (structural copy) ----------------------

type Cloneable =
  | null
  | undefined
  | boolean
  | number
  | string
  | bigint
  | symbol
  | Date
  | RegExp
  | Map<unknown, unknown>
  | Set<unknown>
  | { [k: string]: unknown }
  | unknown[];

function deepClone<T>(value: T): T {
  // Primitives & null/undefined are already values.
  if (value === null || typeof value !== "object") {
    return value;
  }
  // Special objects
  if (value instanceof Date) return new Date(value.getTime()) as T;
  if (value instanceof RegExp) return new RegExp(value.source, value.flags) as T;
  if (value instanceof Map) {
    const m = new Map();
    for (const [k, v] of value) m.set(deepClone(k), deepClone(v));
    return m as T;
  }
  if (value instanceof Set) {
    const s = new Set();
    for (const v of value) s.add(deepClone(v));
    return s as T;
  }
  if (Array.isArray(value)) {
    return value.map(deepClone) as T;
  }
  // Plain object
  const out: Record<string, unknown> = {};
  for (const key of Object.keys(value as object)) {
    out[key] = deepClone((value as Record<string, unknown>)[key]);
  }
  return out as T;
}

// ---- 3b. Structural equality -------------------------------

function deepEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;            // primitives & same ref
  if (typeof a !== "object" || typeof b !== "object") return false;
  if (a === null || b === null) return false;
  if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof RegExp && b instanceof RegExp)
    return a.source === b.source && a.flags === b.flags;
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [k, v] of a) if (!b.has(k) || !deepEqual(v, b.get(k))) return false;
    return true;
  }
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const v of a) {
      let found = false;
      for (const w of b) if (deepEqual(v, w)) { found = true; break; }
      if (!found) return false;
    }
    return true;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((x, i) => deepEqual(x, b[i]));
  }
  const ka = Object.keys(a as object);
  const kb = Object.keys(b as object);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => deepEqual((a as any)[k], (b as any)[k]));
}

// ---- 3c. Value<T>: immutable, copy-on-write value object ----

class Value<T extends object> {
  private readonly data: T;

  constructor(data: T) {
    // Freeze a deep clone so the stored state can never be mutated externally.
    this.data = deepFreeze(deepClone(data));
  }

  /** Read-only access to the underlying data. */
  get(): T {
    return this.data;
  }

  /** Structural equality. */
  equals(other: Value<T> | T): boolean {
    const otherData = other instanceof Value ? other.data : other;
    return deepEqual(this.data, otherData);
  }

  /** Copy-on-write: returns a NEW Value with the patch applied. */
  set<K extends keyof T>(key: K, value: T[K]): Value<T> {
    const next = deepClone(this.data);
    next[key] = deepClone(value);
    return new Value(next);
  }

  /** Deep patch via a recipe function (immutable update). */
  update(recipe: (draft: T) => void): Value<T> {
    const draft = deepClone(this.data);
    recipe(draft);
    return new Value(draft);
  }

  /** Serialize for debugging. */
  toString(): string {
    return JSON.stringify(this.data);
  }
}

function deepFreeze<T>(obj: T): T {
  if (obj === null || typeof obj !== "object") return obj;
  Object.freeze(obj);
  for (const key of Object.keys(obj as object)) {
    deepFreeze((obj as any)[key]);
  }
  if (obj instanceof Map || obj instanceof Set) {
    // freeze entries too
    for (const v of (obj as any).values()) deepFreeze(v);
  }
  if (Array.isArray(obj)) obj.forEach(deepFreeze);
  return obj;
}

// ─────────────────────────────────────────────────────────────
// 4. Demonstration / sanity checks
// ─────────────────────────────────────────────────────────────

function runChecks(): void {
  const v1 = new Value({ point: { x: 1, y: 2 }, tags: ["a", "b"] });

  // Mutation isolation: original stays intact
  const v2 = v1.set("point", { x: 9, y: 9 } as any);
  console.log("v1:", v1.toString());
  console.log("v2:", v2.toString());
  console.assert(v1.get().point.x === 1, "original mutated!");

  // Structural equality
  const v3 = new Value({ point: { x: 1, y: 2 }, tags: ["a", "b"] });
  console.log("equals:", v1.equals(v3)); // true
  console.assert(v1.equals(v3) === true, "equality failed");

  // Array update via recipe
  const v4 = v1.update((d) => { d.tags.push("c"); });
  console.log("v4:", v4.toString());
  console.assert(v1.get().tags.length === 2, "source mutated by update");

  // Deep clone utility
  const src = { nested: { n: 5 }, list: [1, 2] };
  const cp = deepClone(src);
  cp.nested.n = 999;
  cp.list.push(3);
  console.log("clone isolated:", src, cp);
  console.assert(src.nested.n === 5 && src.list.length === 2, "clone not isolated");

  // Reference trap vs value copy
  const refA = { n: 1 };
  const refB = refA;
  refB.n = 2;
  console.log("ref trap:", refA.n); // 2
  const valA = new Value({ n: 1 });
  const valB = valA.set("n", 2 as any);
  console.log("value trap:", valA.get().n, valB.get().n); // 1 2

  console.log("ALL CHECKS PASSED");
}

demoPrimitives();
demoReferences();
runChecks();
```

