# Variables and Data Types in TypeScript

TypeScript adds a static type system on top of JavaScript. The key ideas are:

- **Variables** are declared with `let`, `const`, or (legacy) `var`.
- **Types** can be explicit (`: number`) or inferred by the compiler.
- TypeScript supports **primitives**, **special types**, **arrays/tuples**, **unions/intersections**, **aliases/interfaces**, **enums**, **literal types**, and **type assertions**.

Below is a complete, runnable example. Save it as `variables-and-types.ts`.

## Runnable example

```ts
// variables-and-types.ts
// Run with:
//   npx ts-node variables-and-types.ts
// or compile:
//   npx tsc variables-and-types.ts && node variables-and-types.js

/* ------------------------------------------------------------------ */
/* 1. Variable declarations and inference                               */
/* ------------------------------------------------------------------ */

let mutable: string = "I can change";
const immutable: number = 42;          // cannot be reassigned
var legacy: boolean = true;            // function/global scoped; avoid in modern code

let inferred = 100;                    // inferred as number
// inferred = "text";                  // ❌ Error: Type 'string' is not assignable to type 'number'

/* ------------------------------------------------------------------ */
/* 2. Primitive types                                                   */
/* ------------------------------------------------------------------ */

const name: string = "Alice";
const age: number = 30;               // integer or float
const active: boolean = true;
const big: bigint = 9007199254740991n;
const sym: symbol = Symbol("id");
let maybeNull: string | null = null;
let notSet: undefined = undefined;

/* ------------------------------------------------------------------ */
/* 3. Special types                                                     */
/* ------------------------------------------------------------------ */

let anything: any = "anything goes";   // opts out of type checking (avoid)
let safeUnknown: unknown = 5;          // safer: must narrow before use

function logMessage(msg: string): void {
  console.log(msg);
}

function fail(msg: string): never {
  throw new Error(msg);
}

/* ------------------------------------------------------------------ */
/* 4. Arrays and tuples                                                 */
/* ------------------------------------------------------------------ */

const nums: number[] = [1, 2, 3];
const strs: Array<string> = ["a", "b", "c"];
const tuple: [string, number, boolean] = ["age", 30, true];
const readonlyArr: readonly number[] = [1, 2, 3];
// readonlyArr.push(4);               // ❌ Error

/* ------------------------------------------------------------------ */
/* 5. Union and intersection types                                      */
/* ------------------------------------------------------------------ */

type ID = string | number;
const id1: ID = "abc-123";
const id2: ID = 42;

type Named = { name: string };
type Aged = { age: number };
type Person = Named & Aged;            // must have both properties

const person: Person = { name: "Bob", age: 25 };

/* ------------------------------------------------------------------ */
/* 6. Type aliases and interfaces                                       */
/* ------------------------------------------------------------------ */

type Point = { x: number; y: number };

interface User {
  id: number;
  name: string;
  email?: string;                     // optional
  readonly createdAt: Date;          // readonly property
}

const point: Point = { x: 10, y: 20 };
const user: User = {
  id: 1,
  name: "Carol",
  createdAt: new Date(),
};

/* ------------------------------------------------------------------ */
/* 7. Enums                                                             */
/* ------------------------------------------------------------------ */

enum Color {
  Red,       // 0
  Green,     // 1
  Blue,      // 2
}

enum Direction {
  Up = "UP",
  Down = "DOWN",
  Left = "LEFT",
  Right = "RIGHT",
}

const favoriteColor: Color = Color.Green;

/* ------------------------------------------------------------------ */
/* 8. Literal types and const assertions                                */
/* ------------------------------------------------------------------ */

type Status = "pending" | "done" | "error";
let status: Status = "pending";

const palette = {
  red: [255, 0, 0],
  green: [0, 255, 0],
} as const;                             // deeply readonly literal types

type Palette = typeof palette;

/* ------------------------------------------------------------------ */
/* 9. Type assertions and non-null assertion                            */
/* ------------------------------------------------------------------ */

const input: unknown = "hello world";
const length = (input as string).length;

const maybeText: string | undefined = "definitely here";
const definiteText: string = maybeText!; // assert non-null (use carefully)

/* ------------------------------------------------------------------ */
/* 10. Index signatures and mapped-ish shapes                           */
/* ------------------------------------------------------------------ */

type Dictionary = { [key: string]: number };
const scores: Dictionary = { math: 95, science: 88 };

/* ------------------------------------------------------------------ */
/* 11. satisfies (TS 4.9+)                                              */
/* ------------------------------------------------------------------ */

const config = {
  host: "localhost",
  port: 3000,
} satisfies { host: string; port: number };

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

function main(): void {
  console.log("Variables:", { mutable, immutable, legacy, inferred });
  console.log("Primitives:", { name, age, active, big: big.toString(), sym: sym.toString() });
  console.log("Nullish:", { maybeNull, notSet });
  console.log("Special:", anything, safeUnknown);

  logMessage("void example");

  console.log("Arrays/Tuples:", nums, strs, tuple, readonlyArr);
  console.log("Union/Intersection:", id1, id2, person);
  console.log("Alias/Interface:", point, user);
  console.log("Enums:", Color[favoriteColor], favoriteColor, Direction.Up);
  console.log("Literal:", status, length, definiteText);
  console.log("Dictionary:", scores);
  console.log("Const assertion:", palette);
  console.log("Satisfies:", config);

  try {
    fail("intentional failure");
  } catch (err) {
    console.log("Never example caught:", (err as Error).message);
  }
}

main();
```

