console.log(parse("1.2.3-rc.1+build.5"));
// { major:1, minor:2, patch:3, prerelease:["rc","1"], build:["build","5"] }

console.log(compare("1.0.0-rc.1", "1.0.0"));   // -1
console.log(compare("2.0.0", "1.9.9"));          // 1
console.log(compare("1.0.0+build.1", "1.0.0+build.2")); // 0 (build ignored)

console.log(bump("1.2.3", "minor"));  // "1.3.0"
console.log(bump("1.2.3-rc.1", "patch")); // "1.2.4"

try { parse("not-a-version"); } catch (e) { console.error((e as Error).message); }
```

