  department: string;
  count: number;
  averageSalary: number;
}
```

### Step 4: Add validation helpers

Validation should fail with useful messages. We collect all row errors instead of stopping at the first one.

```ts
function parseBoolean(value: string): boolean {
  const normalized = value.trim().toLowerCase();

  if (["true", "1", "yes", "y"].includes(normalized)) return true;
  if (["false", "0", "no", "n"].includes(normalized)) return false;

  throw new Error(`Invalid boolean value: "${value}"`);
}

function validateEmployee(raw: EmployeeRaw, rowNumber: number): Employee {
  const id = Number(raw.id);
  if (!Number.isInteger(id) || id <= 0) {
    throw new Error(`Row ${rowNumber}: id must be a positive integer`);
  }

  const name = raw.name?.trim() ?? "";
  if (name.length === 0) {
    throw new Error(`Row ${rowNumber}: name must not be empty`);
  }

  const department = raw.department?.trim() ?? "";
  if (department.length === 0) {
    throw new Error(`Row ${rowNumber}: department must not be empty`);
  }

  const salary = Number(raw.salary);
  if (!Number.isFinite(salary) || salary < 0) {
    throw new Error(`Row ${rowNumber}: salary must be a finite non-negative number`);
  }

  const active = parseBoolean(raw.active ?? "");

  return { id, name, department, salary, active };
}
```

### Step 5: Read, parse, validate, filter, sort

The main workflow:

1. Read the file.
2. Parse with `columns: true`, so each row becomes an object.
3. Enable `bom: true` to remove a leading UTF-8 BOM if present.
4. Skip empty lines.
5. Validate each row.
6. Filter and sort.
7. Aggregate by department.

```ts
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { parse } from "csv-parse/sync";
import { stringify } from "csv-stringify/sync";
import path from "node:path";

const INPUT_FILE = path.resolve("data", "employees.csv");
const OUTPUT_DIR = path.resolve("data");
const MIN_SALARY = 50_000;

async function main(): Promise<void> {
  await mkdir(OUTPUT_DIR, { recursive: true });

  const csvText = await readFile(INPUT_FILE, "utf8");

  const rawRows = parse(csvText, {
    columns: true,
    skip_empty_lines: true,
    trim: true,
    bom: true,
  }) as EmployeeRaw[];

  const employees: Employee[] = [];
  const errors: string[] = [];

  rawRows.forEach((raw, index) => {
    try {
      employees.push(validateEmployee(raw, index + 2)); // +2 because header is row 1
    } catch (error) {
      errors.push(error instanceof Error ? error.message : String(error));
    }
  });

  if (errors.length > 0) {
    console.error("Validation errors:");
    errors.forEach((error) => console.error(`- ${error}`));
    process.exitCode = 1;
    return;
  }

  const filtered = employees
    .filter((employee) => employee.active && employee.salary >= MIN_SALARY)
    .sort((a, b) => {
      const departmentComparison = a.department.localeCompare(b.department);
      if (departmentComparison !== 0) return departmentComparison;
      return b.salary - a.salary;
    });

  const summaries = summarizeByDepartment(filtered);

  await writeOutputs(filtered, summaries);

  console.log(`Processed ${employees.length} employees.`);
  console.log(`Wrote ${filtered.length} high earners.`);
  console.log(`Wrote ${summaries.length} department summaries.`);
}

function summarizeByDepartment(employees: Employee[]): DepartmentSummary[] {
  const grouped = new Map<string, Employee[]>();

  for (const employee of employees) {
    const existing = grouped.get(employee.department);
    if (existing) {
      existing.push(employee);
    } else {
      grouped.set(employee.department, [employee]);
    }
  }

  return [...grouped.entries()]
    .map(([department, members]) => {
      const totalSalary = members.reduce((sum, employee) => sum + employee.salary, 0);
      return {
        department,
        count: members.length,
        averageSalary: Math.round((totalSalary / members.length) * 100) / 100,
      };
    })
    .sort((a, b) => a.department.localeCompare(b.department));
}

async function writeOutputs(
  employees: Employee[],
  summaries: DepartmentSummary[],
): Promise<void> {
  const csvOutput = stringify(
    employees.map((employee) => ({
      id: employee.id,
      name: employee.name,
      department: employee.department,
      salary: employee.salary,
      active: employee.active,
    })),
    {
      header: true,
      columns: ["id", "name", "department", "salary", "active"],
    },
  );

  await writeFile(path.resolve(OUTPUT_DIR, "high_earners.csv"), csvOutput, "utf8");
  await writeFile(
    path.resolve(OUTPUT_DIR, "department_summary.json"),
    `${JSON.stringify(summaries, null, 2)}\n`,
    "utf8",
  );
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
```

