## Minimal production-style client template

```go
package main

import (
    "bytes"
    "context"
    "errors"
    "fmt"
    "io"
    "net/http"
    "time"
)

func newClient() *http.Client {
    return &http.Client{
        Timeout: 20 * time.Second,
        Transport: &http.Transport{
            MaxIdleConns:        100,
            MaxIdleConnsPerHost: 10,
            IdleConnTimeout:     90 * time.Second,
            TLSHandshakeTimeout: 10 * time.Second,
        },
    }
}

func getJSON(ctx context.Context, client *http.Client, url string) ([]byte, error) {
    req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
    if err != nil {
        return nil, err
    }
    req.Header.Set("Accept", "application/json")

    resp, err := client.Do(req)
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()

    body, err := io.ReadAll(io.LimitReader(resp.Body, 10<<20))
    if err != nil {
        return nil, err
    }

    if resp.StatusCode < 200 || resp.StatusCode >= 300 {
        return nil, fmt.Errorf("status %d: %s", resp.StatusCode, bytes.TrimSpace(body))
    }
    return body, nil
}

func main() {
    client := newClient()
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    body, err := getJSON(ctx, client, "https://example.com/api")
    if err != nil {
        if errors.Is(err, context.DeadlineExceeded) {
            fmt.Println("request timed out")
            return
        }
        fmt.Println("error:", err)
        return
    }
    fmt.Println(string(body))
}
```

## Minimal production-style server template

```go
package main

import (
    "context"
    "errors"
    "io"
    "log"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"
)

func handler(w http.ResponseWriter, r *http.Request) {
    defer func() {
        if v := recover(); v != nil {
            log.Printf("panic: %v", v)
            http.Error(w, "internal server error", http.StatusInternalServerError)
        }
    }()

    r.Body = http.MaxBytesReader(w, r.Body, 1<<20)

    body, err := io.ReadAll(r.Body)
    if err != nil {
        http.Error(w, "bad request", http.StatusBadRequest)
        return
    }

    w.Header().Set("Content-Type", "text/plain; charset=utf-8")
    w.WriteHeader(http.StatusOK)
    w.Write(body)
}

func main() {
    mux := http.NewServeMux()
    mux.HandleFunc("/", handler)

    srv := &http.Server{
        Addr:              ":8080",
        Handler:           mux,
        ReadHeaderTimeout: 5 * time.Second,
        ReadTimeout:       10 * time.Second,
        WriteTimeout:      10 * time.Second,
        IdleTimeout:       120 * time.Second,
        MaxHeaderBytes:    1 << 20,
    }

    go func() {
        log.Println("listening on :8080")
        if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
            log.Fatal(err)
        }
    }()

    ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
    defer stop()
    <-ctx.Done()

    shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()
    if err := srv.Shutdown(shutdownCtx); err != nil {
        log.Printf("shutdown error: %v", err)
    }
}
```

---

### Summary checklist

Client:
- Set timeouts.
- Close bodies.
- Check status codes.
- Limit memory.
- Reuse client/transport.
- Handle redirects intentionally.
- Retry only idempotent operations.
- Respect context cancellation.
- Validate TLS and proxy behavior.

Server:
- Set all server timeouts.
- Limit body size.
- Recover panics.
- Handle client disconnects.
- Shut down gracefully.
- Validate paths, methods, content types.
- Avoid double `WriteHeader`.
- Flush carefully and hijack safely.

Below is a complete, runnable Go example using **GORM** (the most common Go ORM) with a pure-Go SQLite driver, so it does not require CGO.

### Project layout

```
orm-basics/
├── go.mod
└── main.go
```

### `go.mod`

```go
module orm-basics

go 1.22

require (
	github.com/glebarez/sqlite v1.11.0
	gorm.io/gorm v1.25.12
)
```

### `main.go`

```go
package main

import (
	"errors"
	"fmt"
	"time"

	"github.com/glebarez/sqlite"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// ---------- Models ----------

type User struct {
	ID        uint           `gorm:"primaryKey"`
	Name      string         `gorm:"size:100;not null"`
	Email     string         `gorm:"uniqueIndex;size:255"`
	Age       int
	CreatedAt time.Time
	UpdatedAt time.Time
	DeletedAt gorm.DeletedAt `gorm:"index"` // soft delete

	// Has One
	Profile Profile `gorm:"constraint:OnUpdate:CASCADE,OnDelete:CASCADE;"`

	// Has Many
	Posts []Post
}

type Profile struct {
	ID     uint `gorm:"primaryKey"`
	UserID uint `gorm:"uniqueIndex"` // foreign key to User
	Bio    string
}

type Post struct {
	ID        uint `gorm:"primaryKey"`
	UserID    uint // belongs to User
	Title     string
	Content   string
	CreatedAt time.Time
	UpdatedAt time.Time

	// Many to Many
	Tags []Tag `gorm:"many2many:post_tags;"`
}

type Tag struct {
	ID   uint `gorm:"primaryKey"`
	Name string `gorm:"uniqueIndex;size:50"`
}

// ---------- Hooks ----------

func (u *User) BeforeCreate(tx *gorm.DB) error {
	if u.Name == "" {
		return errors.New("user name is required")
	}
	return nil
}

// ---------- Main ----------

func main() {
	// Open an in-memory SQLite database.
	db, err := gorm.Open(sqlite.Open("file::memory:?cache=shared"), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Info),
	})
	if err != nil {
		panic(err)
	}

	// Auto-create / migrate tables.
	if err := db.AutoMigrate(&User{}, &Profile{}, &Post{}, &Tag{}); err != nil {
		panic(err)
	}

	// ---------- Create with nested associations ----------
	user := User{
		Name:  "Alice",
		Email: "alice@example.com",
		Age:   30,
		Profile: Profile{
			Bio: "Go developer and ORM enthusiast",
		},
		Posts: []Post{
			{
				Title:   "Hello ORM",
				Content: "GORM makes database work pleasant.",
				Tags: []Tag{
					{Name: "go"},
					{Name: "orm"},
				},
			},
			{
				Title:   "Transactions",
				Content: "Use db.Transaction for atomicity.",
				Tags: []Tag{
					{Name: "database"},
				},
			},
		},
	}

	if err := db.Create(&user).Error; err != nil {
		panic(err)
	}
	fmt.Printf("Created user ID=%d\n", user.ID)

	// ---------- Read: preload associations to avoid N+1 ----------
	var loaded User
	if err := db.
		Preload("Profile").
		Preload("Posts.Tags").
		First(&loaded, user.ID).Error; err != nil {
		panic(err)
	}

	fmt.Printf("User: %s (%s), age=%d\n", loaded.Name, loaded.Email, loaded.Age)
	fmt.Printf("Bio: %s\n", loaded.Profile.Bio)
	for _, p := range loaded.Posts {
		tagNames := make([]string, len(p.Tags))
		for i, t := range p.Tags {
			tagNames[i] = t.Name
		}
		fmt.Printf("  Post: %s tags=%v\n", p.Title, tagNames)
	}

	// ---------- Query building ----------
	var adults []User
	db.Where("age > ?", 18).
		Order("name ASC").
		Limit(10).
		Find(&adults)
	fmt.Printf("Adult users: %d\n", len(adults))

	// Count
	var count int64
	db.Model(&User{}).Count(&count)
	fmt.Printf("Total (non-deleted) users: %d\n", count)

	// ---------- Update ----------
	// Partial update
	if err := db.Model(&loaded).Update("Age", 31).Error; err != nil {
		panic(err)
	}
	// Multi-field update with struct (zero values are skipped unless using Select)
	db.Model(&loaded).Updates(map[string]any{
		"age":  32,
		"name": "Alice Cooper",
	})

	// ---------- Association management ----------
	// Append a new post to an existing user
	newPost := Post{Title: "New post", Content: "Added later"}
	if err := db.Model(&loaded).Association("Posts").Append(&newPost); err != nil {
		panic(err)
	}

	// ---------- Transaction ----------
	err = db.Transaction(func(tx *gorm.DB) error {
		// Create a tag inside a transaction
		tag := Tag{Name: "transactional"}
		if err := tx.Create(&tag).Error; err != nil {
			return err // rollback
		}
		// Link it to the first post
		if err := tx.Model(&loaded.Posts[0]).Association("Tags").Append(&tag); err != nil {
			return err
		}
		return nil // commit
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("Transaction committed")

	// ---------- Soft delete ----------
	if err := db.Delete(&loaded).Error; err != nil {
		panic(err)
	}
	fmt.Println("User soft-deleted")

	// Normal queries now exclude it.
	var found User
	err = db.First(&found, user.ID).Error
	fmt.Println("After soft delete, First() error:", err) // record not found

	// Include soft-deleted rows with Unscoped.
	var deleted User
	if err := db.Unscoped().First(&deleted, user.ID).Error; err != nil {
		panic(err)
	}
	fmt.Printf("Unscoped still finds user ID=%d (DeletedAt=%v)\n", deleted.ID, deleted.DeletedAt)

	// ---------- Hard delete ----------
	if err := db.Unscoped().Delete(&User{}, user.ID).Error; err != nil {
		panic(err)
	}
	fmt.Println("User hard-deleted")

	// ---------- Raw SQL (escape hatch) ----------
	type Result struct {
		Name  string
		Posts int64
	}
	var results []Result
	db.Raw(`
		SELECT u.name, COUNT(p.id) AS posts
		FROM users u
		LEFT JOIN posts p ON p.user_id = u.id
		GROUP BY u.id
	`).Scan(&results)
	fmt.Printf("Raw query rows: %d\n", len(results))
}
```

### How to run

```bash
cd orm-basics
go mod tidy
go run .
```

### Key ORM concepts shown

1. **Model definitions** – structs + `gorm` tags (`primaryKey`, `uniqueIndex`, `size`, `not null`).
2. **AutoMigrate** – schema creation/update without manual SQL.
3. **CRUD** – `Create`, `First`, `Find`, `Update`/`Updates`, `Delete`.
4. **Associations** – Has One (`Profile`), Has Many (`Posts`), Belongs To (implicit via `UserID`), Many-to-Many (`Tags` via join table).
5. **Preload** – eager loading to avoid N+1 queries.
6. **Query builder** – `Where`, `Order`, `Limit`, `Offset`, `Count`, `Model`.
7. **Transactions** – `db.Transaction(func(tx *gorm.DB) error { ... })` with automatic commit/rollback.
8. **Hooks** – `BeforeCreate` validation.
9. **Soft deletes** – `gorm.DeletedAt` + `Unscoped()`.
10. **Raw SQL escape hatch** – `db.Raw(...).Scan(...)`.
11. **Association management** – `Association("Posts").Append(...)`.

### Notes for production

- For real apps, prefer a persistent DB (Postgres/MySQL) and configure connection pooling (`sql.DB` via `db.DB()`).
- Keep domain models separate from DB models if your schema diverges from API shape.
- Use migrations (e.g. `golang-migrate`) instead of `AutoMigrate` in production.
- Add indexes/constraints explicitly via tags or migration files.
- Be careful with `Updates(struct{})`: zero values are ignored; use `map[string]any` or `Select` when you need to set zero values.

A very common ORM mistake in Go (especially with GORM) is the **N+1 query problem**: loading a list of records, then querying related records one by one in a loop.

### Mistaken version

```go
package main

import (
	"gorm.io/gorm"
)

type Post struct {
	ID     uint
	UserID uint
	Title  string
}

type User struct {
	ID    uint
	Name  string
	Posts []Post
}

func ListUsersWithPosts(db *gorm.DB) ([]User, error) {
	var users []User

	// 1 query for all users.
	if err := db.Find(&users).Error; err != nil {
		return nil, err
	}

	// Then 1 extra query per user: N+1 total.
	for i := range users {
		if err := db.Where("user_id = ?", users[i].ID).
			Find(&users[i].Posts).Error; err != nil {
			return nil, err
		}
	}

	return users, nil
}
```

### What is wrong

- `db.Find(&users)` loads users.
- The loop then runs a separate `SELECT` for each user's posts.
- For 100 users, this performs 101 database queries instead of 2.
- This causes poor performance, higher latency, and unnecessary database load.
- It also scales badly: the number of queries grows linearly with the number of users.

### Corrected version

```go
package main

import (
	"context"

	"gorm.io/gorm"
)

type Post struct {
	ID     uint
	UserID uint
	Title  string
}

type User struct {
	ID    uint
	Name  string
	Posts []Post
}

func ListUsersWithPosts(ctx context.Context, db *gorm.DB) ([]User, error) {
	var users []User

	// GORM preloads Posts in a small, fixed number of queries.
	err := db.WithContext(ctx).
		Preload("Posts").
		Find(&users).Error

	if err != nil {
		return nil, err
	}

	return users, err
}
```

### Why this is better

- `Preload("Posts")` tells GORM to load the related `Posts` efficiently, usually with one additional query such as:

  ```sql
  SELECT * FROM posts WHERE user_id IN (1, 2, 3, ...);
  ```

- Total queries become roughly **2**, regardless of how many users are returned.
- `WithContext(ctx)` propagates cancellation/timeouts, which is good practice in real services.
- Error handling remains explicit and idiomatic.

### Extra notes

- If you only need a subset of posts, preload with conditions:

  ```go
  db.Preload("Posts", "published = ?", true).Find(&users)
  ```

- For large datasets, consider pagination:

  ```go
  db.Preload("Posts").
      Limit(50).
      Offset(0).
      Find(&users)
  ```

- If the relation is huge, eager loading everything may still be expensive. In that case, fetch users and posts separately, or design the query specifically for the screen/API you are serving.

# ORM basics in Go (interview-style)

## 1. What an ORM does

An ORM maps between **Go structs** and **relational tables**:

| Go side | DB side |
|---|---|
| struct type | table |
| exported field | column |
| struct instance | row |
| field value | cell value |
| slice of structs | result set |

Core responsibilities:
1. **Metadata extraction** — reflect over a struct, read tags (`db:"col,pk"`), derive table/column names.
2. **SQL generation** — build `SELECT/INSERT/UPDATE/DELETE` from metadata + a small query DSL.
3. **Execution & scanning** — run SQL via `database/sql`, scan rows back into struct fields with type conversion.
4. **Lifecycle hooks** (optional) — `BeforeCreate`, transactions, migrations.

## 2. Go-specific considerations

- **Reflection is the engine.** `reflect` lets one generic implementation handle any struct, but it's slower than hand-written SQL; cache parsed metadata per type.
- **No implicit lazy loading.** Go has no proxies; relationships are either eager-loaded (joins) or fetched manually. Most Go ORMs (GORM, ent) lean on code generation or explicit preloading to stay fast.
- **Context everywhere.** `database/sql` is context-aware; pass `context.Context` through.
- **Errors are values.** Return `error`; don't panic. Watch for `sql.ErrNoRows`.
- **Transactions.** Use `*sql.Tx`; an ORM session should work against either `*sql.DB` or `*sql.Tx` (abstract with an interface).
- **Nullability.** Use `sql.NullString`/pointers or `*T` for nullable columns; plain value types get zero values.
- **Generics (1.18+)** can give type-safe `Find[T]`, but you still need reflection for column mapping.

## 3. Minimal ORM core (clean, commented)

```go
// Package miniorm is a tiny, educational ORM core.
// It demonstrates metadata parsing, query building, CRUD via reflection,
// transactions and a trivial migration helper.
package miniorm

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"reflect"
	"strings"
	"time"
)

// ---------- Errors ----------

var (
	ErrNotPointer   = errors.New("miniorm: expected pointer")
	ErrNotStruct    = errors.New("miniorm: expected struct")
	ErrNoPrimaryKey = errors.New("miniorm: model has no primary key")
)

// ---------- Model metadata ----------

// Tabler lets a model override its table name.
type Tabler interface {
	TableName() string
}

type FieldMeta struct {
	Name     string         // Go field name
	Column   string         // DB column name
	Type     reflect.Type
	Index    []int          // reflect path (for nested; unused here)
	IsPK     bool
	AutoIncr bool
	Nullable bool
}

type ModelMeta struct {
	Type      reflect.Type
	TableName string
	Fields    []FieldMeta
	PK        *FieldMeta
}

// modelCache avoids re-parsing the same type.
var modelCache = make(map[reflect.Type]*ModelMeta)

// ParseModel extracts metadata from a struct (or pointer to struct).
func ParseModel(v interface{}) (*ModelMeta, error) {
	t := reflect.TypeOf(v)
	if t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	if t.Kind() != reflect.Struct {
		return nil, ErrNotStruct
	}
	if m, ok := modelCache[t]; ok {
		return m, nil
	}

	m := &ModelMeta{Type: t}
	m.TableName = toSnake(t.Name()) + "s" // naive plural default

	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		tag := f.Tag.Get("db")
		if tag == "-" {
			continue
		}
		fm := FieldMeta{
			Name:  f.Name,
			Type:  f.Type,
			Index: f.Index,
		}
		parts := strings.Split(tag, ",")
		if parts[0] != "" {
			fm.Column = strings.TrimSpace(parts[0])
		} else {
			fm.Column = toSnake(f.Name)
		}
		for _, p := range parts[1:] {
			switch strings.TrimSpace(p) {
			case "pk":
				fm.IsPK = true
			case "autoincr", "auto_increment":
				fm.AutoIncr = true
				fm.IsPK = true
			case "nullable":
				fm.Nullable = true
			}
		}
		m.Fields = append(m.Fields, fm)
		if fm.IsPK && m.PK == nil {
			pk := fm
			m.PK = &pk
		}
	}

	// Allow table-name override via TableName() method.
	if tn, ok := reflect.New(t).Interface().(Tabler); ok {
		m.TableName = tn.TableName()
	}
	modelCache[t] = m
	return m, nil
}

// ---------- SQL helpers ----------

type executor interface {
	ExecContext(context.Context, string, ...interface{}) (sql.Result, error)
	QueryContext(context.Context, string, ...interface{}) (*sql.Rows, error)
	QueryRowContext(context.Context, string, ...interface{}) *sql.Row
}

// DB wraps *sql.DB.
type DB struct {
	sql *sql.DB
}

func New(db *sql.DB) *DB { return &DB{sql: db} }

func (db *DB) Begin(ctx context.Context) (*Tx, error) {
	tx, err := db.sql.BeginTx(ctx, nil)
	if err != nil {
		return nil, err
	}
	return &Tx{tx: tx, db: db}, nil
}

// Tx wraps *sql.Tx so sessions can run inside a transaction.
type Tx struct {
	tx *sql.Tx
	db *DB
}

func (tx *Tx) Commit() error   { return tx.tx.Commit() }
func (tx *Tx) Rollback() error { return tx.tx.Rollback() }

// ---------- Session / query builder ----------

type Session struct {
	exec         executor
	meta         *ModelMeta
	whereClauses []string
	whereArgs    []interface{}
	orderBy      string
	limit        int
	offset       int
	selectedCols []string
}

func (db *DB) Model(v interface{}) *Session {
	s := &Session{exec: db.sql}
	if v != nil {
		if m, err := ParseModel(v); err == nil {
			s.meta = m
		}
	}
	return s
}

func (tx *Tx) Model(v interface{}) *Session {
	s := &Session{exec: tx.tx}
	if v != nil {
		if m, err := ParseModel(v); err == nil {
			s.meta = m
		}
	}
	return s
}

// Convenience pass-throughs on DB.
func (db *DB) Create(ctx context.Context, v interface{}) error {
	return db.Model(v).Create(ctx, v)
}
func (db *DB) Update(ctx context.Context, v interface{}) error {
	return db.Model(v).Update(ctx, v)
}
func (db *DB) Delete(ctx context.Context, v interface{}) error {
	return db.Model(v).Delete(ctx, v)
}

// Chainable query methods.
func (s *Session) Where(cond string, args ...interface{}) *Session {
	s.whereClauses = append(s.whereClauses, cond)
	s.whereArgs = append(s.whereArgs, args...)
	return s
}
func (s *Session) OrderBy(expr string) *Session { s.orderBy = expr; return s }
func (s *Session) Limit(n int) *Session         { s.limit = n; return s }
func (s *Session) Offset(n int) *Session        { s.offset = n; return s }
func (s *Session) Select(cols ...string) *Session {
	s.selectedCols = cols
	return s
}

// First is a convenience for single-row fetch.
func (s *Session) First(ctx context.Context, dest interface{}) error {
	s.limit = 1
	return s.Find(ctx, dest)
}

// Find executes SELECT. dest may be *T or *[]T.
func (s *Session) Find(ctx context.Context, dest interface{}) error {
	dv := reflect.ValueOf(dest)
	if dv.Kind() != reflect.Ptr {
		return ErrNotPointer
	}
	dv = dv.Elem()

	single := false
	var elemType reflect.Type
	switch dv.Kind() {
	case reflect.Slice:
		elemType = dv.Type().Elem()
	case reflect.Struct:
		single = true
		elemType = dv.Type()
	default:
		return errors.New("miniorm: dest must be *struct or *[]struct")
	}

	if s.meta == nil {
		m, err := ParseModel(reflect.New(elemType).Interface())
		if err != nil {
			return err
		}
		s.meta = m
	}
	meta := s.meta

	cols := s.selectedCols
	if len(cols) == 0 {
		for _, f := range meta.Fields {
			cols = append(cols, f.Column)
		}
	}
	q := "SELECT " + strings.Join(cols, ", ") + " FROM " + meta.TableName
	if len(s.whereClauses) > 0 {
		q += " WHERE " + strings.Join(s.whereClauses, " AND ")
	}
	if s.orderBy != "" {
		q += " ORDER BY " + s.orderBy
	}
	if single && s.limit == 0 {
		s.limit = 1
	}
	if s.limit > 0 {
		q += fmt.Sprintf(" LIMIT %d", s.limit)
	}
	if s.offset > 0 {
		q += fmt.Sprintf(" OFFSET %d", s.offset)
	}

	rows, err := s.exec.QueryContext(ctx, q, s.whereArgs...)
	if err != nil {
		return err
	}
	defer rows.Close()

	colNames, err := rows.Columns()
	if err != nil {
		return err
	}

	if single {
		if !rows.Next() {
			return sql.ErrNoRows
		}
		return scanRow(rows, colNames, meta, dv)
	}

	for rows.Next() {
		v := reflect.New(elemType).Elem()
		if err := scanRow(rows, colNames, meta, v); err != nil {
			return err
		}
		dv.Set(reflect.Append(dv, v))
	}
	return rows.Err()
}

// scanRow scans one DB row into dest struct value.
func scanRow(rows *sql.Rows, colNames []string, meta *ModelMeta, dest reflect.Value) error {
	colToField := make(map[string]*FieldMeta, len(meta.Fields))
	for i := range meta.Fields {
		fm := &meta.Fields[i]
		colToField[fm.Column] = fm
	}

	// Scan into intermediate *interface{} slots first, then convert.
	raw := make([]interface{}, len(colNames))
	for i := range raw {
		var v interface{}
		raw[i] = &v
	}
	if err := rows.Scan(raw...); err != nil {
		return err
	}

	for i, c := range colNames {
		fm, ok := colToField[c]
		if !ok {
			continue // unknown column; ignore
		}
		scanned := reflect.ValueOf(raw[i]).Elem().Interface()
		field := dest.FieldByName(fm.Name)
		if !field.CanSet() {
			continue
		}
		if err := setField(field, scanned); err != nil {
			return fmt.Errorf("column %s: %w", c, err)
		}
	}
	return nil
}

// setField assigns a scanned value to a struct field with conversion.
func setField(field reflect.Value, val interface{}) error {
	if val == nil {
		field.Set(reflect.Zero(field.Type()))
		return nil
	}
	v := reflect.ValueOf(val)
	if v.Type().AssignableTo(field.Type()) {
		field.Set(v)
		return nil
	}
	if v.Type().ConvertibleTo(field.Type()) {
		field.Set(v.Convert(field.Type()))
		return nil
	}
	return fmt.Errorf("cannot convert %v to %v", v.Type(), field.Type())
}

// Create inserts a new row. Auto-increment PK is written back.
func (s *Session) Create(ctx context.Context, v interface{}) error {
	val := reflect.ValueOf(v)
	if val.Kind() != reflect.Ptr {
		return ErrNotPointer
	}
	val = val.Elem()
	meta, err := ParseModel(v)
	if err != nil {
		return err
	}
	s.meta = meta

	var cols, ph []string
	var args []interface{}
	for _, f := range meta.Fields {
		if f.AutoIncr {
			continue // DB generates this
		}
		field := val.FieldByName(f.Name)
		cols = append(cols, f.Column)
		ph = append(ph, "?")
		args = append(args, field.Interface())
	}
	q := fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s)",
		meta.TableName,
		strings.Join(cols, ", "),
		strings.Join(ph, ", "),
	)
	res, err := s.exec.ExecContext(ctx, q, args...)
	if err != nil {
		return err
	}
	if meta.PK != nil && meta.PK.AutoIncr {
		if id, err := res.LastInsertId(); err == nil {
			pkField := val.FieldByName(meta.PK.Name)
			if pkField.CanSet() && pkField.Kind() == reflect.Int64 {
				pkField.SetInt(id)
			} else if pkField.CanSet() {
				// best-effort for other int kinds
				pkField.SetInt(id)
			}
		}
	}
	return nil
}

// Update updates all non-PK columns by primary key.
func (s *Session) Update(ctx context.Context, v interface{}) error {
	val := reflect.ValueOf(v)
	if val.Kind() != reflect.Ptr {
		return ErrNotPointer
	}
	val = val.Elem()
	meta, err := ParseModel(v)
	if err != nil {
		return err
	}
	if meta.PK == nil {
		return ErrNoPrimaryKey
	}
	s.meta = meta

	pkField := val.FieldByName(meta.PK.Name)
	var sets []string
	var args []interface{}
	for _, f := range meta.Fields {
		if f.IsPK {
			continue
		}
		field := val.FieldByName(f.Name)
		sets = append(sets, f.Column+" = ?")
		args = append(args, field.Interface())
	}
	args = append(args, pkField.Interface())

	q := fmt.Sprintf("UPDATE %s SET %s WHERE %s = ?",
		meta.TableName,
		strings.Join(sets, ", "),
		meta.PK.Column,
	)
	_, err = s.exec.ExecContext(ctx, q, args...)
	return err
}

// Delete removes a row by primary key.
func (s *Session) Delete(ctx context.Context, v interface{}) error {
	val := reflect.ValueOf(v)
	if val.Kind() != reflect.Ptr {
		return ErrNotPointer
	}
	val = val.Elem()
	meta, err := ParseModel(v)
	if err != nil {
		return err
	}
	if meta.PK == nil {
		return ErrNoPrimaryKey
	}
	s.meta = meta

	pkField := val.FieldByName(meta.PK.Name)
	q := fmt.Sprintf("DELETE FROM %s WHERE %s = ?", meta.TableName, meta.PK.Column)
	_, err = s.exec.ExecContext(ctx, q, pkField.Interface())
	return err
}

// Count returns number of rows matching the session filters.
func (s *Session) Count(ctx context.Context) (int64, error) {
	if s.meta == nil {
		return 0, errors.New("miniorm: model required for Count")
	}
	q := "SELECT COUNT(*) FROM " + s.meta.TableName
	if len(s.whereClauses) > 0 {
		q += " WHERE " + strings.Join(s.whereClauses, " AND ")
	}
	var n int64
	err := s.exec.QueryRowContext(ctx, q, s.whereArgs...).Scan(&n)
	return n, err
}

// ---------- AutoMigrate (trivial) ----------

func (db *DB) AutoMigrate(ctx context.Context, models ...interface{}) error {
	for _, m := range models {
		meta, err := ParseModel(m)
		if err != nil {
			return err
		}
		var cols []string
		for _, f := range meta.Fields {
			def := f.Column + " " + goTypeToSQL(f.Type)
			if f.IsPK {
				def += " PRIMARY KEY"
				if f.AutoIncr {
					def += " AUTOINCREMENT"
				}
			} else if !f.Nullable {
				def += " NOT NULL"
			}
			cols = append(cols, def)
		}
		q := fmt.Sprintf("CREATE TABLE IF NOT EXISTS %s (\n  %s\n)",
			meta.TableName, strings.Join(cols, ",\n  "))
		if _, err := db.sql.ExecContext(ctx, q); err != nil {
			return err
		}
	}
	return nil
}

// ---------- helpers ----------

func toSnake(s string) string {
	var b strings.Builder
	for i, r := range s {
		if i > 0 && r >= 'A' && r <= 'Z' {
			b.WriteByte('_')
		}
		b.WriteRune(r)
	}
	return strings.ToLower(b.String())
}

func goTypeToSQL(t reflect.Type) string {
	switch t.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return "INTEGER"
	case reflect.Float32, reflect.Float64:
		return "REAL"
	case reflect.Bool:
		return "INTEGER"
	case reflect.String:
		return "TEXT"
	case reflect.Struct:
		if t == reflect.TypeOf(time.Time{}) {
			return "DATETIME"
		}
	case reflect.Slice, reflect.Array, reflect.Map:
		return "BLOB"
	}
	return "TEXT"
}
```

## 4. Usage example

```go
package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"

	_ "github.com/mattn/go-sqlite3" // or modernc.org/sqlite
	"example.com/miniorm"
)

type User struct {
	ID        int64  `db:"id,pk,autoincr"`
	Name      string `db:"name"`
	Email     string `db:"email"`
	Age       int    `db:"age"`
	CreatedAt string `db:"created_at,nullable"`
}

func (User) TableName() string { return "users" }

func main() {
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	orm := miniorm.New(db)
	ctx := context.Background()

	if err := orm.AutoMigrate(ctx, &User{}); err != nil {
		log.Fatal(err)
	}

	// Create
	u := &User{Name: "Ada", Email: "ada@example.com", Age: 36}
	if err := orm.Create(ctx, u); err != nil {
		log.Fatal(err)
	}
	fmt.Println("created id:", u.ID)

	// Query
	var users []User
	if err := orm.Model(&User{}).Where("age >= ?", 18).OrderBy("name").Find(ctx, &users); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%+v\n", users)

	// First
	var one User
	if err := orm.Model(&User{}).Where("email = ?", "ada@example.com").First(ctx, &one); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%+v\n", one)

	// Update
	one.Age = 37
	if err := orm.Update(ctx, &one); err != nil {
		log.Fatal(err)
	}

	// Transaction
	tx, _ := orm.Begin(ctx)
	if err := tx.Create(ctx, &User{Name: "Bob", Email: "bob@example.com", Age: 20}); err != nil {
		tx.Rollback()
		log.Fatal(err)
	}
	tx.Commit()

	// Delete
	if err := orm.Delete(ctx, &one); err != nil {
		log.Fatal(err)
	}

	// Count
	n, _ := orm.Model(&User{}).Count(ctx)
	fmt.Println("remaining:", n)
}
```

## 5. What a production ORM adds (and trade-offs)

- **Dialects / placeholders** — Postgres uses `$1`; MySQL uses `?`; SQLite supports both. Abstract with a dialect.
- **Relationships** — `has-one/has-many/many-to-many` with eager loading (`Preload`) to avoid N+1.
- **Migrations** — versioned schema changes, not just `CREATE TABLE IF NOT EXISTS`.
- **Hooks** — `BeforeCreate/AfterUpdate` for auditing, soft deletes.
- **Caching & prepared statements** — reuse parsed SQL; `*sql.Stmt`.
- **Type safety** — codegen (ent, sqlc) or generics (`Find[T]`) instead of `interface{}`.
- **Performance** — prefer generated code or hand-written SQL for hot paths; reflection-based ORMs are fine for CRUD/admin.

### Interview talking points

- **When NOT to use an ORM:** complex reporting queries, bulk inserts, performance-critical paths — use `sqlc` or raw SQL.
- **N+1 problem:** fetching a list then querying per item; fix with joins/preload.
- **sql.ErrNoRows handling:** `First` should map to a sentinel like `ErrRecordNotFound`.
- **Context cancellation:** always pass ctx to `QueryContext`/`ExecContext`.
- **Connection pooling:** `*sql.DB` is a pool; don't open per request.
- **Reflection cost:** cache metadata; consider code generation for large schemas.

If you'd like, I can extend this with **generics-based type-safe queries** (`Find[T]`), **soft deletes**, or **a relationship/preload implementation**.

Below is a complete, self-contained Go program that implements both a REST API server and a typed client. It uses only the standard library, modern `http.ServeMux` routing (Go 1.22+), JSON encoding/decoding, context propagation, and graceful shutdown.

Save as `main.go` and run with `go run main.go`.

```go
// main.go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"sync"
	"syscall"
	"time"
)

// ---------- Domain model ----------

type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// ---------- Server ----------

type userStore struct {
	mu     sync.RWMutex
	users  map[int]User
	nextID int
}

func newUserStore() *userStore {
	s := &userStore{users: make(map[int]User), nextID: 1}
	// seed data
	s.users[1] = User{ID: 1, Name: "Alice", Email: "alice@example.com"}
	s.users[2] = User{ID: 2, Name: "Bob", Email: "bob@example.com"}
	s.nextID = 3
	return s
}

type server struct {
	store *userStore
}

func newServer(store *userStore) *server {
	return &server{store: store}
}

func (s *server) routes() http.Handler {
	mux := http.NewServeMux()

	// Health check
	mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	// Users collection
	mux.HandleFunc("GET /users", s.listUsers)
	mux.HandleFunc("POST /users", s.createUser)

	// Single user
	mux.HandleFunc("GET /users/{id}", s.getUser)
	mux.HandleFunc("PUT /users/{id}", s.updateUser)
	mux.HandleFunc("DELETE /users/{id}", s.deleteUser)

	// Middleware chain: logging -> recovery -> mux
	return loggingMiddleware(recoveryMiddleware(mux))
}

// ---------- Handlers ----------

func (s *server) listUsers(w http.ResponseWriter, r *http.Request) {
	s.store.mu.RLock()
	defer s.store.mu.RUnlock()

	users := make([]User, 0, len(s.store.users))
	for _, u := range s.store.users {
		users = append(users, u)
	}
	writeJSON(w, http.StatusOK, users)
}

func (s *server) getUser(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	s.store.mu.RLock()
	defer s.store.mu.RUnlock()

	u, ok := s.store.users[id]
	if !ok {
		writeError(w, http.StatusNotFound, "user not found")
		return
	}
	writeJSON(w, http.StatusOK, u)
}

func (s *server) createUser(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Name  string `json:"name"`
		Email string `json:"email"`
	}
	if err := readJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	if input.Name == "" || input.Email == "" {
		writeError(w, http.StatusBadRequest, "name and email are required")
		return
	}

	s.store.mu.Lock()
	defer s.store.mu.Unlock()

	u := User{ID: s.store.nextID, Name: input.Name, Email: input.Email}
	s.store.users[u.ID] = u
	s.store.nextID++

	w.Header().Set("Location", fmt.Sprintf("/users/%d", u.ID))
	writeJSON(w, http.StatusCreated, u)
}

func (s *server) updateUser(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	var input struct {
		Name  string `json:"name"`
		Email string `json:"email"`
	}
	if err := readJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	s.store.mu.Lock()
	defer s.store.mu.Unlock()

	u, ok := s.store.users[id]
	if !ok {
		writeError(w, http.StatusNotFound, "user not found")
		return
	}
	if input.Name != "" {
		u.Name = input.Name
	}
	if input.Email != "" {
		u.Email = input.Email
	}
	s.store.users[id] = u
	writeJSON(w, http.StatusOK, u)
}

func (s *server) deleteUser(w http.ResponseWriter, r *http.Request) {
	id, err := parseID(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	s.store.mu.Lock()
	defer s.store.mu.Unlock()

	if _, ok := s.store.users[id]; !ok {
		writeError(w, http.StatusNotFound, "user not found")
		return
	}
	delete(s.store.users, id)
	w.WriteHeader(http.StatusNoContent)
}

// ---------- HTTP helpers ----------

func parseID(s string) (int, error) {
	id, err := strconv.Atoi(s)
	if err != nil || id <= 0 {
		return 0, errors.New("invalid id")
