```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

// Use a configured client instead of http.DefaultClient.
var apiClient = &http.Client{
	Timeout: 10 * time.Second,
}

func fetchUser(ctx context.Context, baseURL string, id int) (User, error) {
	endpoint, err := url.JoinPath(baseURL, "users", strconv.Itoa(id))
	if err != nil {
		return User{}, fmt.Errorf("build URL: %w", err)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return User{}, fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Accept", "application/json")

	resp, err := apiClient.Do(req)
	if err != nil {
		return User{}, fmt.Errorf("do request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		// Drain the body so the underlying connection can be reused.
		_, _ = io.Copy(io.Discard, resp.Body)
		return User{}, fmt.Errorf("unexpected status: %s", resp.Status)
	}

	var u User
	if err := json.NewDecoder(resp.Body).Decode(&u); err != nil {
		return User{}, fmt.Errorf("decode response: %w", err)
	}
	return u, nil
}

func handleGetUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	idStr := strings.TrimPrefix(r.URL.Path, "/users/")
	id, err := strconv.Atoi(idStr)
	if err != nil || id <= 0 {
		http.Error(w, "invalid user id", http.StatusBadRequest)
		return
	}

	u := User{ID: id, Name: "Alice"}

	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)

	if err := json.NewEncoder(w).Encode(u); err != nil {
		// The client may have disconnected; log rather than ignore.
		log.Printf("encode response for user %d: %v", id, err)
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/users/", handleGetUser)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("server failed: %v", err)
		}
	}()

	// Give the server a moment to start.
	time.Sleep(100 * time.Millisecond)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	u, err := fetchUser(ctx, "http://localhost:8080", 42)
	if err != nil {
		log.Fatalf("fetch user: %v", err)
	}
	log.Printf("got user: %+v", u)

	shutdownCtx, cancelShutdown := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancelShutdown()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}
```

## What was wrong and why

### Client side

1. **No response body cleanup**  
   `resp.Body` must be closed. Otherwise file descriptors and connections leak, especially under load. `defer resp.Body.Close()` is the idiomatic fix.

2. **No status-code handling**  
   A REST API may return `404`, `400`, `500`, etc. with a body that is not the expected JSON shape. Decoding blindly can produce misleading zero values or partial data. Check `resp.StatusCode` before decoding.

3. **Ignored decode errors**  
   `json.Decoder.Decode` can fail due to malformed JSON, unexpected types, or truncated responses. Ignoring it hides real failures.

4. **No timeout or cancellation**  
   `http.DefaultClient` has no timeout. A slow or stalled server can hang the client forever. Use a configured `http.Client` and `http.NewRequestWithContext`.

5. **Unsafe URL construction**  
   `fmt.Sprintf` does not escape path segments. `url.JoinPath` and `strconv.Itoa` make URL construction safer and clearer.

6. **Connection reuse**  
   On non-200 responses, draining the body with `io.Copy(io.Discard, resp.Body)` before close helps keep-alive connections remain reusable.

### Server side

1. **Missing `Content-Type`**  
   Clients need to know the response format. Set `Content-Type: application/json; charset=utf-8` before writing the body.

2. **No method/path validation**  
   A REST handler should reject unsupported methods and invalid identifiers with appropriate status codes such as `405` and `400`.

3. **Ignored write/encode errors**  
   If the client disconnects, `json.Encoder.Encode` returns an error. Logging it helps distinguish client disconnects from server bugs.

4. **No server timeouts**  
   `http.ListenAndServe` with default settings is vulnerable to slow clients. Use `http.Server` with `ReadHeaderTimeout`, `WriteTimeout`, and `IdleTimeout`.

5. **Ignored startup error**  
   `http.ListenAndServe` returns an error, for example when the port is already in use. Ignoring it makes failures invisible. Use `log.Fatal` or explicit error handling.

6. **Graceful shutdown**  
   Calling `srv.Shutdown` lets in-flight requests finish instead of abruptly terminating connections.

The corrected version is still small, but it follows the usual Go HTTP client/server contract: explicit errors, bounded time, resource cleanup, and clear HTTP semantics.

## Exercise

Build a small **Task Tracker REST API** in Go:

- Server stores tasks in memory (thread-safe).
- Endpoints:
  - `GET /tasks` – list all tasks
  - `GET /tasks/{id}` – get one task
  - `POST /tasks` – create a task (`{"title":"..."}`)
  - `PUT /tasks/{id}` – replace a task (`{"title":"...","done":true}`)
  - `DELETE /tasks/{id}` – delete a task
- Client is a CLI that calls these endpoints.

We’ll implement it in three parts: shared model/store, HTTP server, and HTTP client.

---

## Step 1: Module and shared model

Create a module:

```bash
mkdir taskapi && cd taskapi
go mod init example.com/taskapi
```

Create `store.go` (package `taskapi`). This holds the data model and an in-memory store.

```go
// store.go
package taskapi

import (
	"sort"
	"sync"
)

type Task struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type Store struct {
	mu     sync.RWMutex
	tasks  map[int]Task
	nextID int
}

func NewStore() *Store {
	return &Store{
		tasks:  make(map[int]Task),
		nextID: 1,
	}
}

func (s *Store) List() []Task {
	s.mu.RLock()
	defer s.mu.RUnlock()

	out := make([]Task, 0, len(s.tasks))
	for _, t := range s.tasks {
		out = append(out, t)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func (s *Store) Get(id int) (Task, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	t, ok := s.tasks[id]
	return t, ok
}

func (s *Store) Create(title string) Task {
	s.mu.Lock()
	defer s.mu.Unlock()

	t := Task{ID: s.nextID, Title: title}
	s.tasks[t.ID] = t
	s.nextID++
	return t
}

func (s *Store) Update(id int, title string, done bool) (Task, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	t, ok := s.tasks[id]
	if !ok {
		return Task{}, false
	}
	t.Title = title
	t.Done = done
	s.tasks[id] = t
	return t, true
}

func (s *Store) Delete(id int) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.tasks[id]; !ok {
		return false
	}
	delete(s.tasks, id)
	return true
}
```

**Why:** `sync.RWMutex` protects the map from concurrent access. The store is small and simple; for production you’d swap this for a database.

