## Step 3: HTTP client CLI

Create `client/main.go`. It reads subcommands and calls the API.

```go
// client/main.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"

	"example.com/taskapi"
)

const defaultBase = "http://localhost:8080"

func usage() {
	fmt.Println(`usage:
  client list
  client get <id>
  client create <title>
  client update <id> <title> [done:true|false]
  client delete <id>

env: API_URL (default http://localhost:8080)`)
}

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}

	base := os.Getenv("API_URL")
	if base == "" {
		base = defaultBase
	}
	base = strings.TrimRight(base, "/")

	var err error
	switch os.Args[1] {
	case "list":
		err = cmdList(base)
	case "get":
		err = cmdGet(base, os.Args[2:])
	case "create":
		err = cmdCreate(base, os.Args[2:])
	case "update":
		err = cmdUpdate(base, os.Args[2:])
	case "delete":
		err = cmdDelete(base, os.Args[2:])
	default:
		usage()
		os.Exit(2)
	}

	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

func request(method, url string, body any) (*http.Response, error) {
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			return nil, err
		}
	}
	req, err := http.NewRequest(method, url, &buf)
	if err != nil {
		return nil, err
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return http.DefaultClient.Do(req)
}

func readError(resp *http.Response) error {
	b, _ := io.ReadAll(resp.Body)
	msg := strings.TrimSpace(string(b))
	if msg == "" {
		msg = resp.Status
	}
	return fmt.Errorf("HTTP %d: %s", resp.StatusCode, msg)
}

func cmdList(base string) error {
	resp, err := request("GET", base+"/tasks", nil)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return readError(resp)
	}
	var tasks []taskapi.Task
	if err := json.NewDecoder(resp.Body).Decode(&tasks); err != nil {
		return err
	}
	if len(tasks) == 0 {
		fmt.Println("no tasks")
		return nil
	}
	for _, t := range tasks {
		fmt.Printf("%d: %s (done=%v)\n", t.ID, t.Title, t.Done)
	}
	return nil
}

func cmdGet(base string, args []string) error {
	if len(args) != 1 {
		return fmt.Errorf("usage: get <id>")
	}
	resp, err := request("GET", base+"/tasks/"+args[0], nil)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return readError(resp)
	}
	var t taskapi.Task
	if err := json.NewDecoder(resp.Body).Decode(&t); err != nil {
		return err
	}
	fmt.Printf("%d: %s (done=%v)\n", t.ID, t.Title, t.Done)
	return nil
}

func cmdCreate(base string, args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("usage: create <title>")
	}
	title := strings.Join(args, " ")
	resp, err := request("POST", base+"/tasks", map[string]string{"title": title})
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusCreated {
		return readError(resp)
	}
	var t taskapi.Task
	if err := json.NewDecoder(resp.Body).Decode(&t); err != nil {
		return err
	}
	fmt.Printf("created %d: %s\n", t.ID, t.Title)
	return nil
}

func cmdUpdate(base string, args []string) error {
	if len(args) < 2 {
		return fmt.Errorf("usage: update <id> <title> [done:true|false]")
	}
	id, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("invalid id")
	}
	_ = id

	body := map[string]any{
		"title": args[1],
		"done":  false,
	}
	if len(args) >= 3 {
		v, err := strconv.ParseBool(args[2])
		if err != nil {
			return fmt.Errorf("done must be true or false")
		}
		body["done"] = v
		// allow multi-word titles when quoted by shell; args[1] already one token
	}

	resp, err := request("PUT", base+"/tasks/"+args[0], body)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return readError(resp)
	}
	var t taskapi.Task
	if err := json.NewDecoder(resp.Body).Decode(&t); err != nil {
		return err
	}
	fmt.Printf("updated %d: %s (done=%v)\n", t.ID, t.Title, t.Done)
	return nil
}

func cmdDelete(base string, args []string) error {
	if len(args) != 1 {
		return fmt.Errorf("usage: delete <id>")
	}
	resp, err := request("DELETE", base+"/tasks/"+args[0], nil)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		return readError(resp)
	}
	fmt.Println("deleted")
	return nil
}
```

