## Complete, runnable example

```go
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"sync"
	"time"
)

// ---------- Domain model ----------

// Item is the JSON representation of a resource.
type Item struct {
	ID    string  `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
}

// ---------- Storage layer ----------

var ErrNotFound = errors.New("not found")

// ItemStore abstracts persistence so handlers do not depend on a concrete DB.
type ItemStore interface {
	List() []Item
	Get(id string) (Item, bool)
	Create(item Item) (Item, error)
	Update(id string, item Item) (Item, error)
	Delete(id string) error
}

// MemoryStore is a thread-safe in-memory implementation.
type MemoryStore struct {
	mu    sync.RWMutex
	items map[string]Item
	next  int
}

func NewMemoryStore() *MemoryStore {
	return &MemoryStore{items: make(map[string]Item)}
}

func (s *MemoryStore) List() []Item {
	s.mu.RLock()
	defer s.mu.RUnlock()

	ids := make([]string, 0, len(s.items))
	for id := range s.items {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	out := make([]Item, 0, len(ids))
	for _, id := range ids {
		out = append(out, s.items[id])
	}
	return out
}

func (s *MemoryStore) Get(id string) (Item, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	item, ok := s.items[id]
	return item, ok
}

func (s *MemoryStore) Create(item Item) (Item, error) {
	if strings.TrimSpace(item.Name) == "" {
		return Item{}, errors.New("name is required")
	}
	if item.Price < 0 {
		return Item{}, errors.New("price must be non-negative")
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	s.next++
	item.ID = fmt.Sprintf("item-%d", s.next)
	s.items[item.ID] = item
	return item, nil
}

func (s *MemoryStore) Update(id string, item Item) (Item, error) {
	if strings.TrimSpace(item.Name) == "" {
		return Item{}, errors.New("name is required")
	}
	if item.Price < 0 {
		return Item{}, errors.New("price must be non-negative")
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.items[id]; !ok {
		return Item{}, ErrNotFound
	}

	item.ID = id
	s.items[id] = item
	return item, nil
}

func (s *MemoryStore) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.items[id]; !ok {
		return ErrNotFound
	}
	delete(s.items, id)
	return nil
}

// ---------- HTTP API ----------

type API struct {
	store ItemStore
}

func NewAPI(store ItemStore) *API {
	return &API{store: store}
}

// Routes returns an http.Handler with all endpoints and middleware.
func (a *API) Routes() http.Handler {
	mux := http.NewServeMux()

	// Go 1.22+ method-aware routing.
	mux.HandleFunc("GET /items", a.listItems)
	mux.HandleFunc("POST /items", a.createItem)
	mux.HandleFunc("GET /items/{id}", a.getItem)
	mux.HandleFunc("PUT /items/{id}", a.updateItem)
	mux.HandleFunc("DELETE /items/{id}", a.deleteItem)

	return withMiddleware(mux)
}

func withMiddleware(next http.Handler) http.Handler {
	return recovery(logging(next))
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

func recovery(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				log.Printf("panic recovered: %v", v)
				writeError(w, http.StatusInternalServerError, "internal server error")
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func (a *API) listItems(w http.ResponseWriter, r *http.Request) {
	items := a.store.List()
	writeJSON(w, http.StatusOK, items)
}

func (a *API) createItem(w http.ResponseWriter, r *http.Request) {
	var item Item
	if err := readJSON(r, &item); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	created, err := a.store.Create(item)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	writeJSON(w, http.StatusCreated, created)
}

func (a *API) getItem(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")

	item, ok := a.store.Get(id)
	if !ok {
		writeError(w, http.StatusNotFound, "item not found")
		return
	}

	writeJSON(w, http.StatusOK, item)
}

func (a *API) updateItem(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")

	var item Item
	if err := readJSON(r, &item); err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	updated, err := a.store.Update(id, item)
	if errors.Is(err, ErrNotFound) {
		writeError(w, http.StatusNotFound, "item not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	writeJSON(w, http.StatusOK, updated)
}

func (a *API) deleteItem(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")

	if err := a.store.Delete(id); err != nil {
		if errors.Is(err, ErrNotFound) {
			writeError(w, http.StatusNotFound, "item not found")
			return
		}
		writeError(w, http.StatusBadRequest, err.Error())
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

// ---------- JSON helpers ----------

func readJSON(r *http.Request, dst any) error {
	defer r.Body.Close()

	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()

	if err := dec.Decode(dst); err != nil {
		return err
	}

	// Reject trailing JSON values.
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		return errors.New("request body must contain a single JSON object")
	}
	return nil
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

type errorResponse struct {
	Error string `json:"error"`
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, errorResponse{Error: message})
}

// ---------- Production server helper ----------

func NewHTTPServer(addr string, handler http.Handler) *http.Server {
	return &http.Server{
		Addr:              addr,
		Handler:           handler,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
}

// ---------- REST client ----------

// APIError represents a non-2xx response.
type APIError struct {
	StatusCode int
	Body       string
}

func (e *APIError) Error() string {
	return fmt.Sprintf("api error %d: %s", e.StatusCode, e.Body)
}

type Client struct {
	BaseURL string
	HTTP    *http.Client
}

func NewClient(baseURL string) *Client {
	return &Client{
		BaseURL: strings.TrimRight(baseURL, "/"),
		HTTP: &http.Client{
			Timeout: 10 * time.Second,
		},
	}
}

func (c *Client) ListItems(ctx context.Context) ([]Item, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.BaseURL+"/items", nil)
	if err != nil {
		return nil, err
	}

	var items []Item
	if err := c.do(req, http.StatusOK, &items); err != nil {
		return nil, err
	}
	return items, nil
}

func (c *Client) GetItem(ctx context.Context, id string) (Item, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.BaseURL+"/items/"+id, nil)
	if err != nil {
		return Item{}, err
	}

	var item Item
	if err := c.do(req, http.StatusOK, &item); err != nil {
		return Item{}, err
	}
	return item, nil
}

func (c *Client) CreateItem(ctx context.Context, item Item) (Item, error) {
	body, err := json.Marshal(item)
	if err != nil {
		return Item{}, err
	}

	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPost,
		c.BaseURL+"/items",
		bytes.NewReader(body),
	)
	if err != nil {
		return Item{}, err
	}
	req.Header.Set("Content-Type", "application/json")

	var created Item
	if err := c.do(req, http.StatusCreated, &created); err != nil {
		return Item{}, err
	}
	return created, nil
}

func (c *Client) UpdateItem(ctx context.Context, id string, item Item) (Item, error) {
	body, err := json.Marshal(item)
	if err != nil {
		return Item{}, err
	}

	req, err := http.NewRequestWithContext(
		ctx,
		http.MethodPut,
		c.BaseURL+"/items/"+id,
		bytes.NewReader(body),
	)
	if err != nil {
		return Item{}, err
	}
	req.Header.Set("Content-Type", "application/json")

	var updated Item
	if err := c.do(req, http.StatusOK, &updated); err != nil {
		return Item{}, err
	}
	return updated, nil
}

func (c *Client) DeleteItem(ctx context.Context, id string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodDelete, c.BaseURL+"/items/"+id, nil)
	if err != nil {
		return err
	}
	return c.do(req, http.StatusNoContent, nil)
}

// do executes a request and decodes a successful JSON response.
func (c *Client) do(req *http.Request, expectedStatus int, dst any) error {
	resp, err := c.HTTP.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return err
	}

	if resp.StatusCode != expectedStatus {
		return &APIError{
			StatusCode: resp.StatusCode,
			Body:       string(body),
		}
	}

	if dst != nil && len(body) > 0 {
		if err := json.Unmarshal(body, dst); err != nil {
			return fmt.Errorf("decode response: %w", err)
		}
	}
	return nil
}

// ---------- Demo ----------

func main() {
	store := NewMemoryStore()
	api := NewAPI(store)

	// httptest server gives a real HTTP endpoint for the client.
	ts := httptest.NewServer(api.Routes())
	defer ts.Close()

	client := NewClient(ts.URL)
	ctx := context.Background()

	created, err := client.CreateItem(ctx, Item{
		Name:  "Keyboard",
		Price: 99.99,
	})
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("created: %+v\n", created)

	items, err := client.ListItems(ctx)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("items: %+v\n", items)

	got, err := client.GetItem(ctx, created.ID)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("got: %+v\n", got)

	updated, err := client.UpdateItem(ctx, created.ID, Item{
		Name:  "Mechanical Keyboard",
		Price: 129.99,
	})
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("updated: %+v\n", updated)

	if err := client.DeleteItem(ctx, created.ID); err != nil {
		log.Fatal(err)
	}
	fmt.Println("deleted successfully")

	// Demonstrate typed error handling.
	_, err = client.GetItem(ctx, created.ID)
	var apiErr *APIError
	if errors.As(err, &apiErr) {
		fmt.Printf("expected 404: %s\n", apiErr)
	}
}
