Below is a complete, runnable Go program that demonstrates idiomatic SQL usage with the standard `database/sql` package and a pure-Go SQLite driver (`modernc.org/sqlite`), so it builds without CGO.

### Project layout

```
sqlgo/
├── go.mod
└── main.go
```

### `go.mod`

```go
module sqlgo

go 1.22

require modernc.org/sqlite v1.29.0
```

### `main.go`

```go
package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"time"

	_ "modernc.org/sqlite" // register the "sqlite" driver
)

// User is our domain model. We keep sql.NullString for nullable columns
// so we don't lose the distinction between "" and NULL.
type User struct {
	ID        int64
	Name      string
	Email     sql.NullString
	CreatedAt time.Time
}

func main() {
	// Use an in-memory DB for a fully self-contained demo.
	// For a real app use a file path, e.g. "file:app.db?_pragma=foreign_keys(1)".
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	// SQLite benefits from a single connection for :memory: (each conn = new DB).
	db.SetMaxOpenConns(1)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := migrate(ctx, db); err != nil {
		log.Fatal(err)
	}

	repo := NewUserRepo(db)

	// ---- Create ----
	id, err := repo.Create(ctx, "Alice", "alice@example.com")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("created user id:", id)

	id2, err := repo.Create(ctx, "Bob", "") // NULL email
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("created user id:", id2)

	// ---- Read one ----
	u, err := repo.GetByID(ctx, id)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("got: %+v\n", u)

	// ---- Read many ----
	users, err := repo.List(ctx)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("all users:")
	for _, u := range users {
		email := "<null>"
		if u.Email.Valid {
			email = u.Email.String
		}
		fmt.Printf("  id=%d name=%s email=%s created=%s\n", u.ID, u.Name, email, u.CreatedAt.Format(time.RFC3339))
	}

	// ---- Update ----
	if err := repo.UpdateEmail(ctx, id, "alice@new.example"); err != nil {
		log.Fatal(err)
	}

	// ---- Delete ----
	if err := repo.Delete(ctx, id2); err != nil {
		log.Fatal(err)
	}

	// ---- Transaction: transfer "credits" between two accounts ----
	if err := transferCredits(ctx, db, 1, 2, 5); err != nil {
		// account 2 may not exist -> rollback demonstrated
		fmt.Println("transfer failed (expected in demo):", err)
	}

	fmt.Println("done")
}

// ---------- schema ----------

func migrate(ctx context.Context, db *sql.DB) error {
	const stmt = `
	CREATE TABLE IF NOT EXISTS users (
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT    NOT NULL,
		email      TEXT    UNIQUE,
		created_at TEXT    NOT NULL
	);
	CREATE TABLE IF NOT EXISTS accounts (
		id      INTEGER PRIMARY KEY,
		balance INTEGER NOT NULL DEFAULT 0
	);`
	_, err := db.ExecContext(ctx, stmt)
	return err
}

// ---------- repository ----------

type UserRepo struct {
	db *sql.DB
}

func NewUserRepo(db *sql.DB) *UserRepo { return &UserRepo{db: db} }

// Create inserts a user and returns its new id. Uses a prepared statement
// cached by the driver; ExecContext keeps it cancellable.
func (r *UserRepo) Create(ctx context.Context, name, email string) (int64, error) {
	var emailArg any
	if email == "" {
		emailArg = nil // -> NULL
	} else {
		emailArg = email
	}

	res, err := r.db.ExecContext(ctx,
		`INSERT INTO users (name, email, created_at) VALUES (?, ?, ?)`,
		name, emailArg, time.Now().UTC().Format(time.RFC3339),
	)
	if err != nil {
		return 0, fmt.Errorf("insert user: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("last insert id: %w", err)
	}
	return id, nil
}

// GetByID returns a single user or sql.ErrNoRows.
func (r *UserRepo) GetByID(ctx context.Context, id int64) (User, error) {
	row := r.db.QueryRowContext(ctx,
		`SELECT id, name, email, created_at FROM users WHERE id = ?`, id)

	var u User
	var email sql.NullString
	var created string
	if err := row.Scan(&u.ID, &u.Name, &email, &created); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return User{}, fmt.Errorf("user %d: %w", id, err)
		}
		return User{}, fmt.Errorf("scan user: %w", err)
	}
	u.Email = email
	t, err := time.Parse(time.RFC3339, created)
	if err != nil {
		return User{}, fmt.Errorf("parse created_at: %w", err)
	}
	u.CreatedAt = t
	return u, nil
}

// List returns all users ordered by id.
func (r *UserRepo) List(ctx context.Context) ([]User, error) {
	rows, err := r.db.QueryContext(ctx,
		`SELECT id, name, email, created_at FROM users ORDER BY id`)
	if err != nil {
		return nil, fmt.Errorf("query users: %w", err)
	}
	defer rows.Close() // always close to release the connection

	var out []User
	for rows.Next() {
		var u User
		var email sql.NullString
		var created string
		if err := rows.Scan(&u.ID, &u.Name, &email, &created); err != nil {
			return nil, fmt.Errorf("scan row: %w", err)
		}
		u.Email = email
		t, err := time.Parse(time.RFC3339, created)
		if err != nil {
			return nil, fmt.Errorf("parse created_at: %w", err)
		}
		u.CreatedAt = t
		out = append(out, u)
	}
	// rows.Err() captures any error encountered during iteration
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("rows: %w", err)
	}
	return out, nil
}

func (r *UserRepo) UpdateEmail(ctx context.Context, id int64, email string) error {
	res, err := r.db.ExecContext(ctx,
		`UPDATE users SET email = ? WHERE id = ?`, email, id)
	if err != nil {
		return fmt.Errorf("update: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if n == 0 {
		return fmt.Errorf("user %d not found", id)
	}
	return nil
}

func (r *UserRepo) Delete(ctx context.Context, id int64) error {
	res, err := r.db.ExecContext(ctx, `DELETE FROM users WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("delete: %w", err)
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		return fmt.Errorf("user %d not found", id)
	}
	return nil
}

// ---------- transaction example ----------

func transferCredits(ctx context.Context, db *sql.DB, from, to int64, amount int) error {
	tx, err := db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
	if err != nil {
		return err
	}
	// Rollback is safe to call after Commit (returns sql.ErrTxDone).
	defer tx.Rollback()

	// ensure accounts exist
	if _, err := tx.ExecContext(ctx,
		`INSERT OR IGNORE INTO accounts (id, balance) VALUES (?, 0)`, from); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx,
		`INSERT OR IGNORE INTO accounts (id, balance) VALUES (?, 0)`, to); err != nil {
		return err
	}

	var bal int
	if err := tx.QueryRowContext(ctx,
		`SELECT balance FROM accounts WHERE id = ?`, from).Scan(&bal); err != nil {
		return err
	}
	if bal < amount {
		return fmt.Errorf("insufficient balance: %d < %d", bal, amount)
	}

	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance - ? WHERE id = ?`, amount, from); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx,
		`UPDATE accounts SET balance = balance + ? WHERE id = ?`, amount, to); err != nil {
		return err
	}

	return tx.Commit()
}
```

### How to run

```bash
cd sqlgo
go mod tidy
go run .
```

### Key points covered

- **Driver registration** via blank import `_ "modernc.org/sqlite"`; driver name `"sqlite"`.
- **Context everywhere**: `ExecContext`, `QueryContext`, `QueryRowContext`, `BeginTx` — makes queries cancellable and timeout-aware.
- **NULL handling** with `sql.NullString` (and `any(nil)` for inserts).
- **Resource cleanup**: `defer rows.Close()` and `defer tx.Rollback()`.
- **Error wrapping** with `%w` and sentinel checks (`sql.ErrNoRows`).
- **Transactions** with explicit isolation level and rollback-on-error.
- **Connection pool tuning** (`SetMaxOpenConns`) — important for SQLite.
- **RowsAffected / LastInsertId** for write verification.

### Notes for production

- For Postgres/MySQL, swap the driver import and DSN; the `database/sql` API is identical.
- Prefer a migration tool (e.g. `golang-migrate`) over inline `CREATE TABLE`.
- For complex scanning, libraries like `sqlx` or `pgx` reduce boilerplate; `sqlc` generates type-safe code from SQL.
- Always set `SetConnMaxLifetime` and pool limits for networked databases.

# SQL Queries in Go

## The Idea

Go's standard library provides a **database-agnostic** SQL interface in `database/sql`. It defines types and methods (`*sql.DB`, `*sql.Rows`, `*sql.Row`, `*sql.Tx`, `*sql.Stmt`) but contains **no actual driver**. You plug in a driver (SQLite, PostgreSQL, MySQL) via an import. This gives portability, connection pooling, and a uniform API across databases.

Key concepts:

- `*sql.DB` is **not a single connection** — it's a pooled handle. Safe to share across goroutines.
- Queries return `*sql.Rows` (multiple rows) or `*sql.Row` (single row).
- You scan columns into Go variables with `Scan`.
- Always `defer rows.Close()` to release connections.
- Use **context** variants for timeouts/cancellation.
- Use **parameterized queries** (`?`, `$1`) to prevent SQL injection.

## Setup

```bash
go mod init example
go get github.com/mattn/go-sqlite3   # CGO driver; or use modernc.org/sqlite (pure Go)
```

```go
package main

import (
    "database/sql"
    "fmt"
    "log"

    _ "github.com/mattn/go-sqlite3" // register driver
)

func main() {
    db, err := sql.Open("sqlite3", "file:example.db?_foreign_keys=on")
    if err != nil {
        log.Fatal(err)
    }
    defer db.Close()

    // Verify connectivity (optional but recommended)
    if err := db.Ping(); err != nil {
        log.Fatal(err)
    }
    _ = db
}
```

`sql.Open` does **not** open a connection immediately; it configures the pool. `Ping` forces a real connection.

## Creating Schema

```go
func initSchema(db *sql.DB) error {
    const ddl = `
    CREATE TABLE IF NOT EXISTS users (
        id    INTEGER PRIMARY KEY AUTOINCREMENT,
        name  TEXT NOT NULL,
        email TEXT NOT NULL UNIQUE
    );`
    _, err := db.Exec(ddl)
    return err
}
```

`Exec` is for statements that don't return rows (INSERT/UPDATE/DELETE/DDL). It returns `sql.Result` (LastInsertId, RowsAffected).

## Inserting Data

```go
func createUser(db *sql.DB, name, email string) (int64, error) {
    res, err := db.Exec(
        "INSERT INTO users (name, email) VALUES (?, ?)",
        name, email,
    )
    if err != nil {
        return 0, err
    }
    id, err := res.LastInsertId()
    return id, err
}
```

Placeholders: `?` for SQLite/MySQL, `$1, $2, ...` for PostgreSQL. Always parameterize — never concatenate user input.

## Querying Multiple Rows

```go
type User struct {
    ID    int64
    Name  string
    Email string
}

func listUsers(db *sql.DB) ([]User, error) {
    rows, err := db.Query("SELECT id, name, email FROM users ORDER BY id")
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var users []User
    for rows.Next() {
        var u User
        if err := rows.Scan(&u.ID, &u.Name, &u.Email); err != nil {
            return nil, err
        }
        users = append(users, u)
    }
    // Check for errors that occurred during iteration
    if err := rows.Err(); err != nil {
        return nil, err
    }
    return users, nil
}
```

Important: `rows.Err()` catches errors that arise while iterating (e.g., network issues mid-stream).

## Querying a Single Row

```go
func getUser(db *sql.DB, id int64) (User, error) {
    var u User
    err := db.QueryRow(
        "SELECT id, name, email FROM users WHERE id = ?", id,
    ).Scan(&u.ID, &u.Name, &u.Email)

    if err == sql.ErrNoRows {
        return u, fmt.Errorf("user %d not found", id)
    }
    return u, err
}
```

`QueryRow` always returns a `*sql.Row`; `Scan` returns `sql.ErrNoRows` if nothing matched. Don't call `Close` on `*sql.Row`.

## Parameterized Queries with Context (Recommended)

```go
import "context"

func findUsers(ctx context.Context, db *sql.DB, like string) ([]User, error) {
    rows, err := db.QueryContext(ctx,
        "SELECT id, name, email FROM users WHERE name LIKE ?", "%"+like+"%")
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var out []User
    for rows.Next() {
        var u User
        if err := rows.Scan(&u.ID, &u.Name, &u.Email); err != nil {
            return nil, err
        }
        out = append(out, u)
    }
    return out, rows.Err()
}
```

Context variants (`QueryContext`, `ExecContext`, `QueryRowContext`) allow cancellation and timeouts, critical in HTTP handlers.

## Prepared Statements

Useful when executing the same query many times:

```go
stmt, err := db.Prepare("INSERT INTO users (name, email) VALUES (?, ?)")
if err != nil {
    log.Fatal(err)
}
defer stmt.Close()

for _, u := range batch {
    if _, err := stmt.Exec(u.Name, u.Email); err != nil {
        log.Println(err)
    }
}
```

Prepared statements are connection-bound internally; `database/sql` caches them on the pool. For single use, `db.Exec` with args is fine (it prepares internally).

## Transactions

```go
func transferBalance(db *sql.DB, from, to int64, amount float64) error {
    tx, err := db.BeginTx(context.Background(), &sql.TxOptions{
        Isolation: sql.LevelSerializable,
    })
    if err != nil {
        return err
    }
    // Always rollback on early return; Commit makes this a no-op
    defer tx.Rollback()

    if _, err := tx.Exec(
        "UPDATE accounts SET balance = balance - ? WHERE id = ?", amount, from); err != nil {
        return err
    }
    if _, err := tx.Exec(
        "UPDATE accounts SET balance = balance + ? WHERE id = ?", amount, to); err != nil {
        return err
    }

    return tx.Commit()
}
```

Within a transaction, use `tx.Exec`/`tx.Query` (not `db.*`), so statements run on the same connection.

## NULL Handling

Columns can be NULL; scan into `sql.NullString`, `sql.NullInt64`, etc., or use pointers:

```go
var name sql.NullString
db.QueryRow("SELECT name FROM users WHERE id = ?", id).Scan(&name)
if name.Valid {
    fmt.Println(name.String)
}

// Or pointer
var name *string
db.QueryRow("SELECT name FROM users WHERE id = ?", id).Scan(&name)
```

## Dynamic Columns / Unknown Schema

```go
cols, _ := rows.Columns()
vals := make([]interface{}, len(cols))
ptrs := make([]interface{}, len(cols))
for i := range vals {
    ptrs[i] = &vals[i]
}
for rows.Next() {
    rows.Scan(ptrs...)
    // vals now contains driver.Value (interface{})
}
```

## Pool Tuning

```go
db.SetMaxOpenConns(25)
db.SetMaxIdleConns(5)
db.SetConnMaxLifetime(5 * time.Minute)
db.SetConnMaxIdleTime(1 * time.Minute)
```

## Typical Use Cases

1. **CRUD in web services**: handlers call repository functions using `QueryContext`/`ExecContext`.
2. **Batch imports**: loop over `stmt.Exec` inside a transaction for speed.
3. **Reporting**: stream large result sets with `rows.Next()` (avoid loading all into memory).
4. **Migrations**: run DDL on startup.
5. **Multi-tenant**: separate DB per tenant or schema-qualified queries.

## Common Pitfalls

- Forgetting `defer rows.Close()` → connection leak.
- Ignoring `rows.Err()`.
- Not handling `sql.ErrNoRows`.
- Concatenating SQL strings (injection risk).
- Using `db` inside a transaction instead of `tx`.
- Holding transactions open across network calls.
- Forgetting context timeouts → hung goroutines.

## Higher-Level Helpers

Most teams use `sqlx` (named params, struct scanning) or an ORM/query builder (`gorm`, `sqlc`, `ent`). Example with `sqlx`:

```go
import "github.com/jmoiron/sqlx"

type User struct {
    ID    int64  `db:"id"`
    Name  string `db:"name"`
    Email string `db:"email"`
}

var users []User
err := db.SelectContext(ctx, &users, "SELECT * FROM users WHERE name LIKE ?", "%"+q+"%")
```

`sqlc` generates type-safe Go from SQL files — often preferred for large projects.

## Summary

- Use `database/sql` + a driver.
- `Open` once, share the `*sql.DB`.
- `Exec` for writes, `Query`/`QueryRow` for reads.
- Always scan with `rows.Scan`, close rows, check `rows.Err()`.
- Parameterize everything; use context variants; wrap multi-step writes in transactions.

This pattern keeps code simple, portable, and safe while letting you scale up to `sqlx`/`sqlc` when needed.

A very common mistake is **building a SQL query by concatenating user input into the string**. This opens the door to SQL injection and can also break on quotes/apostrophes.

### Mistaken version

```go
package main

import (
	"database/sql"
	"fmt"
)

func getUserEmail(db *sql.DB, username string) (string, error) {
	// BAD: user input is interpolated directly into the SQL text.
	query := "SELECT email FROM users WHERE username = '" + username + "'"

	var email string
	err := db.QueryRow(query).Scan(&email)
	if err != nil {
		return "", err
	}
	return email, nil
}
```

If `username` is something like:

```text
' OR '1'='1
```

the resulting query becomes:

```sql
SELECT email FROM users WHERE username = '' OR '1'='1'
```

which can return every user’s email. Worse inputs can modify or delete data.

---

### Corrected version

```go
package main

import (
	"database/sql"
	"fmt"
)

func getUserEmail(db *sql.DB, username string) (string, error) {
	// GOOD: use a parameterized query. The placeholder syntax depends on the driver:
	//   ?  for MySQL, SQLite, etc.
	//   $1 for PostgreSQL.
	const query = "SELECT email FROM users WHERE username = ?"

	var email string
	err := db.QueryRow(query, username).Scan(&email)
	if err != nil {
		// sql.ErrNoRows is a normal "not found" case; callers can check it.
		return "", err
	}
	return email, nil
}
```

### Why this is better

1. **No SQL injection**  
   The SQL text is fixed. The database driver sends the query and the parameter separately, so user input is treated strictly as data, never as SQL syntax.

2. **Handles special characters safely**  
   Names containing quotes, backslashes, or Unicode are handled correctly by the driver.

3. **Better plan caching**  
   Parameterized queries often reuse execution plans, which can improve performance.

4. **Clearer error handling**  
   `QueryRow` returns a `*sql.Row`; calling `Scan` reveals errors such as `sql.ErrNoRows`. You should not ignore that error.

---

### Related common mistakes worth fixing in the same area

- **Forgetting `rows.Close()`** when using `db.Query`:
  ```go
  rows, err := db.Query("SELECT id, name FROM users")
  if err != nil {
      return err
  }
  defer rows.Close() // important
  for rows.Next() {
      // scan...
  }
  if err := rows.Err(); err != nil {
      return err
  }
  ```

- **Using the wrong scan destinations** (e.g., scanning a nullable column into a non-pointer `string`). Use `sql.NullString`, `*string`, or appropriate types.

- **Leaving transactions uncommitted/rolled back**:
  ```go
  tx, err := db.Begin()
  if err != nil {
      return err
  }
  defer tx.Rollback() // safe default; Commit overrides on success
  // ... do work ...
  return tx.Commit()
  ```

- **Not distinguishing “not found” from real errors**:
  ```go
  if errors.Is(err, sql.ErrNoRows) {
      // handle missing row
  }
  ```

So the core fix is: **never concatenate untrusted input into SQL; always use placeholders and pass values as arguments.**

## Exercise

Build a small Go program that manages `users` in SQLite using only `database/sql`. Requirements:

1. Create a `users` table if it doesn't exist.
2. Implement `Create`, `GetByID`, `ListByEmailPrefix`, `UpdateEmail`, and `Delete`.
3. Use `context.Context` with timeouts on every query.
4. Use parameterized SQL (`?`) everywhere—no string concatenation.
5. Implement `BatchCreate` inside a transaction with a prepared statement.
6. Handle `sql.ErrNoRows`, row-scan errors, and transaction rollback correctly.
7. Store `created_at` as Unix milliseconds and convert to `time.Time` in Go.

---

## Step-by-step solution

### 1. Module setup

Use the pure-Go SQLite driver so the example builds without CGO:

```bash
go mod init userstore
go get modernc.org/sqlite
```

### 2. Package and imports

```go
package main

import (
    "context"
    "database/sql"
    "errors"
    "fmt"
    "time"

    _ "modernc.org/sqlite"
)
```

The blank import registers the `"sqlite"` driver with `database/sql`.

### 3. Model and repository

Keep SQL details inside a repository type. The public API only exposes Go types.

```go
type User struct {
    ID        int64
    Name      string
    Email     string
    CreatedAt time.Time
}

type UserRepository struct {
    db *sql.DB
}
```

### 4. Opening the database safely

With `:memory:` and a connection pool, each connection gets a separate in-memory database. Force a single connection so migrations and queries share state.

```go
func openDB() (*sql.DB, error) {
    db, err := sql.Open("sqlite", ":memory:")
    if err != nil {
        return nil, err
    }
    db.SetMaxOpenConns(1)
    db.SetMaxIdleConns(1)

    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    if err := db.PingContext(ctx); err != nil {
        db.Close()
        return nil, err
    }
    return db, nil
}
```

### 5. Migration

Run once at startup. `ExecContext` is appropriate because there are no rows to scan.

```go
func migrate(ctx context.Context, db *sql.DB) error {
    const q = `
    CREATE TABLE IF NOT EXISTS users (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL,
        email      TEXT    NOT NULL UNIQUE,
        created_at INTEGER NOT NULL
    )`
    _, err := db.ExecContext(ctx, q)
    return err
}
```

### 6. CRUD methods

#### Create

`LastInsertId` gives the generated primary key. Use `time.Now().UTC().UnixMilli()` for a stable, sortable timestamp.

```go
func (r *UserRepository) Create(ctx context.Context, name, email string) (int64, error) {
    const q = `INSERT INTO users (name, email, created_at) VALUES (?, ?, ?)`
    res, err := r.db.ExecContext(ctx, q, name, email, time.Now().UTC().UnixMilli())
    if err != nil {
        return 0, fmt.Errorf("create user: %w", err)
    }
    id, err := res.LastInsertId()
    if err != nil {
        return 0, fmt.Errorf("last insert id: %w", err)
    }
    return id, nil
}
```

#### GetByID

`QueryRowContext` returns a row handle; always call `Scan`. Convert `sql.ErrNoRows` into a domain-friendly error or sentinel.

```go
var ErrNotFound = errors.New("user not found")

func (r *UserRepository) GetByID(ctx context.Context, id int64) (*User, error) {
    const q = `SELECT id, name, email, created_at FROM users WHERE id = ?`
    row := r.db.QueryRowContext(ctx, q, id)

    var u User
    var createdMillis int64
    if err := row.Scan(&u.ID, &u.Name, &u.Email, &createdMillis); err != nil {
        if errors.Is(err, sql.ErrNoRows) {
            return nil, ErrNotFound
        }
        return nil, fmt.Errorf("get user by id: %w", err)
    }
    u.CreatedAt = time.UnixMilli(createdMillis).UTC()
    return &u, nil
}
```

#### ListByEmailPrefix

Use `rows.Err()` after the loop to catch iteration errors. `LIKE` with `prefix || '%'` is safe because `prefix` is still a parameter.

```go
func (r *UserRepository) ListByEmailPrefix(ctx context.Context, prefix string, limit int) ([]User, error) {
    const q = `
        SELECT id, name, email, created_at
        FROM users
        WHERE email LIKE ? || '%'
        ORDER BY id
        LIMIT ?`
    rows, err := r.db.QueryContext(ctx, q, prefix, limit)
    if err != nil {
        return nil, fmt.Errorf("list users: %w", err)
    }
    defer rows.Close()

    var users []User
    for rows.Next() {
        var u User
        var createdMillis int64
        if err := rows.Scan(&u.ID, &u.Name, &u.Email, &createdMillis); err != nil {
            return nil, fmt.Errorf("scan user: %w", err)
        }
        u.CreatedAt = time.UnixMilli(createdMillis).UTC()
        users = append(users, u)
    }
    if err := rows.Err(); err != nil {
        return nil, fmt.Errorf("rows iteration: %w", err)
    }
    return users, nil
}
```

#### UpdateEmail

```go
func (r *UserRepository) UpdateEmail(ctx context.Context, id int64, email string) error {
    const q = `UPDATE users SET email = ? WHERE id = ?`
    res, err := r.db.ExecContext(ctx, q, email, id)
    if err != nil {
        return fmt.Errorf("update email: %w", err)
    }
    n, err := res.RowsAffected()
    if err != nil {
        return fmt.Errorf("rows affected: %w", err)
    }
    if n == 0 {
        return ErrNotFound
    }
    return nil
}
