### 7. Transactional batch insert

Prepare the statement once inside the transaction, reuse it for every row, and rollback on any error. `defer tx.Rollback()` is safe to call after `Commit`.

```go
func (r *UserRepository) BatchCreate(ctx context.Context, users []User) error {
    tx, err := r.db.BeginTx(ctx, nil)
    if err != nil {
        return fmt.Errorf("begin tx: %w", err)
    }
    defer tx.Rollback() // no-op after successful Commit

    stmt, err := tx.PrepareContext(ctx, `
        INSERT INTO users (name, email, created_at) VALUES (?, ?, ?)`)
    if err != nil {
        return fmt.Errorf("prepare: %w", err)
    }
    defer stmt.Close()

    for _, u := range users {
        if _, err := stmt.ExecContext(ctx, u.Name, u.Email, u.CreatedAt.UTC().UnixMilli()); err != nil {
            return fmt.Errorf("insert %s: %w", u.Email, err)
        }
    }
    if err := tx.Commit(); err != nil {
        return fmt.Errorf("commit: %w", err)
    }
    return nil
}
```

