## Final solution (single file)

```go
package main

import (
    "context"
    "database/sql"
    "errors"
    "fmt"
    "time"

    _ "modernc.org/sqlite"
)

type User struct {
    ID        int64
    Name      string
    Email     string
    CreatedAt time.Time
}

var ErrNotFound = errors.New("user not found")

type UserRepository struct {
    db *sql.DB
}

func openDB() (*sql.DB, error) {
    db, err := sql.Open("sqlite", ":memory:")
    if err != nil {
        return nil, err
    }
    db.SetMaxOpenConns(1)
    db.SetMaxIdleConns(1)

    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()
    if err := db.PingContext(ctx); err != nil {
        db.Close()
        return nil, err
    }
    return db, nil
}

func migrate(ctx context.Context, db *sql.DB) error {
    const q = `
    CREATE TABLE IF NOT EXISTS users (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        name       TEXT    NOT NULL,
        email      TEXT    NOT NULL UNIQUE,
        created_at INTEGER NOT NULL
    )`
    _, err := db.ExecContext(ctx, q)
    return err
}

func (r *UserRepository) Create(ctx context.Context, name, email string) (int64, error) {
    const q = `INSERT INTO users (name, email, created_at) VALUES (?, ?, ?)`
    res, err := r.db.ExecContext(ctx, q, name, email, time.Now().UTC().UnixMilli())
    if err != nil {
        return 0, fmt.Errorf("create user: %w", err)
    }
    id, err := res.LastInsertId()
    if err != nil {
        return 0, fmt.Errorf("last insert id: %w", err)
    }
    return id, nil
}

func (r *UserRepository) GetByID(ctx context.Context, id int64) (*User, error) {
    const q = `SELECT id, name, email, created_at FROM users WHERE id = ?`
    row := r.db.QueryRowContext(ctx, q, id)

    var u User
    var createdMillis int64
    if err := row.Scan(&u.ID, &u.Name, &u.Email, &createdMillis); err != nil {
        if errors.Is(err, sql.ErrNoRows) {
            return nil, ErrNotFound
        }
        return nil, fmt.Errorf("get user by id: %w", err)
    }
    u.CreatedAt = time.UnixMilli(createdMillis).UTC()
    return &u, nil
}

func (r *UserRepository) ListByEmailPrefix(ctx context.Context, prefix string, limit int) ([]User, error) {
    const q = `
        SELECT id, name, email, created_at
        FROM users
        WHERE email LIKE ? || '%'
        ORDER BY id
        LIMIT ?`
    rows, err := r.db.QueryContext(ctx, q, prefix, limit)
    if err != nil {
        return nil, fmt.Errorf("list users: %w", err)
    }
    defer rows.Close()

    var users []User
    for rows.Next() {
        var u User
        var createdMillis int64
        if err := rows.Scan(&u.ID, &u.Name, &u.Email, &createdMillis); err != nil {
            return nil, fmt.Errorf("scan user: %w", err)
        }
        u.CreatedAt = time.UnixMilli(createdMillis).UTC()
        users = append(users, u)
    }
    if err := rows.Err(); err != nil {
        return nil, fmt.Errorf("rows iteration: %w", err)
    }
    return users, nil
}

func (r *UserRepository) UpdateEmail(ctx context.Context, id int64, email string) error {
    const q = `UPDATE users SET email = ? WHERE id = ?`
    res, err := r.db.ExecContext(ctx, q, email, id)
    if err != nil {
        return fmt.Errorf("update email: %w", err)
    }
    n, err := res.RowsAffected()
    if err != nil {
        return fmt.Errorf("rows affected: %w", err)
    }
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

func (r *UserRepository) Delete(ctx context.Context, id int64) error {
    const q = `DELETE FROM users WHERE id = ?`
    res, err := r.db.ExecContext(ctx, q, id)
    if err != nil {
        return fmt.Errorf("delete user: %w", err)
    }
    n, _ := res.RowsAffected()
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

func (r *UserRepository) BatchCreate(ctx context.Context, users []User) error {
    tx, err := r.db.BeginTx(ctx, nil)
    if err != nil {
        return fmt.Errorf("begin tx: %w", err)
    }
    defer tx.Rollback()

    stmt, err := tx.PrepareContext(ctx, `
        INSERT INTO users (name, email, created_at) VALUES (?, ?, ?)`)
    if err != nil {
        return fmt.Errorf("prepare: %w", err)
    }
    defer stmt.Close()

    for _, u := range users {
        if _, err := stmt.ExecContext(ctx, u.Name, u.Email, u.CreatedAt.UTC().UnixMilli()); err != nil {
            return fmt.Errorf("insert %s: %w", u.Email, err)
        }
    }
    if err := tx.Commit(); err != nil {
        return fmt.Errorf("commit: %w", err)
    }
    return nil
}

func main() {
    db, err := openDB()
    if err != nil {
        panic(err)
    }
    defer db.Close()

    ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
    defer cancel()

    if err := migrate(ctx, db); err != nil {
        panic(err)
    }

    repo := &UserRepository{db: db}

    id, err := repo.Create(ctx, "Alice", "alice@example.com")
    if err != nil {
        panic(err)
    }
    fmt.Println("created id:", id)

    err = repo.BatchCreate(ctx, []User{
        {Name: "Bob", Email: "bob@example.com", CreatedAt: time.Now()},
        {Name: "Carol", Email: "carol@work.com", CreatedAt: time.Now()},
    })
    if err != nil {
        panic(err)
    }

    users, err := repo.ListByEmailPrefix(ctx, "a", 10)
    if err != nil {
        panic(err)
    }
    for _, u := range users {
        fmt.Printf("%d %s %s %s\n", u.ID, u.Name, u.Email, u.CreatedAt.Format(time.RFC3339))
    }

    if err := repo.UpdateEmail(ctx, id, "alice@newdomain.com"); err != nil {
        panic(err)
    }

    u, err := repo.GetByID(ctx, id)
    if err != nil {
        panic(err)
    }
    fmt.Println("updated:", u.Email)

    if err := repo.Delete(ctx, id); err != nil {
        panic(err)
    }
    if _, err := repo.GetByID(ctx, id); err != nil {
        fmt.Println("expected not found:", err)
    }
}
