### Key takeaways

- Always use `?` placeholders; never interpolate user input into SQL.
- Pass `context.Context` into every `database/sql` call and set timeouts at the edges.
- Check `rows.Err()` after iterating rows, and always `defer rows.Close()`.
- Use `BeginTx` + prepared statements for batched writes, with `defer tx.Rollback()` for safe cleanup.
- Normalize time storage (here: Unix milliseconds) so scanning is driver-independent.
- Distinguish “no row” (`sql.ErrNoRows`) from real errors.

## SQL queries in Go — interview-style answer

### 1. Mental model

In Go, SQL is accessed through the standard library package `database/sql`. It is **driver-agnostic**: you import a driver (e.g. `github.com/lib/pq`, `github.com/go-sql-driver/mysql`) for its side effects, and `database/sql` provides the API.

Key concepts an interviewer wants to hear:

| Concept | What it is | Gotcha |
|---|---|---|
| `*sql.DB` | A **pool** of connections, not a single connection | Don't open/close per query; create once, share |
| `sql.Open` | Lazy — does not connect | Call `PingContext` to verify |
| `Query`/`QueryRow`/`Exec` | Run SQL | Always use **placeholders** (`$1`, `?`), never string concat |
| `Rows.Scan` | Copies column values into Go variables | Pointers required; types must be compatible |
| `Tx` | Transaction | Must `Commit` or `Rollback` |
| Prepared stmts | Pre-parsed SQL on the server | Good for hot paths; pool handles caching |

### 2. Safety rules (the part that matters most)

- **Never** build SQL with `fmt.Sprintf` + user input → SQL injection.
- Always pass user values as `args ...any` after the query string.
- Use `context.Context` variants (`QueryContext`, `ExecContext`) for cancellation/timeouts.
- Always `defer rows.Close()` and check `rows.Err()`.
- Set pool limits: `SetMaxOpenConns`, `SetMaxIdleConns`, `SetConnMaxLifetime`.

### 3. Core implementation

Below is a small, clean, reusable core: connection setup, generic row scanning into structs via reflection, single-row fetch, exec, and a transaction wrapper.

```go
// db.go
package db

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"reflect"
	"strings"
	"time"
)

// ---------- Config & open ----------

type Config struct {
	Driver  string        // "postgres", "mysql", ...
	DSN     string
	MaxOpen int
	MaxIdle int
	MaxLife time.Duration
}

// Open creates a pooled *sql.DB and verifies connectivity.
func Open(cfg Config) (*sql.DB, error) {
	if cfg.Driver == "" || cfg.DSN == "" {
		return nil, errors.New("db: driver and dsn are required")
	}
	db, err := sql.Open(cfg.Driver, cfg.DSN)
	if err != nil {
		return nil, fmt.Errorf("db: open: %w", err)
	}
	if cfg.MaxOpen > 0 {
		db.SetMaxOpenConns(cfg.MaxOpen)
	}
	if cfg.MaxIdle > 0 {
		db.SetMaxIdleConns(cfg.MaxIdle)
	}
	if cfg.MaxLife > 0 {
		db.SetConnMaxLifetime(cfg.MaxLife)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil {
		db.Close()
		return nil, fmt.Errorf("db: ping: %w", err)
	}
	return db, nil
}

// ---------- Generic scanning ----------

// QueryRows runs a parameterized query and scans each row into T.
// T must be a struct; columns are matched by `db` tag or field name (case-insensitive).
func QueryRows[T any](ctx context.Context, db *sql.DB, query string, args ...any) ([]T, error) {
	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("db: query: %w", err)
	}
	defer rows.Close()

	cols, err := rows.Columns()
	if err != nil {
		return nil, fmt.Errorf("db: columns: %w", err)
	}

	var out []T
	for rows.Next() {
		v := new(T)
		if err := scanInto(rows, v, cols); err != nil {
			return nil, err
		}
		out = append(out, *v)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("db: rows: %w", err)
	}
	return out, nil
}

// QueryOne fetches at most one row. Returns (value, found, err).
func QueryOne[T any](ctx context.Context, db *sql.DB, query string, args ...any) (T, bool, error) {
	rows, err := QueryRows[T](ctx, db, query, args...)
	if err != nil {
		var zero T
		return zero, false, err
	}
	if len(rows) == 0 {
		var zero T
		return zero, false, nil
	}
	if len(rows) > 1 {
		var zero T
		return zero, false, errors.New("db: expected at most one row")
	}
	return rows[0], true, nil
}

// Exec runs a statement (INSERT/UPDATE/DELETE) and returns the result.
func Exec(ctx context.Context, db *sql.DB, query string, args ...any) (sql.Result, error) {
	res, err := db.ExecContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("db: exec: %w", err)
	}
	return res, nil
}

// ---------- Transactions ----------

// WithTx runs fn inside a transaction; commits on nil error, rolls back otherwise.
func WithTx(ctx context.Context, db *sql.DB, fn func(*sql.Tx) error) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("db: begin: %w", err)
	}
	if err := fn(tx); err != nil {
		if rbErr := tx.Rollback(); rbErr != nil {
			return fmt.Errorf("db: rollback failed: %v (orig: %w)", rbErr, err)
		}
		return err
	}
	return tx.Commit()
}

// ---------- Reflection helpers ----------

// scanInto copies the current row into the struct pointed to by dest.
func scanInto(rows *sql.Rows, dest any, cols []string) error {
	v := reflect.ValueOf(dest)
	if v.Kind() != reflect.Ptr || v.IsNil() {
		return errors.New("db: dest must be a non-nil pointer to struct")
	}
	v = v.Elem()
	if v.Kind() != reflect.Struct {
		return errors.New("db: dest must point to a struct")
	}
	t := v.Type()

	// Build a map: lowercased column name -> field index.
	fieldByCol := make(map[string]int, t.NumField())
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if !f.IsExported() {
			continue
		}
		name := f.Tag.Get("db")
		if name == "-" {
			continue
		}
		if name == "" {
			name = f.Name
		}
		// support "name,omitempty" style (ignore options)
		if idx := strings.Index(name, ","); idx >= 0 {
			name = name[:idx]
		}
		fieldByCol[strings.ToLower(name)] = i
	}

	scanVals := make([]any, len(cols))
	for i, c := range cols {
		if idx, ok := fieldByCol[strings.ToLower(c)]; ok {
			field := v.Field(idx)
			// Field must be addressable; it is, because v came from a pointer.
			scanVals[i] = field.Addr().Interface()
		} else {
			// Unknown column: scan into a discard target.
			var discard any
			scanVals[i] = &discard
		}
	}
	return rows.Scan(scanVals...)
}
```

### 4. Usage example

```go
// main.go
package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	"example.com/app/db"
)

type User struct {
	ID        int64     `db:"id"`
	Email     string    `db:"email"`
	CreatedAt time.Time `db:"created_at"`
}

func main() {
	sqlDB, err := db.Open(db.Config{
		Driver:  "postgres",
		DSN:     "postgres://user:pass@localhost:5432/app?sslmode=disable",
		MaxOpen: 25,
		MaxIdle: 5,
		MaxLife: 30 * time.Minute,
	})
	if err != nil {
		log.Fatal(err)
	}
	defer sqlDB.Close()

	ctx := context.Background()

	// Parameterized query — safe from injection.
	users, err := db.QueryRows[User](ctx, sqlDB,
		"SELECT id, email, created_at FROM users WHERE email LIKE $1 LIMIT $2",
		"%@example.com", 10,
	)
	if err != nil {
		log.Fatal(err)
	}
	for _, u := range users {
		fmt.Printf("%d %s %v\n", u.ID, u.Email, u.CreatedAt)
	}

	// Single row.
	u, found, err := db.QueryOne[User](ctx, sqlDB,
		"SELECT id, email, created_at FROM users WHERE id = $1", 42,
	)
	if err != nil || !found {
		log.Println("not found or err:", err)
	} else {
		fmt.Println("found:", u.Email)
	}

	// Transactional write.
	err = db.WithTx(ctx, sqlDB, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx,
			"INSERT INTO users(email) VALUES ($1)", "new@example.com")
		if err != nil {
			return err
		}
		id, _ := res.LastInsertId()
		_, err = tx.ExecContext(ctx,
			"INSERT INTO audit_log(user_id, action) VALUES ($1, $2)", id, "signup")
		return err
	})
	if err != nil {
		log.Fatal(err)
	}
	_ = sql
}
```

### 5. Interview follow-ups you should mention

- **Nullable columns**: use `sql.NullString`, `sql.NullTime`, or pointers (`*string`) in the struct; the scanner handles them because `field.Addr().Interface()` yields a pointer sql can scan into.
- **N+1 / performance**: prefer joins; use `sqlx` or a query builder (squirrel) if you need more ergonomics, but the core pattern above is what those libraries wrap.
- **Context propagation**: pass `ctx` everywhere; respect cancellation.
- **Migrations**: out of scope here, but use `golang-migrate` / `goose`.
- **Testing**: use `sqlmock` or a real DB in a container (testcontainers-go).

### 6. Common pitfalls to call out

1. Forgetting `rows.Close()` → connection leak.
2. Ignoring `rows.Err()` → silent truncation.
3. Using `Query` for writes → use `Exec`.
4. Scanning into non-pointer fields → panic; scanner above avoids by taking addresses.
5. Sharing `*sql.Tx` across goroutines → not safe.

This gives you a clean, idiomatic, interview-ready answer: concepts first, then a small but real implementation you can extend.

Below are the most important edge cases when using `database/sql` in Go, each with a concrete code example. The examples assume a standard `*sql.DB` and use `?` placeholders (SQLite/MySQL style); adjust to `$1` for PostgreSQL where noted.

---

## 1. SQL injection: never interpolate values

**Edge case:** concatenating user input into SQL.  
**Fix:** always use placeholders and pass arguments separately.

```go
// BAD
q := "SELECT id, name FROM users WHERE email = '" + email + "'"

// GOOD
row := db.QueryRowContext(ctx,
    "SELECT id, name FROM users WHERE email = ?", email)
```

If you must build dynamic SQL (column names, `IN` lists), validate identifiers against an allow-list and generate placeholders programmatically (see §8).

---

## 2. `NULL` handling

**Edge case:** scanning a `NULL` column into a non-nullable Go type returns an error.  
**Fix:** use `sql.Null*` types, pointers, or `COALESCE` in SQL.

```go
type User struct {
    ID   int
    Name sql.NullString // may be NULL
    Bio  *string        // alternative: pointer
}

func getUser(ctx context.Context, db *sql.DB, id int) (User, error) {
    var u User
    err := db.QueryRowContext(ctx,
        "SELECT id, name, bio FROM users WHERE id = ?", id).
        Scan(&u.ID, &u.Name, &u.Bio)
    if err != nil {
        return u, err
    }
    if u.Name.Valid {
        fmt.Println("name:", u.Name.String)
    }
    if u.Bio != nil {
        fmt.Println("bio:", *u.Bio)
    }
    return u, nil
}

// Inserting NULL explicitly
_, err := db.ExecContext(ctx,
    "INSERT INTO users(name, bio) VALUES (?, ?)", nil, nil)
```

---

## 3. Missing rows: `sql.ErrNoRows`

**Edge case:** `QueryRow.Scan` returns `sql.ErrNoRows` when no row matches.  
**Fix:** distinguish “not found” from real errors.

```go
var name string
err := db.QueryRowContext(ctx,
    "SELECT name FROM users WHERE id = ?", id).Scan(&name)

if errors.Is(err, sql.ErrNoRows) {
    // handle not found
    return ErrNotFound
}
if err != nil {
    return err
}
```

---

## 4. Iterating rows correctly

**Edge case:** forgetting `rows.Err()`, not closing rows, or scanning after `Next()` returns false.  
**Fix:** `defer rows.Close()`, check `rows.Err()` after the loop.

```go
rows, err := db.QueryContext(ctx, "SELECT id, name FROM users")
if err != nil {
    return err
}
defer rows.Close()

for rows.Next() {
    var id int
    var name sql.NullString
    if err := rows.Scan(&id, &name); err != nil {
        return err // scanning error
    }
    // use id, name
}
// IMPORTANT: check iteration error
if err := rows.Err(); err != nil {
    return err
}
```

---

## 5. Transactions: rollback on any error

**Edge case:** partial commits, leaked transactions, or forgetting rollback.  
**Fix:** use `BeginTx`, defer rollback, commit only at the end.

```go
func transfer(ctx context.Context, db *sql.DB, from, to int, amount float64) error {
    tx, err := db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
    if err != nil {
        return err
    }
    // Rollback is safe after Commit (returns ErrTxDone, ignored).
    defer tx.Rollback()

    var balance float64
    err = tx.QueryRowContext(ctx,
        "SELECT balance FROM accounts WHERE id = ? FOR UPDATE", from).Scan(&balance)
    if err != nil {
        return err
    }
    if balance < amount {
        return ErrInsufficientFunds
    }

    if _, err = tx.ExecContext(ctx,
        "UPDATE accounts SET balance = balance - ? WHERE id = ?", amount, from); err != nil {
        return err
    }
    if _, err = tx.ExecContext(ctx,
        "UPDATE accounts SET balance = balance + ? WHERE id = ?", amount, to); err != nil {
        return err
    }

    return tx.Commit()
}
```

**Edge case:** nested transactions. Go’s `database/sql` does not support true nested transactions; use savepoints manually if your driver supports them.

---

## 6. Context cancellation and timeouts

**Edge case:** queries hang forever or goroutines leak.  
**Fix:** always use `*Context` methods and set deadlines.

```go
ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
defer cancel()

rows, err := db.QueryContext(ctx, "SELECT ...")
if err != nil {
    if errors.Is(err, context.DeadlineExceeded) {
        // handle timeout
    }
    return err
}
defer rows.Close()
```

Also configure the pool:

```go
db.SetMaxOpenConns(25)
db.SetMaxIdleConns(5)
db.SetConnMaxLifetime(5 * time.Minute)
db.SetConnMaxIdleTime(1 * time.Minute)
```

---

## 7. Resource leaks: `Query` vs `Exec`

**Edge case:** using `db.Query` for `INSERT/UPDATE/DELETE` and not closing rows leaks connections.  
**Fix:** use `Exec`/`ExecContext` for statements that don’t return rows.

```go
res, err := db.ExecContext(ctx,
    "UPDATE users SET last_login = ? WHERE id = ?", time.Now(), id)
if err != nil {
    return err
}
n, _ := res.RowsAffected()
if n == 0 {
    return ErrNotFound
}
```

---

## 8. Dynamic `IN` clauses and empty lists

**Edge case:** you cannot write `WHERE id IN (?)` with a slice directly; also an empty `IN ()` is invalid SQL.  
**Fix:** generate placeholders safely and handle empty input.

```go
func getUsersByIDs(ctx context.Context, db *sql.DB, ids []int) ([]User, error) {
    if len(ids) == 0 {
        return nil, nil // avoid "IN ()"
    }

    placeholders := make([]string, len(ids))
    args := make([]interface{}, len(ids))
    for i, id := range ids {
        placeholders[i] = "?"
        args[i] = id
    }

    q := "SELECT id, name FROM users WHERE id IN (" +
        strings.Join(placeholders, ",") + ")"

    rows, err := db.QueryContext(ctx, q, args...)
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var users []User
    for rows.Next() {
        var u User
        if err := rows.Scan(&u.ID, &u.Name); err != nil {
            return nil, err
        }
        users = append(users, u)
    }
    return users, rows.Err()
}
```

**PostgreSQL alternative:** use `WHERE id = ANY($1)` with a driver that supports arrays, avoiding placeholder explosion.

**Edge case:** too many parameters. SQLite limits bound parameters (often 999). Chunk large batches:

```go
const chunkSize = 500
for start := 0; start < len(ids); start += chunkSize {
    end := start + chunkSize
    if end > len(ids) { end = len(ids) }
    chunk := ids[start:end]
    // query chunk...
}
```

---

## 9. Batch inserts and placeholder limits

**Edge case:** building one giant `INSERT ... VALUES (...), (...)` can exceed parameter limits or memory.  
**Fix:** chunk inserts or use driver-specific bulk APIs (`COPY` in Postgres).

```go
func bulkInsert(ctx context.Context, db *sql.DB, users []User) error {
    const batchSize = 250
    for i := 0; i < len(users); i += batchSize {
        end := i + batchSize
        if end > len(users) { end = len(users) }

        var b strings.Builder
        b.WriteString("INSERT INTO users(name, email) VALUES ")
        args := make([]interface{}, 0, (end-i)*2)
        for j := i; j < end; j++ {
            if j > i { b.WriteString(",") }
            b.WriteString("(?,?)")
            args = append(args, users[j].Name, users[j].Email)
        }
        if _, err := db.ExecContext(ctx, b.String(), args...); err != nil {
            return err
        }
    }
    return nil
}
```

---

## 10. `LIKE` wildcard injection

**Edge case:** user input containing `%` or `_` changes query semantics.  
**Fix:** escape wildcards and declare `ESCAPE`.

```go
func searchUsers(ctx context.Context, db *sql.DB, term string) ([]User, error) {
    // Escape special characters
    term = strings.ReplaceAll(term, `\`, `\\`)
    term = strings.ReplaceAll(term, `%`, `\%`)
    term = strings.ReplaceAll(term, `_`, `\_`)
    term = "%" + term + "%"

    rows, err := db.QueryContext(ctx,
        "SELECT id, name FROM users WHERE name LIKE ? ESCAPE '\\'", term)
    // ...
}
```

---

## 11. `LastInsertId` and `RowsAffected`

**Edge case:** `LastInsertId` is not supported by all drivers (e.g., PostgreSQL). `RowsAffected` may be 0 even on success.  
**Fix:** use `RETURNING` in PostgreSQL; check `RowsAffected` explicitly.

```go
// MySQL/SQLite style
res, err := db.ExecContext(ctx,
    "INSERT INTO users(name) VALUES (?)", "alice")
id, _ := res.LastInsertId()

// PostgreSQL style
var id int
err := db.QueryRowContext(ctx,
    "INSERT INTO users(name) VALUES ($1) RETURNING id", "alice").Scan(&id)
```

```go
res, err := db.ExecContext(ctx,
    "UPDATE users SET active = false WHERE last_login < ?", cutoff)
if err != nil { return err }
n, err := res.RowsAffected()
if err != nil { return err }
if n == 0 {
    // nothing updated; maybe not an error, but often worth knowing
}
```

---

## 12. Type scanning mismatches and custom types

**Edge case:** driver returns `[]byte` for strings, or unsupported types.  
**Fix:** scan into `[]byte`/`interface{}` first, or implement `sql.Scanner`.

```go
type Status string

func (s *Status) Scan(value interface{}) error {
    switch v := value.(type) {
    case string:
        *s = Status(v)
    case []byte:
        *s = Status(v)
    case nil:
        *s = ""
    default:
        return fmt.Errorf("cannot scan %T into Status", value)
    }
    return nil
}

// Usage
var st Status
err := db.QueryRowContext(ctx,
    "SELECT status FROM jobs WHERE id = ?", id).Scan(&st)
```

---

## 13. JSON and binary columns

**Edge case:** scanning JSON directly into a struct often fails.  
**Fix:** scan into `[]byte`/`json.RawMessage`, then unmarshal; handle NULL.

```go
type Event struct {
    ID   int
    Meta map[string]any
}

func getEvent(ctx context.Context, db *sql.DB, id int) (Event, error) {
    var e Event
    var raw sql.NullString // or []byte with null handling
    err := db.QueryRowContext(ctx,
        "SELECT id, meta FROM events WHERE id = ?", id).
        Scan(&e.ID, &raw)
    if err != nil { return e, err }
    if raw.Valid && raw.String != "" {
        if err := json.Unmarshal([]byte(raw.String), &e.Meta); err != nil {
            return e, err
        }
    }
    return e, nil
}
```

For binary data, scan into `[]byte`:

```go
var data []byte
err := db.QueryRowContext(ctx, "SELECT payload FROM blobs WHERE id = ?", id).Scan(&data)
```

---

## 14. Time zones and `time.Time`

**Edge case:** scanned times may be in local time or UTC depending on driver DSN.  
**Fix:** store and query in UTC; normalize after scan.

```go
// DSN example (MySQL): parseTime=true&loc=UTC
// PostgreSQL: prefer timestamptz and UTC session.

var t time.Time
err := db.QueryRowContext(ctx,
    "SELECT created_at FROM events WHERE id = ?", id).Scan(&t)
if err != nil { return err }
t = t.UTC()
```

When inserting, pass `time.Now().UTC()`.

---

## 15. Prepared statements lifecycle

**Edge case:** prepared statements hold server-side resources; not closing them leaks. Transaction-bound statements are tied to the transaction.  
**Fix:** prepare once, reuse, close on shutdown; in transactions use `tx.Prepare`.

```go
stmt, err := db.PrepareContext(ctx, "SELECT name FROM users WHERE id = ?")
if err != nil { return err }
defer stmt.Close()

// reuse
var name string
_ = stmt.QueryRowContext(ctx, 1).Scan(&name)
```

**Edge case:** schema changes invalidate prepared statements. Some drivers auto-reprepare; others error. Handle by recreating on failure or avoid long-lived prepares in volatile schemas.

---

## 16. Concurrency and isolation

**Edge case:** lost updates, phantom reads, or deadlocks under concurrent transactions.  
**Fix:** choose proper isolation level and use `FOR UPDATE`; retry on deadlock.

```go
tx, err := db.BeginTx(ctx, &sql.TxOptions{
    Isolation: sql.LevelRepeatableRead,
})
```

For high-contention counters, prefer atomic SQL:

```go
_, err := db.ExecContext(ctx,
    "UPDATE counters SET value = value + 1 WHERE id = ?", id)
```

Deadlock retry (simplified):

```go
for attempt := 0; attempt < 3; attempt++ {
    err := doTransaction(ctx, db)
    if err == nil { break }
    if isDeadlock(err) {
        time.Sleep(time.Duration(attempt+1) * 10 * time.Millisecond)
        continue
    }
    return err
}
```

---

## 17. Scanning into structs and column order

**Edge case:** `Scan` is positional; column order in SQL must match struct field order. Adding columns breaks code.  
**Fix:** always list columns explicitly; never use `SELECT *` in production queries.

```go
// BAD: SELECT * FROM users
// GOOD:
rows, err := db.QueryContext(ctx,
    "SELECT id, name, email, created_at FROM users")
```

If you need flexible mapping, use a library like `sqlx` or scan manually with a map.

---

## 18. Large result sets and memory

**Edge case:** loading millions of rows into a slice causes OOM.  
**Fix:** stream rows and process incrementally; set fetch size if driver supports it.

```go
rows, err := db.QueryContext(ctx, "SELECT id, payload FROM big_table")
if err != nil { return err }
defer rows.Close()

for rows.Next() {
    var id int
    var payload []byte
    if err := rows.Scan(&id, &payload); err != nil {
        return err
    }
    process(id, payload) // stream; don't accumulate
}
return rows.Err()
```

---

## 19. Connection ping and startup validation

**Edge case:** `sql.Open` does not connect; failures appear later.  
**Fix:** ping on startup and on health checks.

```go
db, err := sql.Open("postgres", dsn)
if err != nil { return err }
ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
defer cancel()
if err := db.PingContext(ctx); err != nil {
    return fmt.Errorf("db ping: %w", err)
}
```

---

## 20. Error wrapping and driver-specific errors

**Edge case:** losing root cause or mishandling driver-specific error codes.  
**Fix:** wrap errors with `%w`; inspect driver error types when needed.

```go
if err != nil {
    return fmt.Errorf("query user %d: %w", id, err)
}

// PostgreSQL example using pgconn
var pgErr *pgconn.PgError
if errors.As(err, &pgErr) && pgErr.Code == "23505" {
    return ErrDuplicate
}
```

---

## 21. NULL in aggregates and `COALESCE`

**Edge case:** `SUM`, `AVG` over no rows returns NULL, scanning into non-nullable int/float errors.  
**Fix:** use `COALESCE`.

```go
var total float64
err := db.QueryRowContext(ctx,
    "SELECT COALESCE(SUM(amount), 0) FROM orders WHERE user_id = ?", id).
    Scan(&total)
```

---

## 22. Closing `*sql.DB` on shutdown

**Edge case:** leaking connections on process exit.  
**Fix:** call `db.Close()` in a graceful shutdown path.

```go
defer func() {
    if err := db.Close(); err != nil {
        log.Printf("db close: %v", err)
    }
}()
```

---

### Practical checklist

- Use `*Context` methods everywhere.
- Always `defer rows.Close()` and check `rows.Err()`.
- Use placeholders; never interpolate values.
- Handle `sql.ErrNoRows` explicitly.
- Use `sql.Null*` or pointers for nullable columns.
- Wrap transactions with deferred rollback.
- List columns explicitly; avoid `SELECT *`.
- Chunk large `IN` lists and batch inserts.
- Escape `LIKE` wildcards.
- Store/normalize times in UTC.
- Ping on startup; tune pool limits.
- Prefer `Exec` for non-row statements.

If you want, I can tailor these examples to a specific driver (PostgreSQL with `pgx`, MySQL, or SQLite) and show a small repository-style wrapper.

# Arrays vs Linked Lists in Go

Below is a single, runnable `main.go` that implements **both** a dynamic array (slice-backed) and a singly linked list, exposes the same API, benchmarks common operations, and prints a comparison. Run it with `go run main.go`.

```go
// main.go
package main

import (
	"fmt"
	"math/rand"
	"time"
)

// ============================================================
// 1) DYNAMIC ARRAY  (Go slice under the hood)
// ============================================================
type ArrayList struct {
	data []int
}

func NewArrayList(cap int) *ArrayList {
	if cap < 0 {
		cap = 0
	}
	return &ArrayList{data: make([]int, 0, cap)}
}

func (a *ArrayList) Len() int { return len(a.data) }

func (a *ArrayList) Get(i int) (int, error) {
	if i < 0 || i >= len(a.data) {
		return 0, fmt.Errorf("index %d out of range [0,%d)", i, len(a.data))
	}
	return a.data[i], nil
}

// Append is amortized O(1).
func (a *ArrayList) Append(v int) {
	a.data = append(a.data, v)
}

// Insert at index i: O(n) because elements must shift.
func (a *ArrayList) Insert(i, v int) error {
	if i < 0 || i > len(a.data) {
		return fmt.Errorf("index %d out of range [0,%d]", i, len(a.data))
	}
	a.data = append(a.data, 0)   // grow by one
	copy(a.data[i+1:], a.data[i:])
	a.data[i] = v
	return nil
}

// Delete at index i: O(n).
func (a *ArrayList) Delete(i int) error {
	if i < 0 || i >= len(a.data) {
		return fmt.Errorf("index %d out of range", i)
	}
	copy(a.data[i:], a.data[i+1:])
	a.data = a.data[:len(a.data)-1]
	return nil
}

// Search is O(n).
func (a *ArrayList) Search(v int) int {
	for i, x := range a.data {
		if x == v {
			return i
		}
	}
	return -1
}

func (a *ArrayList) ToSlice() []int { return append([]int(nil), a.data...) }

// ============================================================
// 2) SINGLY LINKED LIST
// ============================================================
type Node struct {
	value int
	next  *Node
}

type LinkedList struct {
	head *Node
	size int
}

func NewLinkedList() *LinkedList { return &LinkedList{} }

func (l *LinkedList) Len() int { return l.size }

// Prepend is O(1).
func (l *LinkedList) Prepend(v int) {
	l.head = &Node{value: v, next: l.head}
	l.size++
}

// Append is O(n) (no tail pointer kept here; see note below).
func (l *LinkedList) Append(v int) {
	n := &Node{value: v}
	if l.head == nil {
		l.head = n
	} else {
		cur := l.head
		for cur.next != nil {
			cur = cur.next
		}
		cur.next = n
	}
	l.size++
}

// Insert at index i: O(n) to walk + O(1) splice.
func (l *LinkedList) Insert(i, v int) error {
	if i < 0 || i > l.size {
		return fmt.Errorf("index %d out of range [0,%d]", i, l.size)
	}
	if i == 0 {
		l.Prepend(v)
		return nil
	}
	cur := l.head
	for k := 0; k < i-1; k++ {
		cur = cur.next
	}
	cur.next = &Node{value: v, next: cur.next}
	l.size++
	return nil
}

// Delete at index i: O(n).
func (l *LinkedList) Delete(i int) error {
	if i < 0 || i >= l.size {
		return fmt.Errorf("index %d out of range", i)
	}
	if i == 0 {
		l.head = l.head.next
		l.size--
		return nil
	}
	cur := l.head
	for k := 0; k < i-1; k++ {
		cur = cur.next
	}
	cur.next = cur.next.next
	l.size--
	return nil
}

// Get is O(n) — the big weakness vs arrays.
func (l *LinkedList) Get(i int) (int, error) {
	if i < 0 || i >= l.size {
		return 0, fmt.Errorf("index %d out of range", i)
	}
	cur := l.head
	for k := 0; k < i; k++ {
		cur = cur.next
	}
	return cur.value, nil
}

// Search is O(n).
func (l *LinkedList) Search(v int) int {
	i := 0
	for cur := l.head; cur != nil; cur = cur.next {
		if cur.value == v {
			return i
		}
		i++
	}
	return -1
}

func (l *LinkedList) ToSlice() []int {
	out := make([]int, 0, l.size)
	for cur := l.head; cur != nil; cur = cur.next {
		out = append(out, cur.value)
	}
	return out
}

// ============================================================
// 3) DEMO + MICRO-BENCHMARKS
// ============================================================
func timeIt(name string, fn func()) time.Duration {
	start := time.Now()
	fn()
	d := time.Since(start)
	fmt.Printf("  %-38s %v\n", name, d)
	return d
}

func main() {
	rand.Seed(time.Now().UnixNano())
	const N = 200_000

	fmt.Println("=== Correctness check ===")
	a := NewArrayList(0)
	ll := NewLinkedList()
	for i := 0; i < 5; i++ {
		a.Append(i * 10)
		ll.Append(i * 10)
	}
	a.Insert(2, 99)
	ll.Insert(2, 99)
	fmt.Println("array :", a.ToSlice())
	fmt.Println("list  :", ll.ToSlice())
	a.Delete(1)
	ll.Delete(1)
	fmt.Println("array :", a.ToSlice())
	fmt.Println("list  :", ll.ToSlice())
	fmt.Println("get[2] array:", must(a.Get(2)), " list:", must(ll.Get(2)))
	fmt.Println("search 99 -> array:", a.Search(99), " list:", ll.Search(99))
	fmt.Println()

	fmt.Println("=== Benchmarks (N =", N, ") ===")

	// Build
	fmt.Println("Build by appending N elements:")
	timeIt("ArrayList.Append", func() {
		x := NewArrayList(N)
		for i := 0; i < N; i++ {
			x.Append(i)
		}
	})
	timeIt("LinkedList.Append (O(n) each)", func() {
		x := NewLinkedList()
		for i := 0; i < N; i++ {
			x.Append(i)
		}
	})
	timeIt("LinkedList.Prepend (O(1) each)", func() {
		x := NewLinkedList()
		for i := 0; i < N; i++ {
			x.Prepend(i)
		}
	})

	// Random access
	fmt.Println("Random access N times:")
	idx := make([]int, N)
	for i := range idx {
		idx[i] = rand.Intn(N)
	}
	arr := NewArrayList(N)
	ll2 := NewLinkedList()
	for i := 0; i < N; i++ {
		arr.Append(i)
		ll2.Append(i)
	}
	timeIt("ArrayList.Get (O(1))", func() {
		s := 0
		for _, i := range idx {
			v, _ := arr.Get(i)
			s += v
		}
		_ = s
	})
	timeIt("LinkedList.Get (O(n))", func() {
		s := 0
		for _, i := range idx {
			v, _ := ll2.Get(i)
			s += v
		}
		_ = s
	})

	// Insert at front
	fmt.Println("Insert N elements at index 0:")
	timeIt("ArrayList.Insert(0,..) O(n) each", func() {
		x := NewArrayList(0)
		for i := 0; i < N; i++ {
			x.Insert(0, i)
		}
	})
	timeIt("LinkedList.Insert(0,..) O(1) each", func() {
		x := NewLinkedList()
		for i := 0; i < N; i++ {
			x.Insert(0, i)
		}
	})

	// Search
	fmt.Println("Search for a missing value:")
	timeIt("ArrayList.Search", func() {
		arr.Search(-1)
	})
	timeIt("LinkedList.Search", func() {
		ll2.Search(-1)
	})

	fmt.Println()
	fmt.Println("=== Summary ===")
	fmt.Println(`Dynamic array (slice): O(1) random access, amortized O(1) append,
  O(n) insert/delete in middle, cache-friendly, low overhead.`)
	fmt.Println(`Linked list: O(1) prepend/insert given a node pointer, O(n) access,
  O(n) append (without tail), pointer-chasing = cache-unfriendly,
  higher per-element memory overhead.`)
}

func must(v int, err error) int {
	if err != nil {
		panic(err)
	}
	return v
}
```

