	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	urls := []string{
		"https://example.com",
		"https://golang.org",
		"https://pkg.go.dev",
	}

	bodies, err := FetchAll(ctx, urls)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	for i, b := range bodies {
