### Step 4 — “Await one” / race pattern

If you want Promise.race-style behavior, use `select`:

```go
func FetchFirst(ctx context.Context, urls []string) (string, error) {
	type result struct {
		body string
		err  error
	}

	ch := make(chan result, len(urls))
	for _, u := range urls {
		u := u
		go func() {
			req, _ := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				ch <- result{"", err}
				return
			}
			defer resp.Body.Close()
			b, err := io.ReadAll(resp.Body)
			ch <- result{string(b), err}
		}()
	}

	// Await the first completion.
	select {
	case r := <-ch:
		if r.err != nil {
			return "", r.err
		}
		return r.body, nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}
```

Note: this does not cancel the losers automatically unless `ctx` is cancelled by the caller. For production, combine with `errgroup`/context cancellation or use a cancel function.

