### Key takeaways

- Go uses **goroutines + channels**, not `async/await`.
- **`errgroup`** is the closest to `Promise.all` with error propagation and cancellation.
- **`context.Context`** is the standard cancellation/timeout mechanism.
- Always handle **loop variable capture** (`i, u := i, u`) in older Go versions; in Go 1.22+ loop vars are per-iteration, but the explicit capture remains harmless and clear.
- Buffered result channels or `errgroup` prevent goroutine leaks and blocking sends.

In Go there are no `async`/`await` keywords. Go’s concurrency model is built on **goroutines** and **channels**: you launch work with `go`, and synchronize results through channels or other primitives. So “async/await” in Go is usually expressed as: start a goroutine that computes a value, return a handle (`Future`/`Task`), and let callers block on `Await()` until the result is ready.

Below is a small, idiomatic core implementation using generics. It supports:
- launching async work
- awaiting its result
- safe repeated `Await()` calls
- propagation of errors

```go
package async

import "sync"

// Result holds either a value or an error.
type Result[T any] struct {
    Value T
    Err   error
}

// Future represents an asynchronous computation.
type Future[T any] struct {
    fn func() (T, error)

    // once guarantees the goroutine is started exactly once.
    once sync.Once

    // mu protects value/err after completion.
    mu    sync.Mutex
    value T
    err   error

    // done is closed when the computation finishes.
    done chan struct{}
}

// start launches the background goroutine exactly once.
func (f *Future[T]) start() {
    f.once.Do(func() {
        f.done = make(chan struct{})

        go func() {
            v, err := f.fn()

            f.mu.Lock()
            f.value = v
            f.err = err
            f.mu.Unlock()

            // Closing signals all waiters that the result is available.
            close(f.done)
        }()
    })
}

// Async starts fn in a goroutine and returns a Future.
func Async[T any](fn func() (T, error)) *Future[T] {
    f := &Future[T]{fn: fn}
    f.start()
    return f
}

// Await blocks until the future completes and returns its result.
// It is safe to call multiple times.
func (f *Future[T]) Await() (T, error) {
    f.start() // idempotent
    <-f.done

    f.mu.Lock()
    defer f.mu.Unlock()
    return f.value, f.err
}
```

### Usage example

```go
package main

import (
    "fmt"
    "time"

    "example.com/async"
)

func fetchUser(id int) (string, error) {
    time.Sleep(100 * time.Millisecond)
    return fmt.Sprintf("user-%d", id), nil
}

func main() {
    // Launch two independent async operations.
    f1 := async.Async(func() (string, error) {
        return fetchUser(1)
    })
    f2 := async.Async(func() (string, error) {
        return fetchUser(2)
    })

    // Await results; goroutines run concurrently.
    r1, err1 := f1.Await()
    r2, err2 := f2.Await()

    fmt.Println(r1, err1)
    fmt.Println(r2, err2)

    // Re-awaiting is safe and returns the cached result.
    again, _ := f1.Await()
    fmt.Println("again:", again)
}
```

### Interview notes / trade-offs

- **No colored functions**: In Go, any function can call `Await()` because goroutines are cheap and blocking a goroutine does not block an OS thread in the same way user-level async does in some runtimes.
- **Repeated awaits**: The implementation caches the result and closes `done`, so multiple callers can await safely.
- **Cancellation**: This core version does not support cancellation. In production Go code, you would usually pass a `context.Context` into the async function and check `ctx.Done()`.
- **Composition**: Real-world code often uses `errgroup.Group` or channels for “await all / await any” semantics instead of building a full future framework.
- **Error handling**: Errors are returned explicitly, following Go’s usual `(value, error)` convention.

```go
// bigO.go
// A small, self-contained library for describing, measuring, and estimating
// Big-O complexity classes in Go.
//
// Run with:  go run bigO.go
package main

import (
	"fmt"
	"math"
	"sort"
	"time"
)

// ---------- Complexity classes ----------

// Complexity describes a Big-O growth class.
type Complexity struct {
	Name string
	// F maps an input size n to its theoretical growth value.
	F func(n int) float64
}

func (c Complexity) String() string { return c.Name }

// Predefined complexity classes. Each F is the (unnormalised) growth function.
var (
	O1       = Complexity{"O(1)", func(n int) float64 { return 1 }}
	OLogN    = Complexity{"O(log n)", func(n int) float64 {
		if n < 2 {
			return 1
		}
		return math.Log2(float64(n))
	}}
	ON       = Complexity{"O(n)", func(n int) float64 { return float64(n) }}
	ONLogN   = Complexity{"O(n log n)", func(n int) float64 {
		if n < 2 {
			return float64(n)
		}
		return float64(n) * math.Log2(float64(n))
	}}
	ON2      = Complexity{"O(n^2)", func(n int) float64 { return float64(n) * float64(n) }}
	ON3      = Complexity{"O(n^3)", func(n int) float64 {
		return float64(n) * float64(n) * float64(n)
	}}
	O2N      = Complexity{"O(2^n)", func(n int) float64 { return math.Pow(2, float64(n)) }}
	OFactorial = Complexity{"O(n!)", func(n int) float64 {
		r := 1.0
		for i := 2; i <= n; i++ {
			r *= float64(i)
		}
		return r
	}}
)

// DefaultClasses is the set used when estimating an unknown function.
// (Exponential/factorial are excluded by default because they are only
// meaningful for tiny n and would otherwise dominate the fit.)
var DefaultClasses = []Complexity{O1, OLogN, ON, ONLogN, ON2, ON3}

// ---------- Measurement ----------

// Measurement records the best (minimum) execution time observed for size n.
type Measurement struct {
	N     int
	Nanos int64
}

func (m Measurement) Seconds() float64 { return float64(m.Nanos) / 1e9 }

// Measure times fn at each size in sizes. For every size the function is run
// reps times and the minimum time is kept (reduces noise from GC/scheduling).
// sizes are sorted ascending. A single warm-up call is made first.
func Measure(fn func(n int), sizes []int, reps int) []Measurement {
	if reps < 1 {
		reps = 1
	}
	sorted := append([]int(nil), sizes...)
	sort.Ints(sorted)

	out := make([]Measurement, 0, len(sorted))
	for _, n := range sorted {
		fn(n) // warm-up
		var best int64 = math.MaxInt64
		for r := 0; r < reps; r++ {
			start := time.Now()
			fn(n)
			d := time.Since(start).Nanoseconds()
			if d < best {
				best = d
			}
		}
		out = append(out, Measurement{N: n, Nanos: best})
	}
	return out
}

// ---------- Estimation ----------

// estimateResult holds the fitted coefficient of variation for a class.
type estimateResult struct {
	Class Complexity
	CV    float64
	Mean  float64 // mean of T(n)/F(n), i.e. the estimated constant factor
}

// Estimate picks the complexity class (from classes, or DefaultClasses) that
// best fits the measurements. Fit quality is the coefficient of variation of
// the ratios T(n)/F(n): a perfect fit has CV == 0 (constant factor).
func Estimate(ms []Measurement, classes ...Complexity) estimateResult {
	if len(classes) == 0 {
		classes = DefaultClasses
	}
	best := estimateResult{CV: math.Inf(1)}
	for _, c := range classes {
		ratios := make([]float64, 0, len(ms))
		for _, m := range ms {
			f := c.F(m.N)
			if f <= 0 {
				continue
			}
			ratios = append(ratios, float64(m.Nanos)/f)
		}
		if len(ratios) < 2 {
			continue
		}
		mean := 0.0
		for _, r := range ratios {
			mean += r
		}
		mean /= float64(len(ratios))

		variance := 0.0
		for _, r := range ratios {
			d := r - mean
			variance += d * d
		}
		variance /= float64(len(ratios))
		std := math.Sqrt(variance)

		cv := math.Inf(1)
		if mean != 0 {
			cv = std / mean
		}
		if cv < best.CV {
			best = estimateResult{Class: c, CV: cv, Mean: mean}
		}
	}
	return best
}

// ---------- Reporting ----------

// Report prints a measurement table and the estimated class.
func Report(name string, ms []Measurement) {
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("%8s  %12s  %12s\n", "n", "time(ns)", "time(s)")
	for _, m := range ms {
		fmt.Printf("%8d  %12d  %12.6f\n", m.N, m.Nanos, m.Seconds())
	}
	est := Estimate(ms)
	fmt.Printf("estimated: %s  (CV=%.4f, constant factor ~%.3g ns)\n\n",
		est.Class, est.CV, est.Mean)
}

// ---------- Demo ----------

func main() {
	sizes := []int{256, 512, 1024, 2048, 4096}

	// O(1)
	Report("O(1) constant", Measure(func(n int) {
		_ = n * n // a fixed amount of work independent of n... well, one op
	}, sizes, 20))

	// O(log n)
	Report("O(log n)", Measure(func(n int) {
		for i := 1; i < n; i *= 2 {
			_ = i
		}
	}, sizes, 20))

	// O(n)
	Report("O(n) linear", Measure(func(n int) {
		s := 0
		for i := 0; i < n; i++ {
			s += i
		}
		_ = s
	}, sizes, 10))

	// O(n log n)
	Report("O(n log n)", Measure(func(n int) {
		// n passes, each doing log n work
		for i := 0; i < n; i++ {
			for j := 1; j < n; j *= 2 {
				_ = i + j
			}
		}
	}, sizes, 5))

	// O(n^2)
	Report("O(n^2) quadratic", Measure(func(n int) {
		s := 0
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				s += i * j
			}
		}
		_ = s
	}, []int{64, 128, 256, 512, 1024}, 5))

	// O(n^3)
	Report("O(n^3) cubic", Measure(func(n int) {
		s := 0
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				for k := 0; k < n; k++ {
					s += i + j + k
				}
			}
		}
		_ = s
	}, []int{16, 32, 64, 128}, 3))

	// Exponential / factorial need tiny n.
	small := []int{1, 2, 4, 8, 12, 16}
	Report("O(2^n) exponential", Measure(func(n int) {
		// 2^n recursive calls (capped implicitly by n)
		var rec func(int) int
		rec = func(x int) int {
			if x <= 1 {
				return 1
			}
			return rec(x-1) + rec(x-2)
		}
		_ = rec(n)
	}, small, 3))

	Report("O(n!) factorial", Measure(func(n int) {
		var perm func([]int, int)
		perm = func(a []int, k int) {
			if k == len(a) {
				return
			}
			for i := k; i < len(a); i++ {
				a[k], a[i] = a[i], a[k]
				perm(a, k+1)
				a[k], a[i] = a[i], a[k]
			}
		}
		a := make([]int, n)
		for i := range a {
			a[i] = i
		}
		perm(a, 0)
	}, []int{1, 2, 3, 4, 5, 6, 7, 8}, 2))

	// Demonstrate comparing two classes directly.
	fmt.Println("Direct class comparison:")
	fmt.Printf("  ON2.F(1000) = %.0f\n", ON2.F(1000))
