## Final solution

```go
package main

import "fmt"

// HasDuplicate reports whether nums contains any duplicate value.
// Time: O(n), Space: O(n).
func HasDuplicate(nums []int) bool {
    seen := make(map[int]struct{}, len(nums))
    for _, v := range nums {
        if _, ok := seen[v]; ok {
            return true
        }
        seen[v] = struct{}{}
    }
    return false
}

func main() {
    fmt.Println(HasDuplicate([]int{1, 2, 3}))      // false
    fmt.Println(HasDuplicate([]int{1, 2, 1}))      // true
    fmt.Println(HasDuplicate(nil))                 // false
}
```

## Big O in one paragraph

**Big O notation** describes how an algorithm’s **time or space cost grows** as the input size `n` grows, ignoring constant factors and lower-order terms. It’s an *upper bound* on growth rate, so `O(n²)` means “cost grows no faster than quadratically.” In Go we care about it because `n` can be millions of rows, requests, or bytes, and a bad complexity class dominates hardware speed.

Common classes:

| Class | Name | Typical cause |
|-------|------|---------------|
| O(1) | Constant | Array index, hash map lookup |
| O(log n) | Logarithmic | Binary search, balanced BST |
| O(n) | Linear | Single scan |
| O(n log n) | Linearithmic | Merge/heap sort, divide-and-conquer |
| O(n²) | Quadratic | Nested loops over same data |
| O(2ⁿ) | Exponential | Naïve recursion over subsets |
| O(n!) | Factorial | Permutations |

**Rules of thumb in Go:** drop constants (`2n → O(n)`), drop lower terms (`n² + n → O(n²)`), multiplication for nested loops, addition for sequential steps.

---

## Idiomatic Go implementation

```go
// Package bigo demonstrates the core complexity classes with
// minimal, allocation-conscious implementations.
package bigo

import "sort"

// ---------- O(1): constant time ----------
// Lookup does not depend on len(data).
func Lookup(data []int, idx int) int {
	if idx < 0 || idx >= len(data) {
		return 0
	}
	return data[idx] // one array access
}

// ---------- O(log n): logarithmic ----------
// BinarySearch halves the search space each step.
func BinarySearch(sorted []int, target int) int {
	lo, hi := 0, len(sorted)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2 // avoids overflow
		switch {
		case sorted[mid] == target:
			return mid
		case sorted[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

// ---------- O(n): linear ----------
// Sum scans once.
func Sum(data []int) int {
	total := 0
	for _, v := range data {
		total += v
	}
	return total
}

// ---------- O(n log n): linearithmic ----------
// MergeSort is the canonical example.
func MergeSort(data []int) []int {
	if len(data) <= 1 {
		return append([]int(nil), data...) // defensive copy
	}
	mid := len(data) / 2
	left := MergeSort(data[:mid])
	right := MergeSort(data[mid:])
	return merge(left, right)
}

func merge(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	out = append(out, b[j:]...)
	return out
}

// ---------- O(n²): quadratic ----------
// HasPairSumNaive checks all pairs (nested loops).
func HasPairSumNaive(data []int, target int) bool {
	n := len(data)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if data[i]+data[j] == target {
				return true
			}
		}
	}
	return false
}

// O(n) improvement using a hash set — shows how complexity class changes.
func HasPairSumFast(data []int, target int) bool {
	seen := make(map[int]struct{}, len(data))
	for _, v := range data {
		if _, ok := seen[target-v]; ok {
			return true
		}
		seen[v] = struct{}{}
	}
	return false
}

// ---------- O(2ⁿ): exponential ----------
// FibNaive branches twice per call.
func FibNaive(n int) int {
	if n < 2 {
		return n
	}
	return FibNaive(n-1) + FibNaive(n-2)
}

// O(n) version via memoization — same result, better class.
func FibLinear(n int) int {
	if n < 2 {
		return n
	}
	a, b := 0, 1
	for i := 2; i <= n; i++ {
		a, b = b, a+b
	}
	return b
}

// ---------- O(n!): factorial ----------
// Permutations generates all orderings; count grows factorially.
func PermutationsCount(n int) int {
	if n <= 1 {
		return 1
	}
	return n * PermutationsCount(n-1)
}

// ---------- Space complexity examples ----------

// InPlaceReverse is O(1) extra space.
func InPlaceReverse(s []byte) {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
}

// ReversedCopy is O(n) extra space.
func ReversedCopy(s []byte) []byte {
	out := make([]byte, len(s))
	for i := range s {
		out[len(s)-1-i] = s[i]
	}
	return out
}

// ---------- Sorting helper (stdlib) ----------
// SortInts wraps sort.Ints; stdlib uses pdqsort (O(n log n) avg/worst-ish).
func SortInts(data []int) {
	sort.Ints(data)
}
```

