# Binary Data and Bytes in Go

Go models raw binary data as **`[]byte`** (a slice of bytes). The standard library gives you two main tools:

- **`bytes`** — in-memory buffers, readers/writers, searching/splitting helpers.
- **`encoding/binary`** — converting between Go values and their binary representation with a chosen byte order.

Below is a single, runnable program that implements a small binary record format (fixed fields + a variable-length string), then decodes it back. It also demonstrates `bytes.Buffer`, `bytes.Reader`, endianness, `io.ReadFull`, and varints.

## Complete runnable example

```go
// main.go
package main

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
)

// encodeRecord builds: [id uint32][nameLen uint16][name bytes][score float64]
// using big-endian byte order.
func encodeRecord(id uint32, name string, score float64) ([]byte, error) {
	var buf bytes.Buffer

	if err := binary.Write(&buf, binary.BigEndian, id); err != nil {
		return nil, fmt.Errorf("write id: %w", err)
	}

	nameBytes := []byte(name)
	if len(nameBytes) > 0xFFFF {
		return nil, fmt.Errorf("name too long: %d", len(nameBytes))
	}
	if err := binary.Write(&buf, binary.BigEndian, uint16(len(nameBytes))); err != nil {
		return nil, fmt.Errorf("write nameLen: %w", err)
	}
	if _, err := buf.Write(nameBytes); err != nil {
		return nil, fmt.Errorf("write name: %w", err)
	}
	if err := binary.Write(&buf, binary.BigEndian, score); err != nil {
		return nil, fmt.Errorf("write score: %w", err)
	}

	return buf.Bytes(), nil
}

// decodeRecord is the inverse of encodeRecord.
func decodeRecord(data []byte) (uint32, string, float64, error) {
	r := bytes.NewReader(data)

	var id uint32
	if err := binary.Read(r, binary.BigEndian, &id); err != nil {
		return 0, "", 0, fmt.Errorf("read id: %w", err)
	}

	var nameLen uint16
	if err := binary.Read(r, binary.BigEndian, &nameLen); err != nil {
		return 0, "", 0, fmt.Errorf("read nameLen: %w", err)
	}

	nameBytes := make([]byte, nameLen)
	// ReadFull guarantees we get exactly nameLen bytes or an error.
	if _, err := io.ReadFull(r, nameBytes); err != nil {
		return 0, "", 0, fmt.Errorf("read name: %w", err)
	}

	var score float64
	if err := binary.Read(r, binary.BigEndian, &score); err != nil {
		return 0, "", 0, fmt.Errorf("read score: %w", err)
	}

	return id, string(nameBytes), score, nil
}

func main() {
	// 1) Encode a record to []byte.
	data, err := encodeRecord(42, "Gopher", 98.25)
	if err != nil {
		fmt.Println("encode error:", err)
		return
	}
	fmt.Printf("encoded (%d bytes): % x\n", len(data), data)

	// 2) Decode it back.
	id, name, score, err := decodeRecord(data)
	if err != nil {
		fmt.Println("decode error:", err)
		return
	}
	fmt.Printf("decoded: id=%d name=%q score=%g\n", id, name, score)

	// 3) bytes package helpers.
	b := []byte("Hello, Go world!")
	fmt.Println("contains 'Go':", bytes.Contains(b, []byte("Go")))
	fmt.Println("fields:", bytes.Fields([]byte("a  b\tc")))
	fmt.Println("upper:", string(bytes.ToUpper(b)))

	// 4) Varint encoding (compact integers).
	var varBuf [binary.MaxVarintLen64]byte
	n := binary.PutUvarint(varBuf[:], 300)
	fmt.Printf("uvarint bytes: % x (len=%d)\n", varBuf[:n], n)

	val, consumed := binary.Uvarint(varBuf[:n])
	fmt.Printf("uvarint decoded: value=%d consumed=%d\n", val, consumed)

	// 5) Manual packing with binary.Put* (no reflection, fastest).
	out := make([]byte, 4)
	binary.BigEndian.PutUint32(out, 0xDEADBEEF)
	fmt.Printf("manual uint32: % x -> %d\n", out, binary.BigEndian.Uint32(out))
}
```

