Write a tiny binary format for sensor readings:

- Header: magic bytes `SNAP` (4 bytes), version `uint8` (must be `1`), record count `uint16` (little-endian).
- Body: for each record:
  - `uint32` sensor ID (little-endian)
  - `float64` temperature (little-endian IEEE-754)
  - `int64` Unix timestamp (little-endian)
- No trailing bytes allowed.

Implement:

```go
func Encode(records []Reading) ([]byte, error)
func Decode(data []byte) ([]Reading, error)
```

Then demonstrate a round trip and print the decoded values.

---

## Step-by-step solution

### 1. Define the data model

```go
type Reading struct {
    ID    uint32
    Temp  float64
    Time  int64
}
```

### 2. Use `bytes.Buffer` + `encoding/binary`

`encoding/binary` writes integers and floats in a chosen byte order. We write fields one by one to avoid struct padding surprises.

### 3. Encode

- Write magic.
- Write version.
- Write count as `uint16`.
- Write each field.

### 4. Decode

- Read and validate magic.
- Read and validate version.
- Read count.
- Read exactly `count` records.
- Ensure no trailing bytes (`io.EOF` after last record).

### 5. Add a small demo and test

---

## Final solution

```go
package main

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

const (
	magic   = "SNAP"
	version = 1
)

type Reading struct {
	ID   uint32
	Temp float64
	Time int64
}

var (
	ErrBadMagic      = errors.New("bad magic")
	ErrBadVersion    = errors.New("bad version")
	ErrTrailingBytes = errors.New("trailing bytes")
	ErrShortData     = errors.New("short data")
)

func Encode(records []Reading) ([]byte, error) {
	var buf bytes.Buffer

	// Header
	if _, err := buf.WriteString(magic); err != nil {
		return nil, err
	}
	if err := buf.WriteByte(version); err != nil {
		return nil, err
	}
	if err := binary.Write(&buf, binary.LittleEndian, uint16(len(records))); err != nil {
		return nil, err
	}

	// Body
	for _, r := range records {
		if err := binary.Write(&buf, binary.LittleEndian, r.ID); err != nil {
			return nil, err
		}
		if err := binary.Write(&buf, binary.LittleEndian, r.Temp); err != nil {
			return nil, err
		}
		if err := binary.Write(&buf, binary.LittleEndian, r.Time); err != nil {
			return nil, err
		}
	}

	return buf.Bytes(), nil
}

func Decode(data []byte) ([]Reading, error) {
	r := bytes.NewReader(data)

	// Magic
	magicBuf := make([]byte, 4)
	if _, err := io.ReadFull(r, magicBuf); err != nil {
		return nil, ErrShortData
	}
	if string(magicBuf) != magic {
		return nil, ErrBadMagic
	}

	// Version
	v, err := r.ReadByte()
	if err != nil {
		return nil, ErrShortData
	}
	if v != version {
		return nil, ErrBadVersion
	}

	// Count
	var count uint16
	if err := binary.Read(r, binary.LittleEndian, &count); err != nil {
		return nil, ErrShortData
	}

	// Records
	records := make([]Reading, 0, count)
	for i := 0; i < int(count); i++ {
		var rec Reading
		if err := binary.Read(r, binary.LittleEndian, &rec.ID); err != nil {
			return nil, ErrShortData
		}
		if err := binary.Read(r, binary.LittleEndian, &rec.Temp); err != nil {
			return nil, ErrShortData
		}
		if err := binary.Read(r, binary.LittleEndian, &rec.Time); err != nil {
			return nil, ErrShortData
		}
		records = append(records, rec)
	}

	// No trailing bytes
	if r.Len() != 0 {
		return nil, ErrTrailingBytes
	}

	return records, nil
}

func main() {
	in := []Reading{
		{ID: 1, Temp: 23.5, Time: 1700000000},
		{ID: 2, Temp: -5.25, Time: 1700000060},
	}

	data, err := Encode(in)
	if err != nil {
		panic(err)
	}
	fmt.Printf("encoded %d bytes: % x\n", len(data), data)

	out, err := Decode(data)
	if err != nil {
		panic(err)
	}

	for _, r := range out {
		fmt.Printf("id=%d temp=%.2f time=%d\n", r.ID, r.Temp, r.Time)
	}
}
```

### What this teaches

- `bytes.Buffer` is a convenient in-memory byte sink.
- `encoding/binary` handles endianness explicitly, which is essential for portable binary formats.
- `bytes.NewReader` + `io.ReadFull` makes strict decoding and trailing-byte detection easy.
- Writing fields individually avoids hidden struct padding.

