    height = func(n *TreeNode) int {
        if n == nil {
            return 0
        }
        lh := height(n.Left)
        if lh == -1 {
            return -1
        }
        rh := height(n.Right)
        if rh == -1 {
            return -1
        }
        if lh-rh > 1 || rh-lh > 1 {
            return -1
        }
        if lh > rh {
            return lh + 1
        }
        return rh + 1
    }
    return height(root) != -1
}

func main() {
